_ad_refresh_marketing_spend.src:
declare
  v_acc public.ad_accounts;
  v_rate numeric;
  v_count int := 0;
begin
  select * into v_acc from public.ad_accounts where id = p_account_id;
  v_rate := case when upper(coalesce(v_acc.currency, 'USD')) = upper(public.setting_text('store', array['currency'], 'BDT')) then 1 else v_acc.usd_rate end;
  with agg as (
    select c.id as campaign_uuid, s.date, sum(s.cost) as cost, sum(s.impressions) as impressions, sum(s.clicks) as clicks,
           round(sum(s.conversions))::int as orders, round(sum(s.conversion_value) * v_rate, 2) as revenue
    from public.ad_platform_stats s
    join public.marketing_campaigns c on c.platform = v_acc.platform::public.marketing_platform and c.external_id = s.campaign_id
    where s.account_id = p_account_id and s.date between p_since and p_until
    group by c.id, s.date
  ), up as (
    insert into public.marketing_spend(campaign_id, spend_date, spend, impressions, clicks, orders, revenue, source, external_ref, notes)
    select campaign_uuid, date, cost, least(impressions, 2147483647)::int, least(clicks, 2147483647)::int, greatest(orders, 0), revenue,
           'API', lower(v_acc.platform), 'Synced from ' || initcap(lower(v_acc.platform)) || ' Ads'
    from agg
    on conflict (campaign_id, spend_date) do update set
      spend = excluded.spend, impressions = excluded.impressions, clicks = excluded.clicks,
      orders = excluded.orders, revenue = excluded.revenue, source = 'API', external_ref = excluded.external_ref
    where (marketing_spend.spend, marketing_spend.impressions, marketing_spend.clicks, marketing_spend.orders, marketing_spend.revenue)
      is distinct from (excluded.spend, excluded.impressions, excluded.clicks, excluded.orders, excluded.revenue)
    returning 1
  )
  select count(*) into v_count from up;
  -- Days that no longer have spend on the platform.
  update public.marketing_spend m set spend = 0, impressions = 0, clicks = 0, orders = 0, revenue = 0
  from public.marketing_campaigns c
  where c.id = m.campaign_id and c.ad_account_id = p_account_id and m.source = 'API'
    and m.spend_date between p_since and p_until and m.spend > 0
    and not exists (select 1 from public.ad_platform_stats s where s.account_id = p_account_id and s.campaign_id = c.external_id
                    and s.date = m.spend_date and s.cost > 0);
  return v_count;
end;

_add_order_lines.src:
declare
  v_line jsonb;
  v_item public.order_items;
  v_count int := 0;
begin
  for v_line in select * from jsonb_array_elements(coalesce(p_lines, '[]'::jsonb)) loop
    insert into public.order_items(
      order_id, product_id, variant_id, product_name, variant_title, sku, image_url, unit_price, unit_cost,
      quantity, line_subtotal, discount_amount, line_total, track_inventory, requires_production
    ) values (
      p_order.id, (v_line ->> 'product_id')::uuid, (v_line ->> 'variant_id')::uuid, v_line ->> 'product_name',
      nullif(v_line ->> 'variant_title', 'Default'), v_line ->> 'sku', v_line ->> 'image_url',
      (v_line ->> 'unit_price')::numeric, (v_line ->> 'unit_cost')::numeric, (v_line ->> 'quantity')::int,
      (v_line ->> 'line_subtotal')::numeric, 0, (v_line ->> 'line_subtotal')::numeric,
      coalesce((v_line ->> 'track_inventory')::boolean, true), coalesce((v_line ->> 'requires_production')::boolean, false)
    ) returning * into v_item;
    perform public._reserve_order_item(v_item, p_order.order_number);
    v_count := v_count + v_item.quantity;
  end loop;
  return v_count;
end;

_after_order_created.src:
declare
  v_into uuid;
begin
  begin
    v_into := public._auto_merge_web_order(p_order_id);
  exception when others then
    -- A failed merge never loses the order: it stays as it was, flagged.
    perform public.log_system_event('WARN', 'OTHER', 'auto_merge', format('Auto-merge skipped: %s', sqlerrm),
      jsonb_build_object('order_id', p_order_id));
    v_into := null;
  end;
  if v_into is not null then
    return v_into;
  end if;
  perform public._flag_possible_duplicate(p_order_id);
  return p_order_id;
end;

_allocate_discount.src:
declare
  v_total numeric := 0;
  v_out jsonb := '[]'::jsonb;
  v_line jsonb;
  v_share numeric;
  v_allocated numeric := 0;
  v_idx int := 0;
  v_max_idx int := 0;
  v_max_val numeric := -1;
  v_count int := jsonb_array_length(p_lines);
begin
  select coalesce(sum((l ->> 'line_subtotal')::numeric), 0) into v_total from jsonb_array_elements(p_lines) l;
  for v_line in select * from jsonb_array_elements(p_lines) loop
    v_share := case when v_total > 0 and coalesce(p_discount, 0) > 0
      then round(coalesce(p_discount, 0) * (v_line ->> 'line_subtotal')::numeric / v_total, 2) else 0 end;
    v_allocated := v_allocated + v_share;
    if (v_line ->> 'line_subtotal')::numeric > v_max_val then
      v_max_val := (v_line ->> 'line_subtotal')::numeric;
      v_max_idx := v_idx;
    end if;
    v_out := v_out || jsonb_build_array(v_line || jsonb_build_object('_share', v_share));
    v_idx := v_idx + 1;
  end loop;

  -- Put the rounding remainder on the largest line.
  v_out := (
    select jsonb_agg(
      (l - '_share') || jsonb_build_object(
        'discount_amount', least((l ->> '_share')::numeric
          + case when ord - 1 = v_max_idx then coalesce(p_discount, 0) - v_allocated else 0 end,
          (l ->> 'line_subtotal')::numeric),
        'line_total', (l ->> 'line_subtotal')::numeric - least((l ->> '_share')::numeric
          + case when ord - 1 = v_max_idx then coalesce(p_discount, 0) - v_allocated else 0 end,
          (l ->> 'line_subtotal')::numeric)
      ) order by ord)
    from jsonb_array_elements(v_out) with ordinality as t(l, ord)
  );
  return coalesce(v_out, '[]'::jsonb);
end;

_api_require.src:
begin
  perform public._require_system();
  if not exists (select 1 from public.api_keys where id = p_key and revoked_at is null and (expires_at is null or expires_at > now())) then
    raise exception 'PERMISSION_DENIED: this API key is not valid or has been turned off' using errcode = '42501';
  end if;
  if not exists (select 1 from public.api_keys where id = p_key and p_scope = any(scopes)) then
    raise exception 'PERMISSION_DENIED: this API key does not have the % permission', p_scope using errcode = '42501';
  end if;
  perform public.require_feature('external_api');
end;

_apply_fraud_decision.src:
declare
  v_order public.orders;
  v_check public.fraud_checks;
  v_eval jsonb;
  v_req jsonb;
  v_decision public.fraud_decision := 'ALLOW';
  v_target public.order_status;
  v_fraud_enabled boolean := public.setting_bool('fraud', array['enabled'], true);
begin
  select * into v_order from public.orders where id = p_order_id for update;
  if v_order.status not in ('PENDING', 'FRAUD_CHECK', 'FRAUD_REVIEW', 'CONFIRMATION_REQUIRED', 'ADVANCE_REQUIRED') then
    raise exception 'VALIDATION: fraud decisions cannot be applied to % orders', v_order.status using errcode = '22023';
  end if;

  if v_order.status <> 'FRAUD_CHECK' then
    v_order := public._transition_order(p_order_id, 'FRAUD_CHECK', 'Risk check started');
  end if;

  if p_fraud_check_id is not null and v_fraud_enabled then
    select * into v_check from public.fraud_checks where id = p_fraud_check_id;
    if v_check.order_id is null then
      update public.fraud_checks set order_id = p_order_id, customer_id = coalesce(customer_id, v_order.customer_id)
      where id = p_fraud_check_id;
    end if;
    v_eval := public.evaluate_fraud_rules(v_check.metrics, jsonb_build_object(
      'order_value', v_order.total_amount, 'subtotal', v_order.subtotal,
      'delivery_charge', v_order.delivery_charge, 'return_charge', v_order.return_charge,
      'district', v_order.shipping_district, 'area', v_order.shipping_area,
      'payment_method', v_order.payment_method, 'source', v_order.source,
      'item_count', (select sum(quantity) from public.order_items where order_id = p_order_id)));
    v_decision := (v_eval ->> 'decision')::public.fraud_decision;
  elsif v_fraud_enabled then
    -- Checks are on but none could be recorded (provider or service outage):
    -- never fail open. Follow the store's provider-error policy.
    v_decision := case when public.setting_text('fraud', array['on_provider_error'], 'REVIEW') = 'ALLOW'
                       then 'ALLOW' else 'REVIEW' end;
    v_eval := jsonb_build_object('decision', v_decision, 'advance_amount', 0, 'advance_type', 'NONE', 'matched_rules', '[]'::jsonb);
  else
    v_eval := jsonb_build_object('decision', 'ALLOW', 'advance_amount', 0, 'advance_type', 'NONE', 'matched_rules', '[]'::jsonb);
  end if;

  v_req := public.payment_requirement_for(v_decision, (v_eval ->> 'advance_amount')::numeric,
    v_order.total_amount, v_order.payment_method, v_eval ->> 'customer_message');

  update public.orders set
    fraud_check_id = coalesce(p_fraud_check_id, fraud_check_id),
    risk_level = coalesce(v_check.risk_level, risk_level),
    fraud_decision = v_decision,
    fraud_status = case v_decision
      when 'ALLOW' then 'PASSED' when 'ADVANCE_REQUIRED' then 'ADVANCE_REQUIRED'
      when 'REVIEW' then 'REVIEW' else 'REJECTED' end::public.fraud_status,
    -- For REVIEW the rule's advance is kept as the reviewer's recommendation.
    advance_required = case when v_decision = 'REVIEW' then coalesce((v_eval ->> 'advance_amount')::numeric, 0)
                            else coalesce((v_req ->> 'amount')::numeric, 0) end,
    advance_type = case when v_decision = 'REVIEW' then coalesce((v_eval ->> 'advance_type')::public.advance_type, 'NONE')
      when coalesce((v_req ->> 'amount')::numeric, 0) > 0
      then case when v_req ->> 'mode' = 'FULL' then 'FULL'::public.advance_type
                else coalesce((v_eval ->> 'advance_type')::public.advance_type, 'FIXED') end
      else 'NONE' end
  where id = p_order_id
  returning * into v_order;

  perform public._order_log(p_order_id, 'FRAUD_EVALUATED',
    case when v_check.id is null and v_fraud_enabled then 'Risk check unavailable'
         when v_check.id is null then 'Risk check skipped'
         else format('Risk %s (score %s) → %s', v_check.risk_level, v_check.risk_score, v_decision) end,
    null, null, jsonb_build_object('fraud_check_id', p_fraud_check_id, 'decision', v_decision,
      'advance_amount', v_req -> 'amount', 'matched_rules', v_eval -> 'matched_rules'));

  v_target := case
    when v_decision = 'BLOCK' then
      case when public.setting_text('fraud', array['block_mode'], 'REJECT') = 'REVIEW' then 'FRAUD_REVIEW' else 'REJECTED_FRAUD' end
    when v_decision = 'REVIEW' then 'FRAUD_REVIEW'
    when coalesce((v_req ->> 'amount')::numeric, 0) > v_order.amount_paid then 'ADVANCE_REQUIRED'
    when public.setting_bool('orders', array['require_confirmation'], false) then 'CONFIRMATION_REQUIRED'
    else 'CONFIRMED'
  end::public.order_status;

  return public._transition_order(p_order_id, v_target,
    case v_target
      when 'REJECTED_FRAUD' then 'Blocked by fraud rules'
      when 'FRAUD_REVIEW' then 'Sent to manual fraud review'
      when 'ADVANCE_REQUIRED' then format('Advance payment of %s required', v_req ->> 'amount')
      when 'CONFIRMATION_REQUIRED' then 'Awaiting confirmation call'
      else 'Passed risk check'
    end,
    jsonb_build_object('decision', v_decision));
end;

_apply_inventory_movement.src:
declare
  v_inv public.inventory;
  v_mov public.inventory_movements;
  v_qty int;
begin
  if coalesce(p_on_hand_delta, 0) = 0 and coalesce(p_reserved_delta, 0) = 0 and coalesce(p_damaged_delta, 0) = 0 then
    raise exception 'VALIDATION: stock movement without a quantity' using errcode = '22023';
  end if;

  insert into public.inventory(variant_id, product_id)
  select v.id, v.product_id from public.product_variants v where v.id = p_variant_id
  on conflict (variant_id) do nothing;

  select * into v_inv from public.inventory where variant_id = p_variant_id for update;
  if not found then
    raise exception 'NOT_FOUND: variant % does not exist', p_variant_id using errcode = 'P0002';
  end if;

  if v_inv.on_hand + p_on_hand_delta < 0 and not (p_allow_negative or public.allow_overselling()) then
    raise exception 'INSUFFICIENT_STOCK: physical stock cannot go below zero' using errcode = 'P0001';
  end if;
  if v_inv.reserved + p_reserved_delta < 0 then
    raise exception 'VALIDATION: reserved stock cannot go below zero' using errcode = '22023';
  end if;
  if v_inv.damaged + p_damaged_delta < 0 then
    raise exception 'VALIDATION: damaged stock cannot go below zero' using errcode = '22023';
  end if;

  update public.inventory
  set on_hand = on_hand + p_on_hand_delta,
      reserved = reserved + p_reserved_delta,
      damaged = damaged + p_damaged_delta,
      updated_at = now()
  where variant_id = p_variant_id
  returning * into v_inv;

  v_qty := greatest(abs(p_on_hand_delta), abs(p_reserved_delta), abs(p_damaged_delta));

  insert into public.inventory_movements(
    product_id, variant_id, movement_type, quantity, on_hand_change, reserved_change, damaged_change,
    on_hand_after, reserved_after, damaged_after, unit_cost, reference_type, reference_id, reference_label,
    note, created_by
  ) values (
    v_inv.product_id, p_variant_id, p_type, v_qty, p_on_hand_delta, p_reserved_delta, p_damaged_delta,
    v_inv.on_hand, v_inv.reserved, v_inv.damaged, p_unit_cost, p_reference_type, p_reference_id,
    p_reference_label, p_note, auth.uid()
  ) returning * into v_mov;

  return v_mov;
end;

_apply_invoice_charges.src:
declare
  v_inv public.courier_invoices;
  l public.courier_invoice_lines;
  v_label text;
  v_date date;
  v_count int := 0;
begin
  select * into v_inv from public.courier_invoices where id = p_invoice_id;
  v_label := 'statement ' || coalesce(v_inv.invoice_number, to_char(v_inv.created_at, 'DD Mon YYYY'));
  v_date := coalesce(v_inv.invoice_date, (now() at time zone public.store_timezone())::date);
  for l in select * from public.courier_invoice_lines
           where invoice_id = p_invoice_id and match_status in ('MATCHED', 'MISMATCH') and shipment_id is not null
           order by line_no loop
    perform public._set_shipment_charge(l.shipment_id, 'DELIVERY', l.delivery_fee, 'INVOICE', 'invoice_line:' || l.id || ':delivery',
      'Delivery fee on ' || v_label, p_invoice_id, v_date);
    perform public._set_shipment_charge(l.shipment_id, 'RETURN', l.return_fee, 'INVOICE', 'invoice_line:' || l.id || ':return',
      'Return charge on ' || v_label, p_invoice_id, v_date);
    perform public._set_shipment_charge(l.shipment_id, 'COD_FEE', l.cod_fee, 'INVOICE', 'invoice_line:' || l.id || ':cod_fee',
      'COD fee on ' || v_label, p_invoice_id, v_date);
    perform public._set_shipment_charge(l.shipment_id, 'OTHER', l.other_fee, 'INVOICE', 'invoice_line:' || l.id || ':other',
      'Other courier fee on ' || v_label, p_invoice_id, v_date);
    v_count := v_count + 1;
  end loop;
  update public.courier_invoices set charges_applied_at = coalesce(charges_applied_at, now()) where id = p_invoice_id;
  return v_count;
end;

_auto_merge_web_order.src:
declare
  v_order public.orders;
  v_target public.orders;
  v_hours numeric := public.setting_numeric('orders', array['auto_merge_window_hours'], 72);
  v_priority text[] := coalesce((select array_agg(x) from jsonb_array_elements_text(
      coalesce(public.get_setting('orders') -> 'merge_review_priority', '["PROCESSING","FOLLOW_UP","GOOD_NO_RESPONSE","NO_RESPONSE"]'::jsonb)) x), '{}');
  v_web constant public.order_status[] := array['PENDING', 'CONFIRMATION_REQUIRED']::public.order_status[];
begin
  if not public.setting_bool('orders', array['auto_merge_web_enabled'], true) then
    return null;
  end if;
  select * into v_order from public.orders where id = p_order_id;
  if not found or v_order.customer_phone is null then
    return null;
  end if;
  perform pg_advisory_xact_lock(hashtextextended('order-merge:' || v_order.customer_phone, 0));
  select * into v_order from public.orders where id = p_order_id for update;
  if v_order.confirmed_at is not null or v_order.merged_into is not null or not (v_order.status = any(v_web))
     or not (v_order.review_status = any(v_priority))
     or v_order.amount_paid > 0 or v_order.coupon_id is not null
     or coalesce(v_order.manual_discount, 0) > 0 or coalesce(v_order.coupon_discount, 0) > 0
     or exists (select 1 from public.payments where order_id = v_order.id and status = 'REQUIRES_VERIFICATION')
     or exists (select 1 from public.shipments where order_id = v_order.id and is_active) then
    return null;
  end if;

  select o.* into v_target from public.orders o
  where o.customer_phone = v_order.customer_phone
    and o.id <> v_order.id
    and o.merged_into is null
    and o.confirmed_at is null and o.status = any(v_web) and o.review_status = any(v_priority)
    and o.created_at <= v_order.created_at
    and o.created_at >= v_order.created_at - make_interval(secs => (v_hours * 3600)::int)
    and o.label_printed_at is null
    and not exists (select 1 from public.shipments s where s.order_id = o.id and s.is_active)
  order by o.created_at
  limit 1
  for update;
  if not found then
    return null;
  end if;

  perform public._merge_web_orders(v_target.id, v_order.id,
    format('same customer %s, %s apart', v_order.customer_phone,
      case when v_order.created_at - v_target.created_at < interval '1 hour'
        then ceil(extract(epoch from v_order.created_at - v_target.created_at) / 60)::int || ' min'
        else round(extract(epoch from v_order.created_at - v_target.created_at) / 3600, 1) || ' h' end));
  return v_target.id;
end;

_auto_pick_agent.src:
declare
  v_cfg jsonb := public.get_setting('auto_pick');
  v_mode text := coalesce(v_cfg ->> 'mode', 'round_robin');
  v_max int := coalesce((v_cfg ->> 'max_open')::int, 0);
  v_agent uuid;
begin
  if not coalesce((v_cfg ->> 'enabled')::boolean, false) then
    return null;
  end if;
  with agents as (
    select p.id from public.profiles p
    where p.is_active and p.id::text in (select jsonb_array_elements_text(coalesce(v_cfg -> 'agent_ids', '[]'::jsonb)))
  ), load as (
    select a.id,
      (select count(*) from public.orders o where o.assigned_to = a.id and o.confirmed_at is null
         and o.status not in ('CANCELLED', 'REJECTED_FRAUD')
         and o.review_status in (select code from public.order_review_statuses where not closes_order)) as open_count,
      (select max(o.assigned_at) from public.orders o where o.assigned_to = a.id) as last_assigned
    from agents a
  )
  select id into v_agent from load
  where v_max <= 0 or open_count < v_max
  order by case when v_mode = 'least_open' then open_count else 0 end, last_assigned nulls first, id
  limit 1;
  return v_agent;
end;

_bd_district.src:
declare
  v_hint text;
  v_text text;
  v_flat text;
