  v_districts jsonb := coalesce(public.get_setting('delivery') -> 'districts', '[]'::jsonb);
begin
  foreach v_hint in array coalesce(p_hints, '{}') loop
    continue when coalesce(trim(v_hint), '') = '';
    -- Bangla: a district (or well-known area) named anywhere in the text, longest name first.
    for v_key in select k from jsonb_object_keys(v_bn) k order by length(k) desc loop
      if position(v_key in v_hint) > 0 then
        return v_bn ->> v_key;
      end if;
    end loop;
    v_text := lower(regexp_replace(regexp_replace(v_hint, '[''’‘`´]', '', 'g'), '[^A-Za-z ]+', ' ', 'g'));
    v_text := regexp_replace(v_text, '\m(district|division|zila|zilla|sadar|city|bd|bangladesh|upazila|thana)\M', ' ', 'g');
    v_text := trim(regexp_replace(v_text, '\s+', ' ', 'g'));
    continue when v_text = '';
    v_flat := replace(v_text, ' ', '');
    -- The district itself, alone or as a word.
    select d into v_name from jsonb_array_elements_text(v_districts) d
    where lower(regexp_replace(d, '[^A-Za-z]+', '', 'g')) = v_flat limit 1;
    if v_name is not null then return v_name; end if;
    select d into v_name from jsonb_array_elements_text(v_districts) d
    where v_text ~ ('\m' || lower(regexp_replace(d, '[^A-Za-z ]+', '', 'g')) || '\M')
    order by length(d) desc limit 1;
    if v_name is not null then return v_name; end if;
    -- Other spellings and well-known areas, longest first; "coxsbazar" matches "coxs bazar".
    for v_key in select k from jsonb_object_keys(v_aliases) k order by length(k) desc loop
      if v_text ~ ('\m' || v_key || '\M') or v_flat = replace(v_key, ' ', '') then
        return v_aliases ->> v_key;
      end if;
    end loop;
  end loop;
  return null;
end;

_billing_apply_payment.src:
declare
  v_inv public.billing_invoices;
  s public.subscriptions;
begin
  select * into v_inv from public.billing_invoices where id = p_payment.invoice_id for update;
  if v_inv.status <> 'OPEN' then
    return v_inv;
  end if;
  update public.billing_invoices set amount_paid = amount_paid + p_payment.amount,
    status = case when amount_paid + p_payment.amount >= total then 'PAID' else status end,
    paid_at = case when amount_paid + p_payment.amount >= total then now() else paid_at end
  where id = v_inv.id returning * into v_inv;
  if v_inv.status = 'PAID' and v_inv.kind = 'SUBSCRIPTION' then
    select * into s from public.subscriptions where id = v_inv.subscription_id for update;
    if s.id is not null and s.ended_at is null and s.status in ('TRIALING', 'PAST_DUE', 'ACTIVE') then
      update public.subscriptions set status = 'ACTIVE', grace_until = null, trial_ends_at = case when s.status = 'TRIALING' then now() else trial_ends_at end,
        current_period_start = greatest(coalesce(current_period_start, v_inv.period_start), v_inv.period_start),
        current_period_end = greatest(coalesce(current_period_end, v_inv.period_end), v_inv.period_end)
      where id = s.id returning * into s;
      perform public._subscription_event(s, 'invoice.paid', jsonb_build_object('invoice', v_inv.number));
    end if;
  elsif v_inv.status = 'PAID' and v_inv.kind = 'CREDITS' then
    perform public._billing_grant_credits(v_inv);
  end if;
  return v_inv;
end;

_billing_grant_credits.src:
declare
  l record;
begin
  for l in select x.line, x.n from jsonb_array_elements(p_inv.lines) with ordinality as x(line, n) where x.line ->> 'kind' = 'credits' loop
    perform public._credit_post(p_inv.merchant_id, l.line ->> 'credit_type', (l.line ->> 'credits')::int, 'RECHARGE',
      'Bought ' || coalesce(l.line ->> 'label', 'credits'), null, 'SYSTEM', 'billing_invoice', p_inv.id::text,
      'invoice:' || p_inv.id || ':' || l.n, null, jsonb_build_object('invoice', p_inv.number, 'package_id', l.line ->> 'package_id'));
  end loop;
end;

_billing_invoice_for.src:
declare
  v_plan public.plans;
  v_lines jsonb := '[]'::jsonb;
  v_total numeric := 0;
  v_due int := coalesce((select (value ->> 'invoice_due_days')::int from public.platform_settings where key = 'billing'), 7);
  v_inv public.billing_invoices;
  v_over numeric;
  v_orders bigint;
  v_prev_start timestamptz := p_start - public._billing_interval(p_sub.billing_interval);
  a record;
begin
  select * into v_inv from public.billing_invoices where subscription_id = p_sub.id and period_start = p_start and kind = 'SUBSCRIPTION' and status <> 'VOID';
  if v_inv.id is not null then
    return v_inv;
  end if;
  select * into v_plan from public.plans where id = p_sub.plan_id;
  v_lines := v_lines || jsonb_build_object('label', format('%s plan, %s – %s', v_plan.name, to_char(p_start, 'DD Mon YYYY'), to_char(p_end, 'DD Mon YYYY')),
    'amount', p_sub.price, 'kind', 'plan');
  v_total := p_sub.price;
  for a in select pa.name, sa.quantity, sa.price from public.subscription_addons sa join public.plan_addons pa on pa.id = sa.addon_id
           where sa.subscription_id = p_sub.id and sa.ended_at is null loop
    v_lines := v_lines || jsonb_build_object('label', format('%s × %s', a.name, a.quantity), 'amount', a.price * a.quantity, 'kind', 'addon');
    v_total := v_total + a.price * a.quantity;
  end loop;
  -- Orders over the limit in the previous period, at the plan's overage price (actual order count).
  v_over := nullif(v_plan.overage ->> 'order_price', '')::numeric;
  if v_over is not null and (v_plan.limits ->> 'orders_per_month') is not null and v_prev_start >= p_sub.started_at then
    select count(*) into v_orders from public.orders where merchant_id = p_sub.merchant_id and created_at >= v_prev_start and created_at < p_start;
    if v_orders > (v_plan.limits ->> 'orders_per_month')::bigint then
      v_lines := v_lines || jsonb_build_object('label', format('%s orders over the %s included', v_orders - (v_plan.limits ->> 'orders_per_month')::bigint,
        v_plan.limits ->> 'orders_per_month'), 'amount', round((v_orders - (v_plan.limits ->> 'orders_per_month')::bigint) * v_over, 2), 'kind', 'overage');
      v_total := v_total + round((v_orders - (v_plan.limits ->> 'orders_per_month')::bigint) * v_over, 2);
    end if;
  end if;
  insert into public.billing_invoices (merchant_id, subscription_id, kind, period_start, period_end, lines, total, currency, due_at, status, paid_at)
  values (p_sub.merchant_id, p_sub.id, 'SUBSCRIPTION', p_start, p_end, v_lines, v_total, p_sub.currency, now() + make_interval(days => v_due),
          case when v_total = 0 then 'PAID' else 'OPEN' end, case when v_total = 0 then now() end)
  on conflict do nothing
  returning * into v_inv;
  if v_inv.id is null then
    select * into v_inv from public.billing_invoices where subscription_id = p_sub.id and period_start = p_start and kind = 'SUBSCRIPTION' and status <> 'VOID';
  else
    perform public._subscription_event(p_sub, 'invoice.created', jsonb_build_object('invoice', v_inv.number, 'total', v_total));
  end if;
  return v_inv;
end;

_channel_apply_store_details.src:
declare
  v_c public.sales_channels;
  v_n int := 0;
  v_p record;
  v_cat uuid;
  v_name text;
begin
  select * into v_c from public.sales_channels where id = p_channel_id;
  if v_c.first_sync_at is null or not public._channel_opt(v_c, 'update_products', true) then
    return 0;
  end if;
  -- Variants: price, compare-at, cost (when the store has one), barcode, weight.
  update public.product_variants pv set
    price = coalesce(ci.price, pv.price), compare_at_price = ci.compare_at_price,
    cost_price = coalesce(ci.unit_cost, pv.cost_price), barcode = coalesce(ci.barcode, pv.barcode),
    weight_grams = coalesce(ci.weight_grams, pv.weight_grams),
    title = case when nullif(nullif(trim(ci.variant_title), ''), 'Default Title') is not null then ci.variant_title else pv.title end
  from public.sales_channel_variants m
  join public.channel_catalog_items ci on ci.channel_id = m.channel_id and ci.external_variant_id = m.external_variant_id and ci.removed_at is null
  where m.channel_id = p_channel_id and pv.id = m.variant_id
    and (p_product_ids is null or ci.external_product_id = any (p_product_ids))
    and (pv.price is distinct from coalesce(ci.price, pv.price) or pv.compare_at_price is distinct from ci.compare_at_price
         or pv.cost_price is distinct from coalesce(ci.unit_cost, pv.cost_price) or pv.barcode is distinct from coalesce(ci.barcode, pv.barcode)
         or pv.weight_grams is distinct from coalesce(ci.weight_grams, pv.weight_grams)
         or (nullif(nullif(trim(ci.variant_title), ''), 'Default Title') is not null and pv.title is distinct from ci.variant_title));
  get diagnostics v_n = row_count;

  -- Products: name, description, brand, price shown, category from type / collection, images.
  for v_p in
    select distinct on (pv.product_id) pv.product_id, ci.product_title, ci.product_description, ci.vendor, ci.product_type, ci.collections,
      ci.images, ci.image_url, ci.price, ci.compare_at_price, ci.unit_cost, ci.product_status
    from public.sales_channel_variants m
    join public.channel_catalog_items ci on ci.channel_id = m.channel_id and ci.external_variant_id = m.external_variant_id and ci.removed_at is null
    join public.product_variants pv on pv.id = m.variant_id
    where m.channel_id = p_channel_id and (p_product_ids is null or ci.external_product_id = any (p_product_ids))
    order by pv.product_id, ci.external_variant_id
  loop
    v_name := coalesce(nullif(trim(v_p.product_type), ''), v_p.collections[1]);
    v_cat := null;
    if v_name is not null then
      select id into v_cat from public.categories where lower(name) = lower(v_name) or slug = public.slugify(v_name) limit 1;
      if v_cat is null then
        insert into public.categories(name, slug) values (left(v_name, 120), left(public.slugify(v_name), 80))
        on conflict do nothing returning id into v_cat;
        if v_cat is null then
          select id into v_cat from public.categories where slug = left(public.slugify(v_name), 80);
        end if;
      end if;
    end if;
    update public.products p set
      name = coalesce(nullif(trim(v_p.product_title), ''), p.name),
      description = coalesce(v_p.product_description, p.description),
      brand = coalesce(v_p.vendor, p.brand),
      price = coalesce(v_p.price, p.price),
      compare_at_price = v_p.compare_at_price,
      cost_price = case when v_p.unit_cost is not null then v_p.unit_cost else p.cost_price end,
      category_id = coalesce(p.category_id, v_cat)
    where p.id = v_p.product_id
      and (p.name is distinct from coalesce(nullif(trim(v_p.product_title), ''), p.name) or p.description is distinct from coalesce(v_p.product_description, p.description)
           or p.brand is distinct from coalesce(v_p.vendor, p.brand) or p.price is distinct from coalesce(v_p.price, p.price)
           or p.compare_at_price is distinct from v_p.compare_at_price
           or (v_p.unit_cost is not null and p.cost_price is distinct from v_p.unit_cost) or (p.category_id is null and v_cat is not null));
    if found then
      v_n := v_n + 1;
    end if;
    if not exists (select 1 from public.product_images where product_id = v_p.product_id) then
      insert into public.product_images(product_id, url, is_primary, position)
      select v_p.product_id, u, n = 1, (n - 1)::int
      from jsonb_array_elements_text(case when jsonb_array_length(v_p.images) > 0 then v_p.images
                                          when v_p.image_url is not null then jsonb_build_array(v_p.image_url) else '[]'::jsonb end)
        with ordinality as t(u, n);
    end if;
  end loop;
  return v_n;
end;

_channel_autoimport.src:
declare
  v_c public.sales_channels;
  v_ids text[];
  v_r jsonb;
begin
  select * into v_c from public.sales_channels where id = p_channel_id;
  if v_c.first_sync_at is null or not public._channel_opt(v_c, 'auto_import_products', true) then
    return jsonb_build_object('created', 0, 'skipped', 'off');
  end if;
  select coalesce(array_agg(distinct ci.external_product_id), '{}') into v_ids
  from public.channel_catalog_items ci
  where ci.channel_id = p_channel_id and ci.removed_at is null and ci.external_product_id is not null
    and upper(coalesce(ci.product_status, 'ACTIVE')) <> 'TRASH'
    and (p_product_ids is null or ci.external_product_id = any (p_product_ids))
    and not exists (select 1 from public.sales_channel_variants m where m.channel_id = ci.channel_id and m.external_variant_id = ci.external_variant_id);
  if coalesce(array_length(v_ids, 1), 0) = 0 then
    return jsonb_build_object('created', 0);
  end if;
  v_r := public._channel_catalog_adopt(p_channel_id, v_ids[1:500], true, true, null);
  if (v_r ->> 'created')::int > 0 or (v_r ->> 'linked')::int > 0 then
    perform public.log_audit('channel.catalog_auto_import', 'sales_channel', p_channel_id::text, null,
      jsonb_build_object('products', v_ids[1:500], 'created', v_r -> 'created', 'linked', v_r -> 'linked'));
  end if;
  return v_r - 'plan';
end;

_channel_catalog_adopt.src:
declare
  v_c public.sales_channels;
  v_pid text;
  v_first public.channel_catalog_items;
  v_ci public.channel_catalog_items;
  v_product uuid;
  v_variant uuid;
  v_existing uuid;
  v_sku text;
  v_qty int;
  v_opts text[];
  v_plan jsonb := '[]'::jsonb;
  v_created int := 0;
  v_linked int := 0;
  v_pos int;
  v_prefix text;
  v_loc text;
  v_category uuid;
begin
  select * into v_c from public.sales_channels where id = p_channel_id;
  if not found then
    raise exception 'NOT_FOUND: sales channel not found' using errcode = 'P0002';
  end if;
  v_prefix := case v_c.platform when 'SHOPIFY' then 'SHOP' else 'WOO' end;
  v_loc := coalesce(p_location, v_c.settings ->> 'location_id');

  foreach v_pid in array p_product_ids loop
    select * into v_first from public.channel_catalog_items where channel_id = p_channel_id and external_product_id = v_pid and removed_at is null
    order by external_variant_id limit 1;
    continue when not found;
    select pv.product_id into v_product from public.sales_channel_variants m join public.product_variants pv on pv.id = m.variant_id
    where m.channel_id = p_channel_id and m.external_product_id = v_pid limit 1;
    select coalesce(max(position) + 1, 0) into v_pos from public.product_variants where product_id = v_product;
    select coalesce(array_agg(k order by k), '{}') into v_opts
    from (select distinct jsonb_object_keys(options) k from public.channel_catalog_items
          where channel_id = p_channel_id and external_product_id = v_pid and removed_at is null) o;

    for v_ci in select * from public.channel_catalog_items where channel_id = p_channel_id and external_product_id = v_pid and removed_at is null
                order by external_variant_id loop
      if exists (select 1 from public.sales_channel_variants m join public.product_variants pv on pv.id = m.variant_id
                 where m.channel_id = p_channel_id and m.external_variant_id = v_ci.external_variant_id) then
        v_plan := v_plan || jsonb_build_object('product_id', v_pid, 'external_variant_id', v_ci.external_variant_id, 'action', 'ALREADY_LINKED',
          'title', concat_ws(' — ', v_ci.product_title, nullif(v_ci.variant_title, 'Default Title')), 'sku', v_ci.sku);
        continue;
      end if;
      v_sku := coalesce(v_ci.sku, v_prefix || '-' || regexp_replace(v_ci.external_variant_id, '[^A-Za-z0-9]+', '', 'g'));
      select id into v_existing from public.product_variants where lower(sku) = lower(v_sku) limit 1;
      v_qty := case when v_ci.tracked then greatest(coalesce((select (l ->> 'available')::int from jsonb_array_elements(v_ci.levels) l
                 where l ->> 'location_id' = coalesce(v_loc, l ->> 'location_id') limit 1), 0), 0) else 0 end;
      v_plan := v_plan || jsonb_build_object('product_id', v_pid, 'external_variant_id', v_ci.external_variant_id,
        'action', case when v_existing is not null then 'LINK' else 'CREATE' end,
        'title', concat_ws(' — ', v_ci.product_title, nullif(v_ci.variant_title, 'Default Title')), 'sku', v_sku,
        'price', v_ci.price, 'cost', v_ci.unit_cost, 'stock', case when p_with_stock and v_existing is null then v_qty end);
      continue when not p_apply;

      if v_existing is not null then
        v_variant := v_existing;
        v_linked := v_linked + 1;
        perform public._channel_fill_blanks(v_variant, v_ci);
      else
        if v_product is null then
          select id into v_category from public.categories
          where v_first.product_type is not null and (lower(name) = lower(v_first.product_type) or slug = public.slugify(v_first.product_type)) limit 1;
          insert into public.products(name, slug, status, price, compare_at_price, cost_price, description, option_names, track_inventory,
            tags, brand, category_id, weight_grams, created_by)
          values (left(coalesce(nullif(trim(v_first.product_title), ''), 'Product'), 200),
            left(public.slugify(coalesce(v_first.product_title, 'product')), 60) || '-' || left(md5(p_channel_id::text || v_pid), 6),
            public._channel_store_status(v_first.product_status),
            coalesce(v_first.price, 0), v_first.compare_at_price, coalesce(v_first.unit_cost, 0), v_first.product_description, v_opts,
            exists (select 1 from public.channel_catalog_items x where x.channel_id = p_channel_id and x.external_product_id = v_pid
                      and x.removed_at is null and x.tracked),
            (select array_agg(distinct t) from unnest(array[lower(v_c.platform::text)] || v_first.tags
                     || case when v_category is null and v_first.product_type is not null then array[v_first.product_type] else '{}'::text[] end) t),
            v_first.vendor, v_category, v_first.weight_grams, auth.uid())
          returning id into v_product;
          insert into public.product_images(product_id, url, is_primary, position)
          select v_product, u, n = 1, (n - 1)::int
          from jsonb_array_elements_text(case when jsonb_array_length(v_first.images) > 0 then v_first.images
                                              when v_first.image_url is not null then jsonb_build_array(v_first.image_url) else '[]'::jsonb end)
            with ordinality as t(u, n);
        end if;
        insert into public.product_variants(product_id, sku, title, option_values, price, compare_at_price, cost_price, barcode, weight_grams, position, is_default)
        values (v_product, v_sku, coalesce(nullif(nullif(trim(v_ci.variant_title), ''), 'Default Title'), 'Default'), v_ci.options,
          v_ci.price, v_ci.compare_at_price, v_ci.unit_cost, v_ci.barcode, v_ci.weight_grams, v_pos,
          v_pos = 0 and not exists (select 1 from public.product_variants where product_id = v_product))
        returning id into v_variant;
        v_pos := v_pos + 1;
        v_created := v_created + 1;
        if p_with_stock and v_qty > 0 then
          perform public._apply_inventory_movement(v_variant, 'ADJUSTMENT', v_qty, 0, 0, 'CHANNEL', p_channel_id,
            format('Opening stock from %s', v_c.name), format('Imported from %s: %s in stock there', v_c.name, v_qty), v_ci.unit_cost, false);
        end if;
      end if;
      insert into public.sales_channel_variants(channel_id, external_variant_id, external_product_id, variant_id, inventory_item_id, sku,
        shopify_available, last_pushed_qty, sync_status)
      values (p_channel_id, v_ci.external_variant_id, v_pid, v_variant, v_ci.inventory_item_id, v_ci.sku,
        case when v_ci.tracked then v_qty end, case when v_ci.tracked and p_with_stock and v_existing is null then v_qty end,
        case when not v_ci.tracked then 'UNTRACKED' when p_with_stock and v_existing is null then 'OK' else 'NEW' end)
      on conflict (channel_id, external_variant_id) do update
        set variant_id = excluded.variant_id, inventory_item_id = excluded.inventory_item_id, sku = excluded.sku;
    end loop;
  end loop;
  return jsonb_build_object('applied', p_apply, 'created', v_created, 'linked', v_linked, 'plan', v_plan);
end;

_channel_catalog_collections.src:
begin
  update public.channel_catalog_items ci set collections = coalesce((select array_agg(left(trim(t), 120))
      from jsonb_array_elements_text(x -> 'collections') t where trim(t) <> ''), '{}')
  from jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) x
  where ci.channel_id = p_channel_id and ci.external_variant_id = x ->> 'external_variant_id' and jsonb_typeof(x -> 'collections') = 'array';
end;

_channel_fill_blanks.src:
declare
  v_product uuid;
begin
  -- A cost of 0 counts as "not entered".
  update public.product_variants set
    cost_price = case when coalesce(cost_price, 0) = 0 then coalesce(p_ci.unit_cost, cost_price) else cost_price end,
    barcode = coalesce(barcode, p_ci.barcode),
    weight_grams = coalesce(weight_grams, p_ci.weight_grams)
  where id = p_variant_id
    and (coalesce(cost_price, 0) = 0 and p_ci.unit_cost is not null or barcode is null and p_ci.barcode is not null
         or weight_grams is null and p_ci.weight_grams is not null);
  select product_id into v_product from public.product_variants where id = p_variant_id;
  update public.products set cost_price = case when coalesce(cost_price, 0) = 0 then coalesce(p_ci.unit_cost, cost_price) else cost_price end,
    brand = coalesce(brand, p_ci.vendor)
  where id = v_product and (coalesce(cost_price, 0) = 0 and p_ci.unit_cost is not null or brand is null and p_ci.vendor is not null);
  if not exists (select 1 from public.product_images where product_id = v_product) then
    insert into public.product_images(product_id, url, is_primary, position)
    select v_product, u, n = 1, (n - 1)::int
    from jsonb_array_elements_text(case when jsonb_array_length(p_ci.images) > 0 then p_ci.images
                                        when p_ci.image_url is not null then jsonb_build_array(p_ci.image_url) else '[]'::jsonb end)
      with ordinality as t(u, n);
  end if;
end;

_channel_first_sync_run.src:
declare
  v_c public.sales_channels;
  v_store text;
  v_ids text[];
  v_adopt jsonb;
  v_m record;
  v_stock jsonb := '[]'::jsonb;
  v_delta int;
  v_store_qty int;
  v_linked_before int;
begin
  select * into v_c from public.sales_channels where id = p_channel_id for update;
  if not found then
    raise exception 'NOT_FOUND: sales channel not found' using errcode = 'P0002';
  end if;
  v_store := case v_c.platform when 'SHOPIFY' then 'Shopify' else 'WooCommerce' end;
  if v_c.status <> 'CONNECTED' then
    raise exception 'VALIDATION: connect the store first' using errcode = '22023';
  end if;
  if v_c.catalog_imported_at is null then
    raise exception 'VALIDATION: read the store''s catalog first' using errcode = '22023';
  end if;
  if p_location_id is null or not exists (select 1 from jsonb_array_elements(v_c.locations) l where l ->> 'id' = p_location_id) then
    raise exception 'VALIDATION: choose one of the store''s locations' using errcode = '22023';
  end if;
  select count(*) into v_linked_before from public.sales_channel_variants where channel_id = p_channel_id and inventory_item_id is not null;

  update public.sales_channels set settings = settings || jsonb_build_object('location_id', p_location_id, 'inventory_sync', false)
  where id = p_channel_id;
  perform public._channel_link_by_sku(p_channel_id);

  select coalesce(array_agg(distinct ci.external_product_id), '{}') into v_ids
  from public.channel_catalog_items ci
  where ci.channel_id = p_channel_id and ci.removed_at is null and ci.external_product_id is not null
    and upper(coalesce(ci.product_status, 'ACTIVE')) <> 'TRASH'
    and not exists (select 1 from public.sales_channel_variants m where m.channel_id = ci.channel_id and m.external_variant_id = ci.external_variant_id);
  v_adopt := case when coalesce(array_length(v_ids, 1), 0) > 0
    then public._channel_catalog_adopt(p_channel_id, v_ids[1:2000], true, true, p_location_id)
    else jsonb_build_object('created', 0, 'linked', 0, 'plan', '[]'::jsonb) end;

  for v_m in
    select m.variant_id, v.sku, p.name as product, v.title as variant, p.track_inventory,
      greatest(coalesce(i.available, 0), 0) as ours, ci.tracked, ci.levels
    from public.sales_channel_variants m
    join public.product_variants v on v.id = m.variant_id
    join public.products p on p.id = v.product_id
    left join public.inventory i on i.variant_id = m.variant_id
    join public.channel_catalog_items ci on ci.channel_id = m.channel_id and ci.external_variant_id = m.external_variant_id and ci.removed_at is null
    where m.channel_id = p_channel_id
    order by p.name, v.title
  loop
    continue when not v_m.tracked or not v_m.track_inventory;
    v_store_qty := (select (l ->> 'available')::int from jsonb_array_elements(v_m.levels) l where l ->> 'location_id' = p_location_id limit 1);
    continue when v_store_qty is null;
    v_delta := greatest(v_store_qty, 0) - v_m.ours;
    if v_delta <> 0 then
      v_stock := v_stock || jsonb_build_object('variant_id', v_m.variant_id, 'sku', v_m.sku,
        'title', concat_ws(' — ', v_m.product, nullif(v_m.variant, 'Default')), 'ours', v_m.ours, 'store', v_store_qty, 'change', v_delta);
      perform public._apply_inventory_movement(v_m.variant_id, 'ADJUSTMENT', v_delta, 0, 0, 'CHANNEL', p_channel_id,
        format('First sync with %s', v_c.name), format('First sync: stock set to %s''s %s (was %s here)', v_store, v_store_qty, v_m.ours), null, false);
    end if;
    update public.sales_channel_variants set shopify_available = v_store_qty, last_pushed_qty = v_store_qty,
      sync_status = 'OK', last_error = null, mismatch_since = null, synced_at = now()
    where channel_id = p_channel_id and variant_id = v_m.variant_id;
  end loop;

  perform public._channel_fill_blanks(m.variant_id, ci)
  from public.sales_channel_variants m
  join public.channel_catalog_items ci on ci.channel_id = m.channel_id and ci.external_variant_id = m.external_variant_id
  where m.channel_id = p_channel_id;

  update public.sales_channels set first_sync_at = now(),
    settings = settings || jsonb_build_object('location_id', p_location_id, 'inventory_sync', true, 'auto_import_products', coalesce(p_auto_import, true))
  where id = p_channel_id;
  perform public.channel_job_enqueue(p_channel_id, 'INVENTORY', m.variant_id)
  from public.sales_channel_variants m
  left join public.inventory i on i.variant_id = m.variant_id
  where m.channel_id = p_channel_id and m.inventory_item_id is not null and m.sync_status <> 'UNTRACKED'
    and m.shopify_available is distinct from greatest(coalesce(i.available, 0), 0);

  return jsonb_build_object(
    'store', v_store, 'location_id', p_location_id,
    'products', (select count(distinct x ->> 'product_id') from jsonb_array_elements(v_adopt -> 'plan') x where x ->> 'action' = 'CREATE'),
    'create', (select count(*) from jsonb_array_elements(v_adopt -> 'plan') x where x ->> 'action' = 'CREATE'),
    'link', greatest((select count(*) from public.sales_channel_variants where channel_id = p_channel_id and inventory_item_id is not null)
            - v_linked_before - coalesce((v_adopt ->> 'created')::int, 0), 0),
    'already_linked', v_linked_before,
    'untracked', (select count(*) from public.channel_catalog_items where channel_id = p_channel_id and removed_at is null and not tracked),
    'stock_changes', v_stock,
    'items', (select coalesce(jsonb_agg(x), '[]'::jsonb) from (select x from jsonb_array_elements(v_adopt -> 'plan') x
              where x ->> 'action' in ('CREATE', 'LINK') limit 300) q));
end;

_channel_link_by_sku.src:
declare
  v_loc text;
  v_linked int;
begin
  select settings ->> 'location_id' into v_loc from public.sales_channels where id = p_channel_id;
  update public.sales_channel_variants m set inventory_item_id = ci.inventory_item_id, sku = ci.sku,
    sync_status = case when not ci.tracked then 'UNTRACKED' when m.sync_status = 'UNTRACKED' then 'NEW' else m.sync_status end,
    shopify_available = (select (l ->> 'available')::int from jsonb_array_elements(ci.levels) l where l ->> 'location_id' = v_loc limit 1)
  from public.channel_catalog_items ci
  where ci.channel_id = p_channel_id and m.channel_id = p_channel_id and m.external_variant_id = ci.external_variant_id
    and ci.removed_at is null;

  insert into public.sales_channel_variants(channel_id, external_variant_id, external_product_id, variant_id, inventory_item_id, sku,
    shopify_available, sync_status)
  select ci.channel_id, ci.external_variant_id, ci.external_product_id, v.id, ci.inventory_item_id, ci.sku,
    (select (l ->> 'available')::int from jsonb_array_elements(ci.levels) l where l ->> 'location_id' = v_loc limit 1),
    case when ci.tracked then 'NEW' else 'UNTRACKED' end
  from public.channel_catalog_items ci
  join public.product_variants v on lower(v.sku) = lower(ci.sku) and v.is_active
  where ci.channel_id = p_channel_id and ci.sku is not null and ci.removed_at is null
    and not exists (select 1 from public.sales_channel_variants m where m.channel_id = ci.channel_id and m.external_variant_id = ci.external_variant_id)
    and (select count(*) from public.product_variants v2 where lower(v2.sku) = lower(ci.sku) and v2.is_active) = 1
    and (select count(*) from public.channel_catalog_items c2 where c2.channel_id = ci.channel_id and lower(c2.sku) = lower(ci.sku) and c2.removed_at is null) = 1
  on conflict do nothing;
  get diagnostics v_linked = row_count;
  return v_linked;
end;

_channel_order_tax.src:
declare
  v_total numeric := nullif(p_order ->> 'total', '')::numeric;
  v_extra numeric;
begin
  if nullif(p_order ->> 'tax_total', '') is not null then
    return public.money(greatest((p_order ->> 'tax_total')::numeric, 0));
  end if;
  if v_total is null or nullif(p_order ->> 'discount_total', '') is null then
    return 0;
  end if;
  v_extra := v_total - (p_subtotal + p_shipping - greatest((p_order ->> 'discount_total')::numeric, 0));
  return case when v_extra >= 0.01 then public.money(v_extra) else 0 end;
exception when others then
  return 0;
end;

_channel_presync_restock.src:
declare
  v_created timestamptz;
  v_item jsonb;
  v_label text := coalesce(nullif(p_order ->> 'number', ''), p_order ->> 'external_id');
begin
  -- Read by the link trigger in the same transaction (see _orders_channel_import_trigger).
  perform set_config('app.channel_presync_order', '', true);
  if p_channel.first_sync_at is null or not coalesce((p_channel.settings ->> 'inventory_sync')::boolean, false) then
    return;
  end if;
  begin
    v_created := nullif(p_order ->> 'created_at', '')::timestamptz;
  exception when others then
    v_created := null;
  end;
  if v_created is null or v_created >= p_channel.first_sync_at then
    return;
  end if;
  perform set_config('app.channel_presync_order', 'on', true);
  for v_item in select * from jsonb_array_elements(p_items) loop
    continue when coalesce((v_item ->> 'quantity')::int, 0) <= 0;
    if exists (select 1 from public.sales_channel_variants m
               join public.product_variants v on v.id = m.variant_id
               join public.products p on p.id = v.product_id
               where m.channel_id = p_channel.id and m.variant_id = (v_item ->> 'variant_id')::uuid
                 and m.inventory_item_id is not null and p.track_inventory) then
      perform public._apply_inventory_movement((v_item ->> 'variant_id')::uuid, 'ADJUSTMENT', (v_item ->> 'quantity')::int, 0, 0,
        'CHANNEL', p_channel.id, format('Order %s from %s', v_label, p_channel.name),
        'Placed in the store before the first sync, so the stock copied from the store had already counted it', null, false);
    end if;
  end loop;
end;

_channel_variant.src:
declare
  v_ext text := coalesce(nullif(p_line ->> 'external_variant_id', ''), 'custom:' || md5(lower(coalesce(p_line ->> 'title', ''))));
  v_sku text := nullif(trim(coalesce(p_line ->> 'sku', '')), '');
  v_title text := coalesce(nullif(trim(p_line ->> 'title'), ''), 'Item');
  v_variant uuid;
  v_product uuid;
  v_price numeric := greatest(coalesce(nullif(p_line ->> 'unit_price', '')::numeric, 0), 0);
  v_prefix text := case p_channel.platform when 'SHOPIFY' then 'SHOP' else 'WOO' end;
begin
  select variant_id into v_variant from public.sales_channel_variants where channel_id = p_channel.id and external_variant_id = v_ext;
  if v_variant is not null and exists (select 1 from public.product_variants where id = v_variant) then
    return v_variant;
  end if;
  if v_sku is not null then
    select id into v_variant from public.product_variants where lower(sku) = lower(v_sku) order by is_active desc limit 1;
  end if;
  if v_variant is null then
    v_sku := coalesce(v_sku, v_prefix || '-' || left(regexp_replace(v_ext, '[^A-Za-z0-9]+', '', 'g'), 40));
    select id into v_variant from public.product_variants where lower(sku) = lower(v_sku) limit 1;
  end if;
  if v_variant is null then
    insert into public.products(name, slug, status, price, track_inventory, tags, created_by)
    values (left(v_title, 200), left(public.slugify(v_title), 60) || '-' || left(md5(p_channel.id::text || v_ext), 8), 'DRAFT',
            public.money(v_price), false, array[lower(p_channel.platform)], null)
    returning id into v_product;
    insert into public.product_variants(product_id, sku, title, price, is_default)
    values (v_product, v_sku, coalesce(nullif(trim(p_line ->> 'variant_title'), ''), 'Default'), public.money(v_price), true)
    returning id into v_variant;
    if nullif(p_line ->> 'image_url', '') is not null and (p_line ->> 'image_url') ~ '^https://' then
      insert into public.product_images(product_id, url, is_primary, position) values (v_product, p_line ->> 'image_url', true, 0);
    end if;
  end if;
  insert into public.sales_channel_variants(channel_id, external_variant_id, external_product_id, variant_id)
  values (p_channel.id, v_ext, nullif(p_line ->> 'external_product_id', ''), v_variant)
  on conflict (channel_id, external_variant_id) do update set variant_id = excluded.variant_id;
  return v_variant;
end;

_commit_order_stock.src:
declare
  v_res public.stock_reservations;
  v_number text := (select order_number from public.orders where id = p_order_id);
  v_count int := 0;
begin
  for v_res in select * from public.stock_reservations where order_id = p_order_id and status = 'ACTIVE' for update loop
    perform public._apply_inventory_movement(v_res.variant_id, 'SALE', -v_res.quantity, -v_res.quantity, 0,
      'ORDER', p_order_id, v_number, 'Shipped', public.variant_cost(v_res.variant_id), true);
    update public.stock_reservations set status = 'COMMITTED', committed_at = now() where id = v_res.id;
    v_count := v_count + 1;
  end loop;
  return v_count;
end;

_convert_store_carts.src:
declare
  v_count int;
begin
  update public.store_carts set status = 'CONVERTED', order_id = p_order_id, converted_at = now(), updated_at = now(),
    recovered = item_count > 0 and last_activity_at < now() - public._abandoned_after()
  where status in ('ACTIVE', 'DISMISSED')
    and ((p_visitor_id is not null and p_visitor_id <> '' and visitor_id = p_visitor_id)
      or (p_phone is not null and phone = p_phone and last_activity_at > now() - interval '14 days'));
  get diagnostics v_count = row_count;
  return v_count;
end;

_courier_in_context.src:
declare
  v_merchant uuid := public.current_merchant_id();
begin
  if v_merchant is null then
    raise exception 'MERCHANT_REQUIRED: no merchant context for this courier' using errcode = '42501';
  end if;
  if not exists (select 1 from public.couriers where id = p_courier_id and merchant_id = v_merchant) then
    raise exception 'NOT_FOUND: courier not found' using errcode = 'P0002';
  end if;
  return v_merchant;
end;

_create_order.src:
declare
  v_existing public.orders;
  v_customer public.customers;
  v_phone text := public.clean_phone(p_payload #>> '{customer,phone}');
  v_name text := trim(coalesce(p_payload #>> '{customer,full_name}', ''));
  v_email text := nullif(lower(trim(coalesce(p_payload #>> '{customer,email}', ''))), '');
  v_address text := trim(coalesce(p_payload #>> '{shipping,address}', ''));
  v_district text := trim(coalesce(p_payload #>> '{shipping,district}', ''));
  v_area text := nullif(trim(coalesce(p_payload #>> '{shipping,area}', '')), '');
  v_city text := nullif(trim(coalesce(p_payload #>> '{shipping,city}', '')), '');
  v_postal text := nullif(trim(coalesce(p_payload #>> '{shipping,postal_code}', '')), '');
  v_auth uuid := nullif(p_payload ->> 'auth_user_id', '')::uuid;
  v_is_admin boolean := p_source <> 'STOREFRONT';
  v_quote jsonb;
  v_order public.orders;
  v_line jsonb;
  v_item public.order_items;
  v_coupon_id uuid;
  v_coupon public.coupons;
  v_pattern text := public.setting_text('store', array['phone_pattern'], '^01[3-9][0-9]{8}$');
  v_delivery_override numeric := nullif(p_payload ->> 'delivery_charge', '')::numeric;
  v_manual_discount numeric := coalesce(nullif(p_payload ->> 'manual_discount', '')::numeric, 0);
  v_payment_method public.payment_method := coalesce(nullif(p_payload ->> 'payment_method', ''), 'COD')::public.payment_method;
  -- An order imported from the merchant's own store (channel_ingest_order) is taken as the store sent it.
  v_store_import boolean := p_source = 'API' and coalesce(current_setting('app.store_order_import', true), '') = 'on'
    and public.is_system_context();
begin
  -- Idempotent checkout: the same key always returns the same order.
  if nullif(p_payload ->> 'idempotency_key', '') is not null then
    select * into v_existing from public.orders where idempotency_key = p_payload ->> 'idempotency_key';
    if found then
      return v_existing;
    end if;
  end if;

  if length(v_name) < 2 then
    raise exception 'VALIDATION: customer name is required' using errcode = '22023';
  end if;
  if v_phone is null or v_phone !~ v_pattern then
    raise exception 'VALIDATION: enter a valid mobile number' using errcode = '22023';
  end if;
  if v_email is not null and v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then
    raise exception 'VALIDATION: enter a valid email address' using errcode = '22023';
  end if;
  if length(v_address) < 5 and not v_store_import then
    raise exception 'VALIDATION: delivery address is required' using errcode = '22023';
  end if;
  if v_district = '' and not v_store_import then
    raise exception 'VALIDATION: district is required' using errcode = '22023';
  end if;
  if v_manual_discount < 0 or (v_delivery_override is not null and v_delivery_override < 0) then
    raise exception 'VALIDATION: amounts cannot be negative' using errcode = '22023';
  end if;
  if not v_is_admin and v_payment_method = 'COD' and not public.setting_bool('payments', array['cod_enabled'], true) then
    raise exception 'VALIDATION: cash on delivery is not available' using errcode = '22023';
  end if;

  -- Customer (one record per phone number).
  select * into v_customer from public.customers where phone = v_phone for update;
  if not found then
    insert into public.customers(full_name, phone, email, address, area, city, district, auth_user_id)
    values (v_name, v_phone, v_email, nullif(v_address, ''), v_area, v_city, nullif(v_district, ''),
            case when v_auth is not null and not exists (select 1 from public.customers where auth_user_id = v_auth)
                 then v_auth end)
    returning * into v_customer;
  else
    if v_customer.status = 'BLOCKED' and not v_is_admin then
      raise exception 'ORDER_BLOCKED: this order cannot be placed online' using errcode = 'P0001';
    end if;
    update public.customers set
      email = coalesce(email, v_email),
      address = coalesce(nullif(v_address, ''), address), area = v_area, city = v_city, district = coalesce(nullif(v_district, ''), district)
    where id = v_customer.id
    returning * into v_customer;
  end if;

  -- Server-side pricing.
  v_quote := public.calculate_order_quote(
    p_payload -> 'items', v_district, v_area, coalesce(p_payload ->> 'delivery_method', 'standard'),
    p_payload ->> 'coupon_code', v_phone, v_is_admin,
    v_is_admin and public.has_permission('orders.price_override') or (v_is_admin and public.is_system_context()));

  if nullif(trim(coalesce(p_payload ->> 'coupon_code', '')), '') is not null then
    if not coalesce((v_quote #>> '{coupon,valid}')::boolean, false) then
      raise exception 'COUPON_INVALID: %', coalesce(v_quote #>> '{coupon,message}', 'coupon is not valid')
        using errcode = 'P0001';
    end if;
    v_coupon_id := (v_quote #>> '{coupon,coupon_id}')::uuid;
    -- Serialize concurrent use of a limited coupon.
    select * into v_coupon from public.coupons where id = v_coupon_id for update;
    if v_coupon.usage_limit is not null and v_coupon.usage_count >= v_coupon.usage_limit then
      raise exception 'COUPON_INVALID: this coupon has reached its usage limit' using errcode = 'P0001';
    end if;
  end if;

  insert into public.orders(
    order_number, customer_id, auth_user_id, source, status, payment_method,
    customer_name, customer_phone, customer_email,
    shipping_address, shipping_area, shipping_city, shipping_district, shipping_postal_code,
    delivery_zone_id, delivery_method, coupon_id, coupon_code, manual_discount,
    delivery_charge, delivery_discount, return_charge,
    customer_note, idempotency_key, utm_source, utm_medium, utm_campaign, created_by
  ) values (
    public.next_order_number(), v_customer.id, v_auth, p_source, 'PENDING', v_payment_method,
    v_name, v_phone, v_email,
    v_address, v_area, v_city, v_district, v_postal,
    (v_quote #>> '{delivery_zone,id}')::uuid, v_quote ->> 'delivery_method', v_coupon_id,
    case when v_coupon_id is not null then upper(v_quote #>> '{coupon,code}') end,
    case when v_is_admin then v_manual_discount else 0 end,
    case when v_is_admin and v_delivery_override is not null then v_delivery_override
         else (v_quote ->> 'delivery_charge')::numeric end,
    case when v_is_admin and v_delivery_override is not null then 0
         else (v_quote ->> 'delivery_discount')::numeric end,
    (v_quote ->> 'return_charge')::numeric,
    nullif(trim(coalesce(p_payload ->> 'customer_note', '')), ''),
    nullif(p_payload ->> 'idempotency_key', ''),
    nullif(p_payload #>> '{utm,source}', ''), nullif(p_payload #>> '{utm,medium}', ''),
    nullif(p_payload #>> '{utm,campaign}', ''),
    case when v_is_admin then auth.uid() end
  ) returning * into v_order;

  for v_line in select * from jsonb_array_elements(v_quote -> 'lines') loop
    insert into public.order_items(
      order_id, product_id, variant_id, product_name, variant_title, sku, image_url, unit_price, unit_cost,
      quantity, line_subtotal, discount_amount, line_total, track_inventory, requires_production
    ) values (
      v_order.id, (v_line ->> 'product_id')::uuid, (v_line ->> 'variant_id')::uuid, v_line ->> 'product_name',
      nullif(v_line ->> 'variant_title', 'Default'), v_line ->> 'sku', v_line ->> 'image_url',
      (v_line ->> 'unit_price')::numeric, (v_line ->> 'unit_cost')::numeric, (v_line ->> 'quantity')::int,
      (v_line ->> 'line_subtotal')::numeric, (v_line ->> 'discount_amount')::numeric,
      (v_line ->> 'line_total')::numeric, (v_line ->> 'track_inventory')::boolean,
      (v_line ->> 'requires_production')::boolean
    ) returning * into v_item;
    perform public._reserve_order_item(v_item, v_order.order_number);
  end loop;

  if v_coupon_id is not null then
    insert into public.coupon_usage(coupon_id, order_id, customer_id, phone, discount_amount)
    values (v_coupon_id, v_order.id, v_customer.id, v_phone, (v_quote ->> 'coupon_discount')::numeric);
    update public.coupons set usage_count = usage_count + 1 where id = v_coupon_id;
  end if;

  -- Remember the address for the customer's next order.
  if v_district <> '' and length(v_address) >= 5 and not exists (select 1 from public.customer_addresses
                 where customer_id = v_customer.id and lower(address_line) = lower(v_address)
                   and lower(district) = lower(v_district)) then
    insert into public.customer_addresses(customer_id, recipient_name, phone, address_line, area, city,
                                          district, postal_code, is_default)
    values (v_customer.id, v_name, v_phone, v_address, v_area, v_city, v_district, v_postal,
            not exists (select 1 from public.customer_addresses where customer_id = v_customer.id and is_default));
  end if;

  v_order := public.recalculate_order_totals(v_order.id);

  perform public._order_log(v_order.id, 'CREATED',
    case p_source when 'STOREFRONT' then 'Order placed on the storefront' else 'Order created by staff' end,
    null, 'PENDING', jsonb_build_object('source', p_source, 'total', v_order.total_amount), true);
  perform public._order_log(v_order.id, 'STOCK_RESERVED', 'Stock reserved for all tracked items');

  if nullif(trim(coalesce(p_payload ->> 'internal_note', '')), '') is not null then
    insert into public.order_notes(order_id, kind, visibility, body, created_by, created_by_name)
    values (v_order.id, 'NOTE', 'INTERNAL', trim(p_payload ->> 'internal_note'), auth.uid(), public.actor_display_name());
  end if;

  perform public.refresh_customer_stats(v_customer.id);
  perform public._enqueue_order_notification(v_order.id, 'ORDER_CREATED');
  return v_order;
end;

_credit_expire.src:
declare
  l public.credit_lots;
  v_bal int;
  v_entry bigint;
  v_n int := 0;
begin
  for l in select * from public.credit_lots
           where merchant_id = p_merchant and credit_type = p_type and remaining > 0 and expires_at <= now()
           order by id for update loop
    select balance into v_bal from public.credit_balances where merchant_id = p_merchant and credit_type = p_type;
    insert into public.credit_ledger (merchant_id, credit_type, kind, amount, balance_after, reason, actor_kind, reference_type, reference_id, idempotency_key)
    values (p_merchant, p_type, 'EXPIRY', -l.remaining, greatest(v_bal - l.remaining, 0), 'Credits expired', 'SYSTEM', 'credit_lot', l.id::text, 'expiry:' || l.id)
    on conflict (merchant_id, idempotency_key) do nothing
    returning id into v_entry;
    if v_entry is not null then
      insert into public.credit_lot_usage (merchant_id, entry_id, lot_id, amount) values (p_merchant, v_entry, l.id, l.remaining);
      update public.credit_balances set balance = greatest(balance - l.remaining, 0), updated_at = now() where merchant_id = p_merchant and credit_type = p_type;
      v_n := v_n + 1;
    end if;
    update public.credit_lots set remaining = 0 where id = l.id;
  end loop;
  return v_n;
end;

_credit_post.src:
declare
  e public.credit_ledger;
  v_bal int;
  v_need int;
  v_take int;
  l public.credit_lots;
  u record;
  v_restored int := 0;
begin
  if p_amount is null or p_amount = 0 then
    raise exception 'VALIDATION: the amount cannot be zero' using errcode = '22023';
  end if;
  if coalesce(p_key, '') = '' then
    raise exception 'VALIDATION: an idempotency key is required' using errcode = '22023';
  end if;
  select * into e from public.credit_ledger where merchant_id = p_merchant and idempotency_key = p_key;
  if e.id is not null then
    return e;
  end if;
  insert into public.credit_balances (merchant_id, credit_type) values (p_merchant, p_type) on conflict do nothing;
  perform 1 from public.credit_balances where merchant_id = p_merchant and credit_type = p_type for update;
  -- A concurrent duplicate may have finished while we waited for the lock.
  select * into e from public.credit_ledger where merchant_id = p_merchant and idempotency_key = p_key;
  if e.id is not null then
    return e;
  end if;
  perform public._credit_expire(p_merchant, p_type);
  select balance into v_bal from public.credit_balances where merchant_id = p_merchant and credit_type = p_type;

  if p_amount < 0 then
    if v_bal + p_amount < 0 then
      raise exception 'INSUFFICIENT_CREDITS: % % available, % needed', v_bal, (select name from public.credit_types where code = p_type), -p_amount
        using errcode = 'P0001';
    end if;
    insert into public.credit_ledger (merchant_id, credit_type, kind, amount, balance_after, reason, actor_id, actor_kind, reference_type, reference_id,
      idempotency_key, metadata)
    values (p_merchant, p_type, p_kind, p_amount, v_bal + p_amount, p_reason, p_actor, p_actor_kind, p_ref_type, p_ref_id, p_key, coalesce(p_metadata, '{}'::jsonb))
    returning * into e;
    v_need := -p_amount;
    for l in select * from public.credit_lots
             where merchant_id = p_merchant and credit_type = p_type and remaining > 0 and (expires_at is null or expires_at > now())
             order by expires_at nulls last, id for update loop
      v_take := least(l.remaining, v_need);
      update public.credit_lots set remaining = remaining - v_take where id = l.id;
      insert into public.credit_lot_usage (merchant_id, entry_id, lot_id, amount) values (p_merchant, e.id, l.id, v_take);
      v_need := v_need - v_take;
      exit when v_need = 0;
    end loop;
    if v_need > 0 then
      raise exception 'credits: balance and lots disagree for % %', p_merchant, p_type;
    end if;
  else
    insert into public.credit_ledger (merchant_id, credit_type, kind, amount, balance_after, reason, actor_id, actor_kind, reference_type, reference_id,
      idempotency_key, expires_at, metadata)
    values (p_merchant, p_type, p_kind, p_amount, v_bal + p_amount, p_reason, p_actor, p_actor_kind, p_ref_type, p_ref_id, p_key, p_expires_at,
            coalesce(p_metadata, '{}'::jsonb))
    returning * into e;
    if p_kind = 'REFUND' and (p_metadata ->> 'refund_of') is not null then
      for u in select lu.lot_id, lu.amount from public.credit_lot_usage lu where lu.entry_id = (p_metadata ->> 'refund_of')::bigint order by lu.lot_id loop
        exit when v_restored >= p_amount;
        update public.credit_lots set remaining = remaining + least(u.amount, p_amount - v_restored) where id = u.lot_id;
        v_restored := v_restored + least(u.amount, p_amount - v_restored);
      end loop;
    end if;
    if v_restored < p_amount then
      insert into public.credit_lots (merchant_id, credit_type, entry_id, granted, remaining, expires_at)
      values (p_merchant, p_type, e.id, p_amount - v_restored, p_amount - v_restored, p_expires_at);
    end if;
  end if;
  update public.credit_balances set balance = e.balance_after, updated_at = now() where merchant_id = p_merchant and credit_type = p_type;
  -- Restored credits whose lot has expired meanwhile are written off straight away.
  if v_restored > 0 then
    perform public._credit_expire(p_merchant, p_type);
  end if;
  return e;
end;

_cron_health.src:
declare
  v_cron jsonb;
begin
  if to_regclass('cron.job_run_details') is null then
    return null;
  end if;
  execute $q$
    select jsonb_build_object(
      'failed', count(*) filter (where status = 'failed'), 'runs', count(*), 'last', max(end_time),
      'latest_failed', (select count(*) from (select distinct on (jobid) status from cron.job_run_details
                                               where start_time > now() - interval '24 hours' order by jobid, start_time desc) x
                        where x.status = 'failed'))
    from cron.job_run_details where start_time > now() - interval '24 hours'
  $q$ into v_cron;
  return v_cron;
end;

_effective_order_id.src:
declare
  v_id uuid := p_order_id;
  v_next uuid;
  i int := 0;
begin
  loop
    select merged_into into v_next from public.orders where id = v_id;
    exit when v_next is null or i > 5;
    v_id := v_next;
    i := i + 1;
  end loop;
  return v_id;
end;

_enqueue_order_notification.src:
begin
  if p_event = 'ADVANCE_RECEIVED' then
    return 0;
  end if;
  return public._enqueue_order_notification(p_order_id, p_event, null, null);
end;

declare
  v_order public.orders;
  v_tpl public.notifications;
  v_ship record;
  v_vars jsonb;
  v_ch_vars jsonb;
  v_facts jsonb;
  v_prefix text;
  v_symbol text;
  v_sms_prefix text;
  v_rate numeric;
  v_recipient text;
  v_body text;
  v_parts record;
  v_key text;
  v_count int := 0;
  v_payment numeric;
begin
  if not exists (select 1 from public.notifications where event = p_event and is_enabled) then
    return 0;
  end if;

  begin
    if not public.setting_bool('notifications', array['enabled'], true) then
      return 0;
    end if;
    v_symbol := public.setting_text('store', array['currency_symbol'], '৳');
    v_sms_prefix := nullif(trim(public.setting_text('sms', array['currency_text'], 'Tk')), '');
    v_rate := greatest(public.setting_numeric('sms', array['cost_per_sms'], 0.35), 0);
    v_payment := nullif(p_extra ->> 'payment_amount', '')::numeric;
    select * into v_order from public.orders where id = p_order_id;
    if not found then
      return 0;
    end if;
    select s.id, s.courier_id, s.tracking_number, c.name as courier_name,
           case when c.tracking_url_template is not null and s.tracking_number is not null
                then replace(c.tracking_url_template, '{tracking}', s.tracking_number) end as tracking_url
    into v_ship
    from public.shipments s join public.couriers c on c.id = s.courier_id
    where s.order_id = p_order_id and s.is_active
    order by s.created_at desc limit 1;

    v_vars := jsonb_build_object(
      'store_name', public.setting_text('store', array['name'], 'Our store'),
      'store_phone', public.setting_text('store', array['phone'], ''),
      'order_number', v_order.order_number,
      'customer_name', v_order.customer_name,
      'customer_first_name', split_part(trim(v_order.customer_name), ' ', 1),
      'tracking_number', coalesce(v_ship.tracking_number, ''),
      'courier_name', coalesce(v_ship.courier_name, ''),
      'tracking_url', coalesce(v_ship.tracking_url, ''),
      'track_order_url', public.setting_text('store', array['website_url'], '') || '/track-order?order=' || v_order.order_number
    );
    v_facts := jsonb_build_object(
      'payment_method', v_order.payment_method,
      'total', v_order.total_amount,
      'district', v_order.shipping_district,
      'source', v_order.source,
      'courier', v_ship.courier_id,
      'first_order', not exists (select 1 from public.orders o
                                 where o.customer_id = v_order.customer_id and o.id <> v_order.id
                                   and o.created_at < v_order.created_at)
    );

    for v_tpl in select * from public.notifications where event = p_event and is_enabled order by created_at, id loop
      if v_tpl.channel = 'SMS' then
        if not public.setting_bool('sms', array['enabled'], false) or not public.feature_enabled('sms') then
          continue;
        end if;
      elsif not public.setting_bool('notifications', array['channels', lower(v_tpl.channel::text), 'enabled'], false) then
        continue;
      end if;
      if not public._notification_conditions_match(v_tpl.conditions, v_facts) then
        continue;
      end if;

      -- SMS amounts use plain text ("Tk 1,250") so messages stay in the cheaper GSM encoding.
      v_prefix := case when v_tpl.channel = 'SMS' then coalesce(v_sms_prefix || ' ', '') else v_symbol end;
      v_ch_vars := v_vars || jsonb_build_object(
        'total', public._fmt_amount(v_order.total_amount, v_prefix),
        'cod_amount', public._fmt_amount(v_order.cod_amount, v_prefix),
        'due_amount', public._fmt_amount(greatest(v_order.total_amount - v_order.amount_paid, 0), v_prefix),
        'advance_amount', public._fmt_amount(greatest(v_order.advance_required - v_order.amount_paid, 0), v_prefix),
        'payment_amount', case when v_payment is null then '' else public._fmt_amount(v_payment, v_prefix) end
      );
      v_body := public.render_template(v_tpl.template, v_ch_vars);
      v_key := v_tpl.id || ':' || p_order_id || ':' || coalesce(p_ref, p_event::text);
      v_recipient := case v_tpl.channel when 'EMAIL' then v_order.customer_email
                                        when 'SMS' then public.sms_phone(v_order.customer_phone)
                                        else v_order.customer_phone end;

      if v_tpl.channel = 'SMS' then
        select * into v_parts from public.sms_parts(v_body);
        if v_recipient is null then
          insert into public.notification_logs(notification_id, event, channel, recipient, body, order_id, customer_id,
            status, error, dedupe_key, segments, encoding, provider)
          values (v_tpl.id, p_event, 'SMS', coalesce(nullif(v_order.customer_phone, ''), '—'), v_body, p_order_id,
            v_order.customer_id, 'SKIPPED', 'Not a Bangladesh mobile number', v_key, v_parts.segments, v_parts.encoding,
            public._platform_sms_provider())
          on conflict (merchant_id, dedupe_key) do nothing;
          continue;
        end if;
        insert into public.notification_logs(notification_id, event, channel, recipient, body, order_id, customer_id,
          dedupe_key, segments, encoding, cost, cost_source, provider)
        values (v_tpl.id, p_event, 'SMS', v_recipient, v_body, p_order_id, v_order.customer_id, v_key,
          v_parts.segments, v_parts.encoding, round(v_parts.segments * v_rate, 4), 'ESTIMATE',
          public._platform_sms_provider())
        on conflict (merchant_id, dedupe_key) do nothing;
      else
        if v_recipient is null then
          continue;
        end if;
        insert into public.notification_logs(notification_id, event, channel, recipient, subject, body, order_id,
          customer_id, dedupe_key, provider)
        values (v_tpl.id, p_event, v_tpl.channel, v_recipient, public.render_template(v_tpl.subject, v_ch_vars), v_body,
          p_order_id, v_order.customer_id, v_key,
          public.setting_text('notifications', array['channels', lower(v_tpl.channel::text), 'provider'], 'console'))
        on conflict (merchant_id, dedupe_key) do nothing;
      end if;
      if found then
        v_count := v_count + 1;
      end if;
    end loop;
  exception when others then
    -- A broken template or setting must never stop the order change itself.
    perform public._log_system_event('ERROR', 'SMS', '_enqueue_order_notification',
      format('Could not queue the %s message for an order: %s', public.notification_event_label(p_event), sqlerrm),
      jsonb_build_object('order_id', p_order_id, 'event', p_event, 'sqlstate', sqlstate));
    return 0;
  end;
  return v_count;
end;

