_find_merge_target.src:
declare
  v_target public.orders;
  v_phone text := public.clean_phone(p_payload #>> '{customer,phone}');
  v_check public.fraud_checks;
  v_quote jsonb;
  v_eval jsonb;
  v_fraud_enabled boolean := public.setting_bool('fraud', array['enabled'], true);
begin
  if not public.setting_bool('orders', array['auto_merge_enabled'], true)
     or v_phone is null
     or nullif(trim(coalesce(p_payload ->> 'coupon_code', '')), '') is not null then
    return null;
  end if;

  select o.* into v_target
  from public.orders o
  join public.customers c on c.id = o.customer_id
  where o.customer_phone = v_phone
    and o.source = 'STOREFRONT'
    and o.merged_into is null
    and c.status <> 'BLOCKED'
    and o.created_at >= now() - make_interval(mins => public.setting_numeric('orders', array['auto_merge_minutes'], 3)::int)
    and o.confirmed_at is null
    and o.status in ('PENDING', 'FRAUD_CHECK', 'ADVANCE_REQUIRED', 'FRAUD_REVIEW', 'CONFIRMATION_REQUIRED')
    and o.payment_method = coalesce(nullif(p_payload ->> 'payment_method', ''), 'COD')::public.payment_method
    and o.delivery_method = coalesce(nullif(p_payload ->> 'delivery_method', ''), 'standard')
    and lower(o.shipping_district) = lower(trim(coalesce(p_payload #>> '{shipping,district}', '')))
    and public.normalize_address(o.shipping_address) = public.normalize_address(p_payload #>> '{shipping,address}')
    and o.label_printed_at is null
    and not exists (select 1 from public.shipments s where s.order_id = o.id and s.is_active)
  order by o.created_at desc
  limit 1
  for update of o;
  if not found then
    return null;
  end if;

  -- The merged order must not deserve a stricter decision than it already got.
  if v_fraud_enabled then
    select * into v_check from public.fraud_checks where id = p_fraud_check_id;
    if not found then
      return null;
    end if;
    v_quote := public.calculate_order_quote(p_payload -> 'items', v_target.shipping_district, v_target.shipping_area,
      v_target.delivery_method, null, v_phone, false, false);
    v_eval := public.evaluate_fraud_rules(v_check.metrics, jsonb_build_object(
      'order_value', v_target.total_amount + coalesce((v_quote ->> 'subtotal')::numeric, 0),
      'subtotal', v_target.subtotal + coalesce((v_quote ->> 'subtotal')::numeric, 0),
      'delivery_charge', v_target.delivery_charge, 'return_charge', v_target.return_charge,
      'district', v_target.shipping_district, 'area', v_target.shipping_area,
      'payment_method', v_target.payment_method, 'source', v_target.source));
    if public.decision_severity((v_eval ->> 'decision')::public.fraud_decision)
         > public.decision_severity(coalesce(v_target.fraud_decision, 'ALLOW'))
       or coalesce((v_eval ->> 'advance_amount')::numeric, 0) > v_target.advance_required then
      return null;
    end if;
  end if;
  return v_target;
end;

_flag_possible_duplicate.src:
declare
  v_order public.orders;
  v_dup public.orders;
  v_reason text;
  v_kind text;
begin
  if not public.setting_bool('orders', array['duplicate_check_enabled'], true) then
    return null;
  end if;
  select * into v_order from public.orders where id = p_order_id;
  if not found or v_order.status in ('CANCELLED', 'REJECTED_FRAUD') or v_order.merged_into is not null then
    return null;
  end if;

  -- Already in Approved Orders and not finished yet.
  select d.* into v_dup from public.orders d
  where d.customer_phone = v_order.customer_phone and d.id <> v_order.id
    and d.confirmed_at is not null and d.merged_into is null
    and d.status in ('CONFIRMED', 'PRE_ORDER', 'PROCESSING', 'PRODUCTION', 'QUALITY_CHECK', 'PACKING', 'READY_TO_SHIP', 'SHIPPED')
  order by d.created_at desc limit 1;
  if found then
    v_kind := 'APPROVED';
    v_reason := format('already in Approved Orders (%s)', v_dup.status);
  else
    select d.* into v_dup from public.orders d
    where d.id <> v_order.id
      and d.created_at <= v_order.created_at
      and d.created_at >= v_order.created_at
          - make_interval(hours => public.setting_numeric('orders', array['duplicate_window_hours'], 24)::int)
      and d.status not in ('CANCELLED', 'REJECTED_FRAUD', 'DELIVERED', 'PARTIALLY_DELIVERED', 'RETURN_REQUESTED',
                           'RETURNING', 'RETURNED', 'FAILED_DELIVERY', 'LOST')
      and d.merged_into is null
      and (d.customer_phone = v_order.customer_phone
           or (public.normalize_address(d.shipping_address) = public.normalize_address(v_order.shipping_address)
               and lower(d.shipping_district) = lower(v_order.shipping_district)))
    order by d.created_at desc limit 1;
    if not found then
      return null;
    end if;
    v_kind := case when v_dup.customer_phone = v_order.customer_phone then 'PHONE' else 'ADDRESS' end;
    v_reason := case when v_kind = 'PHONE' then 'same phone number' else 'same delivery address' end;
  end if;

  update public.orders set duplicate_of = v_dup.id, duplicate_status = 'SUSPECTED', duplicate_reason = v_kind where id = v_order.id;
  perform public._order_log(v_order.id, 'DUPLICATE_SUSPECTED',
    format('Possible duplicate of %s (%s)', v_dup.order_number, v_reason), null, null,
    jsonb_build_object('duplicate_of', v_dup.id, 'order_number', v_dup.order_number, 'reason', v_reason, 'kind', v_kind));
  perform public._order_log(v_dup.id, 'DUPLICATE_SUSPECTED',
    format('%s may be a duplicate of this order (%s)', v_order.order_number, v_reason), null, null,
    jsonb_build_object('duplicate', v_order.id, 'order_number', v_order.order_number, 'reason', v_reason, 'kind', v_kind));
  return v_dup.id;
end;

_hr_score.src:
declare
  v_start timestamptz;
  v_late int := 0;
  v_worked int;
  v_half int := coalesce((public.get_setting('hr') ->> 'half_day_minutes')::int, 240);
begin
  if p_in is not null and p_shift.id is not null then
    select b.starts_at into v_start from public._hr_shift_bounds(p_shift, p_date) b;
    if p_in > v_start + make_interval(mins => p_shift.grace_minutes) then
      v_late := floor(extract(epoch from p_in - v_start) / 60)::int;
    end if;
  end if;
  if p_in is not null and p_out is not null then
    v_worked := floor(extract(epoch from p_out - p_in) / 60)::int;
  end if;
  return query select
    (case when p_in is null then 'ABSENT'
          when v_worked is not null and v_worked < v_half then 'HALF_DAY'
          when v_late > 0 then 'LATE'
          else 'PRESENT' end)::public.hr_attendance_status,
    v_late, v_worked;
end;

_inventory_channel_trigger.src:
declare
  v_m record;
begin
  if new.available is not distinct from old.available then
    return new;
  end if;
  for v_m in
    select m.channel_id, m.variant_id from public.sales_channel_variants m
    join public.sales_channels c on c.id = m.channel_id
    where m.variant_id = new.variant_id and m.inventory_item_id is not null and c.status = 'CONNECTED'
      and public._channel_opt(c, 'inventory_sync', false) and nullif(c.settings ->> 'location_id', '') is not null
  loop
    update public.sales_channel_variants set sync_status = 'PENDING'
    where channel_id = v_m.channel_id and variant_id = v_m.variant_id and sync_status in ('OK', 'NEW', 'FAILED');
    perform public.channel_job_enqueue(v_m.channel_id, 'INVENTORY', v_m.variant_id);
  end loop;
  return new;
end;

_jnum.src:
declare
  v text := nullif(trim(p ->> p_key), '');
begin
  if v is null then
    return null;
  end if;
  return round(v::numeric, 2);
exception when others then
  raise exception 'VALIDATION: line %: % is not a number (%)', p_line, replace(p_key, '_', ' '), left(v, 30) using errcode = '22023';
