_merge_checkout_into.src:
declare
  v_target public.orders;
  v_quote jsonb;
  v_qty int;
  v_before numeric;
  v_note text := nullif(trim(coalesce(p_payload ->> 'customer_note', '')), '');
begin
  select * into v_target from public.orders where id = p_target_id for update;
  v_before := v_target.total_amount;
  v_quote := public.calculate_order_quote(p_payload -> 'items', v_target.shipping_district, v_target.shipping_area,
    v_target.delivery_method, null, v_target.customer_phone, false, false);
  v_qty := public._add_order_lines(v_target, v_quote -> 'lines');

  update public.orders set
    merged_count = merged_count + 1,
    customer_note = case when v_note is null then customer_note else concat_ws(E'\n', customer_note, v_note) end
  where id = p_target_id;
  v_target := public.recalculate_order_totals(p_target_id);

  insert into public.order_merges(order_id, kind, idempotency_key, items, amount)
  values (p_target_id, 'AUTO', nullif(p_payload ->> 'idempotency_key', ''), v_quote -> 'lines',
          v_target.total_amount - v_before);

  perform public._order_log(p_target_id, 'ORDER_MERGED',
    format('Customer checked out again within %s min — %s item(s) added to this order',
      public.setting_numeric('orders', array['auto_merge_minutes'], 3), v_qty),
    null, null, jsonb_build_object('added_items', v_quote -> 'lines', 'added_amount', v_target.total_amount - v_before,
      'idempotency_key', p_payload ->> 'idempotency_key'), true);
  perform public.log_audit('order.auto_merged', 'order', p_target_id::text,
    jsonb_build_object('total', v_before), jsonb_build_object('total', v_target.total_amount),
    jsonb_build_object('order_number', v_target.order_number, 'added_items', v_qty));
  perform public.refresh_customer_stats(v_target.customer_id);
  return v_target;
end;

_merge_line_into.src:
declare
  v_item public.order_items;
  v_qty int := (p_line ->> 'quantity')::int;
  v_inv public.inventory;
begin
  select * into v_item from public.order_items
  where order_id = p_order.id and variant_id = (p_line ->> 'variant_id')::uuid
    and unit_price = (p_line ->> 'unit_price')::numeric and returned_quantity = 0
  order by created_at limit 1 for update;
  if not found then
    return public._add_order_lines(p_order, jsonb_build_array(p_line));
  end if;
  if v_item.track_inventory then
    select * into v_inv from public.inventory where variant_id = v_item.variant_id for update;
    if v_inv.available < v_qty and not public.allow_overselling() then
      raise exception 'INSUFFICIENT_STOCK: % has only % available', v_item.product_name, greatest(v_inv.available, 0) using errcode = 'P0001';
    end if;
    perform public._apply_inventory_movement(v_item.variant_id, 'RESERVATION', 0, v_qty, 0,
      'ORDER', p_order.id, p_order.order_number, 'Reserved for order (merged)', null, true);
    insert into public.stock_reservations(order_id, order_item_id, variant_id, quantity)
    values (p_order.id, v_item.id, v_item.variant_id, v_qty);
  end if;
  update public.order_items set quantity = quantity + v_qty, line_subtotal = line_subtotal + public.money(v_item.unit_price * v_qty),
    line_total = line_total + public.money(v_item.unit_price * v_qty)
  where id = v_item.id;
  return v_qty;
end;

_merge_web_orders.src:
declare
  v_target public.orders;
  v_source public.orders;
  v_line jsonb;
  v_lines jsonb;
  v_before numeric;
  v_qty int := 0;
  v_priority jsonb := coalesce(public.get_setting('orders') -> 'merge_review_priority', '["PROCESSING","FOLLOW_UP","GOOD_NO_RESPONSE","NO_RESPONSE"]'::jsonb);
  v_result text;
  v_note text;
  v_review_before text;
begin
  select * into v_target from public.orders where id = p_target_id;
  v_review_before := v_target.review_status;
  select * into v_source from public.orders where id = p_source_id;
  select coalesce(jsonb_agg(jsonb_build_object(
      'product_id', product_id, 'variant_id', variant_id, 'product_name', product_name,
      'variant_title', coalesce(variant_title, 'Default'), 'sku', sku, 'image_url', image_url,
      'unit_price', unit_price, 'unit_cost', unit_cost, 'quantity', quantity, 'line_subtotal', line_subtotal,
      'track_inventory', track_inventory, 'requires_production', requires_production) order by created_at), '[]'::jsonb)
  into v_lines from public.order_items where order_id = v_source.id;

  v_before := v_target.total_amount;
  perform public._release_order_stock(v_source.id, format('Released: merged into %s', v_target.order_number));
  for v_line in select * from jsonb_array_elements(v_lines) loop
    v_qty := v_qty + public._merge_line_into(v_target, v_line);
  end loop;

  -- The better call status wins (by the configured priority).
  select x into v_result from jsonb_array_elements_text(v_priority) with ordinality as p(x, n)
  where x in (v_target.review_status, v_source.review_status) order by n limit 1;
  v_result := coalesce(v_result, v_target.review_status);

  v_note := case when public.normalize_address(v_source.shipping_address) is distinct from public.normalize_address(v_target.shipping_address)
      or lower(coalesce(v_source.shipping_district, '')) is distinct from lower(coalesce(v_target.shipping_district, ''))
    then format('Merged order %s had another address (%s); the first order''s address is used', v_source.order_number,
      coalesce(nullif(concat_ws(', ', nullif(trim(v_source.shipping_address), ''), nullif(v_source.shipping_district, '')), ''), 'none')) end;
  update public.orders set
    merged_count = merged_count + 1 + v_source.merged_count,
    tax_amount = coalesce(tax_amount, 0) + coalesce(v_source.tax_amount, 0),
    review_status = v_result,
    customer_note = case
      when v_source.customer_note is null and v_note is null then customer_note
      else concat_ws(E'\n', customer_note, v_source.customer_note, v_note) end
  where id = v_target.id;
  v_target := public.recalculate_order_totals(v_target.id);

  update public.orders set merged_into = v_target.id, duplicate_status = 'MERGED', review_status = 'DUPLICATE'
  where id = v_source.id;
  perform public._transition_order(v_source.id, 'CANCELLED', format('Merged into %s', v_target.order_number),
    jsonb_build_object('merged_into', v_target.id));
  -- One order, one set of messages: the merged order's queued messages are skipped.
  update public.notification_logs set status = 'SKIPPED', error = 'Order merged'
  where order_id = v_source.id and status = 'QUEUED';

  insert into public.order_merges(order_id, source_order_id, kind, idempotency_key, items, amount, created_by,
    source_status, source_review_status, target_review_before, target_review_after, reason)
  values (v_target.id, v_source.id, p_kind, v_source.idempotency_key, v_lines, v_target.total_amount - v_before, auth.uid(),
    v_source.status::text, v_source.review_status, v_review_before, v_result, p_reason);

  perform public._order_log(v_target.id, 'ORDER_MERGED',
    format('%s merged into this order automatically (%s item(s), %s)', v_source.order_number, v_qty, p_reason), null, null,
    jsonb_build_object('source_order_id', v_source.id, 'order_number', v_source.order_number, 'added_amount', v_target.total_amount - v_before,
      'source_review_status', v_source.review_status, 'review_status', v_result));
  perform public.log_audit('order.auto_merged', 'order', v_target.id::text,
    jsonb_build_object('total', v_before), jsonb_build_object('total', v_target.total_amount, 'review_status', v_result),
    jsonb_build_object('order_number', v_target.order_number, 'merged_order', v_source.order_number, 'reason', p_reason));
  perform public.refresh_customer_stats(v_target.customer_id);
  return v_target;
end;

_meta_settle_payments.src:
declare
  v_acc public.meta_ad_accounts;
  v_today date := public._local_date(now());
  v_day record;
  v_count int := 0;
begin
  select * into v_acc from public.meta_ad_accounts where ad_account_id = regexp_replace(coalesce(p_account, ''), '^act_', '');
  if not found or v_acc.payment_account_id is null then
    return 0;
  end if;
  for v_day in
    select d::date as day,
           coalesce((select sum(i.cost) from public.meta_ad_insights i where i.account_id = v_acc.ad_account_id and i.date = d::date), 0) as cost,
           coalesce((select -sum(m.amount) from public.finance_account_movements m where m.meta_account_id = v_acc.id and m.spend_date = d::date), 0) as paid
    from generate_series(greatest(p_since, coalesce(v_acc.payments_from, p_since)), least(p_until, v_today - 1), interval '1 day') d
  loop
    continue when v_day.cost = v_day.paid;
    insert into public.finance_account_movements(account_id, amount, movement_date, description, source, source_key, meta_account_id, spend_date)
    values (v_acc.payment_account_id, -(v_day.cost - v_day.paid),
            case when v_day.paid = 0 then v_day.day + 1 else v_today end,
            left(case when v_day.paid = 0 then 'Meta Ads · ' || v_acc.name || ' · spend on ' || to_char(v_day.day, 'DD Mon YYYY')
                      else 'Meta Ads · ' || v_acc.name || ' · Meta revised ' || to_char(v_day.day, 'DD Mon YYYY') end, 300),
            'META_ADS', 'meta:' || v_acc.id || ':' || v_day.day || ':' || gen_random_uuid(), v_acc.id, v_day.day);
    v_count := v_count + 1;
  end loop;
  return v_count;
end;

_notification_conditions_match.src:
declare
  c jsonb;
  v_fact text;
  v_in boolean;
begin
  for c in select * from jsonb_array_elements(coalesce(p_conditions, '[]'::jsonb)) loop
    v_fact := p_facts ->> (c ->> 'field');
    if c ->> 'op' in ('in', 'not_in') then
      v_in := v_fact is not null and exists (
        select 1 from jsonb_array_elements_text(c -> 'value') x where lower(trim(x)) = lower(trim(v_fact)));
      if (c ->> 'op' = 'in') <> v_in then
        return false;
      end if;
    elsif c ->> 'op' = 'gte' then
      if v_fact is null or v_fact::numeric < (c ->> 'value')::numeric then
        return false;
      end if;
    elsif c ->> 'op' = 'lte' then
      if v_fact is null or v_fact::numeric > (c ->> 'value')::numeric then
        return false;
      end if;
    elsif c ->> 'op' = 'eq' then
      if v_fact is null or lower(v_fact) <> lower(c ->> 'value') then
        return false;
      end if;
    else
      return false;
    end if;
  end loop;
  return true;
end;

_order_advance_to.src:
declare
  v_status public.order_status;
begin
  select status into v_status from public.orders where id = p_order_id;
  if v_status = p_target then
    return;
  end if;
  if v_status = 'CONFIRMED' then
    perform public._transition_order(p_order_id, 'PROCESSING', 'Preparation started', '{}'::jsonb, false);
    v_status := 'PROCESSING';
  end if;
  if v_status = p_target then
    return;
  end if;
  if not exists (select 1 from public.order_status_transitions where from_status = v_status and to_status = p_target) then
    raise exception 'INVALID_TRANSITION: order is % and cannot move to %', v_status, p_target using errcode = 'P0001';
  end if;
  perform public._transition_order(p_order_id, p_target, p_note, '{}'::jsonb, false);
end;

_order_fee_charge.src:
declare
  v_t jsonb := public._order_fee_terms(p_merchant);
  v_fee numeric := (v_t ->> 'fee')::numeric;
  v_poisha int := round((v_t ->> 'fee')::numeric * 100)::int;
  v_balance int;
  e public.credit_ledger;
begin
  if not (v_t ->> 'enabled')::boolean then
    return;
  end if;
  perform pg_advisory_xact_lock(hashtextextended('order-fee:' || p_merchant, 0));
  if exists (select 1 from public.order_fee_charges where order_id = p_order) then
    return;
  end if;
  if (v_t ->> 'exempt')::boolean or (v_t ->> 'unmetered')::boolean then
    insert into public.order_fee_charges (merchant_id, order_id, order_number, fee, charge, approved_by)
    values (p_merchant, p_order, p_number, 0, 'EXEMPT', auth.uid());
    return;
  end if;
  if v_poisha <= 0 or (v_t ->> 'free_used')::int < (v_t ->> 'free_per_month')::int then
    insert into public.order_fee_charges (merchant_id, order_id, order_number, fee, charge, approved_by)
    values (p_merchant, p_order, p_number, 0, 'FREE', auth.uid());
    return;
  end if;
  v_balance := public.credit_available(p_merchant, 'BALANCE');
  if v_balance >= v_poisha then
    e := public._credit_post(p_merchant, 'BALANCE', -v_poisha, 'USAGE', format('Order %s approved', p_number), auth.uid(), 'SYSTEM',
      'order', p_order::text, 'order-fee:' || p_order, null, jsonb_build_object('fee_tk', v_fee));
    insert into public.order_fee_charges (merchant_id, order_id, order_number, fee, charge, ledger_entry_id, approved_by)
    values (p_merchant, p_order, p_number, v_fee, 'CHARGED', e.id, auth.uid());
  elsif v_t ->> 'on_empty' = 'ALLOW' then
    insert into public.order_fee_charges (merchant_id, order_id, order_number, fee, charge, approved_by)
    values (p_merchant, p_order, p_number, v_fee, 'UNPAID', auth.uid());
  else
    raise exception 'LIMIT_REACHED: approving an order costs % Tk and the balance is % Tk. Recharge the balance to keep approving orders',
      to_char(v_fee, 'FM999990.00'), to_char(v_balance / 100.0, 'FM9999999990.00') using errcode = 'P0001';
  end if;
end;

_order_fee_on_approve.src:
begin
