begin
  insert into public.platform_announcement_deliveries (announcement_id, merchant_id, status)
  select a.id, m.id,
    case when a.kind = any (public._announcement_optional_kinds())
          and a.kind in (select jsonb_array_elements_text(coalesce((select s.value -> 'muted' from public.settings s
                           where s.merchant_id = m.id and s.key = 'announcements'), '[]'::jsonb)))
         then 'MUTED' else 'DELIVERED' end
  from public._platform_announcement_audience(a.audience) m(id)
  on conflict do nothing;
  get diagnostics v_n = row_count;
  update public.platform_announcements set status = 'SENT', sent_at = now(),
    recipients = (select count(*) from public.platform_announcement_deliveries where announcement_id = a.id and status = 'DELIVERED')
  where id = a.id;
  return v_n;
end;

_platform_announcement_validate.src:
declare
  v_type text := upper(coalesce(p #>> '{audience,type}', 'ALL'));
begin
  if upper(coalesce(p ->> 'kind', '')) not in ('MAINTENANCE', 'FEATURE', 'SUBSCRIPTION', 'INTEGRATION', 'USAGE', 'RECHARGE', 'GENERAL') then
    raise exception 'VALIDATION: choose what kind of announcement it is' using errcode = '22023';
  end if;
  if upper(coalesce(p ->> 'severity', 'INFO')) not in ('INFO', 'WARN', 'CRITICAL') then
    raise exception 'VALIDATION: unknown importance' using errcode = '22023';
  end if;
  if length(trim(coalesce(p ->> 'title', ''))) < 3 or length(trim(coalesce(p ->> 'body', ''))) < 3 then
    raise exception 'VALIDATION: write a title and a message' using errcode = '22023';
  end if;
  if v_type not in ('ALL', 'PLANS', 'STATUSES', 'MERCHANTS') then
    raise exception 'VALIDATION: choose who gets it' using errcode = '22023';
  end if;
  if v_type <> 'ALL' and jsonb_array_length(coalesce(p -> 'audience' -> lower(v_type), '[]'::jsonb)) = 0 then
    raise exception 'VALIDATION: choose at least one %', lower(rtrim(v_type, 'S')) using errcode = '22023';
  end if;
  if nullif(p ->> 'link', '') is not null and p ->> 'link' !~ '^(/admin|https://)' then
    raise exception 'VALIDATION: links go to a page in the app (/admin/…) or an https:// address' using errcode = '22023';
  end if;
  return jsonb_build_object('type', v_type, 'plans', coalesce(p #> '{audience,plans}', '[]'::jsonb), 'statuses', coalesce(p #> '{audience,statuses}', '[]'::jsonb),
    'merchants', coalesce(p #> '{audience,merchants}', '[]'::jsonb), 'include_demo', coalesce((p #>> '{audience,include_demo}')::boolean, false));
end;

_platform_audit.src:
declare
  v_id bigint;
begin
  insert into public.platform_audit_logs (actor_id, actor_email, action, merchant_id, entity_type, entity_id, reason, before, after, metadata)
  values (auth.uid(), (select email from public.platform_staff where user_id = auth.uid()), p_action, p_merchant,
          p_entity_type, p_entity_id, p_reason, p_before, p_after, coalesce(p_metadata, '{}'::jsonb))
  returning id into v_id;
  return v_id;
end;

_platform_automation_act.src:
declare
  v_key text := s ->> 'subject_key';
  v_merchant uuid := nullif(s ->> 'merchant_id', '')::uuid;
  v_title text := s ->> 'title';
  v_detail text := s ->> 'detail';
  v_ref jsonb := coalesce(s -> 'ref', '{}'::jsonb);
  a jsonb;
  v_done jsonb := '[]'::jsonb;
  v_n int;
  v_link text := case when nullif(s ->> 'merchant_id', '') is not null then '/super-admin/merchants/' || (s ->> 'merchant_id') else '/super-admin/health' end;
  v_mgr uuid;
  t public.support_tickets;
  i public.platform_incidents;
  ann public.platform_announcements;
begin
  for a in select * from jsonb_array_elements(r.actions) loop
    case a ->> 'type'
      when 'notify_staff' then
        v_n := public._platform_notify(coalesce(a ->> 'module', 'health'), coalesce(a ->> 'action', 'view'), v_merchant, 'automation.' || r.trigger,
          coalesce(a ->> 'severity', 'WARN'), v_title, v_detail,
          case when v_ref ? 'ticket_id' then '/super-admin/support?ticket=' || (v_ref ->> 'ticket_id') else v_link end,
          format('auto:%s:%s:%s', r.id, v_key, p_run));
        v_done := v_done || jsonb_build_object('type', 'notify_staff', 'notified', v_n);
      when 'notify_account_manager' then
        select account_manager_id into v_mgr from public.merchants where id = v_merchant;
        v_n := case when v_mgr is null then 0 else public._platform_notify('merchants', 'view', v_merchant, 'automation.' || r.trigger, coalesce(a ->> 'severity', 'WARN'),
          v_title, v_detail, v_link, format('auto:%s:%s:%s:am', r.id, v_key, p_run), array[v_mgr]) end;
        v_done := v_done || jsonb_build_object('type', 'notify_account_manager', 'notified', v_n);
      when 'escalate_ticket' then
        select * into t from public.support_tickets where id = (v_ref ->> 'ticket_id')::uuid;
        if t.id is not null and t.status in ('OPEN', 'IN_PROGRESS') then
          t := public._platform_ticket_escalate(t, 'Overdue — escalated by the rule "' || r.name || '"', true);
          v_done := v_done || jsonb_build_object('type', 'escalate_ticket', 'level', t.escalation_level, 'priority', t.priority);
        end if;
      when 'create_incident' then
        i := public._platform_incident_open(jsonb_build_object('title', v_title, 'description', v_detail || E'\nOpened by the automation rule "' || r.name || '".',
               'severity', coalesce(a ->> 'severity', 'HIGH'), 'integration', case when v_key like 'service:%' then
                 case split_part(v_key, ':', 2) when 'pbx_gateway' then 'pbx' else split_part(v_key, ':', 2) end end,
               'scope', case when v_merchant is null then 'ALL' else 'SELECTED' end,
               'merchants', case when v_merchant is null then '[]'::jsonb else jsonb_build_array(v_merchant) end),
             'AUTOMATION', r.id, format('auto:%s:%s', r.id, v_key));
        v_done := v_done || jsonb_build_object('type', 'create_incident', 'incident', i.number);
      when 'notify_merchant' then
        if v_merchant is not null then
          insert into public.platform_announcements (kind, severity, title, body, link, audience, source, rule_id)
          values (coalesce(a ->> 'kind', case r.trigger when 'usage_limit' then 'USAGE' when 'payment_problems' then 'SUBSCRIPTION'
                    when 'onboarding_incomplete' then 'GENERAL' else 'INTEGRATION' end),
                  coalesce(a ->> 'severity', 'WARN'), left(coalesce(nullif(a ->> 'title', ''), v_title), 140),
                  left(coalesce(nullif(a ->> 'body', ''), v_detail, v_title), 4000), nullif(a ->> 'link', ''),
                  jsonb_build_object('type', 'MERCHANTS', 'merchants', jsonb_build_array(v_merchant), 'include_demo', true), 'AUTOMATION', r.id)
          returning * into ann;
          v_n := public._platform_announcement_deliver(ann);
          v_done := v_done || jsonb_build_object('type', 'notify_merchant', 'announcement', ann.number, 'delivered', v_n);
        end if;
      else
        raise exception 'unknown action %', a ->> 'type';
    end case;
  end loop;
  return v_done;
end;

_platform_automation_validate.src:
declare
  v_cat jsonb := public._platform_automation_catalog() -> (p ->> 'trigger');
  a jsonb;
  k text;
begin
  if v_cat is null then
    raise exception 'VALIDATION: choose what the rule watches' using errcode = '22023';
  end if;
  if length(trim(coalesce(p ->> 'name', ''))) < 3 then
    raise exception 'VALIDATION: give the rule a name' using errcode = '22023';
  end if;
  for k in select jsonb_object_keys(coalesce(p -> 'conditions', '{}'::jsonb)) loop
    if not (v_cat -> 'conditions' ? k) or jsonb_typeof(p -> 'conditions' -> k) <> 'number' or (p -> 'conditions' ->> k)::numeric < 0 then
      raise exception 'VALIDATION: % is not a setting of this rule (or not a number)', k using errcode = '22023';
    end if;
  end loop;
  if jsonb_typeof(coalesce(p -> 'actions', '[]'::jsonb)) <> 'array' or jsonb_array_length(coalesce(p -> 'actions', '[]'::jsonb)) = 0 then
    raise exception 'VALIDATION: add at least one action' using errcode = '22023';
  end if;
  for a in select * from jsonb_array_elements(p -> 'actions') loop
    if not (v_cat -> 'actions' ? (a ->> 'type')) then
      raise exception 'VALIDATION: "%" does not fit this rule', a ->> 'type' using errcode = '22023';
    end if;
    if a ->> 'type' = 'notify_staff' and not exists (select 1 from public.platform_modules m where m.code = coalesce(a ->> 'module', 'health')
         and coalesce(a ->> 'action', 'view') = any (m.actions)) then
      raise exception 'VALIDATION: choose who is notified (a section and access level that exist)' using errcode = '22023';
    end if;
    if coalesce(a ->> 'severity', 'WARN') not in ('INFO', 'WARN', 'CRITICAL', 'HIGH', 'MEDIUM', 'LOW') then
      raise exception 'VALIDATION: unknown importance' using errcode = '22023';
    end if;
  end loop;
  if coalesce((p ->> 'cooldown_minutes')::int, 1440) not between 10 and 43200 or coalesce((p ->> 'max_actions_per_run')::int, 25) not between 1 and 200 then
    raise exception 'VALIDATION: the cooldown is 10 minutes to 30 days, and a run acts on 1–200 subjects' using errcode = '22023';
  end if;
end;

_platform_execute_approval.src:
begin
  case a.action
    when 'grant_super_admin' then
      insert into public.platform_staff (user_id, email, full_name, title, role_id, created_by)
      select u.id, u.email, coalesce(nullif(a.payload ->> 'full_name', ''), u.full_name), a.payload ->> 'title', (a.payload ->> 'role_id')::uuid, a.requested_by
      from public._auth_user((a.payload ->> 'user_id')::uuid) u
      on conflict (user_id) do update set role_id = excluded.role_id;
      return jsonb_build_object('user_id', a.payload ->> 'user_id');
    when 'merchant_close' then
      update public.merchants set status = 'CLOSED', status_reason = a.reason, status_changed_at = now(), status_changed_by = a.requested_by
      where id = a.merchant_id and status <> 'CLOSED';
      update public.support_sessions set ended_at = now(), end_reason = 'Merchant closed' where merchant_id = a.merchant_id and ended_at is null;
      return jsonb_build_object('merchant_id', a.merchant_id, 'status', 'CLOSED');
    else
      return public._platform_execute_approval_more(a);
  end case;
end;

_platform_execute_approval_more.src:
declare
  e public.credit_ledger;
begin
  case a.action
    when 'credit_adjust' then
      e := public._credit_post(a.merchant_id, a.payload ->> 'credit_type', (a.payload ->> 'amount')::int, a.payload ->> 'kind', a.reason,
        a.requested_by, 'PLATFORM', 'platform_approval', a.id::text, a.payload ->> 'key', (a.payload ->> 'expires_at')::timestamptz,
        jsonb_build_object('approved_by', auth.uid()));
      perform public._platform_log('credits.' || lower(a.payload ->> 'kind'), a.merchant_id, 'credit_ledger', e.id::text, a.reason, null,
        jsonb_build_object('credit_type', e.credit_type, 'amount', e.amount, 'balance_after', e.balance_after, 'approval', a.id));
      return jsonb_build_object('entry_id', e.id, 'balance_after', e.balance_after);
    when 'merchant_delete' then
      return public._platform_merchant_delete(a);
    else
      raise exception 'VALIDATION: unknown approval action %', a.action using errcode = '22023';
  end case;
end;

_platform_incident_open.src:
declare
  i public.platform_incidents;
  v_scope text := upper(coalesce(nullif(p ->> 'scope', ''), case when jsonb_array_length(coalesce(p -> 'merchants', '[]'::jsonb)) > 0 then 'SELECTED' else 'NONE' end));
  v_m uuid;
begin
  if p_dedupe is not null then
    select * into i from public.platform_incidents where dedupe_key = p_dedupe and status <> 'RESOLVED';
    if i.id is not null then
      return i;
    end if;
  end if;
  if upper(coalesce(p ->> 'severity', '')) not in ('CRITICAL', 'HIGH', 'MEDIUM', 'LOW') then
    raise exception 'VALIDATION: choose the severity' using errcode = '22023';
  end if;
  if length(trim(coalesce(p ->> 'title', ''))) < 3 then
    raise exception 'VALIDATION: give the incident a title' using errcode = '22023';
  end if;
  if v_scope not in ('ALL', 'SELECTED', 'NONE') then
    raise exception 'VALIDATION: unknown scope' using errcode = '22023';
  end if;
  insert into public.platform_incidents (title, description, severity, integration, mark_unavailable, scope, assigned_to, source, rule_id, dedupe_key, created_by)
  values (left(trim(p ->> 'title'), 160), nullif(trim(coalesce(p ->> 'description', '')), ''), upper(p ->> 'severity'), nullif(p ->> 'integration', ''),
          coalesce((p ->> 'mark_unavailable')::boolean, false), v_scope, nullif(p ->> 'assigned_to', '')::uuid, p_source, p_rule, p_dedupe, auth.uid())
  returning * into i;
  if v_scope = 'SELECTED' then
    for v_m in select (jsonb_array_elements_text(p -> 'merchants'))::uuid loop
      if exists (select 1 from public.merchants where id = v_m) then
        insert into public.platform_incident_merchants (incident_id, merchant_id) values (i.id, v_m) on conflict do nothing;
      end if;
    end loop;
  end if;
  perform public._platform_incident_update(i.id, 'CREATED', i.description, jsonb_build_object('severity', i.severity, 'source', p_source));
  perform public._platform_incident_sync_health();
  if i.severity in ('CRITICAL', 'HIGH') then
    perform public._platform_notify('incidents', 'edit', null, 'incident.opened', case when i.severity = 'CRITICAL' then 'CRITICAL' else 'WARN' end,
      format('%s incident #%s: %s', initcap(i.severity), i.number, i.title), i.description, '/super-admin/incidents?incident=' || i.id, 'incident.opened:' || i.id);
  end if;
  if i.assigned_to is not null then
    perform public._platform_notify('incidents', 'view', null, 'incident.assigned', 'WARN', format('Incident #%s is yours: %s', i.number, i.title), null,
      '/super-admin/incidents?incident=' || i.id, 'incident.assigned:' || i.id || ':' || i.assigned_to, array[i.assigned_to]);
  end if;
  return i;
end;

_platform_log.src:
begin
  insert into public.platform_audit_logs (actor_id, actor_email, action, merchant_id, entity_type, entity_id, reason, before, after, metadata, result, request_id)
  values (auth.uid(), (select email from public.platform_staff where user_id = auth.uid()), p_action, p_merchant, p_entity_type, p_entity_id,
          p_reason, p_before, p_after, coalesce(p_metadata, '{}'::jsonb), p_result,
          nullif(current_setting('request.headers', true), '')::jsonb ->> 'x-request-id');
end;

_platform_merchant_delete.src:
declare
  m public.merchants;
  v_logins uuid[];
  v_reset jsonb;
  r public.store_resets;
  v_tables text[];
  v_left text[];
  v_kept jsonb := '{}'::jsonb;
  v_counts jsonb := '{}'::jsonb;
  t text;
  n int;
  v_pass int := 0;
  v_progress boolean;
begin
  select * into m from public.merchants where id = a.merchant_id for update;
  if not found then
    raise exception 'NOT_FOUND: merchant not found' using errcode = 'P0002';
  end if;
  if m.deleted_at is not null then
    raise exception 'VALIDATION: this merchant was already deleted' using errcode = '22023';
  end if;
  if public._platform_merchant_recent_export(m.id) is null then
    raise exception 'VALIDATION: download a full export of this merchant (Data Management → Export) within 24 hours before approving'
      using errcode = '22023';
  end if;

  perform public._platform_in_merchant(m.id);
  -- Logins that belong only to this business (platform staff keep theirs).
  select coalesce(array_agg(p.id), '{}') into v_logins from public.profiles p
  where p.merchant_id = m.id and not exists (select 1 from public.platform_staff s where s.user_id = p.id);
  update public.profiles set is_active = false where merchant_id = m.id and is_active;

  -- Everything a full store reset removes (orders, customers, products, connections and their keys, ...).
  v_reset := public.platform_store_reset(m.id, 'EVERYTHING', m.name, 'Merchant deleted: ' || a.reason);

  -- Then every other table of the merchant, except money records and audit trails.
  insert into public.store_resets (merchant_id, scope, reason, export_id, requested_by, requested_by_email, txid)
  values (m.id, 'EVERYTHING', left('Merchant deleted: ' || a.reason, 2000), public._platform_merchant_recent_export(m.id), auth.uid(),
          (select email from public.platform_staff where user_id = auth.uid()), txid_current())
  returning * into r;
  perform set_config('app.store_reset', r.id::text, true);
  perform public._platform_in_merchant(m.id);
  set local lock_timeout = '20s';

  select coalesce(array_agg(c.relname::text order by c.relname), '{}') into v_tables
  from pg_class c
  where c.relnamespace = 'public'::regnamespace and c.relkind = 'r'
    and exists (select 1 from pg_attribute at where at.attrelid = c.oid and at.attname = 'merchant_id' and not at.attisdropped)
    and c.relname <> all (public._merchant_delete_kept_tables());

  -- Tables point at each other; delete in passes until nothing more can go.
  loop
    v_pass := v_pass + 1;
    v_progress := false;
    v_left := '{}';
    foreach t in array v_tables loop
      begin
        execute format('delete from public.%I where merchant_id = $1', t) using m.id;
        get diagnostics n = row_count;
        if n > 0 then
          v_counts := v_counts || jsonb_build_object(t, coalesce((v_counts ->> t)::int, 0) + n);
          v_progress := true;
        end if;
      exception
        when foreign_key_violation then
          v_left := v_left || t;
        when others then
          -- A record the database refuses to delete (e.g. immutable history) stays.
          v_kept := v_kept || jsonb_build_object(t, sqlerrm);
      end;
    end loop;
    v_tables := v_left;
    exit when cardinality(v_tables) = 0 or not v_progress or v_pass >= 12;
  end loop;
  foreach t in array v_tables loop
    v_kept := v_kept || jsonb_build_object(t, 'still referenced by a record that stays');
  end loop;

  update public.store_resets set status = 'DONE', counts = v_counts, finished_at = now() where id = r.id;
  perform set_config('app.store_reset', '', true);

  -- What stays carries no contact details.
  update public.billing_payments set raw = '{}'::jsonb, note = null where merchant_id = m.id;
  update public.pbx_bkash_transactions set raw = '{}'::jsonb where merchant_id = m.id;
  update public.pbx_businesses set name = format('Deleted merchant #%s', m.number) where merchant_id = m.id;
  update public.merchants set name = format('Deleted merchant #%s', m.number), slug = null, phone = null, address = null,
    website = null, notes = null, owner_email = null, business_type = null, onboarding = '{}'::jsonb, account_manager_id = null,
    status = 'CLOSED', status_reason = left('Deleted: ' || a.reason, 500), status_changed_at = now(), status_changed_by = auth.uid(),
    deleted_at = now()
  where id = m.id;
  update public.support_sessions set ended_at = now(), end_reason = 'Merchant deleted' where merchant_id = m.id and ended_at is null;

  insert into public.account_removals (user_id, from_merchant, reason)
  select u, m.id, 'Merchant deleted' from unnest(v_logins) u;

  perform public._platform_log('merchants.deleted', m.id, 'merchant', m.id::text, a.reason,
    jsonb_build_object('name', m.name, 'number', m.number),
    jsonb_build_object('reset', v_reset -> 'counts', 'deleted', v_counts, 'kept', v_kept, 'logins', cardinality(v_logins), 'approval', a.id));
  return jsonb_build_object('merchant_id', m.id, 'deleted', v_counts, 'kept', v_kept, 'logins_removed', cardinality(v_logins));
end;

_platform_merchant_signals.src:
declare
  m public.merchants;
  s public.subscriptions;
  v_signals jsonb := '[]'::jsonb;
  v_onb jsonb;
  v_recent int;
  v_prior int;
  v_ever boolean;
  v_errors int;
  v_store_errors int;
  v_open int;
  v_overdue int;
  v_sms_now int;
  v_sms_before int;
  v_add jsonb;
begin
  select * into m from public.merchants where id = p_merchant;
  select * into s from public.subscriptions where merchant_id = p_merchant and ended_at is null order by created_at desc limit 1;
  v_onb := public._merchant_onboarding(p_merchant);
  select count(*) filter (where created_at > now() - interval '14 days'), count(*) filter (where created_at <= now() - interval '14 days' and created_at > now() - interval '28 days'),
         count(*) > 0
    into v_recent, v_prior, v_ever
  from public.orders where merchant_id = p_merchant and created_at > now() - interval '365 days';
  select count(*) into v_errors from public.system_logs where merchant_id = p_merchant and level = 'ERROR' and resolved_at is null and last_seen_at > now() - interval '7 days';
  select count(*) into v_store_errors from public.sales_channels where merchant_id = p_merchant and status = 'ERROR';
  select count(*) filter (where status in ('OPEN', 'IN_PROGRESS')), count(*) filter (where status in ('OPEN', 'IN_PROGRESS') and due_at < now())
    into v_open, v_overdue from public.support_tickets where merchant_id = p_merchant and not internal;
  select count(*) filter (where created_at > now() - interval '30 days'), count(*) filter (where created_at <= now() - interval '30 days')
    into v_sms_now, v_sms_before
  from public.service_usage where merchant_id = p_merchant and service = 'SMS' and status = 'SUCCEEDED' and created_at > now() - interval '60 days';

  -- Each signal: what was seen, how much it weighs (points off 100) and which kind of help it suggests.
  if (v_onb ->> 'done')::int < (v_onb ->> 'total')::int and m.created_at < now() - interval '7 days' then
    v_signals := v_signals || jsonb_build_object('key', 'onboarding', 'need', 'onboarding', 'points', least(25, 5 * ((v_onb ->> 'total')::int - (v_onb ->> 'done')::int)),
      'label', 'Onboarding not finished',
      'detail', format('%s of %s steps done after %s days: %s', v_onb ->> 'done', v_onb ->> 'total', extract(day from now() - m.created_at)::int,
        (select string_agg(e ->> 'label', ', ') from jsonb_array_elements(v_onb -> 'steps') e where not (e ->> 'done')::boolean)));
  end if;
  if v_store_errors > 0 then
    v_signals := v_signals || jsonb_build_object('key', 'store_error', 'need', 'technical', 'points', 20, 'label', 'Store connection failing',
      'detail', format('%s connected store(s) report an error', v_store_errors));
  end if;
  if v_errors > 0 then
    v_signals := v_signals || jsonb_build_object('key', 'errors', 'need', 'technical', 'points', case when v_errors >= 5 then 15 else 5 end,
      'label', 'Integration errors', 'detail', format('%s unresolved error(s) in the last 7 days', v_errors));
  end if;
  if v_ever and v_recent = 0 and m.status = 'ACTIVE' then
    v_signals := v_signals || jsonb_build_object('key', 'no_orders', 'need', 'activity', 'points', 20, 'label', 'No orders for 14 days',
      'detail', format('Had orders before (%s in the 14 days prior)', v_prior));
  elsif v_prior >= 10 and v_recent < v_prior / 2 then
    v_signals := v_signals || jsonb_build_object('key', 'order_drop', 'need', 'activity', 'points', 10, 'label', 'Orders dropped',
      'detail', format('%s orders in the last 14 days, %s in the 14 days before', v_recent, v_prior));
  end if;
  if s.status = 'PAST_DUE' then
    v_signals := v_signals || jsonb_build_object('key', 'past_due', 'need', 'billing', 'points', 20, 'label', 'Payment overdue',
      'detail', format('Subscription past due%s', case when s.grace_until is not null then ' — grace until ' || to_char(s.grace_until at time zone 'Asia/Dhaka', 'DD Mon') else '' end));
  elsif s.status = 'TRIALING' and s.trial_ends_at < now() + interval '7 days' then
    v_signals := v_signals || jsonb_build_object('key', 'trial_ending', 'need', 'billing', 'points', 5, 'label', 'Trial ending',
      'detail', format('Trial ends %s', to_char(s.trial_ends_at at time zone 'Asia/Dhaka', 'DD Mon')));
  elsif s.status = 'PAUSED' then
    v_signals := v_signals || jsonb_build_object('key', 'paused', 'need', 'billing', 'points', 10, 'label', 'Subscription paused', 'detail', 'Paused by the platform or on request');
  end if;
  if s.cancel_at_period_end then
    v_signals := v_signals || jsonb_build_object('key', 'cancelling', 'need', 'billing', 'points', 15, 'label', 'Cancellation scheduled',
      'detail', format('Ends %s unless undone', to_char(s.current_period_end at time zone 'Asia/Dhaka', 'DD Mon')));
  end if;
  if s.id is null and m.status = 'ACTIVE' then
    v_signals := v_signals || jsonb_build_object('key', 'no_subscription', 'need', 'billing', 'points', 10, 'label', 'No subscription', 'detail', 'Active account without a current plan');
  end if;
  if v_overdue > 0 then
    v_signals := v_signals || jsonb_build_object('key', 'tickets_overdue', 'need', 'technical', 'points', 10, 'label', 'Support tickets overdue',
      'detail', format('%s of %s open ticket(s) past their due time', v_overdue, v_open));
  elsif v_open > 0 then
    v_signals := v_signals || jsonb_build_object('key', 'tickets_open', 'need', 'technical', 'points', 3, 'label', 'Open support tickets', 'detail', format('%s open', v_open));
  end if;
  if v_sms_before >= 50 and v_sms_now < v_sms_before / 2 then
    v_signals := v_signals || jsonb_build_object('key', 'usage_drop', 'need', 'activity', 'points', 5, 'label', 'SMS use dropped',
      'detail', format('%s messages in the last 30 days, %s in the 30 days before', v_sms_now, v_sms_before));
  end if;

  return jsonb_build_object(
    'score', greatest(0, 100 - coalesce((select sum((x ->> 'points')::int) from jsonb_array_elements(v_signals) x), 0)),
    'signals', v_signals,
    'needs', coalesce((select jsonb_agg(distinct x ->> 'need') from jsonb_array_elements(v_signals) x), '[]'::jsonb),
    'facts', jsonb_build_object('orders_14d', v_recent, 'orders_prior_14d', v_prior, 'errors_7d', v_errors, 'open_tickets', v_open,
      'onboarding', jsonb_build_object('done', v_onb -> 'done', 'total', v_onb -> 'total'),
      'subscription', case when s.id is null then null else jsonb_build_object('status', s.status, 'trial_ends_at', s.trial_ends_at,
        'cancel_at_period_end', s.cancel_at_period_end, 'plan', (select code from public.plans where id = s.plan_id)) end));
end;

_platform_notify.src:
declare
  v_n int;
begin
  insert into public.platform_notifications (user_id, kind, severity, title, body, link, merchant_id, dedupe_key)
  select s.user_id, p_kind, coalesce(p_severity, 'INFO'), left(p_title, 200), left(p_body, 2000), p_link, p_merchant, p_dedupe
  from public.platform_staff s
  where s.is_active
    and case when p_users is not null
             then s.user_id = any (p_users) and public._platform_staff_can(s.user_id, p_module, 'view', p_merchant)
             else public._platform_staff_can(s.user_id, p_module, p_action, p_merchant) end
  on conflict (user_id, dedupe_key) where dedupe_key is not null do nothing;
  get diagnostics v_n = row_count;
  return v_n;
end;

_platform_pbx_business_json.src:
declare
  v jsonb;
begin
  if b.id is null then
    return null;
  end if;
  -- The VoiceDrive helpers read through row-level security: run them inside the merchant.
  perform public._platform_in_merchant(b.merchant_id);
  v := jsonb_build_object('id', b.id, 'code', b.code, 'name', b.name, 'did', b.did, 'caller_id', b.caller_id,
    'trunk_host', b.trunk_host, 'trunk_port', b.trunk_port, 'trunk_transport', b.trunk_transport, 'trunk_user', b.trunk_user,
    'trunk_register', b.trunk_register, 'trunk_secret_set', b.trunk_secret_set,
    'trunk_secret_hint', (select hint from public.platform_credentials where key = 'voicedrive.trunk.' || replace(b.id::text, '-', '')),
    'dial_format', b.dial_format, 'max_call_minutes', b.max_call_minutes, 'pbx_enabled', b.pbx_enabled,
    'bridge_ready', b.bridge_ready, 'bridge_ready_at', b.bridge_ready_at, 'provisioned_at', b.provisioned_at,
    'limits', public._vd_limits(b.id), 'balance_tk', round(public._vd_balance(b.id), 2), 'problems', to_jsonb(public._vd_line_problems(b.id)),
    'agents', (select count(*) from public.pbx_agents a where a.business_id = b.id and a.active),
    'trunk', public._platform_pbx_trunk_state(b.code));
  perform public._platform_in_merchant(null);
  return v;
end;

_platform_require.src:
begin
  if not public.platform_can(p_module, p_action, p_merchant) then
    if not public._platform_session_ok() and exists (select 1 from public.platform_staff where user_id = auth.uid() and is_active) then
      raise exception 'SESSION_EXPIRED: your Super Admin session has ended — sign in again' using errcode = '42501';
    end if;
    raise exception 'PERMISSION_DENIED: % % is not allowed%', p_module, p_action,
      case when p_merchant is null then '' else ' for this merchant' end using errcode = '42501';
  end if;
end;

_platform_retention_run.src:
declare
  v jsonb := coalesce((select value from public.platform_settings where key = 'retention'), '{}'::jsonb);
  v_logs int;
  v_notes int;
  v_out jsonb;
begin
  delete from public.system_logs where resolved_at is not null
    and resolved_at < now() - make_interval(days => greatest(7, coalesce((v ->> 'system_logs_days')::int, 90)));
  get diagnostics v_logs = row_count;
  delete from public.platform_notifications where read_at is not null
    and read_at < now() - make_interval(days => greatest(7, coalesce((v ->> 'notifications_days')::int, 90)));
  get diagnostics v_notes = row_count;
  v_out := jsonb_build_object('last_run_at', now(), 'system_logs_removed', v_logs, 'notifications_removed', v_notes);
  insert into public.platform_settings (key, value, description) values ('retention_state', v_out, 'The last retention run')
  on conflict (key) do update set value = excluded.value;
  return v_out;
end;

_platform_session_ok.src:
declare
  v_sid uuid := nullif(auth.jwt() ->> 'session_id', '')::uuid;
  v_hours int := nullif((select value ->> 'staff_session_hours' from public.platform_settings where key = 'security'), '')::int;
  v_started timestamptz;
begin
  if v_sid is null then
    return true;
  end if;
  select created_at into v_started from auth.sessions where id = v_sid;
  if not found then
    return false;
  end if;
  return v_hours is null or v_started > now() - make_interval(hours => v_hours);
end;

_platform_support_expire.src:
declare
  s public.support_sessions;
  v_n int := 0;
begin
  for s in
    update public.support_sessions set ended_at = expires_at, end_reason = 'Expired'
    where ended_at is null and expires_at <= now()
    returning *
  loop
    v_n := v_n + 1;
    insert into public.platform_audit_logs (actor_id, actor_email, action, merchant_id, entity_type, entity_id, reason, after, metadata, result)
    values (s.staff_user_id, (select email from public.platform_staff where user_id = s.staff_user_id), 'support.session_expired', s.merchant_id,
            'support_session', s.id::text, s.reason,
            jsonb_build_object('minutes', round(extract(epoch from s.expires_at - s.started_at) / 60), 'ticket_id', s.ticket_id),
            jsonb_build_object('automatic', true), 'SUCCESS');
  end loop;
  return v_n;
end;

_platform_ticket_assignee_ok.src:
begin
  if not public._platform_staff_can(p_user, 'support', 'edit', p_merchant) then
    raise exception 'VALIDATION: that person cannot work on this merchant''s tickets' using errcode = '22023';
  end if;
end;

_platform_ticket_created.src:
begin
  insert into public.support_ticket_events (ticket_id, merchant_id, kind, body, data, actor_id, actor_email)
  values (new.id, new.merchant_id, 'CREATED', null,
          jsonb_build_object('priority', new.priority, 'kind', new.kind, 'by', case when new.opened_by_platform is null then 'MERCHANT' else 'PLATFORM' end),
          coalesce(new.opened_by_platform, new.created_by),
          coalesce((select email from public.platform_staff where user_id = new.opened_by_platform),
                   (select email from public.profiles where id = new.created_by)));
  if new.opened_by_platform is null and new.priority in ('HIGH', 'URGENT') then
    perform public._platform_notify('support', 'edit', new.merchant_id, 'support.ticket_new',
      case when new.priority = 'URGENT' then 'CRITICAL' else 'WARN' end,
      format('%s ticket #%s: %s', initcap(new.priority), new.number, new.subject),
      (select name from public.merchants where id = new.merchant_id), '/super-admin/support?ticket=' || new.id, 'ticket.new:' || new.id);
  end if;
  return new;
end;

_platform_ticket_escalate.src:
declare
  v_row public.support_tickets;
begin
  if t.escalation_level >= 5 then
    return t;
  end if;
  update public.support_tickets set escalation_level = escalation_level + 1, escalated_at = now(),
    priority = case priority when 'LOW' then 'NORMAL' when 'NORMAL' then 'HIGH' else 'URGENT' end
  where id = t.id returning * into v_row;
  perform public._platform_ticket_event(t.id, t.merchant_id, 'ESCALATED', p_reason,
    jsonb_build_object('level', v_row.escalation_level, 'priority_from', t.priority, 'priority_to', v_row.priority, 'automatic', p_auto));
  perform public._platform_notify('support', 'manage', t.merchant_id, 'support.ticket_escalated',
    case when v_row.priority = 'URGENT' then 'CRITICAL' else 'WARN' end,
    format('Escalated (level %s): #%s %s', v_row.escalation_level, t.number, t.subject), p_reason,
    '/super-admin/support?ticket=' || t.id, format('ticket.escalated:%s:%s', t.id, v_row.escalation_level));
  if t.assigned_to is not null then
    perform public._platform_notify('support', 'view', t.merchant_id, 'support.ticket_escalated', 'WARN',
      format('Your ticket #%s was escalated', t.number), p_reason, '/super-admin/support?ticket=' || t.id,
      format('ticket.escalated:%s:%s', t.id, v_row.escalation_level), array[t.assigned_to]);
  end if;
  return v_row;
end;

_platform_ticket_get_row.src:
declare
  t public.support_tickets;
begin
  select * into t from public.support_tickets where id = p_id for update;
  if t.id is null or not public.platform_can('support', 'view', t.merchant_id) then
    raise exception 'NOT_FOUND: ticket not found' using errcode = 'P0002';
  end if;
  perform public._platform_require('support', p_action, t.merchant_id);
  return t;
end;

_platform_ticket_message.src:
declare
  t public.support_tickets;
begin
  select * into t from public.support_tickets where id = new.ticket_id;
  update public.support_tickets set last_reply_from = case when new.platform_author is null then 'MERCHANT' else 'PLATFORM' end
  where id = new.ticket_id;
  if new.platform_author is null then
    insert into public.support_ticket_events (ticket_id, merchant_id, kind, body, data, actor_id, actor_email)
    values (t.id, t.merchant_id, 'MERCHANT_REPLY', left(new.body, 300), jsonb_build_object('message_id', new.id), new.author_id,
            (select email from public.profiles where id = new.author_id));
    -- Only once the platform team is involved: the merchant writing to their own ticket before anyone answered is not news.
    if t.assigned_to is not null then
      perform public._platform_notify('support', 'view', t.merchant_id, 'support.ticket_reply', 'INFO',
        format('Reply on #%s: %s', t.number, t.subject), left(new.body, 300), '/super-admin/support?ticket=' || t.id,
        'ticket.reply:' || new.id, array[t.assigned_to]);
    end if;
  end if;
  return new;
end;

_platform_ticket_sla.src:
declare
  v_hours numeric;
begin
  if tg_op = 'INSERT' or (new.priority is distinct from old.priority and new.due_at is not distinct from old.due_at) then
    v_hours := nullif(public._platform_support_settings() #>> array['sla_hours', new.priority], '')::numeric;
    if v_hours is not null and (tg_op = 'UPDATE' or new.due_at is null) then
      new.due_at := new.created_at + make_interval(secs => v_hours * 3600);
    end if;
  end if;
  return new;
end;

_post_finance.src:
declare
  v_cat uuid := public.finance_category_id(p_category_code);
  v_row public.finance_transactions;
begin
  if coalesce(p_amount, 0) = 0 then
    return null;
  end if;
  if v_cat is null then
    raise exception 'CONFIG: finance category % is missing', p_category_code using errcode = 'P0001';
  end if;
  insert into public.finance_transactions(type, category_id, amount, txn_date, is_cash, payment_channel, reference,
    order_id, customer_id, supplier_id, purchase_order_id, notes, source, source_key, created_by)
  values (p_type, v_cat, public.money(p_amount), coalesce(p_date, (now() at time zone public.store_timezone())::date),
          p_is_cash, p_channel, p_reference, p_order_id, p_customer_id, p_supplier_id, p_purchase_order_id, p_notes,
          'SYSTEM', p_source_key, auth.uid())
  on conflict (source_key) do nothing
  returning * into v_row;
  return v_row;
end;

_post_lost_parcel_finance.src:
declare
  v_order public.orders;
  v_cost numeric;
  v_n int;
begin
  select * into v_order from public.orders where id = p_order_id;
  if v_order.shipped_at is null or v_order.delivered_at is not null then
    return; -- not shipped yet, or the cost was already recognised on delivery
  end if;
  select coalesce(sum(unit_cost * (quantity - returned_quantity - damaged_quantity)), 0) into v_cost
  from public.order_items where order_id = p_order_id;
  select count(*) into v_n from public.order_status_history where order_id = p_order_id and to_status = 'LOST';
  perform public._post_finance('EXPENSE', 'LOST_PARCELS', public.money(v_cost),
    (now() at time zone public.store_timezone())::date, false, p_order_id, null, null,
    v_order.order_number, 'Parcel lost by the courier', 'order:' || p_order_id || ':lost:' || v_n, null);
end;

_post_order_delivery_finance.src:
declare
  v_order public.orders;
  v_ship public.shipments;
  v_date date;
begin
  select * into v_order from public.orders where id = p_order_id;
  v_date := (coalesce(v_order.delivered_at, now()) at time zone public.store_timezone())::date;

  perform public._post_finance('INCOME', 'PRODUCT_SALES', v_order.subtotal - v_order.discount_total, v_date, false,
    p_order_id, v_order.customer_id, null, v_order.order_number, 'Product revenue (delivered)',
    'order:' || p_order_id || ':product_revenue', null);
  perform public._post_finance('INCOME', 'DELIVERY_CHARGES', v_order.delivery_charge - v_order.delivery_discount, v_date, false,
    p_order_id, v_order.customer_id, null, v_order.order_number, 'Delivery charge (delivered)',
    'order:' || p_order_id || ':delivery_revenue', null);
  perform public._post_finance('EXPENSE', 'COGS', v_order.cost_total, v_date, false,
    p_order_id, v_order.customer_id, null, v_order.order_number, 'Cost of goods sold',
    'order:' || p_order_id || ':cogs', null);

  -- Courier costs as estimates; a fee the courier reports later replaces them.
  select * into v_ship from public.shipments where order_id = p_order_id and is_active;
  if found and public.setting_bool('finance', array['record_courier_cost_on_delivery'], true) then
    perform public._estimate_shipment_charge(v_ship.id, 'DELIVERY', v_ship.shipping_cost,
      'shipment:' || v_ship.id || ':shipping_cost', 'Courier charge', v_date);
    perform public._estimate_shipment_charge(v_ship.id, 'COD_FEE', public._courier_cod_fee(v_ship.courier_id, v_order.cod_amount),
      'shipment:' || v_ship.id || ':cod_fee', 'Courier COD fee', v_date);
  end if;

  if public.setting_bool('finance', array['auto_collect_cod_on_delivery'], false) then
    select * into v_order from public.orders where id = p_order_id;
    if v_order.cod_amount > 0 then
      insert into public.order_payments(order_id, kind, channel, amount, note, idempotency_key)
      values (p_order_id, 'COD', 'COURIER_COD', v_order.cod_amount, 'Collected on delivery',
              'cod:delivered:' || p_order_id)
      on conflict (idempotency_key) do nothing;
      if found then
        perform public._post_finance('INCOME', 'COD_COLLECTIONS', v_order.cod_amount, v_date, true,
          p_order_id, v_order.customer_id, null, v_order.order_number, 'COD collected on delivery',
          'order:' || p_order_id || ':cod_on_delivery', 'COURIER_COD');
        perform public.recalculate_order_totals(p_order_id);
      end if;
    end if;
  end if;
end;

_post_order_return_finance.src:
declare
  v_order public.orders;
  v_ship public.shipments;
  v_date date := (now() at time zone public.store_timezone())::date;
begin
  select * into v_order from public.orders where id = p_order_id;
  select * into v_ship from public.shipments where order_id = p_order_id and is_active;
  if not found then
    return;
  end if;
  if v_order.delivered_at is null then
    perform public._estimate_shipment_charge(v_ship.id, 'DELIVERY', v_ship.shipping_cost,
      'shipment:' || v_ship.id || ':shipping_cost', 'Courier charge (failed delivery)', v_date);
  end if;
  perform public._estimate_shipment_charge(v_ship.id, 'RETURN', v_ship.return_charge,
    'shipment:' || v_ship.id || ':return_charge', 'Courier return charge', v_date);
end;

_post_partial_return_finance.src:
declare
  v_order public.orders;
begin
  select * into v_order from public.orders where id = p_order_id;
  if v_order.partial_return_amount <= 0 or v_order.delivered_at is null then
    return;
  end if;
  perform public._post_finance('EXPENSE', 'PARTIAL_RETURNS', v_order.partial_return_amount,
    (v_order.delivered_at at time zone public.store_timezone())::date, false, p_order_id, v_order.customer_id, null,
    v_order.order_number, 'Goods sent back on a partial delivery', 'order:' || p_order_id || ':partial_return', null);
end;

_post_sms_finance.src:
declare
  v_log public.notification_logs;
  v_posted numeric;
  v_date date;
  v_note text;
  v_ref text;
begin
  select * into v_log from public.notification_logs where id = p_log_id;
  if not found or v_log.channel <> 'SMS' or v_log.status <> 'SENT' or v_log.cost is null or v_log.cost <= 0 then
    return;
  end if;
  v_date := (coalesce(v_log.sent_at, now()) at time zone public.store_timezone())::date;
  v_note := format('SMS · %s · %s', coalesce(public.notification_event_label(v_log.event), 'Test message'),
                   public._mask_phone(v_log.recipient));
  select order_number into v_ref from public.orders where id = v_log.order_id;

  if not exists (select 1 from public.finance_transactions where source_key = 'sms:' || v_log.id) then
    perform public._post_finance('EXPENSE', 'SMS', v_log.cost, v_date, true, v_log.order_id, v_log.customer_id, null,
      v_ref, v_note, 'sms:' || v_log.id, null);
  elsif v_log.cost_source = 'PROVIDER' then
    select coalesce(sum(amount), 0) into v_posted from public.finance_transactions
    where source_key in ('sms:' || v_log.id, 'sms:' || v_log.id || ':provider');
    if public.money(v_log.cost) <> v_posted then
      perform public._post_finance('EXPENSE', 'SMS', public.money(v_log.cost) - v_posted, v_date, true, v_log.order_id,
        v_log.customer_id, null, v_ref, v_note || ' · charge reported by the provider', 'sms:' || v_log.id || ':provider', null);
    end if;
  end if;
end;

_process_courier_webhook.src:
declare
  e public.courier_webhook_events;
  v_ship public.shipments;
  v_prev public.shipment_status;
  v_applied boolean := false;
  v_charged numeric := 0;
  v_key text;
  v_date date;
  v_err text;
  v_result text;
  v_note text;
begin
  update public.courier_webhook_events set attempts = attempts + 1 where id = p_event_id returning * into e;
  if not found then
    raise exception 'NOT_FOUND: webhook event not found' using errcode = 'P0002';
  end if;

  select s.* into v_ship
  from public.shipments s
  join public.couriers c on c.id = s.courier_id
  join public.orders o on o.id = s.order_id
  where (case when e.courier_id is not null then s.courier_id = e.courier_id else c.provider = e.provider end)
    and ((e.consignment_id is not null and (s.consignment_id = e.consignment_id or s.tracking_number = e.consignment_id))
      or (e.order_ref is not null and upper(o.order_number) = upper(e.order_ref)))
  order by (e.consignment_id is not null and (s.consignment_id = e.consignment_id or s.tracking_number = e.consignment_id)) desc,
           s.is_active desc, s.created_at desc
  limit 1;
  if not found then
    update public.courier_webhook_events set result = 'UNMATCHED',
      error = format('No %s parcel with consignment %s or order %s', e.provider, coalesce(e.consignment_id, '-'), coalesce(e.order_ref, '-')),
      next_retry_at = case when attempts < 6 then now() + make_interval(mins => least(power(2, attempts)::int, 120)) end,
      processed_at = now()
    where id = p_event_id;
    return jsonb_build_object('status', 'unmatched', 'event_id', p_event_id);
  end if;

  v_prev := v_ship.status;
  v_date := (coalesce(e.occurred_at, now()) at time zone public.store_timezone())::date;
  begin
    if e.new_status is not null and e.new_status <> v_ship.status
       and not public._shipment_status_regresses(v_ship.status, e.new_status) then
      perform public.apply_shipment_status(v_ship.id, e.new_status,
        coalesce(nullif(e.payload ->> 'reason', ''), format('%s: %s', initcap(e.provider), coalesce(e.provider_status, e.event_type))),
        null, e.occurred_at, 'WEBHOOK', e.payload, 'webhook:' || e.event_key);
      v_applied := true;
    end if;

    -- Fees reported with the event (a parcel not yet picked up costs nothing).
    if coalesce(e.new_status, v_ship.status) not in ('PENDING', 'BOOKED', 'CANCELLED') then
      v_key := 'webhook:' || e.event_key;
      v_charged := abs(public._set_shipment_charge(v_ship.id, 'DELIVERY', (e.charges ->> 'delivery_fee')::numeric, 'WEBHOOK',
                     v_key || ':delivery', 'Delivery fee reported by courier', null, v_date))
                 + abs(public._set_shipment_charge(v_ship.id, 'RETURN', (e.charges ->> 'return_fee')::numeric, 'WEBHOOK',
                     v_key || ':return', 'Return charge reported by courier', null, v_date))
                 + abs(public._set_shipment_charge(v_ship.id, 'COD_FEE', (e.charges ->> 'cod_fee')::numeric, 'WEBHOOK',
                     v_key || ':cod_fee', 'COD fee reported by courier', null, v_date));
    end if;
    -- Returned without a fee in the message: the expected return charge stands in until the statement arrives.
    if e.new_status = 'RETURNED' and e.charges ->> 'return_fee' is null then
      v_charged := v_charged + abs(public._estimate_shipment_charge(v_ship.id, 'RETURN', v_ship.return_charge,
        'shipment:' || v_ship.id || ':return_charge', 'Courier return charge', v_date));
    end if;

    v_result := case when v_applied or v_charged <> 0 then 'PROCESSED' else 'IGNORED' end;
    v_note := case
      when v_applied then null
      when e.new_status is null and v_charged = 0 then 'No status change in this event' || coalesce(' (' || e.provider_status || ')', '')
      when e.new_status is not null and e.new_status = v_prev then 'Parcel already ' || replace(lower(v_prev::text), '_', ' ')
      when e.new_status is not null then format('Not applied: parcel is already %s', replace(lower(v_prev::text), '_', ' '))
    end;
    update public.courier_webhook_events set result = v_result, note = v_note, error = null,
      shipment_id = v_ship.id, order_id = v_ship.order_id, previous_status = v_prev, next_retry_at = null, processed_at = now()
    where id = p_event_id;
    return jsonb_build_object('status', lower(v_result), 'event_id', p_event_id, 'shipment_id', v_ship.id);
  exception when others then
    get stacked diagnostics v_err = message_text;
    update public.courier_webhook_events set result = 'FAILED', error = left(v_err, 500),
      shipment_id = v_ship.id, order_id = v_ship.order_id, previous_status = v_prev,
      next_retry_at = case when attempts < 6 then now() + make_interval(mins => least(power(2, attempts)::int, 120)) end,
      processed_at = now()
    where id = p_event_id;
    return jsonb_build_object('status', 'failed', 'event_id', p_event_id, 'error', left(v_err, 500));
  end;
end;

_production_cancel_for_order.src:
declare
  v_po public.production_orders;
begin
  for v_po in select * from public.production_orders where order_id = p_order_id and status <> 'CANCELLED' for update loop
    update public.production_orders set status = 'CANCELLED' where id = v_po.id;
    perform public._production_log(v_po.id, v_po.status, 'CANCELLED', 'CANCEL', 'Order cancelled');
  end loop;
end;

_production_create_for_order.src:
declare
  v_mode text := upper(public.setting_text('production', array['auto_create'], 'REQUIRED_ONLY'));
  v_po public.production_orders;
begin
  select * into v_po from public.production_orders where order_id = p_order_id and status <> 'CANCELLED';
  if found then
    return v_po;
  end if;
  if not p_force then
    if not public.setting_bool('production', array['enabled'], true) or v_mode = 'OFF' then
      return null;
    end if;
    if v_mode = 'REQUIRED_ONLY'
       and not exists (select 1 from public.order_items where order_id = p_order_id and requires_production) then
      return null;
    end if;
  end if;

  insert into public.production_orders(order_id, deadline, priority)
  values (p_order_id,
          (now() at time zone public.store_timezone())::date
            + public.setting_numeric('production', array['default_deadline_days'], 3)::int,
          'NORMAL')
  returning * into v_po;
  perform public._production_fill_items(v_po.id, p_order_id);
  perform public._production_log(v_po.id, null, 'WAITING', 'CREATED', 'Added to production queue');
  perform public._order_log(p_order_id, 'PRODUCTION_QUEUED', 'Added to the production queue');
  return v_po;
end;

_production_refresh_items.src:
declare
  v_po public.production_orders;
begin
  select * into v_po from public.production_orders
  where order_id = p_order_id and status not in ('CANCELLED', 'READY');
  if found then
    delete from public.production_items where production_order_id = v_po.id;
    perform public._production_fill_items(v_po.id, p_order_id);
  end if;
end;

_production_sync_from_order.src:
declare
  v_po public.production_orders;
  v_target public.production_status := case p_order_status
    when 'PRODUCTION' then 'IN_PRODUCTION' when 'QUALITY_CHECK' then 'QUALITY_CHECK'
    when 'PACKING' then 'PACKING' when 'READY_TO_SHIP' then 'READY' end;
begin
  if v_target is null then
    return;
  end if;
  select * into v_po from public.production_orders where order_id = p_order_id and status <> 'CANCELLED' for update;
  if not found then
    if p_order_status = 'PRODUCTION' then
      v_po := public._production_create_for_order(p_order_id, true);
    else
      return;
    end if;
  end if;
  if v_po.status = v_target then
    return;
  end if;
  update public.production_orders set
    status = v_target,
    started_at = case when v_target = 'IN_PRODUCTION' then coalesce(started_at, now()) else started_at end,
    qc_at = case when v_target = 'QUALITY_CHECK' then now() else qc_at end,
    completed_at = case when v_target = 'READY' then now() else completed_at end
  where id = v_po.id;
  perform public._production_log(v_po.id, v_po.status, v_target, 'SYNC', 'Updated from order status');
end;

_profiles_deleted_stay_off.src:
begin
  new.deleted_at := old.deleted_at;
  if new.is_active then
    raise exception 'VALIDATION: this person was deleted; add them again as a new member instead' using errcode = '22023';
  end if;
  return new;
end;

_queue_channel_delivered.src:
declare
  v_order public.orders;
  v_channel public.sales_channels;
  v_f public.channel_fulfillments;
begin
  select * into v_order from public.orders where id = p_order_id;
  if v_order.sales_channel_id is null or v_order.external_order_id is null then
    return;
  end if;
  select * into v_channel from public.sales_channels where id = v_order.sales_channel_id;
  if v_channel.platform <> 'SHOPIFY' or not public._channel_opt(v_channel, 'mark_delivered', true) then
    return;
  end if;
  -- Delivered without ever being Shipped here: fulfil first (same job).
  if not exists (select 1 from public.channel_fulfillments where order_id = p_order_id and source = 'APP') then
    perform public._queue_channel_fulfillment(p_order_id);
  end if;
  update public.channel_fulfillments set delivered_status = 'PENDING', delivered_error = null
  where order_id = p_order_id and source = 'APP' and coalesce(delivered_status, '') <> 'MARKED'
  returning * into v_f;
  if v_f.id is null and exists (select 1 from public.channel_fulfillments where order_id = p_order_id and source = 'SHOPIFY') then
    -- Fulfilled by hand in Shopify and nothing of ours: mark that fulfilment.
    insert into public.channel_fulfillments(channel_id, order_id, external_order_id, status, delivered_status, last_error)
    values (v_channel.id, p_order_id, v_order.external_order_id, 'SKIPPED', 'PENDING', 'Fulfilled in Shopify')
    on conflict (order_id) where source = 'APP' do nothing
    returning * into v_f;
  end if;
  if v_f.id is not null then
    perform public.channel_job_enqueue(v_channel.id, 'FULFILL', p_order_id);
  end if;
end;

_queue_channel_fulfillment.src:
declare
  v_order public.orders;
  v_channel public.sales_channels;
  v_f public.channel_fulfillments;
begin
  select * into v_order from public.orders where id = p_order_id;
  if v_order.sales_channel_id is null or v_order.external_order_id is null then
    return null;
  end if;
  select * into v_channel from public.sales_channels where id = v_order.sales_channel_id;
  if not public._channel_opt(v_channel, 'fulfill_on_ship', v_channel.platform = 'SHOPIFY') then
    return null;
  end if;
  insert into public.channel_fulfillments(channel_id, order_id, external_order_id, status)
  values (v_channel.id, v_order.id, v_order.external_order_id, 'PENDING')
  on conflict (order_id) where source = 'APP' do update
    set status = case when channel_fulfillments.status in ('FULFILLED', 'PROCESSING') then channel_fulfillments.status else 'PENDING' end
  returning * into v_f;
  if v_f.status = 'PENDING' then
    perform public.channel_job_enqueue(v_channel.id, 'FULFILL', v_order.id);
  end if;
  return v_f.id;
end;

_queue_channel_order_sync.src:
declare
  v_order public.orders;
  v_channel public.sales_channels;
begin
  select * into v_order from public.orders where id = p_order_id;
  if v_order.sales_channel_id is null or v_order.external_order_id is null then
    return;
  end if;
  select * into v_channel from public.sales_channels where id = v_order.sales_channel_id;
  if v_channel.platform not in ('SHOPIFY', 'WOOCOMMERCE') or v_channel.status = 'DISCONNECTED' then
    return;
  end if;
  if v_channel.platform = 'WOOCOMMERCE' and not public._channel_opt(v_channel, 'status_sync', true) then
    return;
  end if;
  insert into public.channel_order_sync(order_id, channel_id, external_order_id)
  values (v_order.id, v_channel.id, v_order.external_order_id)
  on conflict (order_id) do nothing;
  if p_cancel and v_channel.platform = 'SHOPIFY' and public._channel_opt(v_channel, 'cancel_on_shopify', true) then
    update public.channel_order_sync set cancel_status = 'PENDING', cancel_error = null
    where order_id = v_order.id and coalesce(cancel_status, '') not in ('REQUESTED', 'CONFIRMED');
  end if;
  perform public.channel_job_enqueue(v_channel.id, 'FULFILL', v_order.id);
end;

_receive_rate_facts.src:
declare
  v_cfg jsonb := coalesce(public.get_setting('fraud') -> 'receive_rate', '{}'::jsonb);
  v_rate numeric := nullif(p_facts ->> 'courier_score', '')::numeric;
  v_parcels int := coalesce((p_facts ->> 'delivered_orders')::int, 0) + coalesce((p_facts ->> 'cancelled_orders')::int, 0)
                 + coalesce((p_facts ->> 'returned_orders')::int, 0) + coalesce((p_facts ->> 'failed_delivery_orders')::int, 0);
  v_tier text;
begin
  -- A courier that only reports a range ("50+") still proves history.
  v_parcels := greatest(v_parcels, coalesce((p_facts ->> 'provider_parcels')::int, 0));
  if v_rate is null or v_parcels < coalesce((v_cfg ->> 'min_parcels')::int, 1) then
    -- No usable history: a failed provider lookup is not the same as a new customer.
    v_tier := case when p_facts ->> 'provider_status' = 'ERROR' then 'ERROR' else 'NEW' end;
  elsif v_rate >= coalesce((v_cfg ->> 'good_min')::numeric, 80) then
    v_tier := 'GOOD';
  elsif v_rate >= coalesce((v_cfg ->> 'mid_min')::numeric, 50) then
    v_tier := 'MID';
  else
    v_tier := 'LOW';
  end if;
  return jsonb_build_object('receive_rate', v_rate, 'receive_rate_tier', v_tier, 'parcel_count', v_parcels);
end;

_record_order_attribution.src:
declare
  v_row public.order_attributions;
  v_first jsonb := case when jsonb_typeof(p_attribution -> 'first_touch') = 'object' then p_attribution -> 'first_touch' end;
  v_last jsonb := case when jsonb_typeof(p_attribution -> 'last_touch') = 'object' then p_attribution -> 'last_touch' end;
  v_visitor text := nullif(left(p_attribution ->> 'visitor_id', 64), '');
  v_session text := nullif(left(p_attribution ->> 'session_id', 64), '');
  v_c jsonb;
  v_fc jsonb;
  v_params jsonb;
  v_journey jsonb := '{}'::jsonb;
  v_order public.orders;
  v_campaign uuid;
begin
  if not public.feature_enabled('attribution') then
    return null;
  end if;
  select * into v_order from public.orders where id = p_order_id;
  if not found then
    raise exception 'NOT_FOUND: order not found' using errcode = 'P0002';
  end if;
  if length(coalesce(p_attribution, '{}'::jsonb)::text) > 20000 then
    raise exception 'VALIDATION: attribution data is too large' using errcode = '22023';
  end if;

  -- No ad, tagged link or referral within the window: a known visitor is direct;
  -- no data at all is unknown.
  v_c := case
    when v_last is not null then public.classify_touch(v_last)
    when v_first is not null or v_visitor is not null then public.classify_touch(jsonb_build_object('params', '{}'::jsonb))
    else public.classify_touch(null) end;
  v_fc := case when v_first is not null then public.classify_touch(v_first) end;
  v_params := coalesce(v_last -> 'params', '{}'::jsonb);

  if v_visitor is not null then
    select jsonb_build_object(
      'visits', count(distinct session_id),
      'page_views', count(*) filter (where event_type = 'PAGE_VIEW'),
      'product_views', count(*) filter (where event_type = 'VIEW_PRODUCT'),
      'add_to_cart', count(*) filter (where event_type = 'ADD_TO_CART'),
      'checkouts', count(*) filter (where event_type = 'BEGIN_CHECKOUT'),
      'first_seen_at', min(created_at),
      'last_seen_at', max(created_at))
    into v_journey
    from public.storefront_events
    where visitor_id = v_visitor and created_at between v_order.created_at - interval '30 days' and v_order.created_at + interval '5 minutes';
  end if;

  if v_c ->> 'campaign_id' is not null then
    select id into v_campaign from public.marketing_campaigns
    where platform = (v_c ->> 'platform')::public.marketing_platform and external_id = v_c ->> 'campaign_id';
  end if;
  if v_campaign is null and v_c ->> 'campaign' is not null then
    select id into v_campaign from public.marketing_campaigns where utm_campaign = v_c ->> 'campaign' limit 1;
  end if;

  insert into public.order_attributions(
    order_id, channel, source, medium, is_paid, platform, campaign, adset, ad, campaign_id, adset_id, ad_id,
    click_id_type, click_id, utm_source, utm_medium, utm_campaign, utm_content, utm_term, landing_page, referrer_host,
    first_channel, first_source, first_touch, last_touch, first_touch_at, last_touch_at, visitor_id, session_id,
    journey, marketing_campaign_id, recorded_by
  ) values (
    p_order_id, v_c ->> 'channel', v_c ->> 'source', v_c ->> 'medium', (v_c ->> 'is_paid')::boolean,
    (v_c ->> 'platform')::public.marketing_platform, left(v_c ->> 'campaign', 200), left(v_c ->> 'adset', 200), left(v_c ->> 'ad', 200),
    left(v_c ->> 'campaign_id', 64), left(v_c ->> 'adset_id', 64), left(v_c ->> 'ad_id', 64),
    v_c ->> 'click_id_type', v_c ->> 'click_id',
    left(v_params ->> 'utm_source', 120), left(v_params ->> 'utm_medium', 120), left(v_params ->> 'utm_campaign', 200),
    left(v_params ->> 'utm_content', 200), left(v_params ->> 'utm_term', 200),
    left(coalesce(v_last ->> 'landing', v_first ->> 'landing'), 300), v_c ->> 'referrer_host',
    coalesce(v_fc ->> 'channel', v_c ->> 'channel'), coalesce(v_fc ->> 'source', v_c ->> 'source'), v_first, v_last,
    (v_first ->> 'at')::timestamptz, (v_last ->> 'at')::timestamptz, v_visitor, v_session,
    coalesce(v_journey, '{}'::jsonb), v_campaign, 'STOREFRONT'
  )
  on conflict (order_id) do nothing
  returning * into v_row;

  if v_row.order_id is not null then
    update public.orders set
      utm_source = coalesce(utm_source, left(v_params ->> 'utm_source', 120)),
      utm_medium = coalesce(utm_medium, left(v_params ->> 'utm_medium', 120)),
      utm_campaign = coalesce(utm_campaign, left(v_params ->> 'utm_campaign', 200))
    where id = p_order_id;
  else
    select * into v_row from public.order_attributions where order_id = p_order_id;
  end if;
  return v_row;
end;

_release_order_stock.src:
declare
  v_res public.stock_reservations;
  v_number text := (select order_number from public.orders where id = p_order_id);
  v_count int := 0;
begin
  for v_res in select * from public.stock_reservations where order_id = p_order_id and status = 'ACTIVE' for update loop
    perform public._apply_inventory_movement(v_res.variant_id, 'RELEASE', 0, -v_res.quantity, 0,
      'ORDER', p_order_id, v_number, coalesce(p_reason, 'Reservation released'), null, true);
    update public.stock_reservations set status = 'RELEASED', released_at = now() where id = v_res.id;
    v_count := v_count + 1;
  end loop;
  return v_count;
end;

_report_access.src:
begin
  if not (public.is_system_context() or public.has_permission(p_permission) or public.has_permission('reports.view')) then
    raise exception 'PERMISSION_DENIED: % is required', p_permission using errcode = '42501';
  end if;
end;

_require_system.src:
begin
  if not public.is_system_context() then
    raise exception 'PERMISSION_DENIED' using errcode = '42501';
  end if;
end;

_reserve_order_item.src:
declare
  v_inv public.inventory;
begin
  if not p_item.track_inventory then
    return;
  end if;
  select * into v_inv from public.inventory where variant_id = p_item.variant_id for update;
  if not found then
    raise exception 'NOT_FOUND: no inventory for %', p_item.sku using errcode = 'P0002';
  end if;
  if v_inv.available < p_item.quantity and not public.allow_overselling() then
    raise exception 'INSUFFICIENT_STOCK: % has only % available', p_item.product_name, greatest(v_inv.available, 0)
      using errcode = 'P0001';
  end if;
  perform public._apply_inventory_movement(p_item.variant_id, 'RESERVATION', 0, p_item.quantity, 0,
    'ORDER', p_item.order_id, p_order_number, 'Reserved for order', null, true);
  insert into public.stock_reservations(order_id, order_item_id, variant_id, quantity)
  values (p_item.order_id, p_item.id, p_item.variant_id, p_item.quantity);
end;

_return_order_stock.src:
declare
  v_order public.orders;
  v_item public.order_items;
  v_req jsonb;
  v_reqs jsonb;
  v_qty int;
  v_condition text;
  v_count int := 0;
  v_default text := case when public.setting_bool('inventory', array['return_restock_default'], true)
                         then 'RESTOCK' else 'DAMAGED' end;
  v_mov public.inventory_movements;
begin
  select * into v_order from public.orders where id = p_order_id;
  if v_order.shipped_at is null then
    return 0; -- nothing left the warehouse; reservations are released instead
  end if;

  if p_items is null then
    select coalesce(jsonb_agg(jsonb_build_object('order_item_id', id,
             'quantity', quantity - returned_quantity - damaged_quantity, 'condition', v_default)), '[]'::jsonb)
    into v_reqs
    from public.order_items
    where order_id = p_order_id and quantity - returned_quantity - damaged_quantity > 0;
  else
    v_reqs := p_items;
  end if;

  -- Several entries may target the same line (e.g. 2 restocked + 1 damaged).
  for v_req in select * from jsonb_array_elements(v_reqs) loop
    select * into v_item from public.order_items
    where id = (v_req ->> 'order_item_id')::uuid and order_id = p_order_id for update;
    if not found then
      raise exception 'VALIDATION: returned item does not belong to this order' using errcode = '22023';
    end if;
    v_qty := (v_req ->> 'quantity')::int;
    v_condition := upper(coalesce(v_req ->> 'condition', v_default));
    if v_qty is null or v_qty <= 0 then
      continue;
    end if;
    if v_qty > v_item.quantity - v_item.returned_quantity - v_item.damaged_quantity then
      raise exception 'VALIDATION: cannot return more % than were shipped', v_item.sku using errcode = '22023';
    end if;
    if v_condition not in ('RESTOCK', 'DAMAGED') then
      raise exception 'VALIDATION: return condition must be RESTOCK or DAMAGED' using errcode = '22023';
    end if;

    v_mov := null;
    if v_item.track_inventory then
      if v_condition = 'RESTOCK' then
        v_mov := public._apply_inventory_movement(v_item.variant_id, 'RETURN', v_qty, 0, 0, 'ORDER', p_order_id,
          v_order.order_number, coalesce(p_note, 'Returned to stock'), v_item.unit_cost);
      else
        v_mov := public._apply_inventory_movement(v_item.variant_id, 'DAMAGE', 0, 0, v_qty, 'ORDER', p_order_id,
          v_order.order_number, coalesce(p_note, 'Returned damaged'), v_item.unit_cost);
      end if;
    end if;

    if v_condition = 'RESTOCK' then
      update public.order_items set returned_quantity = returned_quantity + v_qty where id = v_item.id;
      -- Goods back on the shelf after revenue was recognised: reverse their COGS.
      if v_order.delivered_at is not null and v_item.unit_cost > 0 then
        perform public._post_finance('EXPENSE', 'COGS', -public.money(v_item.unit_cost * v_qty),
          (now() at time zone public.store_timezone())::date, false, p_order_id,
          v_order.customer_id, null,
          v_order.order_number, format('COGS reversal: %s × %s returned to stock', v_qty, v_item.sku),
          'order_item:' || v_item.id || ':return:' || coalesce(v_mov.id::text, gen_random_uuid()::text),
          null);
      end if;
    else
      update public.order_items set damaged_quantity = damaged_quantity + v_qty where id = v_item.id;
    end if;
    v_count := v_count + 1;
  end loop;
  return v_count;
end;

_reverse_lost_parcel_finance.src:
declare
  v_n int;
  v_amount numeric;
  v_number text;
begin
  select count(*) into v_n from public.order_status_history where order_id = p_order_id and to_status = 'LOST';
  select amount into v_amount from public.finance_transactions where source_key = 'order:' || p_order_id || ':lost:' || v_n;
  if v_amount is null then
    return;
  end if;
  select order_number into v_number from public.orders where id = p_order_id;
  perform public._post_finance('EXPENSE', 'LOST_PARCELS', -v_amount,
    (now() at time zone public.store_timezone())::date, false, p_order_id, null, null,
    v_number, 'Lost parcel found', 'order:' || p_order_id || ':lost:' || v_n || ':found', null);
end;

_scan_to_ready.src:
declare
  v_order public.orders := p_order;
begin
  if v_order.status in ('PENDING', 'FRAUD_CHECK', 'ADVANCE_REQUIRED', 'FRAUD_REVIEW', 'CONFIRMATION_REQUIRED') then
    raise exception 'VALIDATION: not approved yet (%) — do not pack this parcel', replace(lower(v_order.status::text), '_', ' ')
      using errcode = '22023';
  end if;
  if v_order.status in ('PRODUCTION', 'QUALITY_CHECK') then
    raise exception 'VALIDATION: still in production' using errcode = '22023';
  end if;
  if v_order.status = 'PENDING_CANCEL' then
    raise exception 'VALIDATION: a cancellation was asked for — do not ship' using errcode = '22023';
  end if;
  if v_order.status not in ('CONFIRMED', 'PRE_ORDER', 'PROCESSING', 'PACKING') then
    raise exception 'VALIDATION: a % order cannot be marked ready to ship', replace(lower(v_order.status::text), '_', ' ')
      using errcode = '22023';
  end if;
  if exists (select 1 from public.order_items where order_id = v_order.id and requires_production)
     and not exists (select 1 from public.production_orders where order_id = v_order.id and status = 'READY') then
    raise exception 'VALIDATION: made-to-order items are not ready yet' using errcode = '22023';
  end if;
  if public.setting_bool('fulfillment', array['require_label_before_rts'], false) and v_order.label_printed_at is null then
    raise exception 'VALIDATION: print the shipping label first' using errcode = '22023';
  end if;
  if v_order.status = 'CONFIRMED' then
    v_order := public._transition_order(v_order.id, 'PROCESSING', p_note);
  end if;
  return public._transition_order(v_order.id, 'READY_TO_SHIP', p_note);
end;

_set_shipment_charge.src:
declare
  v_ship public.shipments;
  v_order public.orders;
  v_current numeric;
  v_delta numeric;
  v_id uuid := gen_random_uuid();
  v_txn public.finance_transactions;
  v_label text := case p_kind when 'DELIVERY' then 'Courier delivery fee' when 'RETURN' then 'Courier return charge'
                    when 'COD_FEE' then 'Courier COD fee' else 'Other courier fee' end;
begin
  if p_total is null or p_total < 0 or p_key is null then
    return 0;
  end if;
  select * into v_ship from public.shipments where id = p_shipment_id for update;
  if not found then
    raise exception 'NOT_FOUND: shipment not found' using errcode = 'P0002';
  end if;
  if exists (select 1 from public.shipment_charges where source_key = p_key) then
    return 0;
  end if;
  select coalesce(sum(amount), 0) into v_current from public.shipment_charges
  where shipment_id = p_shipment_id and kind = p_kind;
  v_delta := public.money(p_total) - v_current;
  if v_delta = 0 then
    return 0;
  end if;
  select * into v_order from public.orders where id = v_ship.order_id;
  v_txn := public._post_finance('EXPENSE', public._charge_category(p_kind), v_delta, p_date, true, v_ship.order_id, null, null,
    v_order.order_number,
    coalesce(p_note, v_label) || case when v_current <> 0 then format(' (was %s)', v_current) else '' end,
    'shipment_charge:' || v_id, 'COURIER_COD');
  insert into public.shipment_charges(id, shipment_id, order_id, courier_id, kind, amount, total_after, source, source_key,
                                      note, invoice_id, finance_transaction_id)
  values (v_id, v_ship.id, v_ship.order_id, v_ship.courier_id, p_kind, v_delta, public.money(p_total), p_source, p_key,
          coalesce(p_note, v_label), p_invoice_id, v_txn.id);
  if p_kind = 'DELIVERY' then
    update public.shipments set shipping_cost = public.money(p_total) where id = v_ship.id;
  elsif p_kind = 'RETURN' then
    update public.shipments set return_charge = public.money(p_total) where id = v_ship.id;
  end if;
  return v_delta;
end;

_settings_store_slug.src:
begin
  if new.key = 'storefront' and coalesce(new.value ->> 'mode', 'OWN') = 'OWN' then
    update public.merchants m set slug = public._store_slug_from(m.name, m.id)
    where m.id = new.merchant_id and m.slug is null;
  end if;
  return new;
end;

_settle_invoice_cod.src:
declare
  v_inv public.courier_invoices;
  v_courier text;
  l public.courier_invoice_lines;
  v_order public.orders;
  v_amount numeric;
  v_total numeric := 0;
begin
  select * into v_inv from public.courier_invoices where id = p_invoice_id;
  select name into v_courier from public.couriers where id = v_inv.courier_id;
  for l in select * from public.courier_invoice_lines
           where invoice_id = p_invoice_id and match_status in ('MATCHED', 'MISMATCH') and order_id is not null
             and coalesce(cod_collected, 0) > 0 and settled_at is null
           order by line_no for update loop
    select * into v_order from public.orders where id = l.order_id for update;
    v_amount := least(l.cod_collected, v_order.total_amount - v_order.amount_paid);
    if v_amount > 0 and v_order.status not in ('CANCELLED', 'REJECTED_FRAUD') then
      perform public.record_order_payment(l.order_id, 'COD', 'COURIER_COD', v_amount,
        coalesce(v_inv.invoice_number, 'courier statement'), 'COD paid out by ' || v_courier, 'cod:invoice_line:' || l.id);
      update public.shipments set cod_collected = cod_collected + v_amount, cod_collected_at = now() where id = l.shipment_id;
      v_total := v_total + v_amount;
    end if;
    update public.courier_invoice_lines set settled_at = now() where id = l.id;
  end loop;
  return v_total;
end;

_settle_payment.src:
declare
  v_payment public.payments;
  v_order public.orders;
  v_op public.order_payments;
  v_kind public.order_payment_kind;
begin
  select * into v_payment from public.payments where id = p_payment_id for update;
  select * into v_op from public.order_payments where payment_id = p_payment_id;
  if found then
    return v_op;
  end if;
  if v_payment.status in ('FAILED', 'CANCELLED', 'EXPIRED') then
    raise exception 'VALIDATION: payment % is %', v_payment.reference, v_payment.status using errcode = '22023';
  end if;
  if p_amount is null or p_amount <= 0 then
    raise exception 'VALIDATION: paid amount must be positive' using errcode = '22023';
  end if;

  update public.payments set status = 'SUCCEEDED', verified_at = now(), verified_by = auth.uid()
  where id = p_payment_id;

  v_kind := case v_payment.purpose when 'ADVANCE' then 'ADVANCE' when 'FULL' then 'FULL' else 'BALANCE' end;
  insert into public.order_payments(order_id, payment_id, kind, channel, amount, reference, recorded_by, idempotency_key)
  values (v_payment.order_id, p_payment_id, v_kind, v_payment.channel, public.money(p_amount),
          coalesce(v_payment.provider_transaction_id, v_payment.reference), auth.uid(), 'payment:' || p_payment_id)
  returning * into v_op;

  select * into v_order from public.orders where id = v_payment.order_id;
  perform public._post_finance('INCOME',
    case when v_kind = 'ADVANCE' then 'ADVANCE_PAYMENTS' else 'ONLINE_PAYMENTS' end,
    v_op.amount, (now() at time zone public.store_timezone())::date, true, v_order.id, v_order.customer_id, null,
    v_order.order_number, format('%s payment via %s (%s)', initcap(v_kind::text), v_payment.provider, v_op.reference),
    'order_payment:' || v_op.id, v_payment.channel);

  perform public._order_log(v_order.id, 'PAYMENT_RECEIVED',
    format('%s received via %s', v_op.amount, v_payment.provider), null, null,
    jsonb_build_object('payment_id', p_payment_id, 'amount', v_op.amount, 'reference', v_op.reference));
  perform public._order_payment_after_change(v_order.id, v_kind, v_op.amount);
  return v_op;
end;

_shipment_status_notifications.src:
begin
  if not new.is_active then
    return null;
  end if;
  if new.status = 'OUT_FOR_DELIVERY' and exists (
       select 1 from public.orders o where o.id = new.order_id
         and o.status not in ('DELIVERED', 'PARTIALLY_DELIVERED', 'RETURN_REQUESTED', 'RETURNING', 'RETURNED',
                              'CANCELLED', 'REJECTED_FRAUD', 'LOST')) then
    -- At most one a day: a parcel can go out again after a failed attempt.
    perform public._enqueue_order_notification(new.order_id, 'OUT_FOR_DELIVERY',
      new.id || ':' || (now() at time zone public.store_timezone())::date, null);
  elsif new.status = 'RETURNING' then
    perform public._enqueue_order_notification(new.order_id, 'RETURN_INITIATED', null, null);
  end if;
  return null;
end;

_shipments_tracking_trigger.src:
declare
  v_f public.channel_fulfillments;
begin
  if coalesce(new.consignment_id, new.tracking_number) is not null
     and (old.consignment_id is distinct from new.consignment_id or old.tracking_number is distinct from new.tracking_number) then
    update public.channel_fulfillments set status = 'PENDING', last_error = null
    where order_id = new.order_id and source = 'APP' and status = 'NEEDS_TRACKING'
    returning * into v_f;
    if found then
      perform public.channel_job_enqueue(v_f.channel_id, 'FULFILL', v_f.order_id);
    end if;
  end if;
  return new;
end;

_sms_reserve.src:
declare
  v_policy jsonb := public._usage_policy('SMS');
  v_units int := case when v_policy ->> 'unit' = 'MESSAGE' then 1 else greatest(coalesce(r.segments, 1), 1) end;
  v jsonb;
begin
  v := public._usage_charge(r.merchant_id, 'SMS', v_units, 'sms:' || r.id, r.id::text, false);
  if (v ->> 'allowed')::boolean and not coalesce((v ->> 'duplicate')::boolean, false) then
    update public.notification_logs set
      cost = case v ->> 'charge'
        when 'FREE' then 0 when 'NONE' then 0
        when 'CREDITS' then round((v ->> 'credits')::int * greatest(public.setting_numeric('sms', array['cost_per_sms'], 0.35), 0), 4)
        else cost end,
      cost_source = 'ESTIMATE'
    where id = r.id;
  end if;
  return v;
end;

_store_reset_active.src:
begin
  if coalesce(current_setting('app.store_reset', true), '') = '' or p_merchant is null then
    return false;
  end if;
  return exists (select 1 from public.store_resets r
                 where r.id::text = current_setting('app.store_reset', true) and r.merchant_id::text = p_merchant
                   and r.status = 'RUNNING' and r.txid = txid_current());
end;

_store_slug_from.src:
declare
  v_base text := trim(both '-' from left(regexp_replace(lower(coalesce(p_name, '')), '[^a-z0-9]+', '-', 'g'), 30));
  v_try text;
  v_n int := 1;
begin
  if length(v_base) < 2 then v_base := 'my-shop'; end if;
  if public._store_slug_reserved(v_base) then v_base := v_base || '-shop'; end if;
  v_try := v_base;
  while public._store_slug_problem(v_try, p_merchant) is not null loop
    v_n := v_n + 1;
    v_try := trim(both '-' from left(v_base, 34)) || '-' || v_n;
  end loop;
  return v_try;
end;

_store_slug_problem.src:
begin
  if p_slug is null or p_slug !~ '^[a-z0-9][a-z0-9-]{1,40}$' or p_slug like '%-' or p_slug like '%--%' then
    return 'Use 2 to 41 lower-case letters, numbers and single dashes, starting with a letter or number';
  end if;
  if public._store_slug_reserved(p_slug) then
    return 'This name is reserved';
  end if;
  if exists (select 1 from public.merchants where slug = p_slug and id is distinct from p_merchant) then
    return 'This store name is taken';
  end if;
  return null;
end;

_tenancy_own_functions.src:
declare
  r record;
  v_n int := 0;
begin
  for r in
    select p.oid::regprocedure as sig
    from pg_proc p
    where p.pronamespace = 'public'::regnamespace
      and p.prosecdef
      and p.proowner <> 'app_owner'::regrole
      and not exists (select 1 from public.tenancy_exempt_functions e where e.name = p.proname)
  loop
    execute format('alter function %s owner to app_owner', r.sig);
    v_n := v_n + 1;
  end loop;
  return v_n;
end;

_transition_order.src:
declare
  v_order public.orders;
  v_from public.order_status;
  v_released int;
begin
  select * into v_order from public.orders where id = p_order_id for update;
  if not found then
    raise exception 'NOT_FOUND: order % does not exist', p_order_id using errcode = 'P0002';
  end if;
  v_from := v_order.status;
  if v_from = p_to then
    return v_order;
  end if;
  if not exists (select 1 from public.order_status_transitions where from_status = v_from and to_status = p_to) then
    raise exception 'INVALID_TRANSITION: an order cannot move from % to %', v_from, p_to using errcode = 'P0001';
  end if;

  if p_to = 'SHIPPED' and public.setting_bool('orders', array['require_courier_before_ship'], false)
     and not exists (select 1 from public.shipments where order_id = p_order_id and is_active) then
    raise exception 'VALIDATION: assign a courier before shipping' using errcode = '22023';
  end if;
  if v_from = 'PENDING_CANCEL' and v_order.shipped_at is not null and p_to in ('CANCELLED', 'READY_TO_SHIP') then
    raise exception 'VALIDATION: the courier already picked this parcel up — mark it as returning instead' using errcode = '22023';
  end if;
  if v_from = 'PENDING_CANCEL' and v_order.shipped_at is null and p_to in ('RETURNING', 'RETURNED', 'LOST') then
    raise exception 'VALIDATION: the parcel was never picked up — cancel the order instead' using errcode = '22023';
  end if;

  update public.orders set
    status = p_to,
    confirmed_at = case when p_to = 'CONFIRMED' then coalesce(confirmed_at, now()) else confirmed_at end,
    shipped_at = case when p_to = 'SHIPPED' then coalesce(shipped_at, now()) else shipped_at end,
    delivered_at = case when p_to in ('DELIVERED', 'PARTIALLY_DELIVERED') then coalesce(delivered_at, now()) else delivered_at end,
    cancelled_at = case when p_to in ('CANCELLED', 'REJECTED_FRAUD') then now() else cancelled_at end,
    returned_at = case when p_to = 'RETURNED' then now() else returned_at end,
    lost_at = case when p_to = 'LOST' then now() when v_from = 'LOST' then null else lost_at end,
    cancel_reason = case
      when p_to = 'PENDING_CANCEL' then coalesce(p_note, cancel_reason)
      when p_to = 'CANCELLED' and v_from = 'PENDING_CANCEL' then coalesce(cancel_reason, p_note)
      when p_to in ('CANCELLED', 'REJECTED_FRAUD') then coalesce(p_note, cancel_reason)
      else cancel_reason end,
    advance_due_at = case when p_to = 'ADVANCE_REQUIRED'
      then now() + make_interval(hours => public.setting_numeric('orders', array['advance_payment_timeout_hours'], 24)::int)
      else advance_due_at end
  where id = p_order_id
  returning * into v_order;

  perform public._order_log(p_order_id, 'STATUS_CHANGED', p_note, v_from, p_to, p_metadata,
    p_to in ('CONFIRMED', 'ADVANCE_REQUIRED', 'PROCESSING', 'PRE_ORDER', 'SHIPPED', 'DELIVERED', 'PARTIALLY_DELIVERED',
             'CANCELLED', 'RETURNED', 'READY_TO_SHIP'));

  -- Side effects --------------------------------------------------------------
  if p_to in ('CANCELLED', 'REJECTED_FRAUD') then
    v_released := public._release_order_stock(p_order_id, case when p_to = 'REJECTED_FRAUD'
      then 'Released: order rejected (fraud)' else 'Released: order cancelled' end);
    if v_released > 0 then
      perform public._order_log(p_order_id, 'STOCK_RELEASED', format('%s reservation(s) released', v_released));
    end if;
    update public.coupon_usage set voided_at = now() where order_id = p_order_id and voided_at is null;
    if found then
      update public.coupons c set usage_count = greatest(c.usage_count - 1, 0)
      where c.id = v_order.coupon_id;
    end if;
    update public.payments set status = 'CANCELLED', failure_reason = 'Order cancelled'
    where order_id = p_order_id and status in ('PENDING');
    update public.shipments set status = 'CANCELLED', updated_at = now()
    where order_id = p_order_id and is_active and status in ('PENDING', 'BOOKED', 'ON_HOLD');
    perform public._production_cancel_for_order(p_order_id);
    if p_to = 'CANCELLED' then
      perform public._enqueue_order_notification(p_order_id, 'ORDER_CANCELLED');
    end if;
  elsif p_to = 'ADVANCE_REQUIRED' then
    perform public._enqueue_order_notification(p_order_id, 'ADVANCE_REQUIRED');
  elsif p_to = 'CONFIRMED' then
    perform public._enqueue_order_notification(p_order_id, 'ORDER_CONFIRMED');
  elsif p_to = 'PROCESSING' then
    perform public._production_create_for_order(p_order_id);
  elsif p_to = 'SHIPPED' then
    perform public._commit_order_stock(p_order_id);
    update public.shipments set status = 'IN_TRANSIT', updated_at = now()
    where order_id = p_order_id and is_active and status in ('PENDING', 'BOOKED', 'PICKED_UP', 'FAILED', 'ON_HOLD');
    if v_from <> 'PENDING_CANCEL' then
      perform public._enqueue_order_notification(p_order_id, 'ORDER_SHIPPED');
    end if;
  elsif p_to in ('DELIVERED', 'PARTIALLY_DELIVERED') then
    update public.shipments set status = case when p_to = 'DELIVERED' then 'DELIVERED' else 'PARTIALLY_DELIVERED' end::public.shipment_status,
      delivered_at = coalesce(delivered_at, now()),
      return_status = case when p_to = 'DELIVERED' then 'NONE' else return_status end, updated_at = now()
    where order_id = p_order_id and is_active and status not in ('DELIVERED', 'PARTIALLY_DELIVERED');
    if v_from = 'LOST' then
      perform public._reverse_lost_parcel_finance(p_order_id);
    end if;
    perform public._post_order_delivery_finance(p_order_id);
    if p_to = 'PARTIALLY_DELIVERED' then
      perform public._post_partial_return_finance(p_order_id);
    end if;
    if v_from = 'SHIPPED' then
      perform public._enqueue_order_notification(p_order_id, 'ORDER_DELIVERED');
    end if;
  elsif p_to = 'FAILED_DELIVERY' then
    update public.shipments set status = 'FAILED', updated_at = now()
    where order_id = p_order_id and is_active and status not in ('FAILED', 'RETURNED');
  elsif p_to = 'RETURN_REQUESTED' then
    update public.shipments set return_status = 'REQUESTED', updated_at = now()
    where order_id = p_order_id and is_active and return_status = 'NONE';
  elsif p_to = 'RETURNING' then
    update public.shipments set status = 'RETURNING', return_status = 'IN_TRANSIT', updated_at = now()
    where order_id = p_order_id and is_active and status <> 'RETURNED';
  elsif p_to = 'LOST' then
    perform public._post_lost_parcel_finance(p_order_id);
    perform public._order_log(p_order_id, 'PARCEL_LOST', 'File a claim with the courier and record the compensation in Finance');
  elsif p_to = 'RETURNED' then
    if v_from = 'LOST' then
      perform public._reverse_lost_parcel_finance(p_order_id);
    end if;
    perform public._return_order_stock(p_order_id, null, 'Returned to stock');
    update public.shipments set status = 'RETURNED', return_status = 'RECEIVED', updated_at = now()
    where order_id = p_order_id and is_active;
    perform public._post_order_return_finance(p_order_id);
    perform public._enqueue_order_notification(p_order_id, 'ORDER_RETURNED');
  end if;

  if p_sync_production and p_to in ('PRODUCTION', 'QUALITY_CHECK', 'PACKING', 'READY_TO_SHIP') then
    perform public._production_sync_from_order(p_order_id, p_to);
  end if;

  perform public.refresh_customer_stats(v_order.customer_id);
  select * into v_order from public.orders where id = p_order_id;
  return v_order;
end;

_usage_charge.src:
declare
  st jsonb;
  u public.service_usage;
  e public.credit_ledger;
  v_reason text;
  v_message text;
  v_charge text;
  v_credits int := 0;
  v_name text := case p_service when 'SMS' then 'SMS' else 'BD Courier check' end;
begin
  if p_units is null or p_units < 1 then
    raise exception 'VALIDATION: units must be at least 1' using errcode = '22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_merchant::text || ':' || p_service, 0));
  select * into u from public.service_usage where merchant_id = p_merchant and idempotency_key = p_key;
  if u.id is not null then
    return jsonb_build_object('allowed', u.status in ('RESERVED', 'SUCCEEDED'), 'usage_id', u.id, 'charge', u.charge, 'credits', u.credits,
      'reason', u.denied_reason, 'duplicate', true);
  end if;
  st := public._usage_state(p_merchant, p_service);
  if not (st ->> 'feature_enabled')::boolean then
    v_reason := 'FEATURE_OFF';
    v_message := format('%s is %s', v_name, case st ->> 'feature_state'
      when 'NOT_IN_PLAN' then 'not included in this plan' when 'DISABLED_GLOBALLY' then 'switched off by the platform'
      when 'DISABLED_FOR_MERCHANT' then 'switched off for this account' else 'not available' end);
  elsif st ->> 'access_mode' = 'BLOCKED' then
    v_reason := 'ACCOUNT_RESTRICTED';
    v_message := 'The account is restricted';
  elsif (st ->> 'monthly_cap') is not null and (st ->> 'month_used')::int + p_units > (st ->> 'monthly_cap')::int then
    v_reason := 'LIMIT_REACHED';
    v_message := format('The monthly limit of %s %s is reached', st ->> 'monthly_cap', lower(v_name));
  elsif (st ->> 'unmetered')::boolean then
    v_charge := 'PLAN';
  elsif (st #>> '{free,remaining}')::int >= p_units then
    v_charge := 'FREE';
  elsif st ->> 'after_free' = 'BLOCK' then
    v_reason := 'FREE_LIMIT_REACHED';
    v_message := 'The free allowance is used up';
  elsif (st ->> 'credits_per_unit')::int = 0 then
    v_charge := 'NONE';
  else
    v_credits := p_units * (st ->> 'credits_per_unit')::int;
    if (st ->> 'credits_available')::int < v_credits then
      v_reason := 'NO_CREDITS';
      v_message := format('Not enough %s credits (%s needed, %s available)', lower(st ->> 'credit_type'), v_credits, st ->> 'credits_available');
    else
      v_charge := 'CREDITS';
    end if;
  end if;

  if v_reason is not null then
    if p_record_denial then
      insert into public.service_usage (merchant_id, service, units, status, charge, denied_reason, error, reference, idempotency_key, finished_at)
      values (p_merchant, p_service, p_units, 'DENIED', 'NONE', v_reason, v_message, p_reference, p_key, now())
      returning * into u;
    end if;
    return jsonb_build_object('allowed', false, 'usage_id', u.id, 'reason', v_reason, 'message', v_message);
  end if;

  insert into public.service_usage (merchant_id, service, units, status, charge, credits, credit_type, reference, idempotency_key)
  values (p_merchant, p_service, p_units, 'RESERVED', v_charge, v_credits, case when v_charge = 'CREDITS' then st ->> 'credit_type' end, p_reference, p_key)
  returning * into u;
  if v_charge = 'CREDITS' then
    e := public._credit_post(p_merchant, st ->> 'credit_type', -v_credits, 'USAGE', v_name, null, 'SYSTEM', 'service_usage', u.id::text, 'usage:' || u.id);
    update public.service_usage set ledger_entry_id = e.id where id = u.id;
  end if;
  return jsonb_build_object('allowed', true, 'usage_id', u.id, 'charge', v_charge, 'credits', v_credits);
end;

_usage_finish.src:
declare
  u public.service_usage;
begin
  select * into u from public.service_usage where id = p_usage for update;
  if u.id is null or u.status <> 'RESERVED' then
    return;
  end if;
  if p_success then
    update public.service_usage set status = 'SUCCEEDED', finished_at = now(),
      provider_cost = case when p_provider_cost >= 0 then p_provider_cost else provider_cost end, outcome = coalesce(p_outcome, outcome)
    where id = u.id;
  else
    update public.service_usage set status = 'FAILED', finished_at = now(), error = left(p_error, 500) where id = u.id;
    perform public._usage_refund(u, case u.service when 'SMS' then 'SMS not sent' else 'BD Courier check failed' end);
  end if;
end;

_usage_outcome.src:
declare
  u public.service_usage;
begin
  select * into u from public.service_usage where id = p_usage for update;
  if u.id is null or u.status <> 'SUCCEEDED' or p_outcome not in ('DELIVERED', 'UNDELIVERED') then
    return;
  end if;
  update public.service_usage set outcome = p_outcome,
    provider_cost = case when p_provider_cost >= 0 then p_provider_cost else provider_cost end
  where id = u.id;
  if p_outcome = 'UNDELIVERED' and coalesce((public._usage_policy(u.service) ->> 'refund_undelivered')::boolean, false) then
    perform public._usage_refund(u, 'SMS not delivered');
  end if;
end;

_usage_policy_validate.src:
declare
  f jsonb := coalesce(p -> 'free', '{}'::jsonb);
  v_cap int := nullif(p ->> 'monthly_cap', '')::int;
begin
  if p_service not in ('SMS', 'BD_COURIER') then
    raise exception 'VALIDATION: unknown service' using errcode = '22023';
  end if;
  if coalesce((f ->> 'limit')::int, -1) not between 0 and 1000000 then
    raise exception 'VALIDATION: the free limit must be between 0 and 1,000,000' using errcode = '22023';
  end if;
  if coalesce(f ->> 'period', '') not in ('ONCE', 'MONTH') then
    raise exception 'VALIDATION: the free allowance is once or every month' using errcode = '22023';
  end if;
  if jsonb_typeof(coalesce(f -> 'plans', '[]'::jsonb)) <> 'array' or jsonb_typeof(coalesce(f -> 'statuses', '[]'::jsonb)) <> 'array'
     or jsonb_typeof(coalesce(p -> 'unmetered_plans', '[]'::jsonb)) <> 'array' then
    raise exception 'VALIDATION: plans and statuses are lists' using errcode = '22023';
  end if;
  if exists (select 1 from jsonb_array_elements_text(coalesce(f -> 'statuses', '[]'::jsonb)) s where s not in ('TRIALING', 'ACTIVE', 'PAST_DUE', 'PAUSED')) then
    raise exception 'VALIDATION: free usage can go to trial, active, past-due or paused subscriptions only' using errcode = '22023';
  end if;
  if coalesce(p ->> 'after_free', '') not in ('CREDITS', 'BLOCK') then
    raise exception 'VALIDATION: after the free allowance: charge credits or block' using errcode = '22023';
  end if;
  if coalesce((p ->> 'credits_per_unit')::int, -1) not between 0 and 1000 then
    raise exception 'VALIDATION: credits per use must be between 0 and 1000' using errcode = '22023';
  end if;
  if v_cap is not null and v_cap < 0 then
    raise exception 'VALIDATION: the monthly cap cannot be negative' using errcode = '22023';
  end if;
  if p_service = 'SMS' and coalesce(p ->> 'unit', '') not in ('SEGMENT', 'MESSAGE') then
    raise exception 'VALIDATION: an SMS use is one part or one message' using errcode = '22023';
  end if;
  if p_service = 'SMS' and coalesce((p ->> 'hold_hours')::int, -1) not between 0 and 72 then
    raise exception 'VALIDATION: messages can wait for credits 0 to 72 hours' using errcode = '22023';
  end if;
  return jsonb_build_object(
    'free', jsonb_build_object('enabled', coalesce((f ->> 'enabled')::boolean, false), 'limit', (f ->> 'limit')::int, 'period', f ->> 'period',
      'plans', coalesce(f -> 'plans', '[]'::jsonb), 'statuses', coalesce(f -> 'statuses', '[]'::jsonb)),
    'unit', case when p_service = 'SMS' then p ->> 'unit' else 'LOOKUP' end,
    'after_free', p ->> 'after_free', 'credits_per_unit', (p ->> 'credits_per_unit')::int, 'monthly_cap', v_cap,
    'unmetered_plans', coalesce(p -> 'unmetered_plans', '[]'::jsonb))
    || case when p_service = 'SMS' then jsonb_build_object('refund_undelivered', coalesce((p ->> 'refund_undelivered')::boolean, false),
                                                           'hold_hours', (p ->> 'hold_hours')::int) else '{}'::jsonb end;
end;

_usage_refund.src:
begin
  if u.refunded_at is not null then
    return;
  end if;
  if u.charge = 'CREDITS' and u.credits > 0 and u.ledger_entry_id is not null then
    perform public._credit_post(u.merchant_id, u.credit_type, u.credits, 'REFUND', p_reason, null, 'SYSTEM', 'service_usage', u.id::text,
      'refund:' || u.id, null, jsonb_build_object('refund_of', u.ledger_entry_id));
  end if;
  update public.service_usage set refunded_at = now() where id = u.id;
end;

_usage_state.src:
declare
  v_policy jsonb := public._usage_policy(p_service);
  v_free jsonb := coalesce(v_policy -> 'free', '{}'::jsonb);
  o public.merchant_service_overrides;
  v_ent jsonb := public.merchant_entitlements(p_merchant) -> public._usage_feature(p_service);
  v_plan text;
  v_sub_status text;
  v_mode text := public.merchant_access_mode(p_merchant);
  v_tz text := coalesce((select timezone from public.merchants where id = p_merchant), 'Asia/Dhaka');
  v_month timestamptz;
  v_type text := case p_service when 'SMS' then 'SMS' else 'COURIER' end;
  v_eligible boolean;
  v_limit int;
  v_used int;
  v_month_used int;
  v_cap int;
begin
  v_month := date_trunc('month', now() at time zone v_tz) at time zone v_tz;
  select * into o from public.merchant_service_overrides where merchant_id = p_merchant and service = p_service;
  select p.code, s.status into v_plan, v_sub_status
  from public.subscriptions s join public.plans p on p.id = s.plan_id where s.merchant_id = p_merchant and s.ended_at is null;
  v_limit := coalesce(o.free_limit, nullif(v_free ->> 'limit', '')::int, 0);
  -- An explicit merchant limit is a decision for that merchant; otherwise plan and status decide.
  v_eligible := v_mode <> 'BLOCKED' and (
    o.free_limit is not null
    or (coalesce((v_free ->> 'enabled')::boolean, false)
        and (jsonb_array_length(coalesce(v_free -> 'plans', '[]'::jsonb)) = 0 or (v_free -> 'plans') ? coalesce(v_plan, ''))
        and coalesce(v_free -> 'statuses', '["ACTIVE"]'::jsonb) ? coalesce(v_sub_status, 'NONE')));
  select coalesce(sum(units) filter (where charge = 'FREE' and (v_free ->> 'period' = 'ONCE' or created_at >= v_month)), 0),
         coalesce(sum(units) filter (where created_at >= v_month), 0)
  into v_used, v_month_used
  from public.service_usage
  where merchant_id = p_merchant and service = p_service and status in ('RESERVED', 'SUCCEEDED') and refunded_at is null;
  v_cap := coalesce(o.monthly_cap, nullif(v_policy ->> 'monthly_cap', '')::int);
  return jsonb_build_object(
    'service', p_service,
    'feature', public._usage_feature(p_service),
    'feature_state', coalesce(v_ent ->> 'state', 'NOT_IN_PLAN'),
    'feature_enabled', coalesce((v_ent ->> 'enabled')::boolean, false),
    'plan', v_plan,
    'subscription_status', v_sub_status,
    'access_mode', v_mode,
    'unmetered', coalesce(v_policy -> 'unmetered_plans', '[]'::jsonb) ? coalesce(v_plan, ''),
    'unit', coalesce(v_policy ->> 'unit', case p_service when 'SMS' then 'SEGMENT' else 'LOOKUP' end),
    'free', jsonb_build_object('eligible', v_eligible, 'limit', v_limit, 'used', v_used,
      'remaining', case when v_eligible then greatest(v_limit - v_used, 0) else 0 end,
      'period', coalesce(v_free ->> 'period', 'MONTH'), 'merchant_limit', o.free_limit),
    'month_used', v_month_used,
    'monthly_cap', v_cap,
    'after_free', coalesce(v_policy ->> 'after_free', 'CREDITS'),
    'credits_per_unit', coalesce((v_policy ->> 'credits_per_unit')::int, 1),
    'credit_type', v_type,
    'credits_available', public.credit_available(p_merchant, v_type),
    'sender_id', o.sender_id);
end;

_vd_apply_package.src:
declare
  v_pkg public.pbx_packages;
  cur public.pbx_subscriptions;
  v_start timestamptz := now();
  s public.pbx_subscriptions;
begin
  select * into v_pkg from public.pbx_packages where id = t.package_id;
  select * into cur from public.pbx_subscriptions
  where business_id = t.business_id and status = 'ACTIVE' and expires_at > now() order by expires_at desc limit 1;
  if cur.id is not null and cur.package_id = t.package_id and cur.extra_agents = t.extra_agents and cur.extra_channels = t.extra_channels then
    -- Same plan: the new months follow the current ones.
    v_start := cur.expires_at;
  elsif cur.id is not null then
    -- A different plan starts now and replaces the current one.
    update public.pbx_subscriptions set status = 'REPLACED' where business_id = t.business_id and status = 'ACTIVE' and expires_at > now();
  end if;
  insert into public.pbx_subscriptions(business_id, package_id, agents, channels, extra_agents, extra_channels, months, amount_tk,
    starts_at, expires_at, source, bkash_transaction_id, created_by)
  values (t.business_id, t.package_id, v_pkg.agent_limit + t.extra_agents, v_pkg.concurrent_channels + t.extra_channels,
    t.extra_agents, t.extra_channels, t.months, t.amount_tk, v_start, v_start + make_interval(months => t.months), 'BKASH', t.id, t.created_by)
  returning * into s;
  return s;
end;

_vd_business.src:
declare
  v_mine uuid := public._vd_my_business();
begin
  if p_business_id is null or p_business_id = v_mine then
    if v_mine is null then
      raise exception 'NOT_FOUND: no business is set up for VoiceDrive PBX' using errcode = 'P0002';
    end if;
    return v_mine;
  end if;
  if not public._vd_is_super() then
    raise exception 'PERMISSION_DENIED: you can only manage your own business' using errcode = '42501';
  end if;
  if not exists (select 1 from public.pbx_businesses where id = p_business_id) then
    raise exception 'NOT_FOUND: business not found' using errcode = 'P0002';
  end if;
  return p_business_id;
end;

_vd_ledger_add.src:
declare
  v_balance numeric;
  v_row public.pbx_ledger;
begin
  insert into public.pbx_outgoing_balances(business_id, balance_tk) values (p_business_id, 0) on conflict do nothing;
  update public.pbx_outgoing_balances set balance_tk = balance_tk + p_amount, updated_at = now()
  where business_id = p_business_id returning balance_tk into v_balance;
  insert into public.pbx_ledger(business_id, kind, amount_tk, balance_after_tk, call_id, bkash_transaction_id, note, created_by)
  values (p_business_id, p_kind, p_amount, v_balance, p_call_id, p_bkash, p_note, auth.uid())
  returning * into v_row;
  return v_row;
end;

_vd_line_problems.src:
declare
  b public.pbx_businesses;
  v text[] := '{}';
begin
  select * into b from public.pbx_businesses where id = p_business_id;
  if b.id is null then return array['NOT_FOUND']; end if;
  if not b.pbx_enabled then v := array_append(v, 'NOT_ENABLED'); end if;
  if b.did is null or b.trunk_host is null then v := array_append(v, 'NO_NUMBER'); end if;
  if not b.bridge_ready then v := array_append(v, 'BRIDGE_NOT_READY'); end if;
  if not (public._vd_limits(b.id) ->> 'active')::boolean then v := array_append(v, 'NO_PACKAGE'); end if;
  if public._vd_maintenance() ->> 'state' = 'active' then v := array_append(v, 'MAINTENANCE'); end if;
  return v;
end;

_vd_my_call.src:
declare
  c public.pbx_call_records;
begin
  select * into c from public.pbx_call_records where id = p_call_id;
  if c.id is null or not (c.agent_id = (public._vd_my_agent()).id
      or (c.business_id = public._vd_my_business() and public.has_permission('pbx.manage'))) then
    raise exception 'NOT_FOUND: call not found' using errcode = 'P0002';
  end if;
  return c;
end;

_vd_require_super.src:
begin
  if not public._vd_is_super() then
    raise exception 'PERMISSION_DENIED: PBX lines, packages and balances are set up by the platform team' using errcode = '42501';
  end if;
end;

_vd_require_system.src:
begin
  if not public.is_system_context() then
    raise exception 'PERMISSION_DENIED' using errcode = '42501';
  end if;
end;

_vd_start_order_call.src:
declare
  o record;
begin
  perform public.require_permission('orders.view');
  select id, customer_phone, merged_into into o from public.orders where id = p_order_id;
  if o.id is null then
    raise exception 'NOT_FOUND: order not found' using errcode = 'P0002';
  end if;
  if coalesce(o.customer_phone, '') = '' then
    raise exception 'VALIDATION: this order has no phone number' using errcode = '22023';
  end if;
  return public._vd_start_outbound(o.customer_phone, p_kind, o.id, null);
end;

_vd_start_outbound.src:
declare
  a public.pbx_agents;
  b public.pbx_businesses;
  v_problems text[];
  v_phone text := public.normalize_phone(p_phone);
  v_row public.pbx_call_records;
  v_cust uuid;
  v_balance numeric;
begin
  perform public.require_permission('pbx.call');
  a := public._vd_my_agent();
  if a.id is null or not a.active then
    raise exception 'VALIDATION: you have no active phone extension' using errcode = '22023';
  end if;
  if v_phone is null or v_phone !~ '^0[0-9]{9,12}$' then
    raise exception 'VALIDATION: enter a Bangladeshi phone number like 01XXXXXXXXX' using errcode = '22023';
  end if;
  select * into b from public.pbx_businesses where id = a.business_id;
  v_problems := public._vd_line_problems(b.id);
  if cardinality(v_problems) > 0 then
    raise exception 'VALIDATION: the phone line is not active (%)', array_to_string(v_problems, ', ') using errcode = '22023';
  end if;
  if not public._vd_seated(a.id) then
    raise exception 'VALIDATION: all paid agent seats are in use' using errcode = '22023';
  end if;
  v_balance := public._vd_balance(b.id);
  if v_balance <= 0 then
    raise exception 'VALIDATION: outgoing balance is empty — recharge with bKash' using errcode = '22023';
  end if;
  if (select count(*) from public.pbx_channel_holds where business_id = b.id) >= (public._vd_limits(b.id) ->> 'channels')::int then
    raise exception 'VALIDATION: all % call channels are busy — try again in a moment', (public._vd_limits(b.id) ->> 'channels') using errcode = '22023';
  end if;
  -- One open request per agent: an older one that never dialled is cancelled.
  update public.pbx_call_records set status = 'CANCELLED', reject_reason = 'REPLACED', ended_at = now()
  where agent_id = a.id and status = 'REQUESTED';
  select id into v_cust from public.customers where phone = v_phone limit 1;
  insert into public.pbx_call_records(business_id, agent_id, direction, kind, order_id, customer_id, callback_of,
    customer_phone, normalized_customer_phone, caller_id, did, agent_extension, status, created_by)
  values (b.id, a.id, 'OUTBOUND', p_kind, p_order_id, v_cust, p_callback_of, left(p_phone, 40), v_phone,
    coalesce(b.caller_id, b.did), b.did, a.extension, 'REQUESTED', auth.uid())
  returning * into v_row;
  return public._vd_call_json(v_row) || jsonb_build_object('dial', v_phone, 'expiresInSeconds', 120);
end;

_vd_telemetry.src:
declare
  a public.pbx_agents;
begin
  perform public.require_permission('pbx.call');
  a := public._vd_my_agent();
  if a.id is null then return; end if;
  if p_call_id is not null and not exists (select 1 from public.pbx_call_records where id = p_call_id and business_id = a.business_id) then
    p_call_id := null;
  end if;
  if (select count(*) from public.pbx_call_telemetry where agent_id = a.id and created_at > now() - interval '1 minute') >= 120 then
    return;
  end if;
  insert into public.pbx_call_telemetry(business_id, agent_id, call_id, kind, event, detail)
  values (a.business_id, a.id, p_call_id, p_kind, left(coalesce(nullif(p_event, ''), 'event'), 60),
    case when length(coalesce(p_detail, '{}'::jsonb)::text) > 4000 then jsonb_build_object('truncated', true) else coalesce(p_detail, '{}'::jsonb) end);
end;

abandoned_counts.src:
begin
  perform public.require_permission('orders.view');
  return jsonb_build_object(
    'store', (select count(*) from public.store_carts where status = 'ACTIVE' and item_count > 0
              and last_activity_at < now() - public._abandoned_after() and last_activity_at > now() - interval '7 days'),
    'shopify', (select count(*) from public.shopify_abandoned_checkouts where status = 'OPEN' and follow_up = 'NONE'
                and shop_created_at > now() - interval '7 days'));
end;

ad_account_record_sync.src:
begin
  perform public._require_system();
  update public.ad_accounts set last_sync_at = now(), last_sync_status = p_status, last_sync_error = left(p_error, 500),
    last_sync_since = p_since, last_sync_until = p_until
  where id = p_id;
end;

ad_account_update.src:
declare
  v_old public.ad_accounts;
  v_row public.ad_accounts;
  v_range record;
begin
  perform public.require_permission('marketing.manage');
  select * into v_old from public.ad_accounts where id = p_id for update;
  if not found then
    raise exception 'NOT_FOUND: ad account not found' using errcode = 'P0002';
  end if;
  if v_old.is_manager and coalesce((p ->> 'is_selected')::boolean, false) then
    raise exception 'VALIDATION: a manager account has no campaigns of its own; choose its client accounts' using errcode = '22023';
  end if;
  if (p ? 'usd_rate') and coalesce((p ->> 'usd_rate')::numeric, 0) <= 0 then
    raise exception 'VALIDATION: the rate must be more than 0' using errcode = '22023';
  end if;
  if (p ? 'tax_percent') and ((p ->> 'tax_percent')::numeric < 0 or (p ->> 'tax_percent')::numeric > 100) then
    raise exception 'VALIDATION: VAT must be between 0 and 100%%' using errcode = '22023';
  end if;
  update public.ad_accounts set
    is_selected = coalesce((p ->> 'is_selected')::boolean, is_selected),
    usd_rate = coalesce((p ->> 'usd_rate')::numeric, usd_rate),
    tax_percent = coalesce((p ->> 'tax_percent')::numeric, tax_percent)
  where id = p_id returning * into v_row;

  if (v_old.usd_rate, v_old.tax_percent) is distinct from (v_row.usd_rate, v_row.tax_percent) then
    update public.ad_platform_stats set cost = round(spend * public._ad_account_factor(v_row), 2) where account_id = p_id;
    select min(date) as since, max(date) as until into v_range from public.ad_platform_stats where account_id = p_id;
    if v_range.since is not null then
      perform public._ad_refresh_marketing_spend(p_id, v_range.since, v_range.until);
    end if;
  end if;
  perform public.log_audit('ad_account.updated', 'ad_account', p_id::text, to_jsonb(v_old), to_jsonb(v_row), '{}'::jsonb);
  return v_row;
end;

ad_accounts_for_sync.src:
begin
  perform public._require_system();
  return coalesce((select jsonb_agg(to_jsonb(a) || jsonb_build_object('connection_status', c.status) order by a.created_at)
    from public.ad_accounts a join public.ad_connections c on c.id = a.connection_id
    where c.status <> 'DISCONNECTED'
      and (p_account_id is null and a.is_selected and not a.is_manager
           and (p_platform is null or a.platform = upper(p_platform)) or a.id = p_account_id)), '[]'::jsonb);
end;

ad_app_set.src:
declare
  v_key text := lower(p_platform);
  v_value jsonb;
begin
  perform public._require_system();
  if v_key not in ('tiktok', 'google') then
    raise exception 'VALIDATION: unknown platform' using errcode = '22023';
  end if;
  update public.settings set value = jsonb_set(value, array[v_key], coalesce(value -> v_key, '{}'::jsonb) || coalesce(p, '{}'::jsonb)),
    updated_by = p_actor
  where key = 'ad_platforms' returning value into v_value;
  insert into public.audit_logs(actor_id, actor_email, action, entity_type, entity_id, new_values)
  values (p_actor, (select email from public.profiles where id = p_actor), 'ad_app.saved', 'integration', 'ads.' || v_key, p);
  return v_value -> v_key;
end;

ad_connection_disconnect.src:
begin
  perform public._require_system();
  update public.ad_connections set status = 'DISCONNECTED', token_hint = null where id = p_id;
  if not found then
    raise exception 'NOT_FOUND: connection not found' using errcode = 'P0002';
  end if;
  update public.ad_accounts set is_selected = false where connection_id = p_id;
  insert into public.audit_logs(actor_id, actor_email, action, entity_type, entity_id)
  values (p_actor, (select email from public.profiles where id = p_actor), 'ad_connection.disconnected', 'ad_connection', p_id::text);
end;

ad_connection_failed.src:
begin
  perform public._require_system();
  update public.ad_connections set status = 'FAILED', last_error = left(p_error, 500) where id = p_id and status <> 'DISCONNECTED';
end;

ad_connection_save.src:
declare
  v_platform text := upper(p_platform);
  v_conn public.ad_connections;
  v_accounts jsonb := coalesce(p -> 'accounts', '[]'::jsonb);
  v_auto boolean;
begin
  perform public._require_system();
  select * into v_conn from public.ad_connections
  where platform = v_platform and status <> 'DISCONNECTED' and lower(external_user) = lower(p ->> 'external_user');
  if found then
    update public.ad_connections set display_name = coalesce(p ->> 'display_name', display_name), token_hint = p ->> 'token_hint',
      status = 'CONNECTED', last_error = null, connected_by = p_actor, connected_at = now()
    where id = v_conn.id returning * into v_conn;
  else
    insert into public.ad_connections(platform, external_user, display_name, token_hint, connected_by)
    values (v_platform, nullif(p ->> 'external_user', ''), p ->> 'display_name', p ->> 'token_hint', p_actor)
    returning * into v_conn;
  end if;

  v_auto := v_platform = 'TIKTOK'
    or (select count(*) from jsonb_array_elements(v_accounts) a where not coalesce((a ->> 'is_manager')::boolean, false)) = 1;
  insert into public.ad_accounts(platform, connection_id, external_id, login_customer_id, name, currency, timezone, is_manager, is_selected)
  select v_platform, v_conn.id, regexp_replace(a ->> 'external_id', '\D', '', 'g'), nullif(regexp_replace(coalesce(a ->> 'login_customer_id', ''), '\D', '', 'g'), ''),
         left(a ->> 'name', 200), upper(a ->> 'currency'), a ->> 'timezone', coalesce((a ->> 'is_manager')::boolean, false),
         v_auto and not coalesce((a ->> 'is_manager')::boolean, false)
  from jsonb_array_elements(v_accounts) a
  where regexp_replace(coalesce(a ->> 'external_id', ''), '\D', '', 'g') ~ '^[0-9]{3,32}$'
  on conflict (platform, external_id) do update set
    connection_id = excluded.connection_id, login_customer_id = excluded.login_customer_id,
    name = coalesce(excluded.name, ad_accounts.name), currency = coalesce(excluded.currency, ad_accounts.currency),
    timezone = coalesce(excluded.timezone, ad_accounts.timezone), is_manager = excluded.is_manager;

  insert into public.audit_logs(actor_id, actor_email, action, entity_type, entity_id, new_values)
  values (p_actor, (select email from public.profiles where id = p_actor), 'ad_connection.connected', 'ad_connection', v_conn.id::text,
          jsonb_build_object('platform', v_platform, 'user', v_conn.external_user, 'accounts', jsonb_array_length(v_accounts)));
  return to_jsonb(v_conn);
end;

ad_oauth_state_create.src:
begin
  perform public._require_system();
  if p_return_to !~ '^https?://[^/]+/admin(/|$|\?)' then
    raise exception 'VALIDATION: invalid return address' using errcode = '22023';
  end if;
  insert into public.ad_oauth_states(state, platform, created_by, return_to, expires_at)
  values (p_state, upper(p_platform), p_actor, p_return_to, now() + interval '15 minutes');
end;

ad_oauth_state_take.src:
declare
  v_row public.ad_oauth_states;
begin
  perform public._require_system();
  update public.ad_oauth_states set used_at = now()
  where state = p_state and platform = upper(p_platform) and used_at is null and expires_at > now()
  returning * into v_row;
  if not found then
    return null;
  end if;
  return jsonb_build_object('created_by', v_row.created_by, 'return_to', v_row.return_to);
end;

ad_platform_apply_sync.src:
declare
  v_acc public.ad_accounts;
  v_since date := (p ->> 'since')::date;
  v_until date := (p ->> 'until')::date;
  v_factor numeric;
  v_campaigns int;
  v_rows int;
  v_zeroed int;
  v_spend_rows int;
begin
  perform public._require_system();
  select * into v_acc from public.ad_accounts where id = (p ->> 'account_id')::uuid;
  if not found then
    raise exception 'NOT_FOUND: ad account not found' using errcode = 'P0002';
  end if;
  if v_since is null or v_until is null or v_until < v_since or v_until - v_since > 120 then
    raise exception 'VALIDATION: sync window must be 1 to 120 days' using errcode = '22023';
  end if;
  v_factor := public._ad_account_factor(v_acc);

  insert into public.marketing_campaigns(platform, name, external_id, utm_campaign, status, source, ad_account_id)
  select v_acc.platform::public.marketing_platform, left(coalesce(nullif(c ->> 'name', ''), 'Campaign ' || (c ->> 'id')), 200), c ->> 'id',
         left(coalesce(nullif(c ->> 'name', ''), c ->> 'id'), 200),
         case when upper(coalesce(c ->> 'status', '')) in ('ENABLE', 'ENABLED', 'ACTIVE', 'CAMPAIGN_STATUS_ENABLE') then 'ACTIVE'
              when upper(coalesce(c ->> 'status', '')) in ('DISABLE', 'PAUSED', 'CAMPAIGN_STATUS_DISABLE') then 'PAUSED'
              else 'ENDED' end::public.campaign_status,
         'API', v_acc.id
  from (select distinct on (x ->> 'id') x from jsonb_array_elements(coalesce(p -> 'campaigns', '[]'::jsonb)) x
        where x ->> 'id' ~ '^[0-9]{1,32}$') d(c)
  on conflict (platform, external_id) do update set
    name = excluded.name, utm_campaign = excluded.utm_campaign, status = excluded.status, ad_account_id = excluded.ad_account_id,
    source = 'API', updated_at = now();
  get diagnostics v_campaigns = row_count;

  -- Campaigns only seen in the numbers (deleted since) keep a name.
  insert into public.marketing_campaigns(platform, name, external_id, utm_campaign, status, source, ad_account_id)
  select distinct v_acc.platform::public.marketing_platform, 'Campaign ' || (d ->> 'campaign_id'), d ->> 'campaign_id', d ->> 'campaign_id',
         'ENDED'::public.campaign_status, 'API'::public.data_source, v_acc.id
  from jsonb_array_elements(coalesce(p -> 'days', '[]'::jsonb)) d
  where d ->> 'campaign_id' ~ '^[0-9]{1,32}$'
  on conflict (platform, external_id) do nothing;

  with rows as (
    select d ->> 'campaign_id' as campaign_id, (d ->> 'date')::date as date,
           sum(greatest(coalesce(nullif(d ->> 'spend', '')::numeric, 0), 0)) as spend,
           sum(coalesce(nullif(d ->> 'impressions', '')::numeric, 0))::bigint as impressions,
           sum(coalesce(nullif(d ->> 'clicks', '')::numeric, 0))::bigint as clicks,
           sum(coalesce(nullif(d ->> 'conversions', '')::numeric, 0)) as conversions,
           sum(coalesce(nullif(d ->> 'conversion_value', '')::numeric, 0)) as conversion_value
    from jsonb_array_elements(coalesce(p -> 'days', '[]'::jsonb)) d
    where d ->> 'campaign_id' ~ '^[0-9]{1,32}$' and (d ->> 'date')::date between v_since and v_until
    group by 1, 2
  )
  insert into public.ad_platform_stats(account_id, campaign_id, date, spend, cost, impressions, clicks, conversions, conversion_value, synced_at)
  select v_acc.id, campaign_id, date, round(spend, 2), round(spend * v_factor, 2), impressions, clicks, round(conversions, 2), round(conversion_value, 2), now()
  from rows
  on conflict (account_id, campaign_id, date) do update set
    spend = excluded.spend, cost = excluded.cost, impressions = excluded.impressions, clicks = excluded.clicks,
    conversions = excluded.conversions, conversion_value = excluded.conversion_value, synced_at = now();
  get diagnostics v_rows = row_count;

  with keep as (
    select distinct d ->> 'campaign_id' as campaign_id, (d ->> 'date')::date as date
    from jsonb_array_elements(coalesce(p -> 'days', '[]'::jsonb)) d
  )
  update public.ad_platform_stats s set spend = 0, cost = 0, impressions = 0, clicks = 0, conversions = 0, conversion_value = 0, synced_at = now()
  where s.account_id = v_acc.id and s.date between v_since and v_until and (s.spend > 0 or s.impressions > 0)
    and not exists (select 1 from keep k where k.campaign_id = s.campaign_id and k.date = s.date);
  get diagnostics v_zeroed = row_count;

  v_spend_rows := public._ad_refresh_marketing_spend(v_acc.id, v_since, v_until);
  return jsonb_build_object('campaigns', v_campaigns, 'rows', v_rows, 'zeroed', v_zeroed, 'spend_days_changed', v_spend_rows,
    'cost', (select coalesce(sum(cost), 0) from public.ad_platform_stats where account_id = v_acc.id and date between v_since and v_until));
end;

ad_platform_overview.src:
declare
  v_platform text := upper(p_platform);
  v_from date := public._local_date(now()) - 29;
begin
  perform public.require_permission('marketing.view');
