add_order_note.src:
declare
  v_note public.order_notes;
begin
  perform public.require_permission('orders.update');
  if length(trim(coalesce(p_body, ''))) = 0 then
    raise exception 'VALIDATION: note cannot be empty' using errcode = '22023';
  end if;
  insert into public.order_notes(order_id, kind, visibility, body, created_by, created_by_name)
  values (p_order_id, p_kind, p_visibility, trim(p_body), auth.uid(), public.actor_display_name())
  returning * into v_note;
  if p_kind = 'CONTACT' then
    perform public._order_log(p_order_id, 'CUSTOMER_CONTACTED', trim(p_body));
  end if;
  return v_note;
end;

adjust_stock.src:
declare
  v_inv public.inventory;
  v_delta int;
  v_mov public.inventory_movements;
begin
  perform public.require_permission('inventory.adjust');
  if p_quantity is null or p_quantity < 0 or (p_quantity = 0 and upper(coalesce(p_mode, '')) <> 'SET') then
    raise exception 'VALIDATION: quantity must be a positive number' using errcode = '22023';
  end if;
  if length(trim(coalesce(p_note, ''))) = 0 then
    raise exception 'VALIDATION: a reason/note is required for stock adjustments' using errcode = '22023';
  end if;

  select * into v_inv from public.inventory where variant_id = p_variant_id for update;
  if not found then
    raise exception 'NOT_FOUND: variant % has no inventory record', p_variant_id using errcode = 'P0002';
  end if;

  case p_type
    when 'ADJUSTMENT' then
      v_delta := case upper(p_mode)
        when 'ADD' then p_quantity
        when 'REMOVE' then -p_quantity
        when 'SET' then p_quantity - v_inv.on_hand
        else null end;
      if v_delta is null then
        raise exception 'VALIDATION: mode must be ADD, REMOVE or SET' using errcode = '22023';
      end if;
      if v_delta = 0 then
        raise exception 'VALIDATION: stock is already %', p_quantity using errcode = '22023';
      end if;
      if v_delta < 0 and v_inv.available + v_delta < 0 and not public.allow_overselling() then
        raise exception 'INSUFFICIENT_STOCK: only % available (% reserved for orders)', v_inv.available, v_inv.reserved
          using errcode = 'P0001';
      end if;
      v_mov := public._apply_inventory_movement(p_variant_id, 'ADJUSTMENT', v_delta, 0, 0, 'ADJUSTMENT', null, null, p_note, p_unit_cost);
    when 'PURCHASE' then
      v_mov := public._apply_inventory_movement(p_variant_id, 'PURCHASE', p_quantity, 0, 0, 'ADJUSTMENT', null, null, p_note, p_unit_cost);
    when 'DAMAGE' then
      if v_inv.available - p_quantity < 0 and not public.allow_overselling() then
        raise exception 'INSUFFICIENT_STOCK: only % available', v_inv.available using errcode = 'P0001';
      end if;
      v_mov := public._apply_inventory_movement(p_variant_id, 'DAMAGE', -p_quantity, 0, p_quantity, 'ADJUSTMENT', null, null, p_note);
    when 'LOSS' then
      if v_inv.available - p_quantity < 0 and not public.allow_overselling() then
        raise exception 'INSUFFICIENT_STOCK: only % available', v_inv.available using errcode = 'P0001';
      end if;
      v_mov := public._apply_inventory_movement(p_variant_id, 'LOSS', -p_quantity, 0, 0, 'ADJUSTMENT', null, null, p_note);
    when 'TRANSFER' then
      v_mov := public._apply_inventory_movement(p_variant_id, 'TRANSFER', p_quantity, 0, -p_quantity, 'ADJUSTMENT', null, null, p_note);
    else
      raise exception 'VALIDATION: % cannot be recorded manually', p_type using errcode = '22023';
  end case;

  perform public.log_audit('stock.adjusted', 'product_variant', p_variant_id::text,
    jsonb_build_object('on_hand', v_inv.on_hand, 'damaged', v_inv.damaged),
    jsonb_build_object('on_hand', v_mov.on_hand_after, 'damaged', v_mov.damaged_after),
    jsonb_build_object('type', p_type, 'mode', p_mode, 'quantity', p_quantity, 'note', p_note, 'movement_id', v_mov.id));
  return v_mov;
end;

admin_api_key_create.src:
declare
  v_scopes text[];
  v_key text;
  v_row public.api_keys;
begin
  perform public.require_permission('settings.manage');
  perform public.require_feature('external_api');
  select coalesce(array_agg(distinct lower(trim(s)) order by lower(trim(s))), '{}') into v_scopes from unnest(coalesce(p_scopes, '{}')) s where trim(s) <> '';
  if cardinality(v_scopes) = 0 then
    raise exception 'VALIDATION: choose what this key may do' using errcode = '22023';
  end if;
  if not v_scopes <@ array['orders:read', 'orders:write', 'products:read', 'inventory:read', 'inventory:write', 'customers:read'] then
    raise exception 'VALIDATION: unknown permission in %', array_to_string(v_scopes, ', ') using errcode = '22023';
  end if;
  if p_expires_at is not null and p_expires_at <= now() then
    raise exception 'VALIDATION: the expiry date must be in the future' using errcode = '22023';
  end if;
  v_key := 'ffl_live_' || encode(extensions.gen_random_bytes(24), 'hex');
  insert into public.api_keys (name, prefix, key_hash, scopes, expires_at, created_by)
  values (trim(p_name), left(v_key, 15), encode(extensions.digest(v_key, 'sha256'), 'hex'), v_scopes, p_expires_at, auth.uid())
  returning * into v_row;
  perform public.log_audit('api_key.create', 'api_key', v_row.id::text, null,
    jsonb_build_object('name', v_row.name, 'scopes', to_jsonb(v_row.scopes), 'expires_at', v_row.expires_at));
  -- The only time the full key leaves the database.
  return jsonb_build_object('id', v_row.id, 'key', v_key, 'prefix', v_row.prefix, 'scopes', to_jsonb(v_row.scopes));
end;

admin_api_key_revoke.src:
begin
  perform public.require_permission('settings.manage');
  update public.api_keys set revoked_at = now(), revoked_by = auth.uid() where id = p_id and revoked_at is null;
  if not found then
    raise exception 'NOT_FOUND: key not found or already turned off' using errcode = 'P0002';
  end if;
  perform public.log_audit('api_key.revoke', 'api_key', p_id::text, null, null);
end;

admin_api_keys.src:
begin
  perform public.require_permission('settings.view');
  return coalesce((select jsonb_agg(jsonb_build_object('id', k.id, 'name', k.name, 'prefix', k.prefix, 'scopes', to_jsonb(k.scopes),
      'expires_at', k.expires_at, 'created_at', k.created_at, 'last_used_at', k.last_used_at, 'request_count', k.request_count,
      'revoked_at', k.revoked_at, 'created_by', (select full_name from public.profiles p where p.id = k.created_by))
    order by k.revoked_at nulls first, k.created_at desc) from public.api_keys k), '[]'::jsonb);
end;

admin_api_logs.src:
begin
  perform public.require_permission('settings.view');
  return coalesce((select jsonb_agg(to_jsonb(x) order by x.created_at desc) from (
    select l.id, l.key_id, k.name as key_name, l.method, l.path, l.status, l.duration_ms, l.error_code, l.created_at
    from public.api_request_logs l left join public.api_keys k on k.id = l.key_id
    where p_key is null or l.key_id = p_key
    order by l.created_at desc limit least(greatest(coalesce(p_limit, 100), 1), 500)) x), '[]'::jsonb);
end;

admin_auto_merge_scan.src:
declare
  v_id uuid;
  v_merged int := 0;
begin
  perform public.require_permission('orders.update');
  for v_id in
    select o.id from public.orders o
    where o.confirmed_at is null and o.merged_into is null and o.status in ('PENDING', 'CONFIRMATION_REQUIRED')
      and exists (select 1 from public.orders p where p.customer_phone = o.customer_phone and p.id <> o.id
                  and p.confirmed_at is null and p.merged_into is null and p.created_at <= o.created_at)
    order by o.created_at
  loop
    if public._auto_merge_web_order(v_id) is not null then
      v_merged := v_merged + 1;
    end if;
  end loop;
  return jsonb_build_object('merged', v_merged);
end;

admin_block_add.src:
declare
  v_kind text := upper(coalesce(p_kind, ''));
  v_value text := nullif(trim(coalesce(p_value, '')), '');
  v_order public.orders;
  v_row public.order_blocks;
begin
  perform public.require_permission('orders.block');
  if v_kind not in ('PHONE', 'IP', 'ADDRESS') then
    raise exception 'VALIDATION: choose phone, IP address or address' using errcode = '22023';
  end if;
  if p_order_id is not null then
    select * into v_order from public.orders where id = p_order_id;
    if not found then
      raise exception 'NOT_FOUND: order not found' using errcode = 'P0002';
    end if;
    v_value := coalesce(v_value, case v_kind when 'PHONE' then v_order.customer_phone when 'IP' then v_order.client_ip
                                              else v_order.shipping_address end);
  end if;
  if v_value is null then
    raise exception 'VALIDATION: %', case v_kind when 'IP' then 'this order has no IP address recorded' else 'enter what to block' end using errcode = '22023';
  end if;
  v_value := public._block_value(v_kind, v_value);
  if v_kind = 'PHONE' and v_value !~ '^01[3-9][0-9]{8}$' then
    raise exception 'VALIDATION: enter a Bangladeshi mobile number (01XXXXXXXXX)' using errcode = '22023';
  end if;
  if v_kind = 'IP' and v_value !~ '^[0-9a-f:.]{3,45}$' then
    raise exception 'VALIDATION: that is not an IP address' using errcode = '22023';
  end if;
  if v_kind = 'ADDRESS' and length(v_value) < 8 then
    raise exception 'VALIDATION: write at least 8 characters of the address' using errcode = '22023';
  end if;
  if length(trim(coalesce(p_reason, ''))) < 3 then
    raise exception 'VALIDATION: give a reason for the block' using errcode = '22023';
  end if;
  if p_expires_at is not null and p_expires_at <= now() then
    raise exception 'VALIDATION: the block must end in the future' using errcode = '22023';
  end if;
  if exists (select 1 from public.order_blocks where kind = v_kind and value = v_value and is_active) then
    raise exception 'DUPLICATE: % is already blocked', v_value using errcode = '23505';
  end if;

  insert into public.order_blocks(kind, value, reason, expires_at, source_order_id, created_by)
  values (v_kind, v_value, trim(p_reason), p_expires_at, p_order_id, auth.uid())
  returning * into v_row;

  -- A permanently blocked phone also blocks the customer record (fraud rule "Blocked customer").
  if v_kind = 'PHONE' and p_expires_at is null then
    update public.customers set status = 'BLOCKED', blocked_reason = left('Block list: ' || trim(p_reason), 500)
    where phone = v_value and status <> 'BLOCKED';
  end if;
  perform public.log_audit('order_block.created', 'order_block', v_row.id::text, null, to_jsonb(v_row), '{}'::jsonb);
  return v_row;
end;

admin_block_lift.src:
declare
  v_row public.order_blocks;
begin
  perform public.require_permission('orders.block');
  update public.order_blocks set is_active = false, lifted_at = now(), lifted_by = auth.uid(), lift_reason = nullif(trim(coalesce(p_reason, '')), '')
  where id = p_id and is_active returning * into v_row;
  if not found then
    raise exception 'NOT_FOUND: this block is not active' using errcode = 'P0002';
  end if;
  if v_row.kind = 'PHONE' then
    update public.customers set status = 'ACTIVE', blocked_reason = null
    where phone = v_row.value and status = 'BLOCKED' and blocked_reason like 'Block list:%';
  end if;
  perform public.log_audit('order_block.removed', 'order_block', v_row.id::text, null, to_jsonb(v_row), '{}'::jsonb);
  return v_row;
end;

admin_bulk_shopify_abandoned.src:
declare
  v_count int;
begin
  perform public.require_permission('orders.update');
  if p_status not in ('CONTACTED', 'DISMISSED', 'OPEN') then
    raise exception 'VALIDATION: unknown status' using errcode = '22023';
  end if;
  if coalesce(cardinality(p_ids), 0) = 0 or cardinality(p_ids) > 500 then
    raise exception 'VALIDATION: choose between 1 and 500 checkouts' using errcode = '22023';
  end if;
  update public.shopify_abandoned_checkouts set
    follow_up = case p_status when 'DISMISSED' then 'DISMISSED' when 'CONTACTED' then 'CONTACTED'
      else case when contact_count > 0 then 'CONTACTED' else 'NONE' end end,
    contact_count = contact_count + case when p_status = 'CONTACTED' then 1 else 0 end,
    last_contacted_at = case when p_status = 'CONTACTED' then now() else last_contacted_at end
  where id = any(p_ids);
  get diagnostics v_count = row_count;
  perform public.log_audit('shopify_abandoned.bulk_' || lower(p_status), 'shopify_abandoned_checkout', 'bulk', null, jsonb_build_object('count', v_count));
  return v_count;
end;

admin_cod_receivable.src:
begin
  if not (public.is_system_context() or public.has_permission('couriers.view') or public.has_permission('finance.view')) then
    raise exception 'PERMISSION_DENIED: couriers.view is required' using errcode = '42501';
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'shipment_id', s.id, 'order_id', o.id, 'order_number', o.order_number, 'customer_name', o.customer_name,
      'courier_id', c.id, 'courier_name', c.name, 'tracking_number', s.tracking_number,
      'delivered_at', coalesce(s.delivered_at, o.delivered_at), 'total_amount', o.total_amount,
      'amount_paid', o.amount_paid, 'due', o.total_amount - o.amount_paid, 'shipping_cost', s.shipping_cost
    ) order by coalesce(s.delivered_at, o.delivered_at))
    from public.shipments s
    join public.orders o on o.id = s.order_id
    join public.couriers c on c.id = s.courier_id
    where s.is_active and o.delivered_at is not null and o.status in ('DELIVERED', 'RETURN_REQUESTED')
      and o.total_amount > o.amount_paid
      and (p_courier_id is null or s.courier_id = p_courier_id)
  ), '[]'::jsonb);
end;

admin_create_customer.src:
declare
  v_phone text := public.clean_phone(p ->> 'phone');
  v_row public.customers;
begin
  perform public.require_permission('customers.manage');
  if v_phone is null or v_phone !~ public.setting_text('store', array['phone_pattern'], '^01[3-9][0-9]{8}$') then
    raise exception 'VALIDATION: enter a valid mobile number' using errcode = '22023';
  end if;
  if length(trim(coalesce(p ->> 'full_name', ''))) < 2 then
    raise exception 'VALIDATION: name is required' using errcode = '22023';
  end if;
  insert into public.customers(full_name, phone, email, address, area, city, district, notes)
  values (trim(p ->> 'full_name'), v_phone, nullif(lower(trim(coalesce(p ->> 'email', ''))), ''),
          nullif(trim(coalesce(p ->> 'address', '')), ''), nullif(trim(coalesce(p ->> 'area', '')), ''),
          nullif(trim(coalesce(p ->> 'city', '')), ''), nullif(trim(coalesce(p ->> 'district', '')), ''),
          nullif(trim(coalesce(p ->> 'notes', '')), ''))
  returning * into v_row;
  perform public.log_audit('customer.created', 'customer', v_row.id::text, null, jsonb_build_object('phone', v_phone));
  return v_row;
exception when unique_violation then
  raise exception 'DUPLICATE: a customer with this phone number already exists' using errcode = '23505';
end;

admin_create_order.src:
declare
  v_order public.orders;
  v_shown uuid;
  v_is_new boolean := nullif(p_payload ->> 'idempotency_key', '') is null
    or not exists (select 1 from public.orders where idempotency_key = p_payload ->> 'idempotency_key');
begin
  perform public.require_permission('orders.create');
  v_order := public._create_order(p_payload, 'ADMIN');
  if p_confirm then
    v_order := public._transition_order(v_order.id, 'CONFIRMED', 'Confirmed by staff when the order was created');
  end if;
  if v_is_new then
    v_shown := public._after_order_created(v_order.id);
    select * into v_order from public.orders where id = v_shown;
  end if;
  perform public.log_audit('order.created', 'order', v_order.id::text, null,
    jsonb_build_object('order_number', v_order.order_number, 'total', v_order.total_amount));
  return v_order;
end;

admin_create_production_order.src:
declare
  v_status public.order_status;
begin
  perform public.require_permission('production.manage');
  select status into v_status from public.orders where id = p_order_id;
  if v_status not in ('CONFIRMED', 'PROCESSING', 'PRODUCTION', 'QUALITY_CHECK', 'PACKING') then
    raise exception 'VALIDATION: only confirmed orders can go to production (order is %)', v_status using errcode = '22023';
  end if;
  return public._production_create_for_order(p_order_id, true);
end;

admin_customer_summary.src:
begin
  perform public.require_permission('customers.view');
  return jsonb_build_object(
    'payments', coalesce((select jsonb_agg(jsonb_build_object('id', op.id, 'order_number', o.order_number, 'kind', op.kind,
        'channel', op.channel, 'amount', op.amount, 'created_at', op.created_at) order by op.created_at desc)
      from public.order_payments op join public.orders o on o.id = op.order_id where o.customer_id = p_customer_id), '[]'::jsonb),
    'fraud_checks', coalesce((select jsonb_agg(jsonb_build_object('id', fc.id, 'risk_score', fc.risk_score,
        'risk_level', fc.risk_level, 'decision', fc.decision, 'provider', fc.provider, 'courier_score', fc.courier_score,
        'created_at', fc.created_at, 'order_id', fc.order_id) order by fc.created_at desc)
      from public.fraud_checks fc where fc.phone = (select phone from public.customers where id = p_customer_id)), '[]'::jsonb),
    'totals', (select jsonb_build_object(
        'paid', coalesce(sum(op.amount) filter (where op.kind <> 'REFUND'), 0),
        'refunded', coalesce(sum(op.amount) filter (where op.kind = 'REFUND'), 0))
      from public.order_payments op join public.orders o on o.id = op.order_id where o.customer_id = p_customer_id)
  );
end;

admin_dismiss_duplicate.src:
declare
  v_order public.orders;
begin
  perform public.require_permission('orders.update');
  update public.orders set duplicate_status = 'DISMISSED'
  where id = p_order_id and duplicate_status = 'SUSPECTED'
  returning * into v_order;
  if not found then
    raise exception 'NOT_FOUND: no duplicate warning on this order' using errcode = 'P0002';
  end if;
  perform public._order_log(p_order_id, 'DUPLICATE_DISMISSED', 'Marked as not a duplicate');
  perform public.log_audit('order.duplicate_dismissed', 'order', p_order_id::text, null, null,
    jsonb_build_object('order_number', v_order.order_number));
  return v_order;
end;

admin_duplicate_order.src:
declare
  v_src public.orders;
  v_new public.orders;
begin
  perform public.require_permission('orders.create');
  select * into v_src from public.orders where id = p_order_id;
  if not found then
    raise exception 'NOT_FOUND: order not found' using errcode = 'P0002';
  end if;
  v_new := public._create_order(jsonb_build_object(
    'customer', jsonb_build_object('full_name', v_src.customer_name, 'phone', v_src.customer_phone, 'email', v_src.customer_email),
    'shipping', jsonb_build_object('address', v_src.shipping_address, 'area', v_src.shipping_area,
      'city', v_src.shipping_city, 'district', v_src.shipping_district, 'postal_code', v_src.shipping_postal_code),
    'items', (select jsonb_agg(jsonb_build_object('variant_id', variant_id, 'quantity', quantity, 'unit_price', unit_price))
              from public.order_items where order_id = p_order_id),
    'delivery_method', v_src.delivery_method,
    'payment_method', v_src.payment_method,
    'delivery_charge', v_src.delivery_charge - v_src.delivery_discount,
    'manual_discount', v_src.manual_discount,
    'internal_note', 'Duplicated from ' || v_src.order_number
  ), 'ADMIN');
  perform public.log_audit('order.duplicated', 'order', v_new.id::text, null,
    jsonb_build_object('source_order', v_src.order_number, 'order_number', v_new.order_number));
  return v_new;
end;

admin_duplicate_orders.src:
declare
  v_result jsonb;
begin
  perform public.require_permission('orders.view');
  if coalesce(array_length(p_stages, 1), 0) = 0 then
    raise exception 'VALIDATION: choose at least one stage' using errcode = '22023';
  end if;
  with o as (
    select o.id, o.order_number, o.customer_phone, o.customer_name, o.shipping_district, o.total_amount, o.created_at, o.status,
      public.order_stage(o.status, o.confirmed_at) as stage
    from public.orders o
    where o.confirmed_at is not null and o.merged_into is null and o.customer_phone is not null
      and public.order_stage(o.status, o.confirmed_at) = any(p_stages)
  ), dup as (
    select customer_phone from o group by customer_phone having count(*) > 1
  ), rows as (
    select o.*,
      (select string_agg(i.product_name || coalesce(' · ' || nullif(i.variant_title, ''), '') || ' ×' || i.quantity, ', ' order by i.product_name)
       from public.order_items i where i.order_id = o.id) as items
    from o join dup using (customer_phone)
  ), g as (
    select r.customer_phone, count(*) as n, max(r.created_at) as last_at, min(r.created_at) as first_at,
      (array_agg(r.customer_name order by r.created_at desc))[1] as name,
      exists (select 1 from public.order_items i join rows r2 on r2.id = i.order_id
              where r2.customer_phone = r.customer_phone and i.variant_id is not null
              group by i.variant_id having count(distinct i.order_id) > 1) as same_items,
      jsonb_agg(jsonb_build_object('id', r.id, 'order_number', r.order_number, 'stage', r.stage, 'status', r.status,
        'total', r.total_amount, 'created_at', r.created_at, 'district', r.shipping_district, 'items', r.items) order by r.created_at) as orders
    from rows r group by r.customer_phone
  )
  select jsonb_build_object(
    'groups', coalesce(jsonb_agg(jsonb_build_object('phone', customer_phone, 'name', name, 'count', n, 'same_items', same_items,
      'first_at', first_at, 'last_at', last_at, 'orders', orders) order by same_items desc, last_at desc), '[]'::jsonb),
    'orders', coalesce(sum(n), 0))
  into v_result
  from (select * from g order by same_items desc, last_at desc limit 300) g;
  return v_result;
end;

admin_fulfillment_summary.src:
declare
  v_today timestamptz := (public._local_date(now())::timestamp at time zone public.store_timezone());
begin
  perform public.require_permission('orders.view');
  return (
    select jsonb_build_object(
      'to_confirm', count(*) filter (where status in ('CONFIRMATION_REQUIRED', 'FRAUD_REVIEW')),
      'advance_pending', count(*) filter (where status = 'ADVANCE_REQUIRED'),
      'to_print', count(*) filter (where status in ('CONFIRMED', 'PROCESSING', 'PACKING', 'READY_TO_SHIP')
                                     and label_printed_at is null),
      'printed', count(*) filter (where status in ('CONFIRMED', 'PROCESSING', 'PACKING') and label_printed_at is not null),
      'ready_to_ship', count(*) filter (where status = 'READY_TO_SHIP'),
      'shipped_today', count(*) filter (where shipped_at >= v_today),
      'duplicates', count(*) filter (where duplicate_status = 'SUSPECTED' and status not in ('CANCELLED', 'REJECTED_FRAUD')),
      'merged_today', count(*) filter (where merged_count > 0 and updated_at >= v_today)
    )
    from public.orders
    where status not in ('DELIVERED', 'RETURNED', 'CANCELLED', 'REJECTED_FRAUD') or shipped_at >= v_today
       or (merged_count > 0 and updated_at >= v_today)
  );
end;

