admin_link_checkout_lead.src:
declare
  v_lead public.checkout_leads;
  v_number text;
begin
  perform public.require_permission('orders.create');
  select * into v_lead from public.checkout_leads where id = p_lead_id for update;
  if not found then
    raise exception 'NOT_FOUND: incomplete checkout not found' using errcode = 'P0002';
  end if;
  select order_number into v_number from public.orders where id = p_order_id;
  if v_number is null then
    raise exception 'NOT_FOUND: order not found' using errcode = 'P0002';
  end if;
  if v_lead.status = 'CONVERTED' and v_lead.order_id is distinct from p_order_id then
    raise exception 'VALIDATION: this checkout already became another order' using errcode = '22023';
  end if;
  if jsonb_typeof(v_lead.attribution) = 'object' then
    perform public._record_order_attribution(p_order_id, v_lead.attribution);
  end if;
  update public.checkout_leads set status = 'CONVERTED', order_id = p_order_id, updated_at = now()
  where id = p_lead_id returning * into v_lead;
  perform public._order_log(p_order_id, 'FROM_INCOMPLETE_CHECKOUT', 'Created from an incomplete checkout');
  perform public.log_audit('checkout_lead.converted', 'checkout_lead', p_lead_id::text, null,
    jsonb_build_object('order_id', p_order_id, 'order_number', v_number));
  return v_lead;
end;

admin_link_store_cart.src:
declare
  v_cart public.store_carts;
begin
  perform public.require_permission('orders.create');
  select * into v_cart from public.store_carts where id = p_cart_id for update;
  if v_cart.id is null then
    raise exception 'NOT_FOUND: cart not found' using errcode = 'P0002';
  end if;
  if not exists (select 1 from public.orders where id = p_order_id) then
    raise exception 'NOT_FOUND: order not found' using errcode = 'P0002';
  end if;
  if v_cart.status = 'CONVERTED' and v_cart.order_id is distinct from p_order_id then
    raise exception 'VALIDATION: this cart already became another order' using errcode = '22023';
  end if;
  if jsonb_typeof(v_cart.attribution) = 'object' and not exists (select 1 from public.order_attributions where order_id = p_order_id) then
    perform public._record_order_attribution(p_order_id, v_cart.attribution);
  end if;
  update public.store_carts set status = 'CONVERTED', order_id = p_order_id, converted_at = coalesce(converted_at, now()), updated_at = now(),
    recovered = recovered or (status <> 'CONVERTED' and last_activity_at < now() - public._abandoned_after())
  where id = p_cart_id returning * into v_cart;
  if v_cart.lead_id is not null then
    update public.checkout_leads set status = 'CONVERTED', order_id = p_order_id, updated_at = now()
    where id = v_cart.lead_id and status in ('OPEN', 'CONTACTED');
  end if;
  perform public._order_log(p_order_id, 'FROM_ABANDONED_CART', 'Created from an abandoned cart');
  return v_cart;
end;

admin_merge_orders.src:
declare
  v_source public.orders;
  v_target public.orders;
  v_lines jsonb;
  v_before numeric;
  v_qty int;
  v_mergeable public.order_status[] := array['PENDING', 'FRAUD_CHECK', 'ADVANCE_REQUIRED', 'FRAUD_REVIEW',
    'CONFIRMATION_REQUIRED', 'CONFIRMED']::public.order_status[];
begin
  perform public.require_permission('orders.update');
  if p_order_id = p_into_order_id then
    raise exception 'VALIDATION: choose a different order to merge into' using errcode = '22023';
  end if;
  -- Lock in a fixed order so two staff merging the same pair cannot deadlock.
  perform 1 from public.orders where id in (p_order_id, p_into_order_id) order by id for update;
  select * into v_source from public.orders where id = p_order_id;
  select * into v_target from public.orders where id = p_into_order_id;
  if v_source.id is null or v_target.id is null then
    raise exception 'NOT_FOUND: order not found' using errcode = 'P0002';
  end if;
  if not (v_source.status = any(v_mergeable)) or not (v_target.status = any(v_mergeable)) then
    raise exception 'VALIDATION: only orders that have not started processing can be merged' using errcode = '22023';
  end if;
  if v_source.merged_into is not null or v_target.merged_into is not null then
    raise exception 'VALIDATION: this order was already merged' using errcode = '22023';
  end if;
  if v_source.amount_paid > 0 or exists (select 1 from public.payments where order_id = v_source.id
                                          and status = 'REQUIRES_VERIFICATION') then
    raise exception 'VALIDATION: % has a payment — verify or refund it before merging', v_source.order_number
      using errcode = '22023';
  end if;
  if exists (select 1 from public.shipments where order_id in (v_source.id, v_target.id) and is_active) then
    raise exception 'VALIDATION: remove the courier assignment before merging' using errcode = '22023';
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
      'product_id', product_id, 'variant_id', variant_id, 'product_name', product_name,
      'variant_title', coalesce(variant_title, 'Default'), 'sku', sku, 'image_url', image_url,
      'unit_price', unit_price, 'unit_cost', unit_cost, 'quantity', quantity, 'line_subtotal', line_subtotal,
      'track_inventory', track_inventory, 'requires_production', requires_production) order by created_at), '[]'::jsonb)
  into v_lines from public.order_items where order_id = v_source.id;

  v_before := v_target.total_amount;
  perform public._release_order_stock(v_source.id, format('Released: merged into %s', v_target.order_number));
  v_qty := public._add_order_lines(v_target, v_lines);
  update public.orders set merged_count = merged_count + 1,
    duplicate_status = case when duplicate_of = v_source.id then 'MERGED' else duplicate_status end
  where id = v_target.id;
  v_target := public.recalculate_order_totals(v_target.id);

  update public.orders set merged_into = v_target.id, duplicate_status = 'MERGED' where id = v_source.id;
  perform public._transition_order(v_source.id, 'CANCELLED', format('Merged into %s', v_target.order_number),
    jsonb_build_object('merged_into', v_target.id));
  -- A merge is not a cancellation for the customer: drop that message.
  update public.notification_logs set status = 'SKIPPED', error = 'Order merged'
  where order_id = v_source.id and event = 'ORDER_CANCELLED' and status = 'QUEUED';

  insert into public.order_merges(order_id, source_order_id, kind, items, amount, created_by)
  values (v_target.id, v_source.id, 'MANUAL', v_lines, v_target.total_amount - v_before, auth.uid());
  perform public._order_log(v_target.id, 'ORDER_MERGED',
    format('%s merged into this order (%s item(s))', v_source.order_number, v_qty), null, null,
    jsonb_build_object('source_order_id', v_source.id, 'order_number', v_source.order_number,
      'added_amount', v_target.total_amount - v_before));
  perform public.log_audit('order.merged', 'order', v_target.id::text,
    jsonb_build_object('total', v_before), jsonb_build_object('total', v_target.total_amount),
    jsonb_build_object('order_number', v_target.order_number, 'merged_order', v_source.order_number));
  perform public.refresh_customer_stats(v_target.customer_id);
  return v_target;
end;

admin_online_store_answer.src:
declare
  v_id uuid := public.current_merchant_id();
  v_slug text := nullif(lower(trim(coalesce(p_slug, ''))), '');
  v_old jsonb;
begin
  perform public.require_permission('settings.manage');
  if p_open is null then
    raise exception 'VALIDATION: answer yes or no' using errcode = '22023';
  end if;
  select value into v_old from public.settings where merchant_id = v_id and key = 'storefront' for update;
  if v_old is null then
    raise exception 'NOT_FOUND: storefront settings missing' using errcode = 'P0002';
  end if;

  if not p_open then
    update public.settings set value = v_old || jsonb_build_object('store_prompt_done', true), updated_by = auth.uid()
    where merchant_id = v_id and key = 'storefront';
    return public.merchant_store_address();
  end if;

  -- Switching the store on gives it a free name (trigger); the chosen name then
  -- replaces it, checked against every business. A taken name undoes both.
  update public.settings set value = v_old || jsonb_build_object('mode', 'OWN', 'store_prompt_done', true), updated_by = auth.uid()
  where merchant_id = v_id and key = 'storefront';
  if v_slug is not null then
    perform public.admin_set_store_slug(v_slug);
  end if;
  perform public.log_audit('store.mode', 'setting', 'storefront',
    jsonb_build_object('mode', coalesce(v_old ->> 'mode', 'OWN')), jsonb_build_object('mode', 'OWN', 'slug', v_slug));
  return public.merchant_store_address();
end;

admin_order_customer_record.src:
declare
  v_order public.orders;
  v_check public.fraud_checks;
begin
  perform public.require_permission('orders.view');
  select * into v_order from public.orders where id = p_order_id;
  if not found then
    raise exception 'NOT_FOUND: order not found' using errcode = 'P0002';
  end if;
  select * into v_check from public.fraud_checks
  where phone = v_order.customer_phone and status <> 'ERROR' and provider <> 'internal'
  order by created_at desc limit 1;
  if v_check.id is null then
    select * into v_check from public.fraud_checks where id = v_order.fraud_check_id;
  end if;
  return jsonb_build_object(
    'ours', (select jsonb_build_object(
        'total', count(*),
        'delivered', count(*) filter (where o.status in ('DELIVERED', 'PARTIALLY_DELIVERED')),
        'cancelled', count(*) filter (where o.status in ('CANCELLED', 'REJECTED_FRAUD')),
        'returned', count(*) filter (where o.status in ('RETURN_REQUESTED', 'RETURNING', 'RETURNED')),
        'in_progress', count(*) filter (where o.status not in ('DELIVERED', 'PARTIALLY_DELIVERED', 'CANCELLED', 'REJECTED_FRAUD',
                                                                'RETURN_REQUESTED', 'RETURNING', 'RETURNED', 'LOST')),
        'by_stage', (select jsonb_object_agg(stage, n) from (
            select public.order_stage(x.status, x.confirmed_at) as stage, count(*) as n
            from public.orders x where x.customer_phone = v_order.customer_phone group by 1) s))
      from public.orders o where o.customer_phone = v_order.customer_phone),
    'check', case when v_check.id is null then null else jsonb_build_object(
        'id', v_check.id, 'checked_at', v_check.created_at, 'provider', v_check.provider,
        'rate', coalesce((v_check.metrics ->> 'receive_rate')::numeric, v_check.courier_score),
        'tier', v_check.metrics ->> 'receive_rate_tier',
        'total', v_check.previous_orders, 'delivered', v_check.delivered_orders,
        'cancelled', v_check.returned_orders + v_check.failed_delivery_orders,
        'couriers', v_check.provider_response -> 'courier_history' -> 'couriers',
        'verdict', v_check.provider_response -> 'courier_history' -> 'verdict') end,
    'shipment', (select jsonb_build_object('courier', c.name, 'provider', c.provider, 'tracking_number', s.tracking_number,
                          'consignment_id', s.consignment_id, 'cod_amount', s.cod_amount, 'uploaded', c.api_enabled and coalesce(s.consignment_id, s.tracking_number) is not null,
                          'tracking_url', public._tracking_url(c.provider, c.tracking_url_template, coalesce(s.tracking_number, s.consignment_id)))
                 from public.shipments s join public.couriers c on c.id = s.courier_id
                 where s.order_id = p_order_id and s.is_active order by s.created_at desc limit 1)
  );
end;

admin_order_filter_options.src:
