admin_reorder_product_images.src:
declare
  v_primary uuid := coalesce(p_primary_id, p_image_ids[1]);
begin
  perform public.require_permission('products.manage');
  if exists (select 1 from unnest(p_image_ids) i where i not in (select id from public.product_images where product_id = p_product_id)) then
    raise exception 'VALIDATION: image does not belong to this product' using errcode = '22023';
  end if;
  update public.product_images set is_primary = false where product_id = p_product_id and is_primary;
  update public.product_images pi set position = t.ord - 1, is_primary = (pi.id = v_primary)
  from unnest(p_image_ids) with ordinality as t(id, ord)
  where pi.id = t.id and pi.product_id = p_product_id;
end;

admin_resolve_system_logs.src:
declare
  v_count int;
begin
  perform public.require_permission('audit.view');
  update public.system_logs set resolved_at = now(), resolved_by = auth.uid()
  where id = any(p_ids) and resolved_at is null;
  get diagnostics v_count = row_count;
  return v_count;
end;

admin_save_fraud_rule.src:
declare
  v_rule public.fraud_rules;
  v_id uuid := nullif(p_rule ->> 'id', '')::uuid;
  v_action jsonb;
  v_cond jsonb;
begin
  perform public.require_permission('fraud.rules');
  if length(trim(coalesce(p_rule ->> 'name', ''))) = 0 then
    raise exception 'VALIDATION: rule name is required' using errcode = '22023';
  end if;
  for v_cond in select * from jsonb_array_elements(coalesce(p_rule -> 'conditions', '[]'::jsonb)) loop
    if coalesce(v_cond ->> 'field', '') = '' or lower(coalesce(v_cond ->> 'op', '')) not in
       ('eq', 'neq', 'gt', 'gte', 'lt', 'lte', 'in', 'not_in', 'is_true', 'is_false') then
      raise exception 'VALIDATION: invalid rule condition %', v_cond using errcode = '22023';
    end if;
  end loop;
  if jsonb_array_length(coalesce(p_rule -> 'actions', '[]'::jsonb)) = 0 then
    raise exception 'VALIDATION: a rule needs an action' using errcode = '22023';
  end if;

  if v_id is null then
    insert into public.fraud_rules(name, description, priority, match_mode, conditions, is_active)
    values (trim(p_rule ->> 'name'), p_rule ->> 'description', coalesce((p_rule ->> 'priority')::int, 100),
            coalesce(nullif(p_rule ->> 'match_mode', ''), 'ALL'), coalesce(p_rule -> 'conditions', '[]'::jsonb),
            coalesce((p_rule ->> 'is_active')::boolean, true))
    returning * into v_rule;
  else
    update public.fraud_rules set name = trim(p_rule ->> 'name'), description = p_rule ->> 'description',
      priority = coalesce((p_rule ->> 'priority')::int, priority),
      match_mode = coalesce(nullif(p_rule ->> 'match_mode', ''), match_mode),
      conditions = coalesce(p_rule -> 'conditions', conditions),
      is_active = coalesce((p_rule ->> 'is_active')::boolean, is_active)
    where id = v_id returning * into v_rule;
    if not found then
      raise exception 'NOT_FOUND: rule not found' using errcode = 'P0002';
    end if;
    delete from public.fraud_rule_actions where rule_id = v_id;
  end if;

  for v_action in select * from jsonb_array_elements(p_rule -> 'actions') loop
    insert into public.fraud_rule_actions(rule_id, decision, advance_type, advance_value, customer_message, stop_processing)
    values (v_rule.id, (v_action ->> 'decision')::public.fraud_decision,
            coalesce(nullif(v_action ->> 'advance_type', ''), 'NONE')::public.advance_type,
            coalesce((v_action ->> 'advance_value')::numeric, 0), nullif(v_action ->> 'customer_message', ''),
            coalesce((v_action ->> 'stop_processing')::boolean, false));
  end loop;
  return v_rule;
end;

admin_save_order_tag.src:
declare
  v_row public.order_tags;
begin
  perform public.require_permission('orders.update');
  insert into public.order_tags(name, color) values (left(trim(p_name), 40), coalesce(nullif(p_color, ''), 'neutral'))
  on conflict (merchant_id, name) do update set color = excluded.color
  returning * into v_row;
  return v_row;
end;

admin_save_product.src:
declare
  v_product public.products;
  v_id uuid := nullif(p_payload ->> 'id', '')::uuid;
  v_slug text;
  v_variant jsonb;
  v_variant_id uuid;
  v_keep uuid[] := '{}';
  v_initial int;
  v_pos int := 0;
  v_variants jsonb := coalesce(p_payload -> 'variants', '[]'::jsonb);
begin
  perform public.require_permission('products.manage');
  if v_id is null then
    perform public.require_limit('products');
  end if;

  if length(trim(coalesce(p_payload ->> 'name', ''))) = 0 then
    raise exception 'VALIDATION: product name is required' using errcode = '22023';
  end if;
  if (p_payload ->> 'price') is null or (p_payload ->> 'price')::numeric < 0 then
    raise exception 'VALIDATION: price must be zero or more' using errcode = '22023';
  end if;
  v_slug := coalesce(nullif(public.slugify(p_payload ->> 'slug'), ''), public.slugify(p_payload ->> 'name'));
  if v_slug = '' then
    raise exception 'VALIDATION: product slug is required' using errcode = '22023';
  end if;

  if v_id is null then
    insert into public.products(
      name, slug, sku, description, category_id, brand, tags, status, option_names, cost_price, price,
      compare_at_price, weight_grams, low_stock_threshold, track_inventory, requires_production, is_featured,
      seo_title, seo_description, created_by
    ) values (
      trim(p_payload ->> 'name'), v_slug, nullif(trim(p_payload ->> 'sku'), ''), p_payload ->> 'description',
      nullif(p_payload ->> 'category_id', '')::uuid, nullif(p_payload ->> 'brand', ''),
      coalesce(array(select jsonb_array_elements_text(coalesce(p_payload -> 'tags', '[]'::jsonb))), '{}'),
      coalesce(nullif(p_payload ->> 'status', '')::public.product_status, 'DRAFT'),
      coalesce(array(select jsonb_array_elements_text(coalesce(p_payload -> 'option_names', '[]'::jsonb))), '{}'),
      coalesce((p_payload ->> 'cost_price')::numeric, 0), (p_payload ->> 'price')::numeric,
      nullif(p_payload ->> 'compare_at_price', '')::numeric, nullif(p_payload ->> 'weight_grams', '')::int,
      nullif(p_payload ->> 'low_stock_threshold', '')::int,
      coalesce((p_payload ->> 'track_inventory')::boolean, true),
      coalesce((p_payload ->> 'requires_production')::boolean, false),
      coalesce((p_payload ->> 'is_featured')::boolean, false),
      nullif(p_payload ->> 'seo_title', ''), nullif(p_payload ->> 'seo_description', ''), auth.uid()
    ) returning * into v_product;
  else
    update public.products set
      name = trim(p_payload ->> 'name'),
      slug = v_slug,
      sku = nullif(trim(p_payload ->> 'sku'), ''),
      description = p_payload ->> 'description',
      category_id = nullif(p_payload ->> 'category_id', '')::uuid,
      brand = nullif(p_payload ->> 'brand', ''),
      tags = coalesce(array(select jsonb_array_elements_text(coalesce(p_payload -> 'tags', '[]'::jsonb))), '{}'),
      status = coalesce(nullif(p_payload ->> 'status', '')::public.product_status, status),
      option_names = coalesce(array(select jsonb_array_elements_text(coalesce(p_payload -> 'option_names', '[]'::jsonb))), '{}'),
      cost_price = coalesce((p_payload ->> 'cost_price')::numeric, 0),
      price = (p_payload ->> 'price')::numeric,
      compare_at_price = nullif(p_payload ->> 'compare_at_price', '')::numeric,
      weight_grams = nullif(p_payload ->> 'weight_grams', '')::int,
      low_stock_threshold = nullif(p_payload ->> 'low_stock_threshold', '')::int,
      track_inventory = coalesce((p_payload ->> 'track_inventory')::boolean, track_inventory),
      requires_production = coalesce((p_payload ->> 'requires_production')::boolean, requires_production),
      is_featured = coalesce((p_payload ->> 'is_featured')::boolean, is_featured),
      seo_title = nullif(p_payload ->> 'seo_title', ''),
      seo_description = nullif(p_payload ->> 'seo_description', '')
    where id = v_id
    returning * into v_product;
    if not found then
      raise exception 'NOT_FOUND: product % does not exist', v_id using errcode = 'P0002';
    end if;
  end if;

  -- A product always has at least one variant (the "Default" variant).
  if jsonb_array_length(v_variants) = 0 then
    if exists (select 1 from public.product_variants where product_id = v_product.id) then
      v_variants := (
        select jsonb_agg(jsonb_build_object('id', id, 'sku', sku, 'title', title, 'is_active', is_active))
        from public.product_variants where product_id = v_product.id and is_default
      );
    end if;
    if v_variants is null or jsonb_array_length(v_variants) = 0 then
      v_variants := jsonb_build_array(jsonb_build_object(
        'sku', coalesce(v_product.sku, upper(left(v_product.slug, 24)) || '-' || left(v_product.id::text, 6)),
        'title', 'Default'
      ));
    end if;
  end if;

  for v_variant in select * from jsonb_array_elements(v_variants) loop
    v_variant_id := nullif(v_variant ->> 'id', '')::uuid;
    if length(trim(coalesce(v_variant ->> 'sku', ''))) = 0 then
      raise exception 'VALIDATION: every variant needs a SKU' using errcode = '22023';
    end if;
    if v_variant_id is null then
      insert into public.product_variants(
        product_id, sku, title, size, color, option_values, price, compare_at_price, cost_price,
        weight_grams, barcode, position, is_default, is_active
      ) values (
        v_product.id, trim(v_variant ->> 'sku'), coalesce(nullif(trim(v_variant ->> 'title'), ''), 'Default'),
        nullif(v_variant ->> 'size', ''), nullif(v_variant ->> 'color', ''),
        coalesce(v_variant -> 'option_values', '{}'::jsonb),
        nullif(v_variant ->> 'price', '')::numeric, nullif(v_variant ->> 'compare_at_price', '')::numeric,
        nullif(v_variant ->> 'cost_price', '')::numeric, nullif(v_variant ->> 'weight_grams', '')::int,
        nullif(v_variant ->> 'barcode', ''), coalesce((v_variant ->> 'position')::int, v_pos),
        v_pos = 0, coalesce((v_variant ->> 'is_active')::boolean, true)
      ) returning id into v_variant_id;

      v_initial := coalesce(nullif(v_variant ->> 'initial_stock', '')::int, 0);
      if v_initial < 0 then
        raise exception 'VALIDATION: opening stock cannot be negative' using errcode = '22023';
      end if;
      if v_initial > 0 then
        perform public._apply_inventory_movement(v_variant_id, 'ADJUSTMENT', v_initial, 0, 0,
          'ADJUSTMENT', null, null, 'Opening stock', public.variant_cost(v_variant_id));
      end if;
    else
      update public.product_variants set
        sku = trim(v_variant ->> 'sku'),
        title = coalesce(nullif(trim(v_variant ->> 'title'), ''), title),
        size = nullif(v_variant ->> 'size', ''),
        color = nullif(v_variant ->> 'color', ''),
        option_values = coalesce(v_variant -> 'option_values', option_values),
        price = nullif(v_variant ->> 'price', '')::numeric,
        compare_at_price = nullif(v_variant ->> 'compare_at_price', '')::numeric,
        cost_price = nullif(v_variant ->> 'cost_price', '')::numeric,
        weight_grams = nullif(v_variant ->> 'weight_grams', '')::int,
        barcode = nullif(v_variant ->> 'barcode', ''),
        position = coalesce((v_variant ->> 'position')::int, v_pos),
        is_active = coalesce((v_variant ->> 'is_active')::boolean, true)
      where id = v_variant_id and product_id = v_product.id;
      if not found then
        raise exception 'NOT_FOUND: variant % does not belong to this product', v_variant_id using errcode = 'P0002';
      end if;
    end if;
    v_keep := v_keep || v_variant_id;
    v_pos := v_pos + 1;
  end loop;

  update public.product_variants set is_active = false
  where product_id = v_product.id and not (id = any(v_keep)) and is_active;

  -- Exactly one default variant: the first kept one.
  update public.product_variants set is_default = (id = v_keep[1]) where product_id = v_product.id;

  return v_product;
end;

admin_save_product_full.src:
declare
  v_product public.products;
  v_cats uuid[];
begin
  perform public.require_permission('products.manage');
  v_product := public.admin_save_product(p_payload);
  v_cats := coalesce(array(
    select distinct c.id from jsonb_array_elements_text(coalesce(p_payload -> 'extra_category_ids', '[]'::jsonb)) x
    join public.categories c on c.id::text = x
    where c.id is distinct from v_product.category_id), '{}');
  update public.products set
    short_description = nullif(trim(coalesce(p_payload ->> 'short_description', '')), ''),
    shipping_note = nullif(trim(coalesce(p_payload ->> 'shipping_note', '')), ''),
    warranty = nullif(trim(coalesce(p_payload ->> 'warranty', '')), ''),
    admin_note = nullif(trim(coalesce(p_payload ->> 'admin_note', '')), ''),
    extra_category_ids = v_cats
  where id = v_product.id
  returning * into v_product;
  return v_product;
end;

admin_save_purchase_order.src:
declare
  v_po public.purchase_orders;
  v_id uuid := nullif(p ->> 'id', '')::uuid;
  v_item jsonb;
begin
  perform public.require_permission('purchases.manage');
  if jsonb_array_length(coalesce(p -> 'items', '[]'::jsonb)) = 0 then
    raise exception 'VALIDATION: add at least one item' using errcode = '22023';
  end if;
  if not exists (select 1 from public.suppliers where id = (p ->> 'supplier_id')::uuid) then
    raise exception 'VALIDATION: choose a supplier' using errcode = '22023';
  end if;

  if v_id is null then
    insert into public.purchase_orders(supplier_id, status, order_date, expected_date, shipping_cost, notes, created_by)
    values ((p ->> 'supplier_id')::uuid,
            coalesce(nullif(p ->> 'status', '')::public.purchase_status, 'DRAFT'),
            coalesce(nullif(p ->> 'order_date', '')::date, current_date), nullif(p ->> 'expected_date', '')::date,
            coalesce((p ->> 'shipping_cost')::numeric, 0), nullif(trim(coalesce(p ->> 'notes', '')), ''), auth.uid())
    returning * into v_po;
  else
    select * into v_po from public.purchase_orders where id = v_id for update;
    if not found then
      raise exception 'NOT_FOUND: purchase order not found' using errcode = 'P0002';
    end if;
    if v_po.status not in ('DRAFT', 'ORDERED') then
      raise exception 'VALIDATION: % purchase orders cannot be edited', v_po.status using errcode = '22023';
    end if;
    if exists (select 1 from public.purchase_order_items where purchase_order_id = v_id and received_quantity > 0) then
      raise exception 'VALIDATION: items cannot be edited after receiving has started' using errcode = '22023';
    end if;
    update public.purchase_orders set supplier_id = (p ->> 'supplier_id')::uuid,
      status = coalesce(nullif(p ->> 'status', '')::public.purchase_status, status),
      order_date = coalesce(nullif(p ->> 'order_date', '')::date, order_date),
      expected_date = nullif(p ->> 'expected_date', '')::date,
      shipping_cost = coalesce((p ->> 'shipping_cost')::numeric, 0),
      notes = nullif(trim(coalesce(p ->> 'notes', '')), '')
    where id = v_id returning * into v_po;
    delete from public.purchase_order_items where purchase_order_id = v_id;
  end if;

  for v_item in select * from jsonb_array_elements(p -> 'items') loop
    insert into public.purchase_order_items(purchase_order_id, product_id, variant_id, quantity, unit_cost)
    select v_po.id, v.product_id, v.id, (v_item ->> 'quantity')::int, (v_item ->> 'unit_cost')::numeric
    from public.product_variants v where v.id = (v_item ->> 'variant_id')::uuid;
    if not found then
      raise exception 'VALIDATION: unknown product variant in purchase order' using errcode = '22023';
    end if;
  end loop;

  update public.purchase_orders po set
    subtotal = s.subtotal, total_cost = s.subtotal + po.shipping_cost
  from (select coalesce(sum(total_cost), 0) as subtotal from public.purchase_order_items where purchase_order_id = v_po.id) s
  where po.id = v_po.id returning po.* into v_po;

  perform public.log_audit(case when v_id is null then 'purchase.created' else 'purchase.updated' end,
    'purchase_order', v_po.id::text, null, jsonb_build_object('po_number', v_po.po_number, 'total_cost', v_po.total_cost));
  return v_po;
end;

admin_save_review_status.src:
declare
  v_label text := trim(coalesce(p ->> 'label', ''));
  v_code text := upper(trim(both '_' from regexp_replace(coalesce(nullif(p ->> 'code', ''), p ->> 'label', ''), '[^A-Za-z0-9]+', '_', 'g')));
  v_existing public.order_review_statuses;
  v_row public.order_review_statuses;
  v_color text := coalesce(nullif(p ->> 'color', ''), 'neutral');
begin
  perform public.require_permission('settings.manage');
  if length(v_label) = 0 or length(v_label) > 40 then
    raise exception 'VALIDATION: give the status a name (up to 40 characters)' using errcode = '22023';
  end if;
  if v_code !~ '^[A-Z][A-Z0-9_]{1,39}$' then
    raise exception 'VALIDATION: the name must start with a letter' using errcode = '22023';
  end if;
  if v_color not in ('neutral', 'info', 'success', 'warning', 'danger', 'violet') then
    raise exception 'VALIDATION: unknown colour' using errcode = '22023';
  end if;
  select * into v_existing from public.order_review_statuses where code = v_code;
  if found and v_existing.is_system then
    if v_code in ('PROCESSING', 'CANCELLED') and not coalesce((p ->> 'is_active')::boolean, true) then
      raise exception 'VALIDATION: % is used by the system and cannot be turned off', v_existing.label using errcode = '22023';
    end if;
    update public.order_review_statuses set label = v_label,
      description = nullif(trim(coalesce(p ->> 'description', '')), ''),
      color = v_color,
      sort_order = coalesce((p ->> 'sort_order')::int, sort_order),
      is_active = coalesce((p ->> 'is_active')::boolean, is_active)
    where code = v_code returning * into v_row;
  else
    insert into public.order_review_statuses(code, label, description, color, closes_order, needs_follow_up, counts_contact, is_active, sort_order)
    values (v_code, v_label, nullif(trim(coalesce(p ->> 'description', '')), ''), v_color,
            coalesce((p ->> 'closes_order')::boolean, false), coalesce((p ->> 'needs_follow_up')::boolean, false),
            coalesce((p ->> 'counts_contact')::boolean, false), coalesce((p ->> 'is_active')::boolean, true),
            coalesce((p ->> 'sort_order')::int, 60))
    on conflict (merchant_id, code) do update set label = excluded.label, description = excluded.description, color = excluded.color,
      closes_order = excluded.closes_order, needs_follow_up = excluded.needs_follow_up, counts_contact = excluded.counts_contact,
      is_active = excluded.is_active, sort_order = excluded.sort_order
    returning * into v_row;
  end if;
  perform public.log_audit('settings.review_status_saved', 'order_review_status', v_row.code,
    case when v_existing.code is not null then to_jsonb(v_existing) end, to_jsonb(v_row));
  return v_row;
end;

admin_set_order_items.src:
declare
  v_old public.orders;
  v_quote jsonb;
  v_line jsonb;
  v_item public.order_items;
  v_old_items jsonb;
  v_override boolean := public.has_permission('orders.price_override') or public.is_system_context();
  v_existing public.order_items;
begin
  perform public.require_permission('orders.update');
  select * into v_old from public.orders where id = p_order_id for update;
  if not found then
    raise exception 'NOT_FOUND: order not found' using errcode = 'P0002';
  end if;
  if not public.order_is_editable(v_old.status) then
    raise exception 'VALIDATION: items cannot be changed after the order ships' using errcode = '22023';
  end if;

  select jsonb_agg(jsonb_build_object('sku', sku, 'quantity', quantity, 'unit_price', unit_price))
  into v_old_items from public.order_items where order_id = p_order_id;

  -- Without price-override permission, existing lines keep their price and new
  -- lines get the catalogue price.
  if not v_override then
    p_items := (
      select jsonb_agg(
        case when oi.unit_price is not null
          then (e - 'unit_price') || jsonb_build_object('unit_price', oi.unit_price)
          else e - 'unit_price' end)
      from jsonb_array_elements(p_items) e
      left join lateral (
        select unit_price from public.order_items
        where order_id = p_order_id and variant_id = (e ->> 'variant_id')::uuid limit 1
      ) oi on true
    );
  end if;

  v_quote := public.calculate_order_quote(p_items, v_old.shipping_district, v_old.shipping_area,
    v_old.delivery_method, null, null, true, true);

  perform public._release_order_stock(p_order_id, 'Released: order items edited');
  delete from public.order_items where order_id = p_order_id;

  for v_line in select * from jsonb_array_elements(v_quote -> 'lines') loop
    insert into public.order_items(
      order_id, product_id, variant_id, product_name, variant_title, sku, image_url, unit_price, unit_cost,
      quantity, line_subtotal, discount_amount, line_total, track_inventory, requires_production
    ) values (
      p_order_id, (v_line ->> 'product_id')::uuid, (v_line ->> 'variant_id')::uuid, v_line ->> 'product_name',
      nullif(v_line ->> 'variant_title', 'Default'), v_line ->> 'sku', v_line ->> 'image_url',
      (v_line ->> 'unit_price')::numeric, (v_line ->> 'unit_cost')::numeric, (v_line ->> 'quantity')::int,
      (v_line ->> 'line_subtotal')::numeric, 0, (v_line ->> 'line_subtotal')::numeric,
      (v_line ->> 'track_inventory')::boolean, (v_line ->> 'requires_production')::boolean
    ) returning * into v_item;
    perform public._reserve_order_item(v_item, v_old.order_number);
  end loop;

  perform public.recalculate_order_totals(p_order_id);
  perform public._production_refresh_items(p_order_id);
  perform public._order_log(p_order_id, 'ITEMS_CHANGED', 'Order items updated', null, null,
    jsonb_build_object('before', v_old_items, 'after', v_quote -> 'lines'));
  perform public.log_audit('order.items_changed', 'order', p_order_id::text,
    jsonb_build_object('items', v_old_items, 'total', v_old.total_amount),
    jsonb_build_object('items', p_items));
  select * into v_old from public.orders where id = p_order_id;
  return v_old;
end;

admin_set_order_source.src:
declare
  v_row public.order_attributions;
  v_channel text;
  v_label text;
  v_old jsonb;
begin
  perform public.require_permission('orders.update');
  select channel, label into v_channel, v_label from public.order_sources
  where code = upper(trim(coalesce(p_source, ''))) and is_active;
  if v_channel is null then
    raise exception 'VALIDATION: choose where this order came from' using errcode = '22023';
  end if;
  select to_jsonb(a) into v_old from public.order_attributions a where order_id = p_order_id;
  if v_old is not null and v_old ->> 'recorded_by' = 'STOREFRONT' and v_old ->> 'channel' not in ('unknown', 'direct') then
    raise exception 'VALIDATION: this order already has tracked source data (%)', v_old ->> 'source' using errcode = '22023';
  end if;
  insert into public.order_attributions(order_id, channel, source, medium, is_paid, recorded_by, note, first_channel, first_source)
  values (p_order_id, v_channel, v_label, 'Manual', false, 'STAFF', left(p_note, 300), v_channel, v_label)
  on conflict (order_id) do update set channel = excluded.channel, source = excluded.source, medium = excluded.medium,
    is_paid = excluded.is_paid, recorded_by = 'STAFF', note = excluded.note, attributed_at = now()
  returning * into v_row;
  perform public._order_log(p_order_id, 'SOURCE_SET', format('Order source set to %s', v_label), null, null,
    jsonb_build_object('source', v_label, 'note', p_note));
  perform public.log_audit('order.source_set', 'order', p_order_id::text, v_old, to_jsonb(v_row));
  return v_row;
end;

admin_set_store_mode.src:
declare
  v_mode text := upper(trim(coalesce(p_mode, '')));
  v_url text := nullif(trim(coalesce(p_redirect_url, '')), '');
  v_old jsonb;
  v_new jsonb;
begin
  perform public.require_permission('settings.manage');
  if v_mode not in ('OWN', 'SHOPIFY', 'WOOCOMMERCE', 'OFF') then
    raise exception 'VALIDATION: choose our store, Shopify, WooCommerce or off' using errcode = '22023';
  end if;
  if v_url is not null and v_url !~* '^https://[a-z0-9.-]+\.[a-z]{2,}(/[^\s]*)?$' then
    raise exception 'VALIDATION: the store address must start with https://' using errcode = '22023';
  end if;
  select value into v_old from public.settings where key = 'storefront' for update;
  if v_old is null then
    raise exception 'NOT_FOUND: storefront settings missing' using errcode = 'P0002';
  end if;
  v_new := v_old || jsonb_build_object('mode', v_mode, 'redirect_url', v_url);
  update public.settings set value = v_new, updated_by = auth.uid() where key = 'storefront';
  perform public.log_audit('store.mode', 'setting', 'storefront',
    jsonb_build_object('mode', coalesce(v_old ->> 'mode', 'OWN'), 'redirect_url', v_old ->> 'redirect_url'),
    jsonb_build_object('mode', v_mode, 'redirect_url', v_url));
  return jsonb_build_object('mode', v_mode, 'redirect_url', v_url);
end;

admin_set_store_slug.src:
declare
  v_id uuid := public.current_merchant_id();
  v_slug text := lower(trim(coalesce(p_slug, '')));
  v_old text;
  v_problem text;
begin
  perform public.require_permission('settings.manage');
  if coalesce((select value ->> 'mode' from public.settings where merchant_id = v_id and key = 'storefront'), 'OWN') <> 'OWN' then
    raise exception 'VALIDATION: turn on the online store first' using errcode = '22023';
  end if;
  v_problem := public._store_slug_problem(v_slug, v_id);
  if v_problem is not null then
    raise exception 'VALIDATION: %', v_problem using errcode = '22023';
  end if;
  select slug into v_old from public.merchants where id = v_id for update;
  update public.merchants set slug = v_slug where id = v_id;
  perform public.log_audit('store.address', 'merchant', v_id::text, jsonb_build_object('slug', v_old), jsonb_build_object('slug', v_slug));
  return public.merchant_store_address();
end;

admin_set_user_role.src:
declare
  v_role public.roles;
  v_profile public.profiles;
  v_my_role text := public.current_role_code();
  v_my_rank int;
  v_merchant uuid := public.current_merchant_id();
  v_other uuid;
begin
  perform public.require_permission('users.manage');
  if v_merchant is null then
    raise exception 'MERCHANT_REQUIRED: choose the merchant first' using errcode = '42501';
  end if;

  select * into v_role from public.roles where code = upper(p_role_code);
  if not found then
    raise exception 'VALIDATION: unknown role %', p_role_code using errcode = '22023';
  end if;

  -- A login works for one business; it cannot be pulled into a second one.
  v_other := public._staff_merchant(p_user_id);
  if v_other is not null and v_other <> v_merchant then
    raise exception 'VALIDATION: this account already belongs to another business' using errcode = '22023';
  end if;

  if not public.is_system_context() then
    if p_user_id = auth.uid() then
      raise exception 'PERMISSION_DENIED: you cannot change your own role or status' using errcode = '42501';
    end if;
    if v_role.code = 'OWNER' and v_my_role <> 'OWNER' then
      raise exception 'PERMISSION_DENIED: only an owner can grant the OWNER role' using errcode = '42501';
    end if;
    if exists (select 1 from public.profiles p join public.roles r on r.id = p.role_id
               where p.id = p_user_id and r.code = 'OWNER') and v_my_role <> 'OWNER' then
      raise exception 'PERMISSION_DENIED: only an owner can modify another owner' using errcode = '42501';
    end if;
    -- Whoever holds users.manage can only hand out, or take away, roles up to their own rank.
    if v_my_role <> 'OWNER' then
      v_my_rank := coalesce((select rank from public.roles where code = v_my_role), 0);
      if v_role.rank > v_my_rank then
        raise exception 'PERMISSION_DENIED: you cannot grant a role above your own' using errcode = '42501';
      end if;
      if exists (select 1 from public.profiles p join public.roles r on r.id = p.role_id
                 where p.id = p_user_id and r.rank > v_my_rank) then
        raise exception 'PERMISSION_DENIED: you cannot change someone with a higher role than yours' using errcode = '42501';
      end if;
    end if;
  end if;

  select * into v_profile from public.profiles where id = p_user_id for update;
  if (v_profile.id is null or not v_profile.is_active) and p_is_active then
    perform public.require_limit('staff');
  end if;
  if v_profile.id is null then
    insert into public.profiles(id, email, full_name, role_id, is_active)
    select u.id, u.email, u.full_name, v_role.id, p_is_active
    from public._auth_user(p_user_id) u
    returning * into v_profile;
    if v_profile.id is null then
      raise exception 'NOT_FOUND: auth user % does not exist', p_user_id using errcode = 'P0002';
    end if;
  else
    -- Never leave the business without an active owner.
    if (select code from public.roles where id = v_profile.role_id) = 'OWNER'
       and (v_role.code <> 'OWNER' or not p_is_active)
       and (select count(*) from public.profiles p join public.roles r on r.id = p.role_id
            where r.code = 'OWNER' and p.is_active and p.id <> p_user_id) = 0 then
      raise exception 'VALIDATION: at least one active owner is required' using errcode = '22023';
    end if;
    update public.profiles set role_id = v_role.id, is_active = p_is_active
    where id = p_user_id returning * into v_profile;
  end if;

  perform public.log_audit('user.role_changed', 'profile', p_user_id::text, null,
    jsonb_build_object('role', v_role.code, 'is_active', p_is_active));
  return v_profile;
end;

admin_site_key_create.src:
declare
  v_kind text := upper(coalesce(p_kind, ''));
  v_origins text[];
  v_key text;
  v_row public.site_api_keys;
begin
  perform public.require_permission('settings.manage');
  if v_kind not in ('PUBLISHABLE', 'SECRET') then
    raise exception 'VALIDATION: choose a browser (publishable) or server (secret) key' using errcode = '22023';
  end if;
  select coalesce(array_agg(distinct rtrim(lower(trim(o)), '/')), '{}') into v_origins
  from unnest(coalesce(p_origins, '{}')) o where trim(o) <> '';
  if exists (select 1 from unnest(v_origins) o where not public._origin_ok(o)) then
    raise exception 'VALIDATION: each website address must look like https://shop.com (no path)' using errcode = '22023';
  end if;
  if v_kind = 'PUBLISHABLE' and coalesce(array_length(v_origins, 1), 0) = 0 then
    raise exception 'VALIDATION: a browser key needs the website address it will be used from' using errcode = '22023';
  end if;
  v_key := case v_kind when 'SECRET' then 'sk_live_' else 'pk_live_' end || encode(extensions.gen_random_bytes(24), 'hex');
  insert into public.site_api_keys(name, kind, prefix, key_hash, allowed_origins, created_by)
  values (trim(p_name), v_kind, left(v_key, 14), encode(extensions.digest(v_key, 'sha256'), 'hex'), v_origins, auth.uid())
  returning * into v_row;
  perform public.log_audit('site_api_key.create', 'site_api_key', v_row.id::text, null,
    jsonb_build_object('name', v_row.name, 'kind', v_row.kind, 'origins', to_jsonb(v_row.allowed_origins)));
  -- The only time the full key leaves the database.
  return jsonb_build_object('id', v_row.id, 'key', v_key, 'prefix', v_row.prefix, 'kind', v_row.kind);
end;

admin_site_key_revoke.src:
begin
  perform public.require_permission('settings.manage');
  update public.site_api_keys set revoked_at = now(), revoked_by = auth.uid() where id = p_id and revoked_at is null;
  if not found then
    raise exception 'NOT_FOUND: key not found or already turned off' using errcode = 'P0002';
  end if;
  perform public.log_audit('site_api_key.revoke', 'site_api_key', p_id::text, null, null);
end;

admin_site_keys.src:
begin
  perform public.require_permission('settings.view');
  return coalesce((select jsonb_agg(jsonb_build_object('id', k.id, 'name', k.name, 'kind', k.kind, 'prefix', k.prefix,
      'allowed_origins', to_jsonb(k.allowed_origins), 'created_at', k.created_at, 'last_used_at', k.last_used_at,
      'request_count', k.request_count, 'revoked_at', k.revoked_at,
      'orders', (select count(*) from public.orders o where ('site:' || k.name) = any(o.tags)))
    order by k.revoked_at nulls first, k.created_at desc) from public.site_api_keys k), '[]'::jsonb);
end;

admin_update_checkout_lead.src:
declare
  v_row public.checkout_leads;
begin
  perform public.require_permission('orders.update');
  if p_status not in ('OPEN', 'CONTACTED', 'DISMISSED') then
    raise exception 'VALIDATION: unknown status' using errcode = '22023';
  end if;
  update public.checkout_leads set
    status = p_status,
    contact_count = contact_count + case when p_status = 'CONTACTED' then 1 else 0 end,
    last_contacted_at = case when p_status = 'CONTACTED' then now() else last_contacted_at end,
    notes = case when nullif(trim(p_note), '') is null then notes
      else concat_ws(E'\n', notes, to_char(now() at time zone public.store_timezone(), 'DD Mon HH24:MI') || ' — ' || trim(p_note)) end,
    updated_at = now()
  where id = p_id and status <> 'CONVERTED'
  returning * into v_row;
  if not found then
    raise exception 'NOT_FOUND: incomplete checkout not found or already ordered' using errcode = 'P0002';
  end if;
  perform public.log_audit('checkout_lead.updated', 'checkout_lead', p_id::text, null, jsonb_build_object('status', p_status));
  return v_row;
end;

admin_update_customer.src:
declare
  v_old public.customers;
  v_new public.customers;
begin
  perform public.require_permission('customers.manage');
  select * into v_old from public.customers where id = p_customer_id for update;
  if not found then
    raise exception 'NOT_FOUND: customer not found' using errcode = 'P0002';
  end if;
  if p_changes ? 'status' and (p_changes ->> 'status') = 'BLOCKED' and length(trim(coalesce(p_changes ->> 'blocked_reason', ''))) = 0 then
    raise exception 'VALIDATION: a reason is required to block a customer' using errcode = '22023';
  end if;
  update public.customers set
    full_name = coalesce(nullif(trim(p_changes ->> 'full_name'), ''), full_name),
    email = case when p_changes ? 'email' then nullif(lower(trim(p_changes ->> 'email')), '') else email end,
    address = case when p_changes ? 'address' then nullif(trim(p_changes ->> 'address'), '') else address end,
    area = case when p_changes ? 'area' then nullif(trim(p_changes ->> 'area'), '') else area end,
    city = case when p_changes ? 'city' then nullif(trim(p_changes ->> 'city'), '') else city end,
    district = case when p_changes ? 'district' then nullif(trim(p_changes ->> 'district'), '') else district end,
    notes = case when p_changes ? 'notes' then nullif(trim(p_changes ->> 'notes'), '') else notes end,
    tags = case when p_changes ? 'tags' then coalesce(array(select jsonb_array_elements_text(p_changes -> 'tags')), '{}') else tags end,
    status = coalesce(nullif(p_changes ->> 'status', '')::public.customer_status, status),
    blocked_reason = case when (p_changes ->> 'status') = 'BLOCKED' then trim(p_changes ->> 'blocked_reason')
                          when (p_changes ->> 'status') = 'ACTIVE' then null else blocked_reason end
  where id = p_customer_id returning * into v_new;
  perform public.refresh_customer_stats(p_customer_id);
  perform public.log_audit(case when v_new.status <> v_old.status then 'customer.status_changed' else 'customer.updated' end,
    'customer', p_customer_id::text,
    (select jsonb_object_agg(k, to_jsonb(v_old) -> k) from jsonb_object_keys(p_changes) k where to_jsonb(v_old) ? k),
    (select jsonb_object_agg(k, to_jsonb(v_new) -> k) from jsonb_object_keys(p_changes) k where to_jsonb(v_new) ? k));
  select * into v_new from public.customers where id = p_customer_id;
  return v_new;
end;

admin_update_order.src:
declare
  v_old public.orders;
  v_order public.orders;
  v_phone text;
  v_customer_id uuid;
  v_pattern text := public.setting_text('store', array['phone_pattern'], '^01[3-9][0-9]{8}$');
begin
  perform public.require_permission('orders.update');
  select * into v_old from public.orders where id = p_order_id for update;
  if not found then
    raise exception 'NOT_FOUND: order not found' using errcode = 'P0002';
  end if;
  if not public.order_is_editable(v_old.status) then
    raise exception 'VALIDATION: orders cannot be edited after they ship (status %)', v_old.status using errcode = '22023';
  end if;
  if (p_changes ? 'delivery_charge' or p_changes ? 'manual_discount')
     and not public.has_permission('orders.price_override') and not public.is_system_context() then
    raise exception 'PERMISSION_DENIED: orders.price_override is required to change prices' using errcode = '42501';
  end if;
  if (p_changes ->> 'delivery_charge')::numeric < 0 or (p_changes ->> 'manual_discount')::numeric < 0 then
    raise exception 'VALIDATION: amounts cannot be negative' using errcode = '22023';
  end if;

  v_customer_id := v_old.customer_id;
  if p_changes ? 'customer_phone' then
    v_phone := public.clean_phone(p_changes ->> 'customer_phone');
    if v_phone is null or v_phone !~ v_pattern then
      raise exception 'VALIDATION: enter a valid mobile number' using errcode = '22023';
    end if;
    if v_phone <> v_old.customer_phone then
      -- Changing the phone moves the order to that phone's customer record.
      select id into v_customer_id from public.customers where phone = v_phone;
      if v_customer_id is null then
        insert into public.customers(full_name, phone, email, address, area, city, district)
        values (coalesce(p_changes ->> 'customer_name', v_old.customer_name), v_phone, v_old.customer_email,
                v_old.shipping_address, v_old.shipping_area, v_old.shipping_city, v_old.shipping_district)
        returning id into v_customer_id;
      end if;
    end if;
  end if;

  update public.orders set
    customer_id = v_customer_id,
    customer_name = coalesce(nullif(trim(p_changes ->> 'customer_name'), ''), customer_name),
    customer_phone = coalesce(v_phone, customer_phone),
    customer_email = case when p_changes ? 'customer_email' then nullif(lower(trim(p_changes ->> 'customer_email')), '') else customer_email end,
    shipping_address = coalesce(nullif(trim(p_changes ->> 'shipping_address'), ''), shipping_address),
    shipping_area = case when p_changes ? 'shipping_area' then nullif(trim(p_changes ->> 'shipping_area'), '') else shipping_area end,
    shipping_city = case when p_changes ? 'shipping_city' then nullif(trim(p_changes ->> 'shipping_city'), '') else shipping_city end,
    shipping_district = coalesce(nullif(trim(p_changes ->> 'shipping_district'), ''), shipping_district),
    shipping_postal_code = case when p_changes ? 'shipping_postal_code' then nullif(trim(p_changes ->> 'shipping_postal_code'), '') else shipping_postal_code end,
    delivery_method = coalesce(nullif(p_changes ->> 'delivery_method', ''), delivery_method),
    delivery_charge = coalesce((p_changes ->> 'delivery_charge')::numeric, delivery_charge),
    delivery_discount = case when p_changes ? 'delivery_charge' then 0 else delivery_discount end,
    manual_discount = coalesce((p_changes ->> 'manual_discount')::numeric, manual_discount),
    payment_method = coalesce(nullif(p_changes ->> 'payment_method', '')::public.payment_method, payment_method),
    customer_note = case when p_changes ? 'customer_note' then nullif(trim(p_changes ->> 'customer_note'), '') else customer_note end
  where id = p_order_id;

  v_order := public.recalculate_order_totals(p_order_id);
  if v_order.advance_required > v_order.total_amount then
    update public.orders set advance_required = v_order.total_amount where id = p_order_id returning * into v_order;
  end if;

  perform public._order_log(p_order_id, 'EDITED', 'Order details updated', null, null,
    jsonb_build_object('fields', (select jsonb_agg(k) from jsonb_object_keys(p_changes) k)));
  perform public.log_audit('order.edited', 'order', p_order_id::text,
    (select jsonb_object_agg(k, to_jsonb(v_old) -> k) from jsonb_object_keys(p_changes) k),
    (select jsonb_object_agg(k, to_jsonb(v_order) -> k) from jsonb_object_keys(p_changes) k));
  if v_customer_id <> v_old.customer_id then
    perform public.refresh_customer_stats(v_old.customer_id);
  end if;
  perform public.refresh_customer_stats(v_customer_id);
  return v_order;
end;

admin_update_setting.src:
declare
  v_row public.settings;
  v_medium numeric;
  v_high numeric;
  v_critical numeric;
begin
  perform public.require_permission('settings.manage');
  if p_value is null or jsonb_typeof(p_value) <> 'object' then
    raise exception 'VALIDATION: setting value must be a JSON object' using errcode = '22023';
  end if;
  if p_key in ('device_approval', 'hr', 'pbx') then
    raise exception 'VALIDATION: change this setting on its own screen' using errcode = '22023';
  end if;
  if p_key = 'fraud' then
    v_medium := (p_value #>> '{thresholds,medium}')::numeric;
    v_high := (p_value #>> '{thresholds,high}')::numeric;
    v_critical := (p_value #>> '{thresholds,critical}')::numeric;
    if v_medium is null or v_high is null or v_critical is null
       or not (0 <= v_medium and v_medium < v_high and v_high < v_critical and v_critical <= 100) then
      raise exception 'VALIDATION: fraud thresholds must satisfy 0 <= medium < high < critical <= 100'
        using errcode = '22023';
    end if;
  end if;
  if p_key = 'store' and coalesce(p_value ->> 'order_prefix', '') !~ '^[A-Z0-9]{1,8}$' then
    raise exception 'VALIDATION: order prefix must be 1-8 uppercase letters or digits' using errcode = '22023';
  end if;
  if p_key = 'advanced' and coalesce((p_value ->> 'idle_logout_minutes')::int, 0) not between 0 and 1440 then
    raise exception 'VALIDATION: automatic sign-out must be between 0 (off) and 1440 minutes' using errcode = '22023';
  end if;
  if p_key = 'merchant' and jsonb_typeof(coalesce(p_value -> 'payout_accounts', '[]'::jsonb)) <> 'array' then
    raise exception 'VALIDATION: payout accounts must be a list' using errcode = '22023';
  end if;

  update public.settings set value = p_value, updated_by = auth.uid()
  where key = p_key returning * into v_row;
  if not found then
    raise exception 'NOT_FOUND: unknown setting %', p_key using errcode = 'P0002';
  end if;
  return v_row;
end;

admin_update_shopify_abandoned.src:
declare
  v_row public.shopify_abandoned_checkouts;
begin
  perform public.require_permission('orders.update');
  if p_status not in ('CONTACTED', 'DISMISSED', 'OPEN') then
    raise exception 'VALIDATION: unknown status' using errcode = '22023';
  end if;
  update public.shopify_abandoned_checkouts set
    follow_up = case p_status when 'DISMISSED' then 'DISMISSED' when 'CONTACTED' then 'CONTACTED'
      else case when contact_count > 0 then 'CONTACTED' else 'NONE' end end,
    contact_count = contact_count + case when p_status = 'CONTACTED' then 1 else 0 end,
    last_contacted_at = case when p_status = 'CONTACTED' then now() else last_contacted_at end,
    notes = case when nullif(trim(coalesce(p_note, '')), '') is null then notes
      else concat_ws(E'\n', notes, to_char(now() at time zone public.store_timezone(), 'DD Mon HH24:MI') || ' — ' || left(trim(p_note), 500)) end
  where id = p_id
  returning * into v_row;
  if v_row.id is null then
    raise exception 'NOT_FOUND: abandoned checkout not found' using errcode = 'P0002';
  end if;
  perform public.log_audit('shopify_abandoned.' || lower(p_status), 'shopify_abandoned_checkout', p_id::text, null, jsonb_build_object('note', p_note));
  return v_row;
end;

admin_update_store_cart.src:
declare
  v_row public.store_carts;
begin
  perform public.require_permission('orders.update');
  if p_status not in ('CONTACTED', 'DISMISSED', 'OPEN') then
    raise exception 'VALIDATION: unknown status' using errcode = '22023';
  end if;
  update public.store_carts set
    status = case when p_status = 'DISMISSED' then 'DISMISSED' when p_status = 'OPEN' and status = 'DISMISSED' then 'ACTIVE' else status end,
    contacted = contacted or p_status = 'CONTACTED',
    contact_count = contact_count + case when p_status = 'CONTACTED' then 1 else 0 end,
    last_contacted_at = case when p_status = 'CONTACTED' then now() else last_contacted_at end,
    notes = case when nullif(trim(coalesce(p_note, '')), '') is null then notes
      else concat_ws(E'\n', notes, to_char(now() at time zone public.store_timezone(), 'DD Mon HH24:MI') || ' — ' || left(trim(p_note), 500)) end,
    updated_at = now()
  where id = p_id and status <> 'CONVERTED'
  returning * into v_row;
  if v_row.id is null then
    raise exception 'NOT_FOUND: cart not found or already ordered' using errcode = 'P0002';
  end if;
  perform public.log_audit('store_cart.' || lower(p_status), 'store_cart', p_id::text, null, jsonb_build_object('note', p_note));
  return v_row;
end;

announcement_mark_read.src:
declare
  v_merchant uuid := public.current_merchant_id();
begin
  -- Support viewers only look; reading on the merchant's behalf is not recorded.
  if not public.is_staff() or public._support_session_id() is not null then
    return;
  end if;
  if not exists (select 1 from public.platform_announcement_deliveries where announcement_id = p_id and merchant_id = v_merchant and status = 'DELIVERED') then
    raise exception 'NOT_FOUND: announcement not found' using errcode = 'P0002';
  end if;
  insert into public.platform_announcement_reads (announcement_id, profile_id, merchant_id) values (p_id, auth.uid(), v_merchant)
  on conflict do nothing;
  if found then
    update public.platform_announcement_deliveries set first_read_at = coalesce(first_read_at, now()), readers = readers + 1
    where announcement_id = p_id and merchant_id = v_merchant;
  end if;
end;

announcement_preferences_save.src:
declare
  v_merchant uuid := public.current_merchant_id();
  v jsonb;
begin
  perform public.require_permission('settings.manage');
  if exists (select 1 from unnest(coalesce(p_muted, '{}')) k where k <> all (public._announcement_optional_kinds())) then
    raise exception 'VALIDATION: maintenance, billing, integration and usage notices cannot be turned off' using errcode = '22023';
  end if;
  v := jsonb_build_object('muted', to_jsonb(coalesce(p_muted, '{}')));
  insert into public.settings (merchant_id, key, value, is_public, description, updated_by) values (v_merchant, 'announcements', v, false, 'Platform announcements this business turned off', auth.uid())
  on conflict (merchant_id, key) do update set value = excluded.value, updated_by = auth.uid();
  return v;
end;

api_customers.src:
declare
  v_limit int := least(greatest(coalesce((p ->> 'limit')::int, 50), 1), 100);
  v_offset int := greatest(coalesce((p ->> 'offset')::int, 0), 0);
  v_phone text := nullif(public.normalize_phone(nullif(trim(coalesce(p ->> 'phone', '')), '')), '');
begin
  perform public._api_require(p_key, 'customers:read');
  return jsonb_build_object('data', coalesce((select jsonb_agg(x.j order by x.last_order_at desc nulls last) from (
      select c.last_order_at, jsonb_build_object('id', c.id, 'name', c.full_name, 'phone', c.phone, 'email', c.email, 'district', c.district,
        'segment', c.segment, 'total_orders', c.total_orders, 'delivered_orders', c.delivered_orders, 'returned_orders', c.returned_orders,
        'total_spent', c.total_spent, 'first_order_at', c.first_order_at, 'last_order_at', c.last_order_at) j
      from public.customers c where v_phone is null or c.phone = v_phone
      order by c.last_order_at desc nulls last, c.id limit v_limit offset v_offset) x), '[]'::jsonb), 'limit', v_limit, 'offset', v_offset);
end;

api_inventory.src:
declare
  v_limit int := least(greatest(coalesce((p ->> 'limit')::int, 100), 1), 500);
  v_offset int := greatest(coalesce((p ->> 'offset')::int, 0), 0);
  v_sku text := nullif(trim(coalesce(p ->> 'sku', '')), '');
begin
  perform public._api_require(p_key, 'inventory:read');
  return jsonb_build_object('data', coalesce((select jsonb_agg(x.j order by x.sku) from (
      select v.sku, jsonb_build_object('sku', v.sku, 'variant_id', v.id, 'product', pr.name, 'variant', v.title,
        'on_hand', i.on_hand, 'reserved', i.reserved, 'available', i.available, 'damaged', i.damaged, 'updated_at', i.updated_at) j
      from public.product_variants v join public.products pr on pr.id = v.product_id join public.inventory i on i.variant_id = v.id
      where v_sku is null or v.sku = v_sku
      order by v.sku limit v_limit offset v_offset) x), '[]'::jsonb), 'limit', v_limit, 'offset', v_offset);
end;

api_inventory_adjust.src:
declare
  v_variant uuid;
  v_name text;
  v_inv public.inventory;
begin
  perform public._api_require(p_key, 'inventory:write');
  select id into v_variant from public.product_variants where sku = trim(coalesce(p_sku, ''));
  if v_variant is null then
    raise exception 'NOT_FOUND: no product with SKU %', p_sku using errcode = 'P0002';
  end if;
  if upper(coalesce(p_mode, '')) not in ('SET', 'ADD', 'REMOVE') then
    raise exception 'VALIDATION: mode must be set, add or remove' using errcode = '22023';
  end if;
  select name into v_name from public.api_keys where id = p_key;
  perform public.adjust_stock(v_variant, 'ADJUSTMENT', p_quantity,
    coalesce(nullif(trim(p_note), ''), 'API') || format(' (API key "%s")', v_name), upper(p_mode));
  select * into v_inv from public.inventory where variant_id = v_variant;
  return jsonb_build_object('sku', trim(p_sku), 'on_hand', v_inv.on_hand, 'reserved', v_inv.reserved, 'available', v_inv.available);
end;

api_key_check.src:
declare
  v_row public.api_keys;
begin
  perform public._require_system();
  update public.api_keys set last_used_at = now(), request_count = request_count + 1
  where key_hash = p_hash and revoked_at is null and (expires_at is null or expires_at > now())
  returning * into v_row;
  if not found then
    return null;
  end if;
  return jsonb_build_object('id', v_row.id, 'name', v_row.name, 'scopes', to_jsonb(v_row.scopes),
    'feature', public.feature_enabled('external_api'));
end;

api_order.src:
declare
  v public.orders;
begin
  perform public._api_require(p_key, 'orders:read');
  select * into v from public.orders where order_number = p_ref or id::text = p_ref limit 1;
  if not found then
    raise exception 'NOT_FOUND: order % not found', p_ref using errcode = 'P0002';
  end if;
  return public._api_order_json(v, true);
end;

api_order_set_status.src:
declare
  v public.orders;
  v_name text;
begin
  perform public._api_require(p_key, 'orders:write');
  select * into v from public.orders where order_number = p_ref or id::text = p_ref limit 1;
  if not found then
    raise exception 'NOT_FOUND: order % not found', p_ref using errcode = 'P0002';
  end if;
  if not upper(coalesce(p_status, '')) = any(enum_range(null::public.order_status)::text[]) then
    raise exception 'VALIDATION: unknown status %', p_status using errcode = '22023';
  end if;
  -- Fraud decisions stay with people in the admin.
  if upper(p_status) in ('REJECTED_FRAUD', 'FRAUD_REVIEW') or v.status in ('FRAUD_REVIEW', 'REJECTED_FRAUD', 'ADVANCE_REQUIRED') then
    raise exception 'PERMISSION_DENIED: fraud and advance-payment decisions are made in the admin' using errcode = '42501';
  end if;
  select name into v_name from public.api_keys where id = p_key;
  v := public.transition_order_status(v.id, upper(p_status)::public.order_status, coalesce(nullif(trim(p_note), ''), format('Updated through the API (%s)', v_name)));
  perform public._order_log(v.id, 'API', format('Status set to %s through the API key "%s"', v.status, v_name), null, null, jsonb_build_object('api_key_id', p_key));
  return public._api_order_json(v, true);
end;

api_orders.src:
declare
  v_limit int := least(greatest(coalesce((p ->> 'limit')::int, 50), 1), 100);
  v_offset int := greatest(coalesce((p ->> 'offset')::int, 0), 0);
  v_status text := nullif(upper(trim(coalesce(p ->> 'status', ''))), '');
  v_since timestamptz := nullif(p ->> 'updated_since', '')::timestamptz;
  v_rows jsonb;
  v_total bigint;
begin
  perform public._api_require(p_key, 'orders:read');
  if v_status is not null and not v_status = any(enum_range(null::public.order_status)::text[]) then
    raise exception 'VALIDATION: unknown status %', v_status using errcode = '22023';
  end if;
  select count(*) into v_total from public.orders o
  where o.merged_into is null and (v_status is null or o.status::text = v_status) and (v_since is null or o.updated_at >= v_since);
  select coalesce(jsonb_agg(public._api_order_json(o, false) order by o.updated_at desc, o.id), '[]'::jsonb) into v_rows from (
    select * from public.orders o
    where o.merged_into is null and (v_status is null or o.status::text = v_status) and (v_since is null or o.updated_at >= v_since)
    order by o.updated_at desc, o.id limit v_limit offset v_offset) o;
  return jsonb_build_object('data', v_rows, 'total', v_total, 'limit', v_limit, 'offset', v_offset);
end;

api_products.src:
declare
  v_limit int := least(greatest(coalesce((p ->> 'limit')::int, 50), 1), 100);
  v_offset int := greatest(coalesce((p ->> 'offset')::int, 0), 0);
  v_search text := nullif(trim(coalesce(p ->> 'search', '')), '');
  v_rows jsonb;
  v_total bigint;
begin
  perform public._api_require(p_key, 'products:read');
  select count(*) into v_total from public.products pr where v_search is null or pr.name ilike '%' || v_search || '%' or pr.sku ilike v_search || '%';
  select coalesce(jsonb_agg(x.j order by x.updated_at desc), '[]'::jsonb) into v_rows from (
    select pr.updated_at, jsonb_build_object('id', pr.id, 'name', pr.name, 'slug', pr.slug, 'sku', pr.sku, 'status', pr.status, 'price', pr.price,
      'compare_at_price', pr.compare_at_price, 'brand', pr.brand, 'tags', to_jsonb(coalesce(pr.tags, '{}')), 'updated_at', pr.updated_at,
      'variants', coalesce((select jsonb_agg(jsonb_build_object('id', v.id, 'sku', v.sku, 'title', v.title, 'price', coalesce(v.price, pr.price), 'barcode', v.barcode,
          'active', v.is_active, 'available', i.available, 'on_hand', i.on_hand) order by v.position, v.created_at)
        from public.product_variants v left join public.inventory i on i.variant_id = v.id where v.product_id = pr.id), '[]'::jsonb)) j
    from public.products pr where v_search is null or pr.name ilike '%' || v_search || '%' or pr.sku ilike v_search || '%'
    order by pr.updated_at desc, pr.id limit v_limit offset v_offset) x;
  return jsonb_build_object('data', v_rows, 'total', v_total, 'limit', v_limit, 'offset', v_offset);
end;

api_request_log.src:
begin
  perform public._require_system();
  insert into public.api_request_logs (key_id, method, path, status, duration_ms, ip, error_code)
  values (p_key, left(p_method, 10), left(p_path, 300), p_status, p_duration_ms, left(p_ip, 64), left(p_error, 60));
end;

apply_fraud_decision.src:
begin
  perform public.require_permission('fraud.review');
  return public._apply_fraud_decision(p_order_id, p_fraud_check_id);
end;

apply_shipment_status.src:
declare
  v_ship public.shipments;
  v_order public.orders;
  v_event_id uuid;
begin
  perform public.require_permission('shipments.manage');
  select * into v_ship from public.shipments where id = p_shipment_id for update;
  if not found then
    raise exception 'NOT_FOUND: shipment not found' using errcode = 'P0002';
  end if;

  insert into public.shipment_events(shipment_id, status, description, location, source, event_key, raw, occurred_at, created_by)
  values (p_shipment_id, p_status, p_description, p_location, p_source, p_event_key, p_raw, coalesce(p_occurred_at, now()), auth.uid())
  on conflict (event_key) do nothing
  returning id into v_event_id;
  if v_event_id is null then
    return v_ship; -- duplicate callback
  end if;

  update public.shipments set status = p_status,
    delivered_at = case when p_status in ('DELIVERED', 'PARTIALLY_DELIVERED') then coalesce(delivered_at, coalesce(p_occurred_at, now())) else delivered_at end,
    return_status = case when p_status = 'RETURNING' then 'IN_TRANSIT'
                         when p_status = 'RETURNED' then 'IN_TRANSIT' else return_status end
  where id = p_shipment_id returning * into v_ship;

  if not v_ship.is_active then
    return v_ship;
  end if;
  select * into v_order from public.orders where id = v_ship.order_id for update;

  -- Cancel asked for, but the courier picked the parcel up anyway.
  if v_order.status = 'PENDING_CANCEL' and v_order.shipped_at is null
     and p_status in ('PICKED_UP', 'IN_TRANSIT', 'OUT_FOR_DELIVERY', 'DELIVERED', 'PARTIALLY_DELIVERED', 'FAILED', 'RETURNING', 'RETURNED') then
    perform public._commit_order_stock(v_order.id);
    update public.orders set shipped_at = coalesce(p_occurred_at, now()) where id = v_order.id returning * into v_order;
    perform public._order_log(v_order.id, 'PICKED_UP_DESPITE_CANCEL',
      'The courier picked the parcel up before the cancellation went through');
  end if;

  if p_status in ('PICKED_UP', 'IN_TRANSIT', 'OUT_FOR_DELIVERY') and v_order.status in ('PACKING', 'READY_TO_SHIP', 'PROCESSING') then
    if v_order.status <> 'READY_TO_SHIP' then
      perform public._order_advance_to(v_order.id, 'READY_TO_SHIP', 'Picked up by courier');
    end if;
    perform public._transition_order(v_order.id, 'SHIPPED', coalesce(p_description, 'Picked up by courier'));
  elsif p_status in ('DELIVERED', 'PARTIALLY_DELIVERED') then
    if v_order.status in ('PACKING', 'READY_TO_SHIP', 'PROCESSING') then
      if v_order.status <> 'READY_TO_SHIP' then
        perform public._order_advance_to(v_order.id, 'READY_TO_SHIP', 'Courier update');
      end if;
      perform public._transition_order(v_order.id, 'SHIPPED', 'Courier update');
      v_order.status := 'SHIPPED';
    end if;
    if p_status = 'PARTIALLY_DELIVERED' and v_order.status in ('SHIPPED', 'FAILED_DELIVERY') then
      perform public._transition_order(v_order.id, 'PARTIALLY_DELIVERED',
        coalesce(p_description, 'Partially delivered by courier — record which items came back'));
    elsif v_order.status in ('SHIPPED', 'RETURN_REQUESTED', 'FAILED_DELIVERY', 'PENDING_CANCEL', 'LOST') then
      if v_order.status = 'FAILED_DELIVERY' then
        perform public._transition_order(v_order.id, 'SHIPPED', 'Re-attempted delivery');
      end if;
      perform public._transition_order(v_order.id, 'DELIVERED', coalesce(p_description, 'Delivered by courier'));
    end if;
  elsif p_status = 'FAILED' and v_order.status = 'SHIPPED' then
    perform public._transition_order(v_order.id, 'FAILED_DELIVERY', coalesce(p_description, 'Delivery failed'));
  elsif p_status in ('RETURNING', 'RETURNED') then
    if v_order.status in ('SHIPPED', 'FAILED_DELIVERY', 'RETURN_REQUESTED', 'PENDING_CANCEL') then
      perform public._transition_order(v_order.id, 'RETURNING', coalesce(p_description, 'Parcel returning to merchant'));
    elsif v_order.status in ('DELIVERED', 'PARTIALLY_DELIVERED') then
      -- Delivered is final: a later courier "return" is recorded, the order stays delivered.
      perform public._order_log(v_order.id, 'COURIER_RETURN_AFTER_DELIVERY',
        format('The courier reported "%s" after delivery. The order stays %s; check with the courier.',
          lower(p_status::text), lower(replace(v_order.status::text, '_', ' '))));
      return v_ship;
    end if;
    if p_status = 'RETURNED' then
      perform public._order_log(v_order.id, 'PARCEL_RETURNED',
        'Courier marked the parcel as returned. Receive it to restock or mark damaged.');
    end if;
  elsif p_status = 'CANCELLED' and v_order.status = 'PENDING_CANCEL' and v_order.shipped_at is null then
    perform public._transition_order(v_order.id, 'CANCELLED', coalesce(p_description, 'Courier cancelled the parcel'));
  end if;
  return v_ship;
end;

approve_orders.src:
declare
  v_id uuid;
  v_order public.orders;
  v_ok int := 0;
  v_failed jsonb := '[]'::jsonb;
begin
  perform public.require_permission('orders.status');
  if coalesce(array_length(p_order_ids, 1), 0) > 200 then
    raise exception 'VALIDATION: at most 200 orders at a time' using errcode = '22023';
  end if;
  foreach v_id in array coalesce(p_order_ids, '{}') loop
    begin
      select * into v_order from public.orders where id = v_id for update;
      if not found then
        raise exception 'NOT_FOUND: order not found' using errcode = 'P0002';
      end if;
      if v_order.confirmed_at is not null then
        raise exception 'VALIDATION: already approved' using errcode = '22023';
      end if;
      if v_order.status = 'REJECTED_FRAUD' then
        raise exception 'VALIDATION: rejected for fraud — reopen it in fraud review first' using errcode = '22023';
      end if;
      if v_order.status = 'CANCELLED' then
        raise exception 'VALIDATION: cancelled orders cannot be approved' using errcode = '22023';
      end if;
      perform public.transition_order_status(v_id, 'CONFIRMED', coalesce(nullif(trim(p_note), ''), 'Approved'));
      update public.orders set approved_by = auth.uid() where id = v_id;
      v_ok := v_ok + 1;
    exception when others then
      v_failed := v_failed || jsonb_build_object('order_id', v_id,
        'order_number', (select order_number from public.orders where id = v_id), 'error', sqlerrm);
    end;
  end loop;
  return jsonb_build_object('approved', v_ok, 'failed', v_failed);
end;

assign_courier.src:
declare
  v_order public.orders;
  v_courier public.couriers;
  v_ship public.shipments;
  v_old public.shipments;
begin
  perform public.require_permission('shipments.manage');
  select * into v_order from public.orders where id = p_order_id for update;
  if not found then
    raise exception 'NOT_FOUND: order not found' using errcode = 'P0002';
  end if;
  if v_order.status in ('CANCELLED', 'REJECTED_FRAUD', 'DELIVERED', 'RETURNED') then
    raise exception 'VALIDATION: cannot assign a courier to a % order', v_order.status using errcode = '22023';
  end if;
  select * into v_courier from public.couriers where id = p_courier_id and is_active;
  if not found then
    raise exception 'NOT_FOUND: courier not found or inactive' using errcode = 'P0002';
  end if;
  if coalesce(p_shipping_cost, 0) < 0 then
    raise exception 'VALIDATION: shipping cost cannot be negative' using errcode = '22023';
  end if;

  select * into v_old from public.shipments where order_id = p_order_id and is_active for update;
  if found and v_old.courier_id = p_courier_id then
    update public.shipments set
      tracking_number = coalesce(nullif(trim(p_tracking_number), ''), tracking_number),
      consignment_id = coalesce(nullif(trim(p_consignment_id), ''), consignment_id),
      shipping_cost = coalesce(p_shipping_cost, shipping_cost),
      status = case when status = 'PENDING' and coalesce(nullif(trim(p_tracking_number), ''), nullif(trim(p_consignment_id), '')) is not null
                    then 'BOOKED' else status end,
      provider_payload = provider_payload || coalesce(p_provider_payload, '{}'::jsonb),
      notes = coalesce(nullif(trim(p_note), ''), notes)
    where id = v_old.id returning * into v_ship;
  else
    if found then
      update public.shipments set is_active = false, status = 'CANCELLED' where id = v_old.id;
      insert into public.shipment_events(shipment_id, status, description, source, created_by)
      values (v_old.id, 'CANCELLED', 'Replaced by another courier', 'MANUAL', auth.uid());
    end if;
    insert into public.shipments(order_id, courier_id, tracking_number, consignment_id, status, shipping_cost,
                                 return_charge, cod_amount, notes, provider_payload, created_by)
    values (p_order_id, p_courier_id, nullif(trim(p_tracking_number), ''), nullif(trim(p_consignment_id), ''),
            case when coalesce(nullif(trim(p_tracking_number), ''), nullif(trim(p_consignment_id), '')) is not null
                 then 'BOOKED' else 'PENDING' end::public.shipment_status,
            coalesce(p_shipping_cost, v_courier.default_shipping_cost, 0), v_order.return_charge,
            v_order.cod_amount, nullif(trim(p_note), ''), coalesce(p_provider_payload, '{}'::jsonb), auth.uid())
    returning * into v_ship;
    insert into public.shipment_events(shipment_id, status, description, source, created_by)
    values (v_ship.id, v_ship.status, 'Courier assigned: ' || v_courier.name,
            case when public.is_system_context() then 'API' else 'MANUAL' end::public.data_source, auth.uid());
  end if;

  perform public._order_log(p_order_id, 'COURIER_ASSIGNED',
    format('Courier %s%s', v_courier.name, coalesce(' · tracking ' || v_ship.tracking_number, '')), null, null,
    jsonb_build_object('shipment_id', v_ship.id, 'courier_id', p_courier_id), v_ship.tracking_number is not null);
  perform public.log_audit('shipment.assigned', 'order', p_order_id::text, null,
    jsonb_build_object('courier', v_courier.name, 'tracking_number', v_ship.tracking_number, 'shipping_cost', v_ship.shipping_cost));
  return v_ship;
end;

assign_customer_district.src:
declare
  v_district text := public._canonical_district(p_district);
  v_n int;
begin
  perform public.require_permission('orders.update');
  if v_district is null then
    raise exception 'VALIDATION: choose one of the 64 districts' using errcode = '22023';
  end if;
  update public.orders set shipping_district = v_district
  where customer_phone = p_phone and public._canonical_district(shipping_district) is null;
  get diagnostics v_n = row_count;
  update public.customers set district = v_district
  where phone = p_phone and public._canonical_district(district) is null;
  perform public.log_audit('customers.district_assigned', 'customer', null, null,
    jsonb_build_object('phone', p_phone, 'district', v_district, 'orders', v_n));
  return jsonb_build_object('orders', v_n, 'district', v_district);
end;

assign_orders.src:
declare
  v_count int;
begin
  perform public.require_permission('orders.assign');
  if p_agent is not null and not exists (select 1 from public.profiles p join public.roles r on r.id = p.role_id
                                         where p.id = p_agent and p.is_active) then
    raise exception 'VALIDATION: choose an active staff member' using errcode = '22023';
  end if;
  update public.orders set assigned_to = p_agent, assigned_at = case when p_agent is null then null else now() end
  where id = any(p_order_ids) and assigned_to is distinct from p_agent;
  get diagnostics v_count = row_count;
  perform public.log_audit('order.assigned', 'order', array_to_string(p_order_ids[1:5], ','), null,
    jsonb_build_object('assigned_to', p_agent), jsonb_build_object('orders', cardinality(p_order_ids)));
  return v_count;
end;

attach_gateway_session.src:
declare
  v_payment public.payments;
begin
  if not public.is_system_context() then
    raise exception 'PERMISSION_DENIED' using errcode = '42501';
  end if;
  update public.payments set
    redirect_url = coalesce(p_redirect_url, redirect_url),
    metadata = metadata || coalesce(p_metadata, '{}'::jsonb)
      || case when nullif(p_session, '') is null then '{}'::jsonb else jsonb_build_object('sessions',
           (select coalesce(jsonb_agg(distinct s), '[]'::jsonb)
            from jsonb_array_elements_text(coalesce(metadata -> 'sessions', '[]'::jsonb) || to_jsonb(left(p_session, 120))) s)) end
  where id = p_payment_id
  returning * into v_payment;
  if not found then
    raise exception 'NOT_FOUND: payment not found' using errcode = 'P0002';
  end if;
  return v_payment;
end;

attach_payment_provider_data.src:
declare
  v_payment public.payments;
begin
  if not public.is_system_context() then
    raise exception 'PERMISSION_DENIED' using errcode = '42501';
  end if;
  update public.payments set redirect_url = p_redirect_url, metadata = metadata || coalesce(p_metadata, '{}'::jsonb)
  where id = p_payment_id returning * into v_payment;
  return v_payment;
end;

audit_row_change.src:
declare
  v_old jsonb;
  v_new jsonb;
  v_key text;
  v_id text;
begin
  if tg_op = 'DELETE' and public._store_reset_active(to_jsonb(old) ->> 'merchant_id') then
    return old;
  end if;
  if tg_op = 'INSERT' then
    v_new := to_jsonb(new);
    v_id := v_new ->> coalesce(tg_argv[0], 'id');
  elsif tg_op = 'DELETE' then
    v_old := to_jsonb(old);
    v_id := v_old ->> coalesce(tg_argv[0], 'id');
  else
    v_old := '{}'::jsonb;
    v_new := '{}'::jsonb;
    for v_key in select jsonb_object_keys(to_jsonb(new)) loop
      if v_key not in ('updated_at') and (to_jsonb(new) -> v_key) is distinct from (to_jsonb(old) -> v_key) then
        v_old := v_old || jsonb_build_object(v_key, to_jsonb(old) -> v_key);
        v_new := v_new || jsonb_build_object(v_key, to_jsonb(new) -> v_key);
      end if;
    end loop;
    if v_new = '{}'::jsonb then
      return new;
    end if;
    v_id := to_jsonb(new) ->> coalesce(tg_argv[0], 'id');
  end if;
  perform public.log_audit(tg_table_name || '.' || lower(tg_op), tg_table_name, v_id, v_old, v_new);
  return coalesce(new, old);
end;

auto_assign_districts.src:
declare
  r record;
  v_done int := 0;
  v_orders int := 0;
  v_left int := 0;
  v_res jsonb;
begin
  perform public.require_permission('orders.update');
  for r in select x ->> 'phone' as phone, x ->> 'suggestion' as suggestion
           from jsonb_array_elements(public.customers_needing_district(500)) x loop
    if r.suggestion is not null and public._canonical_district(r.suggestion) is not null then
      v_res := public.assign_customer_district(r.phone, r.suggestion);
      v_done := v_done + 1;
      v_orders := v_orders + (v_res ->> 'orders')::int;
    else
      v_left := v_left + 1;
    end if;
  end loop;
  return jsonb_build_object('customers', v_done, 'orders', v_orders, 'left', v_left);
end;

auto_pick_run.src:
declare
  v_order record;
  v_agent uuid;
  v_count int := 0;
begin
  perform public.require_permission('orders.assign');
  if not coalesce((public.get_setting('auto_pick') ->> 'enabled')::boolean, false) then
    raise exception 'VALIDATION: turn Auto Pick on first' using errcode = '22023';
  end if;
  for v_order in
    select id from public.orders
    where assigned_to is null and confirmed_at is null and status not in ('CANCELLED', 'REJECTED_FRAUD')
      and review_status in (select code from public.order_review_statuses where not closes_order)
    order by created_at
    for update skip locked
  loop
    v_agent := public._auto_pick_agent();
    exit when v_agent is null;
    update public.orders set assigned_to = v_agent, assigned_at = now() where id = v_order.id;
    v_count := v_count + 1;
  end loop;
  return v_count;
end;

auto_pick_update.src:
declare
  v_mode text := coalesce(p ->> 'mode', 'round_robin');
  v_value jsonb;
begin
  perform public.require_permission('orders.assign');
  if v_mode not in ('round_robin', 'least_open') then
    raise exception 'VALIDATION: unknown mode' using errcode = '22023';
  end if;
  if coalesce((p ->> 'max_open')::int, 0) < 0 then
    raise exception 'VALIDATION: the limit cannot be negative' using errcode = '22023';
  end if;
  update public.settings set value = jsonb_build_object(
      'enabled', coalesce((p ->> 'enabled')::boolean, false),
      'mode', v_mode,
      'agent_ids', coalesce((select jsonb_agg(x) from jsonb_array_elements_text(coalesce(p -> 'agent_ids', '[]'::jsonb)) x
                             where x in (select id::text from public.profiles where is_active)), '[]'::jsonb),
      'max_open', coalesce((p ->> 'max_open')::int, 0)),
    updated_by = auth.uid()
  where key = 'auto_pick' returning value into v_value;
  perform public.log_audit('auto_pick.updated', 'settings', 'auto_pick', null, v_value, '{}'::jsonb);
  return v_value;
end;

billing_gateway_confirm.src:
declare
  v public.billing_payments;
  v_inv public.billing_invoices;
begin
  if not public.is_system_context() then
    raise exception 'PERMISSION_DENIED' using errcode = '42501';
  end if;
  select * into v from public.billing_payments where reference = p_reference and provider = p_provider and method = 'GATEWAY' for update;
  if v.id is null or (public.current_merchant_id() is not null and v.merchant_id <> public.current_merchant_id()) then
    return jsonb_build_object('status', 'unknown_payment');
  end if;
  if v.status = 'SUCCEEDED' then
    return jsonb_build_object('status', 'already_succeeded', 'invoice_id', v.invoice_id);
  end if;
  if not p_success then
    if v.status = 'PENDING' then
      update public.billing_payments set status = 'FAILED', raw = p_payload where id = v.id;
    end if;
    return jsonb_build_object('status', 'failed', 'invoice_id', v.invoice_id);
  end if;
  if p_amount is null or round(p_amount, 2) <> round(v.amount, 2) then
    update public.billing_payments set raw = p_payload, note = coalesce(note || ' · ', '') || format('gateway reported %s, expected %s', p_amount, v.amount)
    where id = v.id;
    perform public._platform_log('billing.gateway_amount_mismatch', v.merchant_id, 'billing_payment', v.id::text, null, null,
      jsonb_build_object('expected', v.amount, 'reported', p_amount, 'txn', p_txn), 'FAILED');
    return jsonb_build_object('status', 'amount_mismatch', 'invoice_id', v.invoice_id);
  end if;
  if p_txn is not null and exists (select 1 from public.billing_payments where provider = p_provider and provider_txn_id = p_txn and status = 'SUCCEEDED') then
    return jsonb_build_object('status', 'duplicate_transaction', 'invoice_id', v.invoice_id);
  end if;
  update public.billing_payments set status = 'SUCCEEDED', provider_txn_id = p_txn, verified_at = now(), raw = p_payload where id = v.id returning * into v;
  v_inv := public._billing_apply_payment(v);
  perform public._platform_log('billing.gateway_payment_succeeded', v.merchant_id, 'billing_payment', v.id::text, null, null,
    jsonb_build_object('amount', v.amount, 'provider', p_provider, 'txn', p_txn, 'invoice', v_inv.number, 'invoice_status', v_inv.status));
  if v_inv.status <> 'PAID' or v_inv.amount_paid > v_inv.total then
    -- Paid twice (two attempts both went through): flagged for the team to refund or credit.
    perform public._platform_log('billing.overpayment', v.merchant_id, 'billing_invoice', v_inv.id::text, null, null,
      jsonb_build_object('invoice', v_inv.number, 'payment', v.reference), 'FAILED');
  end if;
  return jsonb_build_object('status', 'succeeded', 'invoice_id', v.invoice_id, 'invoice_status', v_inv.status, 'kind', v_inv.kind);
end;

billing_gateway_payment_create.src:
declare
  v_merchant uuid := public.current_merchant_id();
  v_inv public.billing_invoices;
  v public.billing_payments;
  m public.merchants;
begin
  if not public.is_system_context() then
    raise exception 'PERMISSION_DENIED' using errcode = '42501';
  end if;
  select * into v_inv from public.billing_invoices where id = p_invoice and merchant_id = v_merchant;
  if v_inv.id is null then
    raise exception 'NOT_FOUND: invoice not found' using errcode = 'P0002';
  end if;
  if v_inv.status <> 'OPEN' or v_inv.total - v_inv.amount_paid <= 0 then
    raise exception 'VALIDATION: this invoice is already %', lower(v_inv.status) using errcode = '22023';
  end if;
  if not coalesce((select (value -> p_provider ->> 'enabled')::boolean from public.platform_settings where key = 'billing_gateways'), false) then
    raise exception 'VALIDATION: this payment method is not available' using errcode = '22023';
  end if;
  if (select count(*) from public.billing_payments where invoice_id = v_inv.id and method = 'GATEWAY' and created_at > now() - interval '1 hour') >= 10 then
    raise exception 'VALIDATION: too many payment attempts for this invoice; try again later' using errcode = '22023';
  end if;
  select * into m from public.merchants where id = v_merchant;
  insert into public.billing_payments (merchant_id, invoice_id, amount, method, provider, reference, status, note)
  values (v_merchant, v_inv.id, v_inv.total - v_inv.amount_paid, 'GATEWAY', p_provider,
          'BP-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 14)), 'PENDING', 'Paid online by the merchant')
  returning * into v;
  return jsonb_build_object('payment_id', v.id, 'reference', v.reference, 'amount', v.amount, 'currency', v_inv.currency,
    'invoice_number', v_inv.number, 'kind', v_inv.kind,
    'merchant', jsonb_build_object('name', m.name, 'phone', coalesce(m.phone, ''), 'email', m.owner_email, 'address', coalesce(m.address, '')));
end;

billing_gateway_payment_session.src:
begin
  if not public.is_system_context() then
    raise exception 'PERMISSION_DENIED' using errcode = '42501';
  end if;
  update public.billing_payments set provider_session = left(p_session, 200)
  where id = p_payment and merchant_id = public.current_merchant_id() and status = 'PENDING';
end;

billing_run.src:
declare
  v_cfg jsonb := coalesce((select value from public.platform_settings where key = 'billing'), '{}'::jsonb);
  v_grace int := coalesce((v_cfg ->> 'grace_days')::int, 7);
  v_expire int := coalesce((v_cfg ->> 'expire_after_days')::int, 30);
  s public.subscriptions;
  v_inv public.billing_invoices;
  v_start timestamptz;
  v_end timestamptz;
  v jsonb := jsonb_build_object('renewed', 0, 'past_due', 0, 'expired', 0, 'cancelled', 0, 'trials_ended', 0);
begin
  if not public.is_system_context() then
    raise exception 'PERMISSION_DENIED' using errcode = '42501';
  end if;
  for s in select * from public.subscriptions where ended_at is null and status in ('TRIALING', 'ACTIVE', 'PAST_DUE') order by created_at for update skip locked loop
    if s.status = 'TRIALING' and s.trial_ends_at <= now() then
      v_start := s.trial_ends_at;
      v_end := v_start + public._billing_interval(s.billing_interval);
      v_inv := public._billing_invoice_for(s, v_start, v_end);
      if v_inv.status = 'PAID' then
        update public.subscriptions set status = 'ACTIVE', current_period_start = v_start, current_period_end = v_end where id = s.id;
      else
        update public.subscriptions set status = 'PAST_DUE', grace_until = v_start + make_interval(days => v_grace) where id = s.id;
        v := jsonb_set(v, '{past_due}', to_jsonb((v ->> 'past_due')::int + 1));
      end if;
      perform public._subscription_event(s, 'trial.ended', jsonb_build_object('invoice', v_inv.number));
      v := jsonb_set(v, '{trials_ended}', to_jsonb((v ->> 'trials_ended')::int + 1));
    elsif s.status = 'ACTIVE' and s.current_period_end is not null and s.current_period_end <= now() then
      if s.cancel_at_period_end then
        update public.subscriptions set status = 'CANCELLED', cancelled_at = now(), ended_at = now() where id = s.id;
        perform public._subscription_event(s, 'subscription.cancelled', '{"at_period_end": true}');
        v := jsonb_set(v, '{cancelled}', to_jsonb((v ->> 'cancelled')::int + 1));
        continue;
      end if;
      v_start := s.current_period_end;
      v_end := v_start + public._billing_interval(s.billing_interval);
      v_inv := public._billing_invoice_for(s, v_start, v_end);
      if v_inv.status = 'PAID' then
        update public.subscriptions set current_period_start = v_start, current_period_end = v_end where id = s.id;
        v := jsonb_set(v, '{renewed}', to_jsonb((v ->> 'renewed')::int + 1));
      else
        update public.subscriptions set status = 'PAST_DUE', grace_until = v_start + make_interval(days => v_grace) where id = s.id;
        perform public._subscription_event(s, 'subscription.past_due', jsonb_build_object('invoice', v_inv.number));
        v := jsonb_set(v, '{past_due}', to_jsonb((v ->> 'past_due')::int + 1));
      end if;
    elsif s.status = 'PAST_DUE' and s.grace_until is not null and s.grace_until + make_interval(days => greatest(v_expire - v_grace, 0)) <= now() then
      update public.subscriptions set status = 'EXPIRED', ended_at = now() where id = s.id;
      perform public._subscription_event(s, 'subscription.expired');
      v := jsonb_set(v, '{expired}', to_jsonb((v ->> 'expired')::int + 1));
    end if;
  end loop;
  v := v || jsonb_build_object('credits_expired', public.credits_expire_all());
  return v;
end;

bulk_transition_orders.src:
declare
  v_id uuid;
  v_ok int := 0;
  v_failed jsonb := '[]'::jsonb;
begin
  if coalesce(array_length(p_order_ids, 1), 0) > 200 then
    raise exception 'VALIDATION: at most 200 orders per bulk update' using errcode = '22023';
  end if;
  foreach v_id in array coalesce(p_order_ids, '{}') loop
    begin
      if p_to in ('PRODUCTION', 'PACKING', 'READY_TO_SHIP') and (select status from public.orders where id = v_id) = 'CONFIRMED' then
        perform public.transition_order_status(v_id, 'PROCESSING', p_note);
      end if;
      perform public.transition_order_status(v_id, p_to, p_note);
      v_ok := v_ok + 1;
    exception when others then
      v_failed := v_failed || jsonb_build_object(
        'order_id', v_id,
        'order_number', (select order_number from public.orders where id = v_id),
        'error', sqlerrm);
    end;
  end loop;
  return jsonb_build_object('updated', v_ok, 'failed', v_failed);
end;

calculate_order_quote.src:
declare
  v_lines jsonb := '[]'::jsonb;
  v_item record;
  v_subtotal numeric := 0;
  v_cost numeric := 0;
  v_zone public.delivery_zones;
  v_method_extra numeric;
  v_delivery numeric := 0;
  v_coupon jsonb;
  v_coupon_discount numeric := 0;
  v_delivery_discount numeric := 0;
  v_max_qty int := public.setting_numeric('orders', array['max_quantity_per_item'], 50)::int;
  v_errors jsonb := '[]'::jsonb;
  v_unit numeric;
begin
  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'VALIDATION: the cart is empty' using errcode = '22023';
  end if;

  for v_item in
    with requested as (
      select (e ->> 'variant_id')::uuid as variant_id,
             sum((e ->> 'quantity')::int) as quantity,
             max(nullif(e ->> 'unit_price', '')::numeric) as unit_price_override
      from jsonb_array_elements(p_items) e
      group by 1
    )
    select r.variant_id, r.quantity, r.unit_price_override,
           v.sku, v.title as variant_title, v.is_active as variant_active,
           p.id as product_id, p.name as product_name, p.status as product_status,
           p.track_inventory, p.requires_production,
           coalesce(v.price, p.price) as unit_price,
           coalesce(v.cost_price, p.cost_price, 0) as unit_cost,
           coalesce(i.available, 0) as available,
           (select pi.url from public.product_images pi
             where pi.product_id = p.id and (pi.variant_id = v.id or pi.variant_id is null)
             order by (pi.variant_id = v.id) desc nulls last, pi.is_primary desc, pi.position limit 1) as image_url
    from requested r
    left join public.product_variants v on v.id = r.variant_id
    left join public.products p on p.id = v.product_id
    left join public.inventory i on i.variant_id = v.id
  loop
    if v_item.sku is null then
      raise exception 'VALIDATION: a product in the cart no longer exists' using errcode = '22023';
    end if;
    if not p_allow_inactive and (v_item.product_status <> 'ACTIVE' or not v_item.variant_active) then
      raise exception 'VALIDATION: % is no longer available', v_item.product_name using errcode = '22023';
    end if;
    if v_item.quantity is null or v_item.quantity < 1 then
      raise exception 'VALIDATION: quantity must be at least 1' using errcode = '22023';
    end if;
    if v_item.quantity > v_max_qty then
      raise exception 'VALIDATION: you can order at most % of %', v_max_qty, v_item.product_name using errcode = '22023';
    end if;
    if v_item.track_inventory and v_item.available < v_item.quantity and not public.allow_overselling() then
      v_errors := v_errors || jsonb_build_object('variant_id', v_item.variant_id, 'code', 'INSUFFICIENT_STOCK',
        'message', case when v_item.available <= 0 then format('%s is out of stock', v_item.product_name)
                        else format('Only %s of %s left in stock', v_item.available, v_item.product_name) end,
        'available', greatest(v_item.available, 0));
    end if;

    v_unit := case when p_allow_price_override and v_item.unit_price_override is not null
                   then v_item.unit_price_override else v_item.unit_price end;
    if v_unit < 0 then
      raise exception 'VALIDATION: price cannot be negative' using errcode = '22023';
    end if;

    v_lines := v_lines || jsonb_build_object(
      'variant_id', v_item.variant_id,
      'product_id', v_item.product_id,
      'product_name', v_item.product_name,
      'variant_title', v_item.variant_title,
      'sku', v_item.sku,
      'image_url', v_item.image_url,
      'unit_price', public.money(v_unit),
      'unit_cost', public.money(v_item.unit_cost),
      'quantity', v_item.quantity,
      'line_subtotal', public.money(v_unit * v_item.quantity),
      'track_inventory', v_item.track_inventory,
      'requires_production', v_item.requires_production,
      'available', case when v_item.track_inventory then greatest(v_item.available, 0) end
    );
    v_subtotal := v_subtotal + public.money(v_unit * v_item.quantity);
    v_cost := v_cost + public.money(v_item.unit_cost * v_item.quantity);
  end loop;

  v_zone := public.resolve_delivery_zone(p_district, p_area);
  v_method_extra := public.delivery_method_extra(p_delivery_method);
  if v_method_extra is null then
    raise exception 'VALIDATION: delivery method % is not available', p_delivery_method using errcode = '22023';
  end if;
  if v_zone.id is not null then
    v_delivery := v_zone.charge + v_method_extra;
  elsif coalesce(trim(p_district), '') <> '' and coalesce(current_setting('app.store_order_import', true), '') <> 'on' then
    raise exception 'VALIDATION: we do not deliver to % yet', p_district using errcode = '22023';
  end if;

  -- Free delivery over a configured order value.
  if public.setting_numeric('delivery', array['free_delivery_threshold'], 0) > 0
     and v_subtotal >= public.setting_numeric('delivery', array['free_delivery_threshold'], 0) then
    v_delivery_discount := v_delivery;
  end if;

  if coalesce(trim(p_coupon_code), '') <> '' then
    v_coupon := public.evaluate_coupon(p_coupon_code, v_subtotal, p_phone, v_delivery);
    if (v_coupon ->> 'valid')::boolean then
      v_coupon_discount := (v_coupon ->> 'discount_amount')::numeric;
      v_delivery_discount := greatest(v_delivery_discount, (v_coupon ->> 'delivery_discount')::numeric);
    end if;
  end if;

  -- Allocate the coupon discount across lines (largest line takes rounding).
  v_lines := public._allocate_discount(v_lines, v_coupon_discount);

  return jsonb_build_object(
    'lines', v_lines,
    'subtotal', public.money(v_subtotal),
    'coupon', v_coupon,
    'coupon_discount', public.money(v_coupon_discount),
    'discount_total', public.money(v_coupon_discount),
    'delivery_zone', case when v_zone.id is null then null else jsonb_build_object(
      'id', v_zone.id, 'name', v_zone.name, 'charge', v_zone.charge, 'return_charge', v_zone.return_charge,
      'estimated_days', v_zone.estimated_days) end,
    'delivery_method', coalesce(nullif(p_delivery_method, ''), 'standard'),
    'delivery_charge', public.money(v_delivery),
    'delivery_discount', public.money(v_delivery_discount),
    'return_charge', public.money(coalesce(v_zone.return_charge, 0)),
    'total', public.money(v_subtotal - v_coupon_discount + v_delivery - v_delivery_discount),
    'cost_total', public.money(v_cost),
    'stock_errors', v_errors
  );
end;

capture_checkout_lead.src:
declare
  v_visitor text := nullif(left(p_input ->> 'visitor_id', 64), '');
  v_phone text := public.clean_phone(p_input ->> 'phone');
  v_id uuid;
  v_items jsonb := coalesce(p_input -> 'items', '[]'::jsonb);
  v_source text;
begin
  if not public.feature_enabled('abandoned_carts') then
    return null;
  end if;
  if not public.is_system_context() then
    raise exception 'PERMISSION_DENIED' using errcode = '42501';
  end if;
  if not public.setting_bool('orders', array['capture_incomplete'], true)
     or v_visitor is null or length(v_visitor) < 8 or v_phone is null
     or jsonb_typeof(v_items) <> 'array' or jsonb_array_length(v_items) = 0 or jsonb_array_length(v_items) > 50 then
    return null;
  end if;
  if exists (select 1 from public.orders where customer_phone = v_phone and created_at > now() - interval '30 minutes') then
    return null;
  end if;
  v_source := case when jsonb_typeof(p_input -> 'attribution' -> 'last_touch') = 'object'
    then public.classify_touch(p_input -> 'attribution' -> 'last_touch') ->> 'source' else 'Direct' end;

  insert into public.checkout_leads(visitor_id, phone, customer_name, address, district, area, items, subtotal, total, attribution, source)
  values (v_visitor, v_phone, left(nullif(trim(p_input ->> 'customer_name'), ''), 100), left(nullif(trim(p_input ->> 'address'), ''), 300),
    left(nullif(trim(p_input ->> 'district'), ''), 60), left(nullif(trim(p_input ->> 'area'), ''), 80), v_items,
    coalesce((p_input ->> 'subtotal')::numeric, 0), coalesce((p_input ->> 'total')::numeric, 0),
    case when length(coalesce(p_input -> 'attribution', 'null'::jsonb)::text) <= 20000 then p_input -> 'attribution' end, v_source)
  on conflict (merchant_id, visitor_id) where status in ('OPEN', 'CONTACTED') do update set
    phone = excluded.phone,
    customer_name = coalesce(excluded.customer_name, public.checkout_leads.customer_name),
    address = coalesce(excluded.address, public.checkout_leads.address),
    district = coalesce(excluded.district, public.checkout_leads.district),
    area = coalesce(excluded.area, public.checkout_leads.area),
    items = excluded.items, subtotal = excluded.subtotal, total = excluded.total,
    attribution = coalesce(excluded.attribution, public.checkout_leads.attribution),
    source = excluded.source, updated_at = now()
  returning id into v_id;

  -- The visitor's cart reached checkout: now we know who it is.
  update public.store_carts set reached_checkout = true, lead_id = v_id, phone = v_phone,
    customer_name = coalesce(left(nullif(trim(p_input ->> 'customer_name'), ''), 100), customer_name),
    last_activity_at = now(), updated_at = now()
  where visitor_id = v_visitor and status = 'ACTIVE';
  return v_id;
end;

channel_abandoned_complete.src:
begin
  perform public._require_system();
  update public.shopify_abandoned_checkouts
  set completed_at = coalesce(completed_at, p_completed_at, now()), status = 'RECOVERED', synced_at = now()
  where channel_id = p_channel_id and external_id = p_external_id;
  return found;
end;

channel_attach_fraud_check.src:
begin
  perform public._require_system();
  update public.orders set fraud_check_id = p_check_id where id = p_order_id and fraud_check_id is null;
end;

channel_catalog_adopt.src:
declare
  v_r jsonb;
begin
  perform public.require_permission('products.manage');
  if p_with_stock then
    perform public.require_permission('inventory.adjust');
  end if;
  if coalesce(array_length(p_product_ids, 1), 0) = 0 then
    raise exception 'VALIDATION: choose at least one product' using errcode = '22023';
  end if;
  if array_length(p_product_ids, 1) > 500 then
    raise exception 'VALIDATION: import at most 500 products at a time' using errcode = '22023';
  end if;
  v_r := public._channel_catalog_adopt(p_channel_id, p_product_ids, p_with_stock, p_apply, null);
  if p_apply then
    perform public.log_audit('channel.catalog_adopt', 'sales_channel', p_channel_id::text, null,
      jsonb_build_object('products', p_product_ids, 'created', v_r -> 'created', 'linked', v_r -> 'linked', 'with_stock', p_with_stock));
  end if;
  return v_r;
end;

channel_catalog_import.src:
declare
  v_item jsonb;
  v_linked int;
  v_auto jsonb;
  v_updated int;
begin
  perform public._require_system();
  update public.sales_channels set locations = coalesce(p_locations, '[]'::jsonb), catalog_imported_at = now() where id = p_channel_id;
  for v_item in select * from jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) loop
    perform public._channel_catalog_put(p_channel_id, v_item);
  end loop;
  perform public._channel_catalog_collections(p_channel_id, p_items);
  v_linked := public._channel_link_by_sku(p_channel_id);
  v_auto := public._channel_autoimport(p_channel_id, null);
  v_updated := public._channel_apply_store_details(p_channel_id, null);
  return jsonb_build_object('items', jsonb_array_length(coalesce(p_items, '[]'::jsonb)), 'linked', v_linked,
    'mapped', (select count(*) from public.sales_channel_variants where channel_id = p_channel_id and inventory_item_id is not null),
    'imported', coalesce((v_auto ->> 'created')::int, 0), 'updated', v_updated);
end;

channel_catalog_product_upsert.src:
declare
  v_item jsonb;
  v_removed int;
  v_auto jsonb;
  v_keep text[];
  v_updated int;
begin
  perform public._require_system();
  if nullif(trim(coalesce(p_product_id, '')), '') is null then
    raise exception 'VALIDATION: product id missing' using errcode = '22023';
  end if;
  for v_item in select * from jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) loop
    continue when v_item ->> 'external_product_id' is distinct from p_product_id;
    perform public._channel_catalog_put(p_channel_id, v_item);
  end loop;
  perform public._channel_catalog_collections(p_channel_id, p_items);
  select coalesce(array_agg(x ->> 'external_variant_id'), '{}') into v_keep from jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) x;
  update public.channel_catalog_items set removed_at = now()
  where channel_id = p_channel_id and external_product_id = p_product_id and removed_at is null
    and not (external_variant_id = any (v_keep));
  get diagnostics v_removed = row_count;
  update public.sales_channel_variants m set inventory_item_id = null, sync_status = 'FAILED',
    last_error = 'Removed from the store', mismatch_since = null
  from public.channel_catalog_items ci
  where ci.channel_id = p_channel_id and ci.external_product_id = p_product_id and ci.removed_at is not null
    and m.channel_id = p_channel_id and m.external_variant_id = ci.external_variant_id and m.inventory_item_id is not null;
  perform public._channel_link_by_sku(p_channel_id);
  v_auto := public._channel_autoimport(p_channel_id, array[p_product_id]);
  v_updated := public._channel_apply_store_details(p_channel_id, array[p_product_id]);
  return jsonb_build_object('items', jsonb_array_length(coalesce(p_items, '[]'::jsonb)), 'removed', v_removed,
    'imported', coalesce((v_auto ->> 'created')::int, 0), 'updated', v_updated);
end;

channel_catalog_summary.src:
declare
  v_c public.sales_channels;
begin
  perform public.require_permission('products.view');
  select * into v_c from public.sales_channels where id = p_channel_id;
  if not found then
    raise exception 'NOT_FOUND: sales channel not found' using errcode = 'P0002';
  end if;
  return (
    with items as (
      select ci.*, exists (select 1 from public.sales_channel_variants m
                           where m.channel_id = ci.channel_id and m.external_variant_id = ci.external_variant_id) as here
      from public.channel_catalog_items ci
      where ci.channel_id = p_channel_id and ci.removed_at is null and ci.external_product_id is not null
    ), prods as (
      select external_product_id, max(product_title) as title, upper(coalesce(max(product_status), 'ACTIVE')) as status,
        count(*) as variants, count(*) filter (where here) as here
      from items group by external_product_id
    )
    select jsonb_build_object(
      'read_at', v_c.catalog_imported_at,
      'store_products', (select count(*) from prods),
      'store_variants', (select count(*) from items),
      'by_status', coalesce((select jsonb_object_agg(status, n) from (select status, count(*) n from prods group by status) s), '{}'::jsonb),
      'imported_products', (select count(*) from prods where here = variants),
      'imported_variants', (select count(*) from items where here),
      'products_here', (select count(distinct pv.product_id) from public.sales_channel_variants m
                        join public.product_variants pv on pv.id = m.variant_id where m.channel_id = p_channel_id),
      'missing', coalesce((select jsonb_agg(jsonb_build_object('product_id', external_product_id, 'title', title, 'status', status,
          'variants', variants, 'imported', here,
          'reason', case when v_c.first_sync_at is null then 'FIRST_SYNC'
                         when status = 'TRASH' then 'TRASH'
                         when not public._channel_opt(v_c, 'auto_import_products', true) then 'AUTO_IMPORT_OFF'
                         else 'NEXT_REFRESH' end) order by title)
        from (select * from prods where here < variants limit 200) q), '[]'::jsonb))
  );
end;

channel_checkout_decision.src:
declare
  v_block jsonb;
  v_check public.fraud_checks;
  v_message text;
begin
  perform public._require_system();
  v_block := public.order_block_match(p_phone, p_ip, p_address);
  if v_block is not null then
    return jsonb_build_object('decision', 'block', 'reason', 'BLOCK_LIST',
      'message', public.setting_text('fraud', array['messages', 'blocked'], 'We are unable to accept this order online. Please contact us to complete your purchase.'));
  end if;
  if p_check_id is null then
    return jsonb_build_object('decision', 'allow', 'reason', 'NO_CHECK');
  end if;
  select * into v_check from public.fraud_checks where id = p_check_id;
  if v_check.id is null or v_check.status = 'ERROR' then
    return jsonb_build_object('decision', 'allow', 'reason', 'CHECK_UNAVAILABLE');
  end if;
  if v_check.decision = 'BLOCK' then
    return jsonb_build_object('decision', 'block', 'reason', 'RULE',
      'message', public.setting_text('fraud', array['messages', 'blocked'], 'We are unable to accept this order online. Please contact us to complete your purchase.'));
  end if;
  if v_check.decision = 'ADVANCE_REQUIRED' then
    v_message := coalesce(nullif(public.get_setting('fraud') #>> '{receive_rate,message}', ''),
      'To confirm this order, please pay {amount} in advance.');
    return jsonb_build_object('decision', 'advance', 'reason', 'ADVANCE', 'advance_amount', v_check.advance_amount,
      'message', replace(v_message, '{amount}', coalesce(public.money(v_check.advance_amount)::text || ' tk', 'the delivery charge')));
  end if;
  return jsonb_build_object('decision', 'allow', 'reason', coalesce(v_check.decision::text, 'ALLOW'));
end;

channel_cost_seen.src:
declare
  v_n int;
begin
  perform public._require_system();
  if p_cost is null or p_cost < 0 then
    return jsonb_build_object('status', 'NO_COST');
  end if;
  update public.channel_catalog_items set unit_cost = public.money(p_cost)
  where channel_id = p_channel_id and inventory_item_id = p_inventory_item_id;
  with v as (
    update public.product_variants pv set cost_price = public.money(p_cost)
    from public.sales_channel_variants m
    where m.channel_id = p_channel_id and m.inventory_item_id = p_inventory_item_id and pv.id = m.variant_id
      and pv.cost_price is distinct from public.money(p_cost)
    returning pv.product_id)
  update public.products p set cost_price = public.money(p_cost)
  from (select distinct product_id from v) x
  where p.id = x.product_id and (select count(*) from public.product_variants where product_id = p.id) = 1;
  get diagnostics v_n = row_count;
  return jsonb_build_object('status', 'OK', 'products', v_n);
end;

channel_delivery_first.src:
declare
  v_new boolean;
begin
  perform public._require_system();
  if nullif(trim(coalesce(p_delivery_id, '')), '') is null then
    return true;
  end if;
  insert into public.channel_webhook_deliveries(channel_id, delivery_id, topic)
  values (p_channel_id, left(p_delivery_id, 200), left(p_topic, 80))
  on conflict do nothing;
  get diagnostics v_new = row_count;
  return v_new;
end;

channel_delivery_seen.src:
begin
  perform public._require_system();
  return exists (select 1 from public.channel_webhook_deliveries where channel_id = p_channel_id and delivery_id = left(p_delivery_id, 200));
end;

channel_first_sync.src:
declare
  v_out jsonb;
begin
  perform public.require_permission('settings.manage');
  perform public.require_permission('products.manage');
  perform public.require_permission('inventory.adjust');
  if p_apply then
    v_out := public._channel_first_sync_run(p_channel_id, p_location_id, p_auto_import);
    update public.sales_channels set settings = settings || '{"external_changes":"TWO_WAY"}'::jsonb where id = p_channel_id;
    perform public._channel_apply_store_details(p_channel_id, null);
    perform public.log_audit('channel.first_sync', 'sales_channel', p_channel_id::text, null,
      jsonb_build_object('location_id', p_location_id, 'create', v_out -> 'create', 'link', v_out -> 'link',
        'stock_corrected', jsonb_array_length(v_out -> 'stock_changes')));
    return v_out || jsonb_build_object('applied', true);
  end if;
  begin
    v_out := public._channel_first_sync_run(p_channel_id, p_location_id, p_auto_import);
    raise exception 'preview' using errcode = 'XP001';
  exception when sqlstate 'XP001' then
    null;
  end;
  return v_out || jsonb_build_object('applied', false);
end;

channel_fulfillment_context.src:
declare
  v_order public.orders;
  v_eff public.orders;
  v_f public.channel_fulfillments;
  v_ship record;
  v_c public.sales_channels;
  v_sync public.channel_order_sync;
  v_import jsonb;
begin
  perform public._require_system();
  select * into v_order from public.orders where id = p_order_id;
  select * into v_eff from public.orders where id = public._effective_order_id(p_order_id);
  select * into v_c from public.sales_channels where id = v_order.sales_channel_id;
  select * into v_f from public.channel_fulfillments where order_id = p_order_id and source = 'APP';
  select * into v_sync from public.channel_order_sync where order_id = p_order_id;
  select payload -> 'lines' into v_import from public.channel_order_imports
  where channel_id = v_order.sales_channel_id and order_id = p_order_id order by created_at desc limit 1;
  select s.consignment_id, s.tracking_number, s.created_at, s.status, c.name as courier_name, c.provider, c.tracking_url_template
  into v_ship from public.shipments s join public.couriers c on c.id = s.courier_id
  where s.order_id = v_eff.id and s.is_active order by s.created_at desc limit 1;
  return jsonb_build_object(
    'order', jsonb_build_object('id', v_order.id, 'order_number', v_order.order_number, 'status', v_eff.status,
      'own_status', v_order.status, 'merged_into', case when v_eff.id <> v_order.id then v_eff.order_number end,
      'external_order_id', v_order.external_order_id, 'customer_email', v_order.customer_email, 'shipped_at', v_eff.shipped_at,
      'delivered_at', v_eff.delivered_at, 'payment_method', v_order.payment_method, 'was_delivered', v_eff.delivered_at is not null),
    'fulfillment', case when v_f.id is null then null else to_jsonb(v_f) end,
    'delivered_target', coalesce(v_f.fulfillment_id, (select f.fulfillment_id from public.channel_fulfillments f
      where f.order_id = p_order_id and f.source = 'SHOPIFY' and f.fulfillment_id is not null order by f.created_at desc limit 1)),
    'sync', case when v_sync.order_id is null then null else to_jsonb(v_sync) end,
    'settings', jsonb_build_object(
      'inventory_sync', public._channel_opt(v_c, 'inventory_sync', false),
      'mark_paid_on_delivery', public._channel_opt(v_c, 'mark_paid_on_delivery', true),
      'status_tags', public._channel_opt(v_c, 'status_tags', true),
      'courier_events', public._channel_opt(v_c, 'courier_events', true),
      'status_sync', public._channel_opt(v_c, 'status_sync', true),
      'fulfill_on_ship', public._channel_opt(v_c, 'fulfill_on_ship', v_c.platform = 'SHOPIFY')),
    'status_tag', case when v_eff.id <> v_order.id and v_eff.status <> 'CANCELLED'
      then public._channel_status_tag(v_eff.status) else public._channel_status_tag(v_order.status) end,
    'merged_tag', case when v_eff.id <> v_order.id then 'Fullfilio: merged into ' || v_eff.order_number end,
    'shipment', case when v_ship is null then null else jsonb_build_object(
      'courier', v_ship.courier_name, 'provider', v_ship.provider,
      'tracking', coalesce(v_ship.consignment_id, v_ship.tracking_number),
      'tracking_url', case when v_ship.tracking_url_template is not null and coalesce(v_ship.consignment_id, v_ship.tracking_number) is not null
        then replace(v_ship.tracking_url_template, '{tracking}', coalesce(v_ship.consignment_id, v_ship.tracking_number)) end,
      'shipped_at', v_ship.created_at) end,
    'lines', coalesce((select jsonb_agg(jsonb_build_object('variant_id', i.variant_id, 'sku', i.sku,
        'quantity', i.quantity - i.returned_quantity,
        'external_variant_id', (select m.external_variant_id from public.sales_channel_variants m
                                where m.channel_id = v_order.sales_channel_id and m.variant_id = i.variant_id limit 1)))
      from public.order_items i where i.order_id = p_order_id), '[]'::jsonb),
    -- Items received back as good, per line, with the store's ids for the line (from the
    -- product link, else from the imported store order).
    'restock_lines', coalesce((select jsonb_agg(jsonb_build_object(
        'external_variant_id', coalesce(
          (select m.external_variant_id from public.sales_channel_variants m where m.channel_id = v_order.sales_channel_id and m.variant_id = i.variant_id limit 1),
          (select l ->> 'external_variant_id' from jsonb_array_elements(coalesce(v_import, '[]'::jsonb)) l
           where nullif(l ->> 'sku', '') is not null and l ->> 'sku' = i.sku limit 1)),
        'sku', i.sku, 'name', i.product_name, 'quantity', i.returned_quantity) order by i.created_at)
      from public.order_items i where i.order_id = p_order_id and i.returned_quantity > 0), '[]'::jsonb)
  );
end;

channel_fulfillment_retry.src:
declare
  v_f public.channel_fulfillments;
  v_order public.orders;
begin
  perform public.require_permission('orders.update');
  select * into v_order from public.orders where id = p_order_id;
  if not found then
    raise exception 'NOT_FOUND: order not found' using errcode = 'P0002';
  end if;
  if v_order.status not in ('SHIPPED', 'DELIVERED', 'PARTIALLY_DELIVERED') then
    raise exception 'VALIDATION: only shipped orders are fulfilled on the store' using errcode = '22023';
  end if;
  perform public._queue_channel_fulfillment(p_order_id);
  update public.channel_fulfillments set status = 'PENDING', last_error = null
  where order_id = p_order_id and source = 'APP' and status in ('FAILED', 'NEEDS_TRACKING')
  returning * into v_f;
  if v_order.status = 'DELIVERED' then
    update public.channel_fulfillments set delivered_status = 'PENDING', delivered_error = null
    where order_id = p_order_id and source = 'APP' and delivered_status in ('FAILED', 'SKIPPED');
  end if;
  select * into v_f from public.channel_fulfillments where order_id = p_order_id and source = 'APP';
  if v_f.status = 'PENDING' or v_f.delivered_status = 'PENDING' then
    update public.channel_sync_jobs set status = 'PENDING', attempts = 0, next_attempt_at = now()
    where kind = 'FULFILL' and ref_id = p_order_id and status = 'FAILED'
      and not exists (select 1 from public.channel_sync_jobs o where o.kind = 'FULFILL' and o.ref_id = p_order_id and o.status in ('PENDING', 'RUNNING'));
    perform public.channel_job_enqueue(v_f.channel_id, 'FULFILL', p_order_id);
  end if;
  perform public.log_audit('channel.fulfillment_retry', 'order', p_order_id::text, null,
    jsonb_build_object('status', v_f.status, 'delivered_status', v_f.delivered_status));
  return jsonb_build_object('status', v_f.status, 'delivered_status', v_f.delivered_status);
end;

channel_fulfillment_update.src:
declare
  v_old public.channel_fulfillments;
  v_row public.channel_fulfillments;
  v_status text := p ->> 'status';
  v_store text;
begin
  perform public._require_system();
  select * into v_old from public.channel_fulfillments where order_id = p_order_id and source = 'APP' for update;
  if not found then
    raise exception 'NOT_FOUND: no fulfilment for this order' using errcode = 'P0002';
  end if;
  if v_status = 'FULFILLED' and nullif(p ->> 'fulfillment_id', '') is null then
    raise exception 'VALIDATION: a fulfilment is only recorded with the store''s fulfilment id' using errcode = '22023';
  end if;
  if p ->> 'delivered_status' = 'MARKED' and nullif(p ->> 'delivered_event_id', '') is null then
    raise exception 'VALIDATION: delivered is only recorded with the store''s event id' using errcode = '22023';
  end if;
  select case platform when 'SHOPIFY' then 'Shopify' else 'WooCommerce' end into v_store from public.sales_channels where id = v_old.channel_id;
  update public.channel_fulfillments set
    status = coalesce(v_status, status),
    fulfillment_id = coalesce(nullif(p ->> 'fulfillment_id', ''), fulfillment_id),
    fulfillment_order_ids = coalesce((select array_agg(x) from jsonb_array_elements_text(p -> 'fulfillment_order_ids') x), fulfillment_order_ids),
    line_items = coalesce(p -> 'line_items', line_items),
    courier = coalesce(p ->> 'courier', courier),
    tracking_number = coalesce(p ->> 'tracking_number', tracking_number),
    tracking_url = coalesce(p ->> 'tracking_url', tracking_url),
    shipped_at = coalesce((p ->> 'shipped_at')::timestamptz, shipped_at),
    shopify_status = coalesce(p ->> 'shopify_status', shopify_status),
    notify_requested = coalesce((p ->> 'notify_requested')::boolean, notify_requested),
    notification_status = coalesce(p ->> 'notification_status', notification_status),
    notification_note = coalesce(p ->> 'notification_note', notification_note),
    attempts = attempts + case when (p ->> 'attempted')::boolean then 1 else 0 end,
    last_error = case when p ? 'error' then nullif(p ->> 'error', '') else last_error end,
    fulfilled_at = case when v_status = 'FULFILLED' and v_old.status <> 'FULFILLED' then now() else fulfilled_at end,
    delivered_status = coalesce(p ->> 'delivered_status', delivered_status),
    delivered_event_id = coalesce(nullif(p ->> 'delivered_event_id', ''), delivered_event_id),
    delivered_at = case when p ->> 'delivered_status' = 'MARKED' and v_old.delivered_status is distinct from 'MARKED' then now() else delivered_at end,
    delivered_error = case when p ? 'delivered_error' then nullif(p ->> 'delivered_error', '') else delivered_error end,
    synced_at = now()
  where id = v_old.id returning * into v_row;

  if v_row.status is distinct from v_old.status then
    perform public._order_log(p_order_id, 'CHANNEL_FULFILLMENT',
      case v_row.status
        when 'FULFILLED' then format('Fulfilled on %s%s%s', v_store, coalesce(' · ' || v_row.courier, ''), coalesce(' ' || v_row.tracking_number, ''))
          || case v_row.notification_status when 'REQUESTED' then format(' — %s asked to e-mail the customer', v_store)
               when 'NO_EMAIL' then ' — no customer e-mail on the order, so no shipping e-mail' else '' end
        when 'NEEDS_TRACKING' then format('%s not fulfilled yet: add the courier tracking number', v_store)
        when 'FAILED' then format('%s fulfilment failed: %s', v_store, coalesce(v_row.last_error, 'unknown error'))
        when 'SKIPPED' then format('%s fulfilment skipped: %s', v_store, coalesce(v_row.last_error, ''))
        else format('%s fulfilment %s', v_store, lower(v_row.status)) end,
      null, null, jsonb_build_object('fulfillment_id', v_row.fulfillment_id, 'status', v_row.status));
  end if;
  if v_row.delivered_status is distinct from v_old.delivered_status and v_row.delivered_status in ('MARKED', 'FAILED', 'SKIPPED') then
    perform public._order_log(p_order_id, 'CHANNEL_FULFILLMENT',
      case v_row.delivered_status
        when 'MARKED' then format('Marked delivered on %s', v_store)
        when 'FAILED' then format('Could not mark delivered on %s: %s', v_store, coalesce(v_row.delivered_error, 'unknown error'))
        else format('Not marked delivered on %s: %s', v_store, coalesce(v_row.delivered_error, '')) end,
      null, null, jsonb_build_object('event_id', v_row.delivered_event_id, 'delivered_status', v_row.delivered_status));
  end if;
  return v_row;
end;

channel_fulfillments_seen.src:
declare
  v_order public.orders;
  v_f jsonb;
  v_app public.channel_fulfillments;
  v_new int := 0;
begin
  perform public._require_system();
  select * into v_order from public.orders where sales_channel_id = p_channel_id and external_order_id = p_external_order_id;
  if not found then
    return jsonb_build_object('status', 'UNKNOWN_ORDER');
  end if;
  select * into v_app from public.channel_fulfillments where order_id = v_order.id and source = 'APP' for update;
  for v_f in select * from jsonb_array_elements(coalesce(p_fulfillments, '[]'::jsonb)) loop
    continue when nullif(v_f ->> 'id', '') is null or v_f ->> 'status' in ('CANCELLED', 'ERROR', 'FAILURE');
    if exists (select 1 from public.channel_fulfillments where fulfillment_id = v_f ->> 'id') then
      update public.channel_fulfillments set shopify_status = coalesce(v_f ->> 'display_status', v_f ->> 'status'), synced_at = now()
      where fulfillment_id = v_f ->> 'id';
      continue;
    end if;
    -- Our own request that succeeded but whose answer we never got.
    if v_app.id is not null and v_app.status <> 'FULFILLED' and v_app.tracking_number is not null
       and v_app.tracking_number = v_f ->> 'tracking_number' then
      update public.channel_fulfillments set status = 'FULFILLED', fulfillment_id = v_f ->> 'id', fulfilled_at = now(), synced_at = now(),
        shopify_status = coalesce(v_f ->> 'display_status', v_f ->> 'status'), last_error = null
      where id = v_app.id;
      perform public._order_log(v_order.id, 'CHANNEL_FULFILLMENT', 'Fulfilled on Shopify (confirmed by Shopify)', null, null,
        jsonb_build_object('fulfillment_id', v_f ->> 'id'));
      continue;
    end if;
    insert into public.channel_fulfillments(channel_id, order_id, external_order_id, source, status, fulfillment_id,
      courier, tracking_number, tracking_url, shopify_status, fulfilled_at, synced_at, shipped_at)
    values (p_channel_id, v_order.id, p_external_order_id, 'SHOPIFY', 'FULFILLED', v_f ->> 'id',
      nullif(v_f ->> 'tracking_company', ''), nullif(v_f ->> 'tracking_number', ''), nullif(v_f ->> 'tracking_url', ''),
      coalesce(v_f ->> 'display_status', v_f ->> 'status'), coalesce((v_f ->> 'created_at')::timestamptz, now()), now(),
      (v_f ->> 'created_at')::timestamptz)
    on conflict do nothing;
    v_new := v_new + 1;
    perform public._order_log(v_order.id, 'CHANNEL_FULFILLMENT',
      format('Fulfilled by hand in Shopify%s%s', coalesce(' · ' || nullif(v_f ->> 'tracking_company', ''), ''), coalesce(' ' || nullif(v_f ->> 'tracking_number', ''), '')),
      null, null, jsonb_build_object('fulfillment_id', v_f ->> 'id'));
    -- Fulfilled in Shopify before we shipped it: our own request is no longer needed.
    if v_app.id is not null and v_app.status in ('PENDING', 'NEEDS_TRACKING', 'FAILED') and (v_f ->> 'all_fulfilled')::boolean then
      update public.channel_fulfillments set status = 'SKIPPED', last_error = 'Already fulfilled in Shopify' where id = v_app.id;
    end if;
  end loop;
  return jsonb_build_object('status', 'OK', 'recorded', v_new);
end;

channel_get.src:
declare
  v_row public.sales_channels;
begin
  perform public._require_system();
  select * into v_row from public.sales_channels where id = p_id;
  return v_row;
end;

channel_import_for_retry.src:
declare
  v_row public.channel_order_imports;
  v_clean jsonb := '{}'::jsonb;
begin
  perform public._require_system();
  select * into v_row from public.channel_order_imports where id = p_import_id for update;
  if not found then
    raise exception 'NOT_FOUND: import not found' using errcode = 'P0002';
  end if;
  if v_row.status = 'IMPORTED' then
    raise exception 'VALIDATION: this order is already imported' using errcode = '22023';
  end if;
  select coalesce(jsonb_object_agg(k, to_jsonb(left(trim(v), 300))), '{}'::jsonb) into v_clean
  from jsonb_each_text(coalesce(p_overrides, '{}'::jsonb)) as e(k, v)
  where k in ('phone', 'name', 'address', 'district') and nullif(trim(v), '') is not null;
  update public.channel_order_imports set overrides = overrides || v_clean where id = p_import_id returning * into v_row;
  insert into public.audit_logs(actor_id, actor_email, action, entity_type, entity_id, new_values)
  values (p_actor, (select email from public.profiles where id = p_actor), 'channel.import_retry', 'channel_order_import',
          p_import_id::text, v_clean);
  return jsonb_build_object('channel_id', v_row.channel_id, 'payload', v_row.payload);
end;

channel_imports_list.src:
declare
  v_channel uuid := nullif(p ->> 'channel_id', '')::uuid;
  v_status text := nullif(upper(p ->> 'status'), '');
  v_limit int := least(greatest(coalesce((p ->> 'limit')::int, 20), 1), 100);
  v_offset int := greatest(coalesce((p ->> 'offset')::int, 0), 0);
begin
  perform public.require_permission('orders.view');
  return (
    with rows as (
      select i.* from public.channel_order_imports i
      where (v_channel is null or i.channel_id = v_channel) and (v_status is null or i.status = v_status)
    )
    select jsonb_build_object(
      'total', (select count(*) from rows),
      'items', coalesce((select jsonb_agg(jsonb_build_object(
          'id', r.id, 'channel_id', r.channel_id, 'channel', c.name, 'platform', c.platform,
          'external_id', r.external_id, 'external_number', r.external_number, 'status', r.status, 'error', r.error,
          'warnings', to_jsonb(r.warnings), 'attempts', r.attempts, 'received_via', r.received_via,
          'order_id', r.order_id, 'order_number', o.order_number,
          'customer', jsonb_build_object('name', coalesce(r.overrides ->> 'name', r.payload #>> '{customer,name}'),
                                         'phone', coalesce(r.overrides ->> 'phone', r.payload #>> '{customer,phone}')),
          'shipping', jsonb_build_object('address', coalesce(r.overrides ->> 'address', r.payload #>> '{shipping,address}'),
                                         'city', r.payload #>> '{shipping,city}', 'state', r.payload #>> '{shipping,state}',
                                         'district', r.overrides ->> 'district'),
          'total', r.payload ->> 'total', 'currency', r.payload ->> 'currency',
          'items', (select count(*) from jsonb_array_elements(case when jsonb_typeof(r.payload -> 'lines') = 'array' then r.payload -> 'lines' else '[]'::jsonb end)),
          'created_at', r.created_at, 'updated_at', r.updated_at) order by r.created_at desc)
        from (select * from rows order by created_at desc limit v_limit offset v_offset) r
        join public.sales_channels c on c.id = r.channel_id
        left join public.orders o on o.id = r.order_id), '[]'::jsonb)
    ));
end;

channel_in_use.src:
begin
  perform public._require_system();
  return coalesce((select public._channel_in_use(c.merchant_id, c.platform) from public.sales_channels c where c.id = p_channel_id), false);
end;

channel_ingest_order.src:
declare
  v_channel public.sales_channels;
  v_ext text := nullif(trim(coalesce(p_order ->> 'external_id', '')), '');
  v_import public.channel_order_imports;
  v_fix jsonb;
  v_o jsonb;
  v_items jsonb := '[]'::jsonb;
  v_line jsonb;
  v_district text;
  v_subtotal numeric := 0;
  v_shipping numeric;
  v_total numeric;
  v_paid numeric;
  v_discount numeric;
  v_warnings text[] := '{}';
  v_order public.orders;
  v_platform_name text;
  v_error text;
  v_shown uuid;
  v_num text;
  v_tax numeric := 0;
begin
  -- Switched off: the store's orders are not imported (the store keeps them).
  if not public.feature_enabled(lower((select platform from public.sales_channels where id = p_channel_id))) then
    return jsonb_build_object('status', 'SKIPPED', 'reason', 'FEATURE_OFF');
  end if;
  perform public._require_system();
  select * into v_channel from public.sales_channels where id = p_channel_id;
  if not found then
    raise exception 'NOT_FOUND: sales channel not found' using errcode = 'P0002';
  end if;
  -- Paused: the merchant sells on another store (Sales channels → Where do customers buy?).
  if not public._channel_in_use(v_channel.merchant_id, v_channel.platform) then
    return jsonb_build_object('status', 'SKIPPED', 'reason', 'PAUSED');
  end if;
  if v_ext is null then
    raise exception 'VALIDATION: the order has no id' using errcode = '22023';
  end if;
  v_platform_name := case v_channel.platform when 'SHOPIFY' then 'Shopify' else 'WooCommerce' end;
  perform pg_advisory_xact_lock(hashtextextended('channel-order:' || p_channel_id || ':' || v_ext, 0));

  select * into v_import from public.channel_order_imports where channel_id = p_channel_id and external_id = v_ext for update;
  if found and v_import.status = 'IMPORTED' then
    return jsonb_build_object('status', 'DUPLICATE', 'import_id', v_import.id, 'order_id', v_import.order_id,
      'order_number', (select order_number from public.orders where id = v_import.order_id));
  end if;
  if not found then
    insert into public.channel_order_imports(channel_id, external_id, external_number, status, payload, received_via)
    values (p_channel_id, v_ext, p_order ->> 'number', 'FAILED', p_order, upper(coalesce(p_via, 'WEBHOOK')))
    returning * into v_import;
  else
    update public.channel_order_imports set payload = p_order, external_number = coalesce(p_order ->> 'number', external_number),
      attempts = attempts + 1, received_via = upper(coalesce(p_via, received_via))
    where id = v_import.id returning * into v_import;
  end if;

  if coalesce((p_order ->> 'cancelled')::boolean, false) then
    update public.channel_order_imports set status = 'SKIPPED', error = 'Cancelled in ' || v_platform_name || ' before it was imported'
    where id = v_import.id;
    return jsonb_build_object('status', 'SKIPPED', 'import_id', v_import.id, 'error', 'cancelled');
  end if;
  -- Only orders still to be shipped: one the store already fulfilled has left (importing it by hand still works).
  if coalesce(public._channel_order_fulfillment_state(p_order), '') in ('FULFILLED', 'PARTIALLY_FULFILLED', 'RESTOCKED')
     and upper(coalesce(p_via, '')) <> 'RETRY' then
    update public.channel_order_imports set status = 'SKIPPED',
      error = case public._channel_order_fulfillment_state(p_order)
        when 'PARTIALLY_FULFILLED' then 'Partly fulfilled in ' || v_platform_name || ' before it was imported'
        when 'RESTOCKED' then 'Restocked in ' || v_platform_name || ' before it was imported'
        else 'Already fulfilled in ' || v_platform_name || ' before it was imported' end
    where id = v_import.id;
    return jsonb_build_object('status', 'SKIPPED', 'import_id', v_import.id, 'error', 'fulfilled');
  end if;
  if not coalesce((v_channel.settings ->> 'import_orders')::boolean, true) and upper(coalesce(p_via, '')) <> 'RETRY' then
    update public.channel_order_imports set status = 'SKIPPED', error = 'Order import is switched off for this store' where id = v_import.id;
    return jsonb_build_object('status', 'SKIPPED', 'import_id', v_import.id, 'error', 'import off');
  end if;

  v_fix := coalesce(v_import.overrides, '{}'::jsonb);
  v_o := p_order;
  -- Shopify "#10768" → "10768"; used only when it is a plain code and not taken here yet.
  v_num := upper(regexp_replace(trim(coalesce(v_o ->> 'number', '')), '^#+\s*', ''));
  if not public._channel_opt(v_channel, 'store_order_numbers', true) or v_num !~ '^[A-Z0-9][A-Z0-9-]{0,29}$'
     or exists (select 1 from public.orders where order_number = v_num) then
    v_num := null;
  end if;
  begin
    if jsonb_typeof(v_o -> 'lines') <> 'array' or jsonb_array_length(v_o -> 'lines') = 0 then
      raise exception 'VALIDATION: the order has no products' using errcode = '22023';
    end if;
    for v_line in select * from jsonb_array_elements(v_o -> 'lines') loop
      continue when coalesce((v_line ->> 'quantity')::int, 0) <= 0;
      v_items := v_items || jsonb_build_object(
        'variant_id', public._channel_variant(v_channel, v_line),
        'quantity', (v_line ->> 'quantity')::int,
        'unit_price', public.money(greatest(coalesce(nullif(v_line ->> 'unit_price', '')::numeric, 0), 0)));
      v_subtotal := v_subtotal + public.money(greatest(coalesce(nullif(v_line ->> 'unit_price', '')::numeric, 0), 0)) * (v_line ->> 'quantity')::int;
    end loop;
    if jsonb_array_length(v_items) = 0 then
      raise exception 'VALIDATION: the order has no products to ship' using errcode = '22023';
    end if;

    v_district := coalesce(nullif(v_fix ->> 'district', ''),
      public._bd_district(array[v_o #>> '{shipping,district_hint}', v_o #>> '{shipping,city}', v_o #>> '{shipping,state}',
                                v_o #>> '{shipping,area}', v_o #>> '{shipping,address}']));
    -- Never held back for the address: it comes in as the store sent it and staff check it.
    if v_district is null then
      v_district := '';
      v_warnings := v_warnings || format('District not recognised from "%s": choose it on the order before booking Pathao or RedX',
        coalesce(nullif(concat_ws(', ', nullif(v_o #>> '{shipping,city}', ''), nullif(v_o #>> '{shipping,state}', '')), ''), 'the address'));
    end if;
    if length(trim(coalesce(nullif(trim(v_fix ->> 'address'), ''), v_o #>> '{shipping,address}', ''))) < 5 then
      v_warnings := v_warnings || format('The delivery address is very short ("%s"): check it with the customer',
        trim(coalesce(nullif(trim(v_fix ->> 'address'), ''), v_o #>> '{shipping,address}', '')));
    end if;

    v_shipping := greatest(coalesce(nullif(v_o ->> 'shipping_price', '')::numeric, 0), 0);
    v_tax := public._channel_order_tax(v_o, v_subtotal, v_shipping);
    v_total := coalesce(nullif(v_o ->> 'total', '')::numeric, v_subtotal + v_shipping + v_tax);
    v_discount := greatest(v_subtotal + v_shipping + v_tax - v_total, 0);
    if v_discount > v_subtotal then
      v_shipping := greatest(v_shipping - (v_discount - v_subtotal), 0);
      v_discount := v_subtotal;
    end if;
    if v_total > v_subtotal + v_shipping + v_tax + 0.009 then
      v_warnings := v_warnings || format('%s total %s is higher than products + delivery (%s): taxes or fees were not imported',
                                         v_platform_name, v_total, v_subtotal + v_shipping);
    end if;
    v_paid := least(greatest(coalesce(nullif(v_o ->> 'paid_amount', '')::numeric, 0), 0), v_total);

    if nullif(trim(coalesce(v_fix ->> 'phone', v_o #>> '{customer,phone}', '')), '') is null then
      raise exception 'VALIDATION: the order has no phone number (the customer left it empty). Add it and import again' using errcode = '22023';
    end if;
    perform set_config('app.order_number', coalesce(v_num, ''), true);
    perform set_config('app.store_order_import', 'on', true);
    perform public._channel_presync_restock(v_channel, v_o, v_items);
    v_order := public._create_order(jsonb_build_object(
      'customer', jsonb_build_object(
        'full_name', coalesce(nullif(trim(v_fix ->> 'name'), ''), nullif(trim(v_o #>> '{customer,name}'), ''), 'Customer'),
        'phone', coalesce(nullif(v_fix ->> 'phone', ''), v_o #>> '{customer,phone}'),
        'email', nullif(v_o #>> '{customer,email}', '')),
      'shipping', jsonb_build_object(
        'address', coalesce(nullif(trim(v_fix ->> 'address'), ''), nullif(trim(v_o #>> '{shipping,address}'), ''), ''),
        'district', v_district,
        'area', nullif(v_o #>> '{shipping,area}', ''),
        'city', nullif(v_o #>> '{shipping,city}', ''),
        'postal_code', nullif(v_o #>> '{shipping,postal_code}', '')),
      'items', v_items,
      'delivery_charge', v_shipping,
      'manual_discount', v_discount,
      'payment_method', case when v_paid >= v_total and v_total > 0 then 'FULL_PAYMENT' when v_paid > 0 then 'ADVANCE' else 'COD' end,
      'customer_note', nullif(trim(coalesce(v_o ->> 'note', '')), ''),
      'idempotency_key', 'channel:' || p_channel_id || ':' || v_ext,
      'utm', jsonb_build_object('source', v_o #>> '{attribution,last_touch,params,utm_source}',
                                'medium', v_o #>> '{attribution,last_touch,params,utm_medium}',
                                'campaign', v_o #>> '{attribution,last_touch,params,utm_campaign}'),
      'internal_note', format('Imported from %s %s (%s)', v_platform_name, coalesce(v_o ->> 'number', v_ext), v_channel.name)
        || case when v_num is null and nullif(v_o ->> 'number', '') is not null
             then format(E'\n%s number %s is already used here, so this order got its own number', v_platform_name, v_o ->> 'number') else '' end
        || coalesce(E'\n' || array_to_string(v_warnings, E'\n'), '')
    ), 'API');
    perform set_config('app.order_number', '', true);
    if v_tax > 0 then
      update public.orders set tax_amount = v_tax where id = v_order.id;
      v_order := public.recalculate_order_totals(v_order.id);
    end if;

    perform set_config('app.store_order_import', '', true);
    v_warnings := v_warnings || public._order_stock_shortfalls(v_order.id);
    update public.orders set sales_channel_id = p_channel_id, external_order_id = v_ext, external_order_number = v_o ->> 'number'
    where id = v_order.id;

    if v_paid > 0 then
      perform public.record_order_payment(v_order.id, case when v_paid >= v_order.total_amount then 'FULL' else 'ADVANCE' end::public.order_payment_kind,
        'GATEWAY', least(v_paid, v_order.total_amount), coalesce(v_o ->> 'number', v_ext),
        format('Paid in %s%s', v_platform_name, coalesce(' via ' || nullif(v_o ->> 'gateway', ''), '')),
        'channel-pay:' || p_channel_id || ':' || v_ext);
    end if;
  exception when others then
    perform set_config('app.order_number', '', true);
    perform set_config('app.store_order_import', '', true);
    v_error := regexp_replace(sqlerrm, '^[A-Z_]+: ', '');
    if v_error = 'enter a valid mobile number' then
      v_error := format('the phone number "%s" is not a valid Bangladesh mobile number. Fix it and import again',
        coalesce(nullif(v_fix ->> 'phone', ''), v_o #>> '{customer,phone}'));
    end if;
    update public.channel_order_imports set status = 'FAILED', error = left(v_error, 500), order_id = null
    where id = v_import.id;
    update public.sales_channels set last_order_at = now() where id = p_channel_id;
    return jsonb_build_object('status', 'FAILED', 'import_id', v_import.id, 'error', v_error);
  end;

  if jsonb_typeof(v_o -> 'attribution') = 'object' then
    begin
      perform public.record_order_attribution(v_order.id, v_o -> 'attribution');
    exception when others then
      v_warnings := v_warnings || ('Source not recorded: ' || sqlerrm);
    end;
  end if;

  update public.channel_order_imports set status = 'IMPORTED', order_id = v_order.id, error = null, warnings = v_warnings
  where id = v_import.id;
  update public.sales_channels set orders_imported = orders_imported + 1, last_order_at = now() where id = p_channel_id;

  v_shown := public._after_order_created(v_order.id);

  return jsonb_build_object('status', 'IMPORTED', 'import_id', v_import.id, 'order_id', v_order.id, 'order_number', v_order.order_number,
    'phone', v_order.customer_phone, 'total', v_order.total_amount, 'warnings', to_jsonb(v_warnings),
    'merged_into', case when v_shown is distinct from v_order.id then (select order_number from public.orders where id = v_shown) end);
end;

channel_inventory_adopt_change.src:
declare
  v_m public.sales_channel_variants;
  v_c public.sales_channels;
  v_inv public.inventory;
  v_delta int;
begin
  perform public._require_system();
  select * into v_m from public.sales_channel_variants where channel_id = p_channel_id and variant_id = p_variant_id for update;
  if not found or v_m.last_pushed_qty is null or p_store_qty is null then
    return jsonb_build_object('status', 'SKIPPED');
  end if;
  select * into v_c from public.sales_channels where id = p_channel_id;
  v_delta := p_store_qty - v_m.last_pushed_qty;
  if v_delta <> 0 then
    select * into v_inv from public.inventory where variant_id = p_variant_id for update;
    v_delta := greatest(v_delta, -coalesce(v_inv.on_hand, 0));
    if v_delta <> 0 then
      perform public._apply_inventory_movement(p_variant_id, 'ADJUSTMENT', v_delta, 0, 0, 'CHANNEL', p_channel_id,
        format('Changed in %s', v_c.name),
        format('Changed in %s: %s → %s (applied here as %s%s)', case v_c.platform when 'SHOPIFY' then 'Shopify' else 'WooCommerce' end,
          v_m.last_pushed_qty, p_store_qty, case when v_delta > 0 then '+' else '' end, v_delta), null, false);
    end if;
  end if;
  update public.sales_channel_variants set last_pushed_qty = p_store_qty, shopify_available = p_store_qty, sync_status = 'OK',
    last_error = null, mismatch_since = null, synced_at = now()
  where channel_id = p_channel_id and variant_id = p_variant_id;
  return jsonb_build_object('status', 'ADOPTED', 'change', v_delta);
end;

channel_inventory_reconcile.src:
declare
  v_item jsonb;
  v_m record;
  v_plan jsonb := '[]'::jsonb;
  v_delta int;
begin
  perform public.require_permission('inventory.adjust');
  for v_item in select * from jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) loop
    select m.*, greatest(coalesce(i.available, 0), 0) as ours, coalesce(i.on_hand, 0) as on_hand, v.sku as our_sku
    into v_m from public.sales_channel_variants m
    join public.product_variants v on v.id = m.variant_id
    left join public.inventory i on i.variant_id = m.variant_id
    where m.channel_id = p_channel_id and m.variant_id = (v_item ->> 'variant_id')::uuid for update of m;
    continue when not found or v_m.inventory_item_id is null;
    if v_item ->> 'action' = 'PUSH' then
      v_plan := v_plan || jsonb_build_object('variant_id', v_m.variant_id, 'sku', v_m.our_sku, 'action', 'PUSH',
        'from', v_m.shopify_available, 'to', v_m.ours);
      if p_apply then
        update public.sales_channel_variants set last_pushed_qty = shopify_available, sync_status = 'PENDING', mismatch_since = null
        where channel_id = p_channel_id and variant_id = v_m.variant_id;
        perform public.channel_job_enqueue(p_channel_id, 'INVENTORY', v_m.variant_id, '{"force":true}'::jsonb);
      end if;
    elsif v_item ->> 'action' = 'ADOPT' and v_m.shopify_available is not null then
      v_delta := v_m.shopify_available - v_m.ours;
      v_plan := v_plan || jsonb_build_object('variant_id', v_m.variant_id, 'sku', v_m.our_sku, 'action', 'ADOPT',
        'from', v_m.ours, 'to', v_m.shopify_available, 'on_hand_change', v_delta);
      if p_apply and v_delta <> 0 then
        perform public._apply_inventory_movement(v_m.variant_id, 'ADJUSTMENT', v_delta, 0, 0, 'CHANNEL', p_channel_id,
          'Shopify reconciliation', format('Shopify reconciliation: matched Shopify''s %s', v_m.shopify_available), null, false);
      end if;
      if p_apply then
        update public.sales_channel_variants set last_pushed_qty = shopify_available, sync_status = 'OK', mismatch_since = null, last_error = null
        where channel_id = p_channel_id and variant_id = v_m.variant_id;
      end if;
    end if;
  end loop;
  if p_apply then
    perform public.log_audit('channel.inventory_reconcile', 'sales_channel', p_channel_id::text, null, jsonb_build_object('plan', v_plan));
  end if;
  return jsonb_build_object('applied', p_apply, 'plan', v_plan);
end;

channel_inventory_seen.src:
declare
  v_c public.sales_channels;
  v_m public.sales_channel_variants;
  v_queued int := 0;
begin
  perform public._require_system();
  select * into v_c from public.sales_channels where id = p_channel_id;
  if coalesce(v_c.settings ->> 'location_id', '') <> p_location_id then
    return jsonb_build_object('status', 'OTHER_LOCATION');
  end if;
  for v_m in select * from public.sales_channel_variants where channel_id = p_channel_id and inventory_item_id = p_inventory_item_id for update loop
    update public.sales_channel_variants set shopify_available = p_available, synced_at = now() where channel_id = v_m.channel_id and external_variant_id = v_m.external_variant_id;
    if p_available is distinct from v_m.last_pushed_qty and public._channel_opt(v_c, 'inventory_sync', false) then
      perform public.channel_job_enqueue(p_channel_id, 'INVENTORY', v_m.variant_id, '{"reason":"store_changed"}'::jsonb, 60);
      v_queued := v_queued + 1;
    end if;
  end loop;
  return jsonb_build_object('status', 'OK', 'queued', v_queued);
end;

channel_job_enqueue.src:
declare
  v_id uuid;
begin
  insert into public.channel_sync_jobs(channel_id, kind, ref_id, payload, next_attempt_at)
  values (p_channel_id, p_kind, p_ref_id, coalesce(p_payload, '{}'::jsonb), now() + make_interval(secs => greatest(p_delay_seconds, 0)))
  on conflict (channel_id, kind, ref_id) where status in ('PENDING', 'RUNNING') do update
    set payload = channel_sync_jobs.payload || excluded.payload
          || case when channel_sync_jobs.status = 'RUNNING' then '{"rerun": true}'::jsonb else '{}'::jsonb end,
        next_attempt_at = least(channel_sync_jobs.next_attempt_at, excluded.next_attempt_at)
  returning id into v_id;
  return v_id;
end;

channel_job_finish.src:
declare
  v_job public.channel_sync_jobs;
begin
  perform public._require_system();
  select * into v_job from public.channel_sync_jobs where id = p_id for update;
  if not found then
    raise exception 'NOT_FOUND: job not found' using errcode = 'P0002';
  end if;
  if p_outcome = 'RETRY' and v_job.attempts < v_job.max_attempts then
    update public.channel_sync_jobs set status = 'PENDING', locked_until = null, last_error = left(p_error, 1000), result = p_result,
      payload = payload - 'rerun',
      next_attempt_at = now() + make_interval(secs => coalesce(p_delay_seconds, least(30 * power(2, v_job.attempts - 1), 21600)::int))
    where id = p_id returning * into v_job;
  elsif v_job.payload ? 'rerun' then
    -- Something changed during this run: look again with fresh data.
    update public.channel_sync_jobs set status = 'PENDING', locked_until = null, attempts = 0, payload = payload - 'rerun',
      last_error = case when p_outcome = 'DONE' then null else left(coalesce(p_error, 'Failed'), 1000) end, result = p_result,
      next_attempt_at = now() + interval '10 seconds'
    where id = p_id returning * into v_job;
  elsif p_outcome = 'DONE' then
    update public.channel_sync_jobs set status = 'DONE', done_at = now(), last_error = null, result = p_result, locked_until = null
    where id = p_id returning * into v_job;
  else
    update public.channel_sync_jobs set status = 'FAILED', locked_until = null, last_error = left(coalesce(p_error, 'Failed'), 1000), result = p_result
    where id = p_id returning * into v_job;
  end if;
  return v_job;
end;

channel_job_retry.src:
begin
  perform public.require_permission('settings.manage');
  update public.channel_sync_jobs set status = 'PENDING', attempts = 0, next_attempt_at = now(), last_error = null
  where id = p_job_id and status = 'FAILED'
    and not exists (select 1 from public.channel_sync_jobs o where o.id <> p_job_id and o.channel_id = channel_sync_jobs.channel_id
                    and o.kind = channel_sync_jobs.kind and o.ref_id = channel_sync_jobs.ref_id and o.status in ('PENDING', 'RUNNING'));
  if not found then
    raise exception 'NOT_FOUND: no failed job to retry (it may already be running)' using errcode = 'P0002';
  end if;
end;

channel_jobs_claim.src:
begin
  perform public._require_system();
  return query
  update public.channel_sync_jobs j set status = 'RUNNING', attempts = j.attempts + 1, locked_until = now() + interval '3 minutes'
  where j.id in (
    select id from public.channel_sync_jobs
    where ((status = 'PENDING' and next_attempt_at <= now()) or (status = 'RUNNING' and locked_until < now()))
      and exists (select 1 from public.sales_channels c where c.id = channel_sync_jobs.channel_id and public._channel_in_use(c.merchant_id, c.platform))
    order by next_attempt_at
    limit least(greatest(p_limit, 1), 100)
    for update skip locked)
  returning j.*;
end;

channel_oauth_state_create.src:
begin
  perform public._require_system();
  if p_return_to !~ '^https?://[^/]+/admin(/|$|\?)' then
    raise exception 'VALIDATION: invalid return address' using errcode = '22023';
  end if;
  insert into public.channel_oauth_states(state, channel_id, created_by, return_to, expires_at)
  values (p_state, p_channel_id, p_actor, p_return_to, now() + interval '20 minutes');
end;

channel_oauth_state_take.src:
declare
  v_row public.channel_oauth_states;
begin
  perform public._require_system();
  update public.channel_oauth_states set used_at = now()
  where state = p_state and used_at is null and expires_at > now()
  returning * into v_row;
  if not found then
    return null;
  end if;
  return jsonb_build_object('channel_id', v_row.channel_id, 'created_by', v_row.created_by, 'return_to', v_row.return_to);
end;

channel_order_action_context.src:
declare
  v_order public.orders;
begin
  perform public._require_system();
  select * into v_order from public.orders where id = p_order_id;
  if not found then
    raise exception 'NOT_FOUND: order not found' using errcode = 'P0002';
  end if;
  return jsonb_build_object('order_id', v_order.id, 'order_number', v_order.order_number, 'status', v_order.status,
    'channel_id', v_order.sales_channel_id, 'external_order_id', v_order.external_order_id,
    'platform', (select platform from public.sales_channels where id = v_order.sales_channel_id));
end;

channel_order_action_record.src:
begin
  perform public._require_system();
  if p_action not in ('MARK_PAID', 'CANCEL') then
    raise exception 'VALIDATION: unknown action' using errcode = '22023';
  end if;
  perform public._order_log(p_order_id, 'CHANNEL_ACTION',
    case p_action when 'MARK_PAID' then format('Marked paid on Shopify (Shopify now shows %s)', coalesce(p_detail ->> 'financial_status', 'paid'))
                  else 'Cancel sent to Shopify (no refund or restock on Shopify; stock follows this app)' end,
    null, null, p_detail);
  insert into public.audit_logs(actor_id, action, entity_type, entity_id, new_values)
  values (p_actor, 'channel.order_' || lower(p_action), 'order', p_order_id::text, p_detail);
end;

channel_order_attribution_fill.src:
declare
  v_order_id uuid;
  v_row public.order_attributions;
  v_last jsonb := case when jsonb_typeof(p_attribution -> 'last_touch') = 'object' then p_attribution -> 'last_touch' end;
  v_first jsonb := case when jsonb_typeof(p_attribution -> 'first_touch') = 'object' then p_attribution -> 'first_touch' end;
  v_c jsonb;
  v_fc jsonb;
  v_params jsonb;
begin
  perform public._require_system();
  if v_last is null and v_first is null then
    return jsonb_build_object('status', 'NOTHING');
  end if;
  select id into v_order_id from public.orders where sales_channel_id = p_channel_id and external_order_id = p_external_id;
  if v_order_id is null then
    return jsonb_build_object('status', 'NO_ORDER');
  end if;
  select * into v_row from public.order_attributions where order_id = v_order_id;
  if not found then
    perform public._record_order_attribution(v_order_id, p_attribution);
    return jsonb_build_object('status', 'RECORDED');
  end if;
  if v_row.last_touch is not null or v_row.recorded_by = 'STAFF' then
    return jsonb_build_object('status', 'ALREADY');
  end if;
  v_last := coalesce(v_last, v_first);
  v_c := public.classify_touch(v_last);
  v_fc := case when v_first is not null then public.classify_touch(v_first) end;
  v_params := coalesce(v_last -> 'params', '{}'::jsonb);
  update public.order_attributions set channel = v_c ->> 'channel', source = v_c ->> 'source', medium = v_c ->> 'medium',
    is_paid = (v_c ->> 'is_paid')::boolean, platform = (v_c ->> 'platform')::public.marketing_platform,
    campaign = left(v_c ->> 'campaign', 200), adset = left(v_c ->> 'adset', 200), ad = left(v_c ->> 'ad', 200),
    campaign_id = left(v_c ->> 'campaign_id', 64), adset_id = left(v_c ->> 'adset_id', 64), ad_id = left(v_c ->> 'ad_id', 64),
    click_id_type = v_c ->> 'click_id_type', click_id = v_c ->> 'click_id',
    utm_source = left(v_params ->> 'utm_source', 120), utm_medium = left(v_params ->> 'utm_medium', 120),
    utm_campaign = left(v_params ->> 'utm_campaign', 200), utm_content = left(v_params ->> 'utm_content', 200), utm_term = left(v_params ->> 'utm_term', 200),
    landing_page = left(coalesce(v_last ->> 'landing', v_first ->> 'landing'), 300), referrer_host = v_c ->> 'referrer_host',
    first_channel = coalesce(v_fc ->> 'channel', v_c ->> 'channel'), first_source = coalesce(v_fc ->> 'source', v_c ->> 'source'),
    first_touch = v_first, last_touch = v_last, first_touch_at = (v_first ->> 'at')::timestamptz, last_touch_at = (v_last ->> 'at')::timestamptz,
    attributed_at = now()
  where order_id = v_order_id;
  update public.orders set utm_source = coalesce(utm_source, left(v_params ->> 'utm_source', 120)),
    utm_medium = coalesce(utm_medium, left(v_params ->> 'utm_medium', 120)), utm_campaign = coalesce(utm_campaign, left(v_params ->> 'utm_campaign', 200))
  where id = v_order_id;
  return jsonb_build_object('status', 'FILLED');
end;

channel_order_cancelled.src:
declare
  v_channel public.sales_channels;
  v_order public.orders;
  v_name text;
begin
  perform public._require_system();
  select * into v_channel from public.sales_channels where id = p_channel_id;
  v_name := case v_channel.platform when 'SHOPIFY' then 'Shopify' else 'WooCommerce' end;
  select * into v_order from public.orders where sales_channel_id = p_channel_id and external_order_id = p_external_id;
  if not found then
    update public.channel_order_imports set status = 'SKIPPED', error = 'Cancelled in ' || v_name
    where channel_id = p_channel_id and external_id = p_external_id and status = 'FAILED';
    return jsonb_build_object('status', 'NO_ORDER');
  end if;
  update public.channel_order_sync set cancel_status = 'CONFIRMED', cancel_confirmed_at = now(), cancel_error = null
  where order_id = v_order.id and cancel_status in ('PENDING', 'REQUESTED', 'FAILED');
  if found then
    perform public._order_log(v_order.id, 'CHANNEL_SYNC', format('Cancelled on %s (confirmed by %s)', v_name, v_name));
  end if;
  if v_order.status in ('CANCELLED', 'REJECTED_FRAUD') then
    return jsonb_build_object('status', 'ALREADY', 'order_id', v_order.id);
  end if;
  if v_order.merged_into is not null then
    insert into public.order_notes(order_id, kind, visibility, body, created_by_name)
    values (public._effective_order_id(v_order.id), 'SYSTEM', 'INTERNAL',
      format('%s order %s was cancelled in %s%s. It is merged into this order — remove its items before shipping if needed.',
        v_name, coalesce(v_order.external_order_number, p_external_id), v_name, coalesce(' (' || nullif(p_reason, '') || ')', '')), v_name);
    return jsonb_build_object('status', 'NOTED', 'order_id', v_order.id);
  end if;
  if v_order.status in ('PENDING', 'FRAUD_CHECK', 'FRAUD_REVIEW', 'ADVANCE_REQUIRED', 'CONFIRMATION_REQUIRED', 'CONFIRMED', 'PROCESSING') then
    begin
      perform set_config('app.channel_cancel', '1', true);
      perform public._transition_order(v_order.id, 'CANCELLED', 'Cancelled in ' || v_name || coalesce(': ' || nullif(p_reason, ''), ''));
      perform set_config('app.channel_cancel', '', true);
      return jsonb_build_object('status', 'CANCELLED', 'order_id', v_order.id);
    exception when others then
      perform set_config('app.channel_cancel', '', true);
    end;
  end if;
  insert into public.order_notes(order_id, kind, visibility, body, created_by_name)
  values (v_order.id, 'SYSTEM', 'INTERNAL', format('Cancelled in %s%s — check before shipping. This order is already %s here.',
          v_name, coalesce(' (' || nullif(p_reason, '') || ')', ''), lower(replace(v_order.status::text, '_', ' '))), v_name);
  return jsonb_build_object('status', 'NOTED', 'order_id', v_order.id);
end;

channel_order_sync_retry.src:
declare
  v_sync public.channel_order_sync;
begin
  perform public.require_permission('orders.update');
  update public.channel_order_sync set
    cancel_status = case when cancel_status = 'FAILED' then 'PENDING' else cancel_status end,
    paid_status = case when paid_status = 'FAILED' then 'PENDING' else paid_status end,
    tag_error = null, event_error = null, store_status_error = null
  where order_id = p_order_id returning * into v_sync;
  if not found then
    raise exception 'NOT_FOUND: nothing was sent to the store for this order' using errcode = 'P0002';
  end if;
  update public.channel_sync_jobs set status = 'PENDING', attempts = 0, next_attempt_at = now()
  where kind = 'FULFILL' and ref_id = p_order_id and status = 'FAILED'
    and not exists (select 1 from public.channel_sync_jobs o where o.kind = 'FULFILL' and o.ref_id = p_order_id and o.status in ('PENDING', 'RUNNING'));
  perform public.channel_job_enqueue(v_sync.channel_id, 'FULFILL', p_order_id);
end;

channel_order_sync_update.src:
declare
  v_old public.channel_order_sync;
  v_new public.channel_order_sync;
  v_store text;
  v_put int;
begin
  perform public._require_system();
  select * into v_old from public.channel_order_sync where order_id = p_order_id for update;
  if not found then
    raise exception 'NOT_FOUND: no store sync for this order' using errcode = 'P0002';
  end if;
  update public.channel_order_sync set
    cancel_status = coalesce(p ->> 'cancel_status', cancel_status),
    cancel_error = case when p ? 'cancel_error' then nullif(p ->> 'cancel_error', '') else cancel_error end,
    cancel_requested_at = case when p ->> 'cancel_status' = 'REQUESTED' then coalesce(cancel_requested_at, now()) else cancel_requested_at end,
    cancel_confirmed_at = case when p ->> 'cancel_status' = 'CONFIRMED' then coalesce(cancel_confirmed_at, now()) else cancel_confirmed_at end,
    restocked_in_store = coalesce((p ->> 'restocked_in_store')::boolean, restocked_in_store),
    paid_status = coalesce(p ->> 'paid_status', paid_status),
    paid_error = case when p ? 'paid_error' then nullif(p ->> 'paid_error', '') else paid_error end,
    paid_at = case when p ->> 'paid_status' = 'MARKED' then coalesce(paid_at, now()) else paid_at end,
    status_tag = coalesce(p ->> 'status_tag', status_tag),
    tag_error = case when p ? 'tag_error' then nullif(p ->> 'tag_error', '') else tag_error end,
    events = events || coalesce(p -> 'events', '{}'::jsonb),
    event_error = case when p ? 'event_error' then nullif(p ->> 'event_error', '') else event_error end,
    store_status = coalesce(nullif(p ->> 'store_status', ''), store_status),
    store_status_at = case when nullif(p ->> 'store_status', '') is not null then now() else store_status_at end,
    store_status_error = case when p ? 'store_status_error' then nullif(p ->> 'store_status_error', '') else store_status_error end,
    store_restock = case when p ? 'store_restock' then p -> 'store_restock' else store_restock end,
    updated_at = now()
  where order_id = p_order_id returning * into v_new;

  select case c.platform when 'SHOPIFY' then 'Shopify' else 'WooCommerce' end into v_store
  from public.sales_channels c where c.id = v_new.channel_id;
  if v_new.cancel_status is distinct from v_old.cancel_status and v_new.cancel_status in ('REQUESTED', 'CONFIRMED', 'FAILED') then
    perform public._order_log(p_order_id, 'CHANNEL_SYNC', case v_new.cancel_status
      when 'REQUESTED' then 'Cancel sent to Shopify' || case when v_new.restocked_in_store then ' (Shopify restocks)' else ' (stock handled here, not restocked twice)' end
        || case when coalesce((p ->> 'customer_emailed')::boolean, false) then '; Shopify e-mails the customer that it was cancelled' else '' end
      when 'CONFIRMED' then 'Cancelled on Shopify'
      else 'Shopify did not cancel the order: ' || coalesce(v_new.cancel_error, 'unknown error') end);
  end if;
  if v_new.paid_status is distinct from v_old.paid_status and v_new.paid_status in ('MARKED', 'FAILED') then
    perform public._order_log(p_order_id, 'CHANNEL_SYNC', case v_new.paid_status when 'MARKED' then 'Marked paid on Shopify'
      else 'Could not mark paid on Shopify: ' || coalesce(v_new.paid_error, 'unknown error') end);
  end if;
  if v_new.events is distinct from v_old.events then
    perform public._order_log(p_order_id, 'CHANNEL_SYNC', 'Shopify delivery update: ' ||
      (select string_agg(lower(replace(k, '_', ' ')), ', ') from jsonb_object_keys(v_new.events) k where not v_old.events ? k));
  end if;
  if v_new.store_status is distinct from v_old.store_status and v_new.store_status is not null then
    perform public._order_log(p_order_id, 'CHANNEL_SYNC', format('Set to %s on %s',
      initcap(replace(v_new.store_status, '-', ' ')), v_store));
  end if;
  if v_new.store_status_error is distinct from v_old.store_status_error and v_new.store_status_error is not null then
    perform public._order_log(p_order_id, 'CHANNEL_SYNC', format('%s status not updated: %s', v_store, v_new.store_status_error));
  end if;
  if v_new.store_restock is distinct from v_old.store_restock then
    select coalesce(sum((x ->> 'added')::int), 0) into v_put from jsonb_array_elements(coalesce(p -> 'restocked', '[]'::jsonb)) x;
    if v_put > 0 then
      perform public._order_log(p_order_id, 'CHANNEL_SYNC', format('%s item(s) put back in %s stock (%s)', v_put, v_store,
        (select string_agg(format('%s × %s', x ->> 'added', x ->> 'name'), ', ') from jsonb_array_elements(p -> 'restocked') x where (x ->> 'added')::int > 0)));
    end if;
  end if;
end;

channel_plugin_config_save.src:
declare
  v_clean jsonb := '{}'::jsonb;
  v_key text;
  v_settings jsonb;
begin
  perform public.require_permission('settings.manage');
  foreach v_key in array array['order_events', 'capture_leads', 'attribution', 'custom_statuses', 'shield', 'shield_fail_open'] loop
    if p ? v_key then
      if jsonb_typeof(p -> v_key) <> 'boolean' then
        raise exception 'VALIDATION: % must be on or off', v_key using errcode = '22023';
      end if;
      v_clean := v_clean || jsonb_build_object(v_key, p -> v_key);
    end if;
  end loop;
  if p ? 'shield_timeout' then
    v_clean := v_clean || jsonb_build_object('shield_timeout', greatest(2, least(10, (p ->> 'shield_timeout')::int)));
  end if;
  update public.sales_channels
  set settings = settings || jsonb_build_object('plugin_config', coalesce(settings -> 'plugin_config', '{}'::jsonb) || v_clean)
  where id = p_channel_id and platform = 'WOOCOMMERCE'
  returning settings into v_settings;
  if v_settings is null then
    raise exception 'NOT_FOUND: WooCommerce store not found' using errcode = 'P0002';
  end if;
  perform public.log_audit('channel.plugin_config', 'sales_channel', p_channel_id::text, null, v_clean);
  return public._plugin_config(v_settings);
end;

channel_plugin_log.src:
begin
  perform public._require_system();
  insert into public.channel_plugin_events(channel_id, event_id, type, status, detail)
  values (p_channel_id, left(p_event_id, 80), left(coalesce(nullif(p_type, ''), 'unknown'), 40), p_status,
    case when length(coalesce(p_detail, '{}'::jsonb)::text) > 4000 then jsonb_build_object('truncated', true) else coalesce(p_detail, '{}'::jsonb) end);
end;

channel_plugin_overview.src:
declare
  c public.sales_channels;
begin
  perform public.require_permission('settings.manage');
  select * into c from public.sales_channels where id = p_channel_id and platform = 'WOOCOMMERCE';
  if c.id is null then
    raise exception 'NOT_FOUND: WooCommerce store not found' using errcode = 'P0002';
  end if;
  return jsonb_build_object(
    'channel', jsonb_build_object('id', c.id, 'name', c.name, 'shop_domain', c.shop_domain, 'status', c.status, 'last_sync_at', c.last_sync_at,
      'last_error', c.last_error, 'webhooks', c.webhooks, 'last_test', c.last_test),
    'plugin', c.settings -> 'plugin',
    'pair', c.settings -> 'plugin_pair',
    'online', coalesce((c.settings #>> '{plugin,last_seen_at}')::timestamptz > now() - interval '40 minutes', false),
    'config', public._plugin_config(c.settings),
    'events', coalesce((select jsonb_agg(to_jsonb(e) - 'channel_id' order by e.id desc)
      from (select * from public.channel_plugin_events where channel_id = c.id order by id desc limit 100) e), '[]'::jsonb),
    'counts', (select jsonb_build_object(
        'events_24h', count(*) filter (where created_at > now() - interval '24 hours'),
        'failed_24h', count(*) filter (where created_at > now() - interval '24 hours' and status in ('FAILED', 'REJECTED')),
        'leads_7d', (select count(*) from public.shopify_abandoned_checkouts a where a.channel_id = c.id and a.created_at > now() - interval '7 days'),
        'leads_recovered_7d', (select count(*) from public.shopify_abandoned_checkouts a where a.channel_id = c.id and a.status = 'RECOVERED' and a.completed_at > now() - interval '7 days'),
        'orders_7d', (select count(*) from public.channel_order_imports i where i.channel_id = c.id and i.created_at > now() - interval '7 days' and i.status = 'IMPORTED'))
      from public.channel_plugin_events where channel_id = c.id));
end;

channel_plugin_paired.src:
begin
  perform public._require_system();
  update public.sales_channels
  set settings = settings
    || jsonb_build_object('plugin_pair', jsonb_build_object('ok', p_ok, 'at', now(), 'detail', left(p_detail, 300)))
    || case when p_ok and p_report is not null then jsonb_build_object('plugin', p_report || jsonb_build_object('last_seen_at', now())) else '{}'::jsonb end
  where id = p_channel_id;
end;

channel_plugin_seen.src:
declare
  v_settings jsonb;
begin
  perform public._require_system();
  update public.sales_channels
  set settings = settings || jsonb_build_object('plugin',
    (case when length(coalesce(p_report, '{}'::jsonb)::text) > 30000 then jsonb_build_object('truncated', true) else coalesce(p_report, '{}'::jsonb) end)
    || jsonb_build_object('last_seen_at', now()))
  where id = p_channel_id and platform = 'WOOCOMMERCE'
  returning settings into v_settings;
  if v_settings is null then
    raise exception 'NOT_FOUND: WooCommerce store not found' using errcode = 'P0002';
  end if;
  return public._plugin_config(v_settings);
