channel_status_push_due.src:
begin
  perform public._require_system();
  return coalesce((select jsonb_agg(jsonb_build_object('id', p.id, 'channel_id', p.channel_id, 'order_id', p.order_id,
      'external_order_id', p.external_order_id, 'target', p.target, 'attempts', p.attempts) order by p.next_at)
    from (select * from public.channel_status_pushes where status = 'PENDING' and next_at <= now()
            and exists (select 1 from public.sales_channels c where c.id = channel_status_pushes.channel_id and public._channel_in_use(c.merchant_id, c.platform))
          order by next_at limit greatest(1, least(coalesce(p_limit, 20), 100)) for update skip locked) p), '[]'::jsonb);
end;

channel_status_push_result.src:
declare
  r public.channel_status_pushes;
  v_store text;
begin
  perform public._require_system();
  update public.channel_status_pushes set
    attempts = attempts + 1,
    status = case when p_ok then 'DONE' when not p_retry or attempts + 1 >= 8 then 'FAILED' else 'PENDING' end,
    next_at = now() + make_interval(mins => least(360, (5 * power(2, attempts))::int)),
    last_error = case when p_ok then null else left(p_error, 300) end,
    done_at = case when p_ok then now() else done_at end
  where id = p_id returning * into r;
  if r.id is null then return; end if;
  select name into v_store from public.sales_channels where id = r.channel_id;
  if p_ok then
    perform public._order_log(r.order_id, 'CHANNEL_STATUS', format('Marked %s on %s', initcap(r.target), coalesce(v_store, 'WooCommerce')));
  elsif r.status = 'FAILED' then
    perform public._order_log(r.order_id, 'CHANNEL_STATUS', format('Could not mark %s on %s: %s', initcap(r.target), coalesce(v_store, 'WooCommerce'), coalesce(p_error, 'unknown error')));
  end if;
end;

channel_store_restock_seen.src:
declare
  v_c public.sales_channels;
  v_order public.orders;
  v_line jsonb;
  v_m public.sales_channel_variants;
  v_qty int;
  v_loc text;
  v_since timestamptz;
  v_n int := 0;
  v_items text[] := '{}';
begin
  perform public._require_system();
  select * into v_c from public.sales_channels where id = p_channel_id;
  if not found or not public._channel_opt(v_c, 'inventory_sync', false) then
    return jsonb_build_object('status', 'SKIPPED');
  end if;
  select * into v_order from public.orders where sales_channel_id = p_channel_id and external_order_id = p_external_order_id;
  if not found then
    -- Never part of our stock here, so Shopify's restock is a real change.
    return jsonb_build_object('status', 'NO_ORDER');
  end if;
  v_loc := regexp_replace(coalesce(v_c.settings ->> 'location_id', ''), '^.*/', '');
  v_since := coalesce((v_c.settings ->> 'restock_guard_since')::timestamptz, v_c.created_at);
  for v_line in select * from jsonb_array_elements(coalesce(p_lines, '[]'::jsonb)) loop
    v_qty := coalesce((v_line ->> 'quantity')::int, 0);
    continue when v_qty <= 0 or coalesce(v_line ->> 'line_id', '') = '';
    continue when nullif(v_line ->> 'location_id', '') is not null and v_line ->> 'location_id' <> v_loc;
    continue when (v_line ->> 'created_at') is not null and (v_line ->> 'created_at')::timestamptz < v_since;
    insert into public.channel_webhook_deliveries(channel_id, delivery_id, topic)
    values (p_channel_id, 'restock:' || (v_line ->> 'line_id'), 'store_restock')
    on conflict do nothing;
    continue when not found;
    for v_m in select * from public.sales_channel_variants
               where channel_id = p_channel_id and external_variant_id = v_line ->> 'external_variant_id' and last_pushed_qty is not null
               for update loop
      update public.sales_channel_variants set last_pushed_qty = last_pushed_qty + v_qty
      where channel_id = v_m.channel_id and external_variant_id = v_m.external_variant_id;
      perform public.channel_job_enqueue(p_channel_id, 'INVENTORY', v_m.variant_id, '{}'::jsonb, 5);
      v_n := v_n + v_qty;
      v_items := v_items || coalesce((select p.name from public.product_variants pv join public.products p on p.id = pv.product_id where pv.id = v_m.variant_id), 'item');
    end loop;
  end loop;
  if v_n > 0 then
    perform public._order_log(v_order.id, 'CHANNEL_SYNC',
      format('Shopify put %s item(s) back in its stock for this order (%s). Not counted again here: stock here follows this order (now %s), so Shopify''s count is set back to ours.',
        v_n, array_to_string(v_items, ', '), lower(replace(v_order.status::text, '_', ' '))));
  end if;
  return jsonb_build_object('status', 'OK', 'ignored', v_n);
end;

channel_sync_settings_save.src:
declare
  v_old public.sales_channels;
  v_new jsonb;
  v_loc text;
begin
  perform public.require_permission('settings.manage');
  select * into v_old from public.sales_channels where id = p_channel_id for update;
  if not found then
    raise exception 'NOT_FOUND: sales channel not found' using errcode = 'P0002';
  end if;
  v_loc := coalesce(nullif(p ->> 'location_id', ''), v_old.settings ->> 'location_id');
  if v_loc is not null and not exists (select 1 from jsonb_array_elements(v_old.locations) l where l ->> 'id' = v_loc) then
    raise exception 'VALIDATION: choose one of the store''s locations (import the catalog first)' using errcode = '22023';
  end if;
  if coalesce((p ->> 'inventory_sync')::boolean, false) and v_loc is null then
    raise exception 'VALIDATION: choose the store location to keep in step before turning stock sync on' using errcode = '22023';
  end if;
  if p ? 'external_changes' and p ->> 'external_changes' not in ('FLAG', 'SAAS_WINS', 'TWO_WAY') then
    raise exception 'VALIDATION: unknown policy' using errcode = '22023';
  end if;
  v_new := v_old.settings || jsonb_strip_nulls(jsonb_build_object(
    'inventory_sync', (p ->> 'inventory_sync')::boolean, 'location_id', v_loc, 'external_changes', p ->> 'external_changes',
    'fulfill_on_ship', (p ->> 'fulfill_on_ship')::boolean, 'notify_customer', (p ->> 'notify_customer')::boolean,
    'fulfill_without_tracking', (p ->> 'fulfill_without_tracking')::boolean,
    'auto_import_products', (p ->> 'auto_import_products')::boolean, 'mark_delivered', (p ->> 'mark_delivered')::boolean,
    'cancel_on_shopify', (p ->> 'cancel_on_shopify')::boolean, 'cancel_email', (p ->> 'cancel_email')::boolean,
    'mark_paid_on_delivery', (p ->> 'mark_paid_on_delivery')::boolean,
    'status_tags', (p ->> 'status_tags')::boolean, 'courier_events', (p ->> 'courier_events')::boolean,
    'update_products', (p ->> 'update_products')::boolean, 'status_sync', (p ->> 'status_sync')::boolean));
  update public.sales_channels set settings = v_new where id = p_channel_id;

  if (coalesce((v_new ->> 'inventory_sync')::boolean, false) and not public._channel_opt(v_old, 'inventory_sync', false))
     or v_loc is distinct from v_old.settings ->> 'location_id' then
    update public.sales_channel_variants m set last_pushed_qty = m.shopify_available,
      sync_status = case when m.inventory_item_id is null then m.sync_status
                         when m.shopify_available is null then 'NEW'
                         when m.shopify_available = (select greatest(coalesce(i.available, 0), 0) from public.inventory i where i.variant_id = m.variant_id) then 'OK'
                         else 'MISMATCH' end
    where m.channel_id = p_channel_id and m.sync_status <> 'UNTRACKED';
  end if;
  perform public.log_audit('channel.sync_settings', 'sales_channel', p_channel_id::text,
    jsonb_build_object('settings', v_old.settings), jsonb_build_object('settings', v_new));
  return v_new;
end;

channel_update.src:
declare
  v_old public.sales_channels;
  v_row public.sales_channels;
begin
  perform public._require_system();
  select * into v_old from public.sales_channels where id = p_id for update;
  if not found then
    raise exception 'NOT_FOUND: sales channel not found' using errcode = 'P0002';
  end if;
  update public.sales_channels set
    name = coalesce(nullif(trim(p ->> 'name'), ''), name),
    status = coalesce(p ->> 'status', status),
    scopes = coalesce((select array_agg(x) from jsonb_array_elements_text(p -> 'scopes') x), scopes),
    currency = coalesce(p ->> 'currency', currency),
    webhooks = coalesce(p -> 'webhooks', webhooks),
    last_test = coalesce(p -> 'last_test', last_test),
    last_tested_at = case when p ? 'last_test' then now() else last_tested_at end,
    last_error = case when p ? 'last_error' then nullif(p ->> 'last_error', '') else last_error end,
    last_sync_at = case when (p ->> 'synced')::boolean then now() else last_sync_at end,
    connected_at = case when (p ->> 'status') = 'CONNECTED' and v_old.status <> 'CONNECTED' then now() else connected_at end
  where id = p_id returning * into v_row;
  if (p ->> 'status') is distinct from v_old.status and p ? 'status' then
    insert into public.audit_logs(actor_id, actor_email, action, entity_type, entity_id, old_values, new_values)
    values (p_actor, (select email from public.profiles where id = p_actor), 'channel.' || lower(v_row.status), 'sales_channel',
            p_id::text, jsonb_build_object('status', v_old.status), jsonb_build_object('status', v_row.status, 'error', v_row.last_error));
  end if;
  return v_row;
end;

channel_upsert.src:
declare
  v_row public.sales_channels;
  v_platform text := upper(p ->> 'platform');
  v_domain text := lower(trim(p ->> 'shop_domain'));
begin
  perform public.require_feature(lower(p ->> 'platform'));
  if not exists (select 1 from public.sales_channels where platform = upper(p ->> 'platform') and lower(shop_domain) = lower(trim(p ->> 'shop_domain'))
                 and status <> 'DISCONNECTED') then
    perform public.require_limit('stores');
  end if;
  perform public._require_system();
  if v_platform not in ('SHOPIFY', 'WOOCOMMERCE') then
    raise exception 'VALIDATION: unknown platform' using errcode = '22023';
  end if;
  insert into public.sales_channels(platform, name, shop_domain, auth_mode, created_by)
  values (v_platform, coalesce(nullif(trim(p ->> 'name'), ''), v_domain), v_domain, p ->> 'auth_mode', p_actor)
  on conflict (platform, lower(shop_domain)) do update
    set auth_mode = coalesce(excluded.auth_mode, sales_channels.auth_mode),
        status = case when sales_channels.status = 'DISCONNECTED' then 'PENDING' else sales_channels.status end
  returning * into v_row;
  return v_row;
end;

channel_variant_link.src:
declare
  v_ci public.channel_catalog_items;
begin
  perform public.require_permission('inventory.adjust');
  select * into v_ci from public.channel_catalog_items where channel_id = p_channel_id and external_variant_id = p_external_variant_id;
  if p_variant_id is null then
    update public.sales_channel_variants set inventory_item_id = null, sync_status = 'NEW'
    where channel_id = p_channel_id and external_variant_id = p_external_variant_id;
  else
    if not found then
      raise exception 'NOT_FOUND: import the store''s catalog first' using errcode = 'P0002';
    end if;
    insert into public.sales_channel_variants(channel_id, external_variant_id, external_product_id, variant_id, inventory_item_id, sku, sync_status)
    values (p_channel_id, p_external_variant_id, v_ci.external_product_id, p_variant_id, v_ci.inventory_item_id, v_ci.sku,
      case when v_ci.tracked then 'NEW' else 'UNTRACKED' end)
    on conflict (channel_id, external_variant_id) do update
      set variant_id = excluded.variant_id, inventory_item_id = excluded.inventory_item_id, sku = excluded.sku, sync_status = excluded.sync_status;
  end if;
  perform public.log_audit('channel.variant_link', 'sales_channel', p_channel_id::text, null,
    jsonb_build_object('external_variant_id', p_external_variant_id, 'variant_id', p_variant_id));
end;

checkout_risk_preview.src:
declare
  v_check public.fraud_checks;
  v_eval jsonb;
begin
  if not public.is_system_context() then
    raise exception 'PERMISSION_DENIED' using errcode = '42501';
  end if;
  select * into v_check from public.fraud_checks where id = p_fraud_check_id;
  if not found or not public.setting_bool('fraud', array['enabled'], true) then
    return public.payment_requirement_for('ALLOW', 0, (p_context ->> 'order_value')::numeric, p_payment_method);
  end if;
  v_eval := public.evaluate_fraud_rules(v_check.metrics, p_context);
  return public.payment_requirement_for((v_eval ->> 'decision')::public.fraud_decision,
    (v_eval ->> 'advance_amount')::numeric, (p_context ->> 'order_value')::numeric, p_payment_method,
    v_eval ->> 'customer_message');
end;

claim_notifications.src:
declare
  r public.notification_logs;
  v jsonb;
  v_out public.notification_logs;
  v_hold int := coalesce((public._usage_policy('SMS') ->> 'hold_hours')::int, 6);
begin
  if not public.is_system_context() then
    raise exception 'PERMISSION_DENIED' using errcode = '42501';
  end if;
  -- Interrupted while sending: we cannot know whether it went out, so it stays charged.
  update public.notification_logs set status = 'FAILED',
    error = 'Sending was interrupted. Check with the provider before trying again.'
  where status = 'SENDING' and updated_at < now() - interval '15 minutes';
  for r in
    select * from public.notification_logs
    where status = 'QUEUED' and next_attempt_at <= now()
    order by next_attempt_at
    limit least(greatest(p_limit, 1), 100)
    for update skip locked
  loop
    if r.channel = 'SMS' then
      v := public._sms_reserve(r);
      if not (v ->> 'allowed')::boolean then
        if v ->> 'reason' = 'NO_CREDITS' and r.created_at > now() - make_interval(hours => v_hold) then
          -- Waits for credits (sent as soon as there are some), up to the policy's hold time.
          update public.notification_logs set next_attempt_at = now() + interval '10 minutes', error = 'Waiting for SMS credits: ' || (v ->> 'message')
          where id = r.id;
        else
          update public.notification_logs set status = 'FAILED', error = left(coalesce(v ->> 'message', v ->> 'reason'), 1000) where id = r.id;
        end if;
        continue;
      end if;
    end if;
    update public.notification_logs set status = 'SENDING', attempts = attempts + 1 where id = r.id returning * into v_out;
    return next v_out;
  end loop;
end;

classify_touch.src:
declare
  p jsonb := coalesce(p_touch -> 'params', '{}'::jsonb);
  src text := lower(trim(coalesce(p ->> 'utm_source', '')));
  med text := lower(trim(coalesce(p ->> 'utm_medium', '')));
  site text := lower(coalesce(p ->> 'site_source_name', ''));
  placement text := lower(coalesce(p ->> 'placement', ''));
  host text := lower(coalesce(substring(p_touch ->> 'referrer' from '^[a-z0-9+.-]+://([^/:?#]+)'), ''));
  shop_ad boolean := lower(coalesce(p ->> 'shopify_marketing_type', '')) = 'ad';
  paid boolean := med ~ '^(cpc|ppc|paid|paid[_ -]?social|paid[_ -]?search|ads?|cpm|cpv|cpa|display|sponsored|boost(ed)?|retargeting|remarketing)$' or shop_ad;
  organic_med boolean := med ~ '^(organic|social|bio|post|story|reel|referral|profile|link[_ -]?in[_ -]?bio)$';
  meta_ids boolean := p ? 'ad_id' or p ? 'adset_id' or p ? 'campaign_id';
  meta_src boolean := src in ('facebook', 'fb', 'meta', 'ig', 'instagram', 'an', 'msg', 'messenger', 'audience_network');
  insta boolean := src in ('ig', 'instagram') or site = 'ig' or placement like 'instagram%' or host ~ '(^|\.)instagram\.com$' or host like '%com.instagram.%';
  v_channel text;
  v_label text;
  v_medium text;
  v_paid boolean;
  v_platform text;
  v_click_type text := case when p ? 'fbclid' then 'fbclid' when p ? 'gclid' then 'gclid' when p ? 'gbraid' then 'gbraid'
    when p ? 'wbraid' then 'wbraid' when p ? 'ttclid' then 'ttclid' when p ? 'msclkid' then 'msclkid'
    when p ? 'srsltid' then 'srsltid' end;
begin
  if p_touch is null or jsonb_typeof(p_touch) <> 'object' then
    return jsonb_build_object('channel', 'unknown', 'source', 'Unknown', 'medium', 'Unknown', 'is_paid', null, 'platform', null);
  end if;

  if (meta_src and (paid or meta_ids)) or (p ? 'fbclid' and (paid or meta_ids)) or (shop_ad and (host ~ '(facebook|instagram|fb)\.' or meta_src)) then
    v_channel := 'paid_social'; v_paid := true; v_platform := 'META'; v_medium := 'Paid';
    v_label := case when insta then 'Instagram Ads' when site = 'msg' then 'Messenger Ads' else 'Facebook Ads' end;
  elsif p ? 'gclid' or p ? 'gbraid' or p ? 'wbraid' or (src in ('google', 'adwords', 'googleads', 'google_ads') and paid) then
    v_channel := 'paid_search'; v_paid := true; v_platform := 'GOOGLE'; v_medium := 'Paid'; v_label := 'Google Ads';
  elsif p ? 'ttclid' or (src in ('tiktok', 'tt') and paid) then
    v_channel := 'paid_social'; v_paid := true; v_platform := 'TIKTOK'; v_medium := 'Paid'; v_label := 'TikTok Ads';
  elsif p ? 'msclkid' or (src in ('bing', 'microsoft') and paid) then
    v_channel := 'paid_search'; v_paid := true; v_platform := 'OTHER'; v_medium := 'Paid'; v_label := 'Microsoft Ads';
  elsif paid and src <> '' then
    v_channel := 'paid_other'; v_paid := true; v_platform := 'OTHER'; v_medium := 'Paid'; v_label := initcap(src) || ' Ads';
  elsif p ? 'srsltid' then
    v_channel := 'organic_search'; v_paid := false; v_medium := 'Organic'; v_label := 'Google';
  elsif src <> '' then
    v_paid := false;
    if meta_src then
      v_label := case when insta then 'Instagram' when src in ('msg', 'messenger') then 'Messenger' else 'Facebook' end;
      if organic_med then
        v_channel := 'organic_social'; v_medium := 'Organic';
      else
        -- Tagged as Facebook / Instagram but not as an ad or a post: unknown.
        v_channel := 'social'; v_paid := null; v_medium := 'Social (paid or organic)';
      end if;
    elsif src in ('whatsapp', 'wa') then v_channel := 'messaging'; v_medium := 'Messaging'; v_label := 'WhatsApp';
    elsif src in ('google', 'bing', 'yahoo', 'duckduckgo', 'yandex') then v_channel := 'organic_search'; v_medium := 'Organic'; v_label := initcap(src);
    elsif src in ('email', 'newsletter', 'mailchimp', 'klaviyo', 'shopify_email') or med = 'email' then v_channel := 'email'; v_medium := 'Email'; v_label := 'Email';
    elsif src = 'sms' or med = 'sms' then v_channel := 'sms'; v_medium := 'SMS'; v_label := 'SMS';
    elsif src in ('tiktok', 'youtube', 'twitter', 'x', 'linkedin', 'pinterest', 'threads') then
      v_label := case src when 'x' then 'X' when 'tiktok' then 'TikTok' when 'youtube' then 'YouTube' else initcap(src) end;
      if organic_med then v_channel := 'organic_social'; v_medium := 'Organic';
      else v_channel := 'social'; v_paid := null; v_medium := 'Social (paid or organic)'; end if;
    else v_channel := 'referral'; v_medium := 'Referral'; v_label := initcap(src);
    end if;
  elsif p ? 'fbclid' then
    v_channel := 'social'; v_paid := null; v_medium := 'Social (paid or organic)'; v_label := case when insta then 'Instagram' else 'Facebook' end;
  elsif host <> '' then
    v_paid := false;
    if host ~ '(^|\.)(facebook\.com|fb\.com|fb\.me)$' or host like '%com.facebook.%' then
      v_channel := 'social'; v_paid := null; v_medium := 'Social (paid or organic)'; v_label := 'Facebook';
    elsif host ~ '(^|\.)instagram\.com$' or host like '%com.instagram.%' then
      v_channel := 'social'; v_paid := null; v_medium := 'Social (paid or organic)'; v_label := 'Instagram';
    elsif host ~ '(^|\.)(messenger\.com|m\.me)$' then v_channel := 'messaging'; v_medium := 'Messaging'; v_label := 'Messenger';
    elsif host ~ '(^|\.)(whatsapp\.com|wa\.me)$' then v_channel := 'messaging'; v_medium := 'Messaging'; v_label := 'WhatsApp';
    elsif host ~ '(^|\.)google\.[a-z.]+$' or host like '%com.google.%' then v_channel := 'organic_search'; v_medium := 'Organic'; v_label := 'Google';
    elsif host ~ '(^|\.)(bing\.com|duckduckgo\.com|search\.yahoo\.com|yandex\.[a-z]+|baidu\.com)$' then
      v_channel := 'organic_search'; v_medium := 'Organic'; v_label := initcap(split_part(regexp_replace(host, '^(www|search)\.', ''), '.', 1));
    elsif host ~ '(^|\.)(youtube\.com|youtu\.be)$' then v_channel := 'social'; v_paid := null; v_medium := 'Social (paid or organic)'; v_label := 'YouTube';
    elsif host ~ '(^|\.)tiktok\.com$' then v_channel := 'social'; v_paid := null; v_medium := 'Social (paid or organic)'; v_label := 'TikTok';
    elsif host ~ '(^|\.)(t\.co|twitter\.com|x\.com)$' then v_channel := 'social'; v_paid := null; v_medium := 'Social (paid or organic)'; v_label := 'X';
    else v_channel := 'referral'; v_medium := 'Referral'; v_label := regexp_replace(host, '^www\.', '');
    end if;
  else
    v_channel := 'direct'; v_paid := false; v_medium := 'Direct'; v_label := 'Direct';
  end if;

  return jsonb_build_object(
    'channel', v_channel, 'source', v_label, 'medium', v_medium, 'is_paid', v_paid, 'platform', v_platform,
    'click_id_type', v_click_type, 'click_id', case when v_click_type is not null then left(p ->> v_click_type, 200) end,
    'campaign', nullif(coalesce(p ->> 'campaign_name', p ->> 'utm_campaign'), ''),
    'adset', nullif(coalesce(p ->> 'adset_name', case when v_channel = 'paid_social' then p ->> 'utm_term' end), ''),
    'ad', nullif(coalesce(p ->> 'ad_name', case when v_channel = 'paid_social' then p ->> 'utm_content' end), ''),
    'campaign_id', nullif(p ->> 'campaign_id', ''), 'adset_id', nullif(p ->> 'adset_id', ''), 'ad_id', nullif(p ->> 'ad_id', ''),
    'referrer_host', nullif(host, ''));
end;

complete_notification.src:
declare
  v_log public.notification_logs;
  u public.service_usage;
  -- Provider charges are the platform's cost; only unmetered (own-business) accounts see them as their cost.
  v_own_cost boolean;
begin
  if not public.is_system_context() then
    raise exception 'PERMISSION_DENIED' using errcode = '42501';
  end if;
  select * into u from public.service_usage s
  where s.merchant_id = (select merchant_id from public.notification_logs where id = p_id) and s.idempotency_key = 'sms:' || p_id;
  v_own_cost := u.id is null or u.charge = 'PLAN';
  update public.notification_logs set
    status = case when p_success then 'SENT' when p_permanent or attempts >= 3 then 'FAILED' else 'QUEUED' end::public.notification_status,
    provider = coalesce(p_provider, provider),
    provider_message_id = case when p_success then left(p_provider_message_id, 120) else provider_message_id end,
    error = case when p_success then null else left(p_error, 1000) end,
    sent_at = case when p_success then now() else sent_at end,
    next_attempt_at = case when p_success then next_attempt_at else now() + make_interval(mins => 5 * attempts) end,
    cost = case when p_success and v_own_cost and p_cost is not null and p_cost >= 0 then p_cost else cost end,
    cost_source = case when p_success and v_own_cost and p_cost is not null and p_cost >= 0 then 'PROVIDER' else cost_source end,
    delivery_status = case
      when p_success and channel = 'SMS' then
        case when p_delivery_status in ('PENDING', 'DELIVERED', 'FAILED', 'UNKNOWN') then p_delivery_status else 'UNKNOWN' end
      else delivery_status end,
    delivered_at = case when p_success and p_delivery_status = 'DELIVERED' then now() else delivered_at end
  where id = p_id and status = 'SENDING'
  returning * into v_log;
  if v_log.id is null then
    return null;
  end if;
  if u.id is not null then
    if v_log.status = 'SENT' then
      perform public._usage_finish(u.id, true, null, p_cost, case when p_delivery_status = 'DELIVERED' then 'DELIVERED' end);
    elsif v_log.status = 'FAILED' then
      perform public._usage_finish(u.id, false, p_error);
    end if;
  end if;
  if v_log.status = 'SENT' then
    perform public._post_sms_finance(p_id);
  end if;
  return v_log.status::text;
end;

compute_risk_score.src:
declare
  v_delivered numeric := coalesce((p_metrics ->> 'delivered_orders')::numeric, 0);
  v_cancelled numeric := coalesce((p_metrics ->> 'cancelled_orders')::numeric, 0);
  v_returned numeric := coalesce((p_metrics ->> 'returned_orders')::numeric, 0);
  v_failed numeric := coalesce((p_metrics ->> 'failed_delivery_orders')::numeric, 0);
  v_completed numeric := v_delivered + v_cancelled + v_returned + v_failed;
  v_rate numeric;
  v_score numeric;
begin
  if v_completed = 0 then
    v_score := public.setting_numeric('fraud', array['new_customer_score'], 20);
  else
    v_rate := (v_returned + v_failed + 0.5 * v_cancelled) / v_completed;
    v_score := v_rate * 100;
    -- Established customers with a clean record are trusted more.
    if v_delivered >= 5 and v_rate < 0.2 then
      v_score := v_score * 0.5;
    end if;
  end if;
  if coalesce((p_metrics ->> 'phone_flagged')::boolean, false) then
    v_score := greatest(v_score, 90);
  end if;
  if (p_metrics ->> 'provider_risk_score') is not null then
    v_score := greatest(v_score, (p_metrics ->> 'provider_risk_score')::numeric);
  end if;
  return round(least(greatest(v_score, 0), 100), 2);
end;

confirm_payment.src:
declare
  v_payment public.payments;
  v_event_id uuid;
  v_op public.order_payments;
begin
  if not public.is_system_context() then
    raise exception 'PERMISSION_DENIED' using errcode = '42501';
  end if;

  select * into v_payment from public.payments where reference = p_reference and provider = p_provider for update;
  if not found then
    raise exception 'NOT_FOUND: payment % not found', p_reference using errcode = 'P0002';
  end if;

  insert into public.payment_events(payment_id, provider, event_id, event_type, payload)
  values (v_payment.id, p_provider, p_event_id, p_event_type, coalesce(p_payload, '{}'::jsonb))
  on conflict (provider, event_id) do nothing
  returning id into v_event_id;

  if v_event_id is null then
    return jsonb_build_object('status', 'duplicate_event', 'payment_status', v_payment.status);
  end if;

  if v_payment.status = 'SUCCEEDED' then
    update public.payment_events set processed_at = now(), result = 'already_succeeded' where id = v_event_id;
    return jsonb_build_object('status', 'already_succeeded', 'payment_status', v_payment.status);
  end if;

  if not p_success then
    update public.payments set status = 'FAILED', failure_reason = coalesce(p_payload ->> 'reason', 'Declined by provider')
    where id = v_payment.id and status in ('PENDING', 'REQUIRES_VERIFICATION');
    update public.payment_events set processed_at = now(), result = 'failed' where id = v_event_id;
    return jsonb_build_object('status', 'failed');
  end if;

  if p_amount is null or public.money(p_amount) < v_payment.amount then
    update public.payments set status = 'REQUIRES_VERIFICATION',
      failure_reason = format('Amount mismatch: expected %s, provider reported %s', v_payment.amount, p_amount),
      provider_transaction_id = coalesce(provider_transaction_id, p_provider_transaction_id)
    where id = v_payment.id;
    update public.payment_events set processed_at = now(), result = 'amount_mismatch' where id = v_event_id;
    return jsonb_build_object('status', 'amount_mismatch');
  end if;

  update public.payments set
    status = case when status in ('FAILED', 'CANCELLED', 'EXPIRED') then 'PENDING' else status end,
    failure_reason = case when status in ('FAILED', 'CANCELLED', 'EXPIRED') then null else failure_reason end,
    provider_transaction_id = coalesce(provider_transaction_id, p_provider_transaction_id)
  where id = v_payment.id;
  v_op := public._settle_payment(v_payment.id, least(public.money(p_amount), v_payment.amount));
  update public.payment_events set processed_at = now(), result = 'succeeded' where id = v_event_id;
  return jsonb_build_object('status', 'succeeded', 'order_payment_id', v_op.id);
end;

convert_checkout_lead.src:
declare
  v_count int;
begin
  if not (public.is_system_context() or public.has_permission('orders.create')) then
    raise exception 'PERMISSION_DENIED' using errcode = '42501';
  end if;
  update public.checkout_leads set status = 'CONVERTED', order_id = p_order_id, updated_at = now()
  where status in ('OPEN', 'CONTACTED')
    and (visitor_id = p_visitor_id or (phone = public.clean_phone(p_phone) and updated_at > now() - interval '7 days'));
  get diagnostics v_count = row_count;
  perform public._convert_store_carts(p_visitor_id, public.clean_phone(p_phone), p_order_id);
  return v_count;
end;

