courier_parcels.src:
declare
  v_tab text := coalesce(nullif(p ->> 'tab', ''), 'all');
  v_q text := nullif(trim(coalesce(p ->> 'q', '')), '');
  v_courier uuid := nullif(p ->> 'courier_id', '')::uuid;
  v_charge text := nullif(p ->> 'in_charge', '');
  v_age_from int := nullif(p ->> 'age_from', '')::int;
  v_age_to int := nullif(p ->> 'age_to', '')::int;
  v_att_from int := nullif(p ->> 'attempt_from', '')::int;
  v_att_to int := nullif(p ->> 'attempt_to', '')::int;
  v_limit int := least(greatest(coalesce((p ->> 'limit')::int, 25), 1), 100);
  v_offset int := greatest(coalesce((p ->> 'offset')::int, 0), 0);
  v_digits text;
  v_today timestamptz := public._ts_from(public._local_date(now()));
begin
  perform public.require_permission('couriers.view');
  if v_tab not in ('all', 'in_transit', 'pending_entry', 'assigned', 'cancelled', 'return_pending', 'returned', 'damage_lost', 'delivered') then
    raise exception 'VALIDATION: unknown parcel tab' using errcode = '22023';
  end if;
  if v_charge is not null and v_charge <> 'none' and v_charge !~ '^[0-9a-f-]{36}$' then
    raise exception 'VALIDATION: unknown staff member' using errcode = '22023';
  end if;
  v_digits := nullif(regexp_replace(coalesce(v_q, ''), '\D', '', 'g'), '');

  return (
    with base as (
      select o, s, a.attempts, public._parcel_tab2(o, s, a.attempts) as tab,
        case when s.id is null then null else greatest(0, (public._local_date(coalesce(s.delivered_at, now())) - public._local_date(s.created_at)))::int end as age_days
      from public.orders o
      left join lateral (
        select * from public.shipments s where s.order_id = o.id
        order by s.is_active desc, s.created_at desc limit 1
      ) s on true
      cross join lateral (
        select count(*)::int as attempts from public.shipment_events e where e.shipment_id = s.id and e.status = 'OUT_FOR_DELIVERY'
      ) a
      where o.merged_into is null
        and (v_courier is null or s.courier_id = v_courier)
        and (v_charge is null or (v_charge = 'none' and o.assigned_to is null) or o.assigned_to::text = v_charge)
        and (v_q is null or o.order_number ilike '%' || v_q || '%' or o.customer_name ilike '%' || v_q || '%'
             or (v_digits is not null and length(v_digits) >= 4 and o.customer_phone like '%' || v_digits || '%')
             or s.consignment_id ilike v_q || '%' or s.tracking_number ilike v_q || '%')
    ), filtered as (
      select * from base where tab is not null
        and (v_age_from is null or age_days >= v_age_from) and (v_age_to is null or age_days <= v_age_to)
        and (v_att_from is null or attempts >= v_att_from) and (v_att_to is null or attempts <= v_att_to)
    ), rows as (
      select * from filtered where v_tab = 'all' or tab = v_tab
    )
    select jsonb_build_object(
      'counts', (select jsonb_build_object(
        'all', count(*),
        'in_transit', count(*) filter (where tab = 'in_transit'),
        'pending_entry', count(*) filter (where tab = 'pending_entry'),
        'assigned', count(*) filter (where tab = 'assigned'),
        'cancelled', count(*) filter (where tab = 'cancelled'),
        'return_pending', count(*) filter (where tab = 'return_pending'),
        'returned', count(*) filter (where tab = 'returned'),
        'damage_lost', count(*) filter (where tab = 'damage_lost'),
        'delivered', count(*) filter (where tab = 'delivered')) from filtered),
      'total', (select count(*) from rows),
      'items', coalesce((
        select jsonb_agg(item order by created_at desc) from (
          select (r.o).created_at as created_at, jsonb_build_object(
            'id', (r.o).id, 'order_number', (r.o).order_number, 'created_at', (r.o).created_at, 'status', (r.o).status, 'tab', r.tab,
            'customer', jsonb_build_object('name', (r.o).customer_name, 'phone', (r.o).customer_phone,
              'address', (r.o).shipping_address, 'area', (r.o).shipping_area, 'district', (r.o).shipping_district),
            'customer_note', (r.o).customer_note,
            'total', (r.o).total_amount, 'cod_amount', (r.o).cod_amount, 'amount_paid', (r.o).amount_paid,
            'products', coalesce((select jsonb_agg(jsonb_build_object('name', i.product_name, 'variant', i.variant_title, 'qty', i.quantity,
                'image', i.image_url, 'damaged', i.damaged_quantity, 'returned', i.returned_quantity) order by i.created_at)
              from public.order_items i where i.order_id = (r.o).id), '[]'::jsonb),
            'item_count', (select coalesce(sum(i.quantity), 0) from public.order_items i where i.order_id = (r.o).id),
            'courier', case when (r.s).id is null then null else (
              select jsonb_build_object('id', c.id, 'name', c.name, 'provider', c.provider, 'tracking_url_template', c.tracking_url_template)
              from public.couriers c where c.id = (r.s).courier_id) end,
            'shipment', case when (r.s).id is null then null else jsonb_build_object(
              'id', (r.s).id, 'status', (r.s).status, 'consignment_id', (r.s).consignment_id, 'tracking_number', (r.s).tracking_number,
              'booked_at', (r.s).created_at, 'shipping_cost', (r.s).shipping_cost, 'cod_collected', (r.s).cod_collected,
              'delivered_at', (r.s).delivered_at) end,
            'attempts', r.attempts,
            'age_days', r.age_days,
            'rider', (select nullif(jsonb_strip_nulls(jsonb_build_object(
                  'name', coalesce(e.raw ->> 'rider_name', e.raw ->> 'delivery_man_name', e.raw ->> 'deliveryman_name', e.raw #>> '{rider,name}'),
                  'phone', coalesce(e.raw ->> 'rider_phone', e.raw ->> 'delivery_man_phone', e.raw ->> 'deliveryman_phone', e.raw #>> '{rider,phone}'))), '{}'::jsonb)
                from public.shipment_events e where e.shipment_id = (r.s).id
                  and coalesce(e.raw ->> 'rider_name', e.raw ->> 'delivery_man_name', e.raw ->> 'deliveryman_name', e.raw #>> '{rider,name}') is not null
                order by e.occurred_at desc limit 1),
            'rider_note', (select coalesce(nullif(e.raw ->> 'reason', ''), nullif(e.raw ->> 'note', ''), e.description)
                from public.shipment_events e where e.shipment_id = (r.s).id order by e.occurred_at desc limit 1),
            'last_update_at', (select max(e.occurred_at) from public.shipment_events e where e.shipment_id = (r.s).id),
            'customer_calls', (select jsonb_build_object(
                'am', count(*) filter (where c.called_at >= v_today and extract(hour from c.called_at at time zone 'Asia/Dhaka') < 12),
                'pm', count(*) filter (where c.called_at >= v_today and extract(hour from c.called_at at time zone 'Asia/Dhaka') >= 12),
                'total', count(*), 'last_outcome', (array_agg(c.outcome order by c.called_at desc))[1], 'last_at', max(c.called_at))
              from public.parcel_calls c where c.order_id = (r.o).id and c.party = 'CUSTOMER'),
            'rider_calls', (select jsonb_build_object(
                'am', count(*) filter (where c.called_at >= v_today and extract(hour from c.called_at at time zone 'Asia/Dhaka') < 12),
                'pm', count(*) filter (where c.called_at >= v_today and extract(hour from c.called_at at time zone 'Asia/Dhaka') >= 12),
                'total', count(*), 'last_outcome', (array_agg(c.outcome order by c.called_at desc))[1], 'last_at', max(c.called_at))
              from public.parcel_calls c where c.order_id = (r.o).id and c.party = 'RIDER'),
            'tags', to_jsonb(coalesce((r.o).tags, '{}')),
            'in_charge', (select jsonb_build_object('id', pr.id, 'name', coalesce(pr.full_name, pr.email)) from public.profiles pr where pr.id = (r.o).assigned_to)
          ) as item
          from rows r
          order by (r.o).created_at desc
          limit v_limit offset v_offset
        ) x), '[]'::jsonb)
    )
  );
end;

courier_webhook_secret_get.src:
declare
  v_value text;
begin
  if not public.is_system_context() then
    raise exception 'PERMISSION_DENIED' using errcode = '42501';
  end if;
  perform public._courier_in_context(p_courier_id);
  select decrypted_secret into v_value from vault.decrypted_secrets where name = 'courier-webhook:' || p_courier_id::text;
  return nullif(v_value, '');
end;

courier_webhook_secret_set.src:
declare
  v_merchant uuid;
  v_secret uuid;
  v_name text := 'courier-webhook:' || p_courier_id::text;
begin
  if not public.is_system_context() then
    raise exception 'PERMISSION_DENIED' using errcode = '42501';
  end if;
  if p_secret is null or length(p_secret) < 16 or length(p_secret) > 200 then
    raise exception 'VALIDATION: the webhook secret must be 16 to 200 characters' using errcode = '22023';
  end if;
  v_merchant := public._courier_in_context(p_courier_id);
  select id into v_secret from vault.secrets where name = v_name;
  if v_secret is null then
    perform vault.create_secret(p_secret, v_name, 'Courier webhook secret');
  else
    perform vault.update_secret(v_secret, p_secret);
  end if;
  update public.couriers set config = config || jsonb_build_object('webhook_secret_hint', '••••' || right(p_secret, 4),
    'webhook_secret_set_at', now()) where id = p_courier_id;
  insert into public.audit_logs(merchant_id, actor_id, actor_email, action, entity_type, entity_id, metadata)
  values (v_merchant, p_actor, (select email from public.profiles where id = p_actor and merchant_id = v_merchant),
          'courier.webhook_secret_set', 'couriers', p_courier_id::text, '{}'::jsonb);
end;

create_finance_transaction.src:
declare
  v_cat public.finance_categories;
  v_row public.finance_transactions;
  v_foreign numeric := nullif(p ->> 'foreign_amount', '')::numeric;
  v_rate numeric := nullif(p ->> 'exchange_rate', '')::numeric;
  v_amount numeric := coalesce(nullif(p ->> 'amount', '')::numeric, v_foreign * v_rate);
  v_date date := coalesce(nullif(p ->> 'txn_date', '')::date, (now() at time zone public.store_timezone())::date);
  v_account uuid := nullif(p ->> 'account_id', '')::uuid;
begin
  perform public.require_permission('finance.manage');
  select * into v_cat from public.finance_categories where id = (p ->> 'category_id')::uuid;
  if not found or not v_cat.is_active then
    raise exception 'VALIDATION: choose an active category' using errcode = '22023';
  end if;
  if not v_cat.allow_manual then
    raise exception 'VALIDATION: % entries are created automatically and cannot be added by hand', v_cat.name using errcode = '22023';
  end if;
  if v_cat.type::text <> upper(coalesce(p ->> 'type', v_cat.type::text)) then
    raise exception 'VALIDATION: category % is an % category', v_cat.name, lower(v_cat.type::text) using errcode = '22023';
  end if;
  if v_amount is null or v_amount <= 0 then
    raise exception 'VALIDATION: amount must be greater than zero' using errcode = '22023';
  end if;
  if v_foreign is not null and (v_foreign <= 0 or v_rate is null or v_rate <= 0) then
    raise exception 'VALIDATION: a foreign amount needs a positive amount and rate' using errcode = '22023';
  end if;
  if v_date > (now() at time zone public.store_timezone())::date + 1 then
    raise exception 'VALIDATION: transactions cannot be dated in the future' using errcode = '22023';
  end if;
  if v_account is not null and not exists (select 1 from public.finance_accounts where id = v_account and is_active) then
    raise exception 'VALIDATION: choose an active payment account' using errcode = '22023';
  end if;

  insert into public.finance_transactions(type, category_id, amount, txn_date, is_cash, payment_channel, reference,
    order_id, customer_id, supplier_id, notes, source, created_by, sub_category, account_id, foreign_amount, foreign_currency, exchange_rate)
  values (v_cat.type, v_cat.id, public.money(v_amount), v_date, coalesce((p ->> 'is_cash')::boolean, true),
          nullif(p ->> 'payment_channel', '')::public.payment_channel, nullif(trim(coalesce(p ->> 'reference', '')), ''),
          nullif(p ->> 'order_id', '')::uuid, nullif(p ->> 'customer_id', '')::uuid, nullif(p ->> 'supplier_id', '')::uuid,
          nullif(trim(coalesce(p ->> 'notes', '')), ''), 'MANUAL', auth.uid(),
          nullif(left(trim(coalesce(p ->> 'sub_category', '')), 60), ''), v_account,
          round(v_foreign, 2), case when v_foreign is not null then upper(coalesce(nullif(p ->> 'foreign_currency', ''), 'USD')) end,
          case when v_foreign is not null then v_rate end)
  returning * into v_row;

  -- Sub-categories typed here are remembered for the category.
  if v_row.sub_category is not null and not (v_row.sub_category = any(v_cat.subcategories)) then
    update public.finance_categories set subcategories = subcategories || v_row.sub_category where id = v_cat.id;
  end if;

  perform public.log_audit('finance.entry_created', 'finance_transaction', v_row.id::text, null,
    jsonb_build_object('txn_number', v_row.txn_number, 'type', v_row.type, 'category', v_cat.code,
                       'amount', v_row.amount, 'date', v_row.txn_date, 'account', v_account));
  return v_row;
end;

credits_expire_all.src:
declare
  r record;
  v_n int := 0;
begin
  for r in select distinct merchant_id, credit_type from public.credit_lots where remaining > 0 and expires_at <= now() loop
    perform 1 from public.credit_balances where merchant_id = r.merchant_id and credit_type = r.credit_type for update;
    v_n := v_n + public._credit_expire(r.merchant_id, r.credit_type);
  end loop;
  return v_n;
end;

credits_start_recharge.src:
declare
  v_merchant uuid := public.current_merchant_id();
  k public.credit_packages;
  v_inv public.billing_invoices;
begin
  if not public.billing_can_pay() then
    raise exception 'PERMISSION_DENIED: only the owner or staff who manage settings can buy credits' using errcode = '42501';
  end if;
  select * into k from public.credit_packages where id = p_package and status = 'ACTIVE';
  if k.id is null then
    raise exception 'NOT_FOUND: package not available' using errcode = 'P0002';
  end if;
  select * into v_inv from public.billing_invoices
  where merchant_id = v_merchant and kind = 'CREDITS' and status = 'OPEN' and amount_paid = 0 and created_at > now() - interval '30 minutes'
    and lines -> 0 ->> 'package_id' = k.id::text
  order by created_at desc limit 1;
  if v_inv.id is null then
    if (select count(*) from public.billing_invoices where merchant_id = v_merchant and kind = 'CREDITS' and created_at > now() - interval '1 hour') >= 10 then
      raise exception 'VALIDATION: too many recharge attempts; try again in an hour' using errcode = '22023';
    end if;
    insert into public.billing_invoices (merchant_id, kind, lines, total, currency, due_at, created_by)
    values (v_merchant, 'CREDITS',
            jsonb_build_array(jsonb_build_object('kind', 'credits', 'label', k.name, 'amount', k.price, 'package_id', k.id,
              'credit_type', k.credit_type, 'credits', k.credits + k.bonus_credits, 'bonus', k.bonus_credits)),
            k.price, k.currency, now() + interval '1 day', auth.uid())
    returning * into v_inv;
  end if;
  return jsonb_build_object('id', v_inv.id, 'number', v_inv.number, 'total', v_inv.total, 'currency', v_inv.currency, 'lines', v_inv.lines,
    'gateways', (select coalesce(jsonb_agg(g.key order by g.key), '[]'::jsonb) from public.platform_settings ps, jsonb_each(ps.value) g
                 where ps.key = 'billing_gateways' and (g.value ->> 'enabled')::boolean));
end;

cron_secret_matches.src:
declare
  v_secret text;
begin
  if not public.is_system_context() then
    raise exception 'PERMISSION_DENIED' using errcode = '42501';
  end if;
  if p_secret is null or length(p_secret) < 16 then
    return false;
  end if;
  select decrypted_secret into v_secret from vault.decrypted_secrets where name = 'cron_secret';
  return v_secret is not null
    and extensions.digest(v_secret, 'sha256') = extensions.digest(p_secret, 'sha256');
end;

current_merchant_id.src:
declare
  v_role text := coalesce(auth.jwt() ->> 'role', '');
  v_uid uuid;
  v_text text;
  v_id uuid;
begin
  v_text := nullif(current_setting('app.merchant_id', true), '');
  if v_text is not null
     and (v_role not in ('anon', 'authenticated')
          or (v_role = 'authenticated'
              and exists (select 1 from public.platform_staff ps where ps.user_id = auth.uid() and ps.is_active))) then
    if v_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
      raise exception 'INVALID_MERCHANT_CONTEXT: app.merchant_id is not a merchant id' using errcode = '22023';
    end if;
    return v_text::uuid;
  end if;

  if v_role = 'authenticated' then
    v_uid := auth.uid();
    if v_uid is not null then
      select s.merchant_id into v_id from public.support_sessions s where s.id = public._support_session_id();
      if v_id is not null then
        return v_id;
      end if;
      select p.merchant_id into v_id from public.profiles p where p.id = v_uid;
      if v_id is not null then
        return v_id;
      end if;
    end if;
  end if;

  if v_role in ('anon', 'authenticated', 'service_role') then
    v_text := nullif(current_setting('request.headers', true), '')::jsonb ->> 'x-merchant-id';
    if v_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
      select m.id into v_id from public.merchants m where m.id = v_text::uuid and m.status <> 'CLOSED';
      return v_id;
    end if;
  end if;

  return null;
end;

customer_my_orders.src:
select jsonb_build_object(
