evaluate_coupon.src:
declare
  v_coupon public.coupons;
  v_phone text := public.clean_phone(p_phone);
  v_used int;
  v_disc record;
begin
  if p_code is null or trim(p_code) = '' then
    return jsonb_build_object('valid', false, 'reason', 'EMPTY', 'message', 'Enter a coupon code');
  end if;
  select * into v_coupon from public.coupons where code = upper(trim(p_code));
  if not found or not v_coupon.is_active then
    return jsonb_build_object('valid', false, 'reason', 'NOT_FOUND', 'message', 'This coupon code is not valid');
  end if;
  if v_coupon.starts_at is not null and v_coupon.starts_at > now() then
    return jsonb_build_object('valid', false, 'reason', 'NOT_STARTED', 'message', 'This coupon is not active yet');
  end if;
  if v_coupon.ends_at is not null and v_coupon.ends_at <= now() then
    return jsonb_build_object('valid', false, 'reason', 'EXPIRED', 'message', 'This coupon has expired');
  end if;
  if v_coupon.usage_limit is not null and v_coupon.usage_count >= v_coupon.usage_limit then
    return jsonb_build_object('valid', false, 'reason', 'USAGE_LIMIT', 'message', 'This coupon has reached its usage limit');
  end if;
  if v_coupon.per_customer_limit is not null and v_phone is not null then
    select count(*) into v_used from public.coupon_usage
    where coupon_id = v_coupon.id and phone = v_phone and voided_at is null;
    if v_used >= v_coupon.per_customer_limit then
      return jsonb_build_object('valid', false, 'reason', 'CUSTOMER_LIMIT', 'message', 'You have already used this coupon');
    end if;
  end if;
  if coalesce(p_subtotal, 0) < v_coupon.min_order_value then
    return jsonb_build_object('valid', false, 'reason', 'MIN_ORDER',
      'message', format('Minimum order value for this coupon is %s', v_coupon.min_order_value),
      'min_order_value', v_coupon.min_order_value);
  end if;

  select * into v_disc from public.coupon_discount(
    v_coupon.discount_type, v_coupon.discount_value, v_coupon.max_discount, coalesce(p_subtotal, 0), p_delivery_charge);

  return jsonb_build_object(
    'valid', true,
    'coupon_id', v_coupon.id,
    'code', v_coupon.code,
    'discount_type', v_coupon.discount_type,
    'discount_amount', v_disc.discount_amount,
    'delivery_discount', v_disc.delivery_discount,
    'message', case v_coupon.discount_type when 'FREE_DELIVERY' then 'Free delivery applied' else 'Coupon applied' end
  );
end;

evaluate_fraud_rules.src:
declare
  v_facts jsonb := coalesce(p_metrics, '{}'::jsonb) || coalesce(p_context, '{}'::jsonb);
  v_rule record;
  v_matched boolean;
  v_decision public.fraud_decision := 'ALLOW';
  v_advance numeric := 0;
  v_advance_type public.advance_type := 'NONE';
  v_message text;
  v_matched_rules jsonb := '[]'::jsonb;
  v_amount numeric;
  v_cfg jsonb := coalesce(public.get_setting('fraud') -> 'receive_rate', '{}'::jsonb);
  v_tier text;
  v_action text;
  v_rr_decision public.fraud_decision;
  v_rr_type public.advance_type;
begin
  v_facts := v_facts || public._receive_rate_facts(v_facts);

  if coalesce((v_cfg ->> 'enabled')::boolean, false) then
    v_tier := v_facts ->> 'receive_rate_tier';
    v_action := upper(coalesce(v_cfg -> 'actions' ->> v_tier,
      case when v_tier in ('MID', 'LOW', 'ERROR') then 'ADVANCE' else 'COD' end));
    v_rr_decision := case v_action
      when 'ADVANCE' then 'ADVANCE_REQUIRED' when 'REVIEW' then 'REVIEW' when 'BLOCK' then 'BLOCK' else 'ALLOW' end;
    v_rr_type := case when v_rr_decision in ('ADVANCE_REQUIRED', 'REVIEW')
      then coalesce(nullif(v_cfg ->> 'advance_type', ''), 'FIXED')::public.advance_type else 'NONE' end;
    v_amount := case when v_rr_type = 'NONE' then 0 else public.compute_advance_amount(v_rr_type,
      coalesce((v_cfg ->> 'advance_amount')::numeric, 55),
      (v_facts ->> 'order_value')::numeric, (v_facts ->> 'delivery_charge')::numeric, (v_facts ->> 'return_charge')::numeric) end;
    v_matched_rules := v_matched_rules || jsonb_build_object(
      'rule_id', null, 'policy', 'receive_rate', 'tier', v_tier, 'rate', v_facts -> 'receive_rate',
      'name', 'Delivery success ' || initcap(v_tier) || coalesce(' (' || round((v_facts ->> 'receive_rate')::numeric) || '%)', ''),
      'decision', v_rr_decision, 'advance_type', v_rr_type, 'advance_amount', v_amount);
    if public.decision_severity(v_rr_decision) > public.decision_severity(v_decision) then
      v_decision := v_rr_decision;
      v_message := case when v_rr_decision = 'ADVANCE_REQUIRED' then nullif(v_cfg ->> 'message', '') end;
    end if;
    if v_rr_decision in ('ADVANCE_REQUIRED', 'REVIEW') and v_amount > v_advance then
      v_advance := v_amount;
      v_advance_type := v_rr_type;
    end if;
  end if;

  for v_rule in
    select r.id, r.name, r.match_mode, r.conditions, r.priority,
           a.decision, a.advance_type, a.advance_value, a.customer_message, a.stop_processing
    from public.fraud_rules r
    join public.fraud_rule_actions a on a.rule_id = r.id
    where r.is_active
    order by r.priority, r.created_at, a.created_at
  loop
    if jsonb_array_length(v_rule.conditions) = 0 then
      v_matched := true;
    elsif v_rule.match_mode = 'ANY' then
      select bool_or(public.fraud_condition_matches(v_facts, c)) into v_matched from jsonb_array_elements(v_rule.conditions) c;
    else
      select bool_and(public.fraud_condition_matches(v_facts, c)) into v_matched from jsonb_array_elements(v_rule.conditions) c;
    end if;

    if coalesce(v_matched, false) then
      v_amount := public.compute_advance_amount(v_rule.advance_type, v_rule.advance_value,
        (v_facts ->> 'order_value')::numeric, (v_facts ->> 'delivery_charge')::numeric, (v_facts ->> 'return_charge')::numeric);
      v_matched_rules := v_matched_rules || jsonb_build_object(
        'rule_id', v_rule.id, 'name', v_rule.name, 'decision', v_rule.decision,
        'advance_type', v_rule.advance_type, 'advance_amount', v_amount);

      if public.decision_severity(v_rule.decision) > public.decision_severity(v_decision) then
        v_decision := v_rule.decision;
        v_message := v_rule.customer_message;
      end if;
      if v_rule.decision in ('ADVANCE_REQUIRED', 'REVIEW') and v_amount > v_advance then
        v_advance := v_amount;
        v_advance_type := v_rule.advance_type;
      end if;
      exit when v_rule.stop_processing;
    end if;
  end loop;

  -- An advance-required decision without an amount falls back to the default.
  if v_decision = 'ADVANCE_REQUIRED' and v_advance <= 0 then
    v_advance_type := coalesce(public.setting_text('fraud', array['default_advance', 'type'], 'DELIVERY_CHARGE'), 'DELIVERY_CHARGE')::public.advance_type;
    v_advance := public.compute_advance_amount(v_advance_type,
      public.setting_numeric('fraud', array['default_advance', 'value'], 0),
      (v_facts ->> 'order_value')::numeric, (v_facts ->> 'delivery_charge')::numeric, (v_facts ->> 'return_charge')::numeric);
  end if;

  return jsonb_build_object(
    'decision', v_decision,
    'advance_type', case when v_decision in ('ADVANCE_REQUIRED', 'REVIEW') then v_advance_type else 'NONE' end,
    'advance_amount', case when v_decision in ('ADVANCE_REQUIRED', 'REVIEW') then v_advance else 0 end,
    'customer_message', v_message,
    'matched_rules', v_matched_rules,
    'receive_rate_tier', v_facts ->> 'receive_rate_tier'
  );
end;

expire_unpaid_advance_orders.src:
declare
  v_id uuid;
  v_count int := 0;
begin
  if not public.is_system_context() then
    perform public.require_permission('orders.cancel');
  end if;
  for v_id in
    select id from public.orders
    where status = 'ADVANCE_REQUIRED' and advance_due_at < now() and amount_paid < advance_required
      and not exists (select 1 from public.payments p where p.order_id = orders.id and p.status = 'REQUIRES_VERIFICATION')
    order by advance_due_at
    limit 500
  loop
    perform public._transition_order(v_id, 'CANCELLED', 'Advance payment not received in time');
    v_count := v_count + 1;
  end loop;
  return v_count;
end;

finance_account_move.src:
declare
  v_row public.finance_account_movements;
begin
  perform public.require_permission('finance.manage');
  if not exists (select 1 from public.finance_accounts where id = p_account_id) then
    raise exception 'NOT_FOUND: account not found' using errcode = 'P0002';
  end if;
  if coalesce(p_amount, 0) = 0 then
    raise exception 'VALIDATION: enter an amount' using errcode = '22023';
  end if;
  if length(trim(coalesce(p_description, ''))) < 2 then
    raise exception 'VALIDATION: say what the money was for' using errcode = '22023';
  end if;
  insert into public.finance_account_movements(account_id, amount, movement_date, description, source, created_by)
  values (p_account_id, round(p_amount, 2), coalesce(p_date, public._local_date(now())), trim(p_description), 'MANUAL', auth.uid())
  returning * into v_row;
  perform public.log_audit('finance_account.movement', 'finance_account', p_account_id::text, null, to_jsonb(v_row), '{}'::jsonb);
  return v_row;
end;

finance_account_movements_list.src:
begin
  perform public.require_permission('finance.view');
  return jsonb_build_object(
    'total', (select count(*) from public.finance_account_movements where account_id = p_account_id),
    'items', coalesce((select jsonb_agg(r order by r.movement_date desc, r.created_at desc) from (
      select m.id, m.amount, m.movement_date, m.description, m.source, m.spend_date, m.created_at,
             (select coalesce(nullif(full_name, ''), email) from public.profiles where id = m.created_by) as created_by_name,
             (select name from public.meta_ad_accounts where id = m.meta_account_id) as meta_account_name
      from public.finance_account_movements m where m.account_id = p_account_id
      order by m.movement_date desc, m.created_at desc
      limit least(greatest(coalesce(p_limit, 50), 1), 200) offset greatest(coalesce(p_offset, 0), 0)) r), '[]'::jsonb));
end;

finance_account_save.src:
declare
  v_id uuid := nullif(p ->> 'id', '')::uuid;
  v_old public.finance_accounts;
  v_row public.finance_accounts;
begin
  perform public.require_permission('finance.manage');
  if length(trim(coalesce(p ->> 'name', ''))) < 2 then
    raise exception 'VALIDATION: give the account a name' using errcode = '22023';
  end if;
  if exists (select 1 from public.finance_accounts where lower(name) = lower(trim(p ->> 'name')) and id is distinct from v_id) then
    raise exception 'DUPLICATE: there is already an account called %', trim(p ->> 'name') using errcode = '23505';
  end if;
  if v_id is null then
    insert into public.finance_accounts(name, kind, opening_balance, is_active, notes, created_by)
    values (trim(p ->> 'name'), coalesce(nullif(p ->> 'kind', ''), 'BANK'), coalesce((p ->> 'opening_balance')::numeric, 0),
            coalesce((p ->> 'is_active')::boolean, true), nullif(trim(coalesce(p ->> 'notes', '')), ''), auth.uid())
    returning * into v_row;
  else
    select * into v_old from public.finance_accounts where id = v_id;
    if not found then
      raise exception 'NOT_FOUND: account not found' using errcode = 'P0002';
    end if;
    update public.finance_accounts set name = trim(p ->> 'name'), kind = coalesce(nullif(p ->> 'kind', ''), kind),
      opening_balance = coalesce((p ->> 'opening_balance')::numeric, opening_balance),
      is_active = coalesce((p ->> 'is_active')::boolean, is_active),
      notes = case when p ? 'notes' then nullif(trim(coalesce(p ->> 'notes', '')), '') else notes end
    where id = v_id returning * into v_row;
  end if;
  perform public.log_audit(case when v_id is null then 'finance_account.created' else 'finance_account.updated' end,
    'finance_account', v_row.id::text, to_jsonb(v_old), to_jsonb(v_row), '{}'::jsonb);
  return v_row;
end;

finance_accounts_list.src:
declare
  v_full boolean := public.has_permission('finance.view');
begin
  if not v_full and not public.has_permission('marketing.manage') then
    perform public.require_permission('finance.view');
  end if;
  return coalesce((select jsonb_agg(r order by r.is_active desc, r.name) from (
    select a.id, a.name, a.kind, a.is_active, a.notes,
           case when v_full then a.opening_balance end as opening_balance,
           case when v_full then a.opening_balance + coalesce(m.total, 0) end as balance,
           case when v_full then coalesce(m.count, 0) end as movements,
           case when v_full then m.last_at end as last_movement_at,
           (select coalesce(jsonb_agg(jsonb_build_object('id', x.id, 'name', x.name)), '[]'::jsonb)
              from public.meta_ad_accounts x where x.payment_account_id = a.id) as meta_accounts
    from public.finance_accounts a
    left join lateral (select sum(amount) as total, count(*) as count, max(created_at) as last_at
                       from public.finance_account_movements where account_id = a.id) m on true) r), '[]'::jsonb);
end;

finance_categories_guard.src:
begin
  if tg_op = 'DELETE' then
    if public._store_reset_active(old.merchant_id::text) then
      return old;
    end if;
    raise exception 'VALIDATION: finance categories cannot be deleted; deactivate them instead' using errcode = '22023';
  end if;
  if old.is_system and (new.code <> old.code or new.type <> old.type or new.pnl_group <> old.pnl_group
                        or new.is_system <> old.is_system or new.allow_manual <> old.allow_manual) then
    raise exception 'VALIDATION: system category % can only be renamed', old.code using errcode = '22023';
  end if;
  return new;
end;

finance_entries.src:
declare
  v_type text := nullif(upper(p ->> 'type'), '');
  v_cat uuid := nullif(p ->> 'category_id', '')::uuid;
  v_sub text := nullif(p ->> 'sub_category', '');
  v_account uuid := nullif(p ->> 'account_id', '')::uuid;
  v_q text := nullif(trim(coalesce(p ->> 'q', '')), '');
  v_from date := nullif(p ->> 'from', '')::date;
  v_to date := nullif(p ->> 'to', '')::date;
  v_all boolean := coalesce((p ->> 'show_reversed')::boolean, false);
  v_limit int := least(greatest(coalesce((p ->> 'limit')::int, 25), 1), 200);
  v_offset int := greatest(coalesce((p ->> 'offset')::int, 0), 0);
begin
  perform public.require_permission('finance.view');
  return (
    with rows as (
      select t.*, exists (select 1 from public.finance_transactions r where r.reverses_id = t.id) as reversed
      from public.finance_transactions t
      where (v_type is null or t.type::text = v_type)
        and (v_cat is null or t.category_id = v_cat)
        and (v_sub is null or t.sub_category = v_sub)
        and (v_account is null or t.account_id = v_account)
        and (v_from is null or t.txn_date >= v_from)
        and (v_to is null or t.txn_date <= v_to)
        and (v_q is null or t.txn_number ilike '%' || v_q || '%' or t.notes ilike '%' || v_q || '%'
             or t.reference ilike '%' || v_q || '%' or t.sub_category ilike '%' || v_q || '%')
    ), shown as (
      select * from rows where v_all or (reverses_id is null and not reversed)
    )
    select jsonb_build_object(
      'total', (select count(*) from shown),
      'sum', (select coalesce(sum(amount), 0) from shown),
      'items', coalesce((select jsonb_agg(jsonb_build_object(
          'id', s.id, 'txn_number', s.txn_number, 'type', s.type, 'date', s.txn_date, 'amount', s.amount,
          'foreign_amount', s.foreign_amount, 'foreign_currency', s.foreign_currency, 'exchange_rate', s.exchange_rate,
          'category', jsonb_build_object('id', c.id, 'name', c.name, 'code', c.code, 'color', c.color),
          'sub_category', s.sub_category,
          'account', case when a.id is not null then jsonb_build_object('id', a.id, 'name', a.name) end,
          'notes', s.notes, 'reference', s.reference, 'source', s.source,
          'order_number', (select o.order_number from public.orders o where o.id = s.order_id),
          'reversed', s.reversed, 'is_reversal', s.reverses_id is not null,
          'editable', s.source = 'MANUAL' and s.reverses_id is null and not s.reversed,
          'created_by', (select coalesce(nullif(pr.full_name, ''), pr.email) from public.profiles pr where pr.id = s.created_by),
          'created_at', s.created_at) order by s.txn_date desc, s.created_at desc)
        from (select * from shown order by txn_date desc, created_at desc limit v_limit offset v_offset) s
        join public.finance_categories c on c.id = s.category_id
        left join public.finance_accounts a on a.id = s.account_id), '[]'::jsonb)
    ));
end;

finance_entry_update.src:
declare
  v_orig public.finance_transactions;
begin
  perform public.require_permission('finance.manage');
  select * into v_orig from public.finance_transactions where id = p_id;
  if not found then
    raise exception 'NOT_FOUND: entry not found' using errcode = 'P0002';
  end if;
  if v_orig.source <> 'MANUAL' or v_orig.reverses_id is not null then
    raise exception 'VALIDATION: only entries added by hand can be edited' using errcode = '22023';
  end if;
  perform public.reverse_finance_transaction(p_id, coalesce(nullif(trim(p_reason), ''), 'Edited'));
  return public.create_finance_transaction(jsonb_build_object('type', v_orig.type) || p);
end;

finance_rebuild_cost.src:
declare
  v_rows jsonb;
  v_items int;
  v_orders int;
  v_amount numeric;
  v_unknown int;
  v_posted int := 0;
  v_txn public.finance_transactions;
  r record;
begin
  perform public.require_permission(case when p_apply then 'finance.manage' else 'finance.view' end);
  perform public._fin_check_args(p_from, p_to, 'delivered');

  if to_regclass('pg_temp._rebuild') is null then
    create temporary table _rebuild (item_id uuid, order_id uuid, order_number text, product text, quantity int,
      new_cost numeric, amount numeric, day date) on commit drop;
  else
    truncate _rebuild;
  end if;
  insert into _rebuild
  select oi.id, o.id, o.order_number, oi.product_name || coalesce(' - ' || nullif(oi.variant_title, 'Default Title'), ''), oi.quantity,
         public.variant_cost(oi.variant_id), public.money(public.variant_cost(oi.variant_id) * oi.quantity),
         (o.delivered_at at time zone public.store_timezone())::date
  from public.order_items oi join public.orders o on o.id = oi.order_id
  where o.status in ('DELIVERED', 'PARTIALLY_DELIVERED') and o.delivered_at is not null
    and (o.delivered_at at time zone public.store_timezone())::date between p_from and p_to
    and oi.quantity > 0 and coalesce(oi.unit_cost, 0) = 0
    and oi.variant_id is not null and public.variant_cost(oi.variant_id) > 0
    and exists (select 1 from public.finance_transactions ft where ft.source_key = 'order:' || o.id || ':product_revenue');

  select count(*), count(distinct order_id), coalesce(sum(amount), 0) into v_items, v_orders, v_amount from _rebuild;
  select count(*) into v_unknown
  from public.order_items oi join public.orders o on o.id = oi.order_id
  where o.status in ('DELIVERED', 'PARTIALLY_DELIVERED') and o.delivered_at is not null
    and (o.delivered_at at time zone public.store_timezone())::date between p_from and p_to
    and oi.quantity > 0 and coalesce(oi.unit_cost, 0) = 0
    and (oi.variant_id is null or public.variant_cost(oi.variant_id) = 0)
    and exists (select 1 from public.finance_transactions ft where ft.source_key = 'order:' || o.id || ':product_revenue');

  select coalesce(jsonb_agg(jsonb_build_object('order_id', order_id, 'order_number', order_number, 'product', product, 'quantity', quantity,
      'unit_cost', new_cost, 'amount', amount, 'day', day) order by day, order_number), '[]'::jsonb)
  into v_rows from (select * from _rebuild order by day, order_number limit 100) x;

  if p_apply then
    for r in
      select rb.*, o.customer_id from _rebuild rb join public.orders o on o.id = rb.order_id
      join public.order_items oi on oi.id = rb.item_id
      order by rb.day
      for update of oi
    loop
      -- Still missing? (another run may have filled it meanwhile)
      continue when (select coalesce(unit_cost, 0) from public.order_items where id = r.item_id) <> 0;
      update public.order_items set unit_cost = r.new_cost where id = r.item_id;
      v_txn := public._post_finance('EXPENSE', 'COGS', r.amount, r.day, false, r.order_id, r.customer_id, null, r.order_number,
        'Product cost added later (was missing at delivery)', 'order_item:' || r.item_id || ':cost_rebuild', null);
      if v_txn.id is not null then
        v_posted := v_posted + 1;
      end if;
    end loop;
    update public.orders o set cost_total = public.money((select coalesce(sum(unit_cost * quantity), 0) from public.order_items where order_id = o.id))
    where o.id in (select order_id from _rebuild);
    perform public.log_audit('finance.rebuild_cost', 'finance', null, null,
      jsonb_build_object('from', p_from, 'to', p_to, 'items', v_items, 'orders', v_orders, 'amount', v_amount, 'posted', v_posted));
  end if;

  return jsonb_build_object('applied', p_apply, 'items', v_items, 'orders', v_orders, 'amount', v_amount, 'posted', v_posted,
    'unknown_items', v_unknown, 'rows', v_rows);
end;

finance_recalculate_orders.src:
declare
  v_before int;
  v_after int;
  v_orders int := 0;
  r record;
begin
  perform public.require_permission('finance.manage');
  perform public._fin_check_args(p_from, p_to, 'delivered');
  select count(*) into v_before from public.finance_transactions;
  for r in
    select o.id from public.orders o
    where o.status in ('DELIVERED', 'PARTIALLY_DELIVERED') and o.delivered_at is not null
      and (o.delivered_at at time zone public.store_timezone())::date between p_from and p_to
      and not exists (select 1 from public.finance_transactions ft where ft.source_key = 'order:' || o.id || ':product_revenue')
    order by o.delivered_at
    for update of o
  loop
    perform public._post_order_delivery_finance(r.id);
    v_orders := v_orders + 1;
  end loop;
  select count(*) into v_after from public.finance_transactions;
  perform public.log_audit('finance.recalculate_orders', 'finance', null, null,
    jsonb_build_object('from', p_from, 'to', p_to, 'orders', v_orders, 'entries', v_after - v_before));
  return jsonb_build_object('orders', v_orders, 'entries', v_after - v_before);
end;

find_gateway_payment.src:
declare
  v_payment public.payments;
begin
  if not public.is_system_context() then
    raise exception 'PERMISSION_DENIED' using errcode = '42501';
  end if;
  select * into v_payment from public.payments
  where provider = p_provider
    and (metadata @> jsonb_build_object('sessions', jsonb_build_array(p_session)) or reference = p_session)
  order by created_at desc limit 1;
  return v_payment;
end;

for_each_merchant.src:
declare
  m record;
  v_runs int := 0;
  v_failed int := 0;
begin
  if not public.is_system_context() then
    raise exception 'PERMISSION_DENIED' using errcode = '42501';
  end if;
  if p_job not in ('retry_courier_webhooks', 'expire_unpaid_advance_orders', 'pbx_sweep') then
    raise exception 'VALIDATION: unknown job %', p_job using errcode = '22023';
  end if;
  for m in select id from public.merchants where status <> 'CLOSED' order by number loop
    perform set_config('app.merchant_id', m.id::text, true);
    v_runs := v_runs + 1;
    -- One merchant's failure is logged for that merchant and does not stop the others.
    begin
      execute format('select public.%I()', p_job);
    exception when others then
      v_failed := v_failed + 1;
      perform public._log_system_event('ERROR', 'JOB', p_job, sqlerrm,
        jsonb_build_object('merchant_id', m.id, 'sqlstate', sqlstate));
    end;
  end loop;
  perform set_config('app.merchant_id', '', true);
  return jsonb_build_object('job', p_job, 'merchants', v_runs, 'failed', v_failed);
end;

fraud_checks_guard.src:
begin
  if tg_op = 'DELETE' and public._store_reset_active(old.merchant_id::text) then
    return old;
  end if;
  if tg_op = 'DELETE' then
    raise exception 'IMMUTABLE_RECORD: fraud checks cannot be deleted' using errcode = 'P0001';
  end if;
  if public._erasure_active(new.merchant_id) then
    return new;
  end if;
  if old.order_id is null and new.order_id is not null
     and (to_jsonb(new) - 'order_id' - 'customer_id') = (to_jsonb(old) - 'order_id' - 'customer_id') then
    return new;
  end if;
  raise exception 'IMMUTABLE_RECORD: fraud checks cannot be modified' using errcode = 'P0001';
end;

fraud_condition_matches.src:
declare
  v_fact jsonb := p_facts -> (p_condition ->> 'field');
  v_op text := lower(coalesce(p_condition ->> 'op', 'eq'));
  v_val jsonb := p_condition -> 'value';
  v_num numeric;
  v_cmp numeric;
begin
  if v_fact is null or jsonb_typeof(v_fact) = 'null' then
    return false;
  end if;

  if v_op in ('is_true', 'is_false') then
    return (v_fact::text = 'true') = (v_op = 'is_true');
  end if;

  if v_op in ('in', 'not_in') then
    if jsonb_typeof(v_val) <> 'array' then
      return false;
    end if;
    return (exists (select 1 from jsonb_array_elements_text(v_val) x
                    where lower(trim(x)) = lower(trim(v_fact #>> '{}')))) = (v_op = 'in');
  end if;

  if jsonb_typeof(v_fact) = 'number' or (v_fact #>> '{}') ~ '^-?[0-9]+(\.[0-9]+)?$' then
    v_num := (v_fact #>> '{}')::numeric;
    begin
      v_cmp := (v_val #>> '{}')::numeric;
    exception when others then
      v_cmp := null;
    end;
  end if;

  if v_num is not null and v_cmp is not null then
    return case v_op
      when 'eq' then v_num = v_cmp
      when 'neq' then v_num <> v_cmp
      when 'gt' then v_num > v_cmp
      when 'gte' then v_num >= v_cmp
      when 'lt' then v_num < v_cmp
      when 'lte' then v_num <= v_cmp
      else false end;
  end if;

  return case v_op
    when 'eq' then lower(v_fact #>> '{}') = lower(v_val #>> '{}')
    when 'neq' then lower(v_fact #>> '{}') <> lower(v_val #>> '{}')
    else false end;
end;

fraud_review_decide.src:
declare
  v_order public.orders;
  v_action text := upper(coalesce(p_action, ''));
  v_amount numeric;
begin
  perform public.require_permission('fraud.review');
  select * into v_order from public.orders where id = p_order_id for update;
  if not found then
    raise exception 'NOT_FOUND: order not found' using errcode = 'P0002';
  end if;
  if v_order.status not in ('PENDING', 'FRAUD_CHECK', 'FRAUD_REVIEW', 'ADVANCE_REQUIRED', 'CONFIRMATION_REQUIRED', 'REJECTED_FRAUD') then
    raise exception 'VALIDATION: % orders are not in fraud review', v_order.status using errcode = '22023';
  end if;

  if v_action = 'APPROVE' then
    insert into public.fraud_reviews(order_id, fraud_check_id, action, decision, advance_amount, note, decided_by, decided_by_name)
    values (p_order_id, v_order.fraud_check_id, 'APPROVE', 'ALLOW', 0, p_note, auth.uid(), public.actor_display_name());
    update public.orders set fraud_status = 'APPROVED', fraud_decision = 'ALLOW',
      advance_required = least(advance_required, amount_paid)
    where id = p_order_id;
    if v_order.status = 'REJECTED_FRAUD' then
      perform public._transition_order(p_order_id, 'FRAUD_REVIEW', 'Reopened for review');
    end if;
    if v_order.status = 'PENDING' then
      perform public._transition_order(p_order_id, 'FRAUD_CHECK', 'Manual review');
    end if;
    v_order := public._transition_order(p_order_id, 'CONFIRMED', coalesce(p_note, 'Approved after fraud review'));

  elsif v_action = 'REQUEST_ADVANCE' then
    v_amount := ceil(coalesce(p_advance_amount, 0));
    if v_amount <= 0 or v_amount > v_order.total_amount then
      raise exception 'VALIDATION: advance must be between 1 and the order total (%)', v_order.total_amount using errcode = '22023';
    end if;
    insert into public.fraud_reviews(order_id, fraud_check_id, action, decision, advance_amount, note, decided_by, decided_by_name)
    values (p_order_id, v_order.fraud_check_id, 'REQUEST_ADVANCE', 'ADVANCE_REQUIRED', v_amount, p_note, auth.uid(), public.actor_display_name());
    update public.orders set fraud_status = 'ADVANCE_REQUIRED', fraud_decision = 'ADVANCE_REQUIRED',
      advance_required = v_amount, advance_type = case when v_amount >= total_amount then 'FULL' else 'FIXED' end::public.advance_type
    where id = p_order_id;
    if v_order.status = 'REJECTED_FRAUD' then
      perform public._transition_order(p_order_id, 'FRAUD_REVIEW', 'Reopened for review');
    elsif v_order.status = 'PENDING' then
      perform public._transition_order(p_order_id, 'FRAUD_CHECK', 'Manual review');
    end if;
    if v_order.status = 'ADVANCE_REQUIRED' then
      update public.orders set advance_due_at = now() + make_interval(
        hours => public.setting_numeric('orders', array['advance_payment_timeout_hours'], 24)::int)
      where id = p_order_id;
      perform public._order_log(p_order_id, 'ADVANCE_UPDATED', format('Advance changed to %s', v_amount), null, null,
        jsonb_build_object('advance_required', v_amount), true);
      perform public._enqueue_order_notification(p_order_id, 'ADVANCE_REQUIRED');
    elsif v_order.amount_paid >= v_amount then
      perform public._transition_order(p_order_id, 'CONFIRMED', 'Advance already paid');
    else
      perform public._transition_order(p_order_id, 'ADVANCE_REQUIRED', coalesce(p_note, format('Advance of %s requested', v_amount)));
    end if;

  elsif v_action = 'REJECT' then
    insert into public.fraud_reviews(order_id, fraud_check_id, action, decision, advance_amount, note, decided_by, decided_by_name)
    values (p_order_id, v_order.fraud_check_id, 'REJECT', 'BLOCK', 0, p_note, auth.uid(), public.actor_display_name());
    update public.orders set fraud_status = 'REJECTED', fraud_decision = 'BLOCK' where id = p_order_id;
    if v_order.status = 'PENDING' then
      perform public._transition_order(p_order_id, 'FRAUD_CHECK', 'Manual review');
    end if;
    if v_order.status <> 'REJECTED_FRAUD' then
      perform public._transition_order(p_order_id, 'REJECTED_FRAUD', coalesce(p_note, 'Rejected after fraud review'));
    end if;
    if p_block_customer then
      update public.customers set status = 'BLOCKED', blocked_reason = coalesce(p_note, 'Rejected in fraud review')
      where id = v_order.customer_id;
      perform public.refresh_customer_stats(v_order.customer_id);
    end if;
  else
    raise exception 'VALIDATION: action must be APPROVE, REQUEST_ADVANCE or REJECT' using errcode = '22023';
  end if;

  perform public.log_audit('fraud.review_' || lower(v_action), 'order', p_order_id::text,
    jsonb_build_object('status', v_order.status, 'advance_required', v_order.advance_required),
    jsonb_build_object('advance_required', v_amount, 'block_customer', p_block_customer),
    jsonb_build_object('note', p_note));
  select * into v_order from public.orders where id = p_order_id;
  return v_order;
end;

fraud_set_provider.src:
declare
  v_value jsonb;
begin
  if not public.is_system_context() then
    raise exception 'PERMISSION_DENIED' using errcode = '42501';
  end if;
  if p_provider !~ '^[a-z_]{2,40}$' then
    raise exception 'VALIDATION: unknown provider' using errcode = '22023';
  end if;
  update public.settings set value = jsonb_set(value, '{providers}', (
    select coalesce(jsonb_agg(distinct p order by p), '[]'::jsonb)
    from (
      select jsonb_array_elements_text(coalesce(value -> 'providers', '["internal"]'::jsonb)) as p
      union all
      select p_provider where p_enabled
    ) s
    where p_enabled or s.p <> p_provider
  ))
  where key = 'fraud'
  returning value into v_value;
  return v_value -> 'providers';
end;

gateway_payments_to_reconcile.src:
begin
  if not public.is_system_context() then
    raise exception 'PERMISSION_DENIED' using errcode = '42501';
  end if;
  return query
    select p.id, p.provider, p.reference, coalesce(p.metadata -> 'sessions', '[]'::jsonb),
           (extract(epoch from now() - p.created_at) / 60)::int
    from public.payments p
    where p.status = 'PENDING' and p.provider in ('bkash', 'paystation')
      and p.created_at < now() - interval '3 minutes' and p.created_at > now() - interval '3 days'
    order by p.created_at
    limit least(greatest(p_limit, 1), 200);
end;

gateway_token_get.src:
declare
  v_merchant uuid := public.current_merchant_id();
  v_value text;
begin
  if not public.is_system_context() then
    raise exception 'PERMISSION_DENIED' using errcode = '42501';
  end if;
  select decrypted_secret into v_value from vault.decrypted_secrets
  where name = 'gateway-token:' || coalesce(v_merchant::text || ':', 'platform:') || p_key;
  return nullif(v_value, '')::jsonb;
end;

gateway_token_put.src:
declare
  v_merchant uuid := public.current_merchant_id();
  v_name text;
  v_secret uuid;
begin
  if not public.is_system_context() then
    raise exception 'PERMISSION_DENIED' using errcode = '42501';
  end if;
  if p_key !~ '^[a-z0-9_]{2,40}$' or jsonb_typeof(p_value) <> 'object' then
    raise exception 'VALIDATION: bad gateway token' using errcode = '22023';
  end if;
  v_name := 'gateway-token:' || coalesce(v_merchant::text || ':', 'platform:') || p_key;
  select id into v_secret from vault.secrets where name = v_name;
  if v_secret is null then
    perform vault.create_secret(p_value::text, v_name, 'Payment gateway access token (expires on its own)');
  else
    perform vault.update_secret(v_secret, p_value::text);
  end if;
end;

get_my_access.src:
declare
  v_p public.profiles;
  v_r public.roles;
  v_ok boolean;
  v_required boolean := coalesce((select (value ->> 'enabled')::boolean from public.settings where key = 'device_approval'), false);
  v_device public.staff_devices;
  v_support jsonb := public._platform_support_session_info();
begin
  if v_support is not null then
    return jsonb_build_object(
      'user_id', auth.uid(),
      'merchant_id', (v_support ->> 'merchant_id')::uuid,
      'access_mode', public.merchant_access_mode((v_support ->> 'merchant_id')::uuid),
      'merchant', (select jsonb_build_object('id', m.id, 'number', m.number, 'name', m.name, 'status', m.status)
                   from public.merchants m where m.id = (v_support ->> 'merchant_id')::uuid),
      'email', v_support ->> 'email',
      'full_name', v_support ->> 'full_name',
      'role', 'SUPPORT_VIEW',
      'role_name', 'Platform support (view only)',
      'device_blocked', false,
      'device', jsonb_build_object('required', false, 'id', null, 'status', null),
      'idle_logout_minutes', 0,
      'pbx_click_to_call', false,
      'support_session', v_support - 'email' - 'full_name' - 'merchant_id',
      'permissions', (select coalesce(jsonb_agg(code order by code), '[]'::jsonb) from public.permissions where code like '%.view'));
  end if;
  select * into v_p from public.profiles where id = auth.uid() and is_active;
  if v_p.id is null then
    return null;
  end if;
  select * into v_r from public.roles where id = v_p.role_id;
  v_ok := public._device_ok(v_p.id, v_r.code);
  select d.* into v_device from public.staff_device_sessions ds join public.staff_devices d on d.id = ds.device_id
  where ds.session_id = public._jwt_session() and d.profile_id = v_p.id;
  return jsonb_build_object(
    'user_id', v_p.id,
    'merchant_id', v_p.merchant_id,
    'access_mode', public.merchant_access_mode(v_p.merchant_id),
    'merchant', (select jsonb_build_object('id', m.id, 'number', m.number, 'name', m.name, 'status', m.status)
                 from public.merchants m where m.id = v_p.merchant_id),
    'email', v_p.email,
    'full_name', v_p.full_name,
    'role', v_r.code,
    'role_name', v_r.name,
    'device_blocked', not v_ok,
    'device', jsonb_build_object('required', v_required and v_r.code <> 'OWNER', 'id', v_device.id, 'status', v_device.status),
    'idle_logout_minutes', coalesce((select (value ->> 'idle_logout_minutes')::int from public.settings where key = 'advanced'), 0),
    -- Click-to-call through the PBX: on, in API mode, and this staff member has an extension.
    'pbx_click_to_call', coalesce((select (value ->> 'enabled')::boolean and value ->> 'click_mode' = 'api'
        and exists (select 1 from jsonb_array_elements(coalesce(value -> 'extensions', '[]'::jsonb)) e where e ->> 'profile_id' = v_p.id::text)
      from public.settings where key = 'pbx'), false),
    'permissions', case
      when not v_ok then '[]'::jsonb
      when v_r.code = 'OWNER' then (select coalesce(jsonb_agg(code order by code), '[]'::jsonb) from public.permissions)
      else (select coalesce(jsonb_agg(pm.code order by pm.code), '[]'::jsonb)
            from public.role_permissions rp join public.permissions pm on pm.id = rp.permission_id
            where rp.role_id = v_r.id)
    end);
end;

grant_owner.src:
declare
  v_user_id uuid;
begin
  if not public.is_system_context() then
    raise exception 'PERMISSION_DENIED: grant_owner can only be run from the SQL editor or service role'
      using errcode = '42501';
  end if;
  v_user_id := public.find_auth_user_id(p_email);
  if v_user_id is null then
    raise exception 'NOT_FOUND: no auth user with email %', p_email using errcode = 'P0002';
  end if;
  return public.admin_set_user_role(v_user_id, 'OWNER', true);
end;

hr_attendance_set.src:
declare
  v_shift public.hr_shifts := public._hr_shift_of(p_profile);
  v_score record;
  v_row public.hr_attendance;
  v_status public.hr_attendance_status := p_status;
begin
  perform public.require_permission('hr.manage');
  if not exists (select 1 from public.profiles where id = p_profile) then
    raise exception 'NOT_FOUND: staff member not found' using errcode = 'P0002';
  end if;
  if p_date > public._hr_today() then
    raise exception 'VALIDATION: attendance cannot be set for a future day' using errcode = '22023';
  end if;
  if p_check_out is not null and p_check_in is not null and p_check_out < p_check_in then
    raise exception 'VALIDATION: check-out is before check-in' using errcode = '22023';
  end if;
  if p_status in ('PRESENT', 'LATE', 'HALF_DAY') and p_check_in is null then
    raise exception 'VALIDATION: add the check-in time' using errcode = '22023';
  end if;
  select * into v_score from public._hr_score(v_shift, p_date, p_check_in, p_check_out);
  -- Times decide present / late / half day; ABSENT, LEAVE and HOLIDAY are taken as chosen.
  if p_status in ('PRESENT', 'LATE', 'HALF_DAY') then
    v_status := v_score.status;
  end if;
  insert into public.hr_attendance(profile_id, work_date, check_in_at, check_out_at, status, late_minutes, worked_minutes, note, source, updated_by)
  values (p_profile, p_date, case when v_status in ('ABSENT', 'LEAVE', 'HOLIDAY') then null else p_check_in end,
    case when v_status in ('ABSENT', 'LEAVE', 'HOLIDAY') then null else p_check_out end, v_status,
    case when v_status in ('ABSENT', 'LEAVE', 'HOLIDAY') then 0 else v_score.late_minutes end,
    case when v_status in ('ABSENT', 'LEAVE', 'HOLIDAY') then null else v_score.worked_minutes end,
    nullif(trim(coalesce(p_note, '')), ''), 'ADMIN', auth.uid())
  on conflict (profile_id, work_date) do update set
    check_in_at = excluded.check_in_at, check_out_at = excluded.check_out_at, status = excluded.status,
    late_minutes = excluded.late_minutes, worked_minutes = excluded.worked_minutes, note = excluded.note,
    source = 'ADMIN', updated_by = auth.uid()
  returning * into v_row;
  perform public.log_audit('hr.attendance_set', 'hr_attendance', v_row.id::text, null,
    jsonb_build_object('profile_id', p_profile, 'date', p_date, 'status', v_status, 'check_in', p_check_in, 'check_out', p_check_out));
  return v_row;
end;

hr_check_in.src:
declare
  v_shift public.hr_shifts := public._hr_shift_of(auth.uid());
  v_today date := public._hr_today();
  v_row public.hr_attendance;
  v_score record;
begin
  if not public.is_staff() then
    raise exception 'PERMISSION_DENIED: staff only' using errcode = '42501';
  end if;
  if not coalesce((public.get_setting('hr') ->> 'allow_self_check_in')::boolean, true) then
    raise exception 'VALIDATION: check-in is done by HR in this store' using errcode = '22023';
  end if;
  select * into v_row from public.hr_attendance where profile_id = auth.uid() and work_date = v_today for update;
  if v_row.check_in_at is not null then
    raise exception 'VALIDATION: you already checked in at %', to_char(v_row.check_in_at at time zone public.store_timezone(), 'HH12:MI AM')
      using errcode = '22023';
  end if;
  select * into v_score from public._hr_score(v_shift, v_today, now(), null);
  insert into public.hr_attendance(profile_id, work_date, check_in_at, status, late_minutes, note, source, updated_by)
  values (auth.uid(), v_today, now(), v_score.status, v_score.late_minutes, nullif(trim(coalesce(p_note, '')), ''), 'SELF', auth.uid())
  on conflict (profile_id, work_date) do update
    set check_in_at = excluded.check_in_at, status = excluded.status, late_minutes = excluded.late_minutes,
        note = coalesce(excluded.note, public.hr_attendance.note), source = 'SELF', updated_by = auth.uid()
  returning * into v_row;
  return v_row;
end;

hr_check_out.src:
declare
  v_shift public.hr_shifts := public._hr_shift_of(auth.uid());
  v_row public.hr_attendance;
  v_score record;
begin
  if not public.is_staff() then
    raise exception 'PERMISSION_DENIED: staff only' using errcode = '42501';
  end if;
  -- Today, or an overnight shift that started yesterday and is still open.
  select * into v_row from public.hr_attendance
  where profile_id = auth.uid() and check_in_at is not null and check_out_at is null
    and work_date >= public._hr_today() - 1
  order by work_date desc limit 1 for update;
  if v_row.id is null then
    raise exception 'VALIDATION: check in first' using errcode = '22023';
  end if;
  select * into v_score from public._hr_score(v_shift, v_row.work_date, v_row.check_in_at, now());
  update public.hr_attendance set check_out_at = now(), status = v_score.status, late_minutes = v_score.late_minutes,
    worked_minutes = v_score.worked_minutes, note = coalesce(nullif(trim(coalesce(p_note, '')), ''), note), updated_by = auth.uid()
  where id = v_row.id returning * into v_row;
  return v_row;
end;

hr_department_save.src:
declare
  v_row public.hr_departments;
  v_id uuid := nullif(p ->> 'id', '')::uuid;
begin
  perform public.require_permission('hr.manage');
  if v_id is null then
    insert into public.hr_departments(name, description, color, head_id, is_active)
    values (trim(p ->> 'name'), nullif(trim(coalesce(p ->> 'description', '')), ''), coalesce(nullif(p ->> 'color', ''), '#64748b'),
      nullif(p ->> 'head_id', '')::uuid, coalesce((p ->> 'is_active')::boolean, true))
    returning * into v_row;
  else
    update public.hr_departments set
      name = coalesce(trim(p ->> 'name'), name),
      description = case when p ? 'description' then nullif(trim(coalesce(p ->> 'description', '')), '') else description end,
      color = coalesce(nullif(p ->> 'color', ''), color),
      head_id = case when p ? 'head_id' then nullif(p ->> 'head_id', '')::uuid else head_id end,
      is_active = coalesce((p ->> 'is_active')::boolean, is_active)
    where id = v_id returning * into v_row;
    if v_row.id is null then raise exception 'NOT_FOUND: department not found' using errcode = 'P0002'; end if;
  end if;
  return v_row;
end;

hr_employee_save.src:
declare
  v_row public.hr_employees;
begin
  perform public.require_permission('hr.manage');
  if not exists (select 1 from public.profiles where id = p_profile) then
    raise exception 'NOT_FOUND: staff member not found' using errcode = 'P0002';
  end if;
  insert into public.hr_employees(profile_id) values (p_profile) on conflict (profile_id) do nothing;
  update public.hr_employees set
    department_id = case when p ? 'department_id' then nullif(p ->> 'department_id', '')::uuid else department_id end,
    shift_id = case when p ? 'shift_id' then nullif(p ->> 'shift_id', '')::uuid else shift_id end,
    designation = case when p ? 'designation' then nullif(trim(coalesce(p ->> 'designation', '')), '') else designation end,
    employee_code = case when p ? 'employee_code' then nullif(trim(coalesce(p ->> 'employee_code', '')), '') else employee_code end,
    joined_on = case when p ? 'joined_on' then nullif(p ->> 'joined_on', '')::date else joined_on end,
    emergency_contact = case when p ? 'emergency_contact' then nullif(trim(coalesce(p ->> 'emergency_contact', '')), '') else emergency_contact end
  where profile_id = p_profile returning * into v_row;
  return v_row;
end;

hr_holiday_save.src:
declare
  v_row public.hr_holidays;
begin
  perform public.require_permission('hr.manage');
  insert into public.hr_holidays(holiday_date, name, is_active) values (p_date, trim(p_name), coalesce(p_active, true))
  on conflict (merchant_id, holiday_date) do update set name = excluded.name, is_active = excluded.is_active
  returning * into v_row;
  return v_row;
end;

hr_my_day.src:
declare
  v_shift public.hr_shifts := public._hr_shift_of(auth.uid());
  v_row public.hr_attendance;
  v_today date := public._hr_today();
begin
  if not public.is_staff() then
    raise exception 'PERMISSION_DENIED: staff only' using errcode = '42501';
  end if;
  select * into v_row from public.hr_attendance where profile_id = auth.uid() and work_date = v_today;
  return jsonb_build_object(
    'date', v_today,
    'tz', public.store_timezone(),
    'record', case when v_row.id is null then null else to_jsonb(v_row) end,
    'shift', case when v_shift.id is null then null else jsonb_build_object('id', v_shift.id, 'name', v_shift.name,
      'start_time', v_shift.start_time, 'end_time', v_shift.end_time, 'grace_minutes', v_shift.grace_minutes) end,
    'work_day', public._hr_is_work_day(v_shift, v_today),
    'self_check_in', coalesce((public.get_setting('hr') ->> 'allow_self_check_in')::boolean, true));
end;

hr_settings_save.src:
declare
  v jsonb := coalesce(public.get_setting('hr'), '{}'::jsonb);
begin
  perform public.require_permission('hr.manage');
  if p ? 'work_days' then
    if jsonb_typeof(p -> 'work_days') <> 'array' or jsonb_array_length(p -> 'work_days') = 0
       or exists (select 1 from jsonb_array_elements_text(p -> 'work_days') x where x !~ '^[0-6]$') then
      raise exception 'VALIDATION: choose at least one work day' using errcode = '22023';
    end if;
    v := v || jsonb_build_object('work_days', p -> 'work_days');
  end if;
  if p ? 'half_day_minutes' then
    v := v || jsonb_build_object('half_day_minutes', least(greatest((p ->> 'half_day_minutes')::int, 30), 720));
  end if;
  if p ? 'allow_self_check_in' then
    v := v || jsonb_build_object('allow_self_check_in', (p ->> 'allow_self_check_in')::boolean);
  end if;
  update public.settings set value = v where key = 'hr';
  perform public.log_audit('hr.settings', 'settings', 'hr', null, v);
  return v;
end;

hr_shift_save.src:
declare
  v_row public.hr_shifts;
  v_id uuid := nullif(p ->> 'id', '')::uuid;
  v_days int[] := case when p ? 'work_days' then (select coalesce(array_agg(x::int order by x::int), '{}') from jsonb_array_elements_text(p -> 'work_days') x) end;
begin
  perform public.require_permission('hr.manage');
  if v_days is not null and cardinality(v_days) = 0 then
    raise exception 'VALIDATION: choose at least one work day' using errcode = '22023';
  end if;
  if v_id is null then
    insert into public.hr_shifts(name, start_time, end_time, grace_minutes, work_days, color, is_active)
    values (trim(p ->> 'name'), (p ->> 'start_time')::time, (p ->> 'end_time')::time, coalesce((p ->> 'grace_minutes')::int, 10),
      coalesce(v_days, '{0,1,2,3,4,6}'), coalesce(nullif(p ->> 'color', ''), '#0ea5e9'), coalesce((p ->> 'is_active')::boolean, true))
    returning * into v_row;
  else
    update public.hr_shifts set
      name = coalesce(trim(p ->> 'name'), name),
      start_time = coalesce((p ->> 'start_time')::time, start_time),
      end_time = coalesce((p ->> 'end_time')::time, end_time),
      grace_minutes = coalesce((p ->> 'grace_minutes')::int, grace_minutes),
      work_days = coalesce(v_days, work_days),
      color = coalesce(nullif(p ->> 'color', ''), color),
      is_active = coalesce((p ->> 'is_active')::boolean, is_active)
    where id = v_id returning * into v_row;
    if v_row.id is null then raise exception 'NOT_FOUND: shift not found' using errcode = 'P0002'; end if;
  end if;
  return v_row;
end;

hr_sop_save.src:
declare
  v_row public.hr_sops;
  v_id uuid := nullif(p ->> 'id', '')::uuid;
begin
  perform public.require_permission('hr.manage');
  if v_id is null then
    insert into public.hr_sops(department_id, title, body, is_active, updated_by)
    values (nullif(p ->> 'department_id', '')::uuid, trim(p ->> 'title'), coalesce(p ->> 'body', ''), coalesce((p ->> 'is_active')::boolean, true), auth.uid())
    returning * into v_row;
  else
    update public.hr_sops set
      department_id = case when p ? 'department_id' then nullif(p ->> 'department_id', '')::uuid else department_id end,
      title = coalesce(trim(p ->> 'title'), title),
      body = coalesce(p ->> 'body', body),
      version = version + case when coalesce(p ->> 'body', body) is distinct from body or coalesce(trim(p ->> 'title'), title) is distinct from title then 1 else 0 end,
      is_active = coalesce((p ->> 'is_active')::boolean, is_active),
      updated_by = auth.uid()
    where id = v_id returning * into v_row;
    if v_row.id is null then raise exception 'NOT_FOUND: SOP not found' using errcode = 'P0002'; end if;
  end if;
  return v_row;
end;

import_courier_invoice.src:
declare
  v_courier public.couriers;
  v_inv public.courier_invoices;
  v_line jsonb;
  v_no int := 0;
  v_ship public.shipments;
  v_order public.orders;
  v_issues text[];
  v_match text;
  v_dup text;
  v_consignment text;
  v_ref text;
  v_cod numeric; v_del numeric; v_ret numeric; v_codfee numeric; v_other numeric; v_payout numeric;
  v_exp_cod numeric; v_exp_del numeric; v_exp_ret numeric; v_exp_codfee numeric;
  v_pct numeric;
  v_seen uuid[] := '{}';
  v_all_payout boolean := true;
  t_cod numeric := 0; t_del numeric := 0; t_ret numeric := 0; t_codfee numeric := 0; t_other numeric := 0; t_payout numeric := 0;
  e_cod numeric := 0; e_del numeric := 0; e_ret numeric := 0; e_codfee numeric := 0; e_payout numeric := 0;
  n_match int := 0; n_mis int := 0; n_un int := 0; n_dup int := 0;
  v_reported numeric;
  v_number text := nullif(trim(p ->> 'invoice_number'), '');
begin
  perform public.require_permission('couriers.manage');
  select * into v_courier from public.couriers where id = (p ->> 'courier_id')::uuid;
  if not found then
    raise exception 'NOT_FOUND: courier not found' using errcode = 'P0002';
  end if;
  if jsonb_typeof(p -> 'lines') is distinct from 'array' or jsonb_array_length(p -> 'lines') = 0 then
    raise exception 'VALIDATION: the statement has no lines' using errcode = '22023';
  end if;
  if jsonb_array_length(p -> 'lines') > 5000 then
    raise exception 'VALIDATION: at most 5,000 lines per statement' using errcode = '22023';
  end if;
  if v_number is not null and exists (select 1 from public.courier_invoices
      where courier_id = v_courier.id and lower(invoice_number) = lower(v_number)) then
    raise exception 'DUPLICATE: statement % from % was already uploaded', v_number, v_courier.name using errcode = '23505';
  end if;
  v_pct := (v_courier.config ->> 'cod_fee_percent')::numeric;

  insert into public.courier_invoices(courier_id, invoice_number, invoice_date, period_start, period_end, file_path, file_name, notes)
  values (v_courier.id, v_number, nullif(p ->> 'invoice_date', '')::date, nullif(p ->> 'period_start', '')::date,
          nullif(p ->> 'period_end', '')::date, nullif(p ->> 'file_path', ''), left(nullif(p ->> 'file_name', ''), 200),
          nullif(trim(p ->> 'notes'), ''))
  returning * into v_inv;

  for v_line in select value from jsonb_array_elements(p -> 'lines') loop
    v_no := v_no + 1;
    v_issues := '{}';
    v_match := null;
    v_dup := null;
    v_ship := null;
    v_order := null;
    v_exp_cod := null; v_exp_del := null; v_exp_ret := null; v_exp_codfee := null;
    v_consignment := nullif(trim(v_line ->> 'consignment_id'), '');
    v_ref := nullif(trim(v_line ->> 'order_ref'), '');
    v_cod := public._jnum(v_line, 'cod_collected', v_no);
    v_del := public._jnum(v_line, 'delivery_fee', v_no);
    v_ret := public._jnum(v_line, 'return_fee', v_no);
    v_codfee := public._jnum(v_line, 'cod_fee', v_no);
    v_other := public._jnum(v_line, 'other_fee', v_no);
    v_payout := public._jnum(v_line, 'payout', v_no);
    if v_consignment is null and v_ref is null then
      raise exception 'VALIDATION: line % has no consignment ID or order number', v_no using errcode = '22023';
    end if;

    select s.* into v_ship
    from public.shipments s join public.orders o on o.id = s.order_id
    where s.courier_id = v_courier.id
      and ((v_consignment is not null and (s.consignment_id = v_consignment or s.tracking_number = v_consignment))
        or (v_ref is not null and upper(o.order_number) = upper(v_ref)))
    order by (v_consignment is not null and (s.consignment_id = v_consignment or s.tracking_number = v_consignment)) desc,
             s.is_active desc, s.created_at desc
    limit 1;

    if v_ship.id is null then
      v_match := 'UNMATCHED';
      v_issues := array['Not found among our ' || v_courier.name || ' parcels'];
    elsif v_ship.id = any(v_seen) then
      v_match := 'DUPLICATE';
      v_issues := array['Listed more than once on this statement'];
    else
      select coalesce(ci.invoice_number, to_char(ci.created_at, 'DD Mon YYYY')) into v_dup
      from public.courier_invoice_lines l join public.courier_invoices ci on ci.id = l.invoice_id
      where l.shipment_id = v_ship.id and l.invoice_id <> v_inv.id and l.match_status in ('MATCHED', 'MISMATCH')
      limit 1;
      if v_dup is not null then
        v_match := 'DUPLICATE';
        v_issues := array['Already billed on statement ' || v_dup];
      end if;
    end if;

    if v_ship.id is not null then
      select * into v_order from public.orders where id = v_ship.order_id;
      v_exp_cod := case when v_ship.status in ('DELIVERED', 'PARTIALLY_DELIVERED') then v_order.cod_amount else 0 end;
      v_exp_del := coalesce((select sum(amount) from public.shipment_charges where shipment_id = v_ship.id and kind = 'DELIVERY'),
                            nullif(v_ship.shipping_cost, 0));
      v_exp_ret := case when v_ship.status in ('RETURNING', 'RETURNED') or v_order.status in ('RETURNING', 'RETURNED')
                     then coalesce((select sum(amount) from public.shipment_charges where shipment_id = v_ship.id and kind = 'RETURN'),
                                   v_ship.return_charge)
                     else coalesce((select sum(amount) from public.shipment_charges where shipment_id = v_ship.id and kind = 'RETURN'), 0) end;
      v_exp_codfee := coalesce((select sum(amount) from public.shipment_charges where shipment_id = v_ship.id and kind = 'COD_FEE'),
                               case when v_pct is not null then round(v_exp_cod * v_pct / 100, 2) end);
      if v_match is null then
        if v_ship.status not in ('DELIVERED', 'PARTIALLY_DELIVERED', 'RETURNING', 'RETURNED', 'FAILED', 'CANCELLED') then
          v_issues := v_issues || ('Still ' || replace(lower(v_ship.status::text), '_', ' ') || ' in our records');
        end if;
        if v_cod is not null and abs(v_cod - v_exp_cod) >= 1 then
          v_issues := v_issues || format('Collected %s, expected %s', v_cod, v_exp_cod);
        end if;
        if v_del is not null and v_exp_del is not null and abs(v_del - v_exp_del) >= 1 then
          v_issues := v_issues || format('Delivery fee %s, expected %s', v_del, v_exp_del);
        end if;
        if v_ret is not null and abs(v_ret - coalesce(v_exp_ret, 0)) >= 1 then
          v_issues := v_issues || format('Return charge %s, expected %s', v_ret, coalesce(v_exp_ret, 0));
        end if;
        if v_codfee is not null and v_exp_codfee is not null and abs(v_codfee - v_exp_codfee) >= 1 then
          v_issues := v_issues || format('COD fee %s, expected %s', v_codfee, v_exp_codfee);
        end if;
        if coalesce(v_other, 0) <> 0 then
          v_issues := v_issues || format('Other fee %s', v_other);
        end if;
        v_match := case when cardinality(v_issues) > 0 then 'MISMATCH' else 'MATCHED' end;
      end if;
      v_seen := v_seen || v_ship.id;
    end if;

    insert into public.courier_invoice_lines(invoice_id, line_no, consignment_id, order_ref, courier_status, cod_collected,
      delivery_fee, return_fee, cod_fee, other_fee, payout, shipment_id, order_id, expected_cod, expected_delivery_fee,
      expected_return_fee, expected_cod_fee, match_status, issues)
    values (v_inv.id, v_no, v_consignment, v_ref, left(nullif(trim(v_line ->> 'courier_status'), ''), 60), v_cod, v_del, v_ret,
      v_codfee, v_other, v_payout, v_ship.id, v_ship.order_id, v_exp_cod, v_exp_del, v_exp_ret, v_exp_codfee, v_match, v_issues);

    t_cod := t_cod + coalesce(v_cod, 0);
    t_del := t_del + coalesce(v_del, 0);
    t_ret := t_ret + coalesce(v_ret, 0);
    t_codfee := t_codfee + coalesce(v_codfee, 0);
    t_other := t_other + coalesce(v_other, 0);
    if v_payout is null then v_all_payout := false; else t_payout := t_payout + v_payout; end if;
    if v_match in ('MATCHED', 'MISMATCH') then
      -- Without our own figure for a fee there is nothing to dispute: the statement's stands.
      e_cod := e_cod + coalesce(v_exp_cod, 0);
      e_del := e_del + coalesce(v_exp_del, v_del, 0);
      e_ret := e_ret + coalesce(v_exp_ret, 0);
      e_codfee := e_codfee + coalesce(v_exp_codfee, v_codfee, 0);
      e_payout := e_payout + coalesce(v_exp_cod, 0) - coalesce(v_exp_del, v_del, 0) - coalesce(v_exp_ret, 0) - coalesce(v_exp_codfee, v_codfee, 0);
    end if;
    case v_match when 'MATCHED' then n_match := n_match + 1; when 'MISMATCH' then n_mis := n_mis + 1;
                 when 'UNMATCHED' then n_un := n_un + 1; else n_dup := n_dup + 1; end case;
  end loop;

  v_reported := coalesce(public._jnum(p, 'payout_reported', 0),
                         case when v_all_payout then t_payout end,
                         t_cod - t_del - t_ret - t_codfee - t_other);
  update public.courier_invoices set
    line_count = v_no, matched_count = n_match, mismatch_count = n_mis, unmatched_count = n_un, duplicate_count = n_dup,
    cod_collected = t_cod, delivery_fees = t_del, return_fees = t_ret, cod_fees = t_codfee, other_fees = t_other,
    payout_reported = v_reported,
    expected_cod_collected = e_cod, expected_delivery_fees = e_del, expected_return_fees = e_ret, expected_cod_fees = e_codfee,
    payout_expected = e_payout,
    status = case when n_mis + n_un + n_dup > 0 or abs(v_reported - e_payout) >= 1 then 'DISCREPANCY' else 'NEEDS_REVIEW' end::public.courier_invoice_status
  where id = v_inv.id
  returning * into v_inv;
  perform public.log_audit('courier_invoice.imported', 'courier_invoice', v_inv.id::text, null,
    jsonb_build_object('courier', v_courier.name, 'invoice_number', v_number, 'lines', v_no, 'difference', v_inv.difference), null);
  return jsonb_build_object('invoice_id', v_inv.id, 'status', v_inv.status, 'lines', v_no, 'matched', n_match,
    'mismatched', n_mis, 'unmatched', n_un, 'duplicates', n_dup, 'payout_expected', v_inv.payout_expected,
    'payout_reported', v_inv.payout_reported, 'difference', v_inv.difference);
end;

integration_secret_clear.src:
declare
  v_merchant uuid := public.current_merchant_id();
  v_secret uuid;
begin
  if not public.is_system_context() then
    raise exception 'PERMISSION_DENIED' using errcode = '42501';
  end if;
  if v_merchant is null then
    raise exception 'MERCHANT_REQUIRED: no merchant context for this credential' using errcode = '42501';
  end if;
  select secret_id into v_secret from public.integration_credentials where merchant_id = v_merchant and key = p_key;
  if v_secret is not null then
    perform vault.update_secret(v_secret, '{}');
  end if;
  update public.integration_credentials set hint = null, updated_at = now() where merchant_id = v_merchant and key = p_key;
  insert into public.audit_logs(merchant_id, actor_id, actor_email, action, entity_type, entity_id, metadata)
  values (v_merchant, p_actor, (select email from public.profiles where id = p_actor and merchant_id = v_merchant),
          'integration.disconnected', 'integration', p_key, '{}'::jsonb);
end;

integration_secret_get.src:
declare
  v_merchant uuid := public.current_merchant_id();
  v_secret uuid;
  v_value text;
begin
  if not public.is_system_context() then
    raise exception 'PERMISSION_DENIED' using errcode = '42501';
  end if;
  if v_merchant is null then
    return null;
  end if;
  select secret_id into v_secret from public.integration_credentials
  where merchant_id = v_merchant and key = p_key and hint is not null;
  if v_secret is null then
    return null;
  end if;
  select decrypted_secret into v_value from vault.decrypted_secrets where id = v_secret;
  return nullif(nullif(v_value, ''), '{}')::jsonb;
end;

integration_secret_store.src:
declare
  v_merchant uuid := public.current_merchant_id();
  v_secret uuid;
  v_name text;
begin
  if not public.is_system_context() then
    raise exception 'PERMISSION_DENIED' using errcode = '42501';
  end if;
  if v_merchant is null then
    raise exception 'MERCHANT_REQUIRED: no merchant context for this credential' using errcode = '42501';
  end if;
  if p_value is null or jsonb_typeof(p_value) <> 'object' then
    raise exception 'VALIDATION: credentials must be an object' using errcode = '22023';
  end if;
  v_name := 'integration:' || v_merchant::text || ':' || p_key;
  select secret_id into v_secret from public.integration_credentials where merchant_id = v_merchant and key = p_key;
  if v_secret is null then
    select id into v_secret from vault.secrets where name = v_name;
  end if;
  if v_secret is null then
    v_secret := vault.create_secret(p_value::text, v_name, 'Integration credentials');
  else
    perform vault.update_secret(v_secret, p_value::text);
  end if;
  insert into public.integration_credentials(merchant_id, key, secret_id, hint, connected_by, connected_at, updated_at)
  values (v_merchant, p_key, v_secret, p_hint, p_actor, now(), now())
  on conflict (merchant_id, key) do update set secret_id = excluded.secret_id, hint = excluded.hint,
    connected_by = excluded.connected_by, connected_at = now(), updated_at = now();
  insert into public.audit_logs(merchant_id, actor_id, actor_email, action, entity_type, entity_id, metadata)
  values (v_merchant, p_actor, (select email from public.profiles where id = p_actor and merchant_id = v_merchant),
          'integration.connected', 'integration', p_key, jsonb_build_object('hint', p_hint));
end;

integrations_overview.src:
declare
  v_creds jsonb;
begin
  perform public.require_permission('settings.view');
  select coalesce(jsonb_object_agg(key, jsonb_build_object('hint', hint, 'at', connected_at)), '{}'::jsonb) into v_creds
  from public.integration_credentials where hint is not null;
  return jsonb_build_object(
    'channels', coalesce((select jsonb_agg(jsonb_build_object('name', name, 'platform', platform, 'status', status, 'domain', shop_domain,
        'last_sync_at', last_sync_at, 'last_order_at', last_order_at, 'last_error', last_error, 'orders', orders_imported) order by created_at)
      from public.sales_channels where status <> 'DISCONNECTED'), '[]'::jsonb),
    'couriers', coalesce((select jsonb_agg(jsonb_build_object('name', c.name, 'provider', cc.provider, 'hint', cc.hint, 'at', cc.connected_at,
        'last_event_at', (select max(e.received_at) from public.courier_webhook_events e where e.provider = cc.provider)) order by c.name)
      from public.courier_credentials cc join public.couriers c on c.id = cc.courier_id where cc.hint is not null), '[]'::jsonb),
    'ads', coalesce((select jsonb_agg(jsonb_build_object('platform', platform, 'name', coalesce(display_name, external_user), 'status', status,
        'last_error', last_error, 'at', connected_at) order by platform) from public.ad_connections), '[]'::jsonb)
      || coalesce((select jsonb_agg(jsonb_build_object('platform', 'META', 'name', coalesce(meta_name, name),
        'status', case when connection_status = 'ERROR' or last_sync_status = 'ERROR' then 'ERROR' else connection_status end,
        'last_error', coalesce(connection_error, last_sync_error), 'at', created_at) order by name)
      from public.meta_ad_accounts where is_active and token_hint is not null), '[]'::jsonb),
    'credentials', v_creds,
    'sms', (select jsonb_build_object('provided_by_platform', true, 'connected', public._platform_sms_provider() is not null, 'enabled', value -> 'enabled')
             from public.settings where key = 'sms'),
    'bd_courier', jsonb_build_object('provided_by_platform', true,
      'connected', public._platform_service_connected('BD_COURIER'),
      'enabled', public.feature_enabled('courier_history')),
    'site_keys', (select count(*) from public.site_api_keys where revoked_at is null),
    'domains', coalesce((select jsonb_agg(jsonb_build_object('domain', domain, 'status', status)) from public.store_domains), '[]'::jsonb),
    'pbx', (select jsonb_build_object('enabled', value -> 'enabled', 'provider', value ->> 'provider', 'mode', value ->> 'click_mode',
        'calls_7d', (select count(*) from public.pbx_calls where received_at > now() - interval '7 days'),
        'last_call_at', (select max(received_at) from public.pbx_calls))
      from public.settings where key = 'pbx'));
end;

inventory_bulk_adjust.src:
declare
  v_item jsonb;
  v_n int := 0;
  v_mode text;
  v_qty int;
begin
  perform public.require_permission('inventory.adjust');
  if jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'VALIDATION: nothing to change' using errcode = '22023';
  end if;
  if jsonb_array_length(p_items) > 1000 then
    raise exception 'VALIDATION: change at most 1000 variants at a time' using errcode = '22023';
  end if;
  if length(trim(coalesce(p_note, ''))) < 2 then
    raise exception 'VALIDATION: add a short note (why the stock changes)' using errcode = '22023';
  end if;
  for v_item in select * from jsonb_array_elements(p_items) loop
    v_mode := upper(coalesce(v_item ->> 'mode', 'ADD'));
    v_qty := (v_item ->> 'quantity')::int;
    if v_mode not in ('ADD', 'REMOVE', 'SET') or v_qty is null or v_qty < 0 then
      raise exception 'VALIDATION: each line needs a quantity of 0 or more and ADD, REMOVE or SET' using errcode = '22023';
    end if;
    continue when v_qty = 0 and v_mode <> 'SET';
    perform public.adjust_stock((v_item ->> 'variant_id')::uuid, 'ADJUSTMENT', v_qty, trim(p_note), v_mode, null);
    v_n := v_n + 1;
  end loop;
  return jsonb_build_object('changed', v_n);
end;

log_audit.src:
declare
  v_uid uuid := auth.uid();
begin
  insert into public.audit_logs(actor_id, actor_email, action, entity_type, entity_id, old_values, new_values, metadata)
  values (
    v_uid,
    coalesce((select email from public.profiles where id = v_uid), auth.jwt() ->> 'email',
             case when public.is_system_context() then 'system' end),
    p_action, p_entity_type, p_entity_id, p_old, p_new, coalesce(p_metadata, '{}'::jsonb)
  );
end;

log_client_error.src:
begin
  if not public.is_staff() then
    raise exception 'PERMISSION_DENIED' using errcode = '42501';
  end if;
  perform public._log_system_event('ERROR', 'FRONTEND', 'admin-app', left(coalesce(p_message, 'Unknown error'), 2000),
    jsonb_strip_nulls(coalesce(p_context, '{}'::jsonb)) || jsonb_build_object('user_id', auth.uid()));
end;

log_system_event.src:
begin
  if not public.is_system_context() then
    raise exception 'PERMISSION_DENIED' using errcode = '42501';
  end if;
  return public._log_system_event(p_level, p_category, p_source, p_message, p_context);
end;

mark_labels_printed.src:
declare
  v_order public.orders;
  v_first int := 0;
  v_reprint int := 0;
  v_skipped jsonb := '[]'::jsonb;
begin
  perform public.require_permission('orders.fulfill');
  if coalesce(array_length(p_order_ids, 1), 0) = 0 then
    raise exception 'VALIDATION: choose at least one order' using errcode = '22023';
  end if;
  if array_length(p_order_ids, 1) > 500 then
    raise exception 'VALIDATION: print at most 500 labels at a time' using errcode = '22023';
  end if;

  for v_order in select * from public.orders where id = any(p_order_ids) order by created_at for update loop
    if v_order.status in ('CANCELLED', 'REJECTED_FRAUD') then
      v_skipped := v_skipped || jsonb_build_object('order_number', v_order.order_number, 'reason', 'cancelled');
      continue;
    end if;
    update public.orders set
      label_printed_at = coalesce(label_printed_at, now()),
      label_last_printed_at = now(),
      label_printed_by = auth.uid(),
      label_print_count = label_print_count + 1
    where id = v_order.id;
    if v_order.label_printed_at is null then
      v_first := v_first + 1;
      perform public._order_log(v_order.id, 'LABEL_PRINTED', 'Shipping label printed', null, null,
        jsonb_build_object('format', p_format));
    else
      v_reprint := v_reprint + 1;
      perform public._order_log(v_order.id, 'LABEL_REPRINTED',
        format('Shipping label reprinted (print #%s)', v_order.label_print_count + 1), null, null,
        jsonb_build_object('format', p_format, 'print_count', v_order.label_print_count + 1));
    end if;
  end loop;

  perform public.log_audit('order.labels_printed', 'order', null, null, null,
    jsonb_build_object('order_ids', to_jsonb(p_order_ids), 'printed', v_first, 'reprinted', v_reprint, 'format', p_format));
  return jsonb_build_object('printed', v_first, 'reprinted', v_reprint, 'skipped', v_skipped);
end;

marketing_spend_to_finance.src:
declare
  v_delta numeric;
  v_row public.marketing_spend := coalesce(new, old);
  v_campaign text;
begin
  if not public.setting_bool('finance', array['post_ad_spend_to_expenses'], true) then
    return coalesce(new, old);
  end if;
  v_delta := case tg_op when 'INSERT' then new.spend when 'DELETE' then -old.spend else new.spend - old.spend end;
  if v_delta = 0 then
    return coalesce(new, old);
  end if;
  select platform || ' · ' || name into v_campaign from public.marketing_campaigns where id = v_row.campaign_id;
  perform public._post_finance('EXPENSE', 'ADVERTISING', v_delta, v_row.spend_date, true, null, null, null,
    v_campaign, case tg_op when 'INSERT' then 'Ad spend' else 'Ad spend correction' end,
    'marketing_spend:' || v_row.id || ':' || case tg_op when 'INSERT' then 'initial' else gen_random_uuid()::text end,
    null);
  return coalesce(new, old);
end;

merchant_access_mode.src:
declare
  v_id uuid := coalesce(p_merchant, public.current_merchant_id());
  v_rules jsonb := coalesce((select value from public.platform_settings where key = 'access_rules'), '{}'::jsonb);
  v_status text;
  s public.subscriptions;
  v_sub_key text;
  v_a text;
  v_b text;
begin
  if v_id is null then
    return 'BLOCKED';
  end if;
  select status into v_status from public.merchants where id = v_id;
  if v_status is null or v_status = 'CLOSED' then
    return 'BLOCKED';
  end if;
  v_a := case v_status when 'SUSPENDED' then coalesce(v_rules ->> 'MERCHANT_SUSPENDED', 'BLOCKED')
                       when 'ONBOARDING' then coalesce(v_rules ->> 'MERCHANT_ONBOARDING', 'FULL') else 'FULL' end;
  -- The current subscription; when none, the last one that ended (expired or
  -- cancelled accounts stay restricted). NO_SUBSCRIPTION only if there never was one.
  select * into s from public.subscriptions where merchant_id = v_id
  order by (ended_at is null) desc, ended_at desc nulls last, created_at desc limit 1;
  v_sub_key := case
    when s.id is null then 'NO_SUBSCRIPTION'
    when s.status = 'PAST_DUE' and s.grace_until is not null and s.grace_until < now() then 'PAST_DUE_AFTER_GRACE'
    else s.status end;
  v_b := coalesce(v_rules ->> v_sub_key, 'FULL');
  -- The stricter of the two wins.
  return case when 'BLOCKED' in (v_a, v_b) then 'BLOCKED' when 'READ_ONLY' in (v_a, v_b) then 'READ_ONLY' else 'FULL' end;
end;

merchant_data_deletion_cancel.src:
begin
  if public.current_role_code() is distinct from 'OWNER' or public._support_session_id() is not null then
    raise exception 'PERMISSION_DENIED' using errcode = '42501';
  end if;
  update public.merchant_deletion_requests set status = 'CANCELLED', decision_note = 'Withdrawn by the account owner'
  where merchant_id = public.current_merchant_id() and status in ('REQUESTED', 'APPROVED');
  if not found then
    raise exception 'NOT_FOUND: no open request' using errcode = 'P0002';
  end if;
end;

merchant_data_deletion_request.src:
declare
  v_merchant uuid := public.current_merchant_id();
  r public.merchant_deletion_requests;
begin
  if public.current_role_code() is distinct from 'OWNER' or public._support_session_id() is not null then
    raise exception 'PERMISSION_DENIED: only the account owner can ask for the data to be erased' using errcode = '42501';
  end if;
  if length(trim(coalesce(p_reason, ''))) < 5 then
    raise exception 'VALIDATION: tell us why (at least 5 characters)' using errcode = '22023';
  end if;
  if exists (select 1 from public.merchant_deletion_requests where merchant_id = v_merchant and status in ('REQUESTED', 'APPROVED')) then
    raise exception 'VALIDATION: a request is already open' using errcode = '22023';
  end if;
  insert into public.merchant_deletion_requests (merchant_id, source, reason, requested_by, requested_by_email)
  values (v_merchant, 'MERCHANT', trim(p_reason), auth.uid(), (select email from public.profiles where id = auth.uid()))
  returning * into r;
  perform public._platform_notify('data', 'approve', v_merchant, 'data.deletion_requested', 'WARN',
    format('Data erasure requested: #%s %s', (select number from public.merchants where id = v_merchant), (select name from public.merchants where id = v_merchant)),
    trim(p_reason), '/super-admin/data?tab=deletion', 'deletion:' || r.id);
  insert into public.audit_logs (merchant_id, actor_id, actor_email, action, entity_type, entity_id, metadata)
  values (v_merchant, auth.uid(), (select email from public.profiles where id = auth.uid()), 'data.deletion_requested', 'merchant', v_merchant::text,
          jsonb_build_object('request', r.number));
  return jsonb_build_object('id', r.id, 'number', r.number, 'status', r.status, 'created_at', r.created_at);
end;

merchant_entitlements.src:
declare
  v_id uuid := coalesce(p_merchant, public.current_merchant_id());
  v_plan public.plans;
  v_out jsonb := '{}'::jsonb;
  f public.features;
  o public.merchant_features;
  v_state text;
  v_limit numeric;
  v_failing text[] := '{}';
begin
  if v_id is null then
    return '{}'::jsonb;
  end if;
  select p.* into v_plan from public.subscriptions s join public.plans p on p.id = s.plan_id where s.merchant_id = v_id and s.ended_at is null;
  -- Integrations reported failing for this merchant right now.
  if exists (select 1 from public.sales_channels where merchant_id = v_id and platform = 'SHOPIFY' and status = 'ERROR') then v_failing := array_append(v_failing, 'shopify'); end if;
  if exists (select 1 from public.sales_channels where merchant_id = v_id and platform = 'WOOCOMMERCE' and status = 'ERROR') then v_failing := array_append(v_failing, 'woocommerce'); end if;
  -- Integrations an open incident marks unavailable, for everyone or for this merchant.
  v_failing := v_failing || coalesce(array(select jsonb_array_elements_text(value -> 'failing') from public.platform_settings where key = 'integration_health'), '{}')
    || coalesce(array(select jsonb_array_elements_text(value -> 'by_merchant' -> v_id::text) from public.platform_settings where key = 'integration_health'), '{}');
  for f in select * from public.features order by sort_order loop
    select * into o from public.merchant_features where merchant_id = v_id and feature_code = f.code and (expires_at is null or expires_at > now());
    v_limit := coalesce(o.limit_value, nullif(v_plan.limits ->> f.code, '')::numeric);
    v_state := case
      when f.is_core then 'CORE'
      when not f.globally_enabled then 'DISABLED_GLOBALLY'
      when o.enabled is false then 'DISABLED_FOR_MERCHANT'
      when o.enabled is true then 'ENABLED'
      when f.release_stage <> 'GA' then 'BETA_NOT_ENROLLED'
      when coalesce((v_plan.features ->> f.code)::boolean, false) then 'ENABLED'
      else 'NOT_IN_PLAN' end;
    if v_state = 'ENABLED' and f.depends_on = any (v_failing) then
      v_state := 'UNAVAILABLE';
    end if;
    v_out := v_out || jsonb_build_object(f.code, jsonb_build_object('name', f.name, 'state', v_state,
      'enabled', v_state in ('ENABLED', 'CORE', 'UNAVAILABLE'), 'limit', v_limit, 'override', o.enabled, 'override_reason', o.reason));
  end loop;
  return v_out;
end;

merchant_for.src:
declare
  v_ids uuid[];
  v_uuid uuid;
  v_a text;
  v_b text;
begin
  if not public.is_system_context() then
    raise exception 'PERMISSION_DENIED' using errcode = '42501';
  end if;
  if p_key is null or length(p_key) = 0 or length(p_key) > 300 then
    return null;
  end if;
  if p_kind in ('channel', 'courier', 'payment', 'pbx_call', 'order', 'profile') then
    if p_key !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
      return null;
    end if;
    v_uuid := p_key::uuid;
  end if;
  v_a := split_part(p_key, ':', 1);
  v_b := substr(p_key, length(v_a) + 2);

  v_ids := case p_kind
    when 'channel' then array(select merchant_id from public.sales_channels where id = v_uuid)
    when 'channel_oauth_state' then array(select merchant_id from public.channel_oauth_states where state = p_key)
    when 'ad_oauth_state' then array(select merchant_id from public.ad_oauth_states where state = p_key)
    when 'courier' then array(select merchant_id from public.couriers where id = v_uuid)
    -- "<provider>:<consignment id>" for provider-wide courier webhooks
    when 'consignment' then array(select distinct s.merchant_id from public.shipments s join public.couriers c on c.id = s.courier_id
                                  where c.provider = v_a and (s.consignment_id = v_b or s.tracking_number = v_b))
    -- "<provider>:<gateway session or our reference>" for payment returns and IPNs
    when 'payment_session' then array(select distinct merchant_id from public.payments
                                      where provider = v_a and (metadata @> jsonb_build_object('sessions', jsonb_build_array(v_b)) or reference = v_b))
    when 'payment' then array(select merchant_id from public.payments where id = v_uuid)
    when 'site_api_key' then array(select merchant_id from public.site_api_keys where key_hash = p_key and revoked_at is null)
    when 'store_domain' then array(select merchant_id from public.store_domains where domain = lower(p_key) and status <> 'REMOVED')
    when 'pbx_bkash_reference' then array(select merchant_id from public.pbx_bkash_transactions where reference = p_key)
    when 'pbx_bkash_payment' then array(select merchant_id from public.pbx_bkash_transactions where payment_id = p_key)
    when 'pbx_sip_username' then array(select merchant_id from public.pbx_agents where sip_username = p_key)
    when 'pbx_did' then array(select merchant_id from public.pbx_businesses where did in (p_key, public.normalize_phone(p_key)))
    when 'pbx_business_code' then array(select merchant_id from public.pbx_businesses where code::text = p_key)
    when 'pbx_call' then array(select merchant_id from public.pbx_call_records where id = v_uuid)
    when 'order' then array(select merchant_id from public.orders where id = v_uuid)
    when 'profile' then array(select merchant_id from public.profiles where id = v_uuid)
    else null
  end;
  if v_ids is null then
    raise exception 'VALIDATION: unknown lookup %', p_kind using errcode = '22023';
  end if;
  -- Not found, or found in more than one merchant: no answer rather than a guess.
  if cardinality(v_ids) <> 1 then
    return null;
  end if;
  return (select id from public.merchants where id = v_ids[1] and status <> 'CLOSED');
end;

merchant_self_onboard.src:
declare
  v_uid uuid := auth.uid();
  v_user record;
  -- Open unless the Super Admin set it to false.
  v_open boolean := coalesce((select value ->> 'enabled' from public.platform_settings where key = 'signup'), 'true') <> 'false';
  v_plan public.plans;
  v_name text := trim(coalesce(p ->> 'business_name', ''));
  v_full_name text := nullif(trim(coalesce(p ->> 'full_name', '')), '');
  v_phone text := public.normalize_phone(nullif(trim(coalesce(p ->> 'phone', '')), ''));
  v_website text := nullif(trim(coalesce(p ->> 'website', '')), '');
  v_id uuid;
  v_role uuid;
  v_sub public.subscriptions;
begin
  if v_uid is null then
    raise exception 'PERMISSION_DENIED: sign in first' using errcode = '42501';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('self-onboard:' || v_uid, 0));
  -- Already done (a second tab, a retry): the same business, nothing new.
  select merchant_id into v_id from public.profiles where id = v_uid;
  if v_id is not null then
    return jsonb_build_object('merchant_id', v_id, 'already', true);
  end if;
  if not v_open then
    raise exception 'VALIDATION: new sign-ups are closed at the moment; contact us to open an account' using errcode = '22023';
  end if;
  select id, email, email_confirmed_at, raw_user_meta_data into v_user from auth.users where id = v_uid;
  if v_user.email_confirmed_at is null then
    raise exception 'VALIDATION: confirm your e-mail address first; the link is in your inbox' using errcode = '22023';
  end if;
  if exists (select 1 from public.platform_staff where user_id = v_uid) then
    raise exception 'VALIDATION: platform staff accounts cannot open a business; use another e-mail' using errcode = '22023';
  end if;
  if length(v_name) < 2 or length(v_name) > 120 then
    raise exception 'VALIDATION: enter your business name (2 to 120 characters)' using errcode = '22023';
  end if;
  if v_phone is null or v_phone !~ '^01[3-9][0-9]{8}$' then
    raise exception 'VALIDATION: enter a Bangladesh mobile number (01XXXXXXXXX)' using errcode = '22023';
  end if;
  if v_website is not null and v_website !~* '^(https?://)?[a-z0-9.-]+\.[a-z]{2,}(/.*)?$' then
    raise exception 'VALIDATION: the website address does not look right' using errcode = '22023';
  end if;
  select * into v_plan from public.plans
  where code = upper(coalesce(nullif(p ->> 'plan_code', ''), (select value ->> 'default_plan' from public.platform_settings where key = 'billing')))
    and status = 'ACTIVE' and is_public;
  if v_plan.id is null then
    raise exception 'VALIDATION: choose one of the plans shown' using errcode = '22023';
  end if;

  insert into public.merchants (name, status, owner_email, phone, business_type, website, created_by, onboarding)
  values (v_name, 'ONBOARDING', lower(v_user.email), v_phone, nullif(left(trim(coalesce(p ->> 'business_type', '')), 60), ''), v_website, v_uid,
          jsonb_build_object('started_at', now(), 'by', v_uid, 'self_signup', true,
            'sells_on', coalesce(p -> 'sells_on', '[]'::jsonb), 'orders_per_month', nullif(p ->> 'orders_per_month', '')))
  returning id into v_id;

  -- The Owner role and profile come first: from then on the person belongs to
  -- the new business, so its defaults are seeded in its own context.
  insert into public.roles (merchant_id, code, name, description, is_system, rank)
  values (v_id, 'OWNER', 'Owner', 'Full access to everything', true, 100)
  returning id into v_role;
  insert into public.profiles (id, merchant_id, email, full_name, phone, role_id, is_active)
  values (v_uid, v_id, v_user.email, coalesce(v_full_name, v_user.raw_user_meta_data ->> 'full_name', ''), v_phone, v_role, true);
  perform public._merchant_seed_defaults(v_id);
  -- Online store or not (a missing answer keeps the store on, as before).
  if coalesce(p ->> 'online_store', 'true') = 'false' then
    update public.settings set value = value || jsonb_build_object('mode', 'OFF') where merchant_id = v_id and key = 'storefront';
    update public.merchants set slug = null where id = v_id;
  elsif nullif(trim(coalesce(p ->> 'store_slug', '')), '') is not null then
    if public._store_slug_problem(lower(trim(p ->> 'store_slug')), v_id) is not null then
      raise exception 'VALIDATION: store address: %', public._store_slug_problem(lower(trim(p ->> 'store_slug')), v_id) using errcode = '22023';
    end if;
    update public.merchants set slug = lower(trim(p ->> 'store_slug')) where id = v_id;
  end if;
  update public.settings set value = value || jsonb_build_object('name', v_name, 'phone', v_phone, 'email', lower(v_user.email))
  where merchant_id = v_id and key = 'store';

  insert into public.subscriptions (merchant_id, plan_id, status, price, currency, billing_interval, trial_ends_at,
                                    current_period_start, current_period_end, created_by)
  values (v_id, v_plan.id, case when v_plan.trial_days > 0 then 'TRIALING' else 'ACTIVE' end, v_plan.price, v_plan.currency, v_plan.billing_interval,
          case when v_plan.trial_days > 0 then now() + make_interval(days => v_plan.trial_days) end, now(),
          -- Free plans run a full period; a paid plan without a trial is due now (its first invoice is raised at once).
          case when v_plan.trial_days > 0 then null when v_plan.price = 0 then now() + public._billing_interval(v_plan.billing_interval) else now() end,
          v_uid)
  returning * into v_sub;
  insert into public.subscription_events (merchant_id, subscription_id, event, detail, actor_id)
  values (v_id, v_sub.id, 'subscription.started', jsonb_build_object('plan', v_plan.code, 'trial', v_sub.status = 'TRIALING', 'reason', 'Self sign-up'), v_uid);
  perform public.log_audit('merchant.self_signup', 'merchant', v_id::text, null, jsonb_build_object('name', v_name, 'plan', v_plan.code));
  perform public._platform_log('merchant.self_signup', v_id, 'merchant', v_id::text, null, null,
    jsonb_build_object('name', v_name, 'plan', v_plan.code, 'email', lower(v_user.email)));
  return jsonb_build_object('merchant_id', v_id, 'plan', v_plan.code, 'status', v_sub.status, 'trial_ends_at', v_sub.trial_ends_at);
end;

merchant_store_address.src:
declare
  v_id uuid := public.current_merchant_id();
  v_m public.merchants;
  v_front jsonb;
  v_mode text;
  v_root text := public._store_root_domain();
begin
  if not public.is_staff() then
    raise exception 'PERMISSION_DENIED: staff only' using errcode = '42501';
  end if;
  select * into v_m from public.merchants where id = v_id;
  select value into v_front from public.settings where merchant_id = v_id and key = 'storefront';
  v_mode := coalesce(v_front ->> 'mode', 'OWN');
  return jsonb_build_object(
    'mode', v_mode,
    'slug', v_m.slug,
    'root_domain', v_root,
    'subdomain', case when v_mode = 'OWN' and v_m.slug is not null and v_root is not null then v_m.slug || '.' || v_root end,
    'custom_domain', (select domain from public.store_domains where merchant_id = v_id and is_primary and status = 'ACTIVE' limit 1),
    -- Answered on the dashboard, or already selling somewhere (any mode but off).
    'asked', v_mode <> 'OFF' or coalesce((v_front ->> 'store_prompt_done')::boolean, false));
end;

meta_account_disconnect.src:
declare
  v_row public.meta_ad_accounts;
begin
  if not public.is_system_context() then
    raise exception 'PERMISSION_DENIED' using errcode = '42501';
  end if;
  update public.meta_ad_accounts set is_active = false, connection_status = 'DISCONNECTED', token_hint = null, has_app_secret = false
  where id = p_id returning * into v_row;
  if not found then
    raise exception 'NOT_FOUND: Meta account not found' using errcode = 'P0002';
  end if;
  insert into public.audit_logs(actor_id, actor_email, action, entity_type, entity_id, new_values)
  values (p_actor, (select email from public.profiles where id = p_actor), 'meta_account.disconnected', 'meta_account', p_id::text, to_jsonb(v_row));
  return v_row;
end;

meta_account_record_sync.src:
begin
  if not public.is_system_context() then
    raise exception 'PERMISSION_DENIED' using errcode = '42501';
  end if;
  update public.meta_ad_accounts set last_sync_at = now(), last_sync_status = p_status, last_sync_error = left(p_error, 500),
    last_sync_since = p_since, last_sync_until = p_until,
    connection_status = case when p_status = 'TOKEN_INVALID' then 'FAILED' when p_status = 'OK' then 'OK' else connection_status end,
    connection_error = case when p_status = 'OK' then null when p_status = 'TOKEN_INVALID' then left(p_error, 500) else connection_error end
  where id = p_id;
  -- The Marketing overview keeps showing the latest sync of any account.
  update public.settings set value = value || jsonb_build_object('connected', true, 'last_sync_at', now(), 'last_sync_status', p_status,
    'last_sync_error', left(p_error, 500), 'last_sync_since', p_since, 'last_sync_until', p_until)
  where key = 'meta_ads';
end;

meta_account_save.src:
declare
  v_id uuid := nullif(p ->> 'id', '')::uuid;
  v_old public.meta_ad_accounts;
  v_row public.meta_ad_accounts;
  v_act text := regexp_replace(trim(coalesce(p ->> 'ad_account_id', '')), '^act_', '');
  v_pay uuid := nullif(p ->> 'payment_account_id', '')::uuid;
  v_range record;
  v_ids text[];
begin
  if not public.is_system_context() then
    raise exception 'PERMISSION_DENIED' using errcode = '42501';
  end if;
  if length(trim(coalesce(p ->> 'name', ''))) < 2 then
    raise exception 'VALIDATION: give the account a name' using errcode = '22023';
  end if;
  if v_act !~ '^[0-9]{3,32}$' then
    raise exception 'VALIDATION: the ad account ID is the number without act_' using errcode = '22023';
  end if;
  if coalesce((p ->> 'usd_rate')::numeric, 110) <= 0 then
    raise exception 'VALIDATION: the USD rate must be more than 0' using errcode = '22023';
  end if;
  if v_pay is not null and not exists (select 1 from public.finance_accounts where id = v_pay and is_active) then
    raise exception 'VALIDATION: choose an active payment account' using errcode = '22023';
  end if;
  if exists (select 1 from public.meta_ad_accounts where ad_account_id = v_act and id is distinct from v_id) then
    raise exception 'DUPLICATE: ad account % is already connected', v_act using errcode = '23505';
  end if;
  if exists (select 1 from public.meta_ad_accounts where lower(name) = lower(trim(p ->> 'name')) and id is distinct from v_id) then
    raise exception 'DUPLICATE: there is already an account called %', trim(p ->> 'name') using errcode = '23505';
  end if;

  if v_id is null then
    insert into public.meta_ad_accounts(name, app_id, ad_account_id, usd_rate, payment_account_id, payments_from, is_active, created_by)
    values (trim(p ->> 'name'), nullif(trim(coalesce(p ->> 'app_id', '')), ''), v_act, coalesce((p ->> 'usd_rate')::numeric, 110),
            v_pay, case when v_pay is not null then public._local_date(now()) end, coalesce((p ->> 'is_active')::boolean, true), p_actor)
    returning * into v_row;
  else
    select * into v_old from public.meta_ad_accounts where id = v_id for update;
    if not found then
      raise exception 'NOT_FOUND: Meta account not found' using errcode = 'P0002';
    end if;
    update public.meta_ad_accounts set name = trim(p ->> 'name'), app_id = nullif(trim(coalesce(p ->> 'app_id', '')), ''),
      ad_account_id = v_act, usd_rate = coalesce((p ->> 'usd_rate')::numeric, usd_rate), payment_account_id = v_pay,
      payments_from = case when v_pay is null then null when v_pay is distinct from v_old.payment_account_id and v_old.payment_account_id is null
                           then public._local_date(now()) else payments_from end,
      is_active = coalesce((p ->> 'is_active')::boolean, is_active)
    where id = v_id returning * into v_row;
  end if;

  -- What the connection test found.
  if p ? 'meta' then
    update public.meta_ad_accounts set meta_name = p #>> '{meta,name}', currency = p #>> '{meta,currency}', timezone = p #>> '{meta,timezone}',
      token_hint = coalesce(p #>> '{meta,token_hint}', token_hint), has_app_secret = coalesce((p #>> '{meta,has_app_secret}')::boolean, has_app_secret),
      token_expires_at = nullif(p #>> '{meta,token_expires_at}', '')::timestamptz,
      connection_status = coalesce(p #>> '{meta,status}', 'OK'), connection_error = p #>> '{meta,error}', tested_at = now()
    where id = v_row.id returning * into v_row;
  end if;

  if v_old.id is not null and v_old.usd_rate is distinct from v_row.usd_rate then
    update public.meta_ad_insights set cost = public._meta_cost(spend, account_id)
    where account_id = v_row.ad_account_id and cost is distinct from public._meta_cost(spend, account_id);
    select min(date) as since, max(date) as until into v_range from public.meta_ad_insights where account_id = v_row.ad_account_id;
    select array_agg(distinct campaign_id) into v_ids from public.meta_ad_insights where account_id = v_row.ad_account_id and campaign_id is not null;
    if v_range.since is not null then
      perform public._meta_refresh_marketing_spend(coalesce(v_ids, '{}'), v_range.since, v_range.until);
      perform public._meta_settle_payments(v_row.ad_account_id, v_range.since, v_range.until);
    end if;
  end if;

  insert into public.audit_logs(actor_id, actor_email, action, entity_type, entity_id, old_values, new_values)
  values (p_actor, (select email from public.profiles where id = p_actor),
          case when v_old.id is null then 'meta_account.created' else 'meta_account.updated' end, 'meta_account', v_row.id::text,
          to_jsonb(v_old), to_jsonb(v_row));
  return v_row;
end;

