notification_conditions_error.src:
declare
  c jsonb;
  v_field text;
  v_op text;
  v_value jsonb;
  v_item text;
begin
  if p_conditions is null or jsonb_typeof(p_conditions) <> 'array' then
    return 'conditions must be a list';
  end if;
  if jsonb_array_length(p_conditions) > 10 then
    return 'use at most 10 conditions';
  end if;
  for c in select * from jsonb_array_elements(p_conditions) loop
    if jsonb_typeof(c) <> 'object' then
      return 'each condition must be an object';
    end if;
    v_field := c ->> 'field';
    v_op := c ->> 'op';
    v_value := c -> 'value';
    if v_field in ('payment_method', 'district', 'source', 'courier') then
      if v_op not in ('in', 'not_in') then
        return format('%s needs "is one of" or "is not one of"', v_field);
      end if;
      if v_value is null or jsonb_typeof(v_value) <> 'array' or jsonb_array_length(v_value) = 0
         or jsonb_array_length(v_value) > 70 then
        return format('choose at least one value for %s', v_field);
      end if;
      for v_item in select * from jsonb_array_elements_text(v_value) loop
        if length(trim(v_item)) = 0 or length(v_item) > 80 then
          return format('%s has an empty or too long value', v_field);
        end if;
        if v_field = 'payment_method' and v_item not in ('COD', 'ADVANCE', 'FULL_PAYMENT') then
          return format('unknown payment method %s', v_item);
        end if;
        if v_field = 'source' and v_item not in ('STOREFRONT', 'ADMIN', 'IMPORT', 'API') then
          return format('unknown order source %s', v_item);
        end if;
        if v_field = 'courier' and v_item !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
          return 'courier must be a courier id';
        end if;
      end loop;
    elsif v_field = 'total' then
      if v_op not in ('gte', 'lte') then
        return 'order total needs "at least" or "at most"';
      end if;
      if v_value is null or jsonb_typeof(v_value) <> 'number' or (v_value #>> '{}')::numeric < 0 then
        return 'order total must be a number of 0 or more';
      end if;
    elsif v_field = 'first_order' then
      if v_op <> 'eq' or v_value is null or jsonb_typeof(v_value) <> 'boolean' then
        return 'first order must be yes or no';
      end if;
    else
      return format('unknown condition %s', coalesce(v_field, '(none)'));
    end if;
  end loop;
  return null;
end;

order_channel_info.src:
declare
  v_order public.orders;
begin
  perform public.require_permission('orders.view');
  select * into v_order from public.orders where id = p_order_id;
  if v_order.sales_channel_id is null then
    return null;
  end if;
  return jsonb_build_object(
    'channel', (select jsonb_build_object('id', c.id, 'name', c.name, 'platform', c.platform, 'shop_domain', c.shop_domain,
      'fulfill_on_ship', public._channel_opt(c, 'fulfill_on_ship', c.platform = 'SHOPIFY'), 'notify_customer', public._channel_opt(c, 'notify_customer', true),
      'mark_delivered', c.platform = 'SHOPIFY' and public._channel_opt(c, 'mark_delivered', true),
      'cancel_on_shopify', c.platform = 'SHOPIFY' and public._channel_opt(c, 'cancel_on_shopify', true))
      from public.sales_channels c where c.id = v_order.sales_channel_id),
    'external_order_id', v_order.external_order_id, 'external_order_number', v_order.external_order_number,
    'merged_into', (select order_number from public.orders where id = v_order.merged_into),
    'fulfillments', coalesce((select jsonb_agg(jsonb_build_object(
        'id', f.id, 'source', f.source, 'status', f.status, 'fulfillment_id', f.fulfillment_id, 'courier', f.courier,
        'tracking_number', f.tracking_number, 'tracking_url', f.tracking_url, 'shopify_status', f.shopify_status,
        'notification_status', f.notification_status, 'notification_note', f.notification_note, 'line_items', f.line_items,
        'attempts', f.attempts, 'last_error', f.last_error, 'fulfilled_at', f.fulfilled_at, 'synced_at', f.synced_at, 'created_at', f.created_at,
        'delivered_status', f.delivered_status, 'delivered_at', f.delivered_at, 'delivered_error', f.delivered_error)
      order by f.created_at) from public.channel_fulfillments f where f.order_id = p_order_id), '[]'::jsonb),
    'sync', (select to_jsonb(s) - 'channel_id' from public.channel_order_sync s where s.order_id = p_order_id),
    'job', (select jsonb_build_object('status', j.status, 'attempts', j.attempts, 'next_attempt_at', j.next_attempt_at, 'last_error', j.last_error)
      from public.channel_sync_jobs j where j.kind = 'FULFILL' and j.ref_id = p_order_id order by j.created_at desc limit 1)
  );
end;

order_merge_info.src:
declare
  v_order public.orders;
  v_primary public.orders;
begin
  perform public.require_permission('orders.view');
  select * into v_order from public.orders where id = p_order_id;
  if not found then
    raise exception 'NOT_FOUND: order not found' using errcode = 'P0002';
  end if;
  select * into v_primary from public.orders where id = coalesce(v_order.merged_into, v_order.id);
  if not exists (select 1 from public.order_merges where order_id = v_primary.id) then
    return null;
  end if;
  return jsonb_build_object(
    'primary', jsonb_build_object('id', v_primary.id, 'order_number', v_primary.order_number, 'status', v_primary.status,
      'review_status', v_primary.review_status, 'total', v_primary.total_amount, 'created_at', v_primary.created_at),
    'is_primary', v_order.merged_into is null,
    'merges', coalesce((select jsonb_agg(jsonb_build_object(
        'id', m.id, 'kind', m.kind, 'at', m.created_at, 'amount', m.amount, 'reason', m.reason,
        'items', m.items, 'source_status', m.source_status, 'source_review_status', m.source_review_status,
        'review_after', m.target_review_after,
        'source', case when s.id is null then null else jsonb_build_object('id', s.id, 'order_number', s.order_number, 'created_at', s.created_at) end)
      order by m.created_at) from public.order_merges m left join public.orders s on s.id = m.source_order_id where m.order_id = v_primary.id), '[]'::jsonb),
    'items', coalesce((select jsonb_agg(jsonb_build_object('name', i.product_name, 'variant', i.variant_title, 'quantity', i.quantity,
        'line_total', i.line_total) order by i.created_at) from public.order_items i where i.order_id = v_primary.id), '[]'::jsonb)
  );
end;

order_set_tags.src:
declare
  v_add text[] := array(select distinct left(trim(t), 40) from unnest(coalesce(p_add, '{}')) t where trim(t) <> '');
  v_remove text[] := array(select trim(t) from unnest(coalesce(p_remove, '{}')) t);
  v_count int;
begin
  perform public.require_permission('orders.update');
  if coalesce(array_length(p_order_ids, 1), 0) > 200 then
    raise exception 'VALIDATION: at most 200 orders at a time' using errcode = '22023';
  end if;
  insert into public.order_tags(name) select unnest(v_add) on conflict (merchant_id, name) do nothing;
  update public.orders o set tags = array(
      select distinct t from unnest(o.tags || v_add) t where not (t = any(v_remove)) order by t)
  where o.id = any(p_order_ids);
  get diagnostics v_count = row_count;
  perform public.log_audit('order.tags', 'order', array_to_string(p_order_ids[1:5], ','), null,
    jsonb_build_object('orders', v_count, 'added', v_add, 'removed', v_remove));
  return v_count;
end;

order_source_save.src:
declare
  v_code text := upper(trim(coalesce(p ->> 'code', '')));
  v_row public.order_sources;
  v_old public.order_sources;
begin
  perform public.require_permission('settings.manage');
  select * into v_old from public.order_sources where code = v_code;
  if v_old.code is null then
    if v_code = '' then
      v_code := upper(regexp_replace(trim(coalesce(p ->> 'label', '')), '[^A-Za-z0-9]+', '_', 'g'));
      v_code := trim(both '_' from left(v_code, 30));
    end if;
    if v_code !~ '^[A-Z0-9_]{2,30}$' then
      raise exception 'VALIDATION: give the source a name of at least 2 letters' using errcode = '22023';
    end if;
    if exists (select 1 from public.order_sources where code = v_code) then
      raise exception 'VALIDATION: a source with this name already exists' using errcode = '23505';
    end if;
    insert into public.order_sources(code, label, channel, is_active, sort_order)
    values (v_code, trim(p ->> 'label'), coalesce(nullif(p ->> 'channel', ''), 'other'), coalesce((p ->> 'is_active')::boolean, true),
      coalesce((p ->> 'sort_order')::int, (select coalesce(max(sort_order), 0) + 10 from public.order_sources)))
    returning * into v_row;
  else
    update public.order_sources set
      label = coalesce(nullif(trim(p ->> 'label'), ''), label),
      channel = coalesce(nullif(p ->> 'channel', ''), channel),
      is_active = coalesce((p ->> 'is_active')::boolean, is_active),
      sort_order = coalesce((p ->> 'sort_order')::int, sort_order)
    where code = v_code returning * into v_row;
  end if;
  perform public.log_audit('order_source.save', 'order_source', v_row.code, to_jsonb(v_old), to_jsonb(v_row));
  return v_row;
end;

parcel_call_log.src:
declare
  v_row public.parcel_calls;
begin
  perform public.require_permission('couriers.view');
  if not exists (select 1 from public.orders where id = p_order_id) then
    raise exception 'NOT_FOUND: order not found' using errcode = 'P0002';
  end if;
  if p_party not in ('CUSTOMER', 'RIDER') or p_outcome not in ('ANSWERED', 'NO_ANSWER', 'BUSY', 'SWITCHED_OFF', 'WRONG_NUMBER') then
    raise exception 'VALIDATION: unknown call party or outcome' using errcode = '22023';
  end if;
  insert into public.parcel_calls(order_id, party, outcome, note, called_by)
  values (p_order_id, p_party, p_outcome, nullif(trim(coalesce(p_note, '')), ''), auth.uid())
  returning * into v_row;
  perform public._order_log(p_order_id, 'PARCEL_CALL',
    format('Called the %s: %s%s', lower(p_party), lower(replace(p_outcome, '_', ' ')), coalesce(' — ' || v_row.note, '')),
    null, null, jsonb_build_object('party', p_party, 'outcome', p_outcome));
  return to_jsonb(v_row);
end;

parcel_history.src:
begin
  perform public.require_permission('couriers.view');
  return coalesce((
    select jsonb_agg(x order by (x ->> 'at')::timestamptz desc) from (
      select jsonb_build_object('kind', 'COURIER', 'at', e.occurred_at, 'status', e.status,
        'text', coalesce(nullif(e.raw ->> 'reason', ''), e.description), 'source', e.source) as x
      from public.shipment_events e join public.shipments s on s.id = e.shipment_id where s.order_id = p_order_id
      union all
      select jsonb_build_object('kind', 'CALL', 'at', c.called_at, 'status', c.outcome, 'party', c.party, 'text', c.note,
        'by', (select coalesce(nullif(pr.full_name, ''), pr.email) from public.profiles pr where pr.id = c.called_by))
      from public.parcel_calls c where c.order_id = p_order_id
      union all
      select jsonb_build_object('kind', 'ORDER', 'at', h.created_at, 'status', h.to_status, 'text', h.message, 'by', h.actor_name)
      from public.order_status_history h where h.order_id = p_order_id and h.to_status is not null
    ) q), '[]'::jsonb);
end;

payment_requirement_for.src:
declare
  v_symbol text := public.setting_text('store', array['currency_symbol'], '৳');
  v_voluntary numeric;
  v_amount numeric := coalesce(p_advance, 0);
  v_mode text;
  v_message text;
begin
  if p_decision = 'BLOCK' then
    return jsonb_build_object('mode', 'BLOCKED', 'amount', 0, 'cod_allowed', false,
      'message', coalesce(p_custom_message, public.setting_text('fraud', array['messages', 'blocked'],
        'We are unable to accept this order online. Please contact us to complete your purchase.')));
  end if;
  if p_decision = 'REVIEW' then
    return jsonb_build_object('mode', 'REVIEW', 'amount', 0, 'cod_allowed', false,
      'message', coalesce(p_custom_message, public.setting_text('fraud', array['messages', 'review'],
        'Your order needs a quick confirmation. Our team will contact you shortly.')));
  end if;

  if p_payment_method = 'FULL_PAYMENT' then
    v_amount := p_total;
  elsif p_payment_method = 'ADVANCE' then
    v_voluntary := public.compute_advance_amount(
      public.setting_text('payments', array['voluntary_advance', 'type'], 'DELIVERY_CHARGE')::public.advance_type,
      public.setting_numeric('payments', array['voluntary_advance', 'value'], 0),
      p_total, null, null);
    v_amount := greatest(v_amount, v_voluntary);
  end if;
  v_amount := least(ceil(v_amount), p_total);

  if v_amount <= 0 then
    return jsonb_build_object('mode', 'COD', 'amount', 0, 'cod_allowed', true, 'message', null);
  end if;

  v_mode := case when v_amount >= p_total then 'FULL' else 'ADVANCE' end;
  v_message := coalesce(p_custom_message,
    case when p_decision = 'ADVANCE_REQUIRED'
      then public.setting_text('fraud', array['messages', 'advance'], 'To confirm this order, a {amount} advance payment is required.')
      else case when v_mode = 'FULL' then 'Complete the payment of {amount} to confirm your order.'
                else 'Pay {amount} in advance to confirm your order.' end
    end);
  v_message := replace(v_message, '{amount}', v_symbol || trim(to_char(v_amount, 'FM999,999,990')));
  return jsonb_build_object('mode', v_mode, 'amount', v_amount, 'cod_allowed', v_mode = 'ADVANCE',
    'remaining_cod', greatest(p_total - v_amount, 0), 'message', v_message);
end;

payment_set_provider.src:
declare
  v_value jsonb;
begin
  if not public.is_system_context() then
    raise exception 'PERMISSION_DENIED' using errcode = '42501';
