platform_approval_decide.src:
declare
  a public.platform_approvals;
  v_result jsonb;
  v_self boolean := false;
begin
  select * into a from public.platform_approvals where id = p_id for update;
  if a.id is null then
    raise exception 'NOT_FOUND: request not found' using errcode = 'P0002';
  end if;
  if a.status <> 'PENDING' or a.expires_at <= now() then
    raise exception 'VALIDATION: this request is already %', lower(case when a.expires_at <= now() and a.status = 'PENDING' then 'EXPIRED' else a.status end) using errcode = '22023';
  end if;
  if a.requested_by = auth.uid() then
    -- The person asking can withdraw; approve only while nobody else could.
    if p_approve and public._platform_sole_approver(a.module, a.merchant_id) then
      v_self := true;
    elsif p_approve then
      raise exception 'PERMISSION_DENIED: a second person must approve this' using errcode = '42501';
    else
      update public.platform_approvals set status = 'CANCELLED', decided_at = now(), decision_note = p_note where id = a.id;
      perform public._platform_log('approval.cancelled', a.merchant_id, 'platform_approval', a.id::text, p_note, null, null);
      return jsonb_build_object('status', 'CANCELLED');
    end if;
  end if;
  perform public._platform_require(a.module, 'approve', a.merchant_id);
  if not p_approve then
    update public.platform_approvals set status = 'REJECTED', decided_by = auth.uid(), decided_at = now(), decision_note = p_note where id = a.id;
    perform public._platform_log('approval.rejected', a.merchant_id, 'platform_approval', a.id::text, p_note, null, jsonb_build_object('action', a.action));
    return jsonb_build_object('status', 'REJECTED');
  end if;
  if v_self then
    p_note := trim(coalesce(p_note, '') || ' (self-approved: nobody else could approve)');
  end if;
  begin
    v_result := public._platform_execute_approval(a);
  exception when others then
    update public.platform_approvals set status = 'FAILED', decided_by = auth.uid(), decided_at = now(), decision_note = p_note, error = sqlerrm, self_approved = v_self
      where id = a.id;
    perform public._platform_log('approval.failed', a.merchant_id, 'platform_approval', a.id::text, p_note, null,
      jsonb_build_object('action', a.action, 'error', sqlerrm, 'self_approved', v_self), 'FAILED');
    return jsonb_build_object('status', 'FAILED', 'error', sqlerrm);
  end;
  update public.platform_approvals set status = 'EXECUTED', decided_by = auth.uid(), decided_at = now(), decision_note = p_note, result = v_result, self_approved = v_self
    where id = a.id;
  perform public._platform_log('approval.executed', a.merchant_id, 'platform_approval', a.id::text, a.reason, null,
    jsonb_build_object('action', a.action, 'result', v_result, 'self_approved', v_self));
  return jsonb_build_object('status', 'EXECUTED', 'result', v_result);
end;

platform_audit_list.src:
declare
  v_merchant uuid := nullif(p_filters ->> 'merchant_id', '')::uuid;
  v_actor uuid := nullif(p_filters ->> 'actor_id', '')::uuid;
  v_action text := nullif(p_filters ->> 'action', '');
  v_result text := nullif(p_filters ->> 'result', '');
  v_from timestamptz := nullif(p_filters ->> 'from', '')::timestamptz;
  v_to timestamptz := nullif(p_filters ->> 'to', '')::timestamptz;
  v_q text := nullif(trim(coalesce(p_filters ->> 'q', '')), '');
begin
  perform public._platform_require('audit', 'view', v_merchant);
  return (
    with rows as (
      select l.* from public.platform_audit_logs l
      where (v_merchant is null or l.merchant_id = v_merchant)
        and (l.merchant_id is null or l.merchant_id in (select public._platform_merchant_ids()))
        and (v_actor is null or l.actor_id = v_actor)
        and (v_action is null or l.action like v_action || '%')
        and (v_result is null or l.result = v_result)
        and (v_from is null or l.created_at >= v_from)
        and (v_to is null or l.created_at < v_to)
        and (v_q is null or l.action ilike '%' || v_q || '%' or l.entity_id ilike '%' || v_q || '%' or l.reason ilike '%' || v_q || '%'
             or l.actor_email ilike '%' || v_q || '%')
    )
    select jsonb_build_object(
      'total', (select count(*) from rows),
      'items', coalesce((select jsonb_agg(jsonb_build_object('id', r.id, 'action', r.action, 'result', r.result, 'actor_email', r.actor_email,
          'actor_id', r.actor_id, 'merchant', (select jsonb_build_object('id', m.id, 'number', m.number, 'name', m.name) from public.merchants m where m.id = r.merchant_id),
          'entity_type', r.entity_type, 'entity_id', r.entity_id, 'reason', r.reason, 'before', r.before, 'after', r.after,
          'metadata', r.metadata, 'request_id', r.request_id, 'created_at', r.created_at) order by r.created_at desc, r.id desc)
        from (select * from rows order by created_at desc, id desc limit greatest(1, least(p_limit, 500)) offset greatest(0, p_offset)) r), '[]'::jsonb))
  );
end;

platform_automation_rule_archive.src:
declare
  r public.platform_automation_rules;
begin
  perform public._platform_require('automation', 'delete');
  if length(trim(coalesce(p_reason, ''))) < 5 then
    raise exception 'VALIDATION: say why the rule is removed' using errcode = '22023';
  end if;
  -- Kept (switched off) so its run log stays readable.
  update public.platform_automation_rules set archived_at = now(), enabled = false, updated_by = auth.uid()
  where id = p_id and archived_at is null returning * into r;
  if r.id is null then
    raise exception 'NOT_FOUND: rule not found' using errcode = 'P0002';
  end if;
  perform public._platform_log('automation.rule_removed', null, 'automation_rule', r.id::text, trim(p_reason), null, jsonb_build_object('name', r.name));
  return to_jsonb(r);
end;

platform_automation_rule_save.src:
declare
  r public.platform_automation_rules;
  v_before jsonb;
  v_id uuid := nullif(p ->> 'id', '')::uuid;
begin
  perform public._platform_require('automation', case when v_id is null then 'create' else 'edit' end);
  perform public._platform_automation_validate(p);
  -- Rules that act on their own need manage access to switch on.
  if coalesce((p ->> 'enabled')::boolean, false) then
    perform public._platform_require('automation', 'manage');
  end if;
  if v_id is null then
    insert into public.platform_automation_rules (name, description, trigger, conditions, actions, enabled, cooldown_minutes, max_actions_per_run, created_by, updated_by)
    values (trim(p ->> 'name'), nullif(trim(coalesce(p ->> 'description', '')), ''), p ->> 'trigger', coalesce(p -> 'conditions', '{}'::jsonb), p -> 'actions',
            coalesce((p ->> 'enabled')::boolean, false), coalesce((p ->> 'cooldown_minutes')::int, 1440), coalesce((p ->> 'max_actions_per_run')::int, 25), auth.uid(), auth.uid())
    returning * into r;
  else
    select to_jsonb(x) into v_before from public.platform_automation_rules x where id = v_id and archived_at is null;
    if v_before is null then
      raise exception 'NOT_FOUND: rule not found' using errcode = 'P0002';
    end if;
    if (v_before ->> 'enabled')::boolean and not coalesce((p ->> 'enabled')::boolean, false) then
      perform public._platform_require('automation', 'manage');
    end if;
    update public.platform_automation_rules set name = trim(p ->> 'name'), description = nullif(trim(coalesce(p ->> 'description', '')), ''), trigger = p ->> 'trigger',
      conditions = coalesce(p -> 'conditions', '{}'::jsonb), actions = p -> 'actions', enabled = coalesce((p ->> 'enabled')::boolean, false),
      cooldown_minutes = coalesce((p ->> 'cooldown_minutes')::int, cooldown_minutes), max_actions_per_run = coalesce((p ->> 'max_actions_per_run')::int, max_actions_per_run),
      updated_by = auth.uid()
    where id = v_id returning * into r;
  end if;
  perform public._config_version('automation_rule', r.id::text, to_jsonb(r) - 'last_run_at' - 'last_result', p_reason);
  perform public._platform_log(case when v_id is null then 'automation.rule_created' else 'automation.rule_changed' end, null, 'automation_rule', r.id::text, p_reason,
    v_before - 'last_run_at' - 'last_result', to_jsonb(r) - 'last_run_at' - 'last_result');
  return to_jsonb(r);
end;

platform_automation_rules_list.src:
begin
  perform public._platform_require('automation', 'view');
  return jsonb_build_object(
    'rules', (select coalesce(jsonb_agg(to_jsonb(r) || jsonb_build_object(
        'runs_7d', (select count(*) from public.platform_automation_runs x where x.rule_id = r.id and x.created_at > now() - interval '7 days'),
        'failed_7d', (select count(*) from public.platform_automation_runs x where x.rule_id = r.id and x.status = 'FAILED' and x.created_at > now() - interval '7 days'))
        order by r.created_at), '[]'::jsonb)
      from public.platform_automation_rules r where r.archived_at is null),
    'catalog', public._platform_automation_catalog(),
    'modules', (select jsonb_agg(jsonb_build_object('code', code, 'name', name, 'actions', actions) order by sort_order) from public.platform_modules),
    'can', jsonb_build_object('create', public.platform_can('automation', 'create'), 'edit', public.platform_can('automation', 'edit'),
      'delete', public.platform_can('automation', 'delete'), 'manage', public.platform_can('automation', 'manage')));
end;

platform_automation_run.src:
declare
  r public.platform_automation_rules;
  s record;
  v_out jsonb := '[]'::jsonb;
  v_acted int;
  v_failed int;
  v_skipped int;
  v_run bigint;
  v_done jsonb;
  v_manual boolean := not public.is_system_context();
begin
  if v_manual then
    perform public._platform_require('automation', 'manage');
  end if;
  for r in select * from public.platform_automation_rules x
           where x.archived_at is null and (p_rule is null and x.enabled or x.id = p_rule) order by x.created_at loop
    -- Two runs of one rule never overlap.
    if not pg_try_advisory_xact_lock(hashtextextended('automation:' || r.id, 0)) then
      v_out := v_out || jsonb_build_object('rule', r.id, 'skipped', 'already running');
      continue;
    end if;
    v_acted := 0; v_failed := 0; v_skipped := 0;
    for s in select * from public._platform_automation_subjects(r) loop
      -- Once per subject per cooldown, whatever happened last time.
      if exists (select 1 from public.platform_automation_runs x where x.rule_id = r.id and x.subject_key = s.subject_key
                 and x.created_at > now() - make_interval(mins => r.cooldown_minutes)) then
        v_skipped := v_skipped + 1;
        continue;
      end if;
      if v_acted + v_failed >= r.max_actions_per_run then
        v_skipped := v_skipped + 1;
        continue;
      end if;
      select coalesce(max(id), 0) + 1 into v_run from public.platform_automation_runs;
      begin
        v_done := public._platform_automation_act(r, to_jsonb(s), v_run);
        insert into public.platform_automation_runs (rule_id, subject_key, merchant_id, title, status, actions, manual, actor_id)
        values (r.id, s.subject_key, s.merchant_id, s.title, 'ACTED', v_done, v_manual, auth.uid());
        v_acted := v_acted + 1;
      exception when others then
        insert into public.platform_automation_runs (rule_id, subject_key, merchant_id, title, status, error, manual, actor_id)
        values (r.id, s.subject_key, s.merchant_id, s.title, 'FAILED', left(sqlerrm, 1000), v_manual, auth.uid());
        v_failed := v_failed + 1;
      end;
    end loop;
    update public.platform_automation_rules set last_run_at = now(),
      last_result = jsonb_build_object('acted', v_acted, 'failed', v_failed, 'skipped', v_skipped, 'manual', v_manual)
    where id = r.id;
    v_out := v_out || jsonb_build_object('rule', r.id, 'name', r.name, 'acted', v_acted, 'failed', v_failed, 'skipped', v_skipped);
  end loop;
  if v_manual then
    perform public._platform_log('automation.run', null, 'automation_rule', p_rule::text, null, null, jsonb_build_object('results', v_out));
  end if;
  return v_out;
end;

platform_automation_runs_list.src:
begin
  perform public._platform_require('automation', 'view');
  return coalesce((select jsonb_agg(jsonb_build_object('id', x.id, 'rule', jsonb_build_object('id', r.id, 'name', r.name), 'subject', x.subject_key, 'title', x.title,
      'merchant', (select jsonb_build_object('id', m.id, 'number', m.number, 'name', m.name) from public.merchants m where m.id = x.merchant_id),
      'status', x.status, 'actions', x.actions, 'error', x.error, 'manual', x.manual, 'created_at', x.created_at) order by x.id desc)
    from (select * from public.platform_automation_runs where p_rule is null or rule_id = p_rule order by id desc limit least(greatest(coalesce(p_limit, 100), 1), 500)) x
    join public.platform_automation_rules r on r.id = x.rule_id), '[]'::jsonb);
end;

platform_automation_test.src:
declare
  r public.platform_automation_rules;
begin
  perform public._platform_require('automation', 'view');
  if nullif(p ->> 'id', '') is not null and p ->> 'trigger' is null then
    select * into r from public.platform_automation_rules where id = (p ->> 'id')::uuid;
  else
    perform public._platform_automation_validate(p);
    r := jsonb_populate_record(null::public.platform_automation_rules, jsonb_build_object('id', coalesce(nullif(p ->> 'id', '')::uuid, gen_random_uuid()),
      'name', p ->> 'name', 'trigger', p ->> 'trigger', 'conditions', coalesce(p -> 'conditions', '{}'::jsonb), 'actions', p -> 'actions',
      'cooldown_minutes', coalesce((p ->> 'cooldown_minutes')::int, 1440), 'max_actions_per_run', coalesce((p ->> 'max_actions_per_run')::int, 25)));
  end if;
  if r.trigger is null then
    raise exception 'NOT_FOUND: rule not found' using errcode = 'P0002';
  end if;
  return (with s as (select * from public._platform_automation_subjects(r))
    select jsonb_build_object(
      'matches', (select count(*) from s),
      'would_act', (select count(*) from (select 1 from s where not exists (select 1 from public.platform_automation_runs x where x.rule_id = r.id
                      and x.subject_key = s.subject_key and x.created_at > now() - make_interval(mins => r.cooldown_minutes)) limit r.max_actions_per_run) q),
      'subjects', (select coalesce(jsonb_agg(jsonb_build_object('key', s.subject_key, 'title', s.title, 'detail', s.detail,
          'in_cooldown', exists (select 1 from public.platform_automation_runs x where x.rule_id = r.id and x.subject_key = s.subject_key
                                 and x.created_at > now() - make_interval(mins => r.cooldown_minutes)))), '[]'::jsonb)
        from (select * from s limit 50) s),
      'actions', r.actions));
end;

platform_bd_courier_set_connection.src:
declare
  v jsonb;
begin
  if not public.is_system_context() then
    raise exception 'PERMISSION_DENIED' using errcode = '42501';
  end if;
  update public.platform_settings set value = value
    || case when p_service is null and p_test_ok is null then jsonb_build_object('connected', false, 'service', null, 'hint', null, 'connected_at', null)
            when p_service is not null then jsonb_build_object('connected', true, 'service', p_service, 'hint', p_hint, 'connected_at', now())
            else '{}'::jsonb end
    || case when p_test_ok is not null then jsonb_build_object('last_test_at', now(), 'last_test_ok', p_test_ok, 'last_error', left(p_error, 300)) else '{}'::jsonb end,
    updated_by = coalesce(p_actor, updated_by)
  where key = 'bd_courier' returning value into v;
  if p_service is not null or p_test_ok is null then
    perform public._platform_log(case when p_service is null then 'bd_courier.disconnected' else 'bd_courier.connected' end, null, 'platform_credential',
      'bd_courier', null, null, jsonb_build_object('service', p_service, 'hint', p_hint));
  end if;
  return v;
end;

platform_billing_gateway_set.src:
declare
  v jsonb;
begin
  if not public.is_system_context() then
    raise exception 'PERMISSION_DENIED' using errcode = '42501';
  end if;
  if p_provider not in ('bkash', 'paystation') then
    raise exception 'VALIDATION: unknown gateway' using errcode = '22023';
  end if;
  update public.platform_settings set value = jsonb_set(value, array[p_provider],
      coalesce(value -> p_provider, '{}'::jsonb) || jsonb_build_object('connected', p_connected, 'enabled', p_connected, 'hint', p_hint,
        'sandbox', coalesce(p_sandbox, (value -> p_provider ->> 'sandbox')::boolean, true), 'connected_at', case when p_connected then now() end)),
    updated_by = p_actor
  where key = 'billing_gateways' returning value into v;
  perform public._platform_log(case when p_connected then 'billing.gateway_connected' else 'billing.gateway_disconnected' end, null, 'platform_credential',
    'gateway.' || p_provider, null, null, jsonb_build_object('hint', p_hint, 'sandbox', p_sandbox));
  return v;
end;

platform_billing_gateway_toggle.src:
declare
  v jsonb;
begin
  perform public._platform_require('subscriptions', 'manage');
  if p_enabled and not coalesce((select (value -> p_provider ->> 'connected')::boolean from public.platform_settings where key = 'billing_gateways'), false) then
    raise exception 'VALIDATION: connect the gateway account first' using errcode = '22023';
  end if;
  update public.platform_settings set value = jsonb_set(value, array[p_provider, 'enabled'], to_jsonb(p_enabled)), updated_by = auth.uid()
  where key = 'billing_gateways' and value ? p_provider returning value into v;
  perform public._platform_log('billing.gateway_' || case when p_enabled then 'enabled' else 'disabled' end, null, 'platform_setting', 'billing_gateways', null, null, v);
