platform_contact_submit.src:
declare
  v_name text := trim(coalesce(p ->> 'name', ''));
  v_email text := nullif(lower(trim(coalesce(p ->> 'email', ''))), '');
  v_phone text := nullif(trim(coalesce(p ->> 'phone', '')), '');
  v_message text := trim(coalesce(p ->> 'message', ''));
  v_topic text := upper(coalesce(nullif(trim(p ->> 'topic'), ''), 'GENERAL'));
  v_id bigint;
begin
  if char_length(v_name) < 2 then
    raise exception 'VALIDATION: enter your name' using errcode = '22023';
  end if;
  if v_email is null and v_phone is null then
    raise exception 'VALIDATION: enter an e-mail address or a phone number so we can reply' using errcode = '22023';
  end if;
  if v_email is not null and v_email !~* '^[^@\s]+@[^@\s]+\.[^@\s]+$' then
    raise exception 'VALIDATION: this e-mail address does not look right' using errcode = '22023';
  end if;
  if v_phone is not null and v_phone !~ '^[+0-9 -]{6,20}$' then
    raise exception 'VALIDATION: this phone number does not look right' using errcode = '22023';
  end if;
  if char_length(v_message) < 10 then
    raise exception 'VALIDATION: tell us a little more (at least 10 characters)' using errcode = '22023';
  end if;
  if v_topic not in ('SALES', 'SUPPORT', 'PARTNERSHIP', 'GENERAL') then v_topic := 'GENERAL'; end if;
  -- Flood protection: per reply address, and overall.
  if (select count(*) from public.platform_contact_messages
      where created_at > now() - interval '1 hour'
        and ((v_email is not null and email = v_email) or (v_phone is not null and phone = v_phone))) >= 3
     or (select count(*) from public.platform_contact_messages where created_at > now() - interval '10 minutes') >= 60 then
    raise exception 'RATE_LIMITED: we already have your message; we will reply soon' using errcode = 'P0001';
  end if;
  insert into public.platform_contact_messages (name, email, phone, business, topic, message, page)
  values (left(v_name, 100), v_email, v_phone, nullif(left(trim(coalesce(p ->> 'business', '')), 120), ''), v_topic,
          left(v_message, 4000), nullif(left(trim(coalesce(p ->> 'page', '')), 200), ''))
  returning id into v_id;
  return jsonb_build_object('id', v_id);
end;

platform_cost_assumptions_save.src:
declare
  v_before jsonb := coalesce((select value from public.platform_settings where key = 'cost_assumptions'), '{}'::jsonb);
  v_after jsonb;
  k text;
begin
  perform public._platform_require('subscriptions', 'manage');
  v_after := v_before || coalesce(p, '{}'::jsonb);
  foreach k in array array['bd_courier_per_lookup', 'payment_fee_percent'] loop
    if jsonb_typeof(v_after -> k) not in ('null', 'number') or coalesce((v_after ->> k)::numeric, 0) < 0
       or (k = 'payment_fee_percent' and coalesce((v_after ->> k)::numeric, 0) > 20) then
      raise exception 'VALIDATION: % must be empty (unknown) or a positive number', replace(k, '_', ' ') using errcode = '22023';
    end if;
  end loop;
  v_after := jsonb_build_object('bd_courier_per_lookup', v_after -> 'bd_courier_per_lookup', 'payment_fee_percent', v_after -> 'payment_fee_percent');
  insert into public.platform_settings (key, value, updated_by) values ('cost_assumptions', v_after, auth.uid())
  on conflict (key) do update set value = excluded.value, updated_by = excluded.updated_by;
  perform public._config_version('platform_setting', 'cost_assumptions', v_after, p_reason);
  perform public._platform_log('analytics.cost_assumptions_changed', null, 'platform_setting', 'cost_assumptions', p_reason, v_before, v_after);
  return v_after;
end;

platform_cost_entries_list.src:
begin
  perform public._platform_require('subscriptions', 'view');
  return jsonb_build_object(
    'entries', coalesce((select jsonb_agg(to_jsonb(e) order by e.month desc, e.id desc) from public.platform_cost_entries e
                         where (p_from is null or e.month >= date_trunc('month', p_from)) and (p_to is null or e.month <= p_to)), '[]'::jsonb),
    'assumptions', public._platform_cost_assumptions(),
    'can_manage', public.platform_can('subscriptions', 'manage'));
end;

platform_cost_entry_add.src:
declare
  v_month date := date_trunc('month', nullif(p ->> 'month', '')::date)::date;
  v_amount numeric := nullif(p ->> 'amount', '')::numeric;
  v_corrects bigint := nullif(p ->> 'corrects', '')::bigint;
  e public.platform_cost_entries;
begin
  perform public._platform_require('subscriptions', 'manage');
  if v_month is null or v_month > date_trunc('month', now())::date or v_month < date '2020-01-01' then
    raise exception 'VALIDATION: choose the month the cost is for (not in the future)' using errcode = '22023';
  end if;
  if v_amount is null or v_amount = 0 or abs(v_amount) > 100000000 then
    raise exception 'VALIDATION: enter the amount (negative only to correct an earlier entry)' using errcode = '22023';
  end if;
  if v_amount < 0 and v_corrects is null then
    raise exception 'VALIDATION: a negative amount must say which entry it corrects' using errcode = '22023';
  end if;
  if v_corrects is not null and not exists (select 1 from public.platform_cost_entries where id = v_corrects) then
    raise exception 'VALIDATION: the entry being corrected does not exist' using errcode = '22023';
  end if;
  insert into public.platform_cost_entries (month, category, amount, note, corrects, recorded_by, recorded_by_email)
  values (v_month, upper(coalesce(p ->> 'category', '')), round(v_amount, 2), trim(coalesce(p ->> 'note', '')), v_corrects, auth.uid(),
          (select email from public.platform_staff where user_id = auth.uid()))
  returning * into e;
  perform public._platform_log('analytics.cost_recorded', null, 'platform_cost_entry', e.id::text, e.note, null, to_jsonb(e));
  return to_jsonb(e);
end;

platform_credit_adjust.src:
declare
  v_threshold int := coalesce((select (value ->> 'approval_threshold')::int from public.platform_settings where key = 'credits'), 1000);
  v_key text := 'admin:' || coalesce(p_request_id, gen_random_uuid());
  v_name text := (select name from public.merchants where id = p_merchant);
  e public.credit_ledger;
  v_approval uuid;
begin
  if p_kind = 'PROMO' then
    perform public._platform_require('credits', 'create', p_merchant);
    if p_amount is null or p_amount <= 0 then
      raise exception 'VALIDATION: promotional credits are added, not removed' using errcode = '22023';
    end if;
  elsif p_kind = 'ADJUSTMENT' then
    perform public._platform_require('credits', 'manage', p_merchant);
  else
    raise exception 'VALIDATION: choose a promotional grant or an adjustment' using errcode = '22023';
  end if;
  if v_name is null then
    raise exception 'NOT_FOUND: merchant not found' using errcode = 'P0002';
  end if;
  if not exists (select 1 from public.credit_types where code = p_type) then
    raise exception 'VALIDATION: unknown credit type' using errcode = '22023';
  end if;
  if p_amount is null or p_amount = 0 or abs(p_amount) > (case when p_type = 'BALANCE' then 100000000 else 1000000 end) then
    raise exception 'VALIDATION: enter an amount between 1 and 1,000,000' using errcode = '22023';
  end if;
  if coalesce(length(trim(p_reason)), 0) < 5 then
    raise exception 'VALIDATION: give a reason (at least 5 characters)' using errcode = '22023';
  end if;
  if p_expires_at is not null and (p_amount < 0 or p_expires_at <= now()) then
    raise exception 'VALIDATION: an expiry date must be in the future, and only for added credits' using errcode = '22023';
  end if;
  if abs(p_amount) > (case when p_type = 'BALANCE'
       then coalesce((select (value ->> 'balance_approval_threshold_tk')::numeric from public.platform_settings where key = 'credits'), 50000) * 100
       else v_threshold end) then
    v_approval := public.platform_request_approval('credits', 'credit_adjust', p_merchant,
      format('%s %s %s credits %s %s', case when p_amount > 0 then 'Add' else 'Remove' end, abs(p_amount), p_type,
             case when p_amount > 0 then 'to' else 'from' end, v_name),
      jsonb_build_object('credit_type', p_type, 'amount', p_amount, 'kind', p_kind, 'expires_at', p_expires_at, 'key', v_key), p_reason);
    return jsonb_build_object('pending_approval', v_approval);
  end if;
  -- The same request sent again (double click, retry): the first result, logged once.
  select * into e from public.credit_ledger where merchant_id = p_merchant and idempotency_key = v_key;
  if e.id is not null then
    return to_jsonb(e);
  end if;
  e := public._credit_post(p_merchant, p_type, p_amount, p_kind, trim(p_reason), auth.uid(), 'PLATFORM', 'platform_adjustment', null, v_key, p_expires_at);
  perform public._platform_log('credits.' || lower(p_kind), p_merchant, 'credit_ledger', e.id::text, p_reason, null,
    jsonb_build_object('credit_type', p_type, 'amount', p_amount, 'balance_after', e.balance_after, 'expires_at', p_expires_at));
  return to_jsonb(e);
end;

platform_credit_package_save.src:
declare
  v public.credit_packages;
  v_before jsonb;
  v_id uuid := nullif(p ->> 'id', '')::uuid;
begin
  perform public._platform_require('credits', 'manage');
  if v_id is null then
    insert into public.credit_packages (credit_type, name, credits, bonus_credits, price, sort_order, created_by)
    values (p ->> 'credit_type', trim(p ->> 'name'), (p ->> 'credits')::int, coalesce((p ->> 'bonus_credits')::int, 0), (p ->> 'price')::numeric,
            coalesce((p ->> 'sort_order')::int, 100), auth.uid())
    returning * into v;
  else
    select to_jsonb(k) into v_before from public.credit_packages k where id = v_id;
    update public.credit_packages set name = coalesce(nullif(trim(p ->> 'name'), ''), name), credits = coalesce((p ->> 'credits')::int, credits),
      bonus_credits = coalesce((p ->> 'bonus_credits')::int, bonus_credits), price = coalesce((p ->> 'price')::numeric, price),
      status = coalesce(p ->> 'status', status), sort_order = coalesce((p ->> 'sort_order')::int, sort_order)
    where id = v_id returning * into v;
    if v.id is null then
      raise exception 'NOT_FOUND: package not found' using errcode = 'P0002';
    end if;
  end if;
  perform public._platform_log(case when v_id is null then 'credits.package_created' else 'credits.package_updated' end, null, 'credit_package', v.id::text,
    p ->> 'note', v_before, to_jsonb(v));
  return to_jsonb(v);
end;

platform_deletion_request_cancel.src:
declare
  r public.merchant_deletion_requests;
begin
  select * into r from public.merchant_deletion_requests where id = p_id for update;
  if r.id is null then
    raise exception 'NOT_FOUND: request not found' using errcode = 'P0002';
  end if;
  perform public._platform_require('data', 'manage', r.merchant_id);
  if r.status not in ('REQUESTED', 'APPROVED') or length(trim(coalesce(p_reason, ''))) < 5 then
    raise exception 'VALIDATION: only an open request can be cancelled, with a reason' using errcode = '22023';
  end if;
  update public.merchant_deletion_requests set status = 'CANCELLED', decision_note = trim(p_reason) where id = p_id returning * into r;
  perform public._platform_log('data.deletion_cancelled', r.merchant_id, 'deletion_request', r.id::text, trim(p_reason), null, null);
  return public._deletion_request_json(r);
end;

platform_deletion_request_create.src:
declare
  r public.merchant_deletion_requests;
begin
  perform public._platform_require('data', 'manage', p_merchant);
  if length(trim(coalesce(p_reason, ''))) < 5 then
    raise exception 'VALIDATION: say who asked and how (at least 5 characters)' using errcode = '22023';
  end if;
  if exists (select 1 from public.merchant_deletion_requests where merchant_id = p_merchant and status in ('REQUESTED', 'APPROVED')) then
    raise exception 'VALIDATION: a request is already open for this merchant' using errcode = '22023';
  end if;
  insert into public.merchant_deletion_requests (merchant_id, source, reason, requested_by, requested_by_email)
  values (p_merchant, 'PLATFORM', trim(p_reason), auth.uid(), (select email from public.platform_staff where user_id = auth.uid()))
  returning * into r;
  perform public._platform_log('data.deletion_requested', p_merchant, 'deletion_request', r.id::text, trim(p_reason), null, jsonb_build_object('number', r.number));
  return public._deletion_request_json(r);
end;

platform_deletion_request_decide.src:
declare
  r public.merchant_deletion_requests;
  v_days int := coalesce((select (value ->> 'deletion_cooling_days')::int from public.platform_settings where key = 'retention'), 14);
begin
  select * into r from public.merchant_deletion_requests where id = p_id for update;
  if r.id is null then
    raise exception 'NOT_FOUND: request not found' using errcode = 'P0002';
  end if;
  perform public._platform_require('data', 'approve', r.merchant_id);
  if r.status <> 'REQUESTED' then
    raise exception 'VALIDATION: this request was already decided' using errcode = '22023';
  end if;
  if r.requested_by = auth.uid() then
    raise exception 'VALIDATION: someone other than the person who recorded it must decide' using errcode = '22023';
  end if;
  if length(trim(coalesce(p_note, ''))) < 5 then
    raise exception 'VALIDATION: note how the request was verified (at least 5 characters)' using errcode = '22023';
  end if;
  update public.merchant_deletion_requests set status = case when p_approve then 'APPROVED' else 'REJECTED' end, decided_by = auth.uid(), decided_at = now(),
    decision_note = trim(p_note), erase_after = case when p_approve then now() + make_interval(days => v_days) end
  where id = p_id returning * into r;
  perform public._platform_log(case when p_approve then 'data.deletion_approved' else 'data.deletion_rejected' end, r.merchant_id, 'deletion_request', r.id::text,
    trim(p_note), null, jsonb_build_object('erase_after', r.erase_after));
  return public._deletion_request_json(r);
end;

platform_deletion_request_execute.src:
declare
  r public.merchant_deletion_requests;
  m public.merchants;
  v_result jsonb;
begin
  select * into r from public.merchant_deletion_requests where id = p_id for update;
  if r.id is null then
    raise exception 'NOT_FOUND: request not found' using errcode = 'P0002';
  end if;
  perform public._platform_require('data', 'manage', r.merchant_id);
  select * into m from public.merchants where id = r.merchant_id;
  if r.status <> 'APPROVED' then
    raise exception 'VALIDATION: only an approved request can be carried out' using errcode = '22023';
  end if;
  if r.erase_after > now() then
    raise exception 'VALIDATION: the waiting period ends %', to_char(r.erase_after at time zone 'Asia/Dhaka', 'DD Mon YYYY HH24:MI') using errcode = '22023';
  end if;
  if r.decided_by = auth.uid() then
    raise exception 'VALIDATION: the person who approved it cannot also erase the data' using errcode = '22023';
  end if;
  if m.status <> 'CLOSED' then
    raise exception 'VALIDATION: close the merchant''s account first (Merchants → status)' using errcode = '22023';
  end if;
  if p_confirm is distinct from m.name then
    raise exception 'VALIDATION: type the merchant''s name exactly to confirm' using errcode = '22023';
  end if;
  v_result := public._merchant_erase_personal_data(m.id, r.id);
  update public.merchant_deletion_requests set status = 'COMPLETED', completed_by = auth.uid(), completed_at = now(), result = v_result
  where id = p_id returning * into r;
  perform public._platform_log('data.erased', m.id, 'deletion_request', r.id::text, r.reason, null, v_result);
  return public._deletion_request_json(r);
end;

platform_export_record.src:
declare
  v_id bigint;
begin
  case p_kind
    when 'MERCHANTS' then perform public._platform_require('merchants', 'export');
    when 'AUDIT' then perform public._platform_require('audit', 'export');
    when 'USAGE', 'REVENUE' then perform public._platform_require('usage', 'export');
    else raise exception 'VALIDATION: unknown export' using errcode = '22023';
  end case;
  insert into public.platform_data_exports (kind, merchant_id, actor_id, actor_email, detail)
  values (p_kind, p_merchant, auth.uid(), (select email from public.platform_staff where user_id = auth.uid()), coalesce(p_detail, '{}'::jsonb))
  returning id into v_id;
  perform public._platform_log('data.export', p_merchant, 'export', v_id::text, null, null, jsonb_build_object('kind', p_kind) || coalesce(p_detail, '{}'::jsonb));
  return v_id;
end;

platform_feature_bulk_apply.src:
declare
  m uuid;
  v_n int := 0;
begin
  perform public._platform_require('features', 'edit');
  if p_token is distinct from md5(p_code || ':' || coalesce(p_enabled::text, 'plan') || ':' || array_to_string(array(select unnest(p_merchants)::text order by 1), ',')) then
    raise exception 'VALIDATION: review the list of merchants first' using errcode = '22023';
  end if;
  foreach m in array p_merchants loop
    continue when not public.platform_can('features', 'edit', m);
    perform public.platform_merchant_feature_set(m, p_code, p_enabled, p_reason);
    v_n := v_n + 1;
  end loop;
  return jsonb_build_object('changed', v_n);
end;

platform_feature_bulk_preview.src:
begin
  perform public._platform_require('features', 'edit');
  return jsonb_build_object(
    'items', coalesce((select jsonb_agg(jsonb_build_object('id', m.id, 'number', m.number, 'name', m.name,
        'now', public.merchant_entitlements(m.id) -> p_code ->> 'state', 'allowed', public.platform_can('features', 'edit', m.id)) order by m.number)
      from public.merchants m where m.id = any (p_merchants)), '[]'::jsonb),
    'token', md5(p_code || ':' || coalesce(p_enabled::text, 'plan') || ':' || array_to_string(array(select unnest(p_merchants)::text order by 1), ',')));
end;

platform_feature_save.src:
declare
  v_before public.features;
  v public.features;
begin
  perform public._platform_require('features', 'manage');
  select * into v_before from public.features where code = p_code for update;
  if v_before.code is null then
    raise exception 'NOT_FOUND: feature not found' using errcode = 'P0002';
  end if;
  if v_before.is_core and (p ->> 'globally_enabled')::boolean is false then
    raise exception 'VALIDATION: % runs the order workflow and cannot be switched off', v_before.name using errcode = '22023';
  end if;
  update public.features set globally_enabled = coalesce((p ->> 'globally_enabled')::boolean, globally_enabled),
    release_stage = coalesce(p ->> 'release_stage', release_stage), updated_by = auth.uid(), updated_at = now()
  where code = p_code returning * into v;
  perform public._config_version('feature', p_code, to_jsonb(v), p ->> 'reason');
  perform public._platform_log('features.global_changed', null, 'feature', p_code, p ->> 'reason', to_jsonb(v_before), to_jsonb(v));
  return to_jsonb(v);
end;

platform_global_settings.src:
begin
  perform public._platform_require('settings', 'view');
  return jsonb_build_object(
    'settings', (select coalesce(jsonb_object_agg(s.key, jsonb_build_object('value', s.value, 'description', s.description, 'updated_at', s.updated_at,
        'last_change', (select jsonb_build_object('id', v.id, 'at', v.changed_at, 'note', v.note,
            'by', (select coalesce(nullif(trim(p.full_name), ''), p.email) from public.platform_staff p where p.user_id = v.changed_by))
          from public.config_versions v where v.kind in ('platform_setting', 'access_rules') and v.ref = s.key order by v.id desc limit 1))), '{}'::jsonb)
      from public.platform_settings s),
    'releases', (select coalesce(jsonb_agg(jsonb_build_object('code', f.code, 'name', f.name, 'stage', f.release_stage, 'globally_enabled', f.globally_enabled,
        'enrolled', (select count(*) from public.merchant_features mf where mf.feature_code = f.code and mf.enabled and (mf.expires_at is null or mf.expires_at > now())),
        'enrolled_demo', (select count(*) from public.merchant_features mf join public.merchants m on m.id = mf.merchant_id
                          where mf.feature_code = f.code and mf.enabled and m.is_demo and (mf.expires_at is null or mf.expires_at > now())))
        order by f.release_stage, f.sort_order), '[]'::jsonb)
      from public.features f where f.release_stage <> 'GA' or not f.globally_enabled),
    'demo_merchants', (select count(*) from public.merchants where is_demo and status <> 'CLOSED'),
    'can', jsonb_build_object('edit', public.platform_can('settings', 'edit'), 'security', public.platform_can('security', 'manage'),
      'data', public.platform_can('data', 'manage')));
end;

platform_health.src:
declare
  v jsonb := '[]'::jsonb;
  v_ids uuid[];
  v_n1 bigint;
  v_n2 bigint;
  v_n3 bigint;
  v_at timestamptz;
  v_at2 timestamptz;
  v_cron jsonb;
  v_sms jsonb := coalesce((select value from public.platform_settings where key = 'sms'), '{}'::jsonb);
  v_bd jsonb := coalesce((select value from public.platform_settings where key = 'bd_courier'), '{}'::jsonb);
begin
  perform public._platform_require('health', 'view');
  select coalesce(array_agg(id), '{}') into v_ids from public.merchants where id in (select public._platform_merchant_ids());

  -- Database: it answered this query; connections and size are measured.
  select count(*) into v_n1 from pg_stat_activity where datname = current_database();
  v := v || jsonb_build_object('key', 'database', 'group', 'Platform', 'name', 'Database',
    'status', case when v_n1 > current_setting('max_connections')::int * 0.8 then 'warn' else 'ok' end,
    'detail', format('Responding · %s of %s connections in use · %s', v_n1, current_setting('max_connections'), pg_size_pretty(pg_database_size(current_database()))),
    'check', 'Ran this check against the database and read its connection count', 'at', now());

  -- Scheduled jobs (pg_cron): the latest run of each job.
  if to_regclass('cron.job_run_details') is not null then
    execute $q$
      select jsonb_build_object(
        'jobs', coalesce(jsonb_agg(jsonb_build_object('name', j.jobname, 'schedule', j.schedule, 'active', j.active,
          'last_status', l.status, 'last_end', l.end_time, 'last_message', left(l.return_message, 200),
          'runs_24h', (select count(*) from cron.job_run_details d where d.jobid = j.jobid and d.start_time > now() - interval '24 hours'),
          'failed_24h', (select count(*) from cron.job_run_details d where d.jobid = j.jobid and d.start_time > now() - interval '24 hours' and d.status = 'failed'))
          order by j.jobname), '[]'::jsonb))
      from cron.job j
      left join lateral (select d.status, d.end_time, d.return_message from cron.job_run_details d where d.jobid = j.jobid order by d.start_time desc limit 1) l on true
    $q$ into v_cron;
    v := v || jsonb_build_object('key', 'cron', 'group', 'Background jobs', 'name', 'Scheduled tasks',
      'status', case when jsonb_array_length(v_cron -> 'jobs') = 0 then 'unknown'
                     when exists (select 1 from jsonb_array_elements(v_cron -> 'jobs') x where x ->> 'last_status' = 'failed') then 'warn'
                     when not exists (select 1 from jsonb_array_elements(v_cron -> 'jobs') x where x ->> 'last_end' is not null) then 'idle'
                     else 'ok' end,
      'detail', format('%s job(s) scheduled · %s with a failed latest run', jsonb_array_length(v_cron -> 'jobs'),
        (select count(*) from jsonb_array_elements(v_cron -> 'jobs') x where x ->> 'last_status' = 'failed')),
      'check', 'Latest run of each pg_cron job', 'jobs', v_cron -> 'jobs',
      'at', (select max((x ->> 'last_end')::timestamptz) from jsonb_array_elements(v_cron -> 'jobs') x));
  else
    v := v || jsonb_build_object('key', 'cron', 'group', 'Background jobs', 'name', 'Scheduled tasks', 'status', 'unknown',
      'detail', 'pg_cron is not installed here, so scheduled tasks cannot be checked', 'check', 'Looks for the pg_cron run history', 'at', null);
  end if;

  -- Store sync jobs: failures and jobs waiting longer than they should.
  select count(*) filter (where status = 'FAILED' and updated_at > now() - interval '24 hours'),
         count(*) filter (where status = 'PENDING' and next_attempt_at < now() - interval '15 minutes'),
         max(done_at), min(next_attempt_at) filter (where status = 'PENDING')
    into v_n1, v_n2, v_at, v_at2
  from public.channel_sync_jobs where merchant_id = any (v_ids);
  v := v || jsonb_build_object('key', 'store_sync', 'group', 'Background jobs', 'name', 'Store sync jobs (Shopify / WooCommerce)',
    'status', case when v_n2 > 20 then 'down' when v_n1 > 0 or v_n2 > 0 then 'warn' when v_at is null then 'idle' else 'ok' end,
    'detail', format('%s failed in 24 h · %s waiting over 15 min%s', v_n1, v_n2,
      case when v_at2 < now() - interval '15 minutes' then ' · oldest waiting since ' || to_char(v_at2 at time zone 'Asia/Dhaka', 'DD Mon HH24:MI') else '' end),
    'check', 'Failed and overdue jobs in the store sync queue', 'at', v_at, 'retry', 'store_jobs', 'retryable', v_n1);

  -- Webhooks in: courier status updates and errors logged by webhook handlers.
  select count(*) filter (where result in ('FAILED', 'UNMATCHED') and received_at > now() - interval '24 hours'),
         count(*) filter (where result in ('FAILED', 'UNMATCHED') and attempts < 6 and received_at > now() - interval '7 days'),
         max(received_at)
    into v_n1, v_n2, v_at
  from public.courier_webhook_events where merchant_id = any (v_ids);
  select count(*) into v_n3 from public.system_logs where category = 'WEBHOOK' and level = 'ERROR' and resolved_at is null
    and last_seen_at > now() - interval '24 hours' and (merchant_id is null or merchant_id = any (v_ids));
  v := v || jsonb_build_object('key', 'webhooks', 'group', 'Integrations', 'name', 'Webhooks (couriers, stores)',
    'status', case when v_n1 + v_n3 > 0 then 'warn' when v_at is null then 'idle' else 'ok' end,
    'detail', format('%s courier update(s) failed in 24 h · %s webhook error(s) logged in 24 h', v_n1, v_n3),
    'check', 'Courier webhook results and webhook errors in the system log', 'at', v_at, 'retry', 'courier_webhooks', 'retryable', v_n2);

  -- SMS: queue backlog and sending.
  select count(*) filter (where status = 'QUEUED' and next_attempt_at < now() - interval '15 minutes'),
         count(*) filter (where status = 'FAILED' and created_at > now() - interval '24 hours'),
         max(sent_at)
    into v_n1, v_n2, v_at
  from public.notification_logs where channel = 'SMS' and merchant_id = any (v_ids);
  v := v || jsonb_build_object('key', 'sms_queue', 'group', 'Queues', 'name', 'SMS queue',
    'status', case when v_n1 > 50 then 'down' when v_n1 > 0 or v_n2 > 0 then 'warn' when v_at is null then 'idle' else 'ok' end,
    'detail', format('%s waiting over 15 min · %s failed in 24 h%s', v_n1, v_n2, case when v_at is not null then ' · last sent ' || to_char(v_at at time zone 'Asia/Dhaka', 'DD Mon HH24:MI') else '' end),
    'check', 'Messages waiting past their send time, and failures', 'at', v_at);

  select count(*) filter (where status = 'SUCCEEDED'), count(*) filter (where status = 'FAILED'), max(finished_at) filter (where status = 'SUCCEEDED')
    into v_n1, v_n2, v_at
  from public.service_usage where service = 'SMS' and created_at > now() - interval '24 hours';
  v := v || jsonb_build_object('key', 'sms_provider', 'group', 'Providers', 'name', 'SMS provider',
    'status', case when not coalesce((v_sms ->> 'connected')::boolean, false) then 'down'
                   when v_n1 + v_n2 = 0 then 'idle'
                   when v_n2 > v_n1 then 'down' when v_n2 > 0 then 'warn' else 'ok' end,
    'detail', case when not coalesce((v_sms ->> 'connected')::boolean, false) then 'Not connected — merchants cannot send SMS'
                   else format('%s sent, %s failed in 24 h', v_n1, v_n2) end,
    'check', 'Connection state and the provider''s answers to real messages in the last 24 h', 'at', v_at);

  select count(*) filter (where status = 'SUCCEEDED'), count(*) filter (where status = 'FAILED'), max(finished_at) filter (where status = 'SUCCEEDED')
    into v_n1, v_n2, v_at
  from public.service_usage where service = 'BD_COURIER' and created_at > now() - interval '24 hours';
  v := v || jsonb_build_object('key', 'bd_courier', 'group', 'Providers', 'name', 'BD Courier',
    'status', case when not coalesce((v_bd ->> 'connected')::boolean, false) then 'down'
                   when v_n1 + v_n2 = 0 then case when (v_bd ->> 'last_test_ok')::boolean is false then 'down' else 'idle' end
                   when v_n2 > v_n1 then 'down' when v_n2 > 0 then 'warn' else 'ok' end,
    'detail', case when not coalesce((v_bd ->> 'connected')::boolean, false) then 'Not connected — checkouts use each store''s own history'
                   else format('%s lookups, %s failed in 24 h', v_n1, v_n2) || coalesce(' · last test ' || case when (v_bd ->> 'last_test_ok')::boolean then 'worked' else 'failed' end, '') end,
    'check', 'Connection state and real lookups in the last 24 h', 'at', v_at);

  -- Payment callbacks: gateway payments that never came back, and logged payment errors.
  select count(*) into v_n1 from public.billing_payments where method = 'GATEWAY' and status = 'PENDING' and created_at < now() - interval '30 minutes'
    and merchant_id = any (v_ids);
  select count(*) into v_n2 from public.pbx_bkash_transactions where status = 'PENDING' and payment_id is not null and created_at < now() - interval '30 minutes'
    and merchant_id = any (v_ids);
  select count(*) into v_n3 from public.system_logs where category = 'PAYMENT' and level = 'ERROR' and resolved_at is null
    and last_seen_at > now() - interval '24 hours' and (merchant_id is null or merchant_id = any (v_ids));
  v := v || jsonb_build_object('key', 'payments', 'group', 'Integrations', 'name', 'Payment callbacks',
    'status', case when v_n1 + v_n2 + v_n3 > 0 then 'warn'
                   when not exists (select 1 from public.billing_payments where method = 'GATEWAY') and not exists (select 1 from public.payment_events) then 'idle'
                   else 'ok' end,
    'detail', format('%s platform payment(s) and %s PBX payment(s) without a confirmation after 30 min · %s payment error(s) in 24 h', v_n1, v_n2, v_n3),
    'check', 'Gateway payments still waiting for their callback, and payment errors', 'at', null);

  -- VoiceDrive gateway heartbeat.
  select last_seen_at into v_at from public.pbx_gateway_status;
  v := v || jsonb_build_object('key', 'pbx_gateway', 'group', 'Providers', 'name', 'VoiceDrive PBX gateway',
    'status', case when v_at is null then 'idle' when v_at > now() - interval '2 minutes' then 'ok' else 'down' end,
    'detail', case when v_at is null then 'Has never checked in' else 'Last check-in ' || to_char(v_at at time zone 'Asia/Dhaka', 'DD Mon HH24:MI') end,
    'check', 'The gateway reports in every 30 seconds', 'at', v_at);

  -- Integration outages at merchants.
  select count(*) filter (where status = 'ERROR'), count(*) into v_n1, v_n2 from public.sales_channels where status <> 'DISCONNECTED' and merchant_id = any (v_ids);
  v := v || jsonb_build_object('key', 'stores', 'group', 'Integrations', 'name', 'Merchant store connections',
    'status', case when v_n2 = 0 then 'idle' when v_n1 > 0 then 'warn' else 'ok' end,
    'detail', format('%s of %s connected stores report an error', v_n1, v_n2), 'check', 'Each store''s connection state', 'at', null);

  -- Application and API errors.
  select count(*) filter (where category = 'FUNCTION'), count(*) filter (where category = 'FRONTEND'), count(*), max(last_seen_at)
    into v_n1, v_n2, v_n3, v_at
  from public.system_logs where level = 'ERROR' and resolved_at is null and last_seen_at > now() - interval '24 hours'
    and (merchant_id is null or merchant_id = any (v_ids));
  v := v || jsonb_build_object('key', 'errors', 'group', 'Platform', 'name', 'Application errors',
    'status', case when v_n3 > 50 then 'down' when v_n3 > 0 then 'warn' else 'ok' end,
    'detail', format('%s unresolved in 24 h (%s from server functions, %s from browsers)', v_n3, v_n1, v_n2),
    'check', 'Errors reported to the system log by server functions and browsers', 'at', v_at);

  return jsonb_build_object('checked_at', now(), 'components', v,
    'incidents', (select jsonb_build_object('open', count(*) filter (where status <> 'RESOLVED'),
        'critical', count(*) filter (where status <> 'RESOLVED' and severity = 'CRITICAL')) from public.platform_incidents),
    'can', jsonb_build_object('manage', public.platform_can('health', 'manage')));
end;

platform_health_retry.src:
declare
  v_n int;
  v_merchants jsonb;
begin
  perform public._platform_require('health', 'manage');
  if p_kind = 'store_jobs' then
    select count(*), coalesce(jsonb_agg(distinct jsonb_build_object('id', m.id, 'number', m.number, 'name', m.name)), '[]'::jsonb) into v_n, v_merchants
    from public.channel_sync_jobs j join public.merchants m on m.id = j.merchant_id
    where j.status = 'FAILED' and j.updated_at > now() - interval '7 days' and j.merchant_id in (select public._platform_merchant_ids())
      and not exists (select 1 from public.channel_sync_jobs o where o.id <> j.id and o.channel_id = j.channel_id and o.kind = j.kind
                      and o.ref_id = j.ref_id and o.status in ('PENDING', 'RUNNING'));
    if not p_preview then
      update public.channel_sync_jobs j set status = 'PENDING', attempts = 0, next_attempt_at = now(), last_error = null, locked_until = null
      where j.status = 'FAILED' and j.updated_at > now() - interval '7 days' and j.merchant_id in (select public._platform_merchant_ids())
        and not exists (select 1 from public.channel_sync_jobs o where o.id <> j.id and o.channel_id = j.channel_id and o.kind = j.kind
                        and o.ref_id = j.ref_id and o.status in ('PENDING', 'RUNNING'));
      get diagnostics v_n = row_count;
    end if;
  elsif p_kind = 'courier_webhooks' then
    -- Handed back to the courier retry job (every 5 minutes); each event is applied once.
    select count(*), coalesce(jsonb_agg(distinct jsonb_build_object('id', m.id, 'number', m.number, 'name', m.name)), '[]'::jsonb) into v_n, v_merchants
    from public.courier_webhook_events e join public.merchants m on m.id = e.merchant_id
    where e.result in ('FAILED', 'UNMATCHED') and e.attempts < 6 and e.received_at > now() - interval '7 days'
      and e.merchant_id in (select public._platform_merchant_ids());
    if not p_preview then
      update public.courier_webhook_events e set next_retry_at = now()
      where e.result in ('FAILED', 'UNMATCHED') and e.attempts < 6 and e.received_at > now() - interval '7 days'
        and e.merchant_id in (select public._platform_merchant_ids());
      get diagnostics v_n = row_count;
    end if;
  else
    raise exception 'VALIDATION: nothing to retry for %', p_kind using errcode = '22023';
  end if;
  if not p_preview then
    perform public._platform_log('health.retry', null, p_kind, null, p_reason, null, jsonb_build_object('count', v_n, 'merchants', v_merchants));
  end if;
  return jsonb_build_object('kind', p_kind, 'count', v_n, 'merchants', v_merchants, 'preview', p_preview);
end;

platform_incident_create.src:
declare
  i public.platform_incidents;
begin
  perform public._platform_require('incidents', 'create');
  if coalesce((p ->> 'mark_unavailable')::boolean, false) then
    perform public._platform_require('incidents', 'manage');
  end if;
  if nullif(p ->> 'assigned_to', '') is not null and not public._platform_staff_can((p ->> 'assigned_to')::uuid, 'incidents', 'edit') then
    raise exception 'VALIDATION: that person cannot work on incidents' using errcode = '22023';
  end if;
  i := public._platform_incident_open(p, 'MANUAL');
  perform public._platform_log('incident.opened', null, 'platform_incident', i.id::text, null, null, public._platform_incident_json(i));
  return public._platform_incident_json(i);
end;

platform_incident_get.src:
declare
  i public.platform_incidents;
begin
  perform public._platform_require('incidents', 'view');
  select * into i from public.platform_incidents where id = p_id;
  if i.id is null then
    raise exception 'NOT_FOUND: incident not found' using errcode = 'P0002';
  end if;
  return public._platform_incident_json(i) || jsonb_build_object(
    'updates', (select coalesce(jsonb_agg(jsonb_build_object('id', u.id, 'kind', u.kind, 'body', u.body, 'data', u.data, 'actor', u.actor_email, 'created_at', u.created_at)
        order by u.id), '[]'::jsonb) from public.platform_incident_updates u where u.incident_id = i.id),
    'rule', (select jsonb_build_object('id', r.id, 'name', r.name) from public.platform_automation_rules r where r.id = i.rule_id));
end;

platform_incident_note.src:
declare
  i public.platform_incidents;
begin
  perform public._platform_require('incidents', 'edit');
  select * into i from public.platform_incidents where id = p_id;
  if i.id is null then
    raise exception 'NOT_FOUND: incident not found' using errcode = 'P0002';
  end if;
  if length(trim(coalesce(p_body, ''))) < 2 then
    raise exception 'VALIDATION: write the update' using errcode = '22023';
  end if;
  perform public._platform_incident_update(i.id, 'NOTE', trim(p_body));
  return public._platform_incident_json(i);
end;

platform_incident_update.src:
declare
  i public.platform_incidents;
  v_row public.platform_incidents;
  v_status text := nullif(upper(coalesce(p ->> 'status', '')), '');
  v_severity text := nullif(upper(coalesce(p ->> 'severity', '')), '');
  v_assign uuid := nullif(p ->> 'assigned_to', '')::uuid;
  v_m uuid;
begin
  perform public._platform_require('incidents', 'edit');
  select * into i from public.platform_incidents where id = p_id for update;
  if i.id is null then
    raise exception 'NOT_FOUND: incident not found' using errcode = 'P0002';
  end if;
  if i.status = 'RESOLVED' and coalesce(v_status, 'RESOLVED') = 'RESOLVED' and (p ? 'severity' or p ? 'assigned_to' or p ? 'mark_unavailable') then
    raise exception 'VALIDATION: reopen the incident first' using errcode = '22023';
  end if;
  if v_status is not null and v_status not in ('INVESTIGATING', 'IDENTIFIED', 'MONITORING', 'RESOLVED') then
    raise exception 'VALIDATION: unknown status' using errcode = '22023';
  end if;
  if v_severity is not null and v_severity not in ('CRITICAL', 'HIGH', 'MEDIUM', 'LOW') then
    raise exception 'VALIDATION: unknown severity' using errcode = '22023';
  end if;
  if v_status = 'RESOLVED' and i.status <> 'RESOLVED' and length(trim(coalesce(p ->> 'resolution', ''))) < 5 then
    raise exception 'VALIDATION: write what fixed it (the resolution notes)' using errcode = '22023';
  end if;
  if p ? 'mark_unavailable' and (p ->> 'mark_unavailable')::boolean is distinct from i.mark_unavailable then
    perform public._platform_require('incidents', 'manage');
    if (p ->> 'mark_unavailable')::boolean and coalesce(nullif(p ->> 'integration', ''), i.integration) is null then
      raise exception 'VALIDATION: say which integration is unavailable' using errcode = '22023';
    end if;
  end if;
  if v_assign is not null and not public._platform_staff_can(v_assign, 'incidents', 'edit') then
    raise exception 'VALIDATION: that person cannot work on incidents' using errcode = '22023';
  end if;
  update public.platform_incidents set
    status = coalesce(v_status, status),
    severity = coalesce(v_severity, severity),
    assigned_to = case when p ? 'assigned_to' then v_assign else assigned_to end,
    integration = case when p ? 'integration' then nullif(p ->> 'integration', '') else integration end,
    mark_unavailable = coalesce((p ->> 'mark_unavailable')::boolean, mark_unavailable),
    resolved_at = case when coalesce(v_status, status) = 'RESOLVED' then coalesce(resolved_at, now()) else null end,
    resolution = case when v_status = 'RESOLVED' then trim(p ->> 'resolution') when v_status is not null then null else resolution end,
    scope = coalesce(nullif(upper(coalesce(p ->> 'scope', '')), ''), scope)
  where id = i.id returning * into v_row;
  if p ? 'merchants' then
    delete from public.platform_incident_merchants where incident_id = i.id;
    for v_m in select (jsonb_array_elements_text(p -> 'merchants'))::uuid loop
      insert into public.platform_incident_merchants (incident_id, merchant_id) values (i.id, v_m) on conflict do nothing;
    end loop;
    perform public._platform_incident_update(i.id, 'MERCHANTS', null, jsonb_build_object('count', jsonb_array_length(p -> 'merchants')));
  end if;
  if v_row.status is distinct from i.status then
    perform public._platform_incident_update(i.id, 'STATUS', case when v_row.status = 'RESOLVED' then v_row.resolution else nullif(trim(coalesce(p ->> 'note', '')), '') end,
      jsonb_build_object('from', i.status, 'to', v_row.status));
  end if;
  if v_row.severity is distinct from i.severity then
    perform public._platform_incident_update(i.id, 'SEVERITY', null, jsonb_build_object('from', i.severity, 'to', v_row.severity));
  end if;
  if v_row.assigned_to is distinct from i.assigned_to then
    perform public._platform_incident_update(i.id, 'ASSIGNED', null, jsonb_build_object('to_email', (select email from public.platform_staff where user_id = v_row.assigned_to)));
    if v_row.assigned_to is not null and v_row.assigned_to <> auth.uid() then
      perform public._platform_notify('incidents', 'view', null, 'incident.assigned', 'WARN', format('Incident #%s is yours: %s', v_row.number, v_row.title), null,
        '/super-admin/incidents?incident=' || v_row.id, 'incident.assigned:' || v_row.id || ':' || v_row.assigned_to || ':' || extract(epoch from now())::bigint, array[v_row.assigned_to]);
    end if;
  end if;
  if v_row.mark_unavailable is distinct from i.mark_unavailable then
    perform public._platform_incident_update(i.id, 'UNAVAILABLE', null, jsonb_build_object('integration', v_row.integration, 'unavailable', v_row.mark_unavailable));
  end if;
  perform public._platform_incident_sync_health();
  perform public._platform_log('incident.updated', null, 'platform_incident', i.id::text, nullif(trim(coalesce(p ->> 'note', '')), ''),
    jsonb_build_object('status', i.status, 'severity', i.severity, 'assigned_to', i.assigned_to, 'mark_unavailable', i.mark_unavailable),
    jsonb_build_object('status', v_row.status, 'severity', v_row.severity, 'assigned_to', v_row.assigned_to, 'mark_unavailable', v_row.mark_unavailable));
  return public._platform_incident_json(v_row);
end;

platform_incidents_list.src:
declare
  v_view text := coalesce(nullif(p ->> 'view', ''), 'open');
begin
  perform public._platform_require('incidents', 'view');
  return jsonb_build_object(
    'rows', (select coalesce(jsonb_agg(public._platform_incident_json(i) order by (i.status = 'RESOLVED'),
        case i.severity when 'CRITICAL' then 0 when 'HIGH' then 1 when 'MEDIUM' then 2 else 3 end, i.started_at desc), '[]'::jsonb)
      from (select * from public.platform_incidents x where case v_view when 'open' then x.status <> 'RESOLVED'
              when 'resolved' then x.status = 'RESOLVED' else true end order by x.started_at desc limit 200) i),
    'summary', (select jsonb_build_object('open', count(*) filter (where status <> 'RESOLVED'),
        'critical', count(*) filter (where status <> 'RESOLVED' and severity = 'CRITICAL'),
        'unavailable', (select coalesce(jsonb_agg(distinct integration), '[]'::jsonb) from public.platform_incidents where status <> 'RESOLVED' and mark_unavailable),
        'resolved_30d', count(*) filter (where resolved_at > now() - interval '30 days'),
        'avg_minutes_30d', round(avg(extract(epoch from resolved_at - started_at) / 60) filter (where resolved_at > now() - interval '30 days')))
      from public.platform_incidents),
    'staff', (select coalesce(jsonb_agg(jsonb_build_object('user_id', s.user_id, 'name', coalesce(nullif(trim(s.full_name), ''), s.email))
        order by s.full_name), '[]'::jsonb) from public.platform_staff s where s.is_active and public._platform_staff_can(s.user_id, 'incidents', 'edit')),
    'can', jsonb_build_object('create', public.platform_can('incidents', 'create'), 'edit', public.platform_can('incidents', 'edit'),
      'manage', public.platform_can('incidents', 'manage')));
end;

platform_integration_retry.src:
declare
  v_merchant uuid;
  v_out jsonb;
  v_n int;
  v_event uuid;
  v_status text;
begin
  if p_kind = 'store_jobs' then
    select merchant_id into v_merchant from public.sales_channels where id = p_id;
  elsif p_kind = 'courier_events' then
    select merchant_id into v_merchant from public.couriers where id = p_id;
  else
    raise exception 'VALIDATION: nothing to retry for %', p_kind using errcode = '22023';
  end if;
  if v_merchant is null or not public.platform_can('integrations', 'view', v_merchant) then
    raise exception 'NOT_FOUND: integration not found' using errcode = 'P0002';
  end if;
  perform public._platform_require('integrations', 'edit', v_merchant);
  if p_kind = 'store_jobs' then
    -- Same rule as the merchant's own retry: never a second copy of a job already waiting or running.
    update public.channel_sync_jobs j set status = 'PENDING', attempts = 0, next_attempt_at = now(), last_error = null, locked_until = null
    where j.channel_id = p_id and j.status = 'FAILED'
      and not exists (select 1 from public.channel_sync_jobs o where o.id <> j.id and o.channel_id = j.channel_id and o.kind = j.kind
                      and o.ref_id = j.ref_id and o.status in ('PENDING', 'RUNNING'));
    get diagnostics v_n = row_count;
    v_out := jsonb_build_object('requeued', v_n);
  else
    perform public._platform_in_merchant(v_merchant);
    v_out := '{}'::jsonb;
    v_n := 0;
    for v_event in select e.id from public.courier_webhook_events e where e.merchant_id = v_merchant and e.courier_id = p_id
                     and e.result in ('FAILED', 'UNMATCHED') and e.received_at > now() - interval '7 days' order by e.received_at limit 100 loop
      v_n := v_n + 1;
      v_status := coalesce(public._process_courier_webhook(v_event) ->> 'status', 'unknown');
      v_out := v_out || jsonb_build_object(v_status, coalesce((v_out ->> v_status)::int, 0) + 1);
    end loop;
    perform public._platform_in_merchant(null);
    v_out := jsonb_build_object('retried', v_n, 'results', v_out);
  end if;
  perform public._platform_log('integrations.retry', v_merchant, p_kind, p_id::text, p_reason, null, v_out);
  return v_out;
end;

platform_invoice_void.src:
declare
  v_inv public.billing_invoices;
begin
  select * into v_inv from public.billing_invoices where id = p_invoice for update;
  if v_inv.id is null then
    raise exception 'NOT_FOUND: invoice not found' using errcode = 'P0002';
  end if;
  perform public._platform_require('subscriptions', 'manage', v_inv.merchant_id);
  if v_inv.status <> 'OPEN' or v_inv.amount_paid > 0 then
    raise exception 'VALIDATION: only an unpaid open invoice can be voided' using errcode = '22023';
  end if;
  if coalesce(length(trim(p_reason)), 0) < 5 then
    raise exception 'VALIDATION: give a reason' using errcode = '22023';
  end if;
  update public.billing_invoices set status = 'VOID', void_reason = p_reason where id = v_inv.id;
  perform public._platform_log('billing.invoice_voided', v_inv.merchant_id, 'billing_invoice', v_inv.id::text, p_reason, to_jsonb(v_inv), null);
end;

platform_invoices_list.src:
declare
  v_status text := nullif(p_filters ->> 'status', '');
  v_overdue boolean := coalesce((p_filters ->> 'overdue')::boolean, false);
begin
  perform public._platform_require('subscriptions', 'view');
  return (with rows as (
      select i.*, m.name as merchant_name, m.number as merchant_number from public.billing_invoices i join public.merchants m on m.id = i.merchant_id
      where i.merchant_id in (select public._platform_merchant_ids())
        and (v_status is null or i.status = v_status)
        and (not v_overdue or (i.status = 'OPEN' and i.due_at < now())))
    select jsonb_build_object('total', (select count(*) from rows),
      'items', coalesce((select jsonb_agg(to_jsonb(r) order by r.created_at desc) from (select * from rows order by created_at desc limit p_limit offset p_offset) r), '[]'::jsonb),
      'pending_payments', coalesce((select jsonb_agg(to_jsonb(bp) - 'raw' || jsonb_build_object('invoice_number', i.number, 'merchant', m.name, 'can_verify',
            bp.recorded_by is distinct from auth.uid() and public.platform_can('subscriptions', 'approve', bp.merchant_id)) order by bp.created_at)
          from public.billing_payments bp join public.billing_invoices i on i.id = bp.invoice_id join public.merchants m on m.id = bp.merchant_id
          where bp.status = 'PENDING' and bp.merchant_id in (select public._platform_merchant_ids())), '[]'::jsonb)));
end;

platform_me.src:
declare
  s public.platform_staff;
  r public.platform_roles;
  v_sid uuid := nullif(auth.jwt() ->> 'session_id', '')::uuid;
  v_started timestamptz;
  v_hours int := nullif((select value ->> 'staff_session_hours' from public.platform_settings where key = 'security'), '')::int;
begin
  select * into s from public.platform_staff where user_id = auth.uid() and is_active;
  if s.user_id is null or coalesce(auth.jwt() ->> 'role', '') <> 'authenticated' then
    return null;
  end if;
  if v_sid is not null then
    select created_at into v_started from auth.sessions where id = v_sid;
  end if;
  -- The panel signs out and explains; nothing else is returned.
  if not public._platform_session_ok() then
    return jsonb_build_object('user_id', s.user_id, 'email', s.email, 'session_expired', true);
  end if;
  select * into r from public.platform_roles where id = s.role_id;
  update public.platform_staff set last_seen_at = now() where user_id = s.user_id and (last_seen_at is null or last_seen_at < now() - interval '5 minutes');
  return jsonb_build_object(
    'user_id', s.user_id, 'email', s.email, 'full_name', s.full_name, 'title', s.title,
    'role', jsonb_build_object('id', r.id, 'code', r.code, 'name', r.name, 'is_super', r.is_super),
    'merchant_scope', case when r.is_super then 'ALL' else s.merchant_scope end,
    'merchant_ids', case when r.is_super or s.merchant_scope = 'ALL' then null
      else (select coalesce(jsonb_agg(merchant_id), '[]'::jsonb) from public.platform_staff_merchants where user_id = s.user_id) end,
    'permissions', case when r.is_super
      then (select jsonb_agg(m.code || '.' || a order by m.sort_order, a) from public.platform_modules m, unnest(m.actions) a)
      else (select coalesce(jsonb_agg(rp.module || '.' || rp.action order by rp.module, rp.action), '[]'::jsonb)
            from public.platform_role_permissions rp where rp.role_id = r.id) end,
    'modules', (select jsonb_agg(jsonb_build_object('code', code, 'name', name, 'actions', actions) order by sort_order) from public.platform_modules),
    'merchant_staff', exists (select 1 from public.profiles p where p.id = s.user_id and p.is_active),
    'pending_approvals', (select count(*) from public.platform_approvals a where a.status = 'PENDING' and a.expires_at > now()
                          and a.requested_by <> s.user_id and public.platform_can(a.module, 'approve', a.merchant_id)),
    'unread_notifications', (select count(*) from public.platform_notifications n where n.user_id = s.user_id and n.read_at is null),
    'support_session', (select public._platform_session_json(ss) from public.support_sessions ss
                        where ss.staff_user_id = s.user_id and ss.ended_at is null and ss.expires_at > now() order by ss.started_at desc limit 1),
    'session', jsonb_build_object('started_at', v_started,
      'expires_at', case when v_started is not null and v_hours is not null then v_started + make_interval(hours => v_hours) end)
  );
end;

platform_merchant_billing.src:
declare
  s public.subscriptions;
begin
  perform public._platform_require('subscriptions', 'view', p_merchant);
  select * into s from public.subscriptions where merchant_id = p_merchant and ended_at is null;
  return jsonb_build_object(
    'subscription', case when s.id is null then null else to_jsonb(s) || jsonb_build_object('plan', (select to_jsonb(p) from public.plans p where p.id = s.plan_id)) end,
    'access_mode', public.merchant_access_mode(p_merchant),
    'limits', public.merchant_limits(p_merchant),
    'usage', public.merchant_usage(p_merchant),
    'entitlements', public.merchant_entitlements(p_merchant),
    'addons', coalesce((select jsonb_agg(jsonb_build_object('id', sa.id, 'name', a.name, 'quantity', sa.quantity, 'price', sa.price, 'grants', a.grants))
               from public.subscription_addons sa join public.plan_addons a on a.id = sa.addon_id where sa.merchant_id = p_merchant and sa.ended_at is null), '[]'::jsonb),
    'invoices', coalesce((select jsonb_agg(to_jsonb(i) order by i.created_at desc) from (select * from public.billing_invoices where merchant_id = p_merchant
               order by created_at desc limit 24) i), '[]'::jsonb),
    'payments', coalesce((select jsonb_agg(to_jsonb(x) - 'raw' order by x.created_at desc) from (select * from public.billing_payments where merchant_id = p_merchant
               order by created_at desc limit 24) x), '[]'::jsonb),
    'events', coalesce((select jsonb_agg(to_jsonb(e) order by e.created_at desc) from (select * from public.subscription_events where merchant_id = p_merchant
               order by created_at desc limit 30) e), '[]'::jsonb));
end;

platform_merchant_create.src:
declare
  v_id uuid;
  v_seeded jsonb;
  v_name text := trim(coalesce(p ->> 'name', ''));
  v_slug text := nullif(lower(trim(coalesce(p ->> 'slug', ''))), '');
begin
  perform public._platform_require('merchants', 'create');
  if length(v_name) < 2 then
    raise exception 'VALIDATION: enter the business name' using errcode = '22023';
  end if;
  if v_slug is not null and exists (select 1 from public.merchants where slug = v_slug) then
    raise exception 'DUPLICATE: that short name is taken' using errcode = '23505';
  end if;
  insert into public.merchants (name, slug, status, is_demo, owner_email, phone, business_type, website, address, notes, account_manager_id, created_by,
                                onboarding)
  values (v_name, v_slug, 'ONBOARDING', coalesce((p ->> 'is_demo')::boolean, false), lower(nullif(trim(p ->> 'owner_email'), '')),
          nullif(trim(p ->> 'phone'), ''), nullif(p ->> 'business_type', ''), nullif(p ->> 'website', ''), nullif(p ->> 'address', ''),
          nullif(p ->> 'notes', ''), coalesce(nullif(p ->> 'account_manager_id', '')::uuid, auth.uid()), auth.uid(),
          jsonb_build_object('started_at', now(), 'by', auth.uid()))
  returning id into v_id;
  -- Seed inside the new merchant only.
  perform set_config('app.merchant_id', v_id::text, true);
  v_seeded := public._merchant_seed_defaults(v_id);
  update public.settings set value = value || jsonb_build_object('name', v_name)
  where merchant_id = v_id and key = 'store';
  perform set_config('app.merchant_id', '', true);
  -- The chosen plan (or the default), as a trial when the plan has one. Choosing
  -- a plan other than the default is a subscription decision.
  if nullif(p ->> 'plan_code', '') is distinct from null
     and p ->> 'plan_code' is distinct from (select value ->> 'default_plan' from public.platform_settings where key = 'billing') then
    perform public._platform_require('subscriptions', 'manage');
  end if;
  insert into public.subscriptions (merchant_id, plan_id, status, price, currency, billing_interval, trial_ends_at, current_period_start, current_period_end, created_by)
  select v_id, pl.id, case when pl.trial_days > 0 then 'TRIALING' else 'ACTIVE' end, pl.price, pl.currency, pl.billing_interval,
         case when pl.trial_days > 0 then now() + make_interval(days => pl.trial_days) end, now(),
         case when pl.trial_days = 0 and pl.price = 0 then now() + public._billing_interval(pl.billing_interval) end, auth.uid()
  from public.plans pl
  where pl.status = 'ACTIVE'
    and pl.code = coalesce(nullif(p ->> 'plan_code', ''), (select value ->> 'default_plan' from public.platform_settings where key = 'billing'))
    and (pl.trial_days > 0 or pl.price = 0);
  insert into public.subscription_events (merchant_id, subscription_id, event, detail, actor_id)
  select s.merchant_id, s.id, 'subscription.started', jsonb_build_object('plan', pl.code, 'trial', s.status = 'TRIALING', 'reason', 'New merchant'), auth.uid()
  from public.subscriptions s join public.plans pl on pl.id = s.plan_id where s.merchant_id = v_id and s.ended_at is null;
  perform public._platform_log('merchant.created', v_id, 'merchant', v_id::text, p ->> 'reason', null,
    jsonb_build_object('name', v_name, 'is_demo', coalesce((p ->> 'is_demo')::boolean, false), 'seeded', v_seeded));
  return jsonb_build_object('id', v_id, 'seeded', v_seeded);
end;

platform_merchant_delete_request.src:
declare
  m public.merchants;
  v_id uuid;
begin
  perform public._platform_require('merchants', 'manage', p_merchant);
  perform public._platform_in_merchant(p_merchant);
  select * into m from public.merchants where id = p_merchant;
  if not found then
    raise exception 'NOT_FOUND: merchant not found' using errcode = 'P0002';
  end if;
  if m.deleted_at is not null then
    raise exception 'VALIDATION: this merchant was already deleted' using errcode = '22023';
  end if;
  if lower(trim(coalesce(p_confirm_name, ''))) <> lower(trim(m.name)) then
    raise exception 'VALIDATION: type the merchant''s name exactly as shown to confirm' using errcode = '22023';
  end if;
  if coalesce(length(trim(p_reason)), 0) < 10 then
    raise exception 'VALIDATION: explain why (at least 10 characters)' using errcode = '22023';
  end if;
  if public._platform_merchant_recent_export(p_merchant) is null then
    raise exception 'VALIDATION: download a full export of this merchant first (Data Management → Export), then ask within 24 hours'
      using errcode = '22023';
  end if;
  v_id := public.platform_request_approval('merchants', 'merchant_delete', m.id,
    format('Delete merchant #%s %s and all its data', m.number, m.name), jsonb_build_object('merchant_id', m.id, 'name', m.name), trim(p_reason));
  return jsonb_build_object('approval_id', v_id, 'can_self_approve', public._platform_sole_approver('merchants', m.id));
end;

platform_merchant_export.src:
declare
  v_cap constant int := 50000;
  v_data jsonb;
  v_counts jsonb;
  v_id bigint;
begin
  perform public._platform_require('data', 'export', p_merchant);
  if length(trim(coalesce(p_reason, ''))) < 5 then
    raise exception 'VALIDATION: say why the data is exported (at least 5 characters)' using errcode = '22023';
  end if;
  if not exists (select 1 from public.merchants where id = p_merchant) then
    raise exception 'NOT_FOUND: merchant not found' using errcode = 'P0002';
  end if;
  v_data := jsonb_build_object(
    'merchant', (select to_jsonb(m) from public.merchants m where m.id = p_merchant),
    'subscription', (select to_jsonb(s) from public.subscriptions s where s.merchant_id = p_merchant and s.ended_at is null),
    'customers', (select coalesce(jsonb_agg(to_jsonb(x)), '[]'::jsonb) from (select * from public.customers where merchant_id = p_merchant order by created_at limit v_cap) x),
    'customer_addresses', (select coalesce(jsonb_agg(to_jsonb(x)), '[]'::jsonb) from (select * from public.customer_addresses where merchant_id = p_merchant limit v_cap) x),
    'products', (select coalesce(jsonb_agg(to_jsonb(x)), '[]'::jsonb) from (select * from public.products where merchant_id = p_merchant order by created_at limit v_cap) x),
    'product_variants', (select coalesce(jsonb_agg(to_jsonb(x)), '[]'::jsonb) from (select * from public.product_variants where merchant_id = p_merchant limit v_cap) x),
    'orders', (select coalesce(jsonb_agg(to_jsonb(x)), '[]'::jsonb) from (select * from public.orders where merchant_id = p_merchant order by created_at limit v_cap) x),
    'order_items', (select coalesce(jsonb_agg(to_jsonb(x)), '[]'::jsonb) from (select * from public.order_items where merchant_id = p_merchant limit v_cap) x),
    'order_payments', (select coalesce(jsonb_agg(to_jsonb(x)), '[]'::jsonb) from (select * from public.order_payments where merchant_id = p_merchant limit v_cap) x),
    'shipments', (select coalesce(jsonb_agg(to_jsonb(x) - 'provider_payload'), '[]'::jsonb) from (select * from public.shipments where merchant_id = p_merchant limit v_cap) x),
    'invoices', (select coalesce(jsonb_agg(to_jsonb(x)), '[]'::jsonb) from (select * from public.billing_invoices where merchant_id = p_merchant order by created_at) x),
    'platform_payments', (select coalesce(jsonb_agg(to_jsonb(x) - 'raw'), '[]'::jsonb) from (select * from public.billing_payments where merchant_id = p_merchant order by created_at) x),
    'credit_ledger', (select coalesce(jsonb_agg(to_jsonb(x)), '[]'::jsonb) from (select * from public.credit_ledger where merchant_id = p_merchant order by created_at limit v_cap) x));
  v_counts := (select jsonb_object_agg(key, case when jsonb_typeof(value) = 'array' then jsonb_array_length(value) else 1 end) from jsonb_each(v_data));
  insert into public.platform_data_exports (kind, merchant_id, actor_id, actor_email, reason, detail)
  values ('MERCHANT_DATA', p_merchant, auth.uid(), (select email from public.platform_staff where user_id = auth.uid()), trim(p_reason),
          jsonb_build_object('rows', v_counts, 'capped_at', v_cap))
  returning id into v_id;
  perform public._platform_log('data.merchant_export', p_merchant, 'export', v_id::text, trim(p_reason), null, jsonb_build_object('rows', v_counts));
  return jsonb_build_object('exported_at', now(), 'export_id', v_id, 'rows', v_counts, 'capped_at', v_cap, 'data', v_data);
end;

platform_merchant_feature_set.src:
declare
  v_before jsonb;
begin
  perform public._platform_require('features', 'edit', p_merchant);
  if coalesce(length(trim(p_reason)), 0) < 3 then
    raise exception 'VALIDATION: give a reason' using errcode = '22023';
  end if;
  if (select is_core from public.features where code = p_code) and p_enabled is false then
    raise exception 'VALIDATION: core features cannot be switched off' using errcode = '22023';
  end if;
  select public.merchant_entitlements(p_merchant) -> p_code into v_before;
  if p_enabled is null and p_limit is null then
    delete from public.merchant_features where merchant_id = p_merchant and feature_code = p_code;
  else
    insert into public.merchant_features (merchant_id, feature_code, enabled, limit_value, reason, expires_at, set_by)
    values (p_merchant, p_code, p_enabled, p_limit, p_reason, p_expires_at, auth.uid())
    on conflict (merchant_id, feature_code) do update set enabled = excluded.enabled, limit_value = excluded.limit_value, reason = excluded.reason,
      expires_at = excluded.expires_at, set_by = excluded.set_by, set_at = now();
  end if;
  perform public._config_version('merchant_feature', p_merchant::text || ':' || p_code,
    jsonb_build_object('enabled', p_enabled, 'limit', p_limit, 'expires_at', p_expires_at), p_reason);
  perform public._platform_log('features.merchant_changed', p_merchant, 'feature', p_code, p_reason, v_before,
    public.merchant_entitlements(p_merchant) -> p_code);
  return public.merchant_entitlements(p_merchant) -> p_code;
end;

platform_merchant_get.src:
declare
  m public.merchants;
begin
  perform public._platform_require('merchants', 'view', p_id);
  select * into m from public.merchants where id = p_id;
  if m.id is null then
    raise exception 'NOT_FOUND: merchant not found' using errcode = 'P0002';
  end if;
  return jsonb_build_object(
    'merchant', to_jsonb(m),
    'account_manager', (select jsonb_build_object('id', s.user_id, 'name', coalesce(nullif(s.full_name, ''), s.email), 'email', s.email)
                        from public.platform_staff s where s.user_id = m.account_manager_id),
    'onboarding', public._merchant_onboarding(m.id),
    'staff', (select coalesce(jsonb_agg(jsonb_build_object('id', p.id, 'email', p.email, 'full_name', p.full_name, 'role', r.code,
                'is_active', p.is_active, 'last_seen_at', p.last_seen_at, 'deleted_at', p.deleted_at) order by r.rank desc, p.full_name), '[]'::jsonb)
              from public.profiles p join public.roles r on r.id = p.role_id where p.merchant_id = m.id),
    'stores', (select coalesce(jsonb_agg(jsonb_build_object('id', c.id, 'platform', c.platform, 'name', c.name, 'shop_domain', c.shop_domain,
                'status', c.status, 'last_sync_at', c.last_sync_at, 'last_error', nullif(c.last_error, ''), 'orders_imported', c.orders_imported)
                order by c.created_at), '[]'::jsonb)
               from public.sales_channels c where c.merchant_id = m.id),
    'couriers', (select coalesce(jsonb_agg(jsonb_build_object('id', c.id, 'name', c.name, 'provider', c.provider, 'api_enabled', c.api_enabled,
                  'api_status', c.api_status, 'is_active', c.is_active) order by c.name), '[]'::jsonb)
                 from public.couriers c where c.merchant_id = m.id),
    'activity', jsonb_build_object(
      'orders_total', (select count(*) from public.orders o where o.merchant_id = m.id),
      'orders_30d', (select count(*) from public.orders o where o.merchant_id = m.id and o.created_at > now() - interval '30 days'),
      'order_value_30d', (select coalesce(sum(o.total_amount), 0) from public.orders o
                          where o.merchant_id = m.id and o.created_at > now() - interval '30 days' and o.status not in ('CANCELLED', 'REJECTED_FRAUD')),
      'returns_30d', (select count(*) from public.orders o where o.merchant_id = m.id and o.status = 'RETURNED' and o.updated_at > now() - interval '30 days'),
      'last_order_at', (select max(o.created_at) from public.orders o where o.merchant_id = m.id),
      'products', (select count(*) from public.products p where p.merchant_id = m.id),
      'stock_units', (select coalesce(sum(i.on_hand), 0) from public.inventory i where i.merchant_id = m.id),
      'shipments_30d', (select count(*) from public.shipments s where s.merchant_id = m.id and s.created_at > now() - interval '30 days'),
      'sms_sent_30d', (select count(*) from public.notification_logs n where n.merchant_id = m.id and n.channel = 'SMS'
                       and n.status = 'SENT' and n.created_at > now() - interval '30 days'),
      'courier_checks_30d', (select count(*) from public.fraud_checks f where f.merchant_id = m.id and f.created_at > now() - interval '30 days'
                             and 'courier_history' = any (f.providers))),
    'errors', (select coalesce(jsonb_agg(jsonb_build_object('id', l.id, 'level', l.level, 'category', l.category, 'source', l.source,
                 'message', l.message, 'occurrences', l.occurrences, 'last_seen_at', l.last_seen_at) order by l.last_seen_at desc), '[]'::jsonb)
               from (select * from public.system_logs l where l.merchant_id = m.id and l.resolved_at is null and l.level in ('ERROR', 'WARN')
                     order by l.last_seen_at desc limit 15) l),
    'recent_activity', (select coalesce(jsonb_agg(jsonb_build_object('action', a.action, 'entity_type', a.entity_type, 'actor_email', a.actor_email,
                 'created_at', a.created_at) order by a.created_at desc), '[]'::jsonb)
               from (select * from public.audit_logs a where a.merchant_id = m.id order by a.created_at desc limit 20) a),
    'notes', (select coalesce(jsonb_agg(jsonb_build_object('id', n.id, 'body', n.body, 'pinned', n.pinned, 'author', n.author_email,
                'created_at', n.created_at) order by n.pinned desc, n.created_at desc), '[]'::jsonb)
              from public.merchant_notes n where n.merchant_id = m.id),
    'platform_log', (select coalesce(jsonb_agg(jsonb_build_object('action', l.action, 'actor_email', l.actor_email, 'reason', l.reason,
                 'result', l.result, 'created_at', l.created_at) order by l.created_at desc), '[]'::jsonb)
               from (select * from public.platform_audit_logs l where l.merchant_id = m.id order by l.created_at desc limit 20) l),
    'can', jsonb_build_object('edit', public.platform_can('merchants', 'edit', m.id), 'manage', public.platform_can('merchants', 'manage', m.id)));
end;

platform_merchant_health.src:
declare
  v_need text := nullif(p ->> 'need', '');
  v_band text := nullif(upper(coalesce(p ->> 'band', '')), '');
  v_q text := nullif(trim(coalesce(p ->> 'q', '')), '');
  v_demo boolean := coalesce((p ->> 'include_demo')::boolean, false);
begin
  perform public._platform_require('merchants', 'view');
  return (with h as (
      select m.id, m.number, m.name, m.status, m.is_demo, m.created_at,
        (select coalesce(nullif(trim(ps.full_name), ''), ps.email) from public.platform_staff ps where ps.user_id = m.account_manager_id) as account_manager,
        public._platform_merchant_signals(m.id) as x
      from public.merchants m
      where m.id in (select public._platform_merchant_ids()) and m.status in ('ONBOARDING', 'ACTIVE', 'SUSPENDED') and (v_demo or not m.is_demo)
        and (v_q is null or m.name ilike '%' || v_q || '%' or m.number::text = ltrim(v_q, '#'))),
    r as (
      select h.*, (h.x ->> 'score')::int as score,
        case when (h.x ->> 'score')::int >= 80 then 'HEALTHY' when (h.x ->> 'score')::int >= 60 then 'WATCH' else 'AT_RISK' end as band
      from h)
    select jsonb_build_object(
      'summary', (select jsonb_build_object('total', count(*), 'healthy', count(*) filter (where band = 'HEALTHY'),
          'watch', count(*) filter (where band = 'WATCH'), 'at_risk', count(*) filter (where band = 'AT_RISK'),
          'onboarding', count(*) filter (where x -> 'needs' ? 'onboarding'), 'technical', count(*) filter (where x -> 'needs' ? 'technical'),
          'billing', count(*) filter (where x -> 'needs' ? 'billing'), 'activity', count(*) filter (where x -> 'needs' ? 'activity')) from r),
      'rows', (select coalesce(jsonb_agg(jsonb_build_object('id', r.id, 'number', r.number, 'name', r.name, 'status', r.status, 'is_demo', r.is_demo,
            'account_manager', r.account_manager, 'created_at', r.created_at, 'score', r.score, 'band', r.band) || (r.x - 'score')
          order by r.score, r.number), '[]'::jsonb)
        from r where (v_band is null or r.band = v_band) and (v_need is null or r.x -> 'needs' ? v_need)),
      'method', 'Each merchant starts at 100; every signal found takes off the points shown next to it. 80 and above: healthy, 60–79: watch, below 60: at risk. '
        || 'This is an estimate from these signals to decide who to contact — not a churn decision.'));
end;

platform_merchant_note_add.src:
declare
  v_note public.merchant_notes;
begin
  perform public._platform_require('merchants', 'edit', p_merchant);
  insert into public.merchant_notes (merchant_id, author_id, author_email, body, pinned)
  values (p_merchant, auth.uid(), (select email from public.platform_staff where user_id = auth.uid()), trim(p_body), coalesce(p_pinned, false))
  returning * into v_note;
