platform_merchant_set_owner.src:
declare
  m public.merchants;
  v_auth record;
  v_other uuid;
  v_role uuid;
  v_profile public.profiles;
begin
  select * into m from public.merchants where id = p_merchant for update;
  if m.id is null then
    raise exception 'NOT_FOUND: merchant not found' using errcode = 'P0002';
  end if;
  if not (public.platform_can('merchants', 'manage', m.id)
          or (public.platform_can('merchants', 'create') and m.created_by = auth.uid()
              and not exists (select 1 from public.profiles p join public.roles r on r.id = p.role_id
                              where p.merchant_id = m.id and r.code = 'OWNER'))) then
    raise exception 'PERMISSION_DENIED: merchants manage is not allowed for this merchant' using errcode = '42501';
  end if;
  if m.status = 'CLOSED' then
    raise exception 'VALIDATION: the merchant is closed' using errcode = '22023';
  end if;
  select * into v_auth from public._auth_user(p_user);
  if v_auth.id is null then
    raise exception 'NOT_FOUND: no account with this id' using errcode = 'P0002';
  end if;
  v_other := public._staff_merchant(p_user);
  if v_other is not null and v_other <> m.id then
    raise exception 'VALIDATION: this account already belongs to another business' using errcode = '22023';
  end if;
  select id into v_role from public.roles where merchant_id = m.id and code = 'OWNER';
  if v_role is null then
    raise exception 'VALIDATION: the merchant has no Owner role yet' using errcode = '22023';
  end if;
  perform set_config('app.merchant_id', m.id::text, true);
  insert into public.profiles (id, merchant_id, email, full_name, role_id, is_active)
  values (p_user, m.id, v_auth.email, coalesce(nullif(trim(p_full_name), ''), v_auth.full_name, ''), v_role, true)
  on conflict (id) do update set role_id = excluded.role_id, is_active = true
  returning * into v_profile;
  update public.merchants set owner_email = coalesce(owner_email, v_auth.email) where id = m.id;
  perform set_config('app.merchant_id', '', true);
  perform public._platform_log('merchant.owner_set', m.id, 'profile', p_user::text, null, null, jsonb_build_object('email', v_auth.email));
  return jsonb_build_object('user_id', v_profile.id, 'email', v_profile.email);
end;

platform_merchant_set_status.src:
declare
  m public.merchants;
  v_changed int := 0;
  v_requests jsonb := '[]'::jsonb;
begin
  perform public._platform_require('merchants', 'manage');
  if coalesce(length(trim(p_reason)), 0) < 5 then
    raise exception 'VALIDATION: give a reason (at least 5 characters)' using errcode = '22023';
  end if;
  if p_token is distinct from md5(p_status || ':' || array_to_string(array(select unnest(p_ids)::text order by 1), ',')) then
    raise exception 'VALIDATION: review the list of merchants first' using errcode = '22023';
  end if;
  for m in select * from public.merchants where id = any (p_ids) order by number for update loop
    perform public._platform_require('merchants', 'manage', m.id);
    continue when m.status = p_status;
    if p_status = 'CLOSED' then
      v_requests := v_requests || to_jsonb(public.platform_request_approval('merchants', 'merchant_close', m.id,
        format('Close merchant #%s %s', m.number, m.name), jsonb_build_object('merchant_id', m.id), p_reason));
      continue;
    end if;
    if m.status = 'CLOSED' then
      raise exception 'VALIDATION: % is closed; closed accounts are not reopened from here', m.name using errcode = '22023';
    end if;
    update public.merchants set status = p_status, status_reason = trim(p_reason), status_changed_at = now(), status_changed_by = auth.uid()
    where id = m.id;
    if p_status = 'ACTIVE' and m.onboarded_at is null then
      update public.merchants set onboarded_at = now() where id = m.id;
    end if;
    v_changed := v_changed + 1;
    perform public._platform_log('merchant.status_changed', m.id, 'merchant', m.id::text, p_reason,
      jsonb_build_object('status', m.status), jsonb_build_object('status', p_status),
      'SUCCESS', jsonb_build_object('bulk', cardinality(p_ids) > 1));
  end loop;
  return jsonb_build_object('changed', v_changed, 'approval_requests', v_requests);
end;

platform_merchant_status_preview.src:
declare
  v_items jsonb;
begin
  perform public._platform_require('merchants', 'manage');
  if p_status not in ('ACTIVE', 'SUSPENDED', 'CLOSED') then
    raise exception 'VALIDATION: unknown status' using errcode = '22023';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object('id', m.id, 'number', m.number, 'name', m.name, 'status', m.status,
      'changes', m.status <> p_status,
      'allowed', public.platform_can('merchants', 'manage', m.id),
      'open_orders', (select count(*) from public.orders o where o.merchant_id = m.id
                      and o.status not in ('DELIVERED', 'CANCELLED', 'RETURNED', 'REJECTED_FRAUD')),
      'stores', (select count(*) from public.sales_channels c where c.merchant_id = m.id and c.status = 'CONNECTED'),
      'staff', (select count(*) from public.profiles p where p.merchant_id = m.id and p.is_active)) order by m.number), '[]'::jsonb)
  into v_items
  from public.merchants m where m.id = any (p_ids);
  return jsonb_build_object('status', p_status, 'items', v_items,
    'token', md5(p_status || ':' || array_to_string(array(select unnest(p_ids)::text order by 1), ',')),
    'needs_approval', p_status = 'CLOSED');
end;

platform_merchant_update.src:
declare
  v_before public.merchants;
  v_after public.merchants;
begin
  perform public._platform_require('merchants', 'edit', p_id);
  select * into v_before from public.merchants where id = p_id for update;
  if v_before.id is null then
    raise exception 'NOT_FOUND: merchant not found' using errcode = 'P0002';
  end if;
  if p ? 'account_manager_id' then
    perform public._platform_require('merchants', 'manage', p_id);
    if nullif(p ->> 'account_manager_id', '') is not null
       and not exists (select 1 from public.platform_staff where user_id = (p ->> 'account_manager_id')::uuid and is_active) then
      raise exception 'VALIDATION: choose an active employee' using errcode = '22023';
    end if;
  end if;
  update public.merchants set
    name = coalesce(nullif(trim(p ->> 'name'), ''), name),
    slug = case when p ? 'slug' then nullif(lower(trim(p ->> 'slug')), '') else slug end,
    owner_email = case when p ? 'owner_email' then lower(nullif(trim(p ->> 'owner_email'), '')) else owner_email end,
    phone = case when p ? 'phone' then nullif(trim(p ->> 'phone'), '') else phone end,
    business_type = case when p ? 'business_type' then nullif(p ->> 'business_type', '') else business_type end,
    website = case when p ? 'website' then nullif(p ->> 'website', '') else website end,
    address = case when p ? 'address' then nullif(p ->> 'address', '') else address end,
    notes = case when p ? 'notes' then nullif(p ->> 'notes', '') else notes end,
    is_demo = coalesce((p ->> 'is_demo')::boolean, is_demo),
    account_manager_id = case when p ? 'account_manager_id' then nullif(p ->> 'account_manager_id', '')::uuid else account_manager_id end
  where id = p_id returning * into v_after;
  perform public._platform_log('merchant.updated', p_id, 'merchant', p_id::text, p ->> 'reason',
    to_jsonb(v_before) - 'onboarding', to_jsonb(v_after) - 'onboarding');
  return to_jsonb(v_after);
end;

platform_merchant_user_delete.src:
declare
  p public.profiles;
  v_role text;
begin
  perform public._platform_require('merchants', 'manage', p_merchant);
  if coalesce(length(trim(p_reason)), 0) < 5 then
    raise exception 'VALIDATION: explain why (at least 5 characters)' using errcode = '22023';
  end if;
  perform public._platform_in_merchant(p_merchant);
  select * into p from public.profiles where id = p_user and merchant_id = p_merchant for update;
  if not found then
    raise exception 'NOT_FOUND: this person is not in this merchant' using errcode = 'P0002';
  end if;
  if p.deleted_at is not null then
    raise exception 'VALIDATION: this person was already deleted' using errcode = '22023';
  end if;
  if p_user = auth.uid() then
    raise exception 'VALIDATION: you cannot delete your own login' using errcode = '22023';
  end if;
  if exists (select 1 from public.platform_staff s where s.user_id = p_user) then
    raise exception 'VALIDATION: this person is on the platform team; switch them off under Employees instead' using errcode = '22023';
  end if;
  select r.code into v_role from public.roles r where r.id = p.role_id;
  if v_role = 'OWNER' and p.is_active and not exists (
    select 1 from public.profiles o join public.roles r on r.id = o.role_id
    where o.merchant_id = p_merchant and o.id <> p_user and o.is_active and o.deleted_at is null and r.code = 'OWNER') then
    raise exception 'VALIDATION: this is the merchant''s only owner; make someone else owner first, or delete the merchant' using errcode = '22023';
  end if;

  update public.profiles set is_active = false, deleted_at = now() where id = p_user;
  insert into public.account_removals (user_id, from_merchant, reason) values (p_user, p_merchant, 'Deleted by Super Admin');
  perform public._platform_log('merchants.user_deleted', p_merchant, 'profile', p_user::text, trim(p_reason),
    jsonb_build_object('email', p.email, 'full_name', p.full_name, 'role', v_role, 'is_active', p.is_active), null);
  return jsonb_build_object('deleted', true, 'user_id', p_user);
end;

platform_notifications_list.src:
begin
  if not public.is_platform_staff() then
    raise exception 'PERMISSION_DENIED: platform staff only' using errcode = '42501';
  end if;
  return jsonb_build_object(
    'unread', (select count(*) from public.platform_notifications where user_id = auth.uid() and read_at is null),
    'items', (select coalesce(jsonb_agg(jsonb_build_object('id', n.id, 'kind', n.kind, 'severity', n.severity, 'title', n.title, 'body', n.body,
        'link', n.link, 'read', n.read_at is not null, 'created_at', n.created_at,
        'merchant', (select jsonb_build_object('id', m.id, 'number', m.number, 'name', m.name) from public.merchants m where m.id = n.merchant_id))
        order by n.created_at desc), '[]'::jsonb)
      from (select * from public.platform_notifications where user_id = auth.uid()
            order by created_at desc limit least(greatest(coalesce(p_limit, 30), 1), 100)) n));
end;

platform_notifications_read.src:
declare
  v_n int;
begin
  if not public.is_platform_staff() then
    raise exception 'PERMISSION_DENIED: platform staff only' using errcode = '42501';
  end if;
  update public.platform_notifications set read_at = now()
  where user_id = auth.uid() and read_at is null and (p_ids is null or id = any (p_ids));
  get diagnostics v_n = row_count;
  return v_n;
end;

platform_ops_run.src:
declare
  a public.platform_announcements;
  v_published int := 0;
  v_sessions int;
  v_auto jsonb;
  v_retention jsonb;
begin
  if not public.is_system_context() then
    raise exception 'PERMISSION_DENIED' using errcode = '42501';
  end if;
  v_sessions := public._platform_support_expire();
  for a in select * from public.platform_announcements where status = 'SCHEDULED' and publish_at <= now() for update skip locked loop
    perform public._platform_announcement_deliver(a);
    v_published := v_published + 1;
  end loop;
  v_auto := public.platform_automation_run(null);
  -- Once a day.
  if coalesce((select (value ->> 'last_run_at')::timestamptz from public.platform_settings where key = 'retention_state'), '-infinity'::timestamptz)
     < now() - interval '23 hours' then
    v_retention := public._platform_retention_run();
  end if;
  return jsonb_build_object('support_sessions_closed', v_sessions, 'announcements_published', v_published, 'automation', v_auto, 'retention', v_retention);
end;

platform_order_fee_charges.src:
begin
  perform public._platform_require('credits', 'view', p_merchant);
  return coalesce((select jsonb_agg(to_jsonb(c) order by c.id desc) from (
    select id, order_id, order_number, fee, charge, created_at from public.order_fee_charges
    where merchant_id = p_merchant order by id desc limit greatest(least(coalesce(p_limit, 100), 500), 1)) c), '[]'::jsonb);
end;

platform_order_fee_override_set.src:
declare
  v_before jsonb := (select to_jsonb(o) from public.merchant_order_fees o where merchant_id = p_merchant);
begin
  perform public._platform_require('credits', 'manage', p_merchant);
  if not exists (select 1 from public.merchants where id = p_merchant) then
    raise exception 'NOT_FOUND: merchant not found' using errcode = 'P0002';
  end if;
  if coalesce(length(trim(p_reason)), 0) < 5 then
    raise exception 'VALIDATION: give a reason (at least 5 characters)' using errcode = '22023';
  end if;
  if p_fee is not null and (p_fee < 0 or p_fee > 1000 or p_fee <> round(p_fee, 2)) then
    raise exception 'VALIDATION: the fee must be between 0 and 1000 Tk, with at most 2 decimals' using errcode = '22023';
  end if;
  if p_fee is null and not coalesce(p_exempt, false) then
    delete from public.merchant_order_fees where merchant_id = p_merchant;
  else
    insert into public.merchant_order_fees (merchant_id, fee, exempt, reason, set_by)
    values (p_merchant, p_fee, coalesce(p_exempt, false), trim(p_reason), auth.uid())
    on conflict (merchant_id) do update set fee = excluded.fee, exempt = excluded.exempt, reason = excluded.reason,
      set_by = excluded.set_by, set_at = now();
  end if;
  perform public._platform_log('credits.order_fee_override', p_merchant, 'merchant', p_merchant::text, trim(p_reason), v_before,
    (select to_jsonb(o) from public.merchant_order_fees o where merchant_id = p_merchant));
  return public._order_fee_state(p_merchant);
end;

platform_order_fee_settings_save.src:
declare
  v_before jsonb := coalesce((select value from public.platform_settings where key = 'order_fee'), '{}'::jsonb);
  v_after jsonb;
  v_fee numeric;
begin
  perform public._platform_require('credits', 'manage');
  if coalesce(length(trim(p_reason)), 0) < 5 then
    raise exception 'VALIDATION: give a reason (at least 5 characters)' using errcode = '22023';
  end if;
  begin
    v_fee := (p ->> 'fee')::numeric;
  exception when others then
    raise exception 'VALIDATION: enter the fee in Tk, for example 1.50' using errcode = '22023';
  end;
  if v_fee is null or v_fee < 0 or v_fee > 1000 or v_fee <> round(v_fee, 2) then
    raise exception 'VALIDATION: the fee must be between 0 and 1000 Tk, with at most 2 decimals' using errcode = '22023';
  end if;
  if coalesce(p ->> 'on_empty', 'BLOCK') not in ('BLOCK', 'ALLOW') then
    raise exception 'VALIDATION: with an empty balance, either refuse approvals (BLOCK) or let them through as unpaid (ALLOW)' using errcode = '22023';
  end if;
  if coalesce(nullif(p ->> 'free_per_month', '')::int, 0) not between 0 and 100000
     or coalesce(nullif(p ->> 'low_balance_tk', '')::numeric, 0) not between 0 and 1000000 then
    raise exception 'VALIDATION: free orders and the low-balance warning must be zero or more' using errcode = '22023';
  end if;
  if jsonb_typeof(coalesce(p -> 'unmetered_plans', '[]'::jsonb)) <> 'array' then
    raise exception 'VALIDATION: plans that are never charged must be a list of plan codes' using errcode = '22023';
  end if;
  v_after := jsonb_build_object(
    'enabled', coalesce((p ->> 'enabled')::boolean, false),
    'fee', v_fee,
    'on_empty', coalesce(p ->> 'on_empty', 'BLOCK'),
    'free_per_month', coalesce(nullif(p ->> 'free_per_month', '')::int, 0),
    'unmetered_plans', coalesce((select jsonb_agg(distinct upper(x)) from jsonb_array_elements_text(p -> 'unmetered_plans') x
                                 where exists (select 1 from public.plans where code = upper(x))), '[]'::jsonb),
    'low_balance_tk', coalesce(nullif(p ->> 'low_balance_tk', '')::numeric, 100));
  insert into public.platform_settings (key, value, description, updated_at)
  values ('order_fee', v_after, 'Fee for each approved order, paid from the store balance', now())
  on conflict (key) do update set value = excluded.value, updated_at = now();
  perform public._config_version('platform_setting', 'order_fee', v_after, trim(p_reason));
  perform public._platform_log('settings.order_fee', null, 'platform_setting', 'order_fee', trim(p_reason), v_before, v_after);
  return v_after;
end;

platform_payment_record.src:
declare
  v_inv public.billing_invoices;
  v public.billing_payments;
begin
  select * into v_inv from public.billing_invoices where id = p_invoice;
  if v_inv.id is null then
    raise exception 'NOT_FOUND: invoice not found' using errcode = 'P0002';
  end if;
  perform public._platform_require('subscriptions', 'manage', v_inv.merchant_id);
  if v_inv.status <> 'OPEN' then
    raise exception 'VALIDATION: the invoice is %', lower(v_inv.status) using errcode = '22023';
  end if;
  if nullif(trim(p ->> 'reference'), '') is null then
    raise exception 'VALIDATION: enter the transaction or receipt reference' using errcode = '22023';
  end if;
  insert into public.billing_payments (merchant_id, invoice_id, amount, method, reference, status, recorded_by, note)
  values (v_inv.merchant_id, v_inv.id, (p ->> 'amount')::numeric, coalesce(p ->> 'method', 'BANK'), trim(p ->> 'reference'), 'PENDING', auth.uid(), p ->> 'note')
  returning * into v;
  perform public._platform_log('billing.payment_recorded', v_inv.merchant_id, 'billing_payment', v.id::text, p ->> 'note', null,
    jsonb_build_object('invoice', v_inv.number, 'amount', v.amount, 'method', v.method, 'reference', v.reference), 'REQUESTED');
  return to_jsonb(v) - 'raw';
end;

platform_payment_verify.src:
declare
  v public.billing_payments;
  v_inv public.billing_invoices;
begin
  select * into v from public.billing_payments where id = p_payment for update;
  if v.id is null then
    raise exception 'NOT_FOUND: payment not found' using errcode = 'P0002';
  end if;
  perform public._platform_require('subscriptions', 'approve', v.merchant_id);
  if v.status <> 'PENDING' then
    raise exception 'VALIDATION: this payment is already %', lower(v.status) using errcode = '22023';
  end if;
  if v.recorded_by = auth.uid() then
    raise exception 'PERMISSION_DENIED: a second person must verify a payment you recorded' using errcode = '42501';
  end if;
  update public.billing_payments set status = case when p_approve then 'SUCCEEDED' else 'REJECTED' end, verified_by = auth.uid(), verified_at = now(),
    note = coalesce(note || ' · ', '') || coalesce(p_note, '')
  where id = v.id returning * into v;
  if p_approve then
    v_inv := public._billing_apply_payment(v);
  end if;
  perform public._platform_log(case when p_approve then 'billing.payment_verified' else 'billing.payment_rejected' end, v.merchant_id, 'billing_payment',
    v.id::text, p_note, null, jsonb_build_object('amount', v.amount, 'invoice_status', v_inv.status));
  return jsonb_build_object('payment', to_jsonb(v) - 'raw', 'invoice', to_jsonb(v_inv));
end;

