platform_pbx_settings_save.src:
declare
  v_before jsonb := public._vd_cfg();
  v jsonb := public._vd_cfg();
  u text;
  k text;
begin
  perform public._platform_require('pbx', 'manage');
  if p ? 'sip_domain' then
    if nullif(trim(p ->> 'sip_domain'), '') is not null and trim(p ->> 'sip_domain') !~ '^[A-Za-z0-9.-]{3,253}$' then
      raise exception 'VALIDATION: the SIP domain is a host name like pbx.example.com' using errcode = '22023';
    end if;
    v := v || jsonb_build_object('sip_domain', nullif(lower(trim(p ->> 'sip_domain')), ''));
  end if;
  if p ? 'wss_url' then
    -- Browsers need WSS; plain ws:// only for a gateway on this machine (local testing).
    if nullif(trim(p ->> 'wss_url'), '') is not null and trim(p ->> 'wss_url') !~ '^wss://[^\s/]+(/\S*)?$'
       and trim(p ->> 'wss_url') !~ '^ws://(localhost|127\.0\.0\.1)(:[0-9]+)?(/\S*)?$' then
      raise exception 'VALIDATION: the WebSocket address starts with wss://' using errcode = '22023';
    end if;
    v := v || jsonb_build_object('wss_url', nullif(trim(p ->> 'wss_url'), ''));
  end if;
  foreach k in array array['turn_urls', 'stun_urls'] loop
    if p ? k then
      if jsonb_typeof(p -> k) <> 'array' then
        raise exception 'VALIDATION: % is a list of addresses', replace(k, '_', ' ') using errcode = '22023';
      end if;
      for u in select jsonb_array_elements_text(p -> k) loop
        if (k = 'turn_urls' and u !~ '^turns?:[^\s]+$') or (k = 'stun_urls' and u !~ '^stuns?:[^\s]+$') then
          raise exception 'VALIDATION: % addresses start with %', upper(split_part(k, '_', 1)), case when k = 'turn_urls' then 'turn: or turns:' else 'stun:' end using errcode = '22023';
        end if;
      end loop;
      v := v || jsonb_build_object(k, p -> k);
    end if;
  end loop;
  if p ? 'credential_ttl_seconds' then
    if (p ->> 'credential_ttl_seconds')::int not between 120 and 3600 then
      raise exception 'VALIDATION: a softphone password lasts 2–60 minutes' using errcode = '22023';
    end if;
    v := v || jsonb_build_object('credential_ttl_seconds', (p ->> 'credential_ttl_seconds')::int);
  end if;
  if p ? 'rate_tk_per_min' then
    if (p ->> 'rate_tk_per_min')::numeric not between 0.01 and 10 then
      raise exception 'VALIDATION: the rate is 0.01–10 tk a minute' using errcode = '22023';
    end if;
    v := v || jsonb_build_object('rate_tk_per_min', (p ->> 'rate_tk_per_min')::numeric);
  end if;
  if p ? 'vat_percent' then
    if (p ->> 'vat_percent')::numeric not between 0 and 50 then
      raise exception 'VALIDATION: VAT is 0–50%%' using errcode = '22023';
    end if;
    v := v || jsonb_build_object('vat_percent', (p ->> 'vat_percent')::numeric);
  end if;
  foreach k in array array['min_topup_tk', 'max_topup_tk', 'extra_agent_tk', 'extra_channel_tk'] loop
    if p ? k then
      if (p ->> k)::numeric not between 0 and 1000000 then
        raise exception 'VALIDATION: % must be 0 or more', replace(k, '_', ' ') using errcode = '22023';
      end if;
      v := v || jsonb_build_object(k, (p ->> k)::numeric);
    end if;
  end loop;
  if (v ->> 'min_topup_tk')::numeric > (v ->> 'max_topup_tk')::numeric then
    raise exception 'VALIDATION: the smallest top-up cannot be more than the largest' using errcode = '22023';
  end if;
  if p ? 'maintenance' then
    if nullif(p #>> '{maintenance,until}', '') is not null and nullif(p #>> '{maintenance,starts_at}', '') is not null
       and (p #>> '{maintenance,until}')::timestamptz <= (p #>> '{maintenance,starts_at}')::timestamptz then
      raise exception 'VALIDATION: maintenance must end after it starts' using errcode = '22023';
    end if;
    v := v || jsonb_build_object('maintenance', jsonb_build_object(
      'starts_at', nullif(p #>> '{maintenance,starts_at}', '')::timestamptz,
      'until', nullif(p #>> '{maintenance,until}', '')::timestamptz,
      'message', left(nullif(trim(p #>> '{maintenance,message}'), ''), 200)));
  end if;
  update public.platform_settings set value = v, updated_by = auth.uid() where key = 'voicedrive';
  perform public._config_version('platform_setting', 'voicedrive', v, p_reason);
  perform public._platform_log('pbx.settings_changed', null, 'platform_setting', 'voicedrive', p_reason, v_before, v);
  return v;
end;

platform_pbx_setup.src:
declare
  b public.pbx_businesses := public._platform_pbx_business(p_merchant);
  v_before jsonb;
  v_after jsonb;
begin
  if not exists (select 1 from public.merchants where id = p_merchant and status <> 'CLOSED') or not public.platform_can('pbx', 'view', p_merchant) then
    raise exception 'NOT_FOUND: merchant not found' using errcode = 'P0002';
  end if;
  perform public._platform_require('pbx', 'manage', p_merchant);
  perform public._platform_in_merchant(p_merchant);
  if b.id is null then
    insert into public.pbx_businesses (merchant_id, name, is_primary)
    values (p_merchant, (select name from public.merchants where id = p_merchant), true) returning * into b;
    insert into public.pbx_ring_groups (merchant_id, business_id, name, is_default) values (p_merchant, b.id, 'Everyone', true);
  end if;
  v_before := to_jsonb(b) - 'trunk_user';
  -- Checked across every merchant (the line procedure only sees this one).
  if exists (select 1 from public.pbx_businesses x where x.did = public.normalize_phone(nullif(trim(p ->> 'did'), '')) and x.id <> b.id) then
    raise exception 'VALIDATION: this number is already used by another merchant' using errcode = '22023';
  end if;
  if coalesce(p ->> 'did', '') <> '' or coalesce(p ->> 'trunk_host', '') <> '' then
    perform public.pbx_provision_business_did(p || jsonb_build_object('business_id', b.id));
  end if;
  if p ? 'max_call_minutes' then
    if (p ->> 'max_call_minutes')::int not between 1 and 120 then
      raise exception 'VALIDATION: the longest call is 1–120 minutes' using errcode = '22023';
    end if;
    update public.pbx_businesses set max_call_minutes = (p ->> 'max_call_minutes')::int where id = b.id;
  end if;
  select to_jsonb(x) - 'trunk_user' into v_after from public.pbx_businesses x where id = b.id;
  perform public._platform_in_merchant(null);
  perform public._platform_log('pbx.configured', p_merchant, 'pbx_business', b.id::text, p_reason, v_before, v_after);
  return public._platform_pbx_business_json((select x from public.pbx_businesses x where id = b.id));
end;

platform_pbx_trunk_secret_saved.src:
declare
  b public.pbx_businesses := public._platform_pbx_business(p_merchant);
begin
  if b.id is null or not public.platform_can('pbx', 'view', p_merchant) then
    raise exception 'NOT_FOUND: set up the merchant''s PBX line first' using errcode = 'P0002';
  end if;
  perform public._platform_require('pbx', 'manage', p_merchant);
  -- A new or removed password means the line must be checked again.
  update public.pbx_businesses set trunk_secret_set = p_set, bridge_ready = false where id = b.id;
  perform public._platform_log(case when p_set then 'pbx.trunk_secret_saved' else 'pbx.trunk_secret_cleared' end, p_merchant, 'pbx_business', b.id::text,
    null, jsonb_build_object('trunk_secret_set', b.trunk_secret_set), jsonb_build_object('trunk_secret_set', p_set, 'hint', p_hint));
  return public._platform_pbx_business_json((select x from public.pbx_businesses x where id = b.id));
end;

platform_plan_save.src:
declare
  v_plan public.plans;
  v_before jsonb;
  v_id uuid := nullif(p ->> 'id', '')::uuid;
begin
  perform public._platform_require('subscriptions', case when v_id is null then 'create' else 'edit' end);
  if v_id is not null then
    select to_jsonb(x) into v_before from public.plans x where id = v_id;
    if v_before is null then
      raise exception 'NOT_FOUND: plan not found' using errcode = 'P0002';
    end if;
    -- Existing subscriptions keep their price until changed on purpose.
    update public.plans set
      name = coalesce(nullif(trim(p ->> 'name'), ''), name),
      description = case when p ? 'description' then p ->> 'description' else description end,
      is_public = coalesce((p ->> 'is_public')::boolean, is_public),
      price = coalesce((p ->> 'price')::numeric, price),
      billing_interval = coalesce(p ->> 'billing_interval', billing_interval),
      trial_days = coalesce((p ->> 'trial_days')::int, trial_days),
      limits = coalesce(p -> 'limits', limits),
      overage = coalesce(p -> 'overage', overage),
      features = coalesce(p -> 'features', features),
      sort_order = coalesce((p ->> 'sort_order')::int, sort_order)
    where id = v_id returning * into v_plan;
  else
    insert into public.plans (code, name, description, is_public, price, billing_interval, trial_days, limits, overage, features, sort_order, created_by)
    values (upper(regexp_replace(coalesce(nullif(p ->> 'code', ''), p ->> 'name'), '[^A-Za-z0-9]+', '_', 'g')), trim(p ->> 'name'), p ->> 'description',
            coalesce((p ->> 'is_public')::boolean, true), coalesce((p ->> 'price')::numeric, 0), coalesce(p ->> 'billing_interval', 'MONTH'),
            coalesce((p ->> 'trial_days')::int, 0), coalesce(p -> 'limits', '{}'::jsonb), coalesce(p -> 'overage', '{}'::jsonb),
            coalesce(p -> 'features', '{}'::jsonb), coalesce((p ->> 'sort_order')::int, 100), auth.uid())
    returning * into v_plan;
  end if;
  perform public._config_version('plan', v_plan.id::text, to_jsonb(v_plan), p ->> 'note');
  perform public._platform_log(case when v_id is null then 'subscription.plan_created' else 'subscription.plan_updated' end, null, 'plan',
    v_plan.id::text, p ->> 'note', v_before, to_jsonb(v_plan));
  return to_jsonb(v_plan);
end;

platform_plan_set_status.src:
declare
  v_plan public.plans;
begin
  perform public._platform_require('subscriptions', 'manage');
  update public.plans set status = p_status where id = p_id and p_status in ('ACTIVE', 'ARCHIVED') returning * into v_plan;
  if v_plan.id is null then
    raise exception 'NOT_FOUND: plan not found' using errcode = 'P0002';
  end if;
  perform public._config_version('plan', v_plan.id::text, to_jsonb(v_plan), 'status ' || p_status);
  perform public._platform_log('subscription.plan_' || lower(p_status), null, 'plan', p_id::text, null, null, jsonb_build_object('status', p_status));
end;

platform_plans_list.src:
begin
  perform public._platform_require('subscriptions', 'view');
  return jsonb_build_object(
    'plans', coalesce((select jsonb_agg(to_jsonb(p) || jsonb_build_object(
        'subscribers', (select count(*) from public.subscriptions s where s.plan_id = p.id and s.ended_at is null),
        'mrr', (select coalesce(sum(case s.billing_interval when 'YEAR' then s.price / 12 else s.price end), 0) from public.subscriptions s
                where s.plan_id = p.id and s.ended_at is null and s.status in ('ACTIVE', 'PAST_DUE')))
      order by p.status, p.sort_order, p.price) from public.plans p), '[]'::jsonb),
    'addons', coalesce((select jsonb_agg(to_jsonb(a) order by a.status, a.name) from public.plan_addons a), '[]'::jsonb),
    'features', coalesce((select jsonb_agg(to_jsonb(f) order by f.sort_order) from public.features f), '[]'::jsonb));
end;

platform_record_action.src:
begin
  if not public.is_system_context() then
    raise exception 'PERMISSION_DENIED' using errcode = '42501';
  end if;
  insert into public.platform_audit_logs (actor_id, actor_email, action, entity_type, entity_id, result, metadata)
  values (p_actor, (select email from public.platform_staff where user_id = p_actor), p_action, p_entity_type, p_entity_id,
          case when p_result in ('SUCCESS', 'FAILED') then p_result else 'SUCCESS' end, coalesce(p_metadata, '{}'::jsonb));
end;

platform_report_denied.src:
begin
  if not public.is_platform_staff() then
    raise exception 'PERMISSION_DENIED' using errcode = '42501';
  end if;
  -- At most one report per person and action a minute.
  if exists (select 1 from public.platform_audit_logs where actor_id = auth.uid() and action = left(p_action, 80) and result = 'DENIED'
             and created_at > now() - interval '1 minute') then
    return;
  end if;
  perform public._platform_log(left(coalesce(p_action, 'unknown'), 80), null, null, null, null, null, null, 'DENIED',
    jsonb_build_object('reported_by_panel', true, 'detail', left(coalesce(p_detail, '{}'::jsonb)::text, 2000)));
end;

platform_request_approval.src:
declare
  v_id uuid;
begin
  if not public.is_platform_staff() then
    raise exception 'PERMISSION_DENIED' using errcode = '42501';
  end if;
  if coalesce(length(trim(p_reason)), 0) < 5 then
    raise exception 'VALIDATION: explain why (at least 5 characters)' using errcode = '22023';
  end if;
  -- The same request waiting already: no second copy.
  select id into v_id from public.platform_approvals
  where status = 'PENDING' and expires_at > now() and action = p_action and requested_by = auth.uid()
    and merchant_id is not distinct from p_merchant and payload = p_payload;
  if v_id is not null then
    return v_id;
  end if;
  insert into public.platform_approvals (action, module, merchant_id, summary, payload, reason, requested_by)
  values (p_action, p_module, p_merchant, p_summary, coalesce(p_payload, '{}'::jsonb), trim(p_reason), auth.uid())
  returning id into v_id;
  perform public._platform_log('approval.requested', p_merchant, 'platform_approval', v_id::text, p_reason, null,
    jsonb_build_object('action', p_action, 'summary', p_summary), 'REQUESTED');
  return v_id;
end;

platform_restore_test_record.src:
declare
  t public.platform_restore_tests;
begin
  perform public._platform_require('data', 'manage');
  if upper(coalesce(p ->> 'result', '')) not in ('PASSED', 'PARTIAL', 'FAILED') then
    raise exception 'VALIDATION: choose the result' using errcode = '22023';
  end if;
  if nullif(p ->> 'tested_at', '') is null or (p ->> 'tested_at')::timestamptz > now() + interval '1 hour' then
    raise exception 'VALIDATION: when was it tested?' using errcode = '22023';
  end if;
  if length(trim(coalesce(p ->> 'environment', ''))) < 2 then
    raise exception 'VALIDATION: say where it was restored (e.g. a staging project)' using errcode = '22023';
  end if;
  insert into public.platform_restore_tests (tested_at, backup_taken_at, environment, result, duration_minutes, checks, notes, recorded_by, recorded_by_email)
  values ((p ->> 'tested_at')::timestamptz, nullif(p ->> 'backup_taken_at', '')::timestamptz, trim(p ->> 'environment'), upper(p ->> 'result'),
          nullif(p ->> 'duration_minutes', '')::int, coalesce(p -> 'checks', '{}'::jsonb), nullif(trim(coalesce(p ->> 'notes', '')), ''),
          auth.uid(), (select email from public.platform_staff where user_id = auth.uid()))
  returning * into t;
  perform public._platform_log('data.restore_test_recorded', null, 'restore_test', t.id::text, null, null, to_jsonb(t));
  return to_jsonb(t);
end;

platform_retention_run_now.src:
declare
  v_out jsonb;
begin
  perform public._platform_require('data', 'manage');
  v_out := public._platform_retention_run();
  perform public._platform_log('data.retention_run', null, 'platform_setting', 'retention', p_reason, null, v_out);
  return v_out;
end;

platform_role_delete.src:
declare
  v_role public.platform_roles;
begin
  if not public._platform_is_super() then
    raise exception 'PERMISSION_DENIED: only a Super Admin can change roles' using errcode = '42501';
  end if;
  select * into v_role from public.platform_roles where id = p_id for update;
  if v_role.id is null then
    raise exception 'NOT_FOUND: role not found' using errcode = 'P0002';
  end if;
  if v_role.is_system then
    raise exception 'VALIDATION: built-in roles cannot be removed' using errcode = '22023';
  end if;
  if exists (select 1 from public.platform_staff where role_id = p_id) then
    raise exception 'VALIDATION: move the people in this role to another role first' using errcode = '22023';
  end if;
  delete from public.platform_roles where id = p_id;
  perform public._platform_log('employees.role_delete', null, 'platform_role', p_id::text, null, to_jsonb(v_role), null);
end;

platform_role_save.src:
declare
  v_role public.platform_roles;
  v_before jsonb;
  v_perm text;
  v_module text;
  v_action text;
begin
  if not public._platform_is_super() then
    raise exception 'PERMISSION_DENIED: only a Super Admin can change roles' using errcode = '42501';
  end if;
  if nullif(p ->> 'id', '') is not null then
    select * into v_role from public.platform_roles where id = (p ->> 'id')::uuid for update;
    if v_role.id is null then
      raise exception 'NOT_FOUND: role not found' using errcode = 'P0002';
    end if;
    if v_role.is_super then
      raise exception 'VALIDATION: the Super Admin role always has every permission' using errcode = '22023';
    end if;
    v_before := jsonb_build_object('name', v_role.name, 'permissions',
      (select coalesce(jsonb_agg(module || '.' || action order by module, action), '[]'::jsonb) from public.platform_role_permissions where role_id = v_role.id));
    update public.platform_roles set name = coalesce(nullif(trim(p ->> 'name'), ''), name), description = coalesce(p ->> 'description', description)
    where id = v_role.id returning * into v_role;
  else
    insert into public.platform_roles (code, name, description, created_by)
    values (upper(regexp_replace(coalesce(nullif(p ->> 'code', ''), p ->> 'name'), '[^A-Za-z0-9]+', '_', 'g')), trim(p ->> 'name'), p ->> 'description', auth.uid())
    returning * into v_role;
  end if;
  if p ? 'permissions' then
    delete from public.platform_role_permissions where role_id = v_role.id;
    for v_perm in select jsonb_array_elements_text(p -> 'permissions') loop
      v_module := split_part(v_perm, '.', 1);
      v_action := split_part(v_perm, '.', 2);
      if not exists (select 1 from public.platform_modules where code = v_module and v_action = any (actions)) then
        raise exception 'VALIDATION: unknown permission %', v_perm using errcode = '22023';
      end if;
      insert into public.platform_role_permissions (role_id, module, action) values (v_role.id, v_module, v_action);
    end loop;
  end if;
  perform public._platform_log('employees.role_save', null, 'platform_role', v_role.id::text, null, v_before,
    jsonb_build_object('name', v_role.name, 'permissions', p -> 'permissions'));
  return to_jsonb(v_role);
end;

platform_roles_list.src:
begin
  perform public._platform_require('employees', 'view');
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', r.id, 'code', r.code, 'name', r.name, 'description', r.description, 'is_system', r.is_system, 'is_super', r.is_super,
      'staff', (select count(*) from public.platform_staff s where s.role_id = r.id and s.removed_at is null),
      'permissions', case when r.is_super then '["*"]'::jsonb
        else (select coalesce(jsonb_agg(rp.module || '.' || rp.action order by rp.module, rp.action), '[]'::jsonb)
              from public.platform_role_permissions rp where rp.role_id = r.id) end)
      order by r.is_super desc, r.is_system desc, r.name)
    from public.platform_roles r), '[]'::jsonb);
end;

platform_search.src:
declare
  v_q text := trim(coalesce(p_q, ''));
  v_like text;
begin
  if not public.is_platform_staff() then
    raise exception 'PERMISSION_DENIED' using errcode = '42501';
  end if;
  if length(v_q) < 2 then
    return jsonb_build_object('merchants', '[]'::jsonb, 'employees', '[]'::jsonb, 'stores', '[]'::jsonb, 'orders', '[]'::jsonb,
                              'errors', '[]'::jsonb, 'audit', '[]'::jsonb, 'tickets', '[]'::jsonb);
  end if;
  v_like := '%' || replace(replace(v_q, '%', ''), '_', '') || '%';
  return jsonb_build_object(
    'merchants', case when public.platform_can('merchants', 'view') then coalesce((select jsonb_agg(jsonb_build_object(
        'id', m.id, 'number', m.number, 'name', m.name, 'status', m.status, 'owner_email', m.owner_email))
      from (select * from public.merchants m where m.id in (select public._platform_merchant_ids())
              and (m.name ilike v_like or m.owner_email ilike v_like or m.phone ilike v_like or m.slug ilike v_like or m.number::text = v_q)
            order by m.number limit 8) m), '[]'::jsonb) else '[]'::jsonb end,
    'employees', case when public.platform_can('employees', 'view') then coalesce((select jsonb_agg(jsonb_build_object(
        'id', s.user_id, 'name', coalesce(nullif(s.full_name, ''), s.email), 'email', s.email, 'is_active', s.is_active))
      from (select * from public.platform_staff s where s.full_name ilike v_like or s.email ilike v_like limit 6) s), '[]'::jsonb) else '[]'::jsonb end,
    'stores', case when public.platform_can('merchants', 'view') then coalesce((select jsonb_agg(jsonb_build_object(
        'id', c.id, 'platform', c.platform, 'name', c.name, 'shop_domain', c.shop_domain, 'status', c.status, 'merchant_id', c.merchant_id,
        'merchant', (select m.name from public.merchants m where m.id = c.merchant_id)))
      from (select * from public.sales_channels c where c.merchant_id in (select public._platform_merchant_ids())
              and (c.shop_domain ilike v_like or c.name ilike v_like) limit 6) c), '[]'::jsonb) else '[]'::jsonb end,
    'orders', case when public.platform_can('merchants', 'view') then coalesce((select jsonb_agg(jsonb_build_object(
        'id', o.id, 'order_number', o.order_number, 'external_order_number', o.external_order_number, 'status', o.status,
        'merchant_id', o.merchant_id, 'merchant', (select m.name from public.merchants m where m.id = o.merchant_id), 'created_at', o.created_at))
      from (select * from public.orders o where o.merchant_id in (select public._platform_merchant_ids())
              and (o.order_number ilike v_q || '%' or o.external_order_number = v_q or o.external_order_id = v_q)
            order by o.created_at desc limit 8) o), '[]'::jsonb) else '[]'::jsonb end,
    'errors', case when public.platform_can('health', 'view') then coalesce((select jsonb_agg(jsonb_build_object(
        'id', l.id, 'level', l.level, 'category', l.category, 'message', l.message, 'merchant_id', l.merchant_id, 'last_seen_at', l.last_seen_at))
      from (select * from public.system_logs l where (l.merchant_id is null or l.merchant_id in (select public._platform_merchant_ids()))
              and l.message ilike v_like order by l.last_seen_at desc limit 6) l), '[]'::jsonb) else '[]'::jsonb end,
    'audit', case when public.platform_can('audit', 'view') then coalesce((select jsonb_agg(jsonb_build_object(
        'id', a.id, 'action', a.action, 'entity_id', a.entity_id, 'actor_email', a.actor_email, 'created_at', a.created_at))
      from (select * from public.platform_audit_logs a where (a.merchant_id is null or a.merchant_id in (select public._platform_merchant_ids()))
              and (a.action ilike v_like or a.entity_id ilike v_like or a.reason ilike v_like) order by a.created_at desc limit 6) a), '[]'::jsonb) else '[]'::jsonb end,
    'tickets', case when public.platform_can('support', 'view') then coalesce((select jsonb_agg(jsonb_build_object(
        'id', t.id, 'number', t.number, 'subject', t.subject, 'status', t.status, 'merchant_id', t.merchant_id,
        'merchant', (select m.name from public.merchants m where m.id = t.merchant_id)))
      from (select * from public.support_tickets t where t.merchant_id in (select public._platform_merchant_ids())
              and (t.subject ilike v_like or t.number::text = v_q) order by t.created_at desc limit 6) t), '[]'::jsonb) else '[]'::jsonb end
  );
end;

platform_secret_clear.src:
declare
  v_secret uuid;
begin
  if not public.is_system_context() then
    raise exception 'PERMISSION_DENIED' using errcode = '42501';
  end if;
  select secret_id into v_secret from public.platform_credentials where key = p_key;
  if v_secret is not null then
    perform vault.update_secret(v_secret, '{}');
  end if;
  update public.platform_credentials set hint = null, updated_by = p_actor, updated_at = now() where key = p_key;
  insert into public.platform_audit_logs (actor_id, actor_email, action, entity_type, entity_id)
  values (p_actor, (select email from public.platform_staff where user_id = p_actor), 'platform_credential.cleared', 'platform_credential', p_key);
end;

platform_secret_get.src:
declare
  v_secret uuid;
  v_value text;
begin
  if not public.is_system_context() then
    raise exception 'PERMISSION_DENIED' using errcode = '42501';
  end if;
  select secret_id into v_secret from public.platform_credentials where key = p_key and hint is not null;
  if v_secret is null then
    return null;
  end if;
  select decrypted_secret into v_value from vault.decrypted_secrets where id = v_secret;
  return nullif(nullif(v_value, ''), '{}')::jsonb;
end;

platform_secret_store.src:
declare
  v_secret uuid;
  v_name text := 'platform:' || p_key;
begin
  if not public.is_system_context() then
    raise exception 'PERMISSION_DENIED' using errcode = '42501';
  end if;
  if p_key !~ '^[a-z0-9_.:-]{2,80}$' then
    raise exception 'VALIDATION: bad credential key' using errcode = '22023';
  end if;
  if p_value is null or jsonb_typeof(p_value) <> 'object' then
    raise exception 'VALIDATION: credentials must be an object' using errcode = '22023';
  end if;
  select secret_id into v_secret from public.platform_credentials where key = p_key;
  if v_secret is null then
    select id into v_secret from vault.secrets where name = v_name;
  end if;
  if v_secret is null then
    v_secret := vault.create_secret(p_value::text, v_name, 'Platform credentials');
  else
    perform vault.update_secret(v_secret, p_value::text);
  end if;
  insert into public.platform_credentials (key, secret_id, hint, updated_by, updated_at)
  values (p_key, v_secret, p_hint, p_actor, now())
  on conflict (key) do update set secret_id = excluded.secret_id, hint = excluded.hint, updated_by = excluded.updated_by, updated_at = now();
  insert into public.platform_audit_logs (actor_id, actor_email, action, entity_type, entity_id, metadata)
  values (p_actor, (select email from public.platform_staff where user_id = p_actor), 'platform_credential.saved', 'platform_credential',
          p_key, jsonb_build_object('hint', p_hint));
end;

platform_service_override_set.src:
declare
  v_before jsonb;
  v_ids jsonb := coalesce((select value -> 'sender_ids' from public.platform_settings where key = 'sms'), '[]'::jsonb);
begin
  perform public._platform_require(public._usage_module(p_service), 'edit', p_merchant);
  if coalesce(length(trim(p_reason)), 0) < 3 then
    raise exception 'VALIDATION: give a reason' using errcode = '22023';
  end if;
  if p_sender_id is not null and p_service <> 'SMS' then
    raise exception 'VALIDATION: a sender ID is for SMS only' using errcode = '22023';
  end if;
  if nullif(trim(p_sender_id), '') is not null and jsonb_array_length(v_ids) > 0 and not v_ids ? trim(p_sender_id) then
    raise exception 'VALIDATION: use one of the approved sender IDs' using errcode = '22023';
  end if;
  select to_jsonb(o) into v_before from public.merchant_service_overrides o where merchant_id = p_merchant and service = p_service;
  if p_free_limit is null and p_monthly_cap is null and nullif(trim(p_sender_id), '') is null then
    delete from public.merchant_service_overrides where merchant_id = p_merchant and service = p_service;
  else
    insert into public.merchant_service_overrides (merchant_id, service, free_limit, monthly_cap, sender_id, reason, set_by)
    values (p_merchant, p_service, p_free_limit, p_monthly_cap, nullif(trim(p_sender_id), ''), trim(p_reason), auth.uid())
    on conflict (merchant_id, service) do update set free_limit = excluded.free_limit, monthly_cap = excluded.monthly_cap, sender_id = excluded.sender_id,
      reason = excluded.reason, set_by = excluded.set_by, set_at = now();
  end if;
  perform public._platform_log(public._usage_module(p_service) || '.merchant_limits_changed', p_merchant, 'merchant_service_override', p_service, p_reason,
    v_before, jsonb_build_object('free_limit', p_free_limit, 'monthly_cap', p_monthly_cap, 'sender_id', p_sender_id));
  return public._usage_state(p_merchant, p_service);
end;

platform_setting_save.src:
declare
  v_before jsonb;
  k text;
begin
  if p_key like 'usage.%' then
    -- Validated, permission-checked and versioned there.
    return public.platform_usage_policy_save(upper(substr(p_key, 7)), p_value, coalesce(p_reason, 'Settings change'));
  end if;
  if p_key = 'support' then
    return public.platform_support_settings_save(p_value, p_reason);
  end if;
  if p_key = 'cost_assumptions' then
    return public.platform_cost_assumptions_save(p_value, p_reason);
  end if;
  if p_key = 'voicedrive' then
    return public.platform_pbx_settings_save(p_value, p_reason);
  end if;
  if p_key in ('sms', 'bd_courier', 'billing_gateways') then
    raise exception 'VALIDATION: % is changed on its own page (it holds connection state)', p_key using errcode = '22023';
  end if;
  if p_key in ('integration_health', 'retention_state', 'storefront') then
    raise exception 'VALIDATION: % is kept by the platform itself', p_key using errcode = '22023';
  end if;
  perform public._platform_require('settings', 'edit');
  if p_key = 'access_rules' then
    perform public._platform_require('subscriptions', 'manage');
    if exists (select 1 from jsonb_each_text(p_value) e where e.value not in ('FULL', 'READ_ONLY', 'BLOCKED')) then
      raise exception 'VALIDATION: each rule is FULL, READ_ONLY or BLOCKED' using errcode = '22023';
    end if;
  end if;
  if p_key = 'credits' then
    perform public._platform_require('credits', 'manage');
    if coalesce((p_value ->> 'approval_threshold')::int, -1) < 0 then
      raise exception 'VALIDATION: the approval threshold is a number of credits (0 or more)' using errcode = '22023';
    end if;
  end if;
  if p_key = 'security' then
    perform public._platform_require('security', 'manage');
    if jsonb_typeof(p_value -> 'staff_session_hours') not in ('null', 'number')
       or coalesce((p_value ->> 'staff_session_hours')::numeric, 1) not between 1 and 720 then
      raise exception 'VALIDATION: staff sessions last 1 to 720 hours (or leave it empty for no limit)' using errcode = '22023';
    end if;
    p_value := jsonb_build_object('staff_session_hours', (p_value ->> 'staff_session_hours')::int);
  end if;
  if p_key = 'retention' then
    perform public._platform_require('data', 'manage');
    foreach k in array array['system_logs_days', 'notifications_days'] loop
      if coalesce((p_value ->> k)::int, 0) not between 7 and 3650 then
        raise exception 'VALIDATION: % is 7 to 3650 days', replace(k, '_', ' ') using errcode = '22023';
      end if;
    end loop;
    if coalesce((p_value ->> 'deletion_cooling_days')::int, -1) not between 1 and 90 then
      raise exception 'VALIDATION: the wait before erasing is 1 to 90 days' using errcode = '22023';
    end if;
    p_value := jsonb_build_object('system_logs_days', (p_value ->> 'system_logs_days')::int, 'notifications_days', (p_value ->> 'notifications_days')::int,
      'deletion_cooling_days', (p_value ->> 'deletion_cooling_days')::int);
  end if;
  if p_key !~ '^[a-z0-9_.]{2,60}$' or jsonb_typeof(p_value) <> 'object' then
    raise exception 'VALIDATION: bad setting' using errcode = '22023';
  end if;
  select value into v_before from public.platform_settings where key = p_key;
  insert into public.platform_settings (key, value, updated_by) values (p_key, p_value, auth.uid())
  on conflict (key) do update set value = excluded.value, updated_by = excluded.updated_by;
  perform public._config_version(case when p_key = 'access_rules' then 'access_rules' else 'platform_setting' end, p_key, p_value, p_reason);
  perform public._platform_log('settings.changed', null, 'platform_setting', p_key, p_reason, v_before, p_value);
  return p_value;
end;

platform_settings_get.src:
begin
  perform public._platform_require('settings', 'view');
  return coalesce((select jsonb_object_agg(key, jsonb_build_object('value', value, 'description', description, 'updated_at', updated_at))
                   from public.platform_settings), '{}'::jsonb);
end;

platform_sms_set_balance.src:
begin
  if not public.is_system_context() then
    raise exception 'PERMISSION_DENIED' using errcode = '42501';
  end if;
  update public.platform_settings set value = value || jsonb_build_object('balance', p_balance, 'balance_checked_at', now()) where key = 'sms';
end;

platform_sms_set_connection.src:
declare
  v jsonb;
begin
  if not public.is_system_context() then
    raise exception 'PERMISSION_DENIED' using errcode = '42501';
  end if;
  update public.platform_settings set value = value || case when p_provider is null then
      jsonb_build_object('connected', false, 'provider', null, 'hint', null, 'balance', null, 'connected_at', null)
    else jsonb_build_object('connected', true, 'provider', p_provider, 'hint', p_hint, 'balance', p_balance,
      'balance_checked_at', case when p_balance is null then null else now() end, 'connected_at', now(),
      'sender_id', coalesce(nullif(trim(p_sender_id), ''), value ->> 'sender_id', ''),
      'sender_ids', case when nullif(trim(p_sender_id), '') is null or coalesce(value -> 'sender_ids', '[]'::jsonb) ? trim(p_sender_id)
                         then coalesce(value -> 'sender_ids', '[]'::jsonb) else coalesce(value -> 'sender_ids', '[]'::jsonb) || to_jsonb(trim(p_sender_id)) end) end,
    updated_by = p_actor
  where key = 'sms' returning value into v;
  perform public._platform_log(case when p_provider is null then 'sms.disconnected' else 'sms.connected' end, null, 'platform_credential', 'sms', null, null,
    jsonb_build_object('provider', p_provider, 'hint', p_hint));
  return v;
end;

platform_sms_settings_save.src:
declare
  v_before jsonb := (select value from public.platform_settings where key = 'sms');
  v_ids jsonb := coalesce(p -> 'sender_ids', v_before -> 'sender_ids', '[]'::jsonb);
  v_default text := coalesce(p ->> 'sender_id', v_before ->> 'sender_id', '');
  v_cost numeric := coalesce((p ->> 'cost_per_segment')::numeric, (v_before ->> 'cost_per_segment')::numeric, 0);
  v jsonb;
begin
  perform public._platform_require('sms', 'edit');
  if jsonb_typeof(v_ids) <> 'array' or exists (select 1 from jsonb_array_elements_text(v_ids) s where s !~ '^[A-Za-z0-9 ._+-]{1,20}$') then
    raise exception 'VALIDATION: sender IDs have up to 20 letters, digits, spaces, dots or dashes' using errcode = '22023';
  end if;
  if v_default <> '' and jsonb_array_length(v_ids) > 0 and not v_ids ? v_default then
    raise exception 'VALIDATION: the default sender ID must be one of the approved ones' using errcode = '22023';
  end if;
  if v_cost < 0 or v_cost > 10 then
    raise exception 'VALIDATION: the provider cost per SMS part must be between 0 and 10' using errcode = '22023';
  end if;
  update public.platform_settings set value = value || jsonb_build_object('sender_ids', v_ids, 'sender_id', v_default, 'cost_per_segment', v_cost),
    updated_by = auth.uid()
  where key = 'sms' returning value into v;
  perform public._platform_log('sms.settings_changed', null, 'platform_setting', 'sms', p_reason, v_before, v);
  return v;
end;

platform_staff_assign.src:
declare
  v_before jsonb;
begin
  perform public._platform_require('employees', 'manage');
  if not exists (select 1 from public.platform_staff where user_id = p_user) then
    raise exception 'NOT_FOUND: employee not found' using errcode = 'P0002';
  end if;
  select coalesce(jsonb_agg(merchant_id), '[]'::jsonb) into v_before from public.platform_staff_merchants where user_id = p_user;
  delete from public.platform_staff_merchants where user_id = p_user and merchant_id <> all (coalesce(p_merchants, '{}'));
  insert into public.platform_staff_merchants (user_id, merchant_id, assigned_by)
  select p_user, m, auth.uid() from unnest(coalesce(p_merchants, '{}')) m
  where exists (select 1 from public.merchants where id = m)
  on conflict do nothing;
  perform public._platform_log('employees.merchants_assigned', null, 'platform_staff', p_user::text, null, v_before, to_jsonb(p_merchants));
end;

platform_staff_list.src:
begin
  perform public._platform_require('employees', 'view');
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'user_id', s.user_id, 'email', s.email, 'full_name', s.full_name, 'title', s.title, 'phone', s.phone,
      'is_active', s.is_active, 'last_seen_at', s.last_seen_at, 'created_at', s.created_at,
      'role', jsonb_build_object('id', r.id, 'code', r.code, 'name', r.name, 'is_super', r.is_super),
      'merchant_scope', s.merchant_scope,
      'merchants', (select coalesce(jsonb_agg(jsonb_build_object('id', m.id, 'number', m.number, 'name', m.name) order by m.number), '[]'::jsonb)
                    from public.platform_staff_merchants sm join public.merchants m on m.id = sm.merchant_id where sm.user_id = s.user_id),
      'managed_merchants', (select count(*) from public.merchants m where m.account_manager_id = s.user_id))
      order by s.is_active desc, s.full_name, s.email)
    from public.platform_staff s join public.platform_roles r on r.id = s.role_id where s.removed_at is null), '[]'::jsonb);
end;

platform_staff_remove.src:
declare
  v_staff public.platform_staff;
  v_is_super boolean;
  v_login boolean;
begin
  perform public._platform_require('employees', 'manage');
  if p_user = auth.uid() then
    raise exception 'VALIDATION: you cannot remove yourself' using errcode = '22023';
  end if;
  if coalesce(length(trim(p_reason)), 0) < 5 then
    raise exception 'VALIDATION: explain why (at least 5 characters)' using errcode = '22023';
  end if;
  select * into v_staff from public.platform_staff where user_id = p_user for update;
  if v_staff.user_id is null or v_staff.removed_at is not null then
    raise exception 'NOT_FOUND: employee not found' using errcode = 'P0002';
  end if;
  if v_staff.is_active then
    raise exception 'VALIDATION: switch this employee off first, then remove them' using errcode = '22023';
  end if;
  select is_super into v_is_super from public.platform_roles where id = v_staff.role_id;
  if v_is_super and not public._platform_is_super() then
    raise exception 'PERMISSION_DENIED: only a Super Admin can remove another Super Admin' using errcode = '42501';
  end if;

  update public.platform_staff set removed_at = now() where user_id = p_user;
  update public.support_sessions set ended_at = now(), ended_by = auth.uid(), end_reason = 'Employee removed'
  where staff_user_id = p_user and ended_at is null;
  -- A login used only for the platform goes too; one that also runs a business stays.
  v_login := not exists (select 1 from public.profiles p where p.id = p_user and p.deleted_at is null);
  if v_login then
    insert into public.account_removals (user_id, from_merchant, reason) values (p_user, null, 'Employee removed');
  end if;
  perform public._platform_log('employees.removed', null, 'platform_staff', p_user::text, trim(p_reason),
    jsonb_build_object('email', v_staff.email, 'full_name', v_staff.full_name, 'is_super', v_is_super), jsonb_build_object('login_removed', v_login));
  return jsonb_build_object('removed', true, 'login_removed', v_login);
end;

platform_staff_save.src:
declare
  v_user uuid := (p ->> 'user_id')::uuid;
  v_role public.platform_roles;
  v_old public.platform_staff;
  v_auth record;
  v_supers int;
  v_approval uuid;
begin
  select * into v_old from public.platform_staff where user_id = v_user;
  perform public._platform_require('employees', case when v_old.user_id is null then 'create' else 'edit' end);
  select * into v_role from public.platform_roles where id = coalesce((p ->> 'role_id')::uuid, v_old.role_id);
  if v_role.id is null then
    raise exception 'VALIDATION: choose a role' using errcode = '22023';
  end if;
  -- Roles decide access: only Super Admins hand them out or change them.
  if (v_old.user_id is null or v_old.role_id is distinct from v_role.id) and not public._platform_is_super() then
    raise exception 'PERMISSION_DENIED: only a Super Admin can assign roles' using errcode = '42501';
  end if;
  if v_user = auth.uid() and v_old.role_id is distinct from v_role.id then
    raise exception 'VALIDATION: you cannot change your own role' using errcode = '22023';
  end if;
  select * into v_auth from public._auth_user(v_user);
  if v_auth.id is null then
    raise exception 'NOT_FOUND: no account with this id' using errcode = 'P0002';
  end if;

  if v_role.is_super and (v_old.user_id is null or v_old.role_id is distinct from v_role.id) then
    select count(*) into v_supers from public.platform_staff s join public.platform_roles r on r.id = s.role_id
    where r.is_super and s.is_active and s.user_id <> auth.uid();
    if v_supers > 0 then
      v_approval := public.platform_request_approval('employees', 'grant_super_admin', null,
        format('Make %s a Super Admin', coalesce(nullif(p ->> 'full_name', ''), v_auth.email)),
        jsonb_build_object('user_id', v_user, 'role_id', v_role.id, 'full_name', p ->> 'full_name', 'title', p ->> 'title'),
        coalesce(nullif(trim(p ->> 'reason'), ''), 'Grant Super Admin access'));
      return jsonb_build_object('pending_approval', v_approval);
    end if;
  end if;

  insert into public.platform_staff (user_id, email, full_name, title, phone, role_id, merchant_scope, created_by)
  values (v_user, v_auth.email, coalesce(nullif(trim(p ->> 'full_name'), ''), v_auth.full_name, ''), p ->> 'title', p ->> 'phone',
          v_role.id, coalesce(p ->> 'merchant_scope', 'ALL'), auth.uid())
  on conflict (user_id) do update set
    full_name = coalesce(nullif(trim(excluded.full_name), ''), public.platform_staff.full_name),
    title = coalesce(p ->> 'title', public.platform_staff.title),
    phone = coalesce(p ->> 'phone', public.platform_staff.phone),
    role_id = excluded.role_id,
    merchant_scope = coalesce(p ->> 'merchant_scope', public.platform_staff.merchant_scope),
    is_active = public.platform_staff.is_active or public.platform_staff.removed_at is not null,
    removed_at = null;
  if p ? 'merchant_ids' then
    perform public.platform_staff_assign(v_user, array(select (jsonb_array_elements_text(p -> 'merchant_ids'))::uuid));
  end if;
  perform public._platform_log('employees.save', null, 'platform_staff', v_user::text, p ->> 'reason',
    case when v_old.user_id is null then null else jsonb_build_object('role_id', v_old.role_id, 'merchant_scope', v_old.merchant_scope) end,
    jsonb_build_object('role', v_role.code, 'merchant_scope', coalesce(p ->> 'merchant_scope', v_old.merchant_scope, 'ALL')));
  return (select to_jsonb(s) from public.platform_staff s where s.user_id = v_user);
end;

platform_staff_set_active.src:
declare
  v_staff public.platform_staff;
  v_is_super boolean;
begin
  perform public._platform_require('employees', 'manage');
  if p_user = auth.uid() then
    raise exception 'VALIDATION: you cannot deactivate yourself' using errcode = '22023';
  end if;
  if coalesce(trim(p_reason), '') = '' then
    raise exception 'VALIDATION: give a reason' using errcode = '22023';
  end if;
  select * into v_staff from public.platform_staff where user_id = p_user for update;
  if v_staff.user_id is null then
    raise exception 'NOT_FOUND: employee not found' using errcode = 'P0002';
  end if;
  if v_staff.removed_at is not null then
    raise exception 'NOT_FOUND: employee not found' using errcode = 'P0002';
  end if;
  select is_super into v_is_super from public.platform_roles where id = v_staff.role_id;
  if v_is_super and not public._platform_is_super() then
    raise exception 'PERMISSION_DENIED: only a Super Admin can change another Super Admin' using errcode = '42501';
  end if;
  if v_is_super and not p_active and (select count(*) from public.platform_staff s join public.platform_roles r on r.id = s.role_id
                                       where r.is_super and s.is_active and s.user_id <> p_user) = 0 then
    raise exception 'VALIDATION: the platform needs at least one active Super Admin' using errcode = '22023';
  end if;
  update public.platform_staff set is_active = p_active where user_id = p_user;
  -- Open support sessions end with the account.
  if not p_active then
    update public.support_sessions set ended_at = now(), ended_by = auth.uid(), end_reason = 'Employee deactivated'
    where staff_user_id = p_user and ended_at is null;
  end if;
  perform public._platform_log(case when p_active then 'employees.reactivated' else 'employees.deactivated' end, null, 'platform_staff',
    p_user::text, p_reason, jsonb_build_object('is_active', v_staff.is_active), jsonb_build_object('is_active', p_active));
end;

platform_staff_sign_out.src:
declare
  v_staff public.platform_staff;
  v_n int;
begin
  perform public._platform_require('security', 'manage');
  if length(trim(coalesce(p_reason, ''))) < 5 then
    raise exception 'VALIDATION: say why (at least 5 characters)' using errcode = '22023';
  end if;
  select * into v_staff from public.platform_staff where user_id = p_user;
  if v_staff.user_id is null then
    raise exception 'NOT_FOUND: not a platform employee' using errcode = 'P0002';
  end if;
  if exists (select 1 from public.platform_roles r where r.id = v_staff.role_id and r.is_super) and not public._platform_is_super() then
    raise exception 'PERMISSION_DENIED: only a Super Admin can sign out a Super Admin' using errcode = '42501';
  end if;
  delete from auth.sessions where user_id = p_user;
  get diagnostics v_n = row_count;
  perform public._platform_log('security.staff_signed_out', null, 'platform_staff', p_user::text, trim(p_reason), null,
    jsonb_build_object('sessions', v_n, 'email', v_staff.email));
  return jsonb_build_object('sessions_ended', v_n);
end;

platform_store_domains_save.src:
declare
  v_root text := nullif(lower(trim(coalesce(p_value ->> 'root_domain', ''))), '');
  v_main text := coalesce(nullif(p_value ->> 'main_site', ''), 'marketing');
  v_before jsonb;
  v_after jsonb;
begin
  perform public._platform_require('settings', 'edit');
  if v_root is not null and v_root !~ '^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+$' then
    raise exception 'VALIDATION: enter a domain like fullfilio.com (no https:// or slashes)' using errcode = '22023';
  end if;
  if v_main not in ('marketing', 'store') then
    raise exception 'VALIDATION: the main address shows the website (marketing) or the default store (store)' using errcode = '22023';
  end if;
  select value into v_before from public.platform_settings where key = 'store_domains' for update;
  v_after := jsonb_build_object('root_domain', v_root, 'main_site', v_main);
  insert into public.platform_settings (key, value, description) values ('store_domains', v_after, 'Store addresses')
  on conflict (key) do update set value = excluded.value;
  perform public._platform_log('settings.store_domains', null, 'platform_setting', 'store_domains', p_reason, v_before, v_after);
  return v_after;
end;

platform_store_reset.src:
declare
  m public.merchants;
  r public.store_resets;
  v_export bigint;
  v jsonb := '{}'::jsonb;
  n int;
  inv record;
begin
  perform public._platform_require('merchants', 'manage', p_merchant);
  select * into m from public.merchants where id = p_merchant;
  if not found then
    raise exception 'NOT_FOUND: merchant not found' using errcode = 'P0002';
  end if;
  if coalesce(p_scope, '') not in ('ORDERS', 'EVERYTHING') then
    raise exception 'VALIDATION: choose what to reset: orders and customers, or everything' using errcode = '22023';
  end if;
  if coalesce(length(trim(p_reason)), 0) < 10 then
    raise exception 'VALIDATION: explain why (at least 10 characters)' using errcode = '22023';
  end if;
  if lower(trim(coalesce(p_confirm_name, ''))) <> lower(trim(m.name)) then
    raise exception 'VALIDATION: type the store name exactly as shown to confirm' using errcode = '22023';
  end if;
  select id into v_export from public.platform_data_exports
  where merchant_id = p_merchant and kind = 'MERCHANT_DATA' and created_at > now() - interval '24 hours'
  order by created_at desc limit 1;
  if v_export is null then
    raise exception 'VALIDATION: download a full export of this store first (Data Management → Export), then reset within 24 hours'
      using errcode = '22023';
  end if;
  if exists (select 1 from public.merchant_deletion_requests where merchant_id = p_merchant and status = 'APPROVED') then
    raise exception 'VALIDATION: this store has an approved data deletion request; finish or cancel it first' using errcode = '22023';
  end if;

  insert into public.store_resets (merchant_id, scope, reason, export_id, requested_by, requested_by_email, txid)
  values (p_merchant, p_scope, trim(p_reason), v_export, auth.uid(), (select email from public.platform_staff where user_id = auth.uid()), txid_current())
  returning * into r;
  perform set_config('app.store_reset', r.id::text, true);
  perform public._platform_in_merchant(p_merchant);
  set local lock_timeout = '20s';

  -- Links from records that stay (calls are billed) to records that go.
  update public.pbx_calls set order_id = null, customer_id = null where merchant_id = p_merchant and (order_id is not null or customer_id is not null);

  -- Store sync records about orders.
  delete from public.channel_status_pushes where merchant_id = p_merchant;
  delete from public.channel_order_sync where merchant_id = p_merchant;
  delete from public.channel_fulfillments where merchant_id = p_merchant;
  delete from public.channel_order_imports where merchant_id = p_merchant;
  get diagnostics n = row_count; v := v || jsonb_build_object('store_imports', n);
  delete from public.channel_sync_jobs where merchant_id = p_merchant;
  delete from public.channel_webhook_deliveries where merchant_id = p_merchant;
  delete from public.channel_plugin_events where merchant_id = p_merchant;

  -- Parcels and courier records.
  delete from public.parcel_scans where merchant_id = p_merchant;
  delete from public.parcel_calls where merchant_id = p_merchant;
  delete from public.courier_webhook_events where merchant_id = p_merchant;
  delete from public.shipment_charges where merchant_id = p_merchant;
  delete from public.courier_invoice_lines where merchant_id = p_merchant;
  delete from public.courier_invoices where merchant_id = p_merchant;
  get diagnostics n = row_count; v := v || jsonb_build_object('courier_invoices', n);

  -- Income & expense records tied to orders or customers (and their corrections).
  with recursive s as (
    select id from public.finance_transactions where merchant_id = p_merchant and (order_id is not null or customer_id is not null)
    union
    select f.id from public.finance_transactions f join s on f.reverses_id = s.id
  )
  delete from public.finance_account_movements where merchant_id = p_merchant and finance_transaction_id in (select id from s);
  with recursive s as (
    select id from public.finance_transactions where merchant_id = p_merchant and (order_id is not null or customer_id is not null)
    union
    select f.id from public.finance_transactions f join s on f.reverses_id = s.id
  )
  delete from public.finance_transactions where id in (select id from s);
  get diagnostics n = row_count; v := v || jsonb_build_object('order_finance_records', n);

  -- Fraud, payments, leads, messages. Orders and fraud checks point at each other.
  update public.orders set fraud_check_id = null where merchant_id = p_merchant and fraud_check_id is not null;
  delete from public.fraud_reviews where merchant_id = p_merchant;
  delete from public.fraud_checks where merchant_id = p_merchant;
  delete from public.order_merges where merchant_id = p_merchant;
  delete from public.order_payments where merchant_id = p_merchant;
  delete from public.payment_events where merchant_id = p_merchant;
  delete from public.payments where merchant_id = p_merchant;
  delete from public.coupon_usage where merchant_id = p_merchant;
  delete from public.order_blocks where merchant_id = p_merchant;
  delete from public.store_carts where merchant_id = p_merchant;
  delete from public.checkout_leads where merchant_id = p_merchant;
  get diagnostics n = row_count; v := v || jsonb_build_object('incomplete_orders', n);
  delete from public.shopify_abandoned_checkouts where merchant_id = p_merchant;
  delete from public.notification_logs where merchant_id = p_merchant;
  delete from public.contact_messages where merchant_id = p_merchant;
  delete from public.storefront_events where merchant_id = p_merchant;

  -- Orders (with their items, history, notes, reservations, shipments, production) and customers.
  delete from public.orders where merchant_id = p_merchant;
  get diagnostics n = row_count; v := v || jsonb_build_object('orders', n);
  delete from public.customers where merchant_id = p_merchant;
  get diagnostics n = row_count; v := v || jsonb_build_object('customers', n);
  update public.sales_channels set orders_imported = 0, last_order_at = null where merchant_id = p_merchant;

  if p_scope = 'ORDERS' then
    -- Products stay; what was held for orders is free again.
    for inv in select variant_id, reserved from public.inventory where merchant_id = p_merchant and reserved <> 0 loop
      perform public._apply_inventory_movement(inv.variant_id, 'RELEASE', 0, -inv.reserved, 0, 'ADJUSTMENT', r.id,
        'Store reset', 'Reservations cleared: the store''s orders were reset', null, true);
    end loop;
  else
    delete from public.marketing_spend where merchant_id = p_merchant;
    delete from public.meta_ad_insights where merchant_id = p_merchant;
    delete from public.meta_ads where merchant_id = p_merchant;
    delete from public.meta_adsets where merchant_id = p_merchant;
    delete from public.meta_campaigns where merchant_id = p_merchant;
    delete from public.ad_platform_stats where merchant_id = p_merchant;
    delete from public.marketing_campaigns where merchant_id = p_merchant;
    delete from public.finance_account_movements where merchant_id = p_merchant;
    delete from public.finance_transactions where merchant_id = p_merchant;
    get diagnostics n = row_count; v := v || jsonb_build_object('finance_records', n);
    delete from public.purchase_orders where merchant_id = p_merchant;
    get diagnostics n = row_count; v := v || jsonb_build_object('purchase_orders', n);
    delete from public.suppliers where merchant_id = p_merchant;
    delete from public.sales_channel_variants where merchant_id = p_merchant;
    delete from public.channel_catalog_items where merchant_id = p_merchant;
    -- Store connections go too, with their saved keys.
    delete from public.channel_oauth_states where merchant_id = p_merchant;
    delete from vault.secrets where id in (
      select secret_id from public.integration_credentials
      where merchant_id = p_merchant and key like 'channels.%' and secret_id is not null);
    delete from public.integration_credentials where merchant_id = p_merchant and key like 'channels.%';
    delete from public.sales_channels where merchant_id = p_merchant;
    get diagnostics n = row_count; v := v || jsonb_build_object('store_connections', n);
    -- Every other connection, with its saved keys and history.
    delete from public.api_request_logs where merchant_id = p_merchant;
    delete from public.api_keys where merchant_id = p_merchant;
    delete from public.site_api_keys where merchant_id = p_merchant;
    delete from public.ad_oauth_states where merchant_id = p_merchant;
    delete from public.ad_accounts where merchant_id = p_merchant;
    delete from public.ad_connections where merchant_id = p_merchant;
    delete from public.meta_ad_accounts where merchant_id = p_merchant;
    delete from vault.secrets where id in (
      select secret_id from public.courier_credentials where merchant_id = p_merchant and secret_id is not null
      union all
      select secret_id from public.integration_credentials where merchant_id = p_merchant and secret_id is not null);
    delete from public.courier_credentials where merchant_id = p_merchant;
    delete from public.integration_credentials where merchant_id = p_merchant;
    delete from public.couriers where merchant_id = p_merchant;
    get diagnostics n = row_count; v := v || jsonb_build_object('couriers', n);
    delete from public.store_domains where merchant_id = p_merchant;
    get diagnostics n = row_count; v := v || jsonb_build_object('domains', n);
    delete from public.system_logs where merchant_id = p_merchant;
    -- Connection settings back to a new business's defaults ("Own delivery" courier included).
    delete from public.settings where merchant_id = p_merchant
      and key in ('ad_platforms', 'meta_ads', 'sms', 'pbx', 'payments', 'couriers', 'fraud', 'notifications');
    perform public._merchant_seed_defaults(p_merchant);
    -- A store that sent visitors to a removed Shopify/WooCommerce shop is closed instead.
    update public.settings set value = (value - 'redirect_url') || '{"mode": "OFF"}'::jsonb
    where merchant_id = p_merchant and key = 'storefront' and upper(coalesce(value ->> 'mode', '')) in ('SHOPIFY', 'WOOCOMMERCE');
    v := v || jsonb_build_object('every_connection', true);
    delete from public.inventory_movements where merchant_id = p_merchant;
    delete from public.stock_reservations where merchant_id = p_merchant;
    delete from public.products where merchant_id = p_merchant;
    get diagnostics n = row_count; v := v || jsonb_build_object('products', n);
    delete from public.categories where merchant_id = p_merchant;
    delete from public.coupons where merchant_id = p_merchant;
  end if;

  update public.store_resets set status = 'DONE', counts = v, finished_at = now() where id = r.id;
  perform set_config('app.store_reset', '', true);
  perform public.log_audit('store.reset', 'merchant', p_merchant::text, null,
    jsonb_build_object('scope', p_scope, 'counts', v), jsonb_build_object('reason', trim(p_reason), 'reset_id', r.id));
  perform public._platform_log('merchants.reset', p_merchant, 'merchant', p_merchant::text, trim(p_reason), null,
    jsonb_build_object('scope', p_scope, 'counts', v, 'export_id', v_export, 'reset_id', r.id));
  return jsonb_build_object('reset_id', r.id, 'scope', p_scope, 'counts', v);
end;

platform_store_resets.src:
begin
  perform public._platform_require('merchants', 'view', p_merchant);
  return jsonb_build_object(
    'resets', coalesce((select jsonb_agg(jsonb_build_object('id', r.id, 'scope', r.scope, 'reason', r.reason, 'status', r.status,
        'requested_by_email', r.requested_by_email, 'counts', r.counts, 'created_at', r.created_at, 'finished_at', r.finished_at)
      order by r.created_at desc) from public.store_resets r where r.merchant_id = p_merchant), '[]'::jsonb),
    'last_export_at', (select max(created_at) from public.platform_data_exports
                       where merchant_id = p_merchant and kind = 'MERCHANT_DATA'),
    'export_valid_until', (select max(created_at) + interval '24 hours' from public.platform_data_exports
                           where merchant_id = p_merchant and kind = 'MERCHANT_DATA' and created_at > now() - interval '24 hours'));
end;

platform_subscription_action.src:
declare
  s public.subscriptions;
  v_before jsonb;
  v_plan public.plans;
  v_reason text := nullif(trim(p ->> 'reason'), '');
  v_days int;
begin
  perform public._platform_require('subscriptions', 'manage', p_merchant);
  if v_reason is null or length(v_reason) < 3 then
    raise exception 'VALIDATION: give a reason' using errcode = '22023';
  end if;
  select * into s from public.subscriptions where merchant_id = p_merchant and ended_at is null for update;
  v_before := to_jsonb(s);
  case p_action
    when 'change_plan' then
      select * into v_plan from public.plans where id = (p ->> 'plan_id')::uuid and status = 'ACTIVE';
      if v_plan.id is null then
        raise exception 'VALIDATION: choose an active plan' using errcode = '22023';
      end if;
      if s.id is null then
        insert into public.subscriptions (merchant_id, plan_id, status, price, currency, billing_interval, trial_ends_at, current_period_start, current_period_end, created_by)
        values (p_merchant, v_plan.id,
                case when coalesce((p ->> 'trial')::boolean, v_plan.trial_days > 0) and v_plan.trial_days > 0 then 'TRIALING' else 'ACTIVE' end,
                coalesce((p ->> 'price')::numeric, v_plan.price), v_plan.currency, v_plan.billing_interval,
                case when coalesce((p ->> 'trial')::boolean, v_plan.trial_days > 0) and v_plan.trial_days > 0 then now() + make_interval(days => v_plan.trial_days) end,
                now(), case when not (coalesce((p ->> 'trial')::boolean, v_plan.trial_days > 0) and v_plan.trial_days > 0) then now() end, auth.uid())
        returning * into s;
        -- A paid plan without a trial starts with its first invoice; the period begins when it is paid.
        if s.status = 'ACTIVE' and s.price > 0 then
          update public.subscriptions set status = 'PAST_DUE', current_period_end = null,
            grace_until = now() + make_interval(days => coalesce((select (value ->> 'grace_days')::int from public.platform_settings where key = 'billing'), 7))
          where id = s.id returning * into s;
          perform public._billing_invoice_for(s, now(), now() + public._billing_interval(s.billing_interval));
        elsif s.status = 'ACTIVE' then
          update public.subscriptions set current_period_end = now() + public._billing_interval(billing_interval) where id = s.id returning * into s;
        end if;
        perform public._subscription_event(s, 'subscription.started', jsonb_build_object('plan', v_plan.code, 'reason', v_reason));
      else
        -- The new plan and price apply from the next invoice; nothing already invoiced changes.
        update public.subscriptions set plan_id = v_plan.id, price = coalesce((p ->> 'price')::numeric, v_plan.price), billing_interval = v_plan.billing_interval
        where id = s.id returning * into s;
        perform public._subscription_event(s, 'subscription.plan_changed', jsonb_build_object('plan', v_plan.code, 'reason', v_reason));
      end if;
    when 'extend_trial' then
      v_days := (p ->> 'days')::int;
      if s.id is null or s.status not in ('TRIALING', 'PAST_DUE') or v_days is null or v_days not between 1 and 90 then
        raise exception 'VALIDATION: only a trial (or a trial that just ended unpaid) can be extended, by 1 to 90 days' using errcode = '22023';
      end if;
      update public.subscriptions set status = 'TRIALING', grace_until = null,
        trial_ends_at = greatest(coalesce(trial_ends_at, now()), now()) + make_interval(days => v_days)
      where id = s.id returning * into s;
      perform public._subscription_event(s, 'trial.extended', jsonb_build_object('days', v_days, 'reason', v_reason));
    when 'pause' then
      if s.id is null or s.status not in ('ACTIVE', 'TRIALING', 'PAST_DUE') then
        raise exception 'VALIDATION: nothing to pause' using errcode = '22023';
      end if;
      update public.subscriptions set status = 'PAUSED', paused_at = now() where id = s.id returning * into s;
      perform public._subscription_event(s, 'subscription.paused', jsonb_build_object('reason', v_reason));
    when 'resume' then
      if s.id is null or s.status <> 'PAUSED' then
        raise exception 'VALIDATION: the subscription is not paused' using errcode = '22023';
      end if;
      -- The paused time is added to the current period.
      update public.subscriptions set status = case when trial_ends_at > now() then 'TRIALING' else 'ACTIVE' end,
        current_period_end = current_period_end + (now() - paused_at), paused_at = null
      where id = s.id returning * into s;
      perform public._subscription_event(s, 'subscription.resumed', jsonb_build_object('reason', v_reason));
    when 'cancel' then
      if s.id is null then
        raise exception 'VALIDATION: no subscription' using errcode = '22023';
      end if;
      if coalesce((p ->> 'immediately')::boolean, false) then
        update public.subscriptions set status = 'CANCELLED', cancelled_at = now(), ended_at = now() where id = s.id returning * into s;
      else
        update public.subscriptions set cancel_at_period_end = true where id = s.id returning * into s;
      end if;
      perform public._subscription_event(s, 'subscription.cancel', jsonb_build_object('immediately', coalesce((p ->> 'immediately')::boolean, false), 'reason', v_reason));
    when 'undo_cancel' then
      update public.subscriptions set cancel_at_period_end = false where id = s.id and cancel_at_period_end returning * into s;
      perform public._subscription_event(s, 'subscription.cancel_undone', jsonb_build_object('reason', v_reason));
    when 'add_addon' then
      if s.id is null then
        raise exception 'VALIDATION: start a subscription first' using errcode = '22023';
      end if;
      insert into public.subscription_addons (merchant_id, subscription_id, addon_id, quantity, price)
      select p_merchant, s.id, a.id, coalesce((p ->> 'quantity')::int, 1), a.price from public.plan_addons a where a.id = (p ->> 'addon_id')::uuid and a.status = 'ACTIVE';
      perform public._subscription_event(s, 'addon.added', jsonb_build_object('addon_id', p ->> 'addon_id', 'reason', v_reason));
    when 'remove_addon' then
      update public.subscription_addons set ended_at = now() where id = (p ->> 'subscription_addon_id')::uuid and merchant_id = p_merchant and ended_at is null;
      perform public._subscription_event(s, 'addon.removed', jsonb_build_object('id', p ->> 'subscription_addon_id', 'reason', v_reason));
    else
      raise exception 'VALIDATION: unknown action %', p_action using errcode = '22023';
  end case;
  perform public._platform_log('subscription.' || p_action, p_merchant, 'subscription', s.id::text, v_reason, v_before, to_jsonb(s));
  return public.platform_merchant_billing(p_merchant);
end;

platform_support_session_end.src:
declare
  s public.support_sessions;
begin
  if not public.is_platform_staff() then
    raise exception 'PERMISSION_DENIED: platform staff only' using errcode = '42501';
  end if;
  if p_id is null then
    select * into s from public.support_sessions where staff_user_id = auth.uid() and ended_at is null order by started_at desc limit 1;
    if s.id is null then
      return null;
    end if;
  else
    select * into s from public.support_sessions where id = p_id;
    if s.id is null or not public.platform_can('support', 'view', s.merchant_id) then
      raise exception 'NOT_FOUND: session not found' using errcode = 'P0002';
    end if;
    if s.staff_user_id <> auth.uid() then
      perform public._platform_require('support', 'manage', s.merchant_id);
      if length(trim(coalesce(p_reason, ''))) < 5 then
        raise exception 'VALIDATION: say why you are ending someone else''s session' using errcode = '22023';
      end if;
    end if;
  end if;
  if s.ended_at is not null then
    return public._platform_session_json(s);
  end if;
  update public.support_sessions set ended_at = least(now(), expires_at), ended_by = auth.uid(),
    end_reason = case when expires_at <= now() then 'Expired' else coalesce(nullif(trim(coalesce(p_reason, '')), ''), 'Ended') end
  where id = s.id returning * into s;
  perform public._platform_log(case when s.end_reason = 'Expired' then 'support.session_expired' else 'support.session_ended' end,
    s.merchant_id, 'support_session', s.id::text, s.end_reason, null,
    jsonb_build_object('minutes', round(extract(epoch from s.ended_at - s.started_at) / 60), 'by_owner', s.staff_user_id = auth.uid()));
  return public._platform_session_json(s);
end;

platform_support_session_start.src:
declare
  v_settings jsonb := public._platform_support_settings();
  v_minutes int := coalesce(p_minutes, (v_settings ->> 'session_default_minutes')::int, 30);
  v_max int := least(coalesce((v_settings ->> 'session_max_minutes')::int, 120), 240);
  m public.merchants;
  s public.support_sessions;
begin
  select * into m from public.merchants where id = p_merchant;
  if m.id is null or not public.platform_can('support', 'view', m.id) then
    raise exception 'NOT_FOUND: merchant not found' using errcode = 'P0002';
  end if;
  perform public._platform_require('support', 'edit', m.id);
  if m.status = 'CLOSED' then
    raise exception 'VALIDATION: this merchant is closed' using errcode = '22023';
  end if;
  if length(trim(coalesce(p_reason, ''))) < 10 then
    raise exception 'VALIDATION: say why you need to see the merchant''s screens (it is logged and shown to the merchant)' using errcode = '22023';
  end if;
  if v_minutes < 5 or v_minutes > v_max then
    raise exception 'VALIDATION: a session lasts 5 to % minutes', v_max using errcode = '22023';
  end if;
  if p_ticket is not null and not exists (select 1 from public.support_tickets where id = p_ticket and merchant_id = m.id) then
    raise exception 'VALIDATION: that ticket belongs to another merchant' using errcode = '22023';
  end if;
  perform public._platform_support_expire();
  -- One open session per person.
  for s in
    update public.support_sessions set ended_at = now(), ended_by = auth.uid(), end_reason = 'Replaced by a new session'
    where staff_user_id = auth.uid() and ended_at is null returning *
  loop
    perform public._platform_log('support.session_ended', s.merchant_id, 'support_session', s.id::text, 'Replaced by a new session', null,
      jsonb_build_object('minutes', round(extract(epoch from now() - s.started_at) / 60)));
  end loop;
  insert into public.support_sessions (staff_user_id, merchant_id, mode, reason, ticket_id, expires_at)
  values (auth.uid(), m.id, 'VIEW', left(trim(p_reason), 500), p_ticket, now() + make_interval(mins => v_minutes))
  returning * into s;
  if p_ticket is not null then
    perform public._platform_ticket_event(p_ticket, m.id, 'SESSION', trim(p_reason), jsonb_build_object('session_id', s.id, 'minutes', v_minutes));
  end if;
  perform public._platform_log('support.session_started', m.id, 'support_session', s.id::text, trim(p_reason), null,
    jsonb_build_object('mode', 'VIEW', 'minutes', v_minutes, 'expires_at', s.expires_at, 'ticket_id', p_ticket));
  return public._platform_session_json(s);
end;

platform_support_sessions.src:
declare
  v_merchant uuid := nullif(p ->> 'merchant', '')::uuid;
  v_active boolean := coalesce((p ->> 'active')::boolean, false);
begin
  perform public._platform_require('support', 'view', v_merchant);
  perform public._platform_support_expire();
  return jsonb_build_object(
    'mine', (select public._platform_session_json(s) from public.support_sessions s
             where s.staff_user_id = auth.uid() and s.ended_at is null and s.expires_at > now() order by s.started_at desc limit 1),
    'rows', (select coalesce(jsonb_agg(public._platform_session_json(s) order by s.started_at desc), '[]'::jsonb)
             from (select * from public.support_sessions s
                   where s.merchant_id in (select public._platform_merchant_ids())
                     and (v_merchant is null or s.merchant_id = v_merchant)
                     and (not v_active or (s.ended_at is null and s.expires_at > now()))
                   order by s.started_at desc limit least(greatest(coalesce(p_limit, 100), 1), 500)) s),
    'settings', jsonb_build_object('default_minutes', (public._platform_support_settings() ->> 'session_default_minutes')::int,
                                   'max_minutes', (public._platform_support_settings() ->> 'session_max_minutes')::int),
    'can', jsonb_build_object('start', public.platform_can('support', 'edit', v_merchant), 'manage', public.platform_can('support', 'manage', v_merchant)));
end;

platform_support_settings_save.src:
declare
  v_before jsonb := public._platform_support_settings();
  v_after jsonb;
  k text;
begin
  perform public._platform_require('support', 'manage');
  v_after := v_before || coalesce(p, '{}'::jsonb);
  foreach k in array array['URGENT', 'HIGH', 'NORMAL', 'LOW'] loop
    if coalesce(nullif(v_after #>> array['sla_hours', k], '')::numeric, 0) not between 0.25 and 720
       or coalesce(nullif(v_after #>> array['response_hours', k], '')::numeric, 0) not between 0.25 and 720 then
      raise exception 'VALIDATION: each target is between 15 minutes and 30 days' using errcode = '22023';
    end if;
    if (v_after #>> array['response_hours', k])::numeric > (v_after #>> array['sla_hours', k])::numeric then
      raise exception 'VALIDATION: the first reply cannot be due after the resolution' using errcode = '22023';
    end if;
  end loop;
  if coalesce((v_after ->> 'session_max_minutes')::int, 0) not between 5 and 240
     or coalesce((v_after ->> 'session_default_minutes')::int, 0) not between 5 and (v_after ->> 'session_max_minutes')::int then
    raise exception 'VALIDATION: customer-view sessions last 5 minutes to 4 hours, and the default cannot exceed the maximum' using errcode = '22023';
  end if;
  if length(trim(coalesce(v_after ->> 'team_name', ''))) not between 2 and 40 then
    raise exception 'VALIDATION: the team name is 2–40 characters' using errcode = '22023';
  end if;
  v_after := jsonb_build_object('sla_hours', v_after -> 'sla_hours', 'response_hours', v_after -> 'response_hours',
    'session_default_minutes', (v_after ->> 'session_default_minutes')::int, 'session_max_minutes', (v_after ->> 'session_max_minutes')::int,
    'team_name', trim(v_after ->> 'team_name'));
  insert into public.platform_settings (key, value, updated_by) values ('support', v_after, auth.uid())
  on conflict (key) do update set value = excluded.value, updated_by = excluded.updated_by;
  perform public._config_version('platform_setting', 'support', v_after, p_reason);
  perform public._platform_log('support.settings_changed', null, 'platform_setting', 'support', p_reason, v_before, v_after);
  return v_after;
end;

platform_system_logs.src:
declare
  v_level text := nullif(upper(coalesce(p ->> 'level', '')), '');
  v_category text := nullif(upper(coalesce(p ->> 'category', '')), '');
  v_merchant uuid := nullif(p ->> 'merchant', '')::uuid;
  v_q text := nullif(trim(coalesce(p ->> 'q', '')), '');
  v_open boolean := coalesce((p ->> 'unresolved')::boolean, true);
  v_id bigint := nullif(p ->> 'id', '')::bigint;
begin
  perform public._platform_require('health', 'view');
  return (with f as (
      select l.* from public.system_logs l
      where (l.merchant_id is null or l.merchant_id in (select public._platform_merchant_ids()))
        and (v_id is null or l.id = v_id)
        and (v_level is null or l.level = v_level) and (v_category is null or l.category = v_category)
        and (v_merchant is null or l.merchant_id = v_merchant)
        and (not v_open or v_id is not null or l.resolved_at is null)
        and (v_q is null or l.message ilike '%' || v_q || '%' or l.source ilike '%' || v_q || '%'))
    select jsonb_build_object(
      'total', (select count(*) from f),
      'rows', (select coalesce(jsonb_agg(jsonb_build_object('id', x.id, 'level', x.level, 'category', x.category, 'source', x.source, 'message', x.message,
          'context', x.context, 'occurrences', x.occurrences, 'first_seen_at', x.created_at, 'last_seen_at', x.last_seen_at, 'resolved_at', x.resolved_at,
          'merchant', (select jsonb_build_object('id', m.id, 'number', m.number, 'name', m.name) from public.merchants m where m.id = x.merchant_id))
          order by x.last_seen_at desc), '[]'::jsonb)
        from (select * from f order by last_seen_at desc limit least(greatest(coalesce(p_limit, 50), 1), 200) offset greatest(coalesce(p_offset, 0), 0)) x),
      'by_category', (select coalesce(jsonb_object_agg(category, n), '{}'::jsonb) from (select category, count(*) n from f group by category) c)));
end;

platform_system_logs_resolve.src:
declare
  v_n int;
begin
  perform public._platform_require('health', 'manage');
  update public.system_logs set resolved_at = now(), resolved_by = auth.uid()
  where id = any (p_ids) and resolved_at is null and (merchant_id is null or merchant_id in (select public._platform_merchant_ids()));
  get diagnostics v_n = row_count;
  perform public._platform_log('health.logs_resolved', null, 'system_log', array_to_string(p_ids[1:20], ','), p_note, null, jsonb_build_object('resolved', v_n));
  return v_n;
end;

platform_ticket_create.src:
declare
  v_merchant uuid := nullif(p ->> 'merchant', '')::uuid;
  v_priority text := upper(coalesce(nullif(p ->> 'priority', ''), 'NORMAL'));
  v_assign uuid := nullif(p ->> 'assign_to', '')::uuid;
  t public.support_tickets;
begin
  if v_merchant is null or not exists (select 1 from public.merchants where id = v_merchant) then
    raise exception 'VALIDATION: choose the merchant' using errcode = '22023';
  end if;
  perform public._platform_require('support', 'create', v_merchant);
  if v_priority not in ('LOW', 'NORMAL', 'HIGH', 'URGENT') then
    raise exception 'VALIDATION: unknown priority' using errcode = '22023';
  end if;
  if length(trim(coalesce(p ->> 'subject', ''))) < 3 then
    raise exception 'VALIDATION: add a short title' using errcode = '22023';
  end if;
  if length(trim(coalesce(p ->> 'body', ''))) < 5 then
    raise exception 'VALIDATION: describe the issue in a few words' using errcode = '22023';
  end if;
  if v_assign is not null then
    if v_assign <> auth.uid() then
      perform public._platform_require('support', 'manage', v_merchant);
    end if;
    perform public._platform_ticket_assignee_ok(v_assign, v_merchant);
  end if;
  insert into public.support_tickets (merchant_id, kind, category, subject, body, priority, context, created_by, opened_by_platform, internal,
                                      assigned_to, assigned_at)
  values (v_merchant, 'BUG', upper(coalesce(nullif(p ->> 'category', ''), 'GENERAL')), left(trim(p ->> 'subject'), 140), left(trim(p ->> 'body'), 4000),
          v_priority, jsonb_build_object('source', 'platform'), null, auth.uid(), coalesce((p ->> 'internal')::boolean, false),
          v_assign, case when v_assign is not null then now() end)
  returning * into t;
  if v_assign is not null then
    perform public._platform_ticket_event(t.id, t.merchant_id, 'ASSIGNED', null, jsonb_build_object('to', v_assign,
      'to_email', (select email from public.platform_staff where user_id = v_assign)));
    if v_assign <> auth.uid() then
      perform public._platform_notify('support', 'view', t.merchant_id, 'support.ticket_assigned', 'INFO', format('Ticket #%s is yours: %s', t.number, t.subject),
        null, '/super-admin/support?ticket=' || t.id, null, array[v_assign]);
    end if;
  end if;
  perform public._platform_log('support.ticket_created', t.merchant_id, 'support_ticket', t.id::text, null, null,
    jsonb_build_object('number', t.number, 'subject', t.subject, 'priority', t.priority, 'internal', t.internal));
  return public._platform_ticket_json(t);
end;

platform_ticket_escalate.src:
declare
  t public.support_tickets := public._platform_ticket_get_row(p_id, 'edit');
begin
  if length(trim(coalesce(p_reason, ''))) < 5 then
    raise exception 'VALIDATION: say why it is being escalated' using errcode = '22023';
  end if;
  if t.status not in ('OPEN', 'IN_PROGRESS') then
    raise exception 'VALIDATION: only open tickets can be escalated' using errcode = '22023';
  end if;
  if t.escalation_level >= 5 then
    raise exception 'VALIDATION: this ticket is already at the highest escalation level' using errcode = '22023';
  end if;
  t := public._platform_ticket_escalate(t, trim(p_reason), false);
  perform public._platform_log('support.ticket_escalated', t.merchant_id, 'support_ticket', t.id::text, trim(p_reason), null,
    jsonb_build_object('level', t.escalation_level, 'priority', t.priority));
  return public._platform_ticket_json(t);
end;

platform_ticket_note.src:
declare
  t public.support_tickets := public._platform_ticket_get_row(p_id, 'edit');
begin
  if length(trim(coalesce(p_body, ''))) < 2 then
    raise exception 'VALIDATION: write the note' using errcode = '22023';
  end if;
  perform public._platform_ticket_event(t.id, t.merchant_id, 'NOTE', trim(p_body));
  return public._platform_ticket_json(t);
end;

platform_ticket_reply.src:
declare
  t public.support_tickets := public._platform_ticket_get_row(p_id, 'edit');
  v_name text;
begin
  if t.internal then
    raise exception 'VALIDATION: this is an internal ticket; add a note instead' using errcode = '22023';
  end if;
  if length(trim(coalesce(p_body, ''))) < 1 then
    raise exception 'VALIDATION: write a reply' using errcode = '22023';
  end if;
  select split_part(coalesce(nullif(trim(full_name), ''), split_part(email, '@', 1)), ' ', 1) into v_name
  from public.platform_staff where user_id = auth.uid();
  insert into public.support_ticket_messages (ticket_id, merchant_id, author_id, platform_author, author_label, body, is_support)
  values (t.id, t.merchant_id, null, auth.uid(), left(v_name || ' · ' || coalesce(public._platform_support_settings() ->> 'team_name', 'Support'), 80),
          left(trim(p_body), 4000), true);
  update public.support_tickets set replies = replies + 1, last_reply_at = now(), last_reply_by = null,
    first_response_at = coalesce(first_response_at, now()),
    status = case when status = 'OPEN' then 'IN_PROGRESS' else status end
  where id = t.id
  returning * into t;
  perform public._platform_ticket_event(t.id, t.merchant_id, 'REPLY', left(trim(p_body), 300));
  return public._platform_ticket_json(t);
end;

platform_ticket_update.src:
declare
  t public.support_tickets := public._platform_ticket_get_row(p_id, 'edit');
  v_row public.support_tickets;
  v_status text := nullif(upper(coalesce(p ->> 'status', '')), '');
  v_priority text := nullif(upper(coalesce(p ->> 'priority', '')), '');
  v_due timestamptz := nullif(p ->> 'due_at', '')::timestamptz;
  v_assign uuid := nullif(p ->> 'assigned_to', '')::uuid;
  v_assign_given boolean := p ? 'assigned_to';
begin
  if v_status is not null and v_status not in ('OPEN', 'IN_PROGRESS', 'RESOLVED', 'CLOSED') then
    raise exception 'VALIDATION: unknown status' using errcode = '22023';
  end if;
  if v_priority is not null and v_priority not in ('LOW', 'NORMAL', 'HIGH', 'URGENT') then
    raise exception 'VALIDATION: unknown priority' using errcode = '22023';
  end if;
  if v_due is not null and v_due < now() - interval '1 minute' then
    raise exception 'VALIDATION: the due time is in the past' using errcode = '22023';
  end if;
  if v_assign_given and v_assign is distinct from t.assigned_to then
    if (v_assign is not null and v_assign <> auth.uid()) or (t.assigned_to is not null and t.assigned_to <> auth.uid()) then
      perform public._platform_require('support', 'manage', t.merchant_id);
    end if;
    if v_assign is not null then
      perform public._platform_ticket_assignee_ok(v_assign, t.merchant_id);
    end if;
  end if;

  update public.support_tickets set
    status = coalesce(v_status, status),
    priority = coalesce(v_priority, priority),
    due_at = coalesce(v_due, due_at),
    assigned_to = case when v_assign_given then v_assign else assigned_to end,
    assigned_at = case when v_assign_given and v_assign is distinct from t.assigned_to then case when v_assign is null then null else now() end
                       else assigned_at end,
    resolved_at = case when coalesce(v_status, status) in ('RESOLVED', 'CLOSED') then coalesce(resolved_at, now()) else null end
  where id = t.id returning * into v_row;

  if v_row.status is distinct from t.status then
    perform public._platform_ticket_event(t.id, t.merchant_id, 'STATUS', nullif(trim(coalesce(p ->> 'reason', '')), ''),
      jsonb_build_object('from', t.status, 'to', v_row.status));
  end if;
  if v_row.priority is distinct from t.priority then
    perform public._platform_ticket_event(t.id, t.merchant_id, 'PRIORITY', null, jsonb_build_object('from', t.priority, 'to', v_row.priority));
  end if;
  if v_row.due_at is distinct from t.due_at then
    perform public._platform_ticket_event(t.id, t.merchant_id, 'DUE', null, jsonb_build_object('from', t.due_at, 'to', v_row.due_at));
  end if;
  if v_row.assigned_to is distinct from t.assigned_to then
    perform public._platform_ticket_event(t.id, t.merchant_id, 'ASSIGNED', null, jsonb_build_object('from', t.assigned_to, 'to', v_row.assigned_to,
      'to_email', (select email from public.platform_staff where user_id = v_row.assigned_to)));
    if v_row.assigned_to is not null and v_row.assigned_to <> auth.uid() then
      perform public._platform_notify('support', 'view', t.merchant_id, 'support.ticket_assigned', 'INFO',
        format('Ticket #%s is yours: %s', t.number, t.subject), null, '/super-admin/support?ticket=' || t.id, null, array[v_row.assigned_to]);
    end if;
  end if;
  perform public._platform_log('support.ticket_updated', t.merchant_id, 'support_ticket', t.id::text, nullif(trim(coalesce(p ->> 'reason', '')), ''),
    jsonb_build_object('status', t.status, 'priority', t.priority, 'due_at', t.due_at, 'assigned_to', t.assigned_to),
    jsonb_build_object('status', v_row.status, 'priority', v_row.priority, 'due_at', v_row.due_at, 'assigned_to', v_row.assigned_to));
  return public._platform_ticket_json(v_row);
end;

platform_usage_policy_save.src:
declare
  v jsonb;
  v_before jsonb := public._usage_policy(p_service);
begin
  perform public._platform_require(coalesce(public._usage_module(p_service), 'sms'), 'edit');
  v := public._usage_policy_validate(p_service, p_policy);
  if coalesce(length(trim(p_reason)), 0) < 5 then
    raise exception 'VALIDATION: give a reason (at least 5 characters)' using errcode = '22023';
  end if;
  update public.platform_settings set value = v, updated_by = auth.uid() where key = 'usage.' || lower(p_service);
  perform public._config_version('platform_setting', 'usage.' || lower(p_service), v, p_reason);
  perform public._platform_log(public._usage_module(p_service) || '.policy_changed', null, 'platform_setting', 'usage.' || lower(p_service), p_reason, v_before, v);
  return v;
end;

prevent_mutation.src:
begin
  if tg_op = 'UPDATE' and tg_table_name = 'shipment_events' then
    if public._erasure_active(new.merchant_id) then
      return new;
    end if;
  end if;
  if tg_op = 'DELETE' and tg_table_name = any (public._store_reset_tables())
     and public._store_reset_active(to_jsonb(old) ->> 'merchant_id') then
    return old;
  end if;
  raise exception 'IMMUTABLE_RECORD: % rows cannot be %d; record a correcting entry instead',
    tg_table_name, lower(tg_op)
    using errcode = 'P0001';
end;

process_order_return.src:
declare
  v_order public.orders;
  v_count int;
begin
  perform public.require_permission('orders.status');
  select * into v_order from public.orders where id = p_order_id for update;
  if not found then
    raise exception 'NOT_FOUND: order not found' using errcode = 'P0002';
  end if;
  if v_order.status = 'PARTIALLY_DELIVERED' then
    if p_items is null or jsonb_array_length(p_items) = 0 then
      raise exception 'VALIDATION: choose the items that came back' using errcode = '22023';
    end if;
    v_count := public._return_order_stock(p_order_id, p_items, p_note);
    perform public._post_order_return_finance(p_order_id);
    update public.shipments set return_status = 'RECEIVED', updated_at = now() where order_id = p_order_id and is_active;
    perform public._order_log(p_order_id, 'PARTIAL_RETURN_RECEIVED',
      coalesce(nullif(trim(p_note), ''), format('%s returned line(s) received', v_count)), null, null, jsonb_build_object('items', p_items));
    perform public.log_audit('order.returned', 'order', p_order_id::text, null, p_items, jsonb_build_object('note', p_note, 'partial', true));
    select * into v_order from public.orders where id = p_order_id;
    return v_order;
  end if;
  if v_order.status not in ('FAILED_DELIVERY', 'RETURN_REQUESTED', 'RETURNING', 'PENDING_CANCEL', 'LOST') then
    raise exception 'INVALID_TRANSITION: only parcels on their way back can be received' using errcode = 'P0001';
  end if;
  perform public._return_order_stock(p_order_id, p_items, p_note);
  v_order := public._transition_order(p_order_id, 'RETURNED', p_note, jsonb_build_object('items', p_items));
  perform public.log_audit('order.returned', 'order', p_order_id::text, null, p_items, jsonb_build_object('note', p_note));
  return v_order;
end;

production_action.src:
declare
  v_po public.production_orders;
  v_action text := upper(coalesce(p_action, ''));
  v_to public.production_status;
  v_from public.production_status;
  v_order_target public.order_status;
begin
  perform public.require_permission('production.manage');
  select * into v_po from public.production_orders where id = p_production_id for update;
  if not found then
    raise exception 'NOT_FOUND: production order not found' using errcode = 'P0002';
  end if;
  v_from := v_po.status;

  v_to := case
    when v_action = 'START' and v_po.status in ('WAITING', 'PAUSED') then 'IN_PRODUCTION'
    when v_action = 'RESUME' and v_po.status = 'PAUSED' then 'IN_PRODUCTION'
    when v_action = 'PAUSE' and v_po.status = 'IN_PRODUCTION' then 'PAUSED'
    when v_action = 'SEND_TO_QC' and v_po.status = 'IN_PRODUCTION' then 'QUALITY_CHECK'
    when v_action = 'APPROVE' and v_po.status = 'QUALITY_CHECK' then 'PACKING'
    when v_action = 'REJECT' and v_po.status = 'QUALITY_CHECK' then 'IN_PRODUCTION'
    when v_action = 'MOVE_TO_PACKING' and v_po.status in ('WAITING', 'IN_PRODUCTION') then 'PACKING'
    when v_action = 'MARK_READY' and v_po.status = 'PACKING' then 'READY'
  end::public.production_status;

  if v_to is null then
    raise exception 'INVALID_TRANSITION: cannot % a production order that is %', lower(replace(v_action, '_', ' ')), v_po.status
      using errcode = 'P0001';
  end if;
  if v_action = 'REJECT' and length(trim(coalesce(p_note, ''))) = 0 then
    raise exception 'VALIDATION: a reason is required when rejecting in quality check' using errcode = '22023';
  end if;

  update public.production_orders set
    status = v_to,
    started_at = case when v_to = 'IN_PRODUCTION' then coalesce(started_at, now()) else started_at end,
    qc_at = case when v_to = 'QUALITY_CHECK' then now() else qc_at end,
    completed_at = case when v_to = 'READY' then now() else completed_at end,
    rejection_count = rejection_count + case when v_action = 'REJECT' then 1 else 0 end
  where id = p_production_id
  returning * into v_po;
  perform public._production_log(p_production_id, v_from, v_to, v_action, p_note);

  v_order_target := case v_to
    when 'IN_PRODUCTION' then 'PRODUCTION'
    when 'QUALITY_CHECK' then 'QUALITY_CHECK'
    when 'PACKING' then 'PACKING'
    when 'READY' then 'READY_TO_SHIP'
  end::public.order_status;
  if v_order_target is not null then
    perform public._order_advance_to(v_po.order_id, v_order_target,
      coalesce(p_note, initcap(lower(replace(v_action, '_', ' ')))));
  end if;
  return v_po;
end;

production_update.src:
declare
  v_po public.production_orders;
begin
  perform public.require_permission('production.manage');
  if p_assigned_to is not null and not exists (select 1 from public.profiles where id = p_assigned_to and is_active) then
    raise exception 'VALIDATION: assignee must be an active staff member' using errcode = '22023';
  end if;
  update public.production_orders set assigned_to = p_assigned_to, priority = coalesce(p_priority, priority),
    deadline = p_deadline, notes = nullif(trim(coalesce(p_notes, '')), '')
  where id = p_production_id returning * into v_po;
  if not found then
    raise exception 'NOT_FOUND: production order not found' using errcode = 'P0002';
  end if;
  return v_po;
end;

purchase_order_set_status.src:
declare
  v_po public.purchase_orders;
begin
  perform public.require_permission('purchases.manage');
  select * into v_po from public.purchase_orders where id = p_id for update;
  if not found then
    raise exception 'NOT_FOUND: purchase order not found' using errcode = 'P0002';
  end if;
  if not ((v_po.status = 'DRAFT' and p_status in ('ORDERED', 'CANCELLED'))
       or (v_po.status = 'ORDERED' and p_status in ('CANCELLED', 'DRAFT'))) then
    raise exception 'INVALID_TRANSITION: purchase order is % and cannot become %', v_po.status, p_status using errcode = 'P0001';
  end if;
  update public.purchase_orders set status = p_status where id = p_id returning * into v_po;
  perform public.log_audit('purchase.status_changed', 'purchase_order', p_id::text, null, jsonb_build_object('status', p_status));
  return v_po;
end;

recalculate_order_totals.src:
declare
  v_order public.orders;
  v_coupon public.coupons;
  v_subtotal numeric;
  v_cost numeric;
  v_coupon_discount numeric := 0;
  v_delivery_discount numeric;
  v_paid numeric;
  v_refunded numeric;
  v_total numeric;
  v_due_total numeric;
  v_lines jsonb;
  v_disc record;
begin
  select * into v_order from public.orders where id = p_order_id for update;
  if not found then
    raise exception 'NOT_FOUND: order % does not exist', p_order_id using errcode = 'P0002';
  end if;

  select coalesce(sum(line_subtotal), 0), coalesce(sum(unit_cost * quantity), 0)
  into v_subtotal, v_cost from public.order_items where order_id = p_order_id;

  v_delivery_discount := least(v_order.delivery_discount, v_order.delivery_charge);
  if v_order.coupon_id is not null then
    select * into v_coupon from public.coupons where id = v_order.coupon_id;
    select * into v_disc from public.coupon_discount(v_coupon.discount_type, v_coupon.discount_value,
      v_coupon.max_discount, v_subtotal, v_order.delivery_charge);
    v_coupon_discount := v_disc.discount_amount;
    if v_coupon.discount_type = 'FREE_DELIVERY' then
      v_delivery_discount := v_disc.delivery_discount;
    end if;
  end if;

  v_coupon_discount := least(v_coupon_discount, v_subtotal);
  update public.orders set manual_discount = least(manual_discount, v_subtotal - v_coupon_discount)
  where id = p_order_id returning * into v_order;

  select coalesce(jsonb_agg(jsonb_build_object('id', id, 'line_subtotal', line_subtotal) order by line_subtotal desc, id), '[]'::jsonb)
  into v_lines from public.order_items where order_id = p_order_id;
  v_lines := public._allocate_discount(v_lines, v_coupon_discount + v_order.manual_discount);
  update public.order_items oi
  set discount_amount = (l ->> 'discount_amount')::numeric, line_total = (l ->> 'line_total')::numeric
  from jsonb_array_elements(v_lines) l
  where oi.id = (l ->> 'id')::uuid
    and (oi.discount_amount, oi.line_total) is distinct from ((l ->> 'discount_amount')::numeric, (l ->> 'line_total')::numeric);

  select coalesce(sum(amount) filter (where kind <> 'REFUND'), 0), coalesce(sum(amount) filter (where kind = 'REFUND'), 0)
  into v_paid, v_refunded from public.order_payments where order_id = p_order_id;

  v_total := public.money(v_subtotal - v_coupon_discount - v_order.manual_discount + v_order.delivery_charge - v_delivery_discount + coalesce(v_order.tax_amount, 0));
  v_due_total := greatest(v_total - v_order.partial_return_amount, 0);

  update public.orders set
    subtotal = public.money(v_subtotal),
    coupon_discount = public.money(v_coupon_discount),
    discount_total = public.money(v_coupon_discount + manual_discount),
    delivery_discount = public.money(v_delivery_discount),
    total_amount = v_total,
    cost_total = public.money(v_cost),
    amount_paid = public.money(v_paid - v_refunded),
    amount_refunded = public.money(v_refunded),
    cod_amount = greatest(v_due_total - public.money(v_paid - v_refunded), 0),
    payment_status = case
      when v_refunded > 0 and v_paid - v_refunded <= 0 then 'REFUNDED'
      when v_refunded > 0 then 'PARTIALLY_REFUNDED'
      when v_paid >= v_due_total and v_due_total > 0 then 'PAID'
      when v_paid > 0 then 'PARTIALLY_PAID'
      else 'UNPAID'
    end::public.payment_status
  where id = p_order_id
  returning * into v_order;

  return v_order;
end;

receive_purchase_order.src:
declare
  v_po public.purchase_orders;
  v_item public.purchase_order_items;
  v_qty int;
  v_inv public.inventory;
  v_old_cost numeric;
  v_method text := upper(public.setting_text('inventory', array['costing_method'], 'WEIGHTED_AVERAGE'));
  v_landed numeric;
  v_received_any boolean := false;
begin
  perform public.require_permission('purchases.manage');
  select * into v_po from public.purchase_orders where id = p_id for update;
  if not found then
    raise exception 'NOT_FOUND: purchase order not found' using errcode = 'P0002';
  end if;
  if v_po.status not in ('ORDERED', 'PARTIALLY_RECEIVED', 'DRAFT') then
    raise exception 'VALIDATION: % purchase orders cannot be received', v_po.status using errcode = '22023';
  end if;

  for v_item in select * from public.purchase_order_items where purchase_order_id = p_id for update loop
    if p_items is null then
      v_qty := v_item.quantity - v_item.received_quantity;
    else
      select (e ->> 'quantity')::int into v_qty from jsonb_array_elements(p_items) e
      where (e ->> 'item_id')::uuid = v_item.id;
    end if;
    if coalesce(v_qty, 0) <= 0 then
      continue;
    end if;
    if v_qty > v_item.quantity - v_item.received_quantity then
      raise exception 'VALIDATION: receiving more than ordered for an item' using errcode = '22023';
    end if;

    -- Landed unit cost: item cost plus its share of the PO shipping cost.
    v_landed := v_item.unit_cost + case when v_po.subtotal > 0
      then v_po.shipping_cost * v_item.unit_cost / v_po.subtotal else 0 end;

    select * into v_inv from public.inventory where variant_id = v_item.variant_id for update;
    v_old_cost := public.variant_cost(v_item.variant_id);
    if v_method = 'WEIGHTED_AVERAGE' then
      update public.product_variants set cost_price = public.money(
        (greatest(coalesce(v_inv.on_hand, 0), 0) * v_old_cost + v_qty * v_landed) / (greatest(coalesce(v_inv.on_hand, 0), 0) + v_qty))
      where id = v_item.variant_id;
    elsif v_method = 'LATEST' then
      update public.product_variants set cost_price = public.money(v_landed) where id = v_item.variant_id;
    end if;

    perform public._apply_inventory_movement(v_item.variant_id, 'PURCHASE', v_qty, 0, 0, 'PURCHASE_ORDER', p_id,
      v_po.po_number, coalesce(p_note, 'Received from purchase order'), public.money(v_landed));
    update public.purchase_order_items set received_quantity = received_quantity + v_qty where id = v_item.id;
    v_received_any := true;
  end loop;

  if not v_received_any then
    raise exception 'VALIDATION: nothing to receive' using errcode = '22023';
  end if;

  update public.purchase_orders set
    status = case when not exists (select 1 from public.purchase_order_items
                                   where purchase_order_id = p_id and received_quantity < quantity)
                  then 'RECEIVED' else 'PARTIALLY_RECEIVED' end::public.purchase_status,
    received_at = now()
  where id = p_id returning * into v_po;

  perform public.log_audit('purchase.received', 'purchase_order', p_id::text, null,
    jsonb_build_object('status', v_po.status, 'items', p_items));
  return v_po;
end;

record_cod_settlement.src:
declare
  v_ship public.shipments;
  v_order public.orders;
  v_due numeric;
  v_count int := 0;
  v_total numeric := 0;
  v_skipped jsonb := '[]'::jsonb;
begin
  perform public.require_permission('payments.record');
  for v_ship in select * from public.shipments where id = any(p_shipment_ids) for update loop
    select * into v_order from public.orders where id = v_ship.order_id;
    v_due := v_order.cod_amount;
    if v_order.delivered_at is null or v_due <= 0 then
      v_skipped := v_skipped || jsonb_build_object('shipment_id', v_ship.id, 'order_number', v_order.order_number,
        'reason', case when v_order.delivered_at is null then 'not delivered' else 'nothing due' end);
      continue;
    end if;
    perform public.record_order_payment(v_order.id, 'COD', 'COURIER_COD', v_due, p_reference,
      coalesce(p_note, 'COD settlement'), 'cod:' || v_ship.id);
    update public.shipments set cod_collected = cod_collected + v_due, cod_collected_at = now() where id = v_ship.id;
    v_count := v_count + 1;
    v_total := v_total + v_due;
  end loop;
  return jsonb_build_object('settled', v_count, 'amount', v_total, 'skipped', v_skipped);
end;

record_courier_webhook.src:
declare
  v_id uuid;
  v_inserted boolean;
  v_result text;
begin
  if not public.is_system_context() then
    raise exception 'PERMISSION_DENIED' using errcode = '42501';
  end if;
  if coalesce(p_event ->> 'event_key', '') = '' then
    raise exception 'VALIDATION: event_key is required' using errcode = '22023';
  end if;
  insert into public.courier_webhook_events(courier_id, provider, event_key, event_type, consignment_id, order_ref,
    provider_status, new_status, occurred_at, charges, payload)
  values (p_courier_id, p_provider, left(p_event ->> 'event_key', 300), coalesce(nullif(p_event ->> 'event_type', ''), 'status'),
    nullif(p_event ->> 'consignment_id', ''), nullif(p_event ->> 'order_ref', ''), nullif(p_event ->> 'provider_status', ''),
    nullif(p_event ->> 'status', '')::public.shipment_status, nullif(p_event ->> 'occurred_at', '')::timestamptz,
    coalesce(p_event -> 'charges', '{}'::jsonb), coalesce(p_event -> 'payload', '{}'::jsonb))
  on conflict (event_key) do update set duplicates = public.courier_webhook_events.duplicates + 1
  returning id, (xmax = 0), result into v_id, v_inserted, v_result;
  if not v_inserted and v_result not in ('FAILED', 'UNMATCHED') then
    return jsonb_build_object('status', 'duplicate', 'event_id', v_id);
  end if;
  return public._process_courier_webhook(v_id);
end;

record_fraud_check.src:
declare
  v_phone text := public.clean_phone(p_input ->> 'phone');
  v_order_id uuid := nullif(p_input ->> 'order_id', '')::uuid;
  v_internal jsonb;
  v_counts jsonb := coalesce(p_input -> 'provider_counts', '{}'::jsonb);
  v_m jsonb;
  v_delivered int;
  v_cancelled int;
  v_returned int;
  v_failed int;
  v_completed int;
  v_score numeric;
  v_level public.risk_level;
  v_courier numeric;
  v_eval jsonb;
  v_context jsonb := coalesce(p_input -> 'context', '{}'::jsonb);
  v_check public.fraud_checks;
  v_status text := coalesce(p_input ->> 'status', 'SUCCESS');
begin
  if not (public.is_system_context() or public.has_permission('fraud.review')) then
    raise exception 'PERMISSION_DENIED: fraud.review is required' using errcode = '42501';
  end if;
  if v_phone is null then
    raise exception 'VALIDATION: phone is required for a fraud check' using errcode = '22023';
  end if;

  v_internal := public.fraud_customer_metrics(v_phone, v_order_id);

  -- Merge own history with provider (courier network) counts.
  v_delivered := greatest((v_internal ->> 'delivered_orders')::int, coalesce((v_counts ->> 'delivered')::int, 0));
  v_cancelled := greatest((v_internal ->> 'cancelled_orders')::int, coalesce((v_counts ->> 'cancelled')::int, 0));
  v_returned := greatest((v_internal ->> 'returned_orders')::int, coalesce((v_counts ->> 'returned')::int, 0));
  v_failed := greatest((v_internal ->> 'failed_delivery_orders')::int, coalesce((v_counts ->> 'failed')::int, 0));
  v_completed := v_delivered + v_cancelled + v_returned + v_failed;

  v_courier := coalesce((p_input ->> 'provider_courier_score')::numeric,
    public.outcome_rate(v_delivered, v_delivered + v_returned + v_failed));

  v_m := v_internal || jsonb_build_object(
    'previous_orders', greatest((v_internal ->> 'previous_orders')::int, coalesce((v_counts ->> 'total')::int, 0)),
    'delivered_orders', v_delivered,
    'cancelled_orders', v_cancelled,
    'returned_orders', v_returned,
    'failed_delivery_orders', v_failed,
    'cancellation_rate', public.outcome_rate(v_cancelled, v_completed),
    'return_rate', public.outcome_rate(v_returned, v_completed),
    'failed_delivery_rate', public.outcome_rate(v_failed, v_completed),
    'courier_score', v_courier,
    'provider_risk_score', (p_input ->> 'provider_risk_score')::numeric,
    'provider_parcels', coalesce((p_input ->> 'provider_parcel_floor')::int, 0),
    'provider_status', case when (p_input ->> 'provider') = 'internal' then 'SUCCESS' else v_status end
  );
  v_m := v_m || public._receive_rate_facts(v_m);

  v_score := public.compute_risk_score(v_m);
  if v_status = 'ERROR' and public.setting_text('fraud', array['on_provider_error'], 'REVIEW') = 'REVIEW'
     and (p_input ->> 'provider') <> 'internal' then
    -- Provider unavailable: never silently pass a check that did not run.
    v_score := greatest(v_score, public.setting_numeric('fraud', array['thresholds', 'high'], 60));
  end if;
  v_level := public.risk_level_for_score(v_score);
  v_m := v_m || jsonb_build_object('risk_score', v_score, 'risk_level', v_level);

  v_eval := public.evaluate_fraud_rules(v_m, v_context);

  insert into public.fraud_checks(
    order_id, customer_id, phone, provider, providers, status, risk_score, risk_level, courier_score,
    previous_orders, delivered_orders, cancelled_orders, returned_orders, failed_delivery_orders,
    cancellation_rate, return_rate, failed_delivery_rate, recommendation, decision, advance_type, advance_amount,
    matched_rules, metrics, context, provider_response, error, created_by
  ) values (
    v_order_id, (v_internal ->> 'customer_id')::uuid, v_phone, coalesce(p_input ->> 'provider', 'internal'),
    coalesce(array(select jsonb_array_elements_text(coalesce(p_input -> 'providers', '[]'::jsonb))), '{}'),
    v_status, v_score, v_level, v_courier,
    (v_m ->> 'previous_orders')::int, v_delivered, v_cancelled, v_returned, v_failed,
    (v_m ->> 'cancellation_rate')::numeric, (v_m ->> 'return_rate')::numeric, (v_m ->> 'failed_delivery_rate')::numeric,
    coalesce(nullif(p_input ->> 'recommendation', ''), initcap(replace(v_eval ->> 'decision', '_', ' '))),
    (v_eval ->> 'decision')::public.fraud_decision, (v_eval ->> 'advance_type')::public.advance_type,
    (v_eval ->> 'advance_amount')::numeric, v_eval -> 'matched_rules', v_m, v_context,
    p_input -> 'provider_response', nullif(p_input ->> 'error', ''), auth.uid()
  ) returning * into v_check;

  if v_check.customer_id is not null then
    update public.customers set risk_level = v_level, last_fraud_score = v_score, last_fraud_check_at = now()
    where id = v_check.customer_id;
    perform public.refresh_customer_stats(v_check.customer_id);
  end if;
  return v_check;
end;

record_order_attribution.src:
begin
  if not public.is_system_context() then
    raise exception 'PERMISSION_DENIED' using errcode = '42501';
