record_order_payment.src:
declare
  v_order public.orders;
  v_op public.order_payments;
begin
  perform public.require_permission('payments.record');
  if p_kind = 'REFUND' then
    raise exception 'VALIDATION: use refund_order for refunds' using errcode = '22023';
  end if;
  if coalesce(p_amount, 0) <= 0 then
    raise exception 'VALIDATION: amount must be positive' using errcode = '22023';
  end if;
  if p_idempotency_key is not null then
    select * into v_op from public.order_payments where idempotency_key = p_idempotency_key;
    if found then
      return v_op;
    end if;
  end if;
  select * into v_order from public.orders where id = p_order_id for update;
  if not found then
    raise exception 'NOT_FOUND: order not found' using errcode = 'P0002';
  end if;
  if v_order.status in ('CANCELLED', 'REJECTED_FRAUD') then
    raise exception 'VALIDATION: cannot record a payment on a % order', v_order.status using errcode = '22023';
  end if;
  if public.money(p_amount) > v_order.total_amount - v_order.amount_paid then
    raise exception 'VALIDATION: amount exceeds the %s still due', v_order.total_amount - v_order.amount_paid
      using errcode = '22023';
  end if;

  insert into public.order_payments(order_id, kind, channel, amount, reference, note, idempotency_key, recorded_by)
  values (p_order_id, p_kind, p_channel, public.money(p_amount), nullif(trim(coalesce(p_reference, '')), ''),
          nullif(trim(coalesce(p_note, '')), ''), p_idempotency_key, auth.uid())
  returning * into v_op;

  perform public._post_finance('INCOME',
    case p_kind when 'ADVANCE' then 'ADVANCE_PAYMENTS' when 'COD' then 'COD_COLLECTIONS' else 'ONLINE_PAYMENTS' end,
    v_op.amount, (now() at time zone public.store_timezone())::date, true, p_order_id, v_order.customer_id, null,
    v_order.order_number, format('%s payment recorded (%s)', initcap(p_kind::text), p_channel),
    'order_payment:' || v_op.id, p_channel);

  perform public._order_log(p_order_id, 'PAYMENT_RECEIVED',
    format('%s %s payment recorded via %s', v_op.amount, lower(p_kind::text), p_channel), null, null,
    jsonb_build_object('order_payment_id', v_op.id));
  perform public.log_audit('payment.recorded', 'order', p_order_id::text, null,
    jsonb_build_object('kind', p_kind, 'channel', p_channel, 'amount', v_op.amount, 'reference', p_reference));
  perform public._order_payment_after_change(p_order_id, p_kind, v_op.amount);
  return v_op;
end;

record_partial_delivery.src:
declare
  v_order public.orders;
  v_value numeric;
  v_units int;
  v_over boolean;
  v_all int;
  v_message text;
begin
  perform public.require_permission('orders.status');
  select * into v_order from public.orders where id = p_order_id for update;
  if not found then
    raise exception 'NOT_FOUND: order not found' using errcode = 'P0002';
  end if;
  if v_order.status not in ('SHIPPED', 'FAILED_DELIVERY', 'PARTIALLY_DELIVERED') then
    raise exception 'INVALID_TRANSITION: only shipped orders can be partly delivered' using errcode = 'P0001';
  end if;
  if v_order.partial_return_amount > 0 then
    raise exception 'VALIDATION: the partial delivery was already recorded' using errcode = '22023';
  end if;
  if jsonb_typeof(p_items) is distinct from 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'VALIDATION: choose the items the customer sent back' using errcode = '22023';
  end if;
  if exists (select 1 from jsonb_array_elements(p_items) r
             where not exists (select 1 from public.order_items oi
                               where oi.id::text = r ->> 'order_item_id' and oi.order_id = p_order_id)) then
    raise exception 'VALIDATION: an item does not belong to this order' using errcode = '22023';
  end if;

  select coalesce(sum(round(oi.line_total / oi.quantity * b.back, 2)), 0), coalesce(sum(b.back), 0), coalesce(bool_or(b.back > oi.quantity), false)
  into v_value, v_units, v_over
  from (select (r ->> 'order_item_id')::uuid as id, sum(greatest(coalesce((r ->> 'quantity')::int, 0), 0)) as back
        from jsonb_array_elements(p_items) r group by 1) b
  join public.order_items oi on oi.id = b.id;
  select coalesce(sum(quantity), 0) into v_all from public.order_items where order_id = p_order_id;
  if v_over then
    raise exception 'VALIDATION: more items came back than were shipped' using errcode = '22023';
  end if;
  if v_units = 0 then
    raise exception 'VALIDATION: choose the items the customer sent back' using errcode = '22023';
  end if;
  if v_units >= v_all then
    raise exception 'VALIDATION: everything came back — mark the order as returning instead' using errcode = '22023';
  end if;

  update public.orders set partial_return_amount = least(public.money(v_value), total_amount) where id = p_order_id;
  v_order := public.recalculate_order_totals(p_order_id);
  v_message := coalesce(nullif(trim(p_note), ''),
    format('Customer kept part of the order; %s item(s) worth %s coming back', v_units, v_order.partial_return_amount));
  if v_order.status = 'PARTIALLY_DELIVERED' then
    perform public._post_partial_return_finance(p_order_id);
    perform public._order_log(p_order_id, 'PARTIAL_RECORDED', v_message, null, null,
      jsonb_build_object('items', p_items, 'returned_value', v_order.partial_return_amount));
  else
    v_order := public._transition_order(p_order_id, 'PARTIALLY_DELIVERED', v_message,
      jsonb_build_object('items', p_items, 'returned_value', v_order.partial_return_amount));
  end if;
  perform public.log_audit('order.partial_delivery', 'order', p_order_id::text, null,
    jsonb_build_object('items', p_items, 'returned_value', v_order.partial_return_amount), jsonb_build_object('note', p_note));
  select * into v_order from public.orders where id = p_order_id;
  return v_order;
end;

record_purchase_payment.src:
declare
  v_po public.purchase_orders;
begin
  perform public.require_permission('purchases.manage');
  perform public.require_permission('finance.manage');
  select * into v_po from public.purchase_orders where id = p_id for update;
  if not found then
    raise exception 'NOT_FOUND: purchase order not found' using errcode = 'P0002';
  end if;
  if coalesce(p_amount, 0) <= 0 or public.money(p_amount) > v_po.total_cost - v_po.amount_paid then
    raise exception 'VALIDATION: payment must be between 1 and the % outstanding', v_po.total_cost - v_po.amount_paid
      using errcode = '22023';
  end if;
  perform public._post_finance('EXPENSE', 'PRODUCT_PURCHASE', p_amount,
    coalesce(p_date, (now() at time zone public.store_timezone())::date), true, null, null, v_po.supplier_id,
    coalesce(nullif(trim(p_reference), ''), v_po.po_number), coalesce(nullif(trim(p_note), ''), 'Supplier payment ' || v_po.po_number),
    'purchase_payment:' || gen_random_uuid(), p_channel, p_id);
  update public.purchase_orders set amount_paid = amount_paid + public.money(p_amount),
    payment_status = case when amount_paid + public.money(p_amount) >= total_cost then 'PAID' else 'PARTIALLY_PAID' end::public.settlement_status
  where id = p_id returning * into v_po;
  perform public.log_audit('purchase.payment_recorded', 'purchase_order', p_id::text, null,
    jsonb_build_object('amount', p_amount, 'channel', p_channel));
  return v_po;
end;

record_sms_delivery.src:
declare
  v_log public.notification_logs;
  u public.service_usage;
  v_own_cost boolean;
begin
  if not public.is_system_context() then
    raise exception 'PERMISSION_DENIED' using errcode = '42501';
  end if;
  select * into v_log from public.notification_logs where id = p_id and channel = 'SMS' and status = 'SENT';
  if v_log.id is null then
    return;
  end if;
  select * into u from public.service_usage where merchant_id = v_log.merchant_id and idempotency_key = 'sms:' || p_id;
  v_own_cost := u.id is null or u.charge = 'PLAN';
  update public.notification_logs set
    delivery_status = case when p_status in ('PENDING', 'DELIVERED', 'FAILED', 'UNKNOWN') then p_status else delivery_status end,
    delivered_at = case when p_status = 'DELIVERED' then coalesce(delivered_at, now()) else delivered_at end,
    status_checked_at = now(),
    cost = case when v_own_cost and p_cost is not null and p_cost >= 0 then p_cost else cost end,
    cost_source = case when v_own_cost and p_cost is not null and p_cost >= 0 then 'PROVIDER' else cost_source end
  where id = p_id;
  if u.id is not null and p_status in ('DELIVERED', 'FAILED') then
    perform public._usage_outcome(u.id, case p_status when 'DELIVERED' then 'DELIVERED' else 'UNDELIVERED' end, p_cost);
  end if;
  perform public._post_sms_finance(p_id);
end;

refund_order.src:
declare
  v_order public.orders;
  v_op public.order_payments;
  v_revenue_recognised boolean;
begin
  perform public.require_permission('refunds.manage');
  if coalesce(p_amount, 0) <= 0 then
    raise exception 'VALIDATION: refund amount must be positive' using errcode = '22023';
  end if;
  if length(trim(coalesce(p_reason, ''))) = 0 then
    raise exception 'VALIDATION: a refund reason is required' using errcode = '22023';
  end if;
  if p_idempotency_key is not null then
    select * into v_op from public.order_payments where idempotency_key = p_idempotency_key;
    if found then
      return v_op;
    end if;
  end if;
  select * into v_order from public.orders where id = p_order_id for update;
  if not found then
    raise exception 'NOT_FOUND: order not found' using errcode = 'P0002';
  end if;
  if public.money(p_amount) > v_order.amount_paid then
    raise exception 'VALIDATION: refund exceeds the % paid on this order', v_order.amount_paid using errcode = '22023';
  end if;
  if v_order.advance_resolution = 'RETAINED' then
    raise exception 'VALIDATION: the advance on this order was retained as income' using errcode = '22023';
  end if;

  insert into public.order_payments(order_id, kind, channel, amount, reference, note, idempotency_key, recorded_by)
  values (p_order_id, 'REFUND', p_channel, public.money(p_amount), null, trim(p_reason), p_idempotency_key, auth.uid())
  returning * into v_op;

  -- Revenue recognised (delivered) -> contra-revenue. Otherwise it is just the
  -- advance going back: cash out, no P&L effect.
  v_revenue_recognised := exists (select 1 from public.finance_transactions
                                  where source_key = 'order:' || p_order_id || ':product_revenue');
  perform public._post_finance('EXPENSE', case when v_revenue_recognised then 'REFUNDS' else 'ADVANCE_REFUNDS' end,
    v_op.amount, (now() at time zone public.store_timezone())::date, true, p_order_id, v_order.customer_id, null,
    v_order.order_number, 'Refund: ' || trim(p_reason), 'order_payment:' || v_op.id, p_channel);

  v_order := public.recalculate_order_totals(p_order_id);
  if v_order.amount_paid <= 0 and v_order.status in ('CANCELLED', 'REJECTED_FRAUD', 'RETURNED', 'FAILED_DELIVERY') then
    update public.orders set advance_resolution = 'REFUNDED' where id = p_order_id;
  end if;
  perform public._order_log(p_order_id, 'REFUNDED', format('Refunded %s: %s', v_op.amount, trim(p_reason)),
    null, null, jsonb_build_object('order_payment_id', v_op.id), true);
  perform public.log_audit('refund.created', 'order', p_order_id::text, null,
    jsonb_build_object('amount', v_op.amount, 'channel', p_channel, 'reason', p_reason));
  return v_op;
end;

render_template.src:
declare
  v_out text := coalesce(p_template, '');
  v_key text;
begin
  for v_key in select jsonb_object_keys(coalesce(p_vars, '{}'::jsonb)) loop
    v_out := replace(v_out, '{{' || v_key || '}}', coalesce(p_vars ->> v_key, ''));
  end loop;
  return regexp_replace(v_out, '\{\{[a-z_]+\}\}', '', 'g');
end;

report_advance_payments.src:
begin
  if current_setting('app.core_report', true) is distinct from 'on' then
    perform public.require_feature('reports');
  end if;
  perform public._report_access('finance.view');
  return (
    select jsonb_build_object(
      'orders_requiring_advance', count(*) filter (where advance_required > 0),
      'advance_required_total', coalesce(sum(advance_required) filter (where advance_required > 0), 0),
      'orders_paid', count(*) filter (where advance_required > 0 and amount_paid >= advance_required),
      'advance_collected', coalesce((select sum(op.amount) from public.order_payments op
          join public._report_orders(p_from, p_to, '{}'::jsonb) o2 on o2.id = op.order_id
          where op.kind in ('ADVANCE', 'FULL')), 0),
      'expired_unpaid', count(*) filter (where advance_required > 0 and status = 'CANCELLED' and amount_paid < advance_required),
      'awaiting_payment', count(*) filter (where status = 'ADVANCE_REQUIRED'),
      'payment_rate', case when count(*) filter (where advance_required > 0) > 0
        then round(100.0 * count(*) filter (where advance_required > 0 and amount_paid >= advance_required)
                   / count(*) filter (where advance_required > 0), 2) end,
      'delivered_after_advance', count(*) filter (where advance_required > 0 and delivered_at is not null),
      'by_channel', coalesce((select jsonb_object_agg(channel, amount) from (
          select op.channel, sum(op.amount) as amount from public.order_payments op
          join public._report_orders(p_from, p_to, '{}'::jsonb) o3 on o3.id = op.order_id
          where op.kind in ('ADVANCE', 'FULL') group by op.channel) s), '{}'::jsonb)
    )
    from public._report_orders(p_from, p_to, '{}'::jsonb)
  );
end;

report_cancellations_returns.src:
begin
  if current_setting('app.core_report', true) is distinct from 'on' then
    perform public.require_feature('reports');
  end if;
  perform public._report_access('reports.view');
  return jsonb_build_object(
    'cancel_reasons', coalesce((select jsonb_agg(t) from (
        select coalesce(nullif(trim(cancel_reason), ''), 'No reason given') as reason, count(*) as orders, sum(total_amount) as value
        from public._report_orders(p_from, p_to, '{}'::jsonb) where status in ('CANCELLED', 'REJECTED_FRAUD')
        group by 1 order by orders desc limit 20) t), '[]'::jsonb),
    'returned_products', coalesce((select jsonb_agg(t) from (
        select oi.product_name, sum(oi.returned_quantity) as restocked, sum(oi.damaged_quantity) as damaged
        from public._report_orders(p_from, p_to, '{}'::jsonb) o join public.order_items oi on oi.order_id = o.id
        where oi.returned_quantity + oi.damaged_quantity > 0
        group by oi.product_name order by sum(oi.returned_quantity + oi.damaged_quantity) desc limit 20) t), '[]'::jsonb),
    'by_district', coalesce((select jsonb_agg(t) from (
        select initcap(shipping_district) as district,
               count(*) filter (where status = 'CANCELLED') as cancelled,
               count(*) filter (where status = 'RETURNED' or status = 'FAILED_DELIVERY') as returned_or_failed,
               count(*) as orders
        from public._report_orders(p_from, p_to, '{}'::jsonb) group by 1
        having count(*) filter (where status in ('CANCELLED', 'RETURNED', 'FAILED_DELIVERY')) > 0
        order by 3 desc, 2 desc limit 20) t), '[]'::jsonb)
  );
end;

report_cash_flow.src:
declare
  v jsonb;
  v_unit text := case when p_granularity in ('day', 'week', 'month', 'year') then p_granularity else 'day' end;
begin
  if current_setting('app.core_report', true) is distinct from 'on' then
    perform public.require_feature('reports');
  end if;
  perform public.require_permission('finance.view');
  with t as (
    select date_trunc(v_unit, ft.txn_date::timestamp)::date as bucket,
           sum(ft.amount) filter (where ft.type = 'INCOME') as cash_in,
           sum(ft.amount) filter (where ft.type = 'EXPENSE') as cash_out
    from public.finance_transactions ft
    where ft.is_cash and ft.txn_date between p_from and p_to
    group by 1
  ), by_cat as (
    select c.name, c.type, sum(ft.amount) as amount
    from public.finance_transactions ft join public.finance_categories c on c.id = ft.category_id
    where ft.is_cash and ft.txn_date between p_from and p_to
    group by c.name, c.type
  )
  select jsonb_build_object(
    'cash_in', coalesce((select sum(cash_in) from t), 0),
    'cash_out', coalesce((select sum(cash_out) from t), 0),
    'net_cash_flow', coalesce((select sum(coalesce(cash_in, 0) - coalesce(cash_out, 0)) from t), 0),
    'series', coalesce((select jsonb_agg(jsonb_build_object('bucket', bucket, 'cash_in', coalesce(cash_in, 0),
      'cash_out', coalesce(cash_out, 0), 'net', coalesce(cash_in, 0) - coalesce(cash_out, 0)) order by bucket) from t), '[]'::jsonb),
    'by_category', coalesce((select jsonb_agg(jsonb_build_object('name', name, 'type', type, 'amount', amount)
      order by type, amount desc) from by_cat), '[]'::jsonb)
  ) into v;
  return v;
end;

report_customers.src:
begin
  if current_setting('app.core_report', true) is distinct from 'on' then
    perform public.require_feature('reports');
  end if;
  perform public._report_access('customers.view');
  return jsonb_build_object(
    'segments', coalesce((select jsonb_object_agg(segment, n) from (
        select segment, count(*) n from public.customers group by segment) s), '{}'::jsonb),
    'new_customers', (select count(*) from public.customers
                      where created_at >= public._ts_from(p_from) and created_at < public._ts_from(p_to + 1)),
    'repeat_customers', (select count(*) from (select customer_id from public._report_orders(p_from, p_to, '{}'::jsonb)
                         group by customer_id having count(*) > 1) r),
    'top_customers', coalesce((select jsonb_agg(t) from (
        select c.id, c.full_name, c.phone, c.segment, c.district, count(o.id) as orders,
               coalesce(sum(o.total_amount) filter (where o.delivered_at is not null), 0) as delivered_value,
               count(o.id) filter (where o.status = 'CANCELLED') as cancelled,
               count(o.id) filter (where o.status in ('RETURNED', 'FAILED_DELIVERY')) as returned_or_failed
        from public._report_orders(p_from, p_to, '{}'::jsonb) o join public.customers c on c.id = o.customer_id
        group by c.id order by delivered_value desc, orders desc limit least(greatest(p_limit, 1), 500)) t), '[]'::jsonb),
    'by_district', coalesce((select jsonb_agg(t) from (
        select initcap(shipping_district) as district, count(*) as orders, count(distinct customer_id) as customers,
               coalesce(sum(total_amount) filter (where delivered_at is not null), 0) as delivered_value
        from public._report_orders(p_from, p_to, '{}'::jsonb) group by initcap(shipping_district)
        order by orders desc limit 30) t), '[]'::jsonb)
  );
end;

report_expenses_by_category.src:
declare
  v jsonb;
begin
  if current_setting('app.core_report', true) is distinct from 'on' then
    perform public.require_feature('reports');
  end if;
  perform public.require_permission('finance.view');
  select coalesce(jsonb_agg(jsonb_build_object('code', code, 'name', name, 'pnl_group', pnl_group, 'amount', amount)
                  order by amount desc), '[]'::jsonb) into v
  from (
    select c.code, c.name, c.pnl_group, sum(ft.amount) as amount
    from public.finance_transactions ft join public.finance_categories c on c.id = ft.category_id
    where ft.type = 'EXPENSE' and ft.txn_date between p_from and p_to
    group by c.code, c.name, c.pnl_group
    having sum(ft.amount) <> 0
  ) t;
  return v;
end;

report_fraud.src:
begin
  if current_setting('app.core_report', true) is distinct from 'on' then
    perform public.require_feature('reports');
  end if;
  perform public._report_access('fraud.view');
  return jsonb_build_object(
    'checks', (select count(*) from public.fraud_checks where created_at >= public._ts_from(p_from) and created_at < public._ts_from(p_to + 1)),
    'provider_errors', (select count(*) from public.fraud_checks where status = 'ERROR'
                        and created_at >= public._ts_from(p_from) and created_at < public._ts_from(p_to + 1)),
    'decisions', coalesce((select jsonb_object_agg(coalesce(fraud_decision::text, 'NOT_CHECKED'), n) from (
        select fraud_decision, count(*) n from public._report_orders(p_from, p_to, '{}'::jsonb) group by fraud_decision) s), '{}'::jsonb),
    'risk_levels', coalesce((select jsonb_object_agg(coalesce(risk_level::text, 'UNKNOWN'), n) from (
        select risk_level, count(*) n from public._report_orders(p_from, p_to, '{}'::jsonb) group by risk_level) s), '{}'::jsonb),
    'outcomes_by_risk', coalesce((select jsonb_agg(t) from (
        select coalesce(risk_level::text, 'UNKNOWN') as risk_level, count(*) as orders,
               count(*) filter (where delivered_at is not null) as delivered,
               count(*) filter (where status in ('CANCELLED', 'REJECTED_FRAUD')) as cancelled_or_rejected,
               count(*) filter (where status = 'FAILED_DELIVERY' or (status = 'RETURNED' and delivered_at is null)) as failed
        from public._report_orders(p_from, p_to, '{}'::jsonb) group by 1 order by 1) t), '[]'::jsonb),
    'reviews', coalesce((select jsonb_object_agg(action, n) from (
        select action, count(*) n from public.fraud_reviews
        where created_at >= public._ts_from(p_from) and created_at < public._ts_from(p_to + 1) group by action) s), '{}'::jsonb),
    'rejected_value', coalesce((select sum(total_amount) from public._report_orders(p_from, p_to, '{}'::jsonb)
                                where status = 'REJECTED_FRAUD'), 0)
  );
end;

report_inventory_valuation.src:
begin
  if current_setting('app.core_report', true) is distinct from 'on' then
    perform public.require_feature('reports');
  end if;
  perform public._report_access('inventory.view');
  return jsonb_build_object(
    'totals', (select jsonb_build_object(
        'units_on_hand', coalesce(sum(on_hand) filter (where on_hand > 0), 0),
        'units_reserved', coalesce(sum(reserved), 0),
        'units_damaged', coalesce(sum(damaged), 0),
        'value_at_cost', coalesce(sum(greatest(on_hand, 0) * unit_cost), 0),
        'value_at_retail', coalesce(sum(greatest(on_hand, 0) * unit_price), 0),
        'damaged_value', coalesce(sum(damaged * unit_cost), 0),
        'low_stock_variants', count(*) filter (where stock_status = 'LOW_STOCK'),
        'out_of_stock_variants', count(*) filter (where stock_status = 'OUT_OF_STOCK'))
      from public.inventory_overview where track_inventory),
    'by_category', coalesce((select jsonb_agg(t order by t.value_at_cost desc) from (
        select coalesce(category_name, 'Uncategorised') as category, sum(greatest(on_hand, 0)) as units,
               sum(greatest(on_hand, 0) * unit_cost) as value_at_cost, sum(greatest(on_hand, 0) * unit_price) as value_at_retail
        from public.inventory_overview where track_inventory group by 1) t), '[]'::jsonb),
    'items', coalesce((select jsonb_agg(t order by t.value_at_cost desc) from (
        select product_name, variant_title, sku, on_hand, reserved, available, damaged, unit_cost, unit_price,
               greatest(on_hand, 0) * unit_cost as value_at_cost, stock_status
        from public.inventory_overview where track_inventory) t), '[]'::jsonb)
  );
end;

report_issue.src:
declare
  v_msg text := trim(coalesce(p_message, ''));
  v_t public.support_tickets;
begin
  if not public.is_staff() then
    raise exception 'PERMISSION_DENIED: staff only' using errcode = '42501';
  end if;
  if length(v_msg) < 5 then
    raise exception 'VALIDATION: Describe the problem in a few words' using errcode = '22023';
  end if;
  v_t := public.support_ticket_create(jsonb_build_object('kind', 'BUG', 'subject',
    case when length(v_msg) > 80 then left(v_msg, 77) || '…' else v_msg end, 'body', v_msg, 'context', coalesce(p_context, '{}'::jsonb)));
  return v_t.number;
end;

report_product_performance.src:
declare
  v jsonb;
  v_finance boolean := public.is_system_context() or public.has_permission('finance.view');
begin
  if current_setting('app.core_report', true) is distinct from 'on' then
    perform public.require_feature('reports');
  end if;
  perform public._report_access('reports.view');
  select coalesce(jsonb_agg(t order by t.revenue desc), '[]'::jsonb) into v
  from (
    select oi.product_id, max(oi.product_name) as product_name, max(c.name) as category_name,
           sum(oi.quantity) filter (where o.status not in ('CANCELLED', 'REJECTED_FRAUD')) as ordered_qty,
           coalesce(sum(oi.quantity - oi.returned_quantity - oi.damaged_quantity) filter (where o.delivered_at is not null), 0) as sold_qty,
           coalesce(sum(oi.returned_quantity + oi.damaged_quantity), 0) as returned_qty,
           coalesce(sum(oi.line_total) filter (where o.delivered_at is not null), 0) as revenue,
           case when v_finance then coalesce(sum(oi.unit_cost * (oi.quantity - oi.returned_quantity)) filter (where o.delivered_at is not null), 0) end as cogs,
           case when v_finance then coalesce(sum(oi.line_total - oi.unit_cost * (oi.quantity - oi.returned_quantity)) filter (where o.delivered_at is not null), 0) end as gross_profit,
           case when v_finance and coalesce(sum(oi.line_total) filter (where o.delivered_at is not null), 0) > 0
             then round(100 * sum(oi.line_total - oi.unit_cost * (oi.quantity - oi.returned_quantity)) filter (where o.delivered_at is not null)
                        / sum(oi.line_total) filter (where o.delivered_at is not null), 2) end as margin_pct
    from public._report_orders(p_from, p_to, p_filters) o
    join public.order_items oi on oi.order_id = o.id
    left join public.products p on p.id = oi.product_id
    left join public.categories c on c.id = p.category_id
    group by oi.product_id
    order by revenue desc
    limit least(greatest(p_limit, 1), 1000)
  ) t;
  return v;
end;

require_feature.src:
declare
  v jsonb := public.merchant_entitlements() -> p_code;
begin
  if coalesce((v ->> 'enabled')::boolean, false) then
    return;
  end if;
  raise exception 'FEATURE_OFF: % is %', coalesce(v ->> 'name', p_code),
    case v ->> 'state'
      when 'NOT_IN_PLAN' then 'not included in your plan'
      when 'DISABLED_GLOBALLY' then 'switched off for everyone right now'
      when 'DISABLED_FOR_MERCHANT' then 'switched off for your account'
      when 'BETA_NOT_ENROLLED' then 'in early access and not open to your account yet'
      else 'not available' end
    using errcode = 'P0001';
end;

require_limit.src:
declare
  v_limit numeric := nullif(public.merchant_limits() ->> p_key, '')::numeric;
  v_used numeric := (public.merchant_usage() ->> p_key)::numeric;
begin
  if v_limit is not null and v_used >= v_limit then
    raise exception 'LIMIT_REACHED: your plan allows % %; upgrade the plan or ask for an add-on', v_limit,
      replace(p_key, '_', ' ') using errcode = 'P0001';
  end if;
end;

require_permission.src:
begin
  if public.is_system_context() or public.has_permission(p_code) then
    return;
  end if;
  raise exception 'PERMISSION_DENIED: % is required', p_code using errcode = '42501';
end;

retain_order_advance.src:
declare
  v_order public.orders;
begin
  perform public.require_permission('refunds.manage');
  select * into v_order from public.orders where id = p_order_id for update;
  if v_order.status not in ('CANCELLED', 'REJECTED_FRAUD', 'RETURNED', 'FAILED_DELIVERY') or v_order.delivered_at is not null then
    raise exception 'VALIDATION: advances can only be retained on undelivered cancelled/returned orders' using errcode = '22023';
  end if;
  if v_order.amount_paid <= 0 or v_order.advance_resolution is not null then
    raise exception 'VALIDATION: there is no unresolved advance on this order' using errcode = '22023';
  end if;
  perform public._post_finance('INCOME', 'RETAINED_ADVANCES', v_order.amount_paid,
    (now() at time zone public.store_timezone())::date, false, p_order_id, v_order.customer_id, null,
    v_order.order_number, coalesce(nullif(trim(p_note), ''), 'Advance retained after cancellation/return'),
    'order:' || p_order_id || ':retained_advance', null);
  update public.orders set advance_resolution = 'RETAINED' where id = p_order_id returning * into v_order;
  perform public._order_log(p_order_id, 'ADVANCE_RETAINED', coalesce(p_note, 'Advance retained'));
  perform public.log_audit('order.advance_retained', 'order', p_order_id::text, null,
    jsonb_build_object('amount', v_order.amount_paid), jsonb_build_object('note', p_note));
  return v_order;
end;

retry_courier_webhook.src:
declare
  v_result text;
begin
  perform public.require_permission('shipments.manage');
  select result into v_result from public.courier_webhook_events where id = p_event_id for update;
  if not found then
    raise exception 'NOT_FOUND: webhook event not found' using errcode = 'P0002';
  end if;
  if v_result not in ('FAILED', 'UNMATCHED') then
    raise exception 'VALIDATION: only failed or unmatched events can be retried' using errcode = '22023';
  end if;
  return public._process_courier_webhook(p_event_id);
end;

retry_courier_webhooks.src:
declare
  v_id uuid;
  v_out jsonb;
  v_counts jsonb := '{}'::jsonb;
begin
  if not public.is_system_context() then
    raise exception 'PERMISSION_DENIED' using errcode = '42501';
  end if;
  for v_id in
    select id from public.courier_webhook_events
    where result in ('FAILED', 'UNMATCHED') and next_retry_at <= now() and attempts < 6
    order by received_at limit least(greatest(p_limit, 1), 500)
  loop
    v_out := public._process_courier_webhook(v_id);
    v_counts := v_counts || jsonb_build_object(v_out ->> 'status', coalesce((v_counts ->> (v_out ->> 'status'))::int, 0) + 1);
  end loop;
  return v_counts;
end;

retry_notification.src:
declare
  v_channel public.notification_channel;
begin
  select channel into v_channel from public.notification_logs where id = p_id;
  if not found then
    raise exception 'NOT_FOUND: message not found' using errcode = 'P0002';
  end if;
  perform public.require_permission(case when v_channel = 'SMS' then 'sms.manage' else 'settings.manage' end);
  update public.notification_logs set status = 'QUEUED', next_attempt_at = now(), attempts = 0, error = null
  where id = p_id and status in ('FAILED', 'SKIPPED');
end;

reverse_finance_transaction.src:
declare
  v_orig public.finance_transactions;
  v_row public.finance_transactions;
begin
  perform public.require_permission('finance.manage');
  if length(trim(coalesce(p_reason, ''))) = 0 then
    raise exception 'VALIDATION: a reason is required to reverse a transaction' using errcode = '22023';
  end if;
  select * into v_orig from public.finance_transactions where id = p_id;
  if not found then
    raise exception 'NOT_FOUND: transaction not found' using errcode = 'P0002';
  end if;
  if v_orig.reverses_id is not null then
    raise exception 'VALIDATION: a reversal cannot itself be reversed' using errcode = '22023';
  end if;
  if exists (select 1 from public.finance_transactions where reverses_id = p_id) then
    raise exception 'VALIDATION: this transaction has already been reversed' using errcode = '22023';
  end if;
  if v_orig.source = 'SYSTEM' and v_orig.source_key like 'order%' then
    raise exception 'VALIDATION: order-generated entries are corrected through the order (refund/return)' using errcode = '22023';
  end if;

  insert into public.finance_transactions(type, category_id, amount, txn_date, is_cash, payment_channel, reference,
    order_id, customer_id, supplier_id, purchase_order_id, notes, source, reverses_id, created_by)
  values (v_orig.type, v_orig.category_id, -v_orig.amount, (now() at time zone public.store_timezone())::date,
          v_orig.is_cash, v_orig.payment_channel, v_orig.txn_number, v_orig.order_id, v_orig.customer_id,
          v_orig.supplier_id, v_orig.purchase_order_id, 'Reversal: ' || trim(p_reason), 'MANUAL', p_id, auth.uid())
  returning * into v_row;

  perform public.log_audit('finance.entry_reversed', 'finance_transaction', p_id::text,
    jsonb_build_object('amount', v_orig.amount), jsonb_build_object('reversal', v_row.txn_number), jsonb_build_object('reason', p_reason));
  return v_row;
end;

sales_channel_settings_save.src:
declare
  v_old public.sales_channels;
  v_row public.sales_channels;
begin
  perform public.require_permission('settings.manage');
  select * into v_old from public.sales_channels where id = p_id for update;
  if not found then
    raise exception 'NOT_FOUND: sales channel not found' using errcode = 'P0002';
  end if;
  update public.sales_channels set
    name = coalesce(nullif(left(trim(p ->> 'name'), 120), ''), name),
    settings = settings || case when p ? 'import_orders' then jsonb_build_object('import_orders', coalesce((p ->> 'import_orders')::boolean, true)) else '{}'::jsonb end
  where id = p_id returning * into v_row;
  perform public.log_audit('channel.settings', 'sales_channel', p_id::text,
    jsonb_build_object('name', v_old.name, 'settings', v_old.settings), jsonb_build_object('name', v_row.name, 'settings', v_row.settings));
  return jsonb_build_object('id', v_row.id, 'name', v_row.name, 'settings', v_row.settings);
end;

scan_parcel.src:
declare
  v_code text := upper(regexp_replace(coalesce(p_code, ''), '\s', '', 'g'));
  v_action text := upper(coalesce(p_action, 'LOOKUP'));
  v_order public.orders;
  v_from public.order_status;
  v_result text := 'OK';
  v_message text;
  v_note text;
begin
  perform public.require_permission('orders.fulfill');
  if v_action not in ('READY_TO_SHIP', 'SHIPPED', 'RETURNED', 'LOOKUP') then
    raise exception 'VALIDATION: unknown scan action' using errcode = '22023';
  end if;
  if length(v_code) < 3 or length(v_code) > 64 then
    raise exception 'VALIDATION: scan a valid order or tracking barcode' using errcode = '22023';
  end if;

  select * into v_order from public.orders where upper(order_number) = v_code for update;
  if not found then
    select o.* into v_order from public.shipments s join public.orders o on o.id = s.order_id
    where s.is_active and (upper(s.tracking_number) = v_code or upper(s.consignment_id) = v_code)
    order by s.created_at desc limit 1;
    if found then
      select * into v_order from public.orders where id = v_order.id for update;
    end if;
  end if;

  if v_order.id is null then
    insert into public.parcel_scans(code, action, result, message, courier_id, scanned_by, scanned_by_name)
    values (v_code, v_action, 'NOT_FOUND', 'No order matches this barcode', p_courier_id, auth.uid(), public.actor_display_name());
    return jsonb_build_object('result', 'NOT_FOUND', 'message', 'No order matches this barcode', 'code', v_code);
  end if;

  v_from := v_order.status;
  v_note := 'Scanned at packing desk';
  begin
    if v_action = 'LOOKUP' then
      v_message := 'Found';
    elsif v_order.status in ('CANCELLED', 'REJECTED_FRAUD') then
      v_result := 'ERROR';
      v_message := 'Order is cancelled — do not ship';
    elsif v_action in ('READY_TO_SHIP', 'SHIPPED') and v_order.status = 'PENDING_CANCEL' and v_order.shipped_at is null then
      v_result := 'ERROR';
      v_message := 'A cancellation was asked for — do not ship';
    elsif v_action = 'READY_TO_SHIP' then
      if v_order.status = 'READY_TO_SHIP' then
        v_result := 'ALREADY';
        v_message := 'Already ready to ship';
      elsif v_order.shipped_at is not null then
        v_result := 'ALREADY';
        v_message := 'Already ' || replace(lower(v_order.status::text), '_', ' ');
      else
        v_order := public._scan_to_ready(v_order, v_note);
        v_message := 'Ready to ship';
      end if;
    elsif v_action = 'SHIPPED' then
      if v_order.status = 'SHIPPED' then
        v_result := 'ALREADY';
        v_message := 'Already shipped';
      elsif v_order.shipped_at is not null then
        v_result := 'ALREADY';
        v_message := 'Already ' || replace(lower(v_order.status::text), '_', ' ');
      else
        if v_order.status <> 'READY_TO_SHIP' then
          v_order := public._scan_to_ready(v_order, v_note);
        end if;
        if p_courier_id is not null
           and not exists (select 1 from public.shipments where order_id = v_order.id and is_active) then
          perform public.assign_courier(v_order.id, p_courier_id, null, null, 'Assigned at packing desk');
        end if;
        v_order := public._transition_order(v_order.id, 'SHIPPED', 'Handed to courier (scanned)');
        v_message := 'Shipped';
      end if;
    elsif v_action = 'RETURNED' then
      if v_order.status = 'RETURNED' then
        v_result := 'ALREADY';
        v_message := 'Already received back';
      elsif v_order.status = 'SHIPPED' then
        v_order := public._transition_order(v_order.id, 'RETURNING', 'Parcel came back (scanned)');
        v_order := public._transition_order(v_order.id, 'RETURNED', 'Returned parcel received (scanned)');
        v_message := 'Returned to stock';
      elsif v_order.status in ('DELIVERED', 'PARTIALLY_DELIVERED') then
        v_result := 'ERROR';
        v_message := 'Delivered — final, it cannot be returned. Adjust stock by hand if the item really came back';
      elsif v_order.status in ('FAILED_DELIVERY', 'RETURN_REQUESTED', 'RETURNING', 'LOST')
         or (v_order.status = 'PENDING_CANCEL' and v_order.shipped_at is not null) then
        v_order := public._transition_order(v_order.id, 'RETURNED', 'Returned parcel received (scanned)');
        v_message := 'Returned to stock';
      else
        v_result := 'ERROR';
        v_message := 'This order has not been shipped';
      end if;
    end if;
  exception when others then
    v_result := 'ERROR';
    v_message := regexp_replace(sqlerrm, '^[A-Z_]+: ', '');
    select * into v_order from public.orders where id = v_order.id;
  end;

  insert into public.parcel_scans(code, action, order_id, order_number, result, message, from_status, to_status,
                                  courier_id, scanned_by, scanned_by_name)
  values (v_code, v_action, v_order.id, v_order.order_number, v_result, v_message, v_from,
          case when v_order.status <> v_from then v_order.status end, p_courier_id, auth.uid(), public.actor_display_name());
  if v_action <> 'LOOKUP' then
    perform public._order_log(v_order.id, 'PARCEL_SCANNED',
      format('Scanned for %s: %s', replace(lower(v_action), '_', ' '), v_message), null, null,
      jsonb_build_object('action', v_action, 'result', v_result, 'code', v_code));
  end if;

  return jsonb_build_object('result', v_result, 'message', v_message, 'code', v_code,
    'from_status', v_from, 'order', public._scan_summary(v_order.id));
end;

set_courier_invoice_status.src:
declare
  v_inv public.courier_invoices;
  v_old public.courier_invoice_status;
  v_settled numeric;
begin
  perform public.require_permission(case when p_status = 'PAID' then 'payments.record' else 'couriers.manage' end);
  select * into v_inv from public.courier_invoices where id = p_invoice_id for update;
  if not found then
    raise exception 'NOT_FOUND: statement not found' using errcode = 'P0002';
  end if;
  v_old := v_inv.status;
  if v_old = 'PAID' then
    raise exception 'VALIDATION: a paid statement cannot be changed' using errcode = '22023';
  end if;
  if p_amount_paid is not null and p_amount_paid < 0 then
    raise exception 'VALIDATION: amount paid cannot be negative' using errcode = '22023';
  end if;
  if p_status in ('VERIFIED', 'PAID') then
    perform public._apply_invoice_charges(p_invoice_id);
  end if;
  if p_status = 'PAID' then
    v_settled := public._settle_invoice_cod(p_invoice_id);
  end if;
  update public.courier_invoices set status = p_status,
    notes = coalesce(nullif(trim(p_note), ''), notes),
    amount_paid = case when p_status = 'PAID' then coalesce(p_amount_paid, payout_reported) else amount_paid end,
    paid_at = case when p_status = 'PAID' then now() else paid_at end,
    paid_reference = case when p_status = 'PAID' then nullif(trim(p_reference), '') else paid_reference end,
    reviewed_by = auth.uid(), reviewed_at = now()
  where id = p_invoice_id
  returning * into v_inv;
  perform public.log_audit('courier_invoice.status', 'courier_invoice', p_invoice_id::text,
    jsonb_build_object('status', v_old), jsonb_build_object('status', p_status, 'cod_settled', v_settled), null);
  return v_inv;
end;

