sms_update_settings.src:
declare
  v_patch jsonb := '{}'::jsonb;
  v_value jsonb;
begin
  perform public.require_permission('sms.manage');
  if p_sender_id is not null then
    raise exception 'VALIDATION: the sender ID is set by the platform; ask support to change it' using errcode = '22023';
  end if;
  if p_enabled is not null then
    if p_enabled then
      perform public.require_feature('sms');
      if public._platform_sms_provider() is null then
        raise exception 'VALIDATION: SMS is not available on the platform right now' using errcode = '22023';
      end if;
    end if;
    v_patch := v_patch || jsonb_build_object('enabled', p_enabled);
  end if;
  if p_cost_per_sms is not null then
    if p_cost_per_sms < 0 or p_cost_per_sms > 20 then
      raise exception 'VALIDATION: the cost per SMS must be between 0 and 20' using errcode = '22023';
    end if;
    v_patch := v_patch || jsonb_build_object('cost_per_sms', round(p_cost_per_sms, 4));
  end if;
  if p_currency_text is not null then
    if length(trim(p_currency_text)) > 6 then
      raise exception 'VALIDATION: the currency text can be up to 6 characters' using errcode = '22023';
    end if;
    v_patch := v_patch || jsonb_build_object('currency_text', trim(p_currency_text));
  end if;
  update public.settings set value = value || v_patch, updated_by = auth.uid()
  where key = 'sms' returning value into v_value;
  perform public.log_audit('sms.settings_changed', 'settings', 'sms', null, v_patch);
  return v_value;
end;

start_order_payment.src:
declare
  v_order public.orders;
  v_amount numeric;
  v_payment public.payments;
begin
  if not public.is_system_context() then
    raise exception 'PERMISSION_DENIED' using errcode = '42501';
  end if;
  select * into v_order from public.orders
  where order_number = upper(trim(p_order_number)) and customer_phone = public.clean_phone(p_phone)
  for update;
  if not found then
    raise exception 'NOT_FOUND: order not found' using errcode = 'P0002';
  end if;
  if v_order.status in ('CANCELLED', 'REJECTED_FRAUD', 'RETURNED', 'DELIVERED', 'PARTIALLY_DELIVERED', 'FAILED_DELIVERY',
                        'RETURNING', 'LOST', 'PENDING_CANCEL') then
    raise exception 'VALIDATION: this order no longer accepts payments' using errcode = '22023';
  end if;

  v_amount := case p_purpose
    when 'ADVANCE' then v_order.advance_required - v_order.amount_paid
    else v_order.total_amount - v_order.amount_paid end;
  if v_amount <= 0 then
    raise exception 'VALIDATION: nothing is due on this order' using errcode = '22023';
  end if;

  select * into v_payment from public.payments
  where order_id = v_order.id and provider = p_provider and purpose = p_purpose and status = 'PENDING'
    and amount = public.money(v_amount) and (expires_at is null or expires_at > now())
  order by created_at desc limit 1;
  if found then
    return v_payment;
  end if;

  insert into public.payments(order_id, provider, purpose, amount, currency, channel, payer_phone, expires_at)
  values (v_order.id, p_provider, p_purpose, public.money(v_amount),
          public.setting_text('store', array['currency'], 'BDT'), p_channel, v_order.customer_phone,
          now() + interval '2 hours')
  returning * into v_payment;
  return v_payment;
end;

store_domain_save.src:
declare
  v_row public.store_domains;
  v_next uuid;
begin
  perform public._require_system();
  insert into public.store_domains(domain, status, records, detail, diagnostics, created_by, checked_at, is_primary)
  values (lower(p_domain), coalesce(p ->> 'status', 'PENDING'), coalesce(p -> 'records', '[]'::jsonb), p ->> 'detail', p -> 'diagnostics', p_actor, now(),
          coalesce(p ->> 'status', 'PENDING') <> 'REMOVED'
            and not exists (select 1 from public.store_domains x where x.is_primary and x.status <> 'REMOVED'))
  on conflict (domain) do update set
    status = coalesce(p ->> 'status', store_domains.status), records = coalesce(p -> 'records', store_domains.records),
    detail = case when p ? 'detail' then p ->> 'detail' else store_domains.detail end,
    diagnostics = case when p ? 'diagnostics' then p -> 'diagnostics' else store_domains.diagnostics end,
    -- Added again after removal: primary again only if the business has none.
    is_primary = case when coalesce(p ->> 'status', store_domains.status) = 'REMOVED' then false
                      when store_domains.status = 'REMOVED' then not exists (select 1 from public.store_domains x where x.is_primary and x.status <> 'REMOVED' and x.id <> store_domains.id)
                      else store_domains.is_primary end,
    checked_at = now()
  returning * into v_row;
  -- The primary domain was removed: the oldest remaining (live first) takes over.
  if v_row.status = 'REMOVED' and not exists (select 1 from public.store_domains x where x.is_primary and x.status <> 'REMOVED') then
    select id into v_next from public.store_domains where status <> 'REMOVED' order by (status = 'ACTIVE') desc, created_at, id limit 1;
    if v_next is not null then
      update public.store_domains set is_primary = true where id = v_next;
    end if;
  end if;
  if p_actor is not null then
    perform public.log_audit('store_domain.' || lower(v_row.status), 'store_domain', v_row.id::text, null,
      jsonb_build_object('domain', v_row.domain, 'status', v_row.status));
  end if;
  return to_jsonb(v_row);
end;

store_domain_set_primary.src:
declare
  v_row public.store_domains;
  v_old text;
begin
  perform public.require_permission('settings.manage');
  select * into v_row from public.store_domains where domain = lower(trim(coalesce(p_domain, ''))) and status <> 'REMOVED' for update;
  if not found then
    raise exception 'NOT_FOUND: that domain is not connected to this store' using errcode = 'P0002';
  end if;
  if v_row.is_primary then
    return to_jsonb(v_row);
  end if;
  select domain into v_old from public.store_domains where is_primary and status <> 'REMOVED';
  update public.store_domains set is_primary = false where is_primary and status <> 'REMOVED';
  update public.store_domains set is_primary = true where id = v_row.id returning * into v_row;
  perform public.log_audit('store_domain.primary', 'store_domain', v_row.id::text,
    jsonb_build_object('primary', v_old), jsonb_build_object('primary', v_row.domain));
  return to_jsonb(v_row);
end;

