storefront_cart_sync.src:
declare
  v_lines jsonb;
  v_count int;
  v_subtotal numeric;
  v_cart public.store_carts;
  v_customer public.customers;
  v_source text;
  v_attr jsonb := case when jsonb_typeof(p_attribution) = 'object' and length(p_attribution::text) <= 20000 then p_attribution end;
begin
  if not public.feature_enabled('abandoned_carts') then
    return null;
  end if;
  if not public.setting_bool('orders', array['track_carts'], true)
     or p_visitor_id is null or p_visitor_id !~ '^[A-Za-z0-9_-]{8,64}$'
     or jsonb_typeof(coalesce(p_items, 'null'::jsonb)) <> 'array' or jsonb_array_length(p_items) > 50 then
    return null;
  end if;

  select * into v_cart from public.store_carts where visitor_id = p_visitor_id and status = 'ACTIVE';
  -- At most one write per second per visitor.
  if v_cart.id is not null and v_cart.last_activity_at > now() - interval '1 second' then
    return v_cart.id;
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
      'variant_id', v.id, 'product_id', p.id, 'name', p.name,
      'variant', case when v.title is null or v.title = 'Default' then null else v.title end,
      'sku', v.sku, 'quantity', x.quantity, 'unit_price', coalesce(v.price, p.price),
      'image', (select i.url from public.product_images i where i.product_id = p.id order by (i.variant_id = v.id) desc nulls last, i.is_primary desc, i.position limit 1))
      order by x.ord), '[]'::jsonb),
    coalesce(sum(x.quantity), 0), coalesce(sum(x.quantity * coalesce(v.price, p.price)), 0)
  into v_lines, v_count, v_subtotal
  from (
    select distinct on (e ->> 'variant_id') (e ->> 'variant_id')::uuid as variant_id,
      least(greatest(coalesce((e ->> 'quantity')::int, 1), 1), 100) as quantity, ord
    from jsonb_array_elements(p_items) with ordinality as t(e, ord)
    where coalesce(e ->> 'variant_id', '') ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' and coalesce(e ->> 'quantity', '1') ~ '^[0-9]{1,3}$'
    order by e ->> 'variant_id', ord
  ) x
  join public.product_variants v on v.id = x.variant_id and v.is_active
  join public.products p on p.id = v.product_id and p.status = 'ACTIVE';

  if v_count = 0 then
    if v_cart.id is not null then
      update public.store_carts set status = 'EMPTIED', items = '[]'::jsonb, item_count = 0, subtotal = 0,
        last_activity_at = now(), updated_at = now()
      where id = v_cart.id;
    end if;
    return null;
  end if;

  if auth.uid() is not null then
    select * into v_customer from public.customers where auth_user_id = auth.uid() limit 1;
  end if;
  v_source := case when jsonb_typeof(v_attr -> 'last_touch') = 'object' then public.classify_touch(v_attr -> 'last_touch') ->> 'source' end;

  insert into public.store_carts(visitor_id, session_id, items, item_count, subtotal, customer_user_id, customer_id, phone, customer_name, source, attribution)
  values (p_visitor_id, left(p_session_id, 64), v_lines, v_count, v_subtotal, auth.uid(), v_customer.id, v_customer.phone, v_customer.full_name,
    coalesce(v_source, 'Direct'), v_attr)
  on conflict (merchant_id, visitor_id) where status = 'ACTIVE' do update set
    session_id = coalesce(excluded.session_id, public.store_carts.session_id),
    items = excluded.items, item_count = excluded.item_count, subtotal = excluded.subtotal,
    customer_user_id = coalesce(excluded.customer_user_id, public.store_carts.customer_user_id),
    customer_id = coalesce(excluded.customer_id, public.store_carts.customer_id),
    phone = coalesce(public.store_carts.phone, excluded.phone),
    customer_name = coalesce(public.store_carts.customer_name, excluded.customer_name),
    source = case when v_source is not null then excluded.source else public.store_carts.source end,
    attribution = coalesce(excluded.attribution, public.store_carts.attribution),
    last_activity_at = now(), updated_at = now()
  returning * into v_cart;
  return v_cart.id;
end;

storefront_quote.src:
declare
  v jsonb;
begin
  v := public.calculate_order_quote(p_items, p_district, p_area, p_delivery_method, p_coupon_code, p_phone, false, false);
  -- Hide cost data from the public response.
  return (v - 'cost_total') || jsonb_build_object(
    'lines', (select coalesce(jsonb_agg(l - 'unit_cost'), '[]'::jsonb) from jsonb_array_elements(v -> 'lines') l));
end;

storefront_resolve.src:
declare
  v_host text := regexp_replace(lower(trim(coalesce(p_host, ''))), ':[0-9]+$', '');
  v_id uuid;
  v_m public.merchants;
  v_primary text;
  v_root text := public._store_root_domain();
  v_sub text;
  v_main text := coalesce((select value ->> 'main_site' from public.platform_settings where key = 'store_domains'), 'store');
begin
  if v_host <> '' then
    select merchant_id into v_id from public.store_domains
    where domain in (v_host, regexp_replace(v_host, '^www\.', ''), 'www.' || v_host) and status <> 'REMOVED'
    order by (domain = v_host) desc limit 1;
    if v_id is not null then
      select domain into v_primary from public.store_domains
      where merchant_id = v_id and is_primary and status = 'ACTIVE' and domain <> v_host;
    end if;
  end if;

  if v_id is null and v_root is not null and v_host like '%.' || v_root then
    v_sub := left(v_host, length(v_host) - length(v_root) - 1);
    if v_sub not in ('www', 'app') and position('.' in v_sub) = 0 then
      select m.* into v_m from public.merchants m
      where m.slug = v_sub and m.status <> 'CLOSED'
        and coalesce((select s.value ->> 'mode' from public.settings s where s.merchant_id = m.id and s.key = 'storefront'), 'OWN') = 'OWN';
      if v_m.id is null then
        return jsonb_build_object('kind', 'missing');
      end if;
      return public._store_json(v_m);
    end if;
  end if;

  if v_id is null then
    if v_main = 'marketing' then
      return jsonb_build_object('kind', 'platform');
    end if;
    select nullif(value ->> 'default_merchant_id', '')::uuid into v_id from public.platform_settings where key = 'storefront';
  end if;
  select * into v_m from public.merchants where id = v_id and status <> 'CLOSED';
  if v_m.id is null then
    return case when v_main = 'marketing' then jsonb_build_object('kind', 'platform') end;
  end if;
  return public._store_json(v_m, v_primary);
end;

storefront_resolve_preview.src:
declare
  v_m public.merchants;
begin
  if not public.is_staff() then
    raise exception 'PERMISSION_DENIED: staff only' using errcode = '42501';
  end if;
  select * into v_m from public.merchants where id = public.current_merchant_id();
  if v_m.id is null then
    return jsonb_build_object('kind', 'missing');
  end if;
  return public._store_json(v_m);
end;

storefront_resolve_slug.src:
declare
  v_m public.merchants;
begin
  select * into v_m from public.merchants where slug = lower(trim(coalesce(p_slug, ''))) and status <> 'CLOSED';
  if v_m.id is null
     or coalesce((select s.value ->> 'mode' from public.settings s where s.merchant_id = v_m.id and s.key = 'storefront'), 'OWN') <> 'OWN' then
    return jsonb_build_object('kind', 'missing');
  end if;
  return public._store_json(v_m);
end;

submit_contact_message.src:
begin
  if length(trim(coalesce(p_name, ''))) < 2 or length(trim(coalesce(p_message, ''))) < 5 then
    raise exception 'VALIDATION: please enter your name and a message' using errcode = '22023';
  end if;
  if coalesce(p_phone, '') = '' and coalesce(p_email, '') = '' then
    raise exception 'VALIDATION: please enter a phone number or email so we can reply' using errcode = '22023';
  end if;
  insert into public.contact_messages(name, phone, email, subject, message)
  values (trim(p_name), nullif(public.clean_phone(p_phone), ''), nullif(lower(trim(coalesce(p_email, ''))), ''),
          nullif(trim(coalesce(p_subject, '')), ''), trim(p_message));
end;

submit_manual_payment.src:
declare
  v_order public.orders;
  v_payment public.payments;
  v_txn text := upper(regexp_replace(coalesce(p_transaction_id, ''), '\s', '', 'g'));
begin
  if not public.is_system_context() then
    raise exception 'PERMISSION_DENIED' using errcode = '42501';
  end if;
  if v_txn !~ '^[A-Z0-9]{6,30}$' then
    raise exception 'VALIDATION: enter the transaction ID from your payment SMS' using errcode = '22023';
  end if;
  if p_channel not in ('BKASH', 'NAGAD', 'ROCKET', 'BANK_TRANSFER', 'OTHER') then
    raise exception 'VALIDATION: unsupported payment method' using errcode = '22023';
  end if;
  select * into v_order from public.orders
  where order_number = upper(trim(p_order_number)) and customer_phone = public.clean_phone(p_phone);
  if not found then
    raise exception 'NOT_FOUND: order not found' using errcode = 'P0002';
  end if;
  if v_order.status in ('CANCELLED', 'REJECTED_FRAUD', 'RETURNED', 'DELIVERED') then
    raise exception 'VALIDATION: this order no longer accepts payments' using errcode = '22023';
  end if;
  if exists (select 1 from public.payments where provider = 'manual' and provider_transaction_id = v_txn
             and status not in ('FAILED', 'CANCELLED')) then
    raise exception 'DUPLICATE: this transaction ID has already been submitted' using errcode = '23505';
  end if;
  if coalesce(p_amount, 0) <= 0 then
    raise exception 'VALIDATION: enter the amount you sent' using errcode = '22023';
  end if;

  insert into public.payments(order_id, provider, purpose, amount, currency, status, provider_transaction_id,
                              channel, payer_phone, metadata)
  values (v_order.id, 'manual',
          case when v_order.advance_required > v_order.amount_paid and p_amount < v_order.total_amount - v_order.amount_paid
               then 'ADVANCE' else 'FULL' end::public.payment_purpose,
          public.money(p_amount), public.setting_text('store', array['currency'], 'BDT'), 'REQUIRES_VERIFICATION',
          v_txn, p_channel, public.clean_phone(p_sender_phone),
          jsonb_build_object('submitted_at', now()))
  returning * into v_payment;

  perform public._order_log(v_order.id, 'PAYMENT_SUBMITTED',
    format('Customer reported %s %s payment (TrxID %s) — awaiting verification', p_amount, p_channel, v_txn),
    null, null, jsonb_build_object('payment_id', v_payment.id), true);
  return v_payment;
end;

support_access_log.src:
begin
  perform public.require_permission('audit.view');
  return coalesce((
    select jsonb_agg(jsonb_build_object('id', s.id, 'mode', s.mode, 'reason', s.reason,
        -- First name only: enough to recognise, without exposing the employee's details.
        'staff', coalesce((select split_part(coalesce(nullif(trim(ps.full_name), ''), split_part(ps.email, '@', 1)), ' ', 1) from public.platform_staff ps
                           where ps.user_id = s.staff_user_id), 'Platform support'),
        'ticket_number', (select t.number from public.support_tickets t where t.id = s.ticket_id and not t.internal),
        'started_at', s.started_at, 'ended_at', least(coalesce(s.ended_at, s.expires_at), greatest(now(), s.started_at)),
        'active', s.ended_at is null and s.expires_at > now()) order by s.started_at desc)
    from (select * from public.support_sessions s where s.merchant_id = public.current_merchant_id()
          order by s.started_at desc limit least(greatest(coalesce(p_limit, 50), 1), 200)) s), '[]'::jsonb);
end;

support_ticket_create.src:
declare
  v_row public.support_tickets;
  v_kind text := upper(coalesce(p ->> 'kind', ''));
  v_name text;
begin
  if not public.is_staff() then
    raise exception 'PERMISSION_DENIED: staff only' using errcode = '42501';
  end if;
  if v_kind not in ('BUG', 'FEEDBACK') then
    raise exception 'VALIDATION: choose bug report or feedback' using errcode = '22023';
  end if;
  if length(trim(coalesce(p ->> 'subject', ''))) < 3 then
    raise exception 'VALIDATION: add a short title' using errcode = '22023';
  end if;
  if length(trim(coalesce(p ->> 'body', ''))) < 5 then
    raise exception 'VALIDATION: describe it in a few words' using errcode = '22023';
  end if;
  if (select count(*) from public.support_tickets where created_by = auth.uid() and created_at > now() - interval '1 hour') >= 20 then
    raise exception 'VALIDATION: too many reports in the last hour — try again later' using errcode = '22023';
  end if;
  insert into public.support_tickets(kind, category, subject, body, rating, priority, context, created_by)
  values (v_kind, upper(coalesce(nullif(p ->> 'category', ''), 'GENERAL')), left(trim(p ->> 'subject'), 140), left(trim(p ->> 'body'), 4000),
    case when v_kind = 'FEEDBACK' then nullif(p ->> 'rating', '')::int end,
    case when v_kind = 'BUG' and upper(coalesce(p ->> 'priority', '')) in ('LOW', 'NORMAL', 'HIGH', 'URGENT') then upper(p ->> 'priority') else 'NORMAL' end,
    jsonb_strip_nulls(jsonb_build_object('page', left(p #>> '{context,page}', 300), 'browser', left(p #>> '{context,browser}', 300),
      'screen', left(p #>> '{context,screen}', 40), 'version', left(p #>> '{context,version}', 60))),
    auth.uid())
  returning * into v_row;
  if v_kind = 'BUG' then
    select coalesce(nullif(trim(full_name), ''), email) into v_name from public.profiles where id = auth.uid();
    perform public._log_system_event('WARN', 'OTHER', 'staff-report',
      left(format('Bug #%s by %s: %s', v_row.number, coalesce(v_name, 'staff'), v_row.subject), 2000),
      jsonb_build_object('ticket_id', v_row.id, 'page', v_row.context ->> 'page', 'user_id', auth.uid()));
  end if;
  return v_row;
end;

support_ticket_reply.src:
declare
  v_t public.support_tickets;
  v_support boolean := public.has_permission('support.manage');
  v_row public.support_ticket_messages;
begin
  select * into v_t from public.support_tickets where id = p_id for update;
  if v_t.id is null or v_t.internal or not (v_t.created_by = auth.uid() or v_support) or not public.is_staff() then
    raise exception 'NOT_FOUND: ticket not found' using errcode = 'P0002';
  end if;
  if length(trim(coalesce(p_body, ''))) < 1 then
    raise exception 'VALIDATION: write a reply' using errcode = '22023';
  end if;
  insert into public.support_ticket_messages(ticket_id, author_id, body, is_support)
  values (p_id, auth.uid(), left(trim(p_body), 4000), false)
  returning * into v_row;
  update public.support_tickets set replies = replies + 1, last_reply_at = now(), last_reply_by = auth.uid(),
    -- The merchant writing again reopens a resolved ticket.
    status = case when status in ('RESOLVED', 'CLOSED') then 'OPEN' else status end,
    resolved_at = case when status in ('RESOLVED', 'CLOSED') then null else resolved_at end
  where id = p_id;
  return v_row;
end;

support_ticket_update.src:
declare
  v_t public.support_tickets;
  v_support boolean := public.has_permission('support.manage');
  v_status text := upper(nullif(p ->> 'status', ''));
  v_priority text := upper(nullif(p ->> 'priority', ''));
  v_row public.support_tickets;
begin
  select * into v_t from public.support_tickets where id = p_id for update;
  if v_t.id is null or not (v_t.created_by = auth.uid() or v_support) or not public.is_staff() then
    raise exception 'NOT_FOUND: ticket not found' using errcode = 'P0002';
  end if;
  if v_status is not null and v_status not in ('OPEN', 'IN_PROGRESS', 'RESOLVED', 'CLOSED') then
    raise exception 'VALIDATION: unknown status' using errcode = '22023';
  end if;
  if v_priority is not null and v_priority not in ('LOW', 'NORMAL', 'HIGH', 'URGENT') then
    raise exception 'VALIDATION: unknown priority' using errcode = '22023';
  end if;
  -- The reporter can only close or reopen their own ticket.
  if not v_support and (v_priority is not null or (v_status is not null and v_status not in ('CLOSED', 'OPEN'))) then
    raise exception 'PERMISSION_DENIED: support.manage is required' using errcode = '42501';
  end if;
  update public.support_tickets set
    status = coalesce(v_status, status),
    priority = coalesce(v_priority, priority),
    resolved_at = case when coalesce(v_status, status) in ('RESOLVED', 'CLOSED') then coalesce(resolved_at, now()) else null end
  where id = p_id returning * into v_row;
  perform public.log_audit('support.update', 'support_ticket', p_id::text,
    jsonb_build_object('status', v_t.status, 'priority', v_t.priority), jsonb_build_object('status', v_row.status, 'priority', v_row.priority));
  return v_row;
end;

system_status.src:
declare
  v jsonb := '[]'::jsonb;
  v_n1 bigint;
  v_n2 bigint;
  v_at timestamptz;
  v_cron jsonb;
begin
  perform public.require_permission('settings.view');

  v := v || jsonb_build_object('key', 'database', 'name', 'Database', 'status', 'ok', 'detail', 'Responding', 'at', now());

  select count(*) filter (where status = 'FAILED' and updated_at > now() - interval '24 hours'),
         count(*) filter (where status = 'PENDING' and next_attempt_at < now() - interval '15 minutes'),
         max(done_at)
    into v_n1, v_n2, v_at from public.channel_sync_jobs;
  v := v || jsonb_build_object('key', 'store_sync', 'name', 'Store sync jobs',
    'status', case when v_n2 > 0 then 'warn' when v_n1 > 0 then 'warn' else 'ok' end,
    'detail', case when v_n2 > 0 then format('%s job(s) overdue', v_n2) when v_n1 > 0 then format('%s failed in 24 h', v_n1) else 'Running normally' end,
    'at', v_at);

  select count(*) filter (where status in ('ERROR')), max(last_sync_at) into v_n1, v_at
  from public.sales_channels where status <> 'DISCONNECTED';
  v := v || jsonb_build_object('key', 'channels', 'name', 'Connected stores',
    'status', case when v_n1 > 0 then 'down' when v_at is null then 'idle' else 'ok' end,
    'detail', case when v_n1 > 0 then format('%s store(s) with errors', v_n1) when v_at is null then 'No store connected' else 'Connected' end,
    'at', v_at);

  select count(*) filter (where result = 'FAILED' and received_at > now() - interval '24 hours'), max(received_at) into v_n1, v_at
  from public.courier_webhook_events;
  v := v || jsonb_build_object('key', 'courier_webhooks', 'name', 'Courier webhooks',
    'status', case when v_n1 > 0 then 'warn' when v_at is null then 'idle' else 'ok' end,
    'detail', case when v_n1 > 0 then format('%s failed in 24 h', v_n1) when v_at is null then 'Nothing received yet' else 'Receiving updates' end,
    'at', v_at);

  select count(*) filter (where status = 'FAILED' and created_at > now() - interval '24 hours'),
         count(*) filter (where status = 'QUEUED' and next_attempt_at < now() - interval '15 minutes'),
         max(sent_at)
    into v_n1, v_n2, v_at from public.notification_logs;
  v := v || jsonb_build_object('key', 'messages', 'name', 'SMS & notifications',
    'status', case when v_n2 > 0 then 'warn' when v_n1 > 0 then 'warn' when v_at is null then 'idle' else 'ok' end,
    'detail', case when v_n2 > 0 then format('%s message(s) waiting too long', v_n2) when v_n1 > 0 then format('%s failed in 24 h', v_n1)
      when v_at is null then 'Nothing sent yet' else 'Sending' end,
    'at', v_at);

  select count(*) filter (where created_at > now() - interval '24 hours'), max(created_at) into v_n1, v_at from public.payment_events;
  v := v || jsonb_build_object('key', 'payments', 'name', 'Payment gateways',
    'status', case when v_at is null then 'idle' else 'ok' end,
    'detail', case when v_at is null then 'No gateway events yet' else format('%s event(s) in 24 h', v_n1) end, 'at', v_at);

  select count(*) filter (where level = 'ERROR' and resolved_at is null and last_seen_at > now() - interval '24 hours'),
         max(last_seen_at) filter (where level = 'ERROR')
    into v_n1, v_at from public.system_logs;
  v := v || jsonb_build_object('key', 'errors', 'name', 'Application errors',
    'status', case when v_n1 > 0 then 'warn' else 'ok' end,
    'detail', case when v_n1 > 0 then format('%s unresolved error(s) in 24 h', v_n1) else 'No unresolved errors in 24 h' end, 'at', v_at);

  -- A rare "job startup timeout" is retried by the next run; warn only when
  -- a job's latest run failed or failures are more than 1 in 20.
  v_cron := public._cron_health();
  if v_cron is not null then
    v := v || jsonb_build_object('key', 'cron', 'name', 'Scheduled tasks',
      'status', case when (v_cron ->> 'latest_failed')::int > 0 or (v_cron ->> 'failed')::int * 20 > (v_cron ->> 'runs')::int then 'warn'
        when v_cron ->> 'last' is null then 'idle' else 'ok' end,
      'detail', case when v_cron ->> 'last' is null then 'No runs in 24 h'
        when (v_cron ->> 'failed')::int > 0 then format('%s of %s runs failed in 24 h — each was retried on its next run', v_cron ->> 'failed', v_cron ->> 'runs')
        else format('%s runs in 24 h, all on schedule', v_cron ->> 'runs') end,
      'at', v_cron ->> 'last');
  end if;

  return jsonb_build_object('checked_at', now(), 'components', v);
end;

track_order.src:
declare
  v_order public.orders;
begin
  select * into v_order from public.orders
  where order_number = upper(trim(coalesce(p_order_number, '')))
    and customer_phone = public.clean_phone(p_phone);
  if not found then
    return null;
  end if;
  return public._order_public_json(v_order);
end;

track_storefront_event.src:
begin
  if p_session_id is null or length(p_session_id) not between 8 and 64 then
    return;
  end if;
  -- One page view per session per minute keeps the table small.
  if p_event_type = 'PAGE_VIEW' and exists (
    select 1 from public.storefront_events
    where session_id = p_session_id and event_type = 'PAGE_VIEW' and created_at > now() - interval '1 minute') then
    return;
  end if;
  insert into public.storefront_events(session_id, event_type, product_id, utm_source, utm_campaign)
  values (p_session_id, p_event_type, p_product_id, left(p_utm_source, 100), left(p_utm_campaign, 100));
end;

track_visit_event.src:
begin
  if p_session_id is null or length(p_session_id) not between 8 and 64
     or p_visitor_id is null or length(p_visitor_id) not between 8 and 64
     or p_event_type not in ('PAGE_VIEW', 'VIEW_PRODUCT', 'ADD_TO_CART', 'BEGIN_CHECKOUT', 'PURCHASE') then
    return;
  end if;
  -- One page view per visit per page per minute keeps the table small.
  if p_event_type = 'PAGE_VIEW' and exists (
    select 1 from public.storefront_events
    where session_id = p_session_id and event_type = 'PAGE_VIEW' and page_path is not distinct from left(p_page, 300)
      and created_at > now() - interval '1 minute') then
    return;
  end if;
  insert into public.storefront_events(session_id, visitor_id, event_type, product_id, page_path)
  values (p_session_id, p_visitor_id, p_event_type, p_product_id, left(p_page, 300));
end;

transition_order_status.src:
declare
  v_order public.orders;
  v_before public.order_status;
begin
  perform public.require_permission(case when p_to in ('CANCELLED', 'PENDING_CANCEL') then 'orders.cancel' else 'orders.status' end);
  select status into v_before from public.orders where id = p_order_id;
  if p_to = 'REJECTED_FRAUD' or (v_before in ('FRAUD_REVIEW', 'REJECTED_FRAUD') and p_to <> 'CANCELLED') then
    perform public.require_permission('fraud.review');
  end if;
  if p_to = 'CONFIRMED' and v_before in ('ADVANCE_REQUIRED', 'FRAUD_REVIEW') then
    perform public.require_permission('fraud.review');
  end if;
  if p_to in ('CANCELLED', 'PENDING_CANCEL') and length(trim(coalesce(p_note, ''))) = 0 then
    raise exception 'VALIDATION: a cancellation reason is required' using errcode = '22023';
  end if;
  if p_to = 'PARTIALLY_DELIVERED' then
    raise exception 'VALIDATION: record which items came back to mark a partial delivery' using errcode = '22023';
  end if;
  v_order := public._transition_order(p_order_id, p_to, p_note);
  perform public.log_audit('order.status_changed', 'order', p_order_id::text,
    jsonb_build_object('status', v_before), jsonb_build_object('status', p_to), jsonb_build_object('note', p_note));
  return v_order;
end;

update_my_profile.src:
declare
  v_profile public.profiles;
begin
  if length(trim(coalesce(p_full_name, ''))) = 0 then
    raise exception 'VALIDATION: name is required' using errcode = '22023';
  end if;
  update public.profiles
  set full_name = trim(p_full_name), phone = nullif(trim(coalesce(p_phone, '')), ''), last_seen_at = now()
  where id = auth.uid()
  returning * into v_profile;
  if not found then
    raise exception 'NOT_FOUND: no staff profile for current user' using errcode = 'P0002';
  end if;
  return v_profile;
end;

update_shipment.src:
declare
  v_old public.shipments;
  v_ship public.shipments;
begin
  perform public.require_permission('shipments.manage');
  select * into v_old from public.shipments where id = p_shipment_id for update;
  if not found then
    raise exception 'NOT_FOUND: shipment not found' using errcode = 'P0002';
  end if;
  if (p_changes ->> 'shipping_cost')::numeric < 0 or (p_changes ->> 'return_charge')::numeric < 0 then
    raise exception 'VALIDATION: charges cannot be negative' using errcode = '22023';
  end if;
  update public.shipments set
    tracking_number = case when p_changes ? 'tracking_number' then nullif(trim(p_changes ->> 'tracking_number'), '') else tracking_number end,
    consignment_id = case when p_changes ? 'consignment_id' then nullif(trim(p_changes ->> 'consignment_id'), '') else consignment_id end,
    shipping_cost = coalesce((p_changes ->> 'shipping_cost')::numeric, shipping_cost),
    return_charge = coalesce((p_changes ->> 'return_charge')::numeric, return_charge),
    notes = case when p_changes ? 'notes' then nullif(trim(p_changes ->> 'notes'), '') else notes end,
    status = case when status = 'PENDING' and nullif(trim(coalesce(p_changes ->> 'tracking_number', '')), '') is not null
                  then 'BOOKED' else status end
  where id = p_shipment_id returning * into v_ship;
  perform public.log_audit('shipment.updated', 'shipment', p_shipment_id::text,
    jsonb_build_object('tracking_number', v_old.tracking_number, 'shipping_cost', v_old.shipping_cost, 'return_charge', v_old.return_charge),
    jsonb_build_object('tracking_number', v_ship.tracking_number, 'shipping_cost', v_ship.shipping_cost, 'return_charge', v_ship.return_charge));
  return v_ship;
end;

verify_manual_payment.src:
declare
  v_payment public.payments;
begin
  perform public.require_permission('payments.verify');
  select * into v_payment from public.payments where id = p_payment_id for update;
  if not found then
    raise exception 'NOT_FOUND: payment not found' using errcode = 'P0002';
  end if;
  if v_payment.status <> 'REQUIRES_VERIFICATION' then
    raise exception 'VALIDATION: payment is % and cannot be verified', v_payment.status using errcode = '22023';
  end if;
  if p_approve then
    perform public._settle_payment(p_payment_id, v_payment.amount);
  else
    update public.payments set status = 'FAILED', failure_reason = coalesce(p_note, 'Rejected during verification'),
      verified_by = auth.uid(), verified_at = now()
    where id = p_payment_id;
    perform public._order_log(v_payment.order_id, 'PAYMENT_REJECTED',
      coalesce(p_note, 'Payment could not be verified'), null, null, jsonb_build_object('payment_id', p_payment_id));
  end if;
  perform public.log_audit(case when p_approve then 'payment.verified' else 'payment.rejected' end,
    'payment', p_payment_id::text, null, jsonb_build_object('amount', v_payment.amount), jsonb_build_object('note', p_note));
  select * into v_payment from public.payments where id = p_payment_id;
  return v_payment;
end;
